class BrandingDetectRequest(BaseModel):
    relative_path: str

    competitor_names: list[str] = Field(default_factory=list)
    competitor_short_names: list[str] = Field(default_factory=list)

    # Optional template image already stored somewhere under /workspace.
    # Example: config/branding/logos/dramabox.png
    logo_relative_path: Optional[str] = None

    # Frame sampling and OCR cadence are deliberately separate:
    # logo matching is cheap, OCR is comparatively expensive.
    sample_interval_seconds: float = 1.0
    ocr_interval_seconds: float = 2.0

    # Optional bounded scan for quick tests. None = video end.
    start_seconds: float = 0.0
    end_seconds: Optional[float] = None

    # Safety caps prevent accidentally OCR'ing thousands of frames.
    max_sample_frames: int = 600
    max_ocr_frames: int = 240

    ocr_language: str = "eng"
    ocr_min_confidence: float = 45.0
    ocr_scale: float = 1.5

    logo_threshold: float = 0.82
    logo_scales: list[float] = Field(
        default_factory=lambda: [0.60, 0.75, 0.90, 1.00, 1.15, 1.30, 1.50]
    )

    save_debug_frames: bool = True
    max_debug_frames: int = 30
    save_negative_debug_frames: bool = True
    negative_debug_every_ocr_frames: int = 5
    max_negative_debug_frames: int = 12
    max_ocr_samples_returned: int = 40


def _safe_workspace_path(relative_path: str, *, must_exist: bool = True) -> Path:
    raw = str(relative_path or "").strip().replace("\\", "/")
    if not raw:
        raise HTTPException(status_code=422, detail="relative_path must not be empty.")
    if raw.startswith("/"):
        raise HTTPException(status_code=422, detail="Use a workspace-relative path, not an absolute path.")

    # Keep the user-facing path spelling stable (important for report joins on
    # Windows where ``resolve`` may expand an 8.3 workspace alias), while using
    # the real path below for traversal validation.
    candidate = Path(os.path.abspath(str(WORKSPACE / raw)))
    # ``Path.parents`` is case-sensitive on Windows while ``resolve()`` may
    # return a differently-cased (or 8.3) spelling of the same directory.
    # Compare normalized absolute paths so valid workspace-relative reports
    # (including temporary regression fixtures) are not rejected as escapes.
    try:
        workspace_norm = os.path.normcase(os.path.realpath(str(WORKSPACE)))
        candidate_norm = os.path.normcase(os.path.realpath(str(candidate)))
        inside_workspace = os.path.commonpath([workspace_norm, candidate_norm]) == workspace_norm
    except Exception:
        inside_workspace = candidate == WORKSPACE or WORKSPACE in candidate.parents
    if not inside_workspace:
        raise HTTPException(status_code=422, detail="Path escapes the workspace.")
    if must_exist and not candidate.exists():
        raise HTTPException(
            status_code=404,
            detail={
                "stage": "branding_detection",
                "error": "file_not_found",
                "relative_path": raw,
            },
        )
    return candidate


def _normalize_text(value: str) -> str:
    value = unicodedata.normalize("NFKC", str(value or "")).casefold()
    return "".join(ch for ch in value if ch.isalnum())


def _dedupe_targets(values: list[str]) -> list[str]:
    result: list[str] = []
    seen: set[str] = set()
    for value in values:
        text = str(value or "").strip()
        norm = _normalize_text(text)
        if not norm or norm in seen:
            continue
        seen.add(norm)
        result.append(text)
    return result


def _bbox_union(boxes: list[dict[str, int]]) -> dict[str, int]:
    x1 = min(b["x"] for b in boxes)
    y1 = min(b["y"] for b in boxes)
    x2 = max(b["x"] + b["width"] for b in boxes)
    y2 = max(b["y"] + b["height"] for b in boxes)
    return {"x": x1, "y": y1, "width": x2 - x1, "height": y2 - y1}


def _clip_bbox(bbox: dict[str, int], width: int, height: int) -> dict[str, int]:
    x = max(0, min(int(bbox["x"]), max(0, width - 1)))
    y = max(0, min(int(bbox["y"]), max(0, height - 1)))
    w = max(1, min(int(bbox["width"]), width - x))
    h = max(1, min(int(bbox["height"]), height - y))
    return {"x": x, "y": y, "width": w, "height": h}


def _tesseract_words(frame, language: str, min_conf: float, scale: float) -> list[dict[str, Any]]:
    if shutil.which("tesseract") is None:
        raise RuntimeError("tesseract executable is not installed in the API container.")

    scale = max(1.0, float(scale))
    if scale != 1.0:
        ocr_frame = cv2.resize(
            frame,
            None,
            fx=scale,
            fy=scale,
            interpolation=cv2.INTER_CUBIC,
        )
    else:
        ocr_frame = frame

    tmp_name = None
    try:
        with tempfile.NamedTemporaryFile(suffix=".png", delete=False) as tmp:
            tmp_name = tmp.name

        if not cv2.imwrite(tmp_name, ocr_frame):
            raise RuntimeError("Could not write temporary OCR frame.")

        proc = subprocess.run(
            [
                "tesseract",
                tmp_name,
                "stdout",
                "-l",
                language,
                "--oem",
                "1",
                "--psm",
                "11",
                "tsv",
            ],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            encoding="utf-8",
            errors="replace",
            timeout=45,
            check=False,
        )
        if proc.returncode != 0:
            raise RuntimeError(
                "Tesseract failed: " + (proc.stderr or proc.stdout or "")[:600]
            )

        rows = csv.DictReader(proc.stdout.splitlines(), delimiter="\t")
        words: list[dict[str, Any]] = []
        for row in rows:
            if str(row.get("level") or "") != "5":
                continue
            text = str(row.get("text") or "").strip()
            if not text:
                continue
            # Defensive guard: malformed TSV rows should never become OCR text.
            if "\t" in text or len(text) > 240:
                continue
            try:
                conf = float(row.get("conf") or -1)
            except Exception:
                conf = -1
            if conf < min_conf:
                continue

            try:
                left = round(float(row["left"]) / scale)
                top = round(float(row["top"]) / scale)
                width = round(float(row["width"]) / scale)
                height = round(float(row["height"]) / scale)
            except Exception:
                continue

            words.append(
                {
                    "text": text,
                    "conf": conf,
                    "x": int(left),
                    "y": int(top),
                    "width": max(1, int(width)),
                    "height": max(1, int(height)),
                    "block_num": str(row.get("block_num") or ""),
                    "par_num": str(row.get("par_num") or ""),
                    "line_num": str(row.get("line_num") or ""),
                    "word_num": str(row.get("word_num") or ""),
                }
            )
        return words
    finally:
        if tmp_name:
            try:
                os.unlink(tmp_name)
            except Exception:
                pass


def _find_text_targets(
    words: list[dict[str, Any]],
    targets: list[str],
    frame_width: int,
    frame_height: int,
) -> list[dict[str, Any]]:
    groups: dict[tuple[str, str, str], list[dict[str, Any]]] = defaultdict(list)
    for word in words:
        groups[
            (
                word["block_num"],
                word["par_num"],
                word["line_num"],
            )
        ].append(word)

    for line_words in groups.values():
        line_words.sort(key=lambda w: int(w["word_num"] or 0))

    detections: list[dict[str, Any]] = []

    for target in targets:
        target_norm = _normalize_text(target)
        if not target_norm:
            continue

        # Very short product abbreviations are risky. Require an exact OCR word.
        if len(target_norm) <= 3:
            for word in words:
                if _normalize_text(word["text"]) != target_norm:
                    continue
                bbox = _clip_bbox(
                    {
                        "x": word["x"],
                        "y": word["y"],
                        "width": word["width"],
                        "height": word["height"],
                    },
                    frame_width,
                    frame_height,
                )
                detections.append(
                    {
                        "detector": "ocr",
                        "target": target,
                        "observed_text": word["text"],
                        "confidence": round(max(0.0, min(1.0, word["conf"] / 100.0)), 4),
                        "bbox": bbox,
                    }
                )
            continue

        for line_words in groups.values():
            line_text = " ".join(w["text"] for w in line_words)
            line_norm = _normalize_text(line_text)
            if target_norm not in line_norm:
                continue

            boxes = [
                {
                    "x": w["x"],
                    "y": w["y"],
                    "width": w["width"],
                    "height": w["height"],
                }
                for w in line_words
            ]
            bbox = _clip_bbox(_bbox_union(boxes), frame_width, frame_height)
            avg_conf = sum(w["conf"] for w in line_words) / max(1, len(line_words))
            detections.append(
                {
                    "detector": "ocr",
                    "target": target,
                    "observed_text": line_text,
                    "confidence": round(max(0.0, min(1.0, avg_conf / 100.0)), 4),
                    "bbox": bbox,
                }
            )

    # Remove duplicate target/bbox detections produced by repeated OCR groupings.
    unique: dict[tuple[Any, ...], dict[str, Any]] = {}
    for det in detections:
        b = det["bbox"]
        key = (
            _normalize_text(det["target"]),
            b["x"],
            b["y"],
            b["width"],
            b["height"],
        )
        old = unique.get(key)
        if old is None or det["confidence"] > old["confidence"]:
            unique[key] = det
    return list(unique.values())



def _ocr_diagnostic_sample(words, targets, time_seconds):
    groups = defaultdict(list)
    for word in words:
        groups[(word["block_num"], word["par_num"], word["line_num"])].append(word)

    lines = []
    for line_words in groups.values():
        line_words.sort(key=lambda w: int(w["word_num"] or 0))
        line = " ".join(str(w["text"]) for w in line_words).strip()
        if line:
            lines.append(line)

    best_candidates = []
    for target in targets:
        target_norm = _normalize_text(target)
        scored = []
        if target_norm:
            for line in lines:
                line_norm = _normalize_text(line)
                if line_norm:
                    scored.append((difflib.SequenceMatcher(None, target_norm, line_norm).ratio(), line))
            for word in words:
                wt = str(word.get("text") or "").strip()
                wn = _normalize_text(wt)
                if wn:
                    scored.append((difflib.SequenceMatcher(None, target_norm, wn).ratio(), wt))
        scored.sort(key=lambda x: x[0], reverse=True)
        if scored:
            best_candidates.append({
                "target": target,
                "best_similarity": round(float(scored[0][0]), 4),
                "best_observed_text": scored[0][1][:200],
            })

    joined = " | ".join(lines)
    if len(joined) > 1200:
        joined = joined[:1200] + "…"

    return {
        "time_seconds": round(float(time_seconds), 3),
        "word_count": len(words),
        "line_count": len(lines),
        "text_preview": joined,
        "best_candidates": best_candidates,
    }


def _prepare_logo_template(path: Path):
    image = cv2.imread(str(path), cv2.IMREAD_UNCHANGED)
    if image is None:
        raise RuntimeError(f"Could not read logo template: {path}")

    if len(image.shape) == 2:
        gray = image
    elif image.shape[2] == 4:
        bgr = image[:, :, :3].astype("float32")
        alpha = (image[:, :, 3].astype("float32") / 255.0)[:, :, None]
        white = 255.0
        composited = (bgr * alpha + white * (1.0 - alpha)).astype("uint8")
        gray = cv2.cvtColor(composited, cv2.COLOR_BGR2GRAY)
    else:
        gray = cv2.cvtColor(image[:, :, :3], cv2.COLOR_BGR2GRAY)

    if gray.shape[0] < 4 or gray.shape[1] < 4:
        raise RuntimeError("Logo template is too small.")
    return gray


def _match_logo(frame, template_gray, scales: list[float], threshold: float) -> Optional[dict[str, Any]]:
    frame_gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
    fh, fw = frame_gray.shape[:2]

    best: Optional[dict[str, Any]] = None

    for scale in scales:
        try:
            scale = float(scale)
        except Exception:
            continue
        if scale <= 0:
            continue

        tw = max(4, round(template_gray.shape[1] * scale))
        th = max(4, round(template_gray.shape[0] * scale))
        if tw > fw or th > fh:
            continue

        template = cv2.resize(
            template_gray,
            (tw, th),
            interpolation=cv2.INTER_AREA if scale < 1.0 else cv2.INTER_CUBIC,
        )

        # A near-constant template is not meaningful for normalized correlation.
        if float(template.std()) < 1.0:
            continue

        result = cv2.matchTemplate(frame_gray, template, cv2.TM_CCOEFF_NORMED)
        _, max_val, _, max_loc = cv2.minMaxLoc(result)
        candidate = {
            "detector": "logo_template",
            "target": "logo",
            "confidence": round(float(max_val), 4),
            "scale": round(scale, 4),
            "bbox": {
                "x": int(max_loc[0]),
                "y": int(max_loc[1]),
                "width": int(tw),
                "height": int(th),
            },
        }
        if best is None or candidate["confidence"] > best["confidence"]:
            best = candidate

    if best is not None and best["confidence"] >= threshold:
        return best
    return None


def _source_icon_watermark_hit(frame, template_gray, time_seconds, width, height):
    """Turn a material-bound app-icon match into a fixed watermark candidate.

    App creatives commonly render a compact icon followed by a stylised
    wordmark. OCR often misses that lettering, so an exact source icon is the
    reliable identity anchor.  The returned box covers the complete horizontal
    mark, not just the icon, allowing the fixed-watermark compositor to clean
    both the icon and the adjacent source text before it draws the own brand.
    """
    match = _match_logo(
        frame,
        template_gray,
        scales=[0.70, 0.85, 1.00, 1.10, 1.25, 1.40],
        threshold=0.68,
    )
    small_top_left = False
    if not match and width >= 120 and height >= 160:
        # Short-video exports often render the source lock-up at roughly
        # 20x20 px in the top-left corner.  The original matcher only used
        # near-native template scales and therefore missed this fixed mark.
        roi_h = max(80, int(round(height * 0.16)))
        roi_w = max(100, int(round(width * 0.30)))
        roi = frame[:roi_h, :roi_w]
        match = _match_logo(
            roi,
            template_gray,
            scales=[0.14, 0.16, 0.18, 0.20, 0.22, 0.24, 0.26, 0.28],
            threshold=0.68,
        )
        if match:
            # The fallback searches only the top-left ROI, so reject any
            # accidental match outside the expected corner lock-up area.
            if int(match["bbox"].get("x") or 0) > int(width * 0.18) or int(match["bbox"].get("y") or 0) > int(height * 0.12):
                match = None
            else:
                small_top_left = True
    if not match:
        return None

    icon = _clip_bbox(match["bbox"], int(width), int(height))
    # Source app marks normally put a wordmark to the icon's right. Cover the
    # whole observed lock-up; its height stays tied to the exact icon match so
    # we do not erase a large arbitrary top band.
    lockup_ratio = 5.60 if small_top_left or int(icon["width"]) < 40 else 3.55
    lockup = _clip_bbox(
        {
            "x": int(icon["x"]),
            "y": int(icon["y"]),
            "width": max(int(icon["width"]), int(round(icon["width"] * lockup_ratio))),
            "height": int(icon["height"]),
        },
        int(width),
        int(height),
    )
    return {
        "time_seconds": round(float(time_seconds), 3),
        "target": "__source_icon_watermark__",
        "observed_text": "source_app_icon",
        "similarity": float(match["confidence"]),
        "exact": True,
        "ocr_confidence": float(match["confidence"]),
        "bbox": lockup,
        "icon_bbox": icon,
        "variant": "source_icon_template",
        "detector": "source_icon_template",
        "small_top_left_fallback": small_top_left,
    }


def _merge_segments(
    detections: list[dict[str, Any]],
    sample_interval: float,
) -> list[dict[str, Any]]:
    buckets: dict[tuple[str, str], list[dict[str, Any]]] = defaultdict(list)
    for det in detections:
        buckets[(det["detector"], det["target"])].append(det)

    segments: list[dict[str, Any]] = []
    merge_gap = max(0.25, float(sample_interval) * 1.75)

    for (detector, target), items in buckets.items():
        items.sort(key=lambda d: float(d["time_seconds"]))
        current: list[dict[str, Any]] = []

        def flush(group: list[dict[str, Any]]):
            if not group:
                return
            representative = max(group, key=lambda d: d["confidence"])
            start = max(0.0, float(group[0]["time_seconds"]) - sample_interval / 2)
            end = float(group[-1]["time_seconds"]) + sample_interval / 2
            segments.append(
                {
                    "detector": detector,
                    "target": target,
                    "start_seconds": round(start, 3),
                    "end_seconds": round(end, 3),
                    "sample_count": len(group),
                    "max_confidence": round(float(representative["confidence"]), 4),
                    "representative_time_seconds": round(
                        float(representative["time_seconds"]), 3
                    ),
                    "representative_bbox": representative["bbox"],
                }
            )

        for item in items:
            if not current:
                current = [item]
                continue
            gap = float(item["time_seconds"]) - float(current[-1]["time_seconds"])
            if gap <= merge_gap:
                current.append(item)
            else:
                flush(current)
                current = [item]
        flush(current)

    segments.sort(key=lambda s: (s["start_seconds"], s["detector"], s["target"]))
    return segments


def _draw_debug(frame, frame_detections: list[dict[str, Any]]):
    annotated = frame.copy()
    for det in frame_detections:
        b = det["bbox"]
        x1, y1 = int(b["x"]), int(b["y"])
        x2, y2 = x1 + int(b["width"]), y1 + int(b["height"])
        cv2.rectangle(annotated, (x1, y1), (x2, y2), (255, 255, 255), 2)
        label = f"{det['detector']} {det['confidence']:.2f}"
        cv2.putText(
            annotated,
            label,
            (x1, max(18, y1 - 6)),
            cv2.FONT_HERSHEY_SIMPLEX,
            0.55,
            (255, 255, 255),
            2,
            cv2.LINE_AA,
        )
    return annotated


def _video_metadata(cap) -> dict[str, Any]:
    fps = float(cap.get(cv2.CAP_PROP_FPS) or 0.0)
    frame_count = float(cap.get(cv2.CAP_PROP_FRAME_COUNT) or 0.0)
    width = int(cap.get(cv2.CAP_PROP_FRAME_WIDTH) or 0)
    height = int(cap.get(cv2.CAP_PROP_FRAME_HEIGHT) or 0)
    duration = frame_count / fps if fps > 0 and frame_count > 0 else 0.0
    return {
        "fps": round(fps, 4) if fps > 0 else None,
        "frame_count": int(frame_count) if frame_count > 0 else None,
        "width": width or None,
        "height": height or None,
        "duration_seconds": round(duration, 3) if duration > 0 else None,
    }


def _detect_sync(req: BrandingDetectRequest) -> dict[str, Any]:
    video_path = _safe_workspace_path(req.relative_path)
    if not video_path.is_file():
        raise HTTPException(status_code=422, detail="relative_path must point to a video file.")

    targets = _dedupe_targets(req.competitor_names + req.competitor_short_names)
    logo_path = None
    template_gray = None

    if req.logo_relative_path:
        logo_path = _safe_workspace_path(req.logo_relative_path)
        template_gray = _prepare_logo_template(logo_path)

    if not targets and template_gray is None:
        raise HTTPException(
            status_code=422,
            detail="Provide at least one competitor name/short name or logo_relative_path.",
        )

    sample_interval = float(req.sample_interval_seconds)
    ocr_interval = float(req.ocr_interval_seconds)
    if not 0.2 <= sample_interval <= 30:
        raise HTTPException(status_code=422, detail="sample_interval_seconds must be between 0.2 and 30.")
    if not 0.5 <= ocr_interval <= 60:
        raise HTTPException(status_code=422, detail="ocr_interval_seconds must be between 0.5 and 60.")
    if not 1 <= int(req.max_sample_frames) <= 5000:
        raise HTTPException(status_code=422, detail="max_sample_frames must be between 1 and 5000.")
    if not 1 <= int(req.max_ocr_frames) <= 2000:
        raise HTTPException(status_code=422, detail="max_ocr_frames must be between 1 and 2000.")
    if not 0 <= float(req.ocr_min_confidence) <= 100:
        raise HTTPException(status_code=422, detail="ocr_min_confidence must be between 0 and 100.")
    if not 0.0 < float(req.logo_threshold) <= 1.0:
        raise HTTPException(status_code=422, detail="logo_threshold must be >0 and <=1.")
    if not 1 <= int(req.negative_debug_every_ocr_frames) <= 1000:
        raise HTTPException(status_code=422, detail="negative_debug_every_ocr_frames must be between 1 and 1000.")
    if not 0 <= int(req.max_negative_debug_frames) <= 200:
        raise HTTPException(status_code=422, detail="max_negative_debug_frames must be between 0 and 200.")
    if not 0 <= int(req.max_ocr_samples_returned) <= 500:
        raise HTTPException(status_code=422, detail="max_ocr_samples_returned must be between 0 and 500.")

    cap = cv2.VideoCapture(str(video_path))
    if not cap.isOpened():
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "branding_detection",
                "error": "video_open_failed",
                "relative_path": req.relative_path,
            },
        )

    try:
        metadata = _video_metadata(cap)
        duration = float(metadata.get("duration_seconds") or 0.0)

        start = max(0.0, float(req.start_seconds or 0.0))
        requested_end = req.end_seconds
        if requested_end is not None:
            end = max(start, float(requested_end))
            if duration > 0:
                end = min(end, duration)
        else:
            end = duration if duration > 0 else start + 60.0

        if duration > 0 and start >= duration:
            raise HTTPException(
                status_code=422,
                detail=f"start_seconds ({start}) is beyond video duration ({duration}).",
            )

        span = max(0.001, end - start)

        effective_sample_interval = max(
            sample_interval,
            span / max(1, int(req.max_sample_frames)),
        )
        effective_ocr_interval = max(
            ocr_interval,
            span / max(1, int(req.max_ocr_frames)),
        )

        timestamp = _app_now().strftime("%Y-%m-%d_%H%M%S")
        report_dir = (
            WORKSPACE
            / "review"
            / "branding_detection"
            / timestamp
            / video_path.stem
        )
        debug_dir = report_dir / "frames"
        report_dir.mkdir(parents=True, exist_ok=True)
        if req.save_debug_frames:
            debug_dir.mkdir(parents=True, exist_ok=True)

        detections: list[dict[str, Any]] = []
        ocr_samples: list[dict[str, Any]] = []
        frames_analyzed = 0
        ocr_frames_analyzed = 0
        debug_frames_saved = 0
        negative_debug_frames_saved = 0
        failed_frame_reads = 0

        next_ocr_time = start - 1e-9
        t = start

        while t <= end + 1e-9 and frames_analyzed < int(req.max_sample_frames):
            cap.set(cv2.CAP_PROP_POS_MSEC, max(0.0, t * 1000.0))
            ok, frame = cap.read()
            if not ok or frame is None:
                failed_frame_reads += 1
                t += effective_sample_interval
                continue

            frames_analyzed += 1
            fh, fw = frame.shape[:2]
            frame_dets: list[dict[str, Any]] = []

            if template_gray is not None:
                logo_det = _match_logo(
                    frame,
                    template_gray,
                    req.logo_scales,
                    float(req.logo_threshold),
                )
                if logo_det:
                    logo_det["time_seconds"] = round(t, 3)
                    frame_dets.append(logo_det)

            ran_ocr_this_frame = False
            if targets and t + 1e-9 >= next_ocr_time and ocr_frames_analyzed < int(req.max_ocr_frames):
                words = _tesseract_words(
                    frame,
                    req.ocr_language,
                    float(req.ocr_min_confidence),
                    float(req.ocr_scale),
                )
                ocr_frames_analyzed += 1
                ran_ocr_this_frame = True

                if len(ocr_samples) < int(req.max_ocr_samples_returned):
                    ocr_samples.append(_ocr_diagnostic_sample(words, targets, t))

                text_dets = _find_text_targets(words, targets, fw, fh)
                for det in text_dets:
                    det["time_seconds"] = round(t, 3)
                frame_dets.extend(text_dets)
                next_ocr_time = t + effective_ocr_interval

            detections.extend(frame_dets)

            if req.save_debug_frames and frame_dets and debug_frames_saved < int(req.max_debug_frames):
                debug_frames_saved += 1
                debug_name = f"hit_{debug_frames_saved:03d}_t_{t:010.3f}.jpg"
                cv2.imwrite(str(debug_dir / debug_name), _draw_debug(frame, frame_dets))

            if (
                req.save_debug_frames
                and req.save_negative_debug_frames
                and ran_ocr_this_frame
                and not frame_dets
                and negative_debug_frames_saved < int(req.max_negative_debug_frames)
                and int(req.negative_debug_every_ocr_frames) > 0
                and ((ocr_frames_analyzed - 1) % int(req.negative_debug_every_ocr_frames) == 0)
            ):
                negative_debug_frames_saved += 1
                debug_name = f"sample_{negative_debug_frames_saved:03d}_t_{t:010.3f}.jpg"
                cv2.imwrite(str(debug_dir / debug_name), frame)

            t += effective_sample_interval

        segments = _merge_segments(detections, effective_sample_interval)

        def rel(path: Path) -> str:
            return path.resolve().relative_to(WORKSPACE).as_posix()

        report = {
            "ok": True,
            "version": "0.17.1",
            "mode": "branding_detection",
            "source": {
                "relative_path": video_path.relative_to(WORKSPACE).as_posix(),
                "filename": video_path.name,
            },
            "video": metadata,
            "scan": {
                "start_seconds": round(start, 3),
                "end_seconds": round(end, 3),
                "requested_sample_interval_seconds": sample_interval,
                "effective_sample_interval_seconds": round(effective_sample_interval, 4),
                "requested_ocr_interval_seconds": ocr_interval,
                "effective_ocr_interval_seconds": round(effective_ocr_interval, 4),
                "frames_analyzed": frames_analyzed,
                "ocr_frames_analyzed": ocr_frames_analyzed,
                "failed_frame_reads": failed_frame_reads,
            },
            "targets": {
                "text": targets,
                "logo_relative_path": (
                    logo_path.relative_to(WORKSPACE).as_posix() if logo_path else None
                ),
            },
            "thresholds": {
                "ocr_min_confidence": float(req.ocr_min_confidence),
                "logo_threshold": float(req.logo_threshold),
            },
            "summary": {
                "detection_count": len(detections),
                "text_detection_count": sum(1 for d in detections if d["detector"] == "ocr"),
                "logo_detection_count": sum(
                    1 for d in detections if d["detector"] == "logo_template"
                ),
                "segment_count": len(segments),
                "debug_frames_saved": debug_frames_saved,
                "negative_debug_frames_saved": negative_debug_frames_saved,
                "ocr_sample_count": len(ocr_samples),
                "manual_review_recommended": True,
            },
            "segments": segments,
            "detections": detections,
            "ocr_samples": ocr_samples,
            "limitations": [
                "No detection does not prove the frame is brand-free; OCR and template matching can miss stylized, animated, rotated, occluded or very small branding.",
                "OCR language models must be installed in the container. v0.9 installs English by default.",
                "Logo template matching is a baseline detector and is not rotation/perspective invariant.",
                "This endpoint is detection-only: it never modifies the source video.",
                "v0.9.1 fuzzy similarity is diagnostic only; it does not create detections or modify the video.",
            ],
        }

        report_path = report_dir / f"{video_path.stem}.branding-detection.json"
        report["report_relative_path"] = rel(report_path)
        report["debug_frames_relative_dir"] = (
            rel(debug_dir) if req.save_debug_frames else None
        )

        report_path.write_text(
            json.dumps(report, ensure_ascii=False, indent=2),
            encoding="utf-8",
        )
        return report
    finally:
        cap.release()



class BrandingMaskPlanRequest(BaseModel):
    detection_report_relative_path: str

    # Candidate discovery from v0.9.1 report
    fuzzy_candidate_threshold: float = 0.84
    window_padding_seconds: float = 1.25

    # Precision rescan
    rescan_interval_seconds: float = 0.25
    ocr_language: str = "eng"
    ocr_min_confidence: float = 20.0
    ocr_scale: float = 2.0
    fuzzy_match_threshold: float = 0.84

    # Mask geometry
    mask_padding_x: int = 12
    mask_padding_y: int = 8

    # Bounding controls
    max_windows: int = 40
    max_rescan_frames: int = 1200
    save_preview_frames: bool = True
    max_preview_frames: int = 80


def _bbox_iou(a: dict[str, int], b: dict[str, int]) -> float:
    ax1, ay1 = a["x"], a["y"]
    ax2, ay2 = ax1 + a["width"], ay1 + a["height"]
    bx1, by1 = b["x"], b["y"]
    bx2, by2 = bx1 + b["width"], by1 + b["height"]

    ix1, iy1 = max(ax1, bx1), max(ay1, by1)
    ix2, iy2 = min(ax2, bx2), min(ay2, by2)
    iw, ih = max(0, ix2 - ix1), max(0, iy2 - iy1)
    inter = iw * ih
    if inter <= 0:
        return 0.0
    union = a["width"] * a["height"] + b["width"] * b["height"] - inter
    return float(inter / union) if union > 0 else 0.0


def _expand_bbox(bbox: dict[str, int], pad_x: int, pad_y: int, width: int, height: int) -> dict[str, int]:
    x1 = max(0, int(bbox["x"]) - int(pad_x))
    y1 = max(0, int(bbox["y"]) - int(pad_y))
    x2 = min(width, int(bbox["x"]) + int(bbox["width"]) + int(pad_x))
    y2 = min(height, int(bbox["y"]) + int(bbox["height"]) + int(pad_y))
    return {
        "x": x1,
        "y": y1,
        "width": max(1, x2 - x1),
        "height": max(1, y2 - y1),
    }


def _word_window_candidates(words: list[dict[str, Any]], target: str) -> list[dict[str, Any]]:
    """
    Build OCR candidates from individual words and short adjacent word windows.
    This produces tight geometry suitable for mask planning.
    """
    target_norm = _normalize_text(target)
    if not target_norm:
        return []

    groups: dict[tuple[str, str, str], list[dict[str, Any]]] = defaultdict(list)
    for word in words:
        groups[(word["block_num"], word["par_num"], word["line_num"])].append(word)

    candidates: list[dict[str, Any]] = []

    for line_words in groups.values():
        line_words.sort(key=lambda w: int(w["word_num"] or 0))

        # Windows 1..3 words handle "Reel Short" while avoiding full subtitle lines.
        for size in (1, 2, 3):
            if size > len(line_words):
                continue
            for i in range(0, len(line_words) - size + 1):
                window = line_words[i:i+size]
                observed = " ".join(str(w["text"]) for w in window).strip()
                observed_norm = _normalize_text(observed)
                if not observed_norm:
                    continue

                length_ratio = len(observed_norm) / max(1, len(target_norm))
                if not 0.65 <= length_ratio <= 1.55:
                    continue

                similarity = difflib.SequenceMatcher(None, target_norm, observed_norm).ratio()
                exact = target_norm == observed_norm or target_norm in observed_norm

                boxes = [
                    {
                        "x": int(w["x"]),
                        "y": int(w["y"]),
                        "width": int(w["width"]),
                        "height": int(w["height"]),
                    }
                    for w in window
                ]
                avg_conf = sum(float(w["conf"]) for w in window) / max(1, len(window))
                candidates.append(
                    {
                        "target": target,
                        "observed_text": observed,
                        "similarity": round(float(similarity), 4),
                        "exact": bool(exact),
                        "ocr_confidence": round(max(0.0, min(1.0, avg_conf / 100.0)), 4),
                        "bbox": _bbox_union(boxes),
                    }
                )

    # Dedupe same geometry/text, keeping best similarity/confidence.
    unique = {}
    for c in candidates:
        b = c["bbox"]
        key = (
            _normalize_text(c["target"]),
            _normalize_text(c["observed_text"]),
            b["x"], b["y"], b["width"], b["height"],
        )
        score = (c["similarity"], c["ocr_confidence"])
        if key not in unique or score > (unique[key]["similarity"], unique[key]["ocr_confidence"]):
            unique[key] = c
    return list(unique.values())


def _report_candidate_times(report: dict[str, Any], threshold: float) -> list[dict[str, Any]]:
    hits = []

    for det in report.get("detections") or []:
        try:
            t = float(det.get("time_seconds"))
        except Exception:
            continue
        hits.append({
            "time_seconds": t,
            "source": "formal_detection",
            "score": float(det.get("confidence") or 0.0),
            "observed_text": det.get("observed_text"),
        })

    for sample in report.get("ocr_samples") or []:
        try:
            t = float(sample.get("time_seconds"))
        except Exception:
            continue
        for cand in sample.get("best_candidates") or []:
            try:
                sim = float(cand.get("best_similarity") or 0.0)
            except Exception:
                sim = 0.0
            if sim >= threshold:
                hits.append({
                    "time_seconds": t,
                    "source": "fuzzy_diagnostic",
                    "score": sim,
                    "observed_text": cand.get("best_observed_text"),
                    "target": cand.get("target"),
                })

    # Unique by rounded timestamp + source; keep useful evidence.
    seen = set()
    result = []
    for hit in sorted(hits, key=lambda x: x["time_seconds"]):
        key = (round(hit["time_seconds"], 3), hit["source"])
        if key in seen:
            continue
        seen.add(key)
        result.append(hit)
    return result


def _merge_candidate_windows(times: list[dict[str, Any]], pad: float, duration: float, max_windows: int):
    raw = []
    for item in times:
        t = float(item["time_seconds"])
        raw.append({
            "start_seconds": max(0.0, t - pad),
            "end_seconds": min(duration, t + pad) if duration > 0 else t + pad,
            "evidence": [item],
        })

    raw.sort(key=lambda w: w["start_seconds"])
    merged = []
    for w in raw:
        if not merged or w["start_seconds"] > merged[-1]["end_seconds"] + 1e-9:
            merged.append(w)
        else:
            merged[-1]["end_seconds"] = max(merged[-1]["end_seconds"], w["end_seconds"])
            merged[-1]["evidence"].extend(w["evidence"])

    return merged[:max_windows]


def _cluster_mask_tracks(samples: list[dict[str, Any]], gap_seconds: float = 1.5):
    """
    Temporal/spatial clustering. Tracks only merge if close in time and overlap
    spatially, so the top watermark and end-card brand remain separate tracks.
    """
    tracks = []

    for sample in sorted(samples, key=lambda x: x["time_seconds"]):
        assigned = False
        for track in reversed(tracks):
            gap = float(sample["time_seconds"]) - float(track["last_time_seconds"])
            if gap < 0 or gap > gap_seconds:
                continue

            rep = track["representative_bbox"]
            if _bbox_iou(rep, sample["mask_bbox"]) >= 0.20:
                track["samples"].append(sample)
                track["last_time_seconds"] = sample["time_seconds"]
                # Representative becomes median-ish via bounding union over recent samples.
                boxes = [s["mask_bbox"] for s in track["samples"][-7:]]
                track["representative_bbox"] = _bbox_union(boxes)
                assigned = True
                break

        if not assigned:
            tracks.append({
                "target": sample["target"],
                "start_seconds": sample["time_seconds"],
                "last_time_seconds": sample["time_seconds"],
                "representative_bbox": dict(sample["mask_bbox"]),
                "samples": [sample],
            })

    result = []
    for idx, track in enumerate(tracks, 1):
        best = max(
            track["samples"],
            key=lambda s: (s["similarity"], s["ocr_confidence"]),
        )
        result.append({
            "track_id": idx,
            "target": track["target"],
            "start_seconds": round(float(track["start_seconds"]), 3),
            "end_seconds": round(float(track["last_time_seconds"]), 3),
            "sample_count": len(track["samples"]),
            "representative_bbox": track["representative_bbox"],
            "best_similarity": best["similarity"],
            "best_ocr_confidence": best["ocr_confidence"],
            "best_observed_text": best["observed_text"],
            "best_time_seconds": best["time_seconds"],
        })
    return result


def _mask_plan_sync(req: BrandingMaskPlanRequest) -> dict[str, Any]:
    report_path = _safe_workspace_path(req.detection_report_relative_path)
    try:
        report = json.loads(report_path.read_text(encoding="utf-8"))
    except Exception as exc:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "branding_mask_plan",
                "error": "invalid_detection_report",
                "message": str(exc)[:500],
            },
        )

    source_rel = ((report.get("source") or {}).get("relative_path") or "").strip()
    if not source_rel:
        raise HTTPException(status_code=422, detail="Detection report has no source.relative_path.")

    video_path = _safe_workspace_path(source_rel)
    targets = list((report.get("targets") or {}).get("text") or [])
    targets = _dedupe_targets(targets)
    if not targets:
        raise HTTPException(status_code=422, detail="Detection report contains no text targets.")

    if not 0.70 <= float(req.fuzzy_candidate_threshold) <= 1.0:
        raise HTTPException(status_code=422, detail="fuzzy_candidate_threshold must be between 0.70 and 1.0.")
    if not 0.70 <= float(req.fuzzy_match_threshold) <= 1.0:
        raise HTTPException(status_code=422, detail="fuzzy_match_threshold must be between 0.70 and 1.0.")
    if not 0.10 <= float(req.rescan_interval_seconds) <= 2.0:
        raise HTTPException(status_code=422, detail="rescan_interval_seconds must be between 0.10 and 2.0.")
    if not 0.0 <= float(req.window_padding_seconds) <= 10.0:
        raise HTTPException(status_code=422, detail="window_padding_seconds must be between 0 and 10.")

    cap = cv2.VideoCapture(str(video_path))
    if not cap.isOpened():
        raise HTTPException(status_code=422, detail="Could not open source video.")

    try:
        metadata = _video_metadata(cap)
        width = int(metadata.get("width") or 0)
        height = int(metadata.get("height") or 0)
        duration = float(metadata.get("duration_seconds") or 0.0)

        evidence = _report_candidate_times(report, float(req.fuzzy_candidate_threshold))
        if not evidence:
            raise HTTPException(
                status_code=422,
                detail={
                    "stage": "branding_mask_plan",
                    "error": "no_candidate_times",
                    "message": "The detection report has no formal/fuzzy candidate times at the requested threshold.",
                },
            )

        windows = _merge_candidate_windows(
            evidence,
            float(req.window_padding_seconds),
            duration,
            int(req.max_windows),
        )

        timestamp = _app_now().strftime("%Y-%m-%d_%H%M%S")
        out_dir = WORKSPACE / "review" / "branding_mask_plan" / timestamp / video_path.stem
        preview_dir = out_dir / "previews"
        mask_dir = out_dir / "masks"
        out_dir.mkdir(parents=True, exist_ok=True)
        preview_dir.mkdir(parents=True, exist_ok=True)
        mask_dir.mkdir(parents=True, exist_ok=True)

        accepted = []
        frames_scanned = 0
        preview_saved = 0

        for window_index, window in enumerate(windows, 1):
            t = float(window["start_seconds"])
            end = float(window["end_seconds"])

            while t <= end + 1e-9 and frames_scanned < int(req.max_rescan_frames):
                cap.set(cv2.CAP_PROP_POS_MSEC, max(0.0, t * 1000.0))
                ok, frame = cap.read()
                if not ok or frame is None:
                    t += float(req.rescan_interval_seconds)
                    continue

                frames_scanned += 1
                words = _tesseract_words(
                    frame,
                    req.ocr_language,
                    float(req.ocr_min_confidence),
                    float(req.ocr_scale),
                )

                frame_hits = []
                for target in targets:
                    candidates = _word_window_candidates(words, target)
                    for cand in candidates:
                        if not (cand["exact"] or cand["similarity"] >= float(req.fuzzy_match_threshold)):
                            continue

                        bbox = _clip_bbox(cand["bbox"], width, height)
                        mask_bbox = _expand_bbox(
                            bbox,
                            int(req.mask_padding_x),
                            int(req.mask_padding_y),
                            width,
                            height,
                        )
                        hit = {
                            "window_index": window_index,
                            "time_seconds": round(float(t), 3),
                            "target": target,
                            "observed_text": cand["observed_text"],
                            "similarity": cand["similarity"],
                            "exact": cand["exact"],
                            "ocr_confidence": cand["ocr_confidence"],
                            "text_bbox": bbox,
                            "mask_bbox": mask_bbox,
                        }
                        frame_hits.append(hit)

                # Suppress multiple overlapping candidates in the same frame,
                # retaining the strongest one for the same target/region.
                frame_hits.sort(
                    key=lambda h: (h["similarity"], h["ocr_confidence"]),
                    reverse=True,
                )
                kept = []
                for hit in frame_hits:
                    if any(
                        old["target"] == hit["target"]
                        and _bbox_iou(old["mask_bbox"], hit["mask_bbox"]) >= 0.45
                        for old in kept
                    ):
                        continue
                    kept.append(hit)

                for hit_index, hit in enumerate(kept, 1):
                    accepted.append(hit)

                    # Per-sample mask image (white = removal region).
                    mask = np.zeros((height, width), dtype=np.uint8)
                    b = hit["mask_bbox"]
                    cv2.rectangle(
                        mask,
                        (b["x"], b["y"]),
                        (b["x"] + b["width"], b["y"] + b["height"]),
                        255,
                        thickness=-1,
                    )
                    mask_name = f"w{window_index:02d}_t_{t:010.3f}_{hit_index:02d}.png"
                    cv2.imwrite(str(mask_dir / mask_name), mask)
                    hit["mask_relative_path"] = mask_dir.joinpath(mask_name).relative_to(WORKSPACE).as_posix()

                if req.save_preview_frames and kept and preview_saved < int(req.max_preview_frames):
                    preview_saved += 1
                    annotated = frame.copy()
                    for hit in kept:
                        tb = hit["text_bbox"]
                        mb = hit["mask_bbox"]
                        cv2.rectangle(
                            annotated,
                            (mb["x"], mb["y"]),
                            (mb["x"] + mb["width"], mb["y"] + mb["height"]),
                            (255, 255, 255),
                            2,
                        )
                        cv2.rectangle(
                            annotated,
                            (tb["x"], tb["y"]),
                            (tb["x"] + tb["width"], tb["y"] + tb["height"]),
                            (180, 180, 180),
                            1,
                        )
                        label = f"{hit['observed_text']} sim={hit['similarity']:.2f}"
                        cv2.putText(
                            annotated,
                            label[:80],
                            (mb["x"], max(20, mb["y"] - 7)),
                            cv2.FONT_HERSHEY_SIMPLEX,
                            0.45,
                            (255, 255, 255),
                            1,
                            cv2.LINE_AA,
                        )
                    preview_name = f"{preview_saved:03d}_t_{t:010.3f}.jpg"
                    cv2.imwrite(str(preview_dir / preview_name), annotated)

                t += float(req.rescan_interval_seconds)

        tracks = _cluster_mask_tracks(
            accepted,
            gap_seconds=max(0.75, float(req.rescan_interval_seconds) * 5.0),
        )

        plan = {
            "ok": True,
            "version": "0.17.0",
            "mode": "branding_mask_plan",
            "source": {
                "relative_path": source_rel,
                "detection_report_relative_path": report_path.relative_to(WORKSPACE).as_posix(),
            },
            "video": metadata,
            "targets": targets,
            "candidate_evidence": evidence,
            "candidate_windows": windows,
            "rescan": {
                "interval_seconds": float(req.rescan_interval_seconds),
                "frames_scanned": frames_scanned,
                "ocr_min_confidence": float(req.ocr_min_confidence),
                "ocr_scale": float(req.ocr_scale),
                "fuzzy_match_threshold": float(req.fuzzy_match_threshold),
            },
            "mask_geometry": {
                "padding_x": int(req.mask_padding_x),
                "padding_y": int(req.mask_padding_y),
            },
            "summary": {
                "candidate_time_count": len(evidence),
                "candidate_window_count": len(windows),
                "mask_sample_count": len(accepted),
                "track_count": len(tracks),
                "preview_frames_saved": preview_saved,
                "source_video_modified": False,
                "manual_review_required_before_removal": True,
            },
            "tracks": tracks,
            "mask_samples": accepted,
            "limitations": [
                "Mask rectangles cover detected OCR text only; adjacent brand icons are not included unless they overlap the padded region.",
                "Fuzzy matching is constrained to short OCR word windows and the configured similarity threshold, but manual review is still required.",
                "This endpoint creates mask plans and PNG masks only. It does not alter the source video.",
            ],
        }

        plan_path = out_dir / f"{video_path.stem}.branding-mask-plan.json"
        plan["plan_relative_path"] = plan_path.relative_to(WORKSPACE).as_posix()
        plan["preview_relative_dir"] = preview_dir.relative_to(WORKSPACE).as_posix()
        plan["masks_relative_dir"] = mask_dir.relative_to(WORKSPACE).as_posix()
        plan_path.write_text(json.dumps(plan, ensure_ascii=False, indent=2), encoding="utf-8")
        return plan
    finally:
        cap.release()




class BrandingMaskReviewRequest(BaseModel):
    mask_plan_relative_path: str

    # Robust geometry cleanup.
    spatial_center_tolerance_px: float = 180.0
    max_area_ratio_from_cluster_median: float = 2.0
    max_center_distance_from_cluster_median_px: float = 120.0

    # Temporal segment construction.
    max_sample_gap_seconds: float = 0.80
    segment_edge_padding_seconds: float = 0.15

    # Stable mask box: use robust quantiles across accepted samples.
    lower_quantile: float = 0.10
    upper_quantile: float = 0.90

    # Review-only inpaint preview.
    make_inpaint_previews: bool = True
    inpaint_radius: float = 3.0
    max_preview_samples_per_segment: int = 3


def _median(values):
    vals = sorted(float(v) for v in values)
    if not vals:
        return 0.0
    n = len(vals)
    mid = n // 2
    if n % 2:
        return vals[mid]
    return (vals[mid - 1] + vals[mid]) / 2.0


def _quantile(values, q: float):
    vals = sorted(float(v) for v in values)
    if not vals:
        return 0.0
    q = max(0.0, min(1.0, float(q)))
    if len(vals) == 1:
        return vals[0]
    pos = (len(vals) - 1) * q
    lo = int(math.floor(pos))
    hi = int(math.ceil(pos))
    if lo == hi:
        return vals[lo]
    frac = pos - lo
    return vals[lo] * (1 - frac) + vals[hi] * frac


def _bbox_center(b):
    return (
        float(b["x"]) + float(b["width"]) / 2.0,
        float(b["y"]) + float(b["height"]) / 2.0,
    )


def _bbox_area(b):
    return max(1.0, float(b["width"]) * float(b["height"]))


def _distance(a, b):
    return math.hypot(float(a[0]) - float(b[0]), float(a[1]) - float(b[1]))


def _spatial_cluster_samples(samples, tolerance_px: float):
    """
    Simple deterministic clustering by bbox center. This intentionally ignores
    time so repeated watermark positions across the video share one geometry
    profile, while the end-card brand remains a separate spatial cluster.
    """
    clusters = []
    for sample in sorted(samples, key=lambda s: float(s["time_seconds"])):
        center = _bbox_center(sample["mask_bbox"])
        best_idx = None
        best_dist = None

        for idx, cluster in enumerate(clusters):
            cc = cluster["center"]
            dist = _distance(center, cc)
            if dist <= tolerance_px and (best_dist is None or dist < best_dist):
                best_idx = idx
                best_dist = dist

        if best_idx is None:
            clusters.append({
                "samples": [sample],
                "center": center,
            })
        else:
            clusters[best_idx]["samples"].append(sample)
            centers = [_bbox_center(s["mask_bbox"]) for s in clusters[best_idx]["samples"]]
            clusters[best_idx]["center"] = (
                _median([c[0] for c in centers]),
                _median([c[1] for c in centers]),
            )

    # Stable order: top to bottom, then left to right.
    clusters.sort(key=lambda c: (c["center"][1], c["center"][0]))
    return clusters


def _clean_spatial_cluster(cluster_samples, max_area_ratio: float, max_center_distance: float):
    boxes = [s["mask_bbox"] for s in cluster_samples]
    centers = [_bbox_center(b) for b in boxes]
    areas = [_bbox_area(b) for b in boxes]

    med_center = (
        _median([c[0] for c in centers]),
        _median([c[1] for c in centers]),
    )
    med_area = max(1.0, _median(areas))

    accepted = []
    rejected = []

    for sample, center, area in zip(cluster_samples, centers, areas):
        area_ratio = area / med_area
        center_distance = _distance(center, med_center)

        rejection_reasons = []
        if area_ratio > max_area_ratio:
            rejection_reasons.append("area_outlier")
        if center_distance > max_center_distance:
            rejection_reasons.append("center_outlier")

        annotated = dict(sample)
        annotated["geometry_diagnostic"] = {
            "cluster_median_area": round(med_area, 2),
            "sample_area": round(area, 2),
            "area_ratio": round(area_ratio, 4),
            "cluster_median_center": {
                "x": round(med_center[0], 2),
                "y": round(med_center[1], 2),
            },
            "sample_center": {
                "x": round(center[0], 2),
                "y": round(center[1], 2),
            },
            "center_distance_px": round(center_distance, 2),
        }

        if rejection_reasons:
            annotated["rejection_reasons"] = rejection_reasons
            rejected.append(annotated)
        else:
            accepted.append(annotated)

    return {
        "median_center": med_center,
        "median_area": med_area,
        "accepted": accepted,
        "rejected": rejected,
    }


def _stable_bbox(samples, width: int, height: int, q_low: float, q_high: float):
    boxes = [s["mask_bbox"] for s in samples]
    lefts = [b["x"] for b in boxes]
    tops = [b["y"] for b in boxes]
    rights = [b["x"] + b["width"] for b in boxes]
    bottoms = [b["y"] + b["height"] for b in boxes]

    # Conservative robust box: low quantile for left/top, high for right/bottom.
    x1 = int(round(_quantile(lefts, q_low)))
    y1 = int(round(_quantile(tops, q_low)))
    x2 = int(round(_quantile(rights, q_high)))
    y2 = int(round(_quantile(bottoms, q_high)))

    return _clip_bbox(
        {
            "x": x1,
            "y": y1,
            "width": max(1, x2 - x1),
            "height": max(1, y2 - y1),
        },
        width,
        height,
    )


def _temporal_segments(samples, max_gap: float, edge_pad: float, duration: float):
    if not samples:
        return []

    items = sorted(samples, key=lambda s: float(s["time_seconds"]))
    groups = []
    current = [items[0]]

    for item in items[1:]:
        gap = float(item["time_seconds"]) - float(current[-1]["time_seconds"])
        if gap <= max_gap:
            current.append(item)
        else:
            groups.append(current)
            current = [item]
    groups.append(current)

    result = []
    for group in groups:
        start = max(0.0, float(group[0]["time_seconds"]) - edge_pad)
        end = float(group[-1]["time_seconds"]) + edge_pad
        if duration > 0:
            end = min(duration, end)
        result.append({
            "start_seconds": round(start, 3),
            "end_seconds": round(end, 3),
            "sample_count": len(group),
            "samples": group,
        })
    return result


def _sample_times_for_segment(segment, max_samples: int):
    max_samples = max(1, int(max_samples))
    start = float(segment["start_seconds"])
    end = float(segment["end_seconds"])
    if end <= start or max_samples == 1:
        return [(start + end) / 2.0]
    if max_samples == 2:
        return [start, end]
    mid = (start + end) / 2.0
    return [start, mid, end][:max_samples]


def _save_review_triplet(frame, bbox, out_base: Path, inpaint_radius: float):
    h, w = frame.shape[:2]
    b = _clip_bbox(bbox, w, h)

    mask = np.zeros((h, w), dtype=np.uint8)
    cv2.rectangle(
        mask,
        (b["x"], b["y"]),
        (b["x"] + b["width"], b["y"] + b["height"]),
        255,
        thickness=-1,
    )

    preview = frame.copy()
    cv2.rectangle(
        preview,
        (b["x"], b["y"]),
        (b["x"] + b["width"], b["y"] + b["height"]),
        (255, 255, 255),
        2,
    )

    inpainted = cv2.inpaint(
        frame,
        mask,
        float(inpaint_radius),
        cv2.INPAINT_TELEA,
    )

    # Do not use Path.with_suffix() here: timestamps contain decimal points,
    # and Path would treat the decimal tail as an existing suffix, causing
    # multiple preview samples within the same second to overwrite each other.
    original_path = Path(str(out_base) + ".original.jpg")
    mask_path = Path(str(out_base) + ".mask.png")
    boxed_path = Path(str(out_base) + ".boxed.jpg")
    inpaint_path = Path(str(out_base) + ".inpaint.jpg")

    cv2.imwrite(str(original_path), frame)
    cv2.imwrite(str(mask_path), mask)
    cv2.imwrite(str(boxed_path), preview)
    cv2.imwrite(str(inpaint_path), inpainted)

    return {
        "original": original_path.relative_to(WORKSPACE).as_posix(),
        "mask": mask_path.relative_to(WORKSPACE).as_posix(),
        "boxed": boxed_path.relative_to(WORKSPACE).as_posix(),
        "inpaint": inpaint_path.relative_to(WORKSPACE).as_posix(),
    }


def _mask_review_sync(req: BrandingMaskReviewRequest) -> dict[str, Any]:
    plan_path = _safe_workspace_path(req.mask_plan_relative_path)
    try:
        plan = json.loads(plan_path.read_text(encoding="utf-8"))
    except Exception as exc:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "branding_mask_review",
                "error": "invalid_mask_plan",
                "message": str(exc)[:500],
            },
        )

    source_rel = ((plan.get("source") or {}).get("relative_path") or "").strip()
    if not source_rel:
        raise HTTPException(status_code=422, detail="Mask plan has no source.relative_path.")

    video_path = _safe_workspace_path(source_rel)
    samples = list(plan.get("mask_samples") or [])
    if not samples:
        raise HTTPException(status_code=422, detail="Mask plan has no mask_samples.")

    if not 1.05 <= float(req.max_area_ratio_from_cluster_median) <= 10.0:
        raise HTTPException(status_code=422, detail="max_area_ratio_from_cluster_median must be between 1.05 and 10.")
    if not 20 <= float(req.spatial_center_tolerance_px) <= 1000:
        raise HTTPException(status_code=422, detail="spatial_center_tolerance_px must be between 20 and 1000.")
    if not 10 <= float(req.max_center_distance_from_cluster_median_px) <= 1000:
        raise HTTPException(status_code=422, detail="max_center_distance_from_cluster_median_px must be between 10 and 1000.")
    if not 0.1 <= float(req.max_sample_gap_seconds) <= 10:
        raise HTTPException(status_code=422, detail="max_sample_gap_seconds must be between 0.1 and 10.")
    if not 0 <= float(req.segment_edge_padding_seconds) <= 2:
        raise HTTPException(status_code=422, detail="segment_edge_padding_seconds must be between 0 and 2.")
    if not 0 <= float(req.lower_quantile) < float(req.upper_quantile) <= 1:
        raise HTTPException(status_code=422, detail="Require 0 <= lower_quantile < upper_quantile <= 1.")

    cap = cv2.VideoCapture(str(video_path))
    if not cap.isOpened():
        raise HTTPException(status_code=422, detail="Could not open source video.")

    try:
        metadata = _video_metadata(cap)
        width = int(metadata.get("width") or 0)
        height = int(metadata.get("height") or 0)
        duration = float(metadata.get("duration_seconds") or 0.0)

        spatial = _spatial_cluster_samples(
            samples,
            float(req.spatial_center_tolerance_px),
        )

        timestamp = _app_now().strftime("%Y-%m-%d_%H%M%S")
        out_dir = WORKSPACE / "review" / "branding_mask_review" / timestamp / video_path.stem
        preview_dir = out_dir / "previews"
        out_dir.mkdir(parents=True, exist_ok=True)
        preview_dir.mkdir(parents=True, exist_ok=True)

        region_profiles = []
        rejected_all = []
        execution_segments = []
        preview_records = []

        for region_idx, cluster in enumerate(spatial, 1):
            cleaned = _clean_spatial_cluster(
                cluster["samples"],
                float(req.max_area_ratio_from_cluster_median),
                float(req.max_center_distance_from_cluster_median_px),
            )
            accepted = cleaned["accepted"]
            rejected = cleaned["rejected"]
            rejected_all.extend(rejected)

            if not accepted:
                continue

            region_bbox = _stable_bbox(
                accepted,
                width,
                height,
                float(req.lower_quantile),
                float(req.upper_quantile),
            )

            segments = _temporal_segments(
                accepted,
                float(req.max_sample_gap_seconds),
                float(req.segment_edge_padding_seconds),
                duration,
            )

            profile = {
                "region_id": region_idx,
                "accepted_sample_count": len(accepted),
                "rejected_sample_count": len(rejected),
                "stable_bbox": region_bbox,
                "median_center": {
                    "x": round(cleaned["median_center"][0], 2),
                    "y": round(cleaned["median_center"][1], 2),
                },
                "median_area": round(cleaned["median_area"], 2),
                "time_min_seconds": round(min(float(s["time_seconds"]) for s in accepted), 3),
                "time_max_seconds": round(max(float(s["time_seconds"]) for s in accepted), 3),
            }
            region_profiles.append(profile)

            for local_idx, segment in enumerate(segments, 1):
                seg_bbox = _stable_bbox(
                    segment["samples"],
                    width,
                    height,
                    float(req.lower_quantile),
                    float(req.upper_quantile),
                )
                record = {
                    "segment_id": len(execution_segments) + 1,
                    "region_id": region_idx,
                    "start_seconds": segment["start_seconds"],
                    "end_seconds": segment["end_seconds"],
                    "sample_count": segment["sample_count"],
                    "stable_bbox": seg_bbox,
                    "source_times": [
                        round(float(s["time_seconds"]), 3)
                        for s in segment["samples"]
                    ],
                    "best_similarity": max(float(s["similarity"]) for s in segment["samples"]),
                    "best_ocr_confidence": max(float(s["ocr_confidence"]) for s in segment["samples"]),
                }
                execution_segments.append(record)

                if req.make_inpaint_previews:
                    for sample_idx, t in enumerate(
                        _sample_times_for_segment(
                            segment,
                            int(req.max_preview_samples_per_segment),
                        ),
                        1,
                    ):
                        cap.set(cv2.CAP_PROP_POS_MSEC, max(0.0, float(t) * 1000.0))
                        ok, frame = cap.read()
                        if not ok or frame is None:
                            continue
                        base = preview_dir / (
                            f"seg_{record['segment_id']:02d}"
                            f"_t_{float(t):010.3f}"
                            f"_{sample_idx:02d}"
                        )
                        paths = _save_review_triplet(
                            frame,
                            seg_bbox,
                            base,
                            float(req.inpaint_radius),
                        )
                        preview_records.append({
                            "segment_id": record["segment_id"],
                            "region_id": region_idx,
                            "time_seconds": round(float(t), 3),
                            "bbox": seg_bbox,
                            **paths,
                        })

        result = {
            "ok": True,
            "version": "0.17.0",
            "mode": "branding_mask_review",
            "source": {
                "relative_path": source_rel,
                "mask_plan_relative_path": plan_path.relative_to(WORKSPACE).as_posix(),
            },
            "video": metadata,
            "cleanup_config": {
                "spatial_center_tolerance_px": float(req.spatial_center_tolerance_px),
                "max_area_ratio_from_cluster_median": float(req.max_area_ratio_from_cluster_median),
                "max_center_distance_from_cluster_median_px": float(req.max_center_distance_from_cluster_median_px),
                "max_sample_gap_seconds": float(req.max_sample_gap_seconds),
                "segment_edge_padding_seconds": float(req.segment_edge_padding_seconds),
                "lower_quantile": float(req.lower_quantile),
                "upper_quantile": float(req.upper_quantile),
            },
            "summary": {
                "input_mask_sample_count": len(samples),
                "spatial_region_count": len(region_profiles),
                "accepted_mask_sample_count": sum(r["accepted_sample_count"] for r in region_profiles),
                "rejected_mask_sample_count": len(rejected_all),
                "execution_segment_count": len(execution_segments),
                "preview_triplet_count": len(preview_records),
                "source_video_modified": False,
                "ready_for_full_video_removal": False,
                "manual_preview_review_required": True,
            },
            "region_profiles": region_profiles,
            "execution_segments": execution_segments,
            "rejected_samples": rejected_all,
            "preview_samples": preview_records,
            "review_note": (
                "Compare original / boxed / inpaint preview images. "
                "Only after the stable boxes and inpaint quality are visually acceptable "
                "should the next version render a full processed video."
            ),
        }

        result_path = out_dir / f"{video_path.stem}.branding-mask-review.json"
        result["review_relative_path"] = result_path.relative_to(WORKSPACE).as_posix()
        result["preview_relative_dir"] = preview_dir.relative_to(WORKSPACE).as_posix()
        result_path.write_text(
            json.dumps(result, ensure_ascii=False, indent=2),
            encoding="utf-8",
        )
        return result
    finally:
        cap.release()




class BrandingMotionPreviewRequest(BaseModel):
    mask_review_relative_path: str

    # Context around the removal segment.
    pre_roll_seconds: float = 0.60
    post_roll_seconds: float = 0.60

    # Review rendering only.
    inpaint_radius: float = 3.0
    pane_width: int = 360
    max_segments: int = 20
    codec: str = "mp4v"


def _fit_to_width(frame, target_width: int):
    target_width = max(160, int(target_width))
    h, w = frame.shape[:2]
    if w <= 0 or h <= 0:
        return frame
    scale = target_width / float(w)
    target_height = max(1, int(round(h * scale)))
    return cv2.resize(frame, (target_width, target_height), interpolation=cv2.INTER_AREA)


def _label_pane(frame, label: str):
    out = frame.copy()
    cv2.rectangle(out, (0, 0), (min(out.shape[1], 175), 34), (0, 0, 0), thickness=-1)
    cv2.putText(
        out,
        label,
        (10, 24),
        cv2.FONT_HERSHEY_SIMPLEX,
        0.62,
        (255, 255, 255),
        2,
        cv2.LINE_AA,
    )
    return out


def _apply_rect_inpaint(frame, bbox, radius: float):
    h, w = frame.shape[:2]
    b = _clip_bbox(bbox, w, h)
    mask = np.zeros((h, w), dtype=np.uint8)
    cv2.rectangle(
        mask,
        (b["x"], b["y"]),
        (b["x"] + b["width"], b["y"] + b["height"]),
        255,
        thickness=-1,
    )
    return cv2.inpaint(frame, mask, float(radius), cv2.INPAINT_TELEA)


def _motion_preview_sync(req: BrandingMotionPreviewRequest) -> dict[str, Any]:
    review_path = _safe_workspace_path(req.mask_review_relative_path)

    try:
        review = json.loads(review_path.read_text(encoding="utf-8"))
    except Exception as exc:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "branding_motion_preview",
                "error": "invalid_mask_review",
                "message": str(exc)[:500],
            },
        )

    source_rel = ((review.get("source") or {}).get("relative_path") or "").strip()
    if not source_rel:
        raise HTTPException(status_code=422, detail="Mask review has no source.relative_path.")

    segments = list(review.get("execution_segments") or [])
    if not segments:
        raise HTTPException(status_code=422, detail="Mask review has no execution_segments.")

    if not 0 <= float(req.pre_roll_seconds) <= 5:
        raise HTTPException(status_code=422, detail="pre_roll_seconds must be between 0 and 5.")
    if not 0 <= float(req.post_roll_seconds) <= 5:
        raise HTTPException(status_code=422, detail="post_roll_seconds must be between 0 and 5.")
    if not 160 <= int(req.pane_width) <= 1080:
        raise HTTPException(status_code=422, detail="pane_width must be between 160 and 1080.")
    if not 1 <= int(req.max_segments) <= 100:
        raise HTTPException(status_code=422, detail="max_segments must be between 1 and 100.")

    video_path = _safe_workspace_path(source_rel)
    cap = cv2.VideoCapture(str(video_path))
    if not cap.isOpened():
        raise HTTPException(status_code=422, detail="Could not open source video.")

    try:
        metadata = _video_metadata(cap)
        fps = float(metadata.get("fps") or 30.0)
        duration = float(metadata.get("duration_seconds") or 0.0)

        timestamp = _app_now().strftime("%Y-%m-%d_%H%M%S")
        out_dir = WORKSPACE / "review" / "branding_motion_preview" / timestamp / video_path.stem
        out_dir.mkdir(parents=True, exist_ok=True)

        clips = []
        codec = str(req.codec or "mp4v")[:4].ljust(4, "v")
        fourcc = cv2.VideoWriter_fourcc(*codec)

        for segment in segments[: int(req.max_segments)]:
            seg_id = int(segment["segment_id"])
            active_start = float(segment["start_seconds"])
            active_end = float(segment["end_seconds"])
            clip_start = max(0.0, active_start - float(req.pre_roll_seconds))
            clip_end = active_end + float(req.post_roll_seconds)
            if duration > 0:
                clip_end = min(duration, clip_end)

            bbox = segment["stable_bbox"]

            cap.set(cv2.CAP_PROP_POS_MSEC, clip_start * 1000.0)
            first_ok, first_frame = cap.read()
            if not first_ok or first_frame is None:
                clips.append({
                    "segment_id": seg_id,
                    "ok": False,
                    "error": "first_frame_read_failed",
                })
                continue

            original_small = _fit_to_width(first_frame, int(req.pane_width))
            pane_h = original_small.shape[0]
            pane_w = original_small.shape[1]
            out_size = (pane_w * 2, pane_h)

            clip_path = out_dir / f"segment_{seg_id:02d}_compare.mp4"
            writer = cv2.VideoWriter(str(clip_path), fourcc, fps, out_size)
            if not writer.isOpened():
                clips.append({
                    "segment_id": seg_id,
                    "ok": False,
                    "error": "video_writer_open_failed",
                })
                continue

            frames_written = 0
            active_frames = 0

            try:
                # Process first frame and continue sequentially.
                frame = first_frame
                frame_index = 0
                while True:
                    current_t = clip_start + frame_index / fps
                    if current_t > clip_end + (0.5 / fps):
                        break

                    in_active = active_start <= current_t <= active_end
                    if in_active:
                        processed = _apply_rect_inpaint(
                            frame,
                            bbox,
                            float(req.inpaint_radius),
                        )
                        active_frames += 1
                    else:
                        processed = frame.copy()

                    left = _label_pane(_fit_to_width(frame, int(req.pane_width)), "ORIGINAL")
                    right_label = "INPAINT ACTIVE" if in_active else "INPAINT OFF"
                    right = _label_pane(_fit_to_width(processed, int(req.pane_width)), right_label)

                    # Both panes derive from the same source aspect ratio.
                    if left.shape[0] != pane_h:
                        left = cv2.resize(left, (pane_w, pane_h))
                    if right.shape[0] != pane_h:
                        right = cv2.resize(right, (pane_w, pane_h))

                    combined = np.hstack([left, right])
                    writer.write(combined)
                    frames_written += 1
                    frame_index += 1

                    ok, frame = cap.read()
                    if not ok or frame is None:
                        break
            finally:
                writer.release()

            clips.append({
                "segment_id": seg_id,
                "ok": True,
                "region_id": segment.get("region_id"),
                "clip_start_seconds": round(clip_start, 3),
                "active_start_seconds": round(active_start, 3),
                "active_end_seconds": round(active_end, 3),
                "clip_end_seconds": round(clip_end, 3),
                "stable_bbox": bbox,
                "frames_written": frames_written,
                "active_frames": active_frames,
                "comparison_size": {
                    "width": out_size[0],
                    "height": out_size[1],
                },
                "relative_path": clip_path.relative_to(WORKSPACE).as_posix(),
            })

        ok_count = sum(1 for c in clips if c.get("ok"))

        result = {
            "ok": ok_count > 0,
            "version": "0.17.0",
            "mode": "branding_motion_preview",
            "source": {
                "relative_path": source_rel,
                "mask_review_relative_path": review_path.relative_to(WORKSPACE).as_posix(),
            },
            "video": metadata,
            "config": {
                "pre_roll_seconds": float(req.pre_roll_seconds),
                "post_roll_seconds": float(req.post_roll_seconds),
                "inpaint_radius": float(req.inpaint_radius),
                "pane_width": int(req.pane_width),
                "codec": codec,
            },
            "summary": {
                "requested_segment_count": min(len(segments), int(req.max_segments)),
                "clips_created": ok_count,
                "clips_failed": len(clips) - ok_count,
                "source_video_modified": False,
                "full_processed_video_created": False,
                "manual_motion_review_required": True,
            },
            "clips": clips,
            "output_relative_dir": out_dir.relative_to(WORKSPACE).as_posix(),
            "review_note": (
                "Review each side-by-side clip for temporal flicker, smearing, "
                "background distortion and transition artifacts. "
                "The next renderer should only use TELEA for regions that pass this motion review."
            ),
        }

        report_path = out_dir / f"{video_path.stem}.branding-motion-preview.json"
        result["report_relative_path"] = report_path.relative_to(WORKSPACE).as_posix()
        report_path.write_text(
            json.dumps(result, ensure_ascii=False, indent=2),
            encoding="utf-8",
        )
        return result
    finally:
        cap.release()




class BrandingWatermarkCensusRequest(BaseModel):
    relative_path: str
    targets: list[str]

    # Source identity is captured with the material at acquisition time.  Keep
    # its product name, app title and app-icon template together so detection is
    # not downgraded to OCR-only when a stylised/animated watermark omits text.
    source_brand_id: Optional[str] = None
    source_product_name: Optional[str] = None
    source_app_title: Optional[str] = None
    source_icon_relative_path: Optional[str] = None
    source_logo_relative_path: Optional[str] = None

    start_seconds: float = 0.0
    end_seconds: Optional[float] = None
    scan_interval_seconds: float = 0.75
    max_frames: int = 260

    ocr_language: str = "eng"
    ocr_min_confidence: float = 10.0
    ocr_scale: float = 2.0
    fuzzy_match_threshold: float = 0.82

    preprocess_variants: list[str] = Field(
        default_factory=lambda: ["original", "clahe", "tophat", "blackhat"]
    )

    # Dynamic watermark mode is a visual-layer detector, not OCR-only.  It is
    # intentionally opt-in for diagnostics and production routing so ordinary
    # subtitles/CTA text do not become cover tracks.
    dynamic_visual_mode: bool = False
    dynamic_visual_sample_interval_seconds: float = 0.50
    dynamic_visual_min_alpha_response: float = 0.035
    # The native v2 translucent-wordmark reference is scored on Canny edges,
    # not on OCR-like confidence.  Keep its threshold independent so a
    # detection-only reviewer can recover faint-but-continuous passes without
    # weakening the generic component/template gates.
    dynamic_visual_native_edge_min_score: float = 0.20
    dynamic_visual_min_persistence_ratio: float = 0.45
    dynamic_visual_max_ocr_overlap_ratio: float = 0.55
    dynamic_visual_min_component_area_ratio: float = 0.00015
    dynamic_visual_max_component_area_ratio: float = 0.035

    # Strict moving-watermark identity track.  This ports the conservative
    # Insightrackr policy: a configured competitor name must be observed at
    # least three times along a genuinely moving path before production may
    # follow-cover it.  It intentionally produces evidence only; rendering
    # still has its own no-extrapolation guard below.
    dynamic_verified_identity_mode: bool = True
    dynamic_verified_identity_min_observations: int = 3
    dynamic_verified_identity_min_mean_confidence: float = 0.62
    dynamic_verified_identity_min_movement_ratio: float = 0.018
    dynamic_verified_identity_max_interpolation_gap_seconds: float = 0.32

    fixed_cluster_tolerance_px: float = 90.0
    fixed_min_unique_times: int = 3
    fixed_max_center_spread_px: float = 90.0

    save_debug_frames: bool = True
    max_debug_frames: int = 80


class BrandingHQMotionPreviewRequest(BaseModel):
    mask_review_relative_path: str

    pre_roll_seconds: float = 0.60
    post_roll_seconds: float = 0.60
    inpaint_radius: float = 3.0

    # The API used to default to x264 ``slow``/CRF 15, which made a full
    # frame-by-frame branding pass several times slower than the source
    # playback rate.  ``veryfast``/CRF 18 keeps visually lossless output for
    # short-form delivery while cutting encode time substantially; callers can
    # still request a slower preset explicitly when archival quality matters.
    crf: int = 18
    preset: str = "veryfast"
    max_segments: int = 20
    side_by_side: bool = True


def _watermark_preprocess_variants(frame, names):
    names = [str(x or "").strip().lower() for x in (names or [])]
    allowed = {"original", "clahe", "tophat", "blackhat"}
    bad = [x for x in names if x not in allowed]
    if bad:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "watermark_census",
                "error": "unsupported_preprocess_variant",
                "unsupported": bad,
                "allowed": sorted(allowed),
            },
        )

    gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
    result = []

    for name in names:
        if name == "original":
            result.append((name, frame))
            continue

        if name == "clahe":
            clahe = cv2.createCLAHE(clipLimit=2.5, tileGridSize=(8, 8))
            enhanced = clahe.apply(gray)
            result.append((name, cv2.cvtColor(enhanced, cv2.COLOR_GRAY2BGR)))
            continue

        # Morphological enhancement for faint bright/dark watermark strokes.
        kernel = cv2.getStructuringElement(cv2.MORPH_RECT, (31, 11))

        if name == "tophat":
            enhanced = cv2.morphologyEx(gray, cv2.MORPH_TOPHAT, kernel)
            enhanced = cv2.normalize(enhanced, None, 0, 255, cv2.NORM_MINMAX)
            result.append((name, cv2.cvtColor(enhanced, cv2.COLOR_GRAY2BGR)))
            continue

        if name == "blackhat":
            enhanced = cv2.morphologyEx(gray, cv2.MORPH_BLACKHAT, kernel)
            enhanced = cv2.normalize(enhanced, None, 0, 255, cv2.NORM_MINMAX)
            result.append((name, cv2.cvtColor(enhanced, cv2.COLOR_GRAY2BGR)))
            continue

    return result


def _dynamic_visual_reference_template_path():
    """Return the reviewed semi-transparent watermark template if available."""
    path = WORKSPACE / "config" / "dynamic_watermark_reference_reelshort_v1.png"
    return path if path.is_file() else None


def _dynamic_visual_reference_template_paths():
    """Return reviewed wordmark references, preferring the true alpha crop.

    v1 was a compact, background-heavy crop.  It is adequate for diagnostics
    but its aspect ratio does not match the large translucent REELSHORT layer
    present in production clips.  v2 is a reviewed native-size crop and is
    deliberately matched through edges, which stay useful after alpha blending
    onto different scenes.
    """
    names = (
        "dynamic_watermark_reference_reelshort_v2.png",
        "dynamic_watermark_reference_reelshort_v1.png",
    )
    return [path for name in names if (path := WORKSPACE / "config" / name).is_file()]


def _dynamic_visual_template_paths(req):
    """Return material-bound icon/logo templates before generic fallbacks."""
    paths = []
    for value in (
        getattr(req, "source_icon_relative_path", None),
        getattr(req, "source_logo_relative_path", None),
    ):
        if not value:
            continue
        try:
            candidate = _safe_workspace_path(str(value))
        except Exception:
            continue
        if candidate.is_file() and candidate not in paths:
            paths.append(candidate)
    # Keep generic templates in the compatibility list for diagnostics and old
    # callers. Production scan selection below is product-identity first and
    # will not use these templates when a source-specific asset is available.
    for fallback in _dynamic_visual_reference_template_paths():
        if fallback not in paths:
            paths.append(fallback)
    return paths


def _dynamic_visual_template_scores(frame, template_gray):
    """Match the reviewed glyph shape at several opacity-friendly scales.

    Normal template matching is fragile against a translucent watermark because
    the scene contributes most pixels.  Edge matching retains the word-shape
    while local contrast normalisation limits false hits on coloured promo
    cards and subtitle plates.
    """
    if template_gray is None or frame is None or frame.size == 0:
        return []

    frame_height, frame_width = frame.shape[:2]
    # Correlation is performed at a bounded 360px-long side. The output bbox
    # is mapped back to source pixels below, keeping portrait scans bounded.
    scan_scale = min(1.0, 360.0 / max(1.0, float(max(frame_height, frame_width))))
    gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
    if scan_scale < 0.999:
        gray = cv2.resize(
            gray,
            None,
            fx=scan_scale,
            fy=scan_scale,
            interpolation=cv2.INTER_AREA,
        )
    gray = cv2.GaussianBlur(gray, (3, 3), 0)
    scene_edges = cv2.Canny(gray, 36, 112)
    template_edges = cv2.Canny(template_gray, 28, 92)

    # A translucent watermark is a local luminance perturbation, not a copy of
    # the pixels in the review crop.  Build an absolute high-pass signal for
    # both the source frame and the template so the scene behind the wordmark
    # contributes much less to the correlation score.
    scene_highpass = cv2.absdiff(
        gray,
        cv2.GaussianBlur(gray, (0, 0), 9.0),
    )
    template_highpass_base = cv2.absdiff(
        template_gray,
        cv2.GaussianBlur(template_gray, (0, 0), 9.0),
    )
    h, w = scene_edges.shape[:2]
    candidates = []

    # Two scales cover the observed lower-band and centre/top wordmark sizes.
    for scale in (1.0, 2.0):
        effective_scale = scale * scan_scale
        resized = cv2.resize(
            template_edges,
            None,
            fx=effective_scale,
            fy=effective_scale,
            interpolation=cv2.INTER_AREA if effective_scale < 1.0 else cv2.INTER_CUBIC,
        )
        th, tw = resized.shape[:2]
        if tw < 24 or th < 10 or tw >= w or th >= h:
            continue

        signal_template = cv2.resize(
            template_highpass_base,
            (tw, th),
            interpolation=cv2.INTER_AREA if effective_scale < 1.0 else cv2.INTER_CUBIC,
        )
        # Semi-transparent glyphs survive best after removing broad scene
        # luminance. Two structural correlations are sufficient and avoid
        # spending time on four full-frame response maps.
        signal_response = cv2.matchTemplate(
            scene_highpass,
            signal_template,
            cv2.TM_CCOEFF_NORMED,
        )
        edge_response = cv2.matchTemplate(scene_edges, resized, cv2.TM_CCOEFF_NORMED)
        _, signal_score, _, signal_loc = cv2.minMaxLoc(signal_response)
        _, edge_score, _, edge_loc = cv2.minMaxLoc(edge_response)
        combined = 0.62 * float(signal_score) + 0.38 * float(edge_score)
        candidate_locs = [
            (signal_loc, float(signal_score), "local_contrast"),
            (edge_loc, float(edge_score), "edge"),
        ]
        seen_locs = set()
        for loc, primary_score, source in candidate_locs:
            if tuple(loc) in seen_locs:
                continue
            seen_locs.add(tuple(loc))
            x, y = int(loc[0]), int(loc[1])
            signal_local_score = float(signal_response[y, x])
            edge_local_score = float(edge_response[y, x])
            raw_score = signal_local_score
            hp_score = signal_local_score
            local_combined = 0.62 * signal_local_score + 0.38 * edge_local_score
            bbox = {
                "x": int(round(x / scan_scale)),
                "y": int(round(y / scan_scale)),
                "width": max(1, int(round(tw / scan_scale))),
                "height": max(1, int(round(th / scan_scale))),
            }
            candidates.append(
                {
                    "template_score": local_combined,
                    "raw_template_score": raw_score,
                    "highpass_template_score": hp_score,
                    "local_contrast_template_score": signal_local_score,
                    "edge_template_score": edge_local_score,
                    "peak_source": source,
                    "bbox": bbox,
                    "scale": float(scale),
                }
            )
    return candidates


def _dynamic_visual_alpha_edge_scores(frame, template_gray, max_candidates=1):
    """Locate the large, semi-transparent reviewed wordmark by its contours.

    This path is intentionally separate from generic template correlation.  A
    translucent wordmark changes its pixel intensity with the underlying shot,
    while the thick letter contours remain stable.  Matching the native review
    crop's Canny structure avoids the old detector's failure mode where a face,
    subtitle or poster texture had a higher grayscale correlation than the
    actual moving REELSHORT mark.
    """
    if template_gray is None or frame is None or frame.size == 0:
        return []
    frame_height, frame_width = frame.shape[:2]
    scan_scale = min(1.0, 360.0 / max(1.0, float(max(frame_height, frame_width))))
    gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
    if scan_scale < 0.999:
        gray = cv2.resize(gray, None, fx=scan_scale, fy=scan_scale, interpolation=cv2.INTER_AREA)
    template_edges = cv2.Canny(template_gray, 40, 110)
    scene_edges = cv2.Canny(gray, 40, 110)
    template_edges = cv2.resize(
        template_edges,
        None,
        fx=scan_scale,
        fy=scan_scale,
        interpolation=cv2.INTER_AREA,
    )
    if template_edges.shape[0] < 8 or template_edges.shape[1] < 24:
        return []
    if template_edges.shape[0] >= scene_edges.shape[0] or template_edges.shape[1] >= scene_edges.shape[1]:
        return []
    response = cv2.matchTemplate(scene_edges, template_edges, cv2.TM_CCOEFF_NORMED)
    # Callers can request several spatial peaks.  The old single-global-maximum policy lost
    # the real translucent wordmark whenever a subtitle, face or bright edge
    # scored higher in the same frame.  Non-maximum suppression keeps the
    # candidate set bounded while allowing the temporal tracker to choose a
    # lower-scoring peak that continues an already-moving source mark.
    remaining = response.copy()
    candidate_rows = []
    suppress_x = max(8, int(round(template_edges.shape[1] * 0.42)))
    suppress_y = max(6, int(round(template_edges.shape[0] * 0.42)))
    minimum_peak = 0.08
    for _ in range(max(1, min(12, int(max_candidates)))):
        _, score, _, location = cv2.minMaxLoc(remaining)
        if float(score) < minimum_peak:
            break
        x, y = int(location[0]), int(location[1])
        candidate_rows.append((float(score), x, y))
        x1 = max(0, x - suppress_x)
        y1 = max(0, y - suppress_y)
        x2 = min(remaining.shape[1], x + suppress_x + 1)
        y2 = min(remaining.shape[0], y + suppress_y + 1)
        remaining[y1:y2, x1:x2] = -1.0

    return [
        {
            "template_score": score,
            "raw_template_score": score,
            "highpass_template_score": 0.0,
            "local_contrast_template_score": 0.0,
            "edge_template_score": score,
            "peak_source": "native_alpha_wordmark_edge",
            "edge_reference": True,
            "bbox": {
                "x": int(round(x / scan_scale)),
                "y": int(round(y / scan_scale)),
                "width": max(1, int(round(template_edges.shape[1] / scan_scale))),
                "height": max(1, int(round(template_edges.shape[0] / scan_scale))),
            },
            "scale": 1.0,
        }
        for score, x, y in candidate_rows
    ]


def _bbox_overlap_ratio(a, b):
    ax1, ay1 = float(a["x"]), float(a["y"])
    ax2, ay2 = ax1 + float(a["width"]), ay1 + float(a["height"])
    bx1, by1 = float(b["x"]), float(b["y"])
    bx2, by2 = bx1 + float(b["width"]), by1 + float(b["height"])
    ix1, iy1 = max(ax1, bx1), max(ay1, by1)
    ix2, iy2 = min(ax2, bx2), min(ay2, by2)
    intersection = max(0.0, ix2 - ix1) * max(0.0, iy2 - iy1)
    return intersection / max(1.0, float(a["width"]) * float(a["height"]))


def _dynamic_visual_candidate_allowed(candidate, *, width, height, ocr_boxes, req):
    bbox = _clip_bbox(candidate["bbox"], width, height)
    area_ratio = float(bbox["width"] * bbox["height"]) / max(1.0, float(width * height))
    if not (
        float(req.dynamic_visual_min_component_area_ratio)
        <= area_ratio
        <= float(req.dynamic_visual_max_component_area_ratio)
    ):
        return False, "area_out_of_dynamic_watermark_range"

    # Scene-native promos and OCR-visible title cards are intentionally not a
    # dynamic watermark, even when they contain the competitor name.  A
    # reviewed wordmark template is different: the real moving watermark is
    # expected to overlap the OCR box for the same word.  Only suppress that
    # overlap when the visual evidence itself is weak.
    overlaps_ocr = any(
        _bbox_overlap_ratio(bbox, ocr_bbox)
        >= float(req.dynamic_visual_max_ocr_overlap_ratio)
        for ocr_bbox in ocr_boxes
    )
    if overlaps_ocr:
        strong_wordmark_evidence = (
            float(candidate.get("template_score") or 0.0) >= 0.20
            and max(
                float(candidate.get("local_contrast_template_score") or 0.0),
                float(candidate.get("highpass_template_score") or 0.0),
                float(candidate.get("edge_template_score") or 0.0),
            ) >= 0.16
        )
        if not strong_wordmark_evidence:
            return False, "overlaps_ocr_brand_text"

    return True, None


def _dynamic_visual_track_report(candidates, width, height, interval, req):
    """Turn visual template candidates into temporally persistent tracks."""
    tracks = []
    for candidate in sorted(candidates, key=lambda item: item["time_seconds"]):
        center = _bbox_center(candidate["bbox"])
        chosen = None
        for track in tracks:
            last = track["points"][-1]
            last_center = _bbox_center(last["bbox"])
            last_bbox = last["bbox"]
            candidate_bbox = candidate["bbox"]
            last_area = max(1.0, float(last_bbox["width"]) * float(last_bbox["height"]))
            candidate_area = max(1.0, float(candidate_bbox["width"]) * float(candidate_bbox["height"]))
            scale_ratio = max(last_area, candidate_area) / min(last_area, candidate_area)
            native_edge_pair = bool(candidate.get("edge_reference")) and bool(last.get("edge_reference"))
            maximum_motion = (
                max(28.0, float(candidate_bbox["width"]) * 0.14)
                if native_edge_pair
                else max(45.0, min(float(candidate_bbox["width"]) * 0.45, float(width) * 0.32))
            )
            if (
                candidate["time_seconds"] - last["time_seconds"]
                <= max(1.0, interval * 2.6)
                and _distance(center, last_center)
                <= maximum_motion
                and scale_ratio <= 1.55
            ):
                chosen = track
                break
        if chosen is None:
            chosen = {"points": []}
            tracks.append(chosen)
        chosen["points"].append(candidate)

    accepted = []
    for track_id, track in enumerate(tracks, 1):
        # A single frame can produce several peaks (raw/high-pass/edge and
        # multiple scales). Treat those as one observation; otherwise duplicate
        # peaks can satisfy the persistence gate without proving a real motion
        # path and can also make the renderer paint the same mark repeatedly.
        best_by_time = {}
        for point in track["points"]:
            time_key = round(float(point["time_seconds"]), 3)
            previous = best_by_time.get(time_key)
            if previous is None or float(point.get("template_score") or 0.0) > float(
                previous.get("template_score") or 0.0
            ):
                best_by_time[time_key] = point
        points = [best_by_time[key] for key in sorted(best_by_time)]
        unique_times = sorted({round(float(point["time_seconds"]), 3) for point in points})
        if len(unique_times) < 2:
            continue
        total_span = max(0.001, unique_times[-1] - unique_times[0] + interval)
        persistence = min(1.0, len(unique_times) * interval / total_span)
        mean_score = sum(float(point["template_score"]) for point in points) / len(points)
        if (
            persistence < float(req.dynamic_visual_min_persistence_ratio)
            or mean_score < float(req.dynamic_visual_min_alpha_response)
        ):
            continue
        boxes = [point["bbox"] for point in points]
        stable_bbox = _clip_bbox(
            {
                "x": int(round(_quantile([b["x"] for b in boxes], 0.20))),
                "y": int(round(_quantile([b["y"] for b in boxes], 0.20))),
                "width": max(
                    1,
                    int(round(_quantile([b["x"] + b["width"] for b in boxes], 0.80)))
                    - int(round(_quantile([b["x"] for b in boxes], 0.20))),
                ),
                "height": max(
                    1,
                    int(round(_quantile([b["y"] + b["height"] for b in boxes], 0.80)))
                    - int(round(_quantile([b["y"] for b in boxes], 0.20))),
                ),
            },
            width,
            height,
        )
        accepted.append(
            {
                "track_id": "visual-dynamic-%02d" % track_id,
                "classification": "semi_transparent_visual_watermark",
                "handler": "dynamic_visual_template_track",
                "point_count": len(points),
                "unique_time_count": len(unique_times),
                "time_min_seconds": round(unique_times[0], 3),
                "time_max_seconds": round(unique_times[-1], 3),
                "persistence_ratio": round(persistence, 4),
                "mean_template_score": round(mean_score, 4),
                "stable_bbox": stable_bbox,
                "points": points,
            }
        )
    return accepted


def _dynamic_visual_watermark_scan(video_path, *, width, height, duration, ocr_hits, req):
    """Detect faint scene-independent source-brand layers from acquired assets."""
    started_monotonic = time.monotonic()
    template_paths = _dynamic_visual_template_paths(req)
    if not template_paths:
        return {
            "enabled": bool(req.dynamic_visual_mode),
            "available": False,
            "reason": "source_brand_visual_template_missing",
            "tracks": [],
        }
    templates = []
    for template_path in template_paths:
        template = cv2.imread(str(template_path), cv2.IMREAD_GRAYSCALE)
        if template is not None and template.size:
            templates.append((template_path, template))
    if not templates:
        return {
            "enabled": bool(req.dynamic_visual_mode),
            "available": False,
            "reason": "source_brand_visual_template_unreadable",
            "tracks": [],
        }

    # Dynamic visual tracking is product-scoped. If this material has a source
    # icon/logo, those assets are the identity authority for this scan. Generic
    # ReelShort references are only a fallback when no product asset exists;
    # otherwise A/B product videos could be matched against the wrong brand.
    reviewed_template_names = {
        "dynamic_watermark_reference_reelshort_v1.png",
        "dynamic_watermark_reference_reelshort_v2.png",
    }
    reviewed_templates = [
        item for item in templates if item[0].name in reviewed_template_names
    ]
    # The native alpha crop is the authoritative detector when available; the
    # older generic crop remains only as a compatibility fallback.
    native_templates = [item for item in reviewed_templates if item[0].name.endswith("_v2.png")]
    source_templates = [
        item for item in templates
        if item[0].name not in reviewed_template_names
    ]
    scan_templates = source_templates or native_templates or reviewed_templates or templates

    # Detection-only review can request frame-level cadence (roughly 1/30s)
    # to audit short fades and gaps.  Production callers still choose their
    # own interval; this lower bound only prevents a zero/negative loop.
    interval = max(0.02, min(2.0, float(req.dynamic_visual_sample_interval_seconds)))
    ocr_by_time = {}
    for hit in ocr_hits or []:
        try:
            key = round(float(hit.get("time_seconds") or 0.0), 3)
        except Exception:
            continue
        if hit.get("bbox"):
            ocr_by_time.setdefault(key, []).append(hit["bbox"])

    cap = cv2.VideoCapture(str(video_path))
    if not cap.isOpened():
        return {
            "enabled": True,
            "available": False,
            "reason": "source_video_unreadable_for_dynamic_visual_scan",
            "tracks": [],
        }
    accepted_candidates = []
    rejected = defaultdict(int)
    frames_scanned = 0
    t = 0.0
    # Seeking to each 0.2s sample forces OpenCV/FFmpeg to repeatedly decode
    # from a previous keyframe.  On a bind-mounted workspace this turned a
    # 52-second review clip into a multi-minute operation.  Samples are
    # chronological, so advance one decoder instead and retain the exact
    # requested timestamp in the report.
    source_fps = float(cap.get(cv2.CAP_PROP_FPS) or 0.0)
    next_frame_index = 0
    try:
        while t <= duration + 1e-9:
            if source_fps > 0.0:
                target_frame_index = max(0, int(round(t * source_fps)))
                while next_frame_index < target_frame_index:
                    if not cap.grab():
                        break
                    next_frame_index += 1
                ok, frame = cap.read()
                next_frame_index += 1
            else:
                # Rare metadata fallback: preserve the previous seek behavior
                # rather than silently sampling the wrong frames.
                cap.set(cv2.CAP_PROP_POS_MSEC, t * 1000.0)
                ok, frame = cap.read()
            if not ok or frame is None:
                t += interval
                continue
            frames_scanned += 1
            nearby_ocr = []
            for observed_time, boxes in ocr_by_time.items():
                if abs(observed_time - t) <= interval * 0.75:
                    nearby_ocr.extend(boxes)
            for template_path, template in scan_templates:
                is_native_alpha_reference = template_path.name.endswith("_v2.png")
                candidate_rows = (
                    _dynamic_visual_alpha_edge_scores(frame, template)
                    if is_native_alpha_reference
                    else _dynamic_visual_template_scores(frame, template)
                )
                for candidate in candidate_rows:
                    # The reference is a 167x44 crop. Require local structural
                    # agreement so one subtitle edge cannot become a track.
                    raw_score = float(candidate.get("raw_template_score") or 0.0)
                    highpass_score = float(candidate.get("highpass_template_score") or 0.0)
                    local_contrast_score = float(
                        candidate.get("local_contrast_template_score") or 0.0
                    )
                    edge_score = float(candidate.get("edge_template_score") or 0.0)
                    # Do not require the raw crop correlation to be high: the
                    # crop contains one particular background behind a
                    # translucent wordmark, while each production frame has a
                    # different scene.  Require agreement from two local
                    # structure signals instead.  This is what lets the
                    # 25s/27s REELSHORT wordmark survive the visual gate.
                    local_evidence = max(
                        0.52 * local_contrast_score + 0.30 * highpass_score + 0.18 * edge_score,
                        0.52 * raw_score + 0.28 * local_contrast_score + 0.20 * edge_score,
                    )
                    native_alpha_pass = is_native_alpha_reference and edge_score >= float(
                        getattr(req, "dynamic_visual_native_edge_min_score", 0.20)
                    )
                    generic_pass = (
                        candidate["template_score"] >= max(0.12, float(req.dynamic_visual_min_alpha_response))
                        and local_evidence >= 0.16
                        and not (local_contrast_score < 0.16 and highpass_score < 0.16 and edge_score < 0.10)
                    )
                    if not (native_alpha_pass or generic_pass):
                        rejected["template_score_below_threshold"] += 1
                        continue
                    allowed, reason = _dynamic_visual_candidate_allowed(
                        candidate,
                        width=width,
                        height=height,
                        ocr_boxes=nearby_ocr,
                        req=req,
                    )
                    if not allowed:
                        rejected[reason] += 1
                        continue
                    accepted_candidates.append(
                        {
                            **candidate,
                            "time_seconds": round(t, 3),
                            "template_relative_path": template_path.relative_to(WORKSPACE).as_posix(),
                        }
                    )
            t += interval
    finally:
        cap.release()

    tracks = _dynamic_visual_track_report(
        accepted_candidates,
        width,
        height,
        interval,
        req,
    )
    return {
        "enabled": True,
        "available": True,
        "template_relative_paths": [
            path.relative_to(WORKSPACE).as_posix()
            for path, _ in templates
        ],
        "scan_template_relative_paths": [
            path.relative_to(WORKSPACE).as_posix()
            for path, _ in scan_templates
        ],
        "source_specific_template_available": bool(source_templates),
        "source_specific_scan_template_relative_paths": [
            path.relative_to(WORKSPACE).as_posix()
            for path, _ in source_templates
        ],
        "sample_interval_seconds": round(interval, 3),
        "frames_scanned": frames_scanned,
        "wall_elapsed_seconds": round(time.monotonic() - started_monotonic, 3),
        "candidate_count": len(accepted_candidates),
        "rejected_candidate_counts": dict(rejected),
        "tracks": tracks,
    }


def _dedupe_watermark_hits(frame_hits):
    """
    Dedupe the same visual watermark found by multiple preprocessing variants.
    Keep the strongest similarity/confidence hit for overlapping geometry.
    """
    frame_hits = sorted(
        frame_hits,
        key=lambda h: (float(h["similarity"]), float(h["ocr_confidence"])),
        reverse=True,
    )
    kept = []
    for hit in frame_hits:
        duplicate = False
        for old in kept:
            if old["target"] != hit["target"]:
                continue
            if _bbox_iou(old["bbox"], hit["bbox"]) >= 0.45:
                duplicate = True
                break
        if not duplicate:
            kept.append(hit)
    return kept


# v0.18.10.9.7: Persistent full-width bottom CTA bars (e.g. ReelShort's red
# "Free for a limited time" strip) carry no brand-name text, so the brand-target
# OCR pass never sees them.  These phrases are matched inside the bottom band;
# the hit bbox is expanded to the full bar so the renderer can cover it with a
# compact own-brand banner instead of leaving the competitor CTA visible.
_BOTTOM_CTA_PHRASES = (
    "limited time",
    "free for",
    "download now",
    "install now",
    "watch now",
    "start watching",
    "click the link",
    "app store",
    "google play",
    "binge",
    "download",
    "install",
)


def _bottom_cta_hits(
    words,
    width,
    height,
    t,
    fuzzy_threshold,
    band_ratio=0.90,
):
    bar_y = int(round(float(height) * float(band_ratio)))
    hits = []
    for phrase in _BOTTOM_CTA_PHRASES:
        for cand in _word_window_candidates(words, phrase):
            if not (
                cand["exact"]
                or float(cand["similarity"]) >= float(fuzzy_threshold)
            ):
                continue
            b = cand["bbox"] or {}
            if not b:
                continue
            center_y = (
                float(b.get("y") or 0)
                + float(b.get("height") or 0) / 2.0
            )
            if center_y < float(bar_y):
                continue
            hits.append(
                {
                    "time_seconds": round(float(t), 3),
                    "target": "__bottom_cta__",
                    "observed_text": cand["observed_text"],
                    "similarity": cand["similarity"],
                    "exact": cand["exact"],
                    "ocr_confidence": cand["ocr_confidence"],
                    "bbox": {
                        "x": 0,
                        "y": bar_y,
                        "width": int(width),
                        "height": max(1, int(height) - bar_y),
                    },
                    "variant": "original",
                }
            )
    return hits


def _cluster_watermark_hits(hits, tolerance_px):
    clusters = []

    for hit in sorted(hits, key=lambda x: float(x["time_seconds"])):
        center = _bbox_center(hit["bbox"])
        best_idx = None
        best_dist = None

        for idx, cluster in enumerate(clusters):
            dist = _distance(center, cluster["center"])
            if dist <= tolerance_px and (best_dist is None or dist < best_dist):
                best_idx = idx
                best_dist = dist

        if best_idx is None:
            clusters.append({"hits": [hit], "center": center})
        else:
            clusters[best_idx]["hits"].append(hit)
            centers = [_bbox_center(h["bbox"]) for h in clusters[best_idx]["hits"]]
            clusters[best_idx]["center"] = (
                _median([c[0] for c in centers]),
                _median([c[1] for c in centers]),
            )

    clusters.sort(key=lambda c: (c["center"][1], c["center"][0]))
    return clusters


def _watermark_cluster_report(cluster_id, hits, min_times, max_spread, width, height):
    centers = [_bbox_center(h["bbox"]) for h in hits]
    med_center = (
        _median([c[0] for c in centers]),
        _median([c[1] for c in centers]),
    )
    spreads = [_distance(c, med_center) for c in centers]
    unique_times = sorted({round(float(h["time_seconds"]), 3) for h in hits})

    boxes = [h["bbox"] for h in hits]
    stable_bbox = _clip_bbox(
        {
            "x": int(round(_quantile([b["x"] for b in boxes], 0.10))),
            "y": int(round(_quantile([b["y"] for b in boxes], 0.10))),
            "width": max(
                1,
                int(round(_quantile([b["x"] + b["width"] for b in boxes], 0.90)))
                - int(round(_quantile([b["x"] for b in boxes], 0.10))),
            ),
            "height": max(
                1,
                int(round(_quantile([b["y"] + b["height"] for b in boxes], 0.90)))
                - int(round(_quantile([b["y"] for b in boxes], 0.10))),
            ),
        },
        width,
        height,
    )

    max_center_spread = max(spreads) if spreads else 0.0
    fixed = len(unique_times) >= int(min_times) and max_center_spread <= float(max_spread)

    variants = sorted({str(h.get("variant") or "") for h in hits if h.get("variant")})

    return {
        "cluster_id": cluster_id,
        "classification": "fixed_candidate" if fixed else "moving_or_transient_candidate",
        "hit_count": len(hits),
        "unique_time_count": len(unique_times),
        "time_min_seconds": min(unique_times) if unique_times else None,
        "time_max_seconds": max(unique_times) if unique_times else None,
        "median_center": {
            "x": round(med_center[0], 2),
            "y": round(med_center[1], 2),
        },
        "max_center_spread_px": round(max_center_spread, 2),
        "stable_bbox": stable_bbox,
        "variants_seen": variants,
        "best_similarity": round(max(float(h["similarity"]) for h in hits), 4),
        "best_ocr_confidence": round(max(float(h["ocr_confidence"]) for h in hits), 4),
        "sample_times": unique_times[:80],
    }


def _strict_verified_identity_tracks(hits, width, height, req, duration=0.0):
    """Build conservative moving tracks from configured competitor-name OCR.

    This is deliberately stricter than the legacy spatial-cluster recovery.
    A dynamic cover is allowed only for a dense sequence of verified target
    observations that has real screen displacement.  In particular, this
    function does not promote a one-off title, a fixed corner mark with OCR
    jitter, or a sparse set of unrelated detections into a moving watermark.
    """
    configured_gap = float(
        getattr(req, "dynamic_verified_identity_max_interpolation_gap_seconds", 0.32)
    )
    scan_cadence = float(getattr(req, "scan_interval_seconds", 0.75))
    visual_cadence = float(getattr(req, "dynamic_visual_sample_interval_seconds", 0.50)) if bool(
        getattr(req, "dynamic_visual_mode", False)
    ) else 0.0
    cadence_gap = min(2.0, max(0.10, max(scan_cadence, visual_cadence, 0.02) * 1.35))
    policy = {
        "enabled": bool(getattr(req, "dynamic_verified_identity_mode", True)),
        "min_observations": max(3, int(getattr(req, "dynamic_verified_identity_min_observations", 3))),
        "min_mean_confidence": float(getattr(req, "dynamic_verified_identity_min_mean_confidence", 0.62)),
        "min_movement_ratio": float(getattr(req, "dynamic_verified_identity_min_movement_ratio", 0.018)),
        "max_interpolation_gap_seconds": max(configured_gap, cadence_gap),
    }
    policy["max_interpolation_gap_seconds"] = max(
        0.10, min(2.0, policy["max_interpolation_gap_seconds"])
    )
    if not policy["enabled"]:
        return [], policy, []

    # One strongest identity-confirmed observation per target/time.  The target
    # originates from the source material's resolved competitor identity, so an
    # exact name match is stronger evidence than an unconstrained OCR fragment.
    best_by_target_time = {}
    for hit in hits or []:
        target = str(hit.get("target") or "").strip()
        bbox = hit.get("bbox") or {}
        if not target or not bbox:
            continue
        try:
            t = round(float(hit.get("time_seconds") or 0.0), 3)
            similarity = float(hit.get("similarity") or 0.0)
            ocr_confidence = float(hit.get("ocr_confidence") or 0.0)
        except Exception:
            continue
        if not bool(hit.get("exact")) and similarity < 0.90:
            continue
        try:
            clipped = _clip_bbox(bbox, int(width), int(height))
        except Exception:
            continue
        identity_confidence = max(similarity, ocr_confidence)
        candidate = {
            "time_seconds": t,
            "bbox": clipped,
            "target": target,
            "similarity": round(similarity, 4),
            "ocr_confidence": round(ocr_confidence, 4),
            "identity_confidence": round(identity_confidence, 4),
            "identity_evidence": "configured_competitor_target_ocr",
        }
        key = (_normalize_text(target), t)
        previous = best_by_target_time.get(key)
        score = (bool(hit.get("exact")), identity_confidence, ocr_confidence)
        if previous is None or score > previous[0]:
            best_by_target_time[key] = (score, candidate)

    grouped = defaultdict(list)
    for (target_key, _), (_, point) in best_by_target_time.items():
        grouped[target_key].append(point)

    tracks = []
    rejected = []
    min_motion_px = min(int(width), int(height)) * policy["min_movement_ratio"]
    for target_key, points in grouped.items():
        points.sort(key=lambda item: float(item["time_seconds"]))
        # A source-specific icon/text detector can see the same product again
        # inside the terminal end card.  Its large center-card bbox is not a
        # continuation of an in-story moving watermark; keeping it in the same
        # segment creates a false 200px+ movement vector and can either promote
        # a fixed corner mark or poison the dynamic-track decision.  Remove
        # terminal-card observations before motion validation. End-card actions
        # have their own replacement path.
        if float(duration or 0.0) > 0.0:
            story_points = []
            terminal_card_points = 0
            for point in points:
                bbox = point.get("bbox") or {}
                center_x, center_y = _bbox_center(bbox)
                area_ratio = (
                    float(bbox.get("width") or 0.0)
                    * float(bbox.get("height") or 0.0)
                    / max(1.0, float(width * height))
                )
                is_terminal_card_point = (
                    # End-card candidates can occupy the final ~3 seconds;
                    # using only the last 1.5s let their first frames join the
                    # in-story source-icon sequence and manufacture motion.
                    float(point.get("time_seconds") or 0.0)
                    >= float(duration) - 3.5
                    and area_ratio >= 0.015
                    and 0.12 * width <= center_x <= 0.88 * width
                    and 0.20 * height <= center_y <= 0.90 * height
                )
                if not is_terminal_card_point:
                    story_points.append(point)
                else:
                    terminal_card_points += 1
            if story_points:
                points = story_points
            elif terminal_card_points:
                rejected.append({
                    "target": points[0]["target"],
                    "reason": "terminal_end_card_not_dynamic_watermark",
                    "observation_count": terminal_card_points,
                })
                continue
        contiguous = []
        segments = []
        for point in points:
            if contiguous and (
                float(point["time_seconds"])
                - float(contiguous[-1]["time_seconds"])
                > policy["max_interpolation_gap_seconds"] + 1e-6
            ):
                segments.append(contiguous)
                contiguous = []
            contiguous.append(point)
        if contiguous:
            segments.append(contiguous)

        for segment_index, segment in enumerate(segments, 1):
            if len(segment) < policy["min_observations"]:
                rejected.append({
                    "target": segment[0]["target"],
                    "reason": "insufficient_dense_verified_observations",
                    "observation_count": len(segment),
                })
                continue
            centers = [_bbox_center(point["bbox"]) for point in segment]
            xs = [center[0] for center in centers]
            ys = [center[1] for center in centers]
            movement_px = math.hypot(max(xs) - min(xs), max(ys) - min(ys))
            mean_confidence = sum(
                float(point["identity_confidence"]) for point in segment
            ) / len(segment)
            # Terminal product cards are handled by the End Card route, not by
            # an in-story moving follow-cover.  OCR box jitter on a card can
            # otherwise look like movement once the census becomes dense.
            if float(duration or 0.0) > 0.0:
                segment_bbox = _bbox_union([point["bbox"] for point in segment])
                segment_center_x, segment_center_y = _bbox_center(segment_bbox)
                segment_area_ratio = (
                    float(segment_bbox["width"] * segment_bbox["height"])
                    / max(1.0, float(width * height))
                )
                terminal_card = (
                    float(segment[-1]["time_seconds"]) >= float(duration) - 1.5
                    and float(segment[0]["time_seconds"]) >= max(0.0, float(duration) - 8.0)
                    and segment_area_ratio >= 0.015
                    and 0.12 * width <= segment_center_x <= 0.88 * width
                    and 0.20 * height <= segment_center_y <= 0.90 * height
                )
                if terminal_card:
                    rejected.append({
                        "target": segment[0]["target"],
                        "reason": "terminal_end_card_not_dynamic_watermark",
                        "observation_count": len(segment),
                    })
                    continue
            # Fixed top-corner product marks often have OCR-box jitter; they
            # are handled by the canonical top-composition path, never here.
            corner_only = all(
                center[1] < 0.17 * float(height)
                and (center[0] < 0.38 * float(width) or center[0] > 0.62 * float(width))
                for center in centers
            )
            if corner_only:
                rejected.append({
                    "target": segment[0]["target"],
                    "reason": "fixed_corner_identity_not_dynamic",
                    "observation_count": len(segment),
                })
                continue
            if movement_px < min_motion_px:
                rejected.append({
                    "target": segment[0]["target"],
                    "reason": "movement_below_verified_dynamic_threshold",
                    "movement_px": round(movement_px, 2),
                    "minimum_movement_px": round(min_motion_px, 2),
                })
                continue
            if mean_confidence < policy["min_mean_confidence"]:
                rejected.append({
                    "target": segment[0]["target"],
                    "reason": "mean_identity_confidence_below_threshold",
                    "mean_identity_confidence": round(mean_confidence, 4),
                })
                continue
            tracks.append({
                "track_id": f"strict-ocr-{target_key or 'brand'}-{segment_index:02d}",
                "classification": "verified_moving_competitor_watermark",
                "handler": "verified_identity_dense_ocr_track",
                "identity_evidence": "configured_competitor_target_ocr",
                "target": segment[0]["target"],
                "point_count": len(segment),
                "movement_px": round(movement_px, 2),
                "mean_identity_confidence": round(mean_confidence, 4),
                "visibility_window": [
                    round(float(segment[0]["time_seconds"]), 3),
                    round(float(segment[-1]["time_seconds"]), 3),
                ],
                "max_interpolation_gap_seconds": policy["max_interpolation_gap_seconds"],
                "tracking_policy": "verified_identity_only__no_pre_or_post_extrapolation__hide_on_tracking_gap",
                "points": segment,
            })
    return tracks, policy, rejected


def _strict_verified_visual_tracks(visual_payload, width, height, policy, duration=0.0):
    """Apply the same no-gap/movement policy to a reviewed template track.

    A reviewed source template is independent identity evidence for faint alpha
    wordmarks.  Its template scores are not OCR probabilities, so the visual
    scanner's own score gate remains authoritative; this helper enforces only
    persistence, genuine motion and temporal safety.
    """
    tracks = []
    rejected = []
    min_motion_px = min(int(width), int(height)) * float(policy["min_movement_ratio"])
    # A reviewed visual template is stronger identity evidence than one OCR
    # word. Permit two temporally distinct observations for a brief mark while
    # retaining the motion and score gates below.
    min_visual_observations = max(2, int(policy["min_observations"]) - 1)
    # Visual template matching is useful for faint marks but its raw maxima
    # are also prone to locking onto scene text/edges.  Production callers can
    # provide stricter gates without weakening the historical unit-test policy.
    min_visual_mean_score = float(policy.get("min_visual_mean_score", 0.0) or 0.0)
    min_native_edge_mean_score = float(policy.get("min_native_edge_mean_score", min_visual_mean_score) or 0.0)
    min_visual_persistence = float(policy.get("min_visual_persistence_ratio", 0.0) or 0.0)
    require_three_visual_observations = bool(policy.get("require_three_visual_observations", False))
    reviewed_template_enabled = any(
        any(name in str(path or "") for name in (
            "dynamic_watermark_reference_reelshort_v1.png",
            "dynamic_watermark_reference_reelshort_v2.png",
        ))
        for path in (visual_payload or {}).get("template_relative_paths") or []
    ) and not bool((visual_payload or {}).get("source_specific_template_available"))
    for raw_track in (visual_payload or {}).get("tracks") or []:
        raw_track_points = list(raw_track.get("points") or [])
        # The source app icon is a useful auxiliary detector, but it is not the
        # reviewed translucent wordmark shown in the reference crop.  When
        # template provenance is present, only the reviewed wordmark evidence
        # may authorize a production dynamic-wordmark track; otherwise an icon
        # match can place a cover over unrelated story content.
        if reviewed_template_enabled:
            raw_track_points = [
                point
                for point in raw_track_points
                if any(name in str(point.get("template_relative_path") or "") for name in (
                    "dynamic_watermark_reference_reelshort_v1.png",
                    "dynamic_watermark_reference_reelshort_v2.png",
                ))
            ]
        raw_points = sorted(
            [point for point in raw_track_points if point.get("bbox")],
            key=lambda item: float(item.get("time_seconds") or 0.0),
        )
        contiguous = []
        segments = []
        for point in raw_points:
            try:
                normalized = {
                    "time_seconds": round(float(point.get("time_seconds") or 0.0), 3),
                    "bbox": _clip_bbox(point["bbox"], int(width), int(height)),
                    "template_score": round(float(point.get("template_score") or 0.0), 4),
                    "template_relative_path": point.get("template_relative_path"),
                    "identity_evidence": "reviewed_competitor_watermark_template",
                    "target": "reviewed_competitor_watermark_template",
                }
            except Exception:
                continue
            if contiguous and (
                normalized["time_seconds"] - contiguous[-1]["time_seconds"]
                > float(policy["max_interpolation_gap_seconds"]) + 1e-6
            ):
                segments.append(contiguous)
                contiguous = []
            contiguous.append(normalized)
        if contiguous:
            segments.append(contiguous)
        for segment_index, segment in enumerate(segments, 1):
            minimum_observations = max(min_visual_observations, 3) if require_three_visual_observations else min_visual_observations
            if len(segment) < minimum_observations:
                rejected.append({
                    "track_id": raw_track.get("track_id"),
                    "reason": "insufficient_dense_reviewed_template_observations",
                    "observation_count": len(segment),
                    "minimum": minimum_observations,
                })
                continue
            mean_template_score = sum(float(point.get("template_score") or 0.0) for point in segment) / max(1, len(segment))
            native_edge_track = all(
                "dynamic_watermark_reference_reelshort_v2.png"
                in str(point.get("template_relative_path") or "")
                for point in segment
            )
            required_mean_score = min_native_edge_mean_score if native_edge_track else min_visual_mean_score
            if mean_template_score < required_mean_score:
                rejected.append({
                    "track_id": raw_track.get("track_id"),
                    "reason": "reviewed_template_mean_score_below_threshold",
                    "mean_template_score": round(mean_template_score, 4),
                    "minimum_mean_template_score": round(required_mean_score, 4),
                })
                continue
            persistence_ratio = float(raw_track.get("persistence_ratio") or 0.0)
            if min_visual_persistence > 0.0 and persistence_ratio < min_visual_persistence:
                rejected.append({
                    "track_id": raw_track.get("track_id"),
                    "reason": "reviewed_template_persistence_below_threshold",
                    "persistence_ratio": round(persistence_ratio, 4),
                    "minimum_persistence_ratio": round(min_visual_persistence, 4),
                })
                continue
            # A real watermark keeps roughly the same footprint while moving;
            # a scene edge match commonly jumps between the 1x/2x templates.
            areas = [float(point["bbox"]["width"] * point["bbox"]["height"]) for point in segment]
            median_area = float(np.median(areas)) if areas else 0.0
            if median_area > 0.0 and (max(areas) - min(areas)) / median_area > 0.75:
                rejected.append({
                    "track_id": raw_track.get("track_id"),
                    "reason": "reviewed_template_bbox_scale_jump",
                    "area_range_ratio": round((max(areas) - min(areas)) / median_area, 4),
                })
                continue
            centers = [_bbox_center(point["bbox"]) for point in segment]
            movement_px = math.hypot(
                max(center[0] for center in centers) - min(center[0] for center in centers),
                max(center[1] for center in centers) - min(center[1] for center in centers),
            )
            # A lower edge threshold is useful for alpha-blended letters over
            # a bright or textured shot, but it must not turn a subtitle or
            # CTA edge into a source-watermark track.  Low-score recovery is
            # therefore allowed only when the segment has two strong native
            # template anchors and follows a coherent path between them.
            native_anchor_score = float(policy.get("min_native_edge_anchor_score", 0.20) or 0.20)
            if native_edge_track and required_mean_score < native_anchor_score:
                anchor_count = sum(
                    1 for point in segment
                    if float(point.get("template_score") or 0.0) >= native_anchor_score
                )
                minimum_anchor_count = int(policy.get("min_native_edge_anchor_count", 2) or 2)
                if anchor_count < minimum_anchor_count:
                    rejected.append({
                        "track_id": raw_track.get("track_id"),
                        "reason": "low_score_native_edge_track_lacks_strong_anchors",
                        "anchor_count": anchor_count,
                        "minimum": minimum_anchor_count,
                    })
                    continue
                path_length = sum(
                    _distance(left, right)
                    for left, right in zip(centers, centers[1:])
                )
                path_straightness = movement_px / max(1.0, path_length)
                minimum_straightness = float(policy.get("min_native_edge_path_straightness", 0.45) or 0.45)
                if path_straightness < minimum_straightness:
                    rejected.append({
                        "track_id": raw_track.get("track_id"),
                        "reason": "low_score_native_edge_path_not_coherent",
                        "path_straightness": round(path_straightness, 4),
                        "minimum": minimum_straightness,
                    })
                    continue
            if movement_px < min_motion_px:
                rejected.append({
                    "track_id": raw_track.get("track_id"),
                    "reason": "reviewed_template_movement_below_threshold",
                    "movement_px": round(movement_px, 2),
                    "minimum_movement_px": round(min_motion_px, 2),
                })
                continue
            if float(duration or 0.0) > 0.0:
                union = _bbox_union([point["bbox"] for point in segment])
                center_x, center_y = _bbox_center(union)
                area_ratio = float(union["width"] * union["height"]) / max(1.0, float(width * height))
                if (
                    float(segment[-1]["time_seconds"]) >= float(duration) - 1.5
                    and float(segment[0]["time_seconds"]) >= max(0.0, float(duration) - 8.0)
                    and area_ratio >= 0.015
                    and 0.12 * width <= center_x <= 0.88 * width
                    and 0.20 * height <= center_y <= 0.90 * height
                ):
                    rejected.append({
                        "track_id": raw_track.get("track_id"),
                        "reason": "terminal_end_card_template_not_dynamic_watermark",
                        "observation_count": len(segment),
                    })
                    continue
            tracks.append({
                "track_id": f"strict-template-{raw_track.get('track_id') or 'brand'}-{segment_index:02d}",
                "classification": "verified_moving_competitor_watermark",
                "handler": "verified_identity_reviewed_template_track",
                "identity_evidence": "reviewed_competitor_watermark_template",
                "target": "reviewed_competitor_watermark_template",
                "point_count": len(segment),
                "movement_px": round(movement_px, 2),
                "visibility_window": [
                    round(float(segment[0]["time_seconds"]), 3),
                    round(float(segment[-1]["time_seconds"]), 3),
                ],
                "max_interpolation_gap_seconds": float(policy["max_interpolation_gap_seconds"]),
                "tracking_policy": "reviewed_template_identity_only__no_pre_or_post_extrapolation__hide_on_tracking_gap",
                "points": segment,
            })
    return tracks, rejected


def _watermark_census_sync(req: BrandingWatermarkCensusRequest):
    started_monotonic = time.monotonic()
    video_path = _safe_workspace_path(req.relative_path)
    targets = _dedupe_targets(list(req.targets or []))
    if not targets:
        raise HTTPException(status_code=422, detail="targets must contain at least one brand name.")

    if not 0.25 <= float(req.scan_interval_seconds) <= 10:
        raise HTTPException(status_code=422, detail="scan_interval_seconds must be between 0.25 and 10.")
    if not 1 <= int(req.max_frames) <= 2000:
        raise HTTPException(status_code=422, detail="max_frames must be between 1 and 2000.")
    if not 0.70 <= float(req.fuzzy_match_threshold) <= 1.0:
        raise HTTPException(status_code=422, detail="fuzzy_match_threshold must be between 0.70 and 1.0.")

    cap = cv2.VideoCapture(str(video_path))
    if not cap.isOpened():
        raise HTTPException(status_code=422, detail="Could not open source video.")

    try:
        metadata = _video_metadata(cap)
        width = int(metadata.get("width") or 0)
        height = int(metadata.get("height") or 0)
        duration = float(metadata.get("duration_seconds") or 0.0)

        start = max(0.0, float(req.start_seconds or 0.0))
        if req.end_seconds is None:
            end = duration if duration > 0 else start + 60.0
        else:
            end = max(start, float(req.end_seconds))
            if duration > 0:
                end = min(end, duration)

        span = max(0.001, end - start)
        interval = max(
            float(req.scan_interval_seconds),
            span / max(1, int(req.max_frames)),
        )

        timestamp = _app_now().strftime("%Y-%m-%d_%H%M%S")
        out_dir = WORKSPACE / "review" / "branding_watermark_census" / timestamp / video_path.stem
        debug_dir = out_dir / "frames"
        out_dir.mkdir(parents=True, exist_ok=True)
        if req.save_debug_frames:
            debug_dir.mkdir(parents=True, exist_ok=True)

        hits = []
        frames_scanned = 0
        ocr_passes = 0
        debug_saved = 0
        variant_hit_counts = defaultdict(int)

        source_icon_template = None
        source_icon_template_relative_path = None
        source_icon_rel = str(
            getattr(req, "source_icon_relative_path", None) or ""
        ).strip()
        if source_icon_rel:
            try:
                source_icon_path = _safe_workspace_path(source_icon_rel)
                source_icon_template = _prepare_logo_template(source_icon_path)
                source_icon_template_relative_path = source_icon_path.relative_to(WORKSPACE).as_posix()
            except Exception:
                # OCR and other source-specific detectors remain available if
                # a registry icon is corrupt or no longer present.
                source_icon_template = None

        t = start
        while t <= end + 1e-9 and frames_scanned < int(req.max_frames):
            _operator_raise_if_cancelled()
            cap.set(cv2.CAP_PROP_POS_MSEC, t * 1000.0)
            ok, frame = cap.read()
            if not ok or frame is None:
                t += interval
                continue

            frames_scanned += 1
            frame_hits = []

            for variant_name, variant_frame in _watermark_preprocess_variants(
                frame,
                req.preprocess_variants,
            ):
                words = _tesseract_words(
                    variant_frame,
                    req.ocr_language,
                    float(req.ocr_min_confidence),
                    float(req.ocr_scale),
                )
                ocr_passes += 1

                for target in targets:
                    candidates = _word_window_candidates(words, target)
                    for cand in candidates:
                        if not (
                            cand["exact"]
                            or float(cand["similarity"]) >= float(req.fuzzy_match_threshold)
                        ):
                            continue

                        bbox = _clip_bbox(cand["bbox"], width, height)
                        frame_hits.append(
                            {
                                "time_seconds": round(float(t), 3),
                                "target": target,
                                "observed_text": cand["observed_text"],
                                "similarity": cand["similarity"],
                                "exact": cand["exact"],
                                "ocr_confidence": cand["ocr_confidence"],
                                "bbox": bbox,
                                "variant": variant_name,
                            }
                        )

                # v0.18.10.9.7: Bottom CTA bar pass (original variant only). The
                # red "Free for a limited time" strip carries no brand-name text,
                # so it can only be recovered from its persistent CTA phrases.
                if variant_name == "original":
                    frame_hits.extend(
                        _bottom_cta_hits(
                            words,
                            width,
                            height,
                            float(t),
                            float(req.fuzzy_match_threshold),
                        )
                    )

            if source_icon_template is not None:
                source_icon_hit = _source_icon_watermark_hit(
                    frame,
                    source_icon_template,
                    t,
                    width,
                    height,
                )
                if source_icon_hit is not None:
                    frame_hits.append(source_icon_hit)

            frame_hits = _dedupe_watermark_hits(frame_hits)
            for hit in frame_hits:
                hits.append(hit)
                variant_hit_counts[hit["variant"]] += 1

            if req.save_debug_frames and frame_hits and debug_saved < int(req.max_debug_frames):
                annotated = frame.copy()
                for hit in frame_hits:
                    b = hit["bbox"]
                    cv2.rectangle(
                        annotated,
                        (b["x"], b["y"]),
                        (b["x"] + b["width"], b["y"] + b["height"]),
                        (255, 255, 255),
                        2,
                    )
                    label = f"{hit['target']} {hit['variant']} sim={hit['similarity']:.2f}"
                    cv2.putText(
                        annotated,
                        label[:90],
                        (b["x"], max(20, b["y"] - 6)),
                        cv2.FONT_HERSHEY_SIMPLEX,
                        0.45,
                        (255, 255, 255),
                        1,
                        cv2.LINE_AA,
                    )
                debug_saved += 1
                cv2.imwrite(
                    str(debug_dir / f"{debug_saved:03d}_t_{t:010.3f}.jpg"),
                    annotated,
                )

            t += interval

        clusters = _cluster_watermark_hits(hits, float(req.fixed_cluster_tolerance_px))
        cluster_reports = []
        for idx, cluster in enumerate(clusters, 1):
            report = _watermark_cluster_report(
                idx,
                cluster["hits"],
                int(req.fixed_min_unique_times),
                float(req.fixed_max_center_spread_px),
                width,
                height,
            )
            # Mark clusters dominated by bottom-CTA phrase hits so the router can
            # route them to a compact bottom-banner cover without brand text.
            cta_count = sum(
                1
                for h in cluster["hits"]
                if str(h.get("target") or "") == "__bottom_cta__"
            )
            if cta_count and cta_count >= max(3, len(cluster["hits"]) // 2):
                report["classification"] = "fixed_candidate"
                report["source"] = "bottom_cta"
            source_icon_count = sum(
                1
                for h in cluster["hits"]
                if str(h.get("target") or "") == "__source_icon_watermark__"
            )
            if source_icon_count and source_icon_count >= max(2, len(cluster["hits"]) // 2):
                report["source"] = "source_icon_template"
            cluster_reports.append(report)

        fixed_count = sum(1 for c in cluster_reports if c["classification"] == "fixed_candidate")
        moving_count = sum(
            1 for c in cluster_reports
            if c["classification"] == "moving_or_transient_candidate"
        )

        dynamic_visual = {
            "enabled": False,
            "available": False,
            "tracks": [],
        }
        if bool(req.dynamic_visual_mode):
            dynamic_visual = _dynamic_visual_watermark_scan(
                video_path,
                width=width,
                height=height,
                duration=duration,
                ocr_hits=hits,
                req=req,
            )
        source_visual_available = bool(
            dynamic_visual.get("source_specific_template_available")
        )

        # Insightrackr-compatible strict identity gate.  Keep the legacy OCR
        # clusters in the report for diagnostics/review, but expose only dense,
        # genuinely moving verified tracks to the production follow-cover path.
        # The strict verifier operates on sampled observations.  A fixed
        # 0.32s gap is shorter than both the default OCR cadence (0.75s) and
        # the visual-template cadence (0.50s), which split every real moving
        # watermark into isolated one-point segments.  Make the bridge window
        # cadence-aware while retaining the caller's stricter value when it is
        # actually larger.  This affects only verification/interpolation; the
        # renderer still uses the per-frame track mask and never extrapolates
        # outside the observed window.
        configured_gap = float(
            getattr(req, "dynamic_verified_identity_max_interpolation_gap_seconds", 0.32)
        )
        visual_cadence = float(
            getattr(req, "dynamic_visual_sample_interval_seconds", 0.50)
        ) if bool(req.dynamic_visual_mode) else 0.0
        identity_cadence = max(
            float(getattr(req, "scan_interval_seconds", 0.75)),
            visual_cadence,
            0.02,
        )
        cadence_gap = min(2.0, max(0.10, identity_cadence * 1.35))
        strict_policy = {
            "enabled": bool(req.dynamic_verified_identity_mode),
            "min_observations": max(3, int(req.dynamic_verified_identity_min_observations)),
            "min_mean_confidence": float(req.dynamic_verified_identity_min_mean_confidence),
            "min_movement_ratio": float(req.dynamic_verified_identity_min_movement_ratio),
            "max_interpolation_gap_seconds": max(configured_gap, cadence_gap),
            # Generic visual templates are intentionally held to a higher bar
            # than OCR identity evidence.  This prevents a scene edge or
            # subtitle from becoming a production watermark action merely
            # because it resembles the reviewed crop at one scale.
            # Registry-bound product icons/logos are weaker under alpha
            # blending than the reviewed opaque reference crop.  Keep the
            # generic reference at 0.45, but allow the source-specific scan
            # into the calibrated 0.30--0.45 range; identity is still guarded
            # by persistence, motion, fixed cadence-aware gaps, and the
            # three-observation requirement below.
            "min_visual_mean_score": (
                0.30 if source_visual_available else 0.45
            ),
            "min_native_edge_mean_score": 0.20,
            "min_visual_persistence_ratio": 0.72,
            "require_three_visual_observations": True,
        }
        strict_ocr_tracks, strict_ocr_policy, strict_ocr_rejected = _strict_verified_identity_tracks(
            hits,
            width,
            height,
            req,
            duration=duration,
        )
        strict_visual_tracks, strict_visual_rejected = _strict_verified_visual_tracks(
            dynamic_visual,
            width,
            height,
            strict_ocr_policy,
            duration=duration,
        )
        dynamic_visual["strict_identity_policy"] = strict_ocr_policy
        dynamic_visual["strict_ocr_tracks"] = strict_ocr_tracks
        dynamic_visual["strict_visual_tracks"] = strict_visual_tracks
        dynamic_visual["strict_rejected_candidates"] = [
            *strict_ocr_rejected,
            *strict_visual_rejected,
        ]
        # If the reviewed visual detector is enabled and has a usable template,
        # it is the production authority. OCR tracks remain in the report for
        # diagnostics but are not rendered: promotional narration containing
        # “ReelShort” must not become a moving cover.
        reviewed_visual_available = any(
            any(name in str(path or "") for name in (
                "dynamic_watermark_reference_reelshort_v1.png",
                "dynamic_watermark_reference_reelshort_v2.png",
            ))
            for path in dynamic_visual.get("template_relative_paths") or []
        )
        source_visual_available = bool(
            dynamic_visual.get("source_specific_template_available")
        )
        visual_identity_available = source_visual_available or reviewed_visual_available
        if bool(req.dynamic_visual_mode) and visual_identity_available and strict_visual_tracks:
            verified_tracks = strict_visual_tracks
            dynamic_visual["production_track_source"] = (
                "source_product_visual_identity_only"
                if source_visual_available
                else "reviewed_visual_identity_only"
            )
        elif bool(req.dynamic_visual_mode) and visual_identity_available:
            # A generic reviewed template may be present for compatibility but
            # still be the wrong watermark family for this source. Do not let an
            # empty visual result erase a valid source-identity OCR track.
            verified_tracks = strict_ocr_tracks
            dynamic_visual["production_track_source"] = (
                "strict_ocr_fallback_no_product_visual_track"
                if source_visual_available
                else "strict_ocr_fallback_no_reviewed_visual_track"
            )
        else:
            verified_tracks = [*strict_ocr_tracks, *strict_visual_tracks]
            dynamic_visual["production_track_source"] = "strict_ocr_plus_reviewed_visual_identity"
        dynamic_visual["strict_track_count"] = len(verified_tracks)
        dynamic_visual["source_identity"] = {
            "brand_id": req.source_brand_id,
            "product_name": req.source_product_name,
            "app_title": req.source_app_title,
            "icon_relative_path": req.source_icon_relative_path,
            "logo_relative_path": req.source_logo_relative_path,
        }

        result = {
            "ok": True,
            "version": "0.17.1",
            "mode": "branding_watermark_census",
            "source": {
                "relative_path": video_path.relative_to(WORKSPACE).as_posix(),
            },
            "video": metadata,
            "targets": targets,
            "source_identity": dynamic_visual["source_identity"],
            "scan": {
                "start_seconds": round(start, 3),
                "end_seconds": round(end, 3),
                "requested_interval_seconds": float(req.scan_interval_seconds),
                "effective_interval_seconds": round(interval, 4),
                "frames_scanned": frames_scanned,
                "ocr_passes": ocr_passes,
                "preprocess_variants": list(req.preprocess_variants or []),
                "wall_elapsed_seconds": round(time.monotonic() - started_monotonic, 3),
            },
            "summary": {
                "hit_count": len(hits),
                "source_icon_template_relative_path": source_icon_template_relative_path,
                "source_icon_template_hit_count": sum(
                    1
                    for hit in hits
                    if str(hit.get("target") or "") == "__source_icon_watermark__"
                ),
                "spatial_cluster_count": len(cluster_reports),
                "fixed_candidate_cluster_count": fixed_count,
                "moving_or_transient_cluster_count": moving_count,
                "debug_frames_saved": debug_saved,
                "source_video_modified": False,
            },
            "variant_hit_counts": dict(variant_hit_counts),
            "clusters": cluster_reports,
            "hits": hits,
            "interpretation": {
                "fixed_candidate": (
                    "Repeated OCR-compatible watermark detections at approximately the same screen position."
                ),
                "moving_or_transient_candidate": (
                    "Detections do not stay within one stable screen region; this may represent a floating watermark, "
                    "a short-lived brand element, or OCR noise. Dynamic tracking should verify it before removal."
                ),
            },
            "dynamic_visual_watermark": dynamic_visual,
            "verified_dynamic_identity": {
                "enabled": bool(strict_ocr_policy["enabled"]),
                "policy": strict_ocr_policy,
                "ocr_track_count": len(strict_ocr_tracks),
                "visual_track_count": len(strict_visual_tracks),
                "track_count": len(verified_tracks),
                "rejected_candidate_count": len(strict_ocr_rejected) + len(strict_visual_rejected),
                "tracks": verified_tracks,
            },
        }

        report_path = out_dir / f"{video_path.stem}.watermark-census.json"
        result["report_relative_path"] = report_path.relative_to(WORKSPACE).as_posix()
        result["debug_frames_relative_dir"] = (
            debug_dir.relative_to(WORKSPACE).as_posix()
            if req.save_debug_frames
            else None
        )
        report_path.write_text(
            json.dumps(result, ensure_ascii=False, indent=2),
            encoding="utf-8",
        )
        return result
    finally:
        cap.release()


def _ffmpeg_runtime():
    ffmpeg = shutil.which("ffmpeg")
    if not ffmpeg:
        return {
            "ffmpeg_path": None,
            "libx264_available": False,
            "error": "ffmpeg_not_found",
        }

    try:
        proc = subprocess.run(
            [ffmpeg, "-hide_banner", "-encoders"],
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            text=True,
            timeout=20,
            check=False,
        )
        output = proc.stdout or ""
        return {
            "ffmpeg_path": ffmpeg,
            "libx264_available": bool(re.search(r"\blibx264\b", output)),
            "error": None,
        }
    except Exception as exc:
        return {
            "ffmpeg_path": ffmpeg,
            "libx264_available": False,
            "error": str(exc)[:300],
        }


def _open_x264_raw_writer(path: Path, width: int, height: int, fps: float, crf: int, preset: str):
    runtime = _ffmpeg_runtime()
    if not runtime["ffmpeg_path"] or not runtime["libx264_available"]:
        raise HTTPException(
            status_code=503,
            detail={
                "stage": "hq_motion_preview",
                "error": "libx264_unavailable",
                "runtime": runtime,
            },
        )

    cmd = [
        runtime["ffmpeg_path"],
        "-y",
        "-hide_banner",
        "-loglevel",
        "error",
        "-f",
        "rawvideo",
        "-pix_fmt",
        "bgr24",
        "-video_size",
        f"{int(width)}x{int(height)}",
        "-framerate",
        f"{float(fps):.6f}",
        "-i",
        "pipe:0",
        "-an",
        "-c:v",
        "libx264",
        "-preset",
        str(preset),
        "-crf",
        str(int(crf)),
        "-pix_fmt",
        "yuv420p",
        "-movflags",
        "+faststart",
        str(path),
    ]

    proc = subprocess.Popen(
        cmd,
        stdin=subprocess.PIPE,
        stdout=subprocess.DEVNULL,
        stderr=subprocess.PIPE,
    )
    return proc, runtime


def _hq_motion_preview_sync(req: BrandingHQMotionPreviewRequest):
    review_path = _safe_workspace_path(req.mask_review_relative_path)
    try:
        review = json.loads(review_path.read_text(encoding="utf-8"))
    except Exception as exc:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "hq_motion_preview",
                "error": "invalid_mask_review",
                "message": str(exc)[:500],
            },
        )

    source_rel = ((review.get("source") or {}).get("relative_path") or "").strip()
    if not source_rel:
        raise HTTPException(status_code=422, detail="Mask review has no source.relative_path.")

    segments = list(review.get("execution_segments") or [])
    if not segments:
        raise HTTPException(status_code=422, detail="Mask review has no execution_segments.")

    if not 0 <= float(req.pre_roll_seconds) <= 5:
        raise HTTPException(status_code=422, detail="pre_roll_seconds must be between 0 and 5.")
    if not 0 <= float(req.post_roll_seconds) <= 5:
        raise HTTPException(status_code=422, detail="post_roll_seconds must be between 0 and 5.")
    if not 8 <= int(req.crf) <= 28:
        raise HTTPException(status_code=422, detail="crf must be between 8 and 28.")
    if not 1 <= int(req.max_segments) <= 100:
        raise HTTPException(status_code=422, detail="max_segments must be between 1 and 100.")

    preset = str(req.preset or "").strip()
    allowed_presets = {
        "ultrafast", "superfast", "veryfast", "faster", "fast",
        "medium", "slow", "slower", "veryslow",
    }
    if preset not in allowed_presets:
        raise HTTPException(
            status_code=422,
            detail={"error": "unsupported_x264_preset", "allowed": sorted(allowed_presets)},
        )

    video_path = _safe_workspace_path(source_rel)
    cap = cv2.VideoCapture(str(video_path))
    if not cap.isOpened():
        raise HTTPException(status_code=422, detail="Could not open source video.")

    try:
        metadata = _video_metadata(cap)
        fps = float(metadata.get("fps") or 30.0)
        width = int(metadata.get("width") or 0)
        height = int(metadata.get("height") or 0)
        duration = float(metadata.get("duration_seconds") or 0.0)

        timestamp = _app_now().strftime("%Y-%m-%d_%H%M%S")
        out_dir = WORKSPACE / "review" / "branding_hq_motion_preview" / timestamp / video_path.stem
        out_dir.mkdir(parents=True, exist_ok=True)

        outputs = []
        runtime = None

        for segment in segments[: int(req.max_segments)]:
            seg_id = int(segment["segment_id"])
            active_start = float(segment["start_seconds"])
            active_end = float(segment["end_seconds"])
            clip_start = max(0.0, active_start - float(req.pre_roll_seconds))
            clip_end = active_end + float(req.post_roll_seconds)
            if duration > 0:
                clip_end = min(duration, clip_end)

            bbox = segment["stable_bbox"]
            out_width = width * 2 if req.side_by_side else width
            out_height = height

            clip_path = out_dir / f"segment_{seg_id:02d}_hq_compare.mp4"

            proc, runtime = _open_x264_raw_writer(
                clip_path,
                out_width,
                out_height,
                fps,
                int(req.crf),
                preset,
            )

            cap.set(cv2.CAP_PROP_POS_MSEC, clip_start * 1000.0)
            frame_index = 0
            frames_written = 0
            active_frames = 0
            write_error = None

            try:
                while True:
                    ok, frame = cap.read()
                    if not ok or frame is None:
                        break

                    current_t = clip_start + frame_index / fps
                    if current_t > clip_end + (0.5 / fps):
                        break

                    in_active = active_start <= current_t <= active_end
                    if in_active:
                        processed = _apply_rect_inpaint(
                            frame,
                            bbox,
                            float(req.inpaint_radius),
                        )
                        active_frames += 1
                    else:
                        processed = frame.copy()

                    if req.side_by_side:
                        left = _label_pane(frame, "ORIGINAL")
                        right = _label_pane(
                            processed,
                            "INPAINT ACTIVE" if in_active else "INPAINT OFF",
                        )
                        output_frame = np.hstack([left, right])
                    else:
                        output_frame = processed

                    try:
                        proc.stdin.write(output_frame.tobytes())
                    except Exception as exc:
                        write_error = str(exc)[:400]
                        break

                    frames_written += 1
                    frame_index += 1
            finally:
                try:
                    if proc.stdin:
                        proc.stdin.close()
                except Exception:
                    pass

            stderr = b""
            try:
                stderr = proc.stderr.read() if proc.stderr else b""
            except Exception:
                pass
            return_code = proc.wait()

            ok = return_code == 0 and write_error is None and clip_path.exists()

            outputs.append(
                {
                    "segment_id": seg_id,
                    "ok": ok,
                    "region_id": segment.get("region_id"),
                    "clip_start_seconds": round(clip_start, 3),
                    "active_start_seconds": round(active_start, 3),
                    "active_end_seconds": round(active_end, 3),
                    "clip_end_seconds": round(clip_end, 3),
                    "stable_bbox": bbox,
                    "frames_written": frames_written,
                    "active_frames": active_frames,
                    "output_size": {
                        "width": out_width,
                        "height": out_height,
                    },
                    "crf": int(req.crf),
                    "preset": preset,
                    "side_by_side": bool(req.side_by_side),
                    "relative_path": clip_path.relative_to(WORKSPACE).as_posix()
                    if clip_path.exists()
                    else None,
                    "error": write_error
                    or (
                        stderr.decode("utf-8", errors="replace")[:800]
                        if return_code != 0
                        else None
                    ),
                }
            )

        ok_count = sum(1 for x in outputs if x["ok"])

        result = {
            "ok": ok_count > 0,
            "version": "0.17.0",
            "mode": "branding_hq_motion_preview",
            "source": {
                "relative_path": source_rel,
                "mask_review_relative_path": review_path.relative_to(WORKSPACE).as_posix(),
            },
            "video": metadata,
            "encoder": {
                "engine": "ffmpeg",
                "codec": "libx264",
                "crf": int(req.crf),
                "preset": preset,
                "pixel_format": "yuv420p",
                "runtime": runtime,
            },
            "summary": {
                "clips_requested": min(len(segments), int(req.max_segments)),
                "clips_created": ok_count,
                "clips_failed": len(outputs) - ok_count,
                "source_video_modified": False,
                "full_processed_video_created": False,
                "preview_is_full_source_resolution_per_pane": bool(req.side_by_side),
            },
            "clips": outputs,
            "output_relative_dir": out_dir.relative_to(WORKSPACE).as_posix(),
            "quality_note": (
                "Unlike v0.9.4, this preview does not downscale each source pane to 360 px width. "
                "It encodes with FFmpeg libx264 constant-quality mode, so it is suitable for judging "
                "inpaint damage separately from low-resolution preview encoding damage."
            ),
        }

        report_path = out_dir / f"{video_path.stem}.hq-motion-preview.json"
        result["report_relative_path"] = report_path.relative_to(WORKSPACE).as_posix()
        report_path.write_text(
            json.dumps(result, ensure_ascii=False, indent=2),
            encoding="utf-8",
        )
        return result
    finally:
        cap.release()




class BrandingStrokeMaskPreviewRequest(BaseModel):
    census_report_relative_path: str
    cluster_ids: list[int] = Field(default_factory=list)

    # Representative frames per cluster.
    max_samples_per_cluster: int = 4

    # Morphological stroke extraction.
    kernel_width: int = 31
    kernel_height: int = 11
    response_percentile: float = 82.0
    min_component_area: int = 8
    max_component_area_ratio: float = 0.22
    dilate_iterations: int = 1
    close_iterations: int = 1

    # Preview-only inpainting.
    inpaint_radius: float = 3.0


class BrandingFlowTrackPreviewRequest(BaseModel):
    census_report_relative_path: str
    cluster_ids: list[int] = Field(default_factory=list)

    # If empty, moving_or_transient candidates are selected automatically.
    # Fixed clusters can be explicitly selected for tracker diagnostics.
    track_seconds: float = 2.0
    direction: str = "forward"
    sample_every_frames: int = 1
    max_tracks: int = 20

    # Farneback dense optical-flow parameters.
    pyr_scale: float = 0.5
    levels: int = 3
    winsize: int = 21
    iterations: int = 3
    poly_n: int = 5
    poly_sigma: float = 1.2

    save_debug_video: bool = True
    crf: int = 18
    preset: str = "medium"


def _select_census_clusters(report, cluster_ids):
    clusters = list(report.get("clusters") or [])
    if cluster_ids:
        wanted = {int(x) for x in cluster_ids}
        selected = [c for c in clusters if int(c.get("cluster_id") or -1) in wanted]
        missing = sorted(wanted - {int(c.get("cluster_id") or -1) for c in selected})
        if missing:
            raise HTTPException(
                status_code=422,
                detail={
                    "stage": "watermark_cluster_selection",
                    "error": "cluster_id_not_found",
                    "missing_cluster_ids": missing,
                },
            )
        return selected

    return [
        c for c in clusters
        if c.get("classification") == "moving_or_transient_candidate"
    ]


def _hits_for_cluster(report, cluster):
    """
    Census v0.9.5 stores cluster summaries but not hit IDs. Re-associate hits
    geometrically to the cluster median center. This is deterministic enough
    because census clustering itself used center proximity.
    """
    center_info = cluster.get("median_center") or {}
    cx = float(center_info.get("x") or 0.0)
    cy = float(center_info.get("y") or 0.0)
    cluster_center = (cx, cy)

    stable = cluster.get("stable_bbox") or {}
    tolerance = max(
        80.0,
        float(cluster.get("max_center_spread_px") or 0.0) + 45.0,
        float(stable.get("width") or 0.0) * 0.55,
        float(stable.get("height") or 0.0) * 0.55,
    )

    result = []
    for hit in report.get("hits") or []:
        bbox = hit.get("bbox") or {}
        if not bbox:
            continue
        if _distance(_bbox_center(bbox), cluster_center) <= tolerance:
            result.append(hit)

    return sorted(
        result,
        key=lambda h: (
            float(h.get("time_seconds") or 0.0),
            -float(h.get("similarity") or 0.0),
            -float(h.get("ocr_confidence") or 0.0),
        ),
    )


def _representative_cluster_hits(report, cluster, limit):
    hits = _hits_for_cluster(report, cluster)
    if not hits:
        return []

    # One strongest hit per unique sampled time.
    best_by_time = {}
    for hit in hits:
        t = round(float(hit.get("time_seconds") or 0.0), 3)
        old = best_by_time.get(t)
        score = (
            float(hit.get("similarity") or 0.0),
            float(hit.get("ocr_confidence") or 0.0),
        )
        if old is None or score > (
            float(old.get("similarity") or 0.0),
            float(old.get("ocr_confidence") or 0.0),
        ):
            best_by_time[t] = hit

    unique = list(best_by_time.values())
    unique.sort(
        key=lambda h: (
            float(h.get("similarity") or 0.0),
            float(h.get("ocr_confidence") or 0.0),
        ),
        reverse=True,
    )
    return unique[: max(1, int(limit))]


def _stroke_response_and_mask(
    frame,
    bbox,
    kernel_width,
    kernel_height,
    response_percentile,
    min_component_area,
    max_component_area_ratio,
    dilate_iterations,
    close_iterations,
):
    h, w = frame.shape[:2]
    b = _clip_bbox(bbox, w, h)
    roi = frame[
        b["y"]: b["y"] + b["height"],
        b["x"]: b["x"] + b["width"],
    ]

    gray = cv2.cvtColor(roi, cv2.COLOR_BGR2GRAY)

    kw = max(3, int(kernel_width))
    kh = max(3, int(kernel_height))
    if kw % 2 == 0:
        kw += 1
    if kh % 2 == 0:
        kh += 1

    kw = min(kw, max(3, (b["width"] // 2) * 2 - 1))
    kh = min(kh, max(3, (b["height"] // 2) * 2 - 1))
    kernel = cv2.getStructuringElement(cv2.MORPH_RECT, (kw, kh))

    top = cv2.morphologyEx(gray, cv2.MORPH_TOPHAT, kernel)
    black = cv2.morphologyEx(gray, cv2.MORPH_BLACKHAT, kernel)
    response = cv2.max(top, black)
    response = cv2.GaussianBlur(response, (3, 3), 0)

    nonzero = response[response > 0]
    if nonzero.size:
        percentile_thr = float(np.percentile(nonzero, float(response_percentile)))
    else:
        percentile_thr = 255.0

    otsu_thr, _ = cv2.threshold(
        response,
        0,
        255,
        cv2.THRESH_BINARY + cv2.THRESH_OTSU,
    )
    threshold_value = max(8.0, min(percentile_thr, max(8.0, float(otsu_thr))))

    _, binary = cv2.threshold(
        response,
        threshold_value,
        255,
        cv2.THRESH_BINARY,
    )

    if int(close_iterations) > 0:
        close_kernel = cv2.getStructuringElement(cv2.MORPH_RECT, (3, 3))
        binary = cv2.morphologyEx(
            binary,
            cv2.MORPH_CLOSE,
            close_kernel,
            iterations=int(close_iterations),
        )

    # Remove obvious background texture components while retaining text strokes.
    num_labels, labels, stats, _ = cv2.connectedComponentsWithStats(
        binary,
        connectivity=8,
    )
    cleaned = np.zeros_like(binary)
    roi_area = max(1, b["width"] * b["height"])
    max_area = max(
        int(min_component_area) + 1,
        int(round(float(max_component_area_ratio) * roi_area)),
    )

    component_count = 0
    kept_component_count = 0
    for label in range(1, num_labels):
        component_count += 1
        area = int(stats[label, cv2.CC_STAT_AREA])
        cw = int(stats[label, cv2.CC_STAT_WIDTH])
        ch = int(stats[label, cv2.CC_STAT_HEIGHT])

        if area < int(min_component_area) or area > max_area:
            continue

        # Text-like components should not be a near-full-frame blob.
        if cw >= int(b["width"] * 0.98) and ch >= int(b["height"] * 0.80):
            continue

        cleaned[labels == label] = 255
        kept_component_count += 1

    if int(dilate_iterations) > 0:
        cleaned = cv2.dilate(
            cleaned,
            np.ones((3, 3), dtype=np.uint8),
            iterations=int(dilate_iterations),
        )

    full_mask = np.zeros((h, w), dtype=np.uint8)
    full_mask[
        b["y"]: b["y"] + b["height"],
        b["x"]: b["x"] + b["width"],
    ] = cleaned

    response_vis = cv2.normalize(
        response,
        None,
        0,
        255,
        cv2.NORM_MINMAX,
    )
    response_vis = cv2.applyColorMap(response_vis, cv2.COLORMAP_TURBO)

    coverage = float(np.count_nonzero(cleaned)) / float(max(1, roi_area))

    return {
        "bbox": b,
        "full_mask": full_mask,
        "roi_mask": cleaned,
        "response_vis": response_vis,
        "coverage_ratio": coverage,
        "threshold_value": float(threshold_value),
        "component_count": component_count,
        "kept_component_count": kept_component_count,
    }


def _stroke_preview_sync(req: BrandingStrokeMaskPreviewRequest):
    report_path = _safe_workspace_path(req.census_report_relative_path)
    try:
        report = json.loads(report_path.read_text(encoding="utf-8"))
    except Exception as exc:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "watermark_stroke_preview",
                "error": "invalid_census_report",
                "message": str(exc)[:500],
            },
        )

    source_rel = ((report.get("source") or {}).get("relative_path") or "").strip()
    if not source_rel:
        raise HTTPException(status_code=422, detail="Census report has no source.relative_path.")

    clusters_all = list(report.get("clusters") or [])
    if req.cluster_ids:
        selected = _select_census_clusters(report, req.cluster_ids)
    else:
        # For stroke-mask evaluation default to every fixed cluster.
        selected = [
            c for c in clusters_all
            if c.get("classification") == "fixed_candidate"
        ]

    if not selected:
        raise HTTPException(status_code=422, detail="No clusters selected.")

    if not 50 <= float(req.response_percentile) <= 99.9:
        raise HTTPException(status_code=422, detail="response_percentile must be between 50 and 99.9.")
    if not 0.01 <= float(req.max_component_area_ratio) <= 0.8:
        raise HTTPException(status_code=422, detail="max_component_area_ratio must be between 0.01 and 0.8.")

    video_path = _safe_workspace_path(source_rel)
    cap = cv2.VideoCapture(str(video_path))
    if not cap.isOpened():
        raise HTTPException(status_code=422, detail="Could not open source video.")

    try:
        metadata = _video_metadata(cap)
        timestamp = _app_now().strftime("%Y-%m-%d_%H%M%S")
        out_dir = WORKSPACE / "review" / "branding_stroke_mask_preview" / timestamp / video_path.stem
        out_dir.mkdir(parents=True, exist_ok=True)

        cluster_results = []
        previews = []

        for cluster in selected:
            cid = int(cluster["cluster_id"])
            stable_bbox = cluster["stable_bbox"]
            representative_hits = _representative_cluster_hits(
                report,
                cluster,
                int(req.max_samples_per_cluster),
            )

            sample_results = []

            for sample_index, hit in enumerate(representative_hits, 1):
                t = float(hit["time_seconds"])
                cap.set(cv2.CAP_PROP_POS_MSEC, t * 1000.0)
                ok, frame = cap.read()
                if not ok or frame is None:
                    continue

                extracted = _stroke_response_and_mask(
                    frame,
                    stable_bbox,
                    req.kernel_width,
                    req.kernel_height,
                    req.response_percentile,
                    req.min_component_area,
                    req.max_component_area_ratio,
                    req.dilate_iterations,
                    req.close_iterations,
                )

                mask = extracted["full_mask"]
                inpainted = cv2.inpaint(
                    frame,
                    mask,
                    float(req.inpaint_radius),
                    cv2.INPAINT_TELEA,
                )

                boxed = frame.copy()
                b = extracted["bbox"]
                cv2.rectangle(
                    boxed,
                    (b["x"], b["y"]),
                    (b["x"] + b["width"], b["y"] + b["height"]),
                    (255, 255, 255),
                    2,
                )

                base = out_dir / f"cluster_{cid:02d}_t_{t:010.3f}_{sample_index:02d}"
                original_path = Path(str(base) + ".original.jpg")
                boxed_path = Path(str(base) + ".boxed.jpg")
                mask_path = Path(str(base) + ".stroke-mask.png")
                inpaint_path = Path(str(base) + ".stroke-inpaint.jpg")
                response_path = Path(str(base) + ".response.jpg")

                cv2.imwrite(str(original_path), frame)
                cv2.imwrite(str(boxed_path), boxed)
                cv2.imwrite(str(mask_path), mask)
                cv2.imwrite(str(inpaint_path), inpainted)

                # Put ROI response back into a black full-frame canvas for easy comparison.
                response_canvas = np.zeros_like(frame)
                rv = extracted["response_vis"]
                response_canvas[
                    b["y"]: b["y"] + b["height"],
                    b["x"]: b["x"] + b["width"],
                ] = rv
                cv2.imwrite(str(response_path), response_canvas)

                sample_record = {
                    "time_seconds": round(t, 3),
                    "source_variant": hit.get("variant"),
                    "observed_text": hit.get("observed_text"),
                    "similarity": hit.get("similarity"),
                    "ocr_confidence": hit.get("ocr_confidence"),
                    "bbox": b,
                    "mask_coverage_ratio": round(extracted["coverage_ratio"], 6),
                    "rectangle_coverage_ratio": 1.0,
                    "coverage_reduction_vs_rectangle": round(
                        1.0 - extracted["coverage_ratio"],
                        6,
                    ),
                    "threshold_value": round(extracted["threshold_value"], 3),
                    "component_count": extracted["component_count"],
                    "kept_component_count": extracted["kept_component_count"],
                    "original": original_path.relative_to(WORKSPACE).as_posix(),
                    "boxed": boxed_path.relative_to(WORKSPACE).as_posix(),
                    "response": response_path.relative_to(WORKSPACE).as_posix(),
                    "mask": mask_path.relative_to(WORKSPACE).as_posix(),
                    "inpaint": inpaint_path.relative_to(WORKSPACE).as_posix(),
                }
                sample_results.append(sample_record)
                previews.append({"cluster_id": cid, **sample_record})

            coverages = [float(s["mask_coverage_ratio"]) for s in sample_results]
            cluster_results.append(
                {
                    "cluster_id": cid,
                    "classification": cluster.get("classification"),
                    "stable_bbox": stable_bbox,
                    "time_min_seconds": cluster.get("time_min_seconds"),
                    "time_max_seconds": cluster.get("time_max_seconds"),
                    "variants_seen": cluster.get("variants_seen"),
                    "sample_count": len(sample_results),
                    "median_mask_coverage_ratio": round(_median(coverages), 6)
                    if coverages else None,
                    "median_coverage_reduction_vs_rectangle": round(
                        1.0 - _median(coverages),
                        6,
                    ) if coverages else None,
                }
            )

        result = {
            "ok": True,
            "version": "0.17.0",
            "mode": "branding_stroke_mask_preview",
            "source": {
                "relative_path": source_rel,
                "census_report_relative_path": report_path.relative_to(WORKSPACE).as_posix(),
            },
            "video": metadata,
            "config": {
                "kernel_width": int(req.kernel_width),
                "kernel_height": int(req.kernel_height),
                "response_percentile": float(req.response_percentile),
                "min_component_area": int(req.min_component_area),
                "max_component_area_ratio": float(req.max_component_area_ratio),
                "dilate_iterations": int(req.dilate_iterations),
                "close_iterations": int(req.close_iterations),
                "inpaint_radius": float(req.inpaint_radius),
            },
            "summary": {
                "selected_cluster_count": len(selected),
                "preview_sample_count": len(previews),
                "source_video_modified": False,
                "full_processed_video_created": False,
                "manual_stroke_mask_review_required": True,
            },
            "clusters": cluster_results,
            "previews": previews,
            "output_relative_dir": out_dir.relative_to(WORKSPACE).as_posix(),
            "review_note": (
                "The stroke mask should follow watermark strokes rather than fill the whole OCR rectangle. "
                "Compare original, response, stroke-mask and stroke-inpaint. "
                "A low coverage ratio is desirable only if the complete watermark is still covered."
            ),
        }

        report_out = out_dir / f"{video_path.stem}.stroke-mask-preview.json"
        result["report_relative_path"] = report_out.relative_to(WORKSPACE).as_posix()
        report_out.write_text(
            json.dumps(result, ensure_ascii=False, indent=2),
            encoding="utf-8",
        )
        return result
    finally:
        cap.release()


def _farneback_bbox_step(prev_gray, next_gray, bbox, params):
    h, w = prev_gray.shape[:2]
    b = _clip_bbox(bbox, w, h)

    flow = cv2.calcOpticalFlowFarneback(
        prev_gray,
        next_gray,
        None,
        float(params["pyr_scale"]),
        int(params["levels"]),
        int(params["winsize"]),
        int(params["iterations"]),
        int(params["poly_n"]),
        float(params["poly_sigma"]),
        0,
    )

    x1 = b["x"]
    y1 = b["y"]
    x2 = b["x"] + b["width"]
    y2 = b["y"] + b["height"]

    # Ignore a thin edge margin to reduce contamination from nearby background.
    mx = max(1, int(round(b["width"] * 0.10)))
    my = max(1, int(round(b["height"] * 0.10)))
    sx1 = min(x2 - 1, x1 + mx)
    sy1 = min(y2 - 1, y1 + my)
    sx2 = max(sx1 + 1, x2 - mx)
    sy2 = max(sy1 + 1, y2 - my)

    roi_flow = flow[sy1:sy2, sx1:sx2]
    if roi_flow.size == 0:
        return b, {"ok": False, "reason": "empty_flow_roi"}

    dx = roi_flow[..., 0].reshape(-1)
    dy = roi_flow[..., 1].reshape(-1)
    finite = np.isfinite(dx) & np.isfinite(dy)
    if int(np.count_nonzero(finite)) < 20:
        return b, {"ok": False, "reason": "insufficient_finite_flow"}

    dx = dx[finite]
    dy = dy[finite]
    med_dx = float(np.median(dx))
    med_dy = float(np.median(dy))

    mad = float(
        np.median(
            np.sqrt(
                np.square(dx - med_dx)
                + np.square(dy - med_dy)
            )
        )
    )

    moved = _clip_bbox(
        {
            "x": int(round(b["x"] + med_dx)),
            "y": int(round(b["y"] + med_dy)),
            "width": b["width"],
            "height": b["height"],
        },
        w,
        h,
    )

    return moved, {
        "ok": True,
        "median_dx": round(med_dx, 4),
        "median_dy": round(med_dy, 4),
        "flow_mad": round(mad, 4),
        "finite_flow_pixels": int(np.count_nonzero(finite)),
    }


def _flow_track_preview_sync(req: BrandingFlowTrackPreviewRequest):
    report_path = _safe_workspace_path(req.census_report_relative_path)
    try:
        report = json.loads(report_path.read_text(encoding="utf-8"))
    except Exception as exc:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "watermark_flow_track",
                "error": "invalid_census_report",
                "message": str(exc)[:500],
            },
        )

    source_rel = ((report.get("source") or {}).get("relative_path") or "").strip()
    if not source_rel:
        raise HTTPException(status_code=422, detail="Census report has no source.relative_path.")

    selected = _select_census_clusters(report, req.cluster_ids)
    if not selected:
        # This is a valid outcome for a video containing only fixed watermarks.
        return {
            "ok": True,
            "version": "0.17.0",
            "mode": "branding_flow_track_preview",
            "source": {
                "relative_path": source_rel,
                "census_report_relative_path": report_path.relative_to(WORKSPACE).as_posix(),
            },
            "summary": {
                "selected_cluster_count": 0,
                "track_count": 0,
                "source_video_modified": False,
                "reason": "no_moving_or_transient_clusters",
            },
            "tracks": [],
        }

    if str(req.direction).lower() != "forward":
        raise HTTPException(
            status_code=422,
            detail="v0.9.6 flow preview currently supports direction='forward' only.",
        )
    if not 0.25 <= float(req.track_seconds) <= 10:
        raise HTTPException(status_code=422, detail="track_seconds must be between 0.25 and 10.")
    if not 1 <= int(req.sample_every_frames) <= 30:
        raise HTTPException(status_code=422, detail="sample_every_frames must be between 1 and 30.")

    video_path = _safe_workspace_path(source_rel)
    cap = cv2.VideoCapture(str(video_path))
    if not cap.isOpened():
        raise HTTPException(status_code=422, detail="Could not open source video.")

    params = {
        "pyr_scale": float(req.pyr_scale),
        "levels": int(req.levels),
        "winsize": int(req.winsize),
        "iterations": int(req.iterations),
        "poly_n": int(req.poly_n),
        "poly_sigma": float(req.poly_sigma),
    }

    try:
        metadata = _video_metadata(cap)
        fps = float(metadata.get("fps") or 30.0)
        duration = float(metadata.get("duration_seconds") or 0.0)

        timestamp = _app_now().strftime("%Y-%m-%d_%H%M%S")
        out_dir = WORKSPACE / "review" / "branding_flow_track_preview" / timestamp / video_path.stem
        out_dir.mkdir(parents=True, exist_ok=True)

        tracks = []
        debug_clips = []

        for cluster in selected[: int(req.max_tracks)]:
            cid = int(cluster["cluster_id"])
            hits = _hits_for_cluster(report, cluster)
            if not hits:
                continue

            anchor = max(
                hits,
                key=lambda h: (
                    float(h.get("similarity") or 0.0),
                    float(h.get("ocr_confidence") or 0.0),
                ),
            )
            anchor_t = float(anchor["time_seconds"])
            bbox = dict(anchor["bbox"])

            cap.set(cv2.CAP_PROP_POS_MSEC, anchor_t * 1000.0)
            ok, prev_frame = cap.read()
            if not ok or prev_frame is None:
                continue

            prev_gray = cv2.cvtColor(prev_frame, cv2.COLOR_BGR2GRAY)
            path = [{
                "time_seconds": round(anchor_t, 4),
                "bbox": bbox,
                "anchor": True,
                "flow": None,
            }]

            max_steps = int(round(float(req.track_seconds) * fps))
            frame_step = int(req.sample_every_frames)

            debug_frames = []
            if req.save_debug_video:
                first_dbg = prev_frame.copy()
                b = _clip_bbox(bbox, first_dbg.shape[1], first_dbg.shape[0])
                cv2.rectangle(
                    first_dbg,
                    (b["x"], b["y"]),
                    (b["x"] + b["width"], b["y"] + b["height"]),
                    (255, 255, 255),
                    2,
                )
                debug_frames.append(first_dbg)

            current_index = 0
            while current_index < max_steps:
                # Advance frame_step frames sequentially.
                next_frame = None
                ok = True
                for _ in range(frame_step):
                    ok, next_frame = cap.read()
                    current_index += 1
                    if not ok or next_frame is None:
                        break
                if not ok or next_frame is None:
                    break

                current_t = anchor_t + current_index / fps
                if duration > 0 and current_t > duration:
                    break

                next_gray = cv2.cvtColor(next_frame, cv2.COLOR_BGR2GRAY)
                bbox, flow_diag = _farneback_bbox_step(
                    prev_gray,
                    next_gray,
                    bbox,
                    params,
                )

                path.append({
                    "time_seconds": round(current_t, 4),
                    "bbox": bbox,
                    "anchor": False,
                    "flow": flow_diag,
                })

                if req.save_debug_video:
                    dbg = next_frame.copy()
                    b = _clip_bbox(bbox, dbg.shape[1], dbg.shape[0])
                    cv2.rectangle(
                        dbg,
                        (b["x"], b["y"]),
                        (b["x"] + b["width"], b["y"] + b["height"]),
                        (255, 255, 255),
                        2,
                    )
                    debug_frames.append(dbg)

                prev_gray = next_gray

            debug_rel = None
            if req.save_debug_video and debug_frames:
                clip_path = out_dir / f"cluster_{cid:02d}_flow.mp4"
                proc, _ = _open_x264_raw_writer(
                    clip_path,
                    debug_frames[0].shape[1],
                    debug_frames[0].shape[0],
                    fps / frame_step,
                    int(req.crf),
                    str(req.preset),
                )
                write_error = None
                try:
                    for frame in debug_frames:
                        try:
                            proc.stdin.write(frame.tobytes())
                        except Exception as exc:
                            write_error = str(exc)[:400]
                            break
                finally:
                    try:
                        if proc.stdin:
                            proc.stdin.close()
                    except Exception:
                        pass
                stderr = proc.stderr.read() if proc.stderr else b""
                rc = proc.wait()
                if rc == 0 and write_error is None and clip_path.exists():
                    debug_rel = clip_path.relative_to(WORKSPACE).as_posix()

            tracks.append({
                "cluster_id": cid,
                "classification": cluster.get("classification"),
                "anchor_time_seconds": round(anchor_t, 3),
                "anchor_observed_text": anchor.get("observed_text"),
                "anchor_similarity": anchor.get("similarity"),
                "anchor_ocr_confidence": anchor.get("ocr_confidence"),
                "anchor_bbox": anchor.get("bbox"),
                "path_sample_count": len(path),
                "path": path,
                "debug_video_relative_path": debug_rel,
            })

        result = {
            "ok": True,
            "version": "0.17.0",
            "mode": "branding_flow_track_preview",
            "source": {
                "relative_path": source_rel,
                "census_report_relative_path": report_path.relative_to(WORKSPACE).as_posix(),
            },
            "video": metadata,
            "flow": {
                "algorithm": "Farneback",
                **params,
                "track_seconds": float(req.track_seconds),
                "sample_every_frames": int(req.sample_every_frames),
            },
            "summary": {
                "selected_cluster_count": len(selected),
                "track_count": len(tracks),
                "source_video_modified": False,
                "full_processed_video_created": False,
                "manual_track_review_required": bool(tracks),
            },
            "tracks": tracks,
            "output_relative_dir": out_dir.relative_to(WORKSPACE).as_posix(),
            "review_note": (
                "This endpoint is a tracker diagnostic. OCR detections remain anchors; "
                "dense optical flow propagates the bbox between/after anchors. "
                "Do not remove pixels from a moving watermark until track drift is visually reviewed."
            ),
        }

        report_out = out_dir / f"{video_path.stem}.flow-track-preview.json"
        result["report_relative_path"] = report_out.relative_to(WORKSPACE).as_posix()
        report_out.write_text(
            json.dumps(result, ensure_ascii=False, indent=2),
            encoding="utf-8",
        )
        return result
    finally:
        cap.release()




class BrandingVisualWatermarkCensusRequest(BaseModel):
    census_report_relative_path: str

    # Optional tight crop supplied by a reviewer.  This is the preferred mode
    # for faint translucent watermarks: it searches the actual glyph shape and
    # does not treat ordinary OCR text from posters, subtitles or CTA cards as
    # a moving watermark anchor.
    reference_image_relative_path: Optional[str] = None
    reference_crop_x: Optional[int] = None
    reference_crop_y: Optional[int] = None
    reference_crop_width: Optional[int] = None
    reference_crop_height: Optional[int] = None

    # Clear wordmark/logo cluster used to build a visual template.
    source_cluster_id: int = 1
    template_sample_count: int = 6

    # Search cadence.
    start_seconds: float = 0.0
    end_seconds: Optional[float] = None
    scan_interval_seconds: float = 0.75
    max_frames: int = 220

    # Edge-domain visual search. Opacity changes matter much less here than OCR.
    scales: list[float] = Field(
        default_factory=lambda: [0.60, 0.75, 0.90, 1.0, 1.15, 1.30, 1.50, 1.80, 2.20]
    )
    angles_degrees: list[float] = Field(
        default_factory=lambda: [-30.0, -15.0, 0.0, 15.0, 30.0]
    )
    match_threshold: float = 0.38
    top_k_per_frame: int = 5
    nms_iou_threshold: float = 0.30

    # Existing OCR clusters are explicitly suppressed so they cannot be
    # rediscovered as "faint watermark" candidates.
    exclude_existing_ocr_clusters: bool = True
    exclude_padding_px: int = 18

    # Cross-time consensus.
    cluster_center_tolerance_px: float = 120.0
    cluster_scale_ratio_tolerance: float = 1.8
    min_unique_times: int = 3
    fixed_max_center_spread_px: float = 110.0

    # Screenshot-reference tracks may be transient.  A candidate must still
    # appear in more than one sampled frame; one-screen OCR/template flashes
    # are never promoted to a dynamic watermark.
    transient_min_unique_times: int = 2
    transient_max_span_seconds: float = 12.0

    # Strict reference mode: a watermark template is expected to retain a
    # near-original scale and shallow rotation. Broad generic matching is too
    # permissive for natural video texture and subtitles.
    reference_min_score: float = 0.62
    reference_max_scale_deviation: float = 0.16
    reference_max_abs_angle_degrees: float = 8.0
    reference_min_spatial_support: int = 3

    # A screenshot reference by itself has too much scene background to safely
    # search across an entire video.  Extraction therefore requires a source
    # frame anchor (time + tight bbox) unless an expert explicitly uses the
    # diagnostic-only broad search path.
    require_reference_anchor: bool = True

    # A screenshot crop alone is not enough to authorize a dynamic track. The
    # target must also be observed in a coherent source-side motion segment;
    # scattered template coincidences across unrelated scenes are rejected.
    require_source_motion_consensus: bool = True
    motion_consensus_max_gap_seconds: float = 1.25
    motion_consensus_max_center_jump_px: float = 150.0
    motion_consensus_min_samples: int = 3

    # Optional source-frame anchor for a reviewer-confirmed faint watermark.
    # It is deliberately independent from OCR clusters and lets calibration
    # recover a translucent wordmark that is too weak for generic search.
    reference_anchor_time_seconds: Optional[float] = None
    reference_anchor_x: Optional[int] = None
    reference_anchor_y: Optional[int] = None
    reference_anchor_width: Optional[int] = None
    reference_anchor_height: Optional[int] = None
    reference_anchor_score_threshold: float = 0.70
    reference_anchor_search_padding_px: int = 72
    reference_anchor_max_center_drift_px: float = 90.0
    reference_anchor_local_window_seconds: float = 3.0
    reference_anchor_sample_interval_seconds: float = 0.10
    reference_anchor_segment_max_gap_seconds: float = 0.35
    reference_anchor_segment_min_samples: int = 3

    save_debug_frames: bool = True
    max_debug_frames: int = 80


def _edge_signature(frame):
    """
    Contrast/opacity tolerant visual signature.
    CLAHE + Scharr gradient magnitude emphasizes wordmark contours while
    suppressing absolute brightness differences caused by transparency.
    """
    if len(frame.shape) == 3:
        gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
    else:
        gray = frame.copy()

    clahe = cv2.createCLAHE(clipLimit=2.2, tileGridSize=(8, 8))
    gray = clahe.apply(gray)

    gx = cv2.Scharr(gray, cv2.CV_32F, 1, 0)
    gy = cv2.Scharr(gray, cv2.CV_32F, 0, 1)
    mag = cv2.magnitude(gx, gy)
    mag = cv2.GaussianBlur(mag, (3, 3), 0)

    p = float(np.percentile(mag, 97.0)) if mag.size else 1.0
    if not np.isfinite(p) or p <= 1e-6:
        p = 1.0
    mag = np.clip(mag / p, 0.0, 1.0)
    return (mag * 255.0).astype(np.uint8)


def _rotate_bound_gray(image, angle_deg):
    if abs(float(angle_deg)) < 1e-6:
        return image

    h, w = image.shape[:2]
    center = (w / 2.0, h / 2.0)
    matrix = cv2.getRotationMatrix2D(center, float(angle_deg), 1.0)

    cos = abs(matrix[0, 0])
    sin = abs(matrix[0, 1])
    nw = int(math.ceil(h * sin + w * cos))
    nh = int(math.ceil(h * cos + w * sin))

    matrix[0, 2] += nw / 2.0 - center[0]
    matrix[1, 2] += nh / 2.0 - center[1]

    return cv2.warpAffine(
        image,
        matrix,
        (nw, nh),
        flags=cv2.INTER_LINEAR,
        borderMode=cv2.BORDER_CONSTANT,
        borderValue=0,
    )


def _expanded_bbox(bbox, pad, width, height):
    return _clip_bbox(
        {
            "x": int(bbox["x"]) - int(pad),
            "y": int(bbox["y"]) - int(pad),
            "width": int(bbox["width"]) + int(pad) * 2,
            "height": int(bbox["height"]) + int(pad) * 2,
        },
        width,
        height,
    )


def _extract_visual_template(report, source_cluster, video_path, sample_count):
    """
    Build a robust wordmark edge template from multiple strong occurrences.
    Median aggregation suppresses changing background detail while preserving
    the persistent ReelShort strokes.
    """
    hits = _hits_for_cluster(report, source_cluster)
    if not hits:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "visual_watermark_census",
                "error": "source_cluster_has_no_hits",
                "source_cluster_id": source_cluster.get("cluster_id"),
            },
        )

    # Prefer exact/high-confidence hits.
    ranked = sorted(
        hits,
        key=lambda h: (
            1 if h.get("exact") else 0,
            float(h.get("similarity") or 0.0),
            float(h.get("ocr_confidence") or 0.0),
        ),
        reverse=True,
    )

    # One hit per time, spread across the video where possible.
    best_by_time = {}
    for hit in ranked:
        t = round(float(hit.get("time_seconds") or 0.0), 3)
        if t not in best_by_time:
            best_by_time[t] = hit

    candidates = list(best_by_time.values())
    if len(candidates) > sample_count:
        # Evenly sample ranked candidates to avoid one short scene dominating.
        indexes = np.linspace(0, len(candidates) - 1, sample_count).round().astype(int)
        candidates = [candidates[int(i)] for i in indexes]

    cap = cv2.VideoCapture(str(video_path))
    if not cap.isOpened():
        raise HTTPException(status_code=422, detail="Could not open source video.")

    try:
        signatures = []
        sample_meta = []
        target_w = None
        target_h = None

        for hit in candidates[: max(1, int(sample_count))]:
            t = float(hit["time_seconds"])
            cap.set(cv2.CAP_PROP_POS_MSEC, t * 1000.0)
            ok, frame = cap.read()
            if not ok or frame is None:
                continue

            fh, fw = frame.shape[:2]
            b = _clip_bbox(hit["bbox"], fw, fh)
            crop = frame[
                b["y"]: b["y"] + b["height"],
                b["x"]: b["x"] + b["width"],
            ]
            if crop.size == 0:
                continue

            if target_w is None:
                target_w = max(48, int(b["width"]))
                target_h = max(16, int(b["height"]))

            crop = cv2.resize(
                crop,
                (target_w, target_h),
                interpolation=cv2.INTER_CUBIC,
            )
            sig = _edge_signature(crop)
            signatures.append(sig.astype(np.float32))
            sample_meta.append({
                "time_seconds": round(t, 3),
                "bbox": b,
                "observed_text": hit.get("observed_text"),
                "similarity": hit.get("similarity"),
                "ocr_confidence": hit.get("ocr_confidence"),
            })

        if len(signatures) < 2:
            raise HTTPException(
                status_code=422,
                detail={
                    "stage": "visual_watermark_census",
                    "error": "insufficient_template_samples",
                    "usable_samples": len(signatures),
                },
            )

        stack = np.stack(signatures, axis=0)
        template = np.median(stack, axis=0).astype(np.uint8)

        # Remove weak residual background gradient and keep persistent strokes.
        nonzero = template[template > 0]
        thr = float(np.percentile(nonzero, 55.0)) if nonzero.size else 0.0
        template = np.where(template >= thr, template, 0).astype(np.uint8)

        return template, sample_meta
    finally:
        cap.release()


def _extract_reference_visual_template(req):
    """Build an edge-domain template from a reviewer-provided watermark crop."""
    reference_rel = str(
        getattr(req, "reference_image_relative_path", None) or ""
    ).strip()
    if not reference_rel:
        return None, None

    reference_path = _safe_workspace_path(reference_rel)
    image = cv2.imread(str(reference_path), cv2.IMREAD_UNCHANGED)
    if image is None or image.size == 0:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "visual_watermark_census",
                "error": "reference_image_unreadable",
                "reference_image_relative_path": reference_rel,
            },
        )

    h, w = image.shape[:2]
    crop_values = [
        getattr(req, "reference_crop_x", None),
        getattr(req, "reference_crop_y", None),
        getattr(req, "reference_crop_width", None),
        getattr(req, "reference_crop_height", None),
    ]
    if any(value is not None for value in crop_values):
        if any(value is None for value in crop_values):
            raise HTTPException(
                status_code=422,
                detail={
                    "stage": "visual_watermark_census",
                    "error": "reference_crop_requires_all_coordinates",
                },
            )
        bbox = _clip_bbox(
            {
                "x": int(crop_values[0]),
                "y": int(crop_values[1]),
                "width": int(crop_values[2]),
                "height": int(crop_values[3]),
            },
            w,
            h,
        )
        image = image[
            bbox["y"]:bbox["y"] + bbox["height"],
            bbox["x"]:bbox["x"] + bbox["width"],
        ]
    else:
        bbox = {"x": 0, "y": 0, "width": int(w), "height": int(h)}

    if image.shape[0] < 8 or image.shape[1] < 24:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "visual_watermark_census",
                "error": "reference_image_too_small",
                "width": int(image.shape[1]),
                "height": int(image.shape[0]),
            },
        )

    template = _edge_signature(image)
    positive = template[template > 0]
    floor = float(np.percentile(positive, 58.0)) if positive.size else 255.0
    template = np.where(template >= floor, template, 0).astype(np.uint8)
    nonzero = int(np.count_nonzero(template))
    if nonzero < max(18, int(template.size * 0.012)):
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "visual_watermark_census",
                "error": "reference_image_has_insufficient_glyph_structure",
                "nonzero_pixels": nonzero,
            },
        )

    return template, {
        "relative_path": reference_rel,
        "crop": bbox,
        "width": int(template.shape[1]),
        "height": int(template.shape[0]),
        "nonzero_pixels": nonzero,
        "signature": "reviewer_reference_CLAHE_Scharr_edge_signature",
    }


def _extract_reference_anchor_template(req, video_path):
    """Extract a tight visual template from a reviewer-confirmed source ROI."""
    values = [
        getattr(req, "reference_anchor_time_seconds", None),
        getattr(req, "reference_anchor_x", None),
        getattr(req, "reference_anchor_y", None),
        getattr(req, "reference_anchor_width", None),
        getattr(req, "reference_anchor_height", None),
    ]
    if not any(value is not None for value in values):
        return None, None
    if any(value is None for value in values):
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "visual_watermark_census",
                "error": "reference_anchor_requires_time_and_full_bbox",
            },
        )

    cap = cv2.VideoCapture(str(video_path))
    if not cap.isOpened():
        raise HTTPException(status_code=422, detail="Could not open source video.")
    try:
        time_seconds = float(values[0])
        cap.set(cv2.CAP_PROP_POS_MSEC, time_seconds * 1000.0)
        ok, frame = cap.read()
        if not ok or frame is None:
            raise HTTPException(
                status_code=422,
                detail={
                    "stage": "visual_watermark_census",
                    "error": "reference_anchor_frame_unreadable",
                    "time_seconds": time_seconds,
                },
            )
        height, width = frame.shape[:2]
        bbox = _clip_bbox(
            {
                "x": int(values[1]),
                "y": int(values[2]),
                "width": int(values[3]),
                "height": int(values[4]),
            },
            width,
            height,
        )
        crop = frame[
            bbox["y"]:bbox["y"] + bbox["height"],
            bbox["x"]:bbox["x"] + bbox["width"],
        ]
        if crop.size == 0 or crop.shape[0] < 8 or crop.shape[1] < 24:
            raise HTTPException(
                status_code=422,
                detail={
                    "stage": "visual_watermark_census",
                    "error": "reference_anchor_crop_too_small",
                    "bbox": bbox,
                },
            )
        template = _edge_signature(crop)
        nonzero = int(np.count_nonzero(template))
        if nonzero < max(18, int(template.size * 0.012)):
            raise HTTPException(
                status_code=422,
                detail={
                    "stage": "visual_watermark_census",
                    "error": "reference_anchor_has_insufficient_glyph_structure",
                    "bbox": bbox,
                    "nonzero_pixels": nonzero,
                },
            )
        return template, {
            "time_seconds": round(time_seconds, 3),
            "bbox": bbox,
            "width": int(template.shape[1]),
            "height": int(template.shape[0]),
            "nonzero_pixels": nonzero,
            "signature": "source_anchor_CLAHE_Scharr_edge_signature",
        }
    finally:
        cap.release()


def _reference_anchor_bbox(req):
    values = [
        getattr(req, "reference_anchor_time_seconds", None),
        getattr(req, "reference_anchor_x", None),
        getattr(req, "reference_anchor_y", None),
        getattr(req, "reference_anchor_width", None),
        getattr(req, "reference_anchor_height", None),
    ]
    if any(value is None for value in values):
        return None
    return {
        "x": int(values[1]),
        "y": int(values[2]),
        "width": int(values[3]),
        "height": int(values[4]),
    }


def _anchored_reference_hits(
    video_path,
    template,
    anchor_bbox,
    *,
    start_seconds,
    end_seconds,
    interval_seconds,
    max_frames,
    score_threshold,
    search_padding_px,
    max_center_drift_px,
):
    """Track a faint watermark around a reviewer-confirmed source anchor.

    Full-frame template searches are inherently ambiguous for semi-transparent
    lettering.  The user has supplied an authoritative frame and region, so
    constrain the search around that screen-space location and require a high
    shape match.  This produces a REVIEW evidence track, never an automatic
    replacement action by itself.
    """
    cap = cv2.VideoCapture(str(video_path))
    if not cap.isOpened():
        raise HTTPException(status_code=422, detail="Could not open source video.")
    hits = []
    sampled = []
    try:
        metadata = _video_metadata(cap)
        width = int(metadata.get("width") or 0)
        height = int(metadata.get("height") or 0)
        anchor = _clip_bbox(anchor_bbox, width, height)
        search = _expanded_bbox(
            anchor,
            int(search_padding_px),
            width,
            height,
        )
        t = float(start_seconds)
        frames = 0
        while t <= float(end_seconds) + 1e-9 and frames < int(max_frames):
            cap.set(cv2.CAP_PROP_POS_MSEC, t * 1000.0)
            ok, frame = cap.read()
            if not ok or frame is None:
                t += float(interval_seconds)
                continue
            signature = _edge_signature(frame)
            roi = signature[
                search["y"]:search["y"] + search["height"],
                search["x"]:search["x"] + search["width"],
            ]
            if roi.shape[0] >= template.shape[0] and roi.shape[1] >= template.shape[1]:
                response = cv2.matchTemplate(roi, template, cv2.TM_CCOEFF_NORMED)
                _, score, _, loc = cv2.minMaxLoc(response)
                bbox = {
                    "x": int(search["x"] + loc[0]),
                    "y": int(search["y"] + loc[1]),
                    "width": int(template.shape[1]),
                    "height": int(template.shape[0]),
                }
                anchor_center = _bbox_center(anchor)
                center_distance = _distance(_bbox_center(bbox), anchor_center)
                if (
                    float(score) >= float(score_threshold)
                    and center_distance <= float(max_center_drift_px)
                ):
                    hits.append(
                        {
                            "time_seconds": round(float(t), 3),
                            "score": round(float(score), 5),
                            "bbox": bbox,
                            "center_drift_px": round(center_distance, 3),
                            "match_mode": "reviewer_source_anchor_local_search",
                        }
                    )
            sampled.append(round(float(t), 3))
            frames += 1
            t += float(interval_seconds)
        return {
            "metadata": metadata,
            "anchor_bbox": anchor,
            "search_bbox": search,
            "sampled_times": sampled,
            "hits": hits,
        }
    finally:
        cap.release()


def _visual_nms(candidates, iou_threshold, top_k):
    ordered = sorted(candidates, key=lambda c: float(c["score"]), reverse=True)
    kept = []
    for cand in ordered:
        if any(_bbox_iou(cand["bbox"], old["bbox"]) >= iou_threshold for old in kept):
            continue
        kept.append(cand)
        if len(kept) >= top_k:
            break
    return kept


def _visual_candidate_overlaps_exclusion(candidate_bbox, exclusions):
    for ex in exclusions:
        if _bbox_iou(candidate_bbox, ex) >= 0.08:
            return True

        # Also reject if candidate center lies inside excluded rectangle.
        cx, cy = _bbox_center(candidate_bbox)
        if (
            ex["x"] <= cx <= ex["x"] + ex["width"]
            and ex["y"] <= cy <= ex["y"] + ex["height"]
        ):
            return True
    return False


def _match_visual_template_on_frame(
    frame,
    template,
    scales,
    angles,
    threshold,
    top_k,
    nms_iou,
    exclusions,
):
    frame_sig = _edge_signature(frame)
    fh, fw = frame_sig.shape[:2]

    all_candidates = []

    for angle in angles:
        rotated = _rotate_bound_gray(template, float(angle))
        rh, rw = rotated.shape[:2]
        if rh < 4 or rw < 8:
            continue

        for scale in scales:
            scale = float(scale)
            if scale <= 0:
                continue

            tw = max(8, int(round(rw * scale)))
            th = max(4, int(round(rh * scale)))
            if tw >= fw or th >= fh:
                continue

            candidate_template = cv2.resize(
                rotated,
                (tw, th),
                interpolation=cv2.INTER_CUBIC if scale >= 1.0 else cv2.INTER_AREA,
            )

            # Skip near-empty templates.
            if int(np.count_nonzero(candidate_template)) < max(20, int(tw * th * 0.025)):
                continue

            response = cv2.matchTemplate(
                frame_sig,
                candidate_template,
                cv2.TM_CCOEFF_NORMED,
            )

            # Take several local maxima per transform so one strong top logo
            # does not hide a second faint watermark.
            local = response.copy()
            picks = 0
            while picks < max(2, int(top_k)):
                _, max_val, _, max_loc = cv2.minMaxLoc(local)
                score = float(max_val)
                if not np.isfinite(score) or score < float(threshold):
                    break

                bbox = {
                    "x": int(max_loc[0]),
                    "y": int(max_loc[1]),
                    "width": int(tw),
                    "height": int(th),
                }

                if not _visual_candidate_overlaps_exclusion(bbox, exclusions):
                    all_candidates.append({
                        "score": round(score, 5),
                        "bbox": bbox,
                        "scale": round(scale, 4),
                        "angle_degrees": round(float(angle), 3),
                    })

                # Suppress neighborhood around the selected response peak.
                x1 = max(0, int(max_loc[0] - tw * 0.5))
                y1 = max(0, int(max_loc[1] - th * 0.5))
                x2 = min(local.shape[1], int(max_loc[0] + tw * 0.5))
                y2 = min(local.shape[0], int(max_loc[1] + th * 0.5))
                if x2 > x1 and y2 > y1:
                    local[y1:y2, x1:x2] = -1.0
                picks += 1

    return _visual_nms(
        all_candidates,
        float(nms_iou),
        int(top_k),
    )


def _reference_template_candidates_on_frame(
    frame,
    template,
    *,
    min_score,
    scales,
    max_scale_deviation,
    angles,
    max_abs_angle_degrees,
    top_k,
    nms_iou,
    exclusions,
):
    """Strict reviewer-template matcher for faint overlay glyphs.

    Screenshot references are already tightly cropped wordmarks.  Searching
    them across arbitrary rotations/scales turns background texture into false
    text.  Preserve the reference geometry and require a high raw signature
    correlation before a candidate can enter spatial-grid validation.
    """
    allowed_scales = [
        float(value)
        for value in scales
        if abs(float(value) - 1.0) <= float(max_scale_deviation) + 1e-6
    ]
    if not allowed_scales:
        allowed_scales = [1.0]
    allowed_angles = [
        float(value)
        for value in angles
        if abs(float(value)) <= float(max_abs_angle_degrees) + 1e-6
    ]
    if not allowed_angles:
        allowed_angles = [0.0]

    frame_sig = _edge_signature(frame)
    fh, fw = frame_sig.shape[:2]
    candidates = []

    for angle in allowed_angles:
        rotated = _rotate_bound_gray(template, angle)
        rh, rw = rotated.shape[:2]
        for scale in allowed_scales:
            tw = max(16, int(round(rw * scale)))
            th = max(8, int(round(rh * scale)))
            if tw >= fw or th >= fh:
                continue
            needle = cv2.resize(
                rotated,
                (tw, th),
                interpolation=(
                    cv2.INTER_CUBIC if scale >= 1.0 else cv2.INTER_AREA
                ),
            )
            if int(np.count_nonzero(needle)) < max(24, int(needle.size * 0.02)):
                continue
            response = cv2.matchTemplate(
                frame_sig,
                needle,
                cv2.TM_CCOEFF_NORMED,
            )
            local = response.copy()
            picks = 0
            while picks < max(1, int(top_k)):
                _, score, _, location = cv2.minMaxLoc(local)
                if not np.isfinite(score) or float(score) < float(min_score):
                    break
                bbox = {
                    "x": int(location[0]),
                    "y": int(location[1]),
                    "width": int(tw),
                    "height": int(th),
                }
                if not _visual_candidate_overlaps_exclusion(bbox, exclusions):
                    candidates.append(
                        {
                            "score": round(float(score), 5),
                            "bbox": bbox,
                            "scale": round(float(scale), 4),
                            "angle_degrees": round(float(angle), 3),
                        }
                    )
                x1 = max(0, int(location[0] - tw * 0.50))
                y1 = max(0, int(location[1] - th * 0.50))
                x2 = min(local.shape[1], int(location[0] + tw * 0.50))
                y2 = min(local.shape[0], int(location[1] + th * 0.50))
                local[y1:y2, x1:x2] = -1.0
                picks += 1

    return _visual_nms(candidates, float(nms_iou), int(top_k))


def _reference_grid_frame_support(candidates, min_spatial_support):
    """Keep only frames where the reference glyph repeats as an overlay grid."""
    if len(candidates) < int(min_spatial_support):
        return []

    centers = [_bbox_center(item["bbox"]) for item in candidates]
    xs = [center[0] for center in centers]
    ys = [center[1] for center in centers]
    # A tiled watermark should cover distinct x and y lanes, unlike one
    # title/subtitle line or a single in-scene poster.
    x_span = max(xs) - min(xs)
    y_span = max(ys) - min(ys)
    median_w = max(1.0, _median([item["bbox"]["width"] for item in candidates]))
    median_h = max(1.0, _median([item["bbox"]["height"] for item in candidates]))
    if x_span < median_w * 1.2 or y_span < median_h * 1.2:
        return []
    return candidates


def _reference_motion_consensus_segments(
    hits,
    *,
    max_gap_seconds,
    max_center_jump_px,
    min_samples,
):
    """Keep only coherent short source-side tracks from a screenshot template.

    A translucent watermark may drift with the source compositor.  A real track
    therefore has nearby timestamps and bounded motion.  Hits that only recur
    across unrelated scenes are template coincidences, not watermark evidence.
    """
    ordered = sorted(hits or [], key=lambda item: float(item["time_seconds"]))
    segments = []
    current = []
    for hit in ordered:
        if not current:
            current = [hit]
            continue
        previous = current[-1]
        dt = float(hit["time_seconds"]) - float(previous["time_seconds"])
        jump = _distance(_bbox_center(hit["bbox"]), _bbox_center(previous["bbox"]))
        if dt <= float(max_gap_seconds) and jump <= float(max_center_jump_px):
            current.append(hit)
        else:
            if len(current) >= int(min_samples):
                segments.append(current)
            current = [hit]
    if len(current) >= int(min_samples):
        segments.append(current)
    return segments


def _cluster_visual_candidates(hits, center_tolerance, scale_ratio_tolerance):
    clusters = []

    for hit in sorted(hits, key=lambda h: float(h["time_seconds"])):
        center = _bbox_center(hit["bbox"])
        area = _bbox_area(hit["bbox"])

        best_idx = None
        best_dist = None
        for idx, cluster in enumerate(clusters):
            dist = _distance(center, cluster["center"])
            med_area = max(1.0, float(cluster["median_area"]))
            ratio = max(area / med_area, med_area / area)

            if dist <= center_tolerance and ratio <= scale_ratio_tolerance:
                if best_dist is None or dist < best_dist:
                    best_idx = idx
                    best_dist = dist

        if best_idx is None:
            clusters.append({
                "hits": [hit],
                "center": center,
                "median_area": area,
            })
        else:
            cluster = clusters[best_idx]
            cluster["hits"].append(hit)
            centers = [_bbox_center(h["bbox"]) for h in cluster["hits"]]
            areas = [_bbox_area(h["bbox"]) for h in cluster["hits"]]
            cluster["center"] = (
                _median([c[0] for c in centers]),
                _median([c[1] for c in centers]),
            )
            cluster["median_area"] = _median(areas)

    clusters.sort(key=lambda c: (c["center"][1], c["center"][0]))
    return clusters


def _visual_cluster_report(idx, cluster, min_times, fixed_spread, width, height):
    hits = cluster["hits"]
    times = sorted({round(float(h["time_seconds"]), 3) for h in hits})
    centers = [_bbox_center(h["bbox"]) for h in hits]
    med_center = (
        _median([c[0] for c in centers]),
        _median([c[1] for c in centers]),
    )
    spreads = [_distance(c, med_center) for c in centers]
    max_spread = max(spreads) if spreads else 0.0

    boxes = [h["bbox"] for h in hits]
    x1 = int(round(_quantile([b["x"] for b in boxes], 0.10)))
    y1 = int(round(_quantile([b["y"] for b in boxes], 0.10)))
    x2 = int(round(_quantile([b["x"] + b["width"] for b in boxes], 0.90)))
    y2 = int(round(_quantile([b["y"] + b["height"] for b in boxes], 0.90)))
    stable = _clip_bbox(
        {
            "x": x1,
            "y": y1,
            "width": max(1, x2 - x1),
            "height": max(1, y2 - y1),
        },
        width,
        height,
    )

    enough = len(times) >= int(min_times)
    classification = (
        "fixed_visual_candidate"
        if enough and max_spread <= float(fixed_spread)
        else "moving_or_transient_visual_candidate"
    )

    return {
        "visual_cluster_id": idx,
        "classification": classification,
        "hit_count": len(hits),
        "unique_time_count": len(times),
        "time_min_seconds": min(times) if times else None,
        "time_max_seconds": max(times) if times else None,
        "median_center": {
            "x": round(med_center[0], 2),
            "y": round(med_center[1], 2),
        },
        "max_center_spread_px": round(max_spread, 2),
        "stable_bbox": stable,
        "median_bbox_area": round(_median([_bbox_area(b) for b in boxes]), 2),
        "best_match_score": round(max(float(h["score"]) for h in hits), 5),
        "median_match_score": round(_median([float(h["score"]) for h in hits]), 5),
        "angles_seen": sorted({float(h["angle_degrees"]) for h in hits}),
        "scales_seen": sorted({float(h["scale"]) for h in hits}),
        "sample_times": times[:100],
        "promoted_by_temporal_consensus": enough,
    }


def _anchored_reference_local_track(
    video_path,
    template,
    anchor_bbox,
    anchor_time,
    *,
    window_seconds,
    interval_seconds,
    score_threshold,
    search_padding_px,
    max_center_drift_px,
):
    """Dense local track around the confirmed anchor for frame-level proof."""
    start = max(0.0, float(anchor_time) - float(window_seconds))
    end = float(anchor_time) + float(window_seconds)
    return _anchored_reference_hits(
        video_path,
        template,
        anchor_bbox,
        start_seconds=start,
        end_seconds=end,
        interval_seconds=max(0.033333, float(interval_seconds)),
        max_frames=max(1, int(round((end - start) / max(0.033333, float(interval_seconds)))) + 1),
        score_threshold=score_threshold,
        search_padding_px=search_padding_px,
        max_center_drift_px=max_center_drift_px,
    )


def _reference_track_segments(hits, max_gap_seconds, min_samples):
    """Group accepted anchor hits into contiguous frame-level watermark spans."""
    ordered = sorted(hits or [], key=lambda item: float(item["time_seconds"]))
    segments = []
    current = []
    for item in ordered:
        if current and (
            float(item["time_seconds"]) - float(current[-1]["time_seconds"])
            > float(max_gap_seconds)
        ):
            if len(current) >= int(min_samples):
                segments.append(current)
            current = []
        current.append(item)
    if len(current) >= int(min_samples):
        segments.append(current)

    return [
        {
            "start_seconds": round(float(segment[0]["time_seconds"]), 3),
            "end_seconds": round(float(segment[-1]["time_seconds"]), 3),
            "sample_count": len(segment),
            "mean_score": round(
                sum(float(item["score"]) for item in segment) / len(segment),
                5,
            ),
            "max_score": round(
                max(float(item["score"]) for item in segment),
                5,
            ),
            "points": segment,
        }
        for segment in segments
    ]


def _promote_reference_visual_clusters(
    cluster_reports,
    *,
    fixed_max_center_spread_px,
    transient_min_unique_times,
    transient_max_span_seconds,
):
    """Promote only persistent or short multi-frame reference-template tracks."""
    promoted = []
    for cluster in cluster_reports:
        unique_times = int(cluster.get("unique_time_count") or 0)
        start = float(cluster.get("time_min_seconds") or 0.0)
        end = float(cluster.get("time_max_seconds") or start)
        span = max(0.0, end - start)
        spread = float(cluster.get("max_center_spread_px") or 0.0)

        if (
            unique_times >= int(transient_min_unique_times)
            and span <= float(transient_max_span_seconds)
        ):
            promoted.append(
                {
                    **cluster,
                    "classification": "reference_transient_watermark_candidate",
                    "promotion_reason": "multi_frame_reference_template_short_track",
                    "track_span_seconds": round(span, 3),
                }
            )
            continue

        if (
            bool(cluster.get("promoted_by_temporal_consensus"))
            and spread <= float(fixed_max_center_spread_px)
        ):
            promoted.append(
                {
                    **cluster,
                    "classification": "reference_persistent_watermark_candidate",
                    "promotion_reason": "cross_time_reference_template_consensus",
                    "track_span_seconds": round(span, 3),
                }
            )

    return promoted


def _visual_watermark_census_sync(req: BrandingVisualWatermarkCensusRequest):
    report_path = _safe_workspace_path(req.census_report_relative_path)
    try:
        report = json.loads(report_path.read_text(encoding="utf-8"))
    except Exception as exc:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "visual_watermark_census",
                "error": "invalid_census_report",
                "message": str(exc)[:500],
            },
        )

    source_rel = ((report.get("source") or {}).get("relative_path") or "").strip()
    if not source_rel:
        raise HTTPException(status_code=422, detail="Census report has no source.relative_path.")

    clusters = list(report.get("clusters") or [])
    reference_mode = bool(
        str(getattr(req, "reference_image_relative_path", None) or "").strip()
    )
    if (
        reference_mode
        and bool(getattr(req, "require_reference_anchor", True))
        and _reference_anchor_bbox(req) is None
    ):
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "visual_watermark_census",
                "error": "reference_anchor_required_for_extraction",
                "message": (
                    "A screenshot reference must be paired with a source-frame "
                    "anchor time and bbox before it can produce a watermark track."
                ),
                "next_step": (
                    "Provide reference_anchor_time_seconds and the source-frame "
                    "bbox for the faint watermark."
                ),
            },
        )
    source_cluster = None
    if not reference_mode:
        source_cluster = next(
            (
                c for c in clusters
                if int(c.get("cluster_id") or -1) == int(req.source_cluster_id)
            ),
            None,
        )
        if source_cluster is None:
            raise HTTPException(
                status_code=422,
                detail={
                    "error": "source_cluster_id_not_found",
                    "source_cluster_id": int(req.source_cluster_id),
                },
            )

    if not 0.15 <= float(req.match_threshold) <= 0.95:
        raise HTTPException(status_code=422, detail="match_threshold must be between 0.15 and 0.95.")
    if not 1 <= int(req.top_k_per_frame) <= 30:
        raise HTTPException(status_code=422, detail="top_k_per_frame must be between 1 and 30.")
    if not 1 <= int(req.template_sample_count) <= 20:
        raise HTTPException(status_code=422, detail="template_sample_count must be between 1 and 20.")
    if not 0.25 <= float(req.scan_interval_seconds) <= 10:
        raise HTTPException(status_code=422, detail="scan_interval_seconds must be between 0.25 and 10.")
    if not 1 <= int(req.max_frames) <= 2000:
        raise HTTPException(status_code=422, detail="max_frames must be between 1 and 2000.")
    if not 1 <= int(req.min_unique_times) <= 100:
        raise HTTPException(status_code=422, detail="min_unique_times must be between 1 and 100.")
    if not 2 <= int(req.transient_min_unique_times) <= 100:
        raise HTTPException(status_code=422, detail="transient_min_unique_times must be between 2 and 100.")
    if not 0.15 <= float(req.reference_min_score) <= 0.98:
        raise HTTPException(status_code=422, detail="reference_min_score must be between 0.15 and 0.98.")
    if not 0.0 <= float(req.reference_max_scale_deviation) <= 0.80:
        raise HTTPException(status_code=422, detail="reference_max_scale_deviation must be between 0 and 0.80.")
    if not 0.0 <= float(req.reference_max_abs_angle_degrees) <= 45.0:
        raise HTTPException(status_code=422, detail="reference_max_abs_angle_degrees must be between 0 and 45.")
    if not 2 <= int(req.reference_min_spatial_support) <= 20:
        raise HTTPException(status_code=422, detail="reference_min_spatial_support must be between 2 and 20.")

    video_path = _safe_workspace_path(source_rel)
    if reference_mode:
        template, reference_meta = _extract_reference_anchor_template(
            req,
            video_path,
        )
        if template is None:
            template, reference_meta = _extract_reference_visual_template(req)
        template_samples = []
    else:
        template, template_samples = _extract_visual_template(
            report,
            source_cluster,
            video_path,
            int(req.template_sample_count),
        )
        reference_meta = None

    anchor_tracking = None
    anchor_local_track = None
    if reference_mode and _reference_anchor_bbox(req) is not None:
        anchor_tracking = _anchored_reference_hits(
            video_path,
            template,
            _reference_anchor_bbox(req),
            start_seconds=max(0.0, float(req.start_seconds or 0.0)),
            end_seconds=(
                float(req.end_seconds)
                if req.end_seconds is not None
                else float((_probe_media(video_path) or {}).get("duration_seconds") or 0.0)
            ),
            interval_seconds=float(req.scan_interval_seconds),
            max_frames=int(req.max_frames),
            score_threshold=float(req.reference_anchor_score_threshold),
            search_padding_px=int(req.reference_anchor_search_padding_px),
            max_center_drift_px=float(req.reference_anchor_max_center_drift_px),
        )
        anchor_local_track = _anchored_reference_local_track(
            video_path,
            template,
            _reference_anchor_bbox(req),
            float(req.reference_anchor_time_seconds),
            window_seconds=float(req.reference_anchor_local_window_seconds),
            interval_seconds=float(req.reference_anchor_sample_interval_seconds),
            score_threshold=min(
                float(req.reference_anchor_score_threshold),
                0.48,
            ),
            search_padding_px=int(req.reference_anchor_search_padding_px),
            max_center_drift_px=float(req.reference_anchor_max_center_drift_px),
        )
        anchor_local_track["segments"] = _reference_track_segments(
            anchor_local_track.get("hits") or [],
            float(req.reference_anchor_segment_max_gap_seconds),
            int(req.reference_anchor_segment_min_samples),
        )

    cap = cv2.VideoCapture(str(video_path))
    if not cap.isOpened():
        raise HTTPException(status_code=422, detail="Could not open source video.")

    try:
        metadata = _video_metadata(cap)
        width = int(metadata.get("width") or 0)
        height = int(metadata.get("height") or 0)
        duration = float(metadata.get("duration_seconds") or 0.0)

        start = max(0.0, float(req.start_seconds or 0.0))
        if req.end_seconds is None:
            end = duration if duration > 0 else start + 60.0
        else:
            end = max(start, float(req.end_seconds))
            if duration > 0:
                end = min(end, duration)

        span = max(0.001, end - start)
        interval = max(
            float(req.scan_interval_seconds),
            span / max(1, int(req.max_frames)),
        )

        exclusions = []
        if req.exclude_existing_ocr_clusters:
            for cluster in clusters:
                stable = cluster.get("stable_bbox") or {}
                if not stable:
                    continue
                # The reference crop describes the faint target itself; its
                # strong OCR source cluster may occupy the same position in
                # some frames and must not globally mask reference matching.
                if (
                    reference_mode
                    and int(cluster.get("cluster_id") or -1)
                    == int(req.source_cluster_id)
                ):
                    continue
                exclusions.append(
                    _expanded_bbox(
                        stable,
                        int(req.exclude_padding_px),
                        width,
                        height,
                    )
                )

        timestamp = _app_now().strftime("%Y-%m-%d_%H%M%S")
        out_dir = WORKSPACE / "review" / "branding_visual_watermark_census" / timestamp / video_path.stem
        debug_dir = out_dir / "frames"
        out_dir.mkdir(parents=True, exist_ok=True)
        if req.save_debug_frames:
            debug_dir.mkdir(parents=True, exist_ok=True)

        template_path = out_dir / "visual-template.png"
        cv2.imwrite(str(template_path), template)

        all_hits = []
        frames_scanned = 0
        frames_with_candidates = 0
        debug_saved = 0

        if anchor_tracking is not None:
            all_hits = [
                {
                    "time_seconds": item["time_seconds"],
                    "score": item["score"],
                    "bbox": item["bbox"],
                    "scale": 1.0,
                    "angle_degrees": 0.0,
                    "anchor_tracking": True,
                    "center_drift_px": item["center_drift_px"],
                }
                for item in anchor_tracking.get("hits") or []
            ]
            frames_scanned = len(anchor_tracking.get("sampled_times") or [])
            frames_with_candidates = len(
                {item["time_seconds"] for item in all_hits}
            )

        t = start
        while (
            anchor_tracking is None
            and t <= end + 1e-9
            and frames_scanned < int(req.max_frames)
        ):
            cap.set(cv2.CAP_PROP_POS_MSEC, t * 1000.0)
            ok, frame = cap.read()
            if not ok or frame is None:
                t += interval
                continue

            frames_scanned += 1
            if reference_mode:
                candidates = _reference_template_candidates_on_frame(
                    frame,
                    template,
                    min_score=float(req.reference_min_score),
                    scales=req.scales,
                    max_scale_deviation=float(req.reference_max_scale_deviation),
                    angles=req.angles_degrees,
                    max_abs_angle_degrees=float(req.reference_max_abs_angle_degrees),
                    top_k=int(req.top_k_per_frame),
                    nms_iou=float(req.nms_iou_threshold),
                    exclusions=exclusions,
                )
                candidates = _reference_grid_frame_support(
                    candidates,
                    int(req.reference_min_spatial_support),
                )
            else:
                candidates = _match_visual_template_on_frame(
                    frame,
                    template,
                    req.scales,
                    req.angles_degrees,
                    float(req.match_threshold),
                    int(req.top_k_per_frame),
                    float(req.nms_iou_threshold),
                    exclusions,
                )

            if candidates:
                frames_with_candidates += 1

            for cand in candidates:
                all_hits.append({
                    "time_seconds": round(float(t), 3),
                    **cand,
                })

            if (
                req.save_debug_frames
                and candidates
                and debug_saved < int(req.max_debug_frames)
            ):
                dbg = frame.copy()

                # Draw exclusions lightly.
                for ex in exclusions:
                    cv2.rectangle(
                        dbg,
                        (ex["x"], ex["y"]),
                        (ex["x"] + ex["width"], ex["y"] + ex["height"]),
                        (100, 100, 100),
                        1,
                    )

                for cand in candidates:
                    b = cand["bbox"]
                    cv2.rectangle(
                        dbg,
                        (b["x"], b["y"]),
                        (b["x"] + b["width"], b["y"] + b["height"]),
                        (255, 255, 255),
                        2,
                    )
                    label = (
                        f"visual {cand['score']:.2f} "
                        f"s={cand['scale']:.2f} a={cand['angle_degrees']:.0f}"
                    )
                    cv2.putText(
                        dbg,
                        label,
                        (b["x"], max(18, b["y"] - 5)),
                        cv2.FONT_HERSHEY_SIMPLEX,
                        0.42,
                        (255, 255, 255),
                        1,
                        cv2.LINE_AA,
                    )

                debug_saved += 1
                cv2.imwrite(
                    str(debug_dir / f"{debug_saved:03d}_t_{t:010.3f}.jpg"),
                    dbg,
                )

            t += interval

        visual_clusters_raw = _cluster_visual_candidates(
            all_hits,
            float(req.cluster_center_tolerance_px),
            float(req.cluster_scale_ratio_tolerance),
        )

        cluster_reports = []
        promoted_clusters = []
        for idx, cluster in enumerate(visual_clusters_raw, 1):
            c = _visual_cluster_report(
                idx,
                cluster,
                int(req.min_unique_times),
                float(req.fixed_max_center_spread_px),
                width,
                height,
            )
            cluster_reports.append(c)
            if c["promoted_by_temporal_consensus"]:
                promoted_clusters.append(c)

        if reference_mode:
            promoted_clusters = _promote_reference_visual_clusters(
                cluster_reports,
                fixed_max_center_spread_px=float(req.fixed_max_center_spread_px),
                transient_min_unique_times=int(req.transient_min_unique_times),
                transient_max_span_seconds=float(req.transient_max_span_seconds),
            )

            if bool(req.require_source_motion_consensus):
                segments = _reference_motion_consensus_segments(
                    all_hits,
                    max_gap_seconds=float(req.motion_consensus_max_gap_seconds),
                    max_center_jump_px=float(req.motion_consensus_max_center_jump_px),
                    min_samples=int(req.motion_consensus_min_samples),
                )
                consensus_times = {
                    (round(float(hit["time_seconds"]), 3), int(hit["bbox"]["x"]), int(hit["bbox"]["y"]))
                    for segment in segments
                    for hit in segment
                }
                promoted_clusters = [
                    cluster
                    for cluster in promoted_clusters
                    if any(
                        (
                            round(float(hit["time_seconds"]), 3),
                            int(hit["bbox"]["x"]),
                            int(hit["bbox"]["y"]),
                        ) in consensus_times
                        for hit in all_hits
                    )
                ]
            else:
                segments = []
        else:
            segments = []

        fixed_count = sum(
            1 for c in promoted_clusters
            if c["classification"] == "fixed_visual_candidate"
        )
        moving_count = sum(
            1 for c in promoted_clusters
            if c["classification"] == "moving_or_transient_visual_candidate"
        )

        result = {
            "ok": True,
            "version": "0.17.0",
            "mode": "branding_visual_watermark_census",
            "source": {
                "relative_path": source_rel,
                "census_report_relative_path": report_path.relative_to(WORKSPACE).as_posix(),
                "source_cluster_id": (
                    int(req.source_cluster_id)
                    if source_cluster is not None
                    else None
                ),
            },
            "video": metadata,
            "template": {
                "relative_path": template_path.relative_to(WORKSPACE).as_posix(),
                "width": int(template.shape[1]),
                "height": int(template.shape[0]),
                "sample_count": len(template_samples),
                "samples": template_samples,
                "signature": (
                    "reviewer reference: CLAHE + Scharr gradient magnitude"
                    if reference_mode
                    else "CLAHE + Scharr gradient magnitude + multi-frame median"
                ),
                "reference": reference_meta,
            },
            "search": {
                "start_seconds": round(start, 3),
                "end_seconds": round(end, 3),
                "requested_interval_seconds": float(req.scan_interval_seconds),
                "effective_interval_seconds": round(interval, 4),
                "frames_scanned": frames_scanned,
                "frames_with_candidates": frames_with_candidates,
                "scales": [float(x) for x in req.scales],
                "angles_degrees": [float(x) for x in req.angles_degrees],
                "match_threshold": float(req.match_threshold),
                "top_k_per_frame": int(req.top_k_per_frame),
                "exclude_existing_ocr_clusters": bool(req.exclude_existing_ocr_clusters),
                "excluded_region_count": len(exclusions),
                "reference_mode": reference_mode,
                "transient_min_unique_times": int(req.transient_min_unique_times),
                "transient_max_span_seconds": float(req.transient_max_span_seconds),
                "reference_min_score": float(req.reference_min_score),
                "reference_max_scale_deviation": float(req.reference_max_scale_deviation),
                "reference_max_abs_angle_degrees": float(req.reference_max_abs_angle_degrees),
                "reference_min_spatial_support": int(req.reference_min_spatial_support),
                "reference_anchor_tracking": anchor_tracking is not None,
                "reference_anchor_score_threshold": float(req.reference_anchor_score_threshold),
                "reference_anchor_search_padding_px": int(req.reference_anchor_search_padding_px),
                "reference_anchor_max_center_drift_px": float(req.reference_anchor_max_center_drift_px),
                "reference_anchor_local_window_seconds": float(req.reference_anchor_local_window_seconds),
                "reference_anchor_sample_interval_seconds": float(req.reference_anchor_sample_interval_seconds),
                "reference_anchor_segment_max_gap_seconds": float(req.reference_anchor_segment_max_gap_seconds),
                "reference_anchor_segment_min_samples": int(req.reference_anchor_segment_min_samples),
                "require_source_motion_consensus": bool(req.require_source_motion_consensus),
                "motion_consensus_max_gap_seconds": float(req.motion_consensus_max_gap_seconds),
                "motion_consensus_max_center_jump_px": float(req.motion_consensus_max_center_jump_px),
                "motion_consensus_min_samples": int(req.motion_consensus_min_samples),
            },
            "summary": {
                "raw_visual_hit_count": len(all_hits),
                "raw_visual_cluster_count": len(cluster_reports),
                "promoted_visual_cluster_count": len(promoted_clusters),
                "fixed_visual_candidate_count": fixed_count,
                "moving_or_transient_visual_candidate_count": moving_count,
                "debug_frames_saved": debug_saved,
                "source_video_modified": False,
                "ocr_used_for_search": False,
                "reference_template_used": reference_mode,
                "reference_anchor_tracking_used": anchor_tracking is not None,
            },
            "promoted_clusters": promoted_clusters,
            "all_clusters": cluster_reports,
            "hits": all_hits,
            "anchor_tracking": anchor_tracking,
            "anchor_local_track": anchor_local_track,
            "reference_motion_consensus_segments": [
                {
                    "sample_count": len(segment),
                    "start_seconds": round(float(segment[0]["time_seconds"]), 3),
                    "end_seconds": round(float(segment[-1]["time_seconds"]), 3),
                    "hits": segment,
                }
                for segment in segments
            ],
            "interpretation": {
                "important": (
                    "Visual search uses glyph contours rather than OCR. In reviewer-reference mode, "
                    "the supplied faint watermark crop is the only template; ordinary poster/CTA text "
                    "cannot become a watermark without matching that template across multiple frames."
                ),
                "fixed_visual_candidate": (
                    "The visual wordmark candidate repeats at approximately the same screen location."
                ),
                "moving_or_transient_visual_candidate": (
                    "The ReelShort-like contour repeats across time but its center moves substantially; "
                    "this should be verified and then tracked frame-to-frame."
                ),
            },
        }

        report_out = out_dir / f"{video_path.stem}.visual-watermark-census.json"
        result["report_relative_path"] = report_out.relative_to(WORKSPACE).as_posix()
        result["debug_frames_relative_dir"] = (
            debug_dir.relative_to(WORKSPACE).as_posix()
            if req.save_debug_frames
            else None
        )
        report_out.write_text(
            json.dumps(result, ensure_ascii=False, indent=2),
            encoding="utf-8",
        )
        return result
    finally:
        cap.release()




class BrandingTemporalOverlayRequest(BaseModel):
    census_report_relative_path: str

    start_seconds: float = 0.0
    end_seconds: Optional[float] = None
    scan_interval_seconds: float = 0.75
    max_frames: int = 260

    # Divide the video into time buckets. A real screen-fixed translucent
    # watermark should reappear in multiple unrelated temporal buckets.
    temporal_bins: int = 8
    min_bin_presence_count: int = 4

    # Per-frame faint text/overlay response.
    morph_kernel_widths: list[int] = Field(
        default_factory=lambda: [15, 31, 61]
    )
    frame_response_percentile: float = 88.0

    # Cross-time persistence thresholds.
    bin_response_percentile: float = 88.0
    global_response_percentile: float = 72.0

    # Suppress regions already explained by OCR: clear top logo, end card,
    # promotional text, etc.
    exclude_existing_ocr_clusters: bool = True
    exclude_padding_px: int = 20

    # Candidate grouping/filtering.
    group_close_width: int = 31
    group_close_height: int = 7
    group_dilate_iterations: int = 1
    min_bbox_width: int = 36
    min_bbox_height: int = 10
    min_candidate_pixels: int = 28
    max_bbox_area_ratio: float = 0.35
    max_candidates: int = 40

    save_diagnostic_images: bool = True


def _overlay_frame_response(frame, kernel_widths):
    """
    Produce a contrast-normalized response for faint bright/dark text-like
    overlays. It does not try to read the text or match any brand template.
    """
    gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
    clahe = cv2.createCLAHE(clipLimit=2.0, tileGridSize=(8, 8))
    gray = clahe.apply(gray)

    responses = []

    for width in kernel_widths:
        kw = max(5, int(width))
        if kw % 2 == 0:
            kw += 1

        kh = max(3, int(round(kw * 0.35)))
        if kh % 2 == 0:
            kh += 1

        kernel = cv2.getStructuringElement(cv2.MORPH_RECT, (kw, kh))
        top = cv2.morphologyEx(gray, cv2.MORPH_TOPHAT, kernel)
        black = cv2.morphologyEx(gray, cv2.MORPH_BLACKHAT, kernel)
        responses.append(cv2.max(top, black).astype(np.float32))

    # Also add local gradient energy. This helps when a translucent watermark
    # leaves edge structure but little absolute brightness difference.
    gx = cv2.Scharr(gray, cv2.CV_32F, 1, 0)
    gy = cv2.Scharr(gray, cv2.CV_32F, 0, 1)
    grad = cv2.magnitude(gx, gy)
    grad = cv2.GaussianBlur(grad, (3, 3), 0)
    responses.append(grad)

    combined = np.maximum.reduce(responses)

    # Robust per-frame normalization. The goal is not OCR-quality text, but a
    # comparable 0..1 structural response across changing scenes.
    positive = combined[combined > 0]
    if positive.size:
        scale = float(np.percentile(positive, 99.2))
    else:
        scale = 1.0
    if not np.isfinite(scale) or scale <= 1e-6:
        scale = 1.0

    combined = np.clip(combined / scale, 0.0, 1.0)
    return combined.astype(np.float32)


def _make_exclusion_mask(report, width, height, padding):
    mask = np.ones((height, width), dtype=np.uint8)
    boxes = []

    for cluster in report.get("clusters") or []:
        stable = cluster.get("stable_bbox") or {}
        if not stable:
            continue
        b = _expanded_bbox(stable, int(padding), width, height)
        boxes.append(b)
        cv2.rectangle(
            mask,
            (b["x"], b["y"]),
            (b["x"] + b["width"], b["y"] + b["height"]),
            0,
            thickness=-1,
        )

    return mask, boxes


def _normalize_u8(array):
    arr = np.asarray(array, dtype=np.float32)
    finite = arr[np.isfinite(arr)]
    if finite.size == 0:
        return np.zeros(arr.shape, dtype=np.uint8)

    lo = float(np.percentile(finite, 1.0))
    hi = float(np.percentile(finite, 99.5))
    if hi <= lo + 1e-9:
        hi = lo + 1.0

    norm = np.clip((arr - lo) / (hi - lo), 0.0, 1.0)
    return (norm * 255.0).astype(np.uint8)


def _temporal_overlay_sync(req: BrandingTemporalOverlayRequest):
    report_path = _safe_workspace_path(req.census_report_relative_path)
    try:
        report = json.loads(report_path.read_text(encoding="utf-8"))
    except Exception as exc:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "temporal_overlay",
                "error": "invalid_census_report",
                "message": str(exc)[:500],
            },
        )

    source_rel = ((report.get("source") or {}).get("relative_path") or "").strip()
    if not source_rel:
        raise HTTPException(status_code=422, detail="Census report has no source.relative_path.")

    if not 0.25 <= float(req.scan_interval_seconds) <= 10:
        raise HTTPException(status_code=422, detail="scan_interval_seconds must be between 0.25 and 10.")
    if not 1 <= int(req.max_frames) <= 2000:
        raise HTTPException(status_code=422, detail="max_frames must be between 1 and 2000.")
    if not 3 <= int(req.temporal_bins) <= 24:
        raise HTTPException(status_code=422, detail="temporal_bins must be between 3 and 24.")
    if not 1 <= int(req.min_bin_presence_count) <= int(req.temporal_bins):
        raise HTTPException(status_code=422, detail="min_bin_presence_count must be between 1 and temporal_bins.")
    if not 50 <= float(req.frame_response_percentile) <= 99.9:
        raise HTTPException(status_code=422, detail="frame_response_percentile must be between 50 and 99.9.")
    if not 50 <= float(req.bin_response_percentile) <= 99.9:
        raise HTTPException(status_code=422, detail="bin_response_percentile must be between 50 and 99.9.")
    if not 40 <= float(req.global_response_percentile) <= 99.9:
        raise HTTPException(status_code=422, detail="global_response_percentile must be between 40 and 99.9.")
    if not 0.01 <= float(req.max_bbox_area_ratio) <= 0.8:
        raise HTTPException(status_code=422, detail="max_bbox_area_ratio must be between 0.01 and 0.8.")

    video_path = _safe_workspace_path(source_rel)
    cap = cv2.VideoCapture(str(video_path))
    if not cap.isOpened():
        raise HTTPException(status_code=422, detail="Could not open source video.")

    try:
        metadata = _video_metadata(cap)
        width = int(metadata.get("width") or 0)
        height = int(metadata.get("height") or 0)
        duration = float(metadata.get("duration_seconds") or 0.0)

        start = max(0.0, float(req.start_seconds or 0.0))
        if req.end_seconds is None:
            end = duration if duration > 0 else start + 60.0
        else:
            end = max(start, float(req.end_seconds))
            if duration > 0:
                end = min(end, duration)

        span = max(0.001, end - start)
        interval = max(
            float(req.scan_interval_seconds),
            span / max(1, int(req.max_frames)),
        )

        if req.exclude_existing_ocr_clusters:
            valid_mask, exclusion_boxes = _make_exclusion_mask(
                report,
                width,
                height,
                int(req.exclude_padding_px),
            )
        else:
            valid_mask = np.ones((height, width), dtype=np.uint8)
            exclusion_boxes = []

        bin_count = int(req.temporal_bins)
        bin_soft_sums = [
            np.zeros((height, width), dtype=np.float32)
            for _ in range(bin_count)
        ]
        bin_hard_counts = [
            np.zeros((height, width), dtype=np.uint16)
            for _ in range(bin_count)
        ]
        frames_per_bin = [0 for _ in range(bin_count)]

        frames_scanned = 0
        t = start

        while t <= end + 1e-9 and frames_scanned < int(req.max_frames):
            cap.set(cv2.CAP_PROP_POS_MSEC, t * 1000.0)
            ok, frame = cap.read()
            if not ok or frame is None:
                t += interval
                continue

            response = _overlay_frame_response(
                frame,
                req.morph_kernel_widths,
            )

            response *= valid_mask.astype(np.float32)

            valid_values = response[valid_mask > 0]
            if valid_values.size:
                frame_thr = float(
                    np.percentile(
                        valid_values,
                        float(req.frame_response_percentile),
                    )
                )
            else:
                frame_thr = 1.0

            hard = (
                (response >= frame_thr)
                & (valid_mask > 0)
            ).astype(np.uint8)

            rel = (t - start) / span
            bin_index = min(
                bin_count - 1,
                max(0, int(math.floor(rel * bin_count))),
            )

            bin_soft_sums[bin_index] += response
            bin_hard_counts[bin_index] += hard.astype(np.uint16)
            frames_per_bin[bin_index] += 1

            frames_scanned += 1
            t += interval

        used_bins = [
            idx for idx, count in enumerate(frames_per_bin)
            if count > 0
        ]
        if not used_bins:
            raise HTTPException(status_code=422, detail="No video frames were scanned.")

        bin_mean_soft = []
        bin_presence_masks = []

        overall_soft_sum = np.zeros((height, width), dtype=np.float32)
        total_frames = 0

        for idx in used_bins:
            count = max(1, frames_per_bin[idx])
            mean_soft = bin_soft_sums[idx] / float(count)
            hard_ratio = bin_hard_counts[idx].astype(np.float32) / float(count)

            overall_soft_sum += bin_soft_sums[idx]
            total_frames += count

            valid_values = mean_soft[valid_mask > 0]
            if valid_values.size:
                soft_thr = float(
                    np.percentile(
                        valid_values,
                        float(req.bin_response_percentile),
                    )
                )
            else:
                soft_thr = 1.0

            # A pixel is "present" in a time bucket if it has both persistent
            # structural energy and appears among strong per-frame responses.
            presence = (
                (mean_soft >= soft_thr)
                & (hard_ratio >= 0.08)
                & (valid_mask > 0)
            ).astype(np.uint8)

            bin_mean_soft.append(mean_soft)
            bin_presence_masks.append(presence)

        overall_mean_soft = overall_soft_sum / float(max(1, total_frames))
        bin_presence_count = np.sum(
            np.stack(bin_presence_masks, axis=0),
            axis=0,
        ).astype(np.uint8)

        valid_overall = overall_mean_soft[valid_mask > 0]
        if valid_overall.size:
            global_thr = float(
                np.percentile(
                    valid_overall,
                    float(req.global_response_percentile),
                )
            )
        else:
            global_thr = 1.0

        min_bins = min(
            int(req.min_bin_presence_count),
            len(used_bins),
        )

        persistent_pixels = (
            (bin_presence_count >= min_bins)
            & (overall_mean_soft >= global_thr)
            & (valid_mask > 0)
        ).astype(np.uint8) * 255

        # Group nearby persistent strokes into reviewable candidate regions.
        grouped = persistent_pixels.copy()

        close_w = max(3, int(req.group_close_width))
        close_h = max(3, int(req.group_close_height))
        if close_w % 2 == 0:
            close_w += 1
        if close_h % 2 == 0:
            close_h += 1

        close_kernel = cv2.getStructuringElement(
            cv2.MORPH_RECT,
            (close_w, close_h),
        )
        grouped = cv2.morphologyEx(
            grouped,
            cv2.MORPH_CLOSE,
            close_kernel,
            iterations=1,
        )

        if int(req.group_dilate_iterations) > 0:
            grouped = cv2.dilate(
                grouped,
                np.ones((3, 3), dtype=np.uint8),
                iterations=int(req.group_dilate_iterations),
            )

        num_labels, labels, stats, _ = cv2.connectedComponentsWithStats(
            (grouped > 0).astype(np.uint8),
            connectivity=8,
        )

        frame_area = max(1, width * height)
        candidates = []

        for label in range(1, num_labels):
            x = int(stats[label, cv2.CC_STAT_LEFT])
            y = int(stats[label, cv2.CC_STAT_TOP])
            w = int(stats[label, cv2.CC_STAT_WIDTH])
            h = int(stats[label, cv2.CC_STAT_HEIGHT])
            grouped_pixels = int(stats[label, cv2.CC_STAT_AREA])

            if w < int(req.min_bbox_width) or h < int(req.min_bbox_height):
                continue

            bbox_area = max(1, w * h)
            if bbox_area / float(frame_area) > float(req.max_bbox_area_ratio):
                continue

            roi_persistent = persistent_pixels[y:y+h, x:x+w] > 0
            persistent_pixel_count = int(np.count_nonzero(roi_persistent))
            if persistent_pixel_count < int(req.min_candidate_pixels):
                continue

            roi_presence = bin_presence_count[y:y+h, x:x+w]
            roi_soft = overall_mean_soft[y:y+h, x:x+w]

            active_bins = []
            for local_idx, presence in enumerate(bin_presence_masks):
                roi = presence[y:y+h, x:x+w]
                ratio = float(np.count_nonzero(roi)) / float(max(1, bbox_area))
                if ratio >= 0.005:
                    active_bins.append(int(used_bins[local_idx]))

            candidates.append(
                {
                    "bbox": {
                        "x": x,
                        "y": y,
                        "width": w,
                        "height": h,
                    },
                    "bbox_area": bbox_area,
                    "persistent_pixel_count": persistent_pixel_count,
                    "persistent_fill_ratio": round(
                        persistent_pixel_count / float(bbox_area),
                        6,
                    ),
                    "grouped_pixel_count": grouped_pixels,
                    "active_temporal_bins": active_bins,
                    "active_temporal_bin_count": len(active_bins),
                    "mean_bin_presence_count": round(
                        float(np.mean(roi_presence)),
                        4,
                    ),
                    "max_bin_presence_count": int(np.max(roi_presence)),
                    "mean_response": round(
                        float(np.mean(roi_soft)),
                        6,
                    ),
                    "max_response": round(
                        float(np.max(roi_soft)),
                        6,
                    ),
                }
            )

        candidates.sort(
            key=lambda c: (
                c["active_temporal_bin_count"],
                c["mean_bin_presence_count"],
                c["mean_response"],
            ),
            reverse=True,
        )
        candidates = candidates[: int(req.max_candidates)]

        timestamp = _app_now().strftime("%Y-%m-%d_%H%M%S")
        out_dir = WORKSPACE / "review" / "branding_temporal_overlay" / timestamp / video_path.stem
        out_dir.mkdir(parents=True, exist_ok=True)

        diagnostic_paths = {}

        if req.save_diagnostic_images:
            mean_path = out_dir / "01_mean_response.png"
            presence_path = out_dir / "02_bin_presence.png"
            mask_path = out_dir / "03_persistent_candidate_mask.png"
            grouped_path = out_dir / "04_grouped_candidate_mask.png"
            overlay_path = out_dir / "05_candidate_overlay.jpg"

            mean_vis = _normalize_u8(overall_mean_soft)
            presence_vis = (
                bin_presence_count.astype(np.float32)
                / float(max(1, len(used_bins)))
                * 255.0
            ).astype(np.uint8)

            cv2.imwrite(str(mean_path), mean_vis)
            cv2.imwrite(str(presence_path), presence_vis)
            cv2.imwrite(str(mask_path), persistent_pixels)
            cv2.imwrite(str(grouped_path), grouped)

            # Draw candidate boxes on a middle source frame.
            mid_t = (start + end) / 2.0
            cap.set(cv2.CAP_PROP_POS_MSEC, mid_t * 1000.0)
            ok, middle_frame = cap.read()
            if not ok or middle_frame is None:
                middle_frame = np.zeros((height, width, 3), dtype=np.uint8)

            for ex in exclusion_boxes:
                cv2.rectangle(
                    middle_frame,
                    (ex["x"], ex["y"]),
                    (ex["x"] + ex["width"], ex["y"] + ex["height"]),
                    (96, 96, 96),
                    1,
                )

            for idx, cand in enumerate(candidates, 1):
                b = cand["bbox"]
                cv2.rectangle(
                    middle_frame,
                    (b["x"], b["y"]),
                    (b["x"] + b["width"], b["y"] + b["height"]),
                    (255, 255, 255),
                    2,
                )
                label = (
                    f"T{idx} bins={cand['active_temporal_bin_count']} "
                    f"p={cand['mean_bin_presence_count']:.1f}"
                )
                cv2.putText(
                    middle_frame,
                    label,
                    (b["x"], max(18, b["y"] - 5)),
                    cv2.FONT_HERSHEY_SIMPLEX,
                    0.42,
                    (255, 255, 255),
                    1,
                    cv2.LINE_AA,
                )

            cv2.imwrite(str(overlay_path), middle_frame)

            diagnostic_paths = {
                "mean_response": mean_path.relative_to(WORKSPACE).as_posix(),
                "bin_presence": presence_path.relative_to(WORKSPACE).as_posix(),
                "persistent_candidate_mask": mask_path.relative_to(WORKSPACE).as_posix(),
                "grouped_candidate_mask": grouped_path.relative_to(WORKSPACE).as_posix(),
                "candidate_overlay": overlay_path.relative_to(WORKSPACE).as_posix(),
            }

        result = {
            "ok": True,
            "version": "0.17.0",
            "mode": "branding_temporal_overlay",
            "source": {
                "relative_path": source_rel,
                "census_report_relative_path": report_path.relative_to(WORKSPACE).as_posix(),
            },
            "video": metadata,
            "scan": {
                "start_seconds": round(start, 3),
                "end_seconds": round(end, 3),
                "requested_interval_seconds": float(req.scan_interval_seconds),
                "effective_interval_seconds": round(interval, 4),
                "frames_scanned": frames_scanned,
                "temporal_bins_requested": int(req.temporal_bins),
                "temporal_bins_used": len(used_bins),
                "frames_per_bin": frames_per_bin,
            },
            "detector": {
                "ocr_used": False,
                "brand_template_used": False,
                "method": (
                    "multi-scale top-hat/black-hat + Scharr structural response "
                    "+ temporal-bin screen-space persistence"
                ),
                "morph_kernel_widths": [int(x) for x in req.morph_kernel_widths],
                "frame_response_percentile": float(req.frame_response_percentile),
                "bin_response_percentile": float(req.bin_response_percentile),
                "global_response_percentile": float(req.global_response_percentile),
                "min_bin_presence_count": min_bins,
                "exclude_existing_ocr_clusters": bool(req.exclude_existing_ocr_clusters),
                "excluded_region_count": len(exclusion_boxes),
            },
            "summary": {
                "candidate_region_count": len(candidates),
                "persistent_pixel_count": int(np.count_nonzero(persistent_pixels)),
                "source_video_modified": False,
                "manual_review_required": True,
                "v0_9_7_template_matching_deprecated_for_faint_watermark": True,
            },
            "candidate_regions": candidates,
            "diagnostic_images": diagnostic_paths,
            "interpretation": {
                "goal": (
                    "Find low-opacity structures that repeatedly occupy the same screen pixels "
                    "across multiple unrelated time buckets, without reading text or matching a ReelShort template."
                ),
                "manual_check": (
                    "Open the persistence/candidate images and verify whether a candidate follows the shallow "
                    "background ReelShort watermark. Static scene/UI structures can still appear and must not be "
                    "removed automatically without review."
                ),
            },
        }

        report_out = out_dir / f"{video_path.stem}.temporal-overlay.json"
        result["report_relative_path"] = report_out.relative_to(WORKSPACE).as_posix()
        result["output_relative_dir"] = out_dir.relative_to(WORKSPACE).as_posix()
        report_out.write_text(
            json.dumps(result, ensure_ascii=False, indent=2),
            encoding="utf-8",
        )
        return result
    finally:
        cap.release()




class BrandingTemporalCandidatePreviewRequest(BaseModel):
    temporal_overlay_report_relative_path: str

    # 1-based indexes from candidate_regions.
    candidate_numbers: list[int] = Field(default_factory=lambda: [2])
    samples_per_candidate: int = 8
    crop_padding_px: int = 24

    # Enhancement is review-only; source stays untouched.
    clahe_clip_limit: float = 2.5
    save_full_frame_boxes: bool = True


def _contact_sheet(images, labels, cols=4, pad=8):
    if not images:
        return None

    heights = [img.shape[0] for img in images]
    widths = [img.shape[1] for img in images]
    cell_h = max(heights) + 34
    cell_w = max(widths)

    rows = int(math.ceil(len(images) / float(cols)))
    sheet = np.zeros(
        (
            rows * cell_h + max(0, rows - 1) * pad,
            cols * cell_w + max(0, cols - 1) * pad,
            3,
        ),
        dtype=np.uint8,
    )

    for idx, img in enumerate(images):
        row = idx // cols
        col = idx % cols
        y0 = row * (cell_h + pad)
        x0 = col * (cell_w + pad)

        canvas = np.zeros((cell_h, cell_w, 3), dtype=np.uint8)
        h, w = img.shape[:2]
        canvas[0:h, 0:w] = img

        label = str(labels[idx]) if idx < len(labels) else ""
        cv2.putText(
            canvas,
            label[:80],
            (6, cell_h - 10),
            cv2.FONT_HERSHEY_SIMPLEX,
            0.50,
            (255, 255, 255),
            1,
            cv2.LINE_AA,
        )

        sheet[
            y0:y0 + cell_h,
            x0:x0 + cell_w,
        ] = canvas

    return sheet


def _enhance_review_crop(crop, clip_limit):
    gray = cv2.cvtColor(crop, cv2.COLOR_BGR2GRAY)
    clahe = cv2.createCLAHE(
        clipLimit=float(clip_limit),
        tileGridSize=(8, 8),
    )
    enhanced = clahe.apply(gray)

    # Local contrast view only, intentionally not used for detection.
    blur = cv2.GaussianBlur(enhanced, (0, 0), sigmaX=3.0)
    highpass = cv2.addWeighted(enhanced, 1.7, blur, -0.7, 0)
    highpass = cv2.normalize(
        highpass,
        None,
        0,
        255,
        cv2.NORM_MINMAX,
    )
    return cv2.cvtColor(highpass, cv2.COLOR_GRAY2BGR)


def _temporal_candidate_preview_sync(req: BrandingTemporalCandidatePreviewRequest):
    report_path = _safe_workspace_path(
        req.temporal_overlay_report_relative_path
    )
    try:
        report = json.loads(
            report_path.read_text(encoding="utf-8")
        )
    except Exception as exc:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "temporal_candidate_preview",
                "error": "invalid_temporal_overlay_report",
                "message": str(exc)[:500],
            },
        )

    source_rel = ((report.get("source") or {}).get("relative_path") or "").strip()
    if not source_rel:
        raise HTTPException(
            status_code=422,
            detail="Temporal overlay report has no source.relative_path.",
        )

    candidates = list(report.get("candidate_regions") or [])
    if not candidates:
        raise HTTPException(
            status_code=422,
            detail="Temporal overlay report has no candidate_regions.",
        )

    requested = []
    for number in req.candidate_numbers:
        n = int(number)
        if n < 1 or n > len(candidates):
            raise HTTPException(
                status_code=422,
                detail={
                    "error": "candidate_number_out_of_range",
                    "candidate_number": n,
                    "available": len(candidates),
                },
            )
        requested.append((n, candidates[n - 1]))

    if not 3 <= int(req.samples_per_candidate) <= 16:
        raise HTTPException(
            status_code=422,
            detail="samples_per_candidate must be between 3 and 16.",
        )

    video_path = _safe_workspace_path(source_rel)
    cap = cv2.VideoCapture(str(video_path))
    if not cap.isOpened():
        raise HTTPException(
            status_code=422,
            detail="Could not open source video.",
        )

    try:
        metadata = _video_metadata(cap)
        width = int(metadata.get("width") or 0)
        height = int(metadata.get("height") or 0)
        duration = float(metadata.get("duration_seconds") or 0.0)

        scan = report.get("scan") or {}
        start = float(scan.get("start_seconds") or 0.0)
        end = float(scan.get("end_seconds") or duration or 0.0)
        if end <= start:
            end = duration

        timestamp = _app_now().strftime("%Y-%m-%d_%H%M%S")
        out_dir = (
            WORKSPACE
            / "review"
            / "branding_temporal_candidate_preview"
            / timestamp
            / video_path.stem
        )
        out_dir.mkdir(parents=True, exist_ok=True)

        diagnostic = report.get("diagnostic_images") or {}
        persistent_mask = None
        persistent_rel = diagnostic.get("persistent_candidate_mask")
        if persistent_rel:
            persistent_path = _safe_workspace_path(persistent_rel)
            if persistent_path.exists():
                persistent_mask = cv2.imread(
                    str(persistent_path),
                    cv2.IMREAD_GRAYSCALE,
                )

        results = []

        for candidate_number, candidate in requested:
            raw_bbox = candidate["bbox"]
            bbox = _expanded_bbox(
                raw_bbox,
                int(req.crop_padding_px),
                width,
                height,
            )

            sample_count = int(req.samples_per_candidate)
            sample_times = np.linspace(
                start,
                end,
                sample_count,
            ).tolist()

            original_crops = []
            enhanced_crops = []
            labels = []
            frame_records = []

            for idx, t in enumerate(sample_times, 1):
                cap.set(
                    cv2.CAP_PROP_POS_MSEC,
                    max(0.0, float(t) * 1000.0),
                )
                ok, frame = cap.read()
                if not ok or frame is None:
                    continue

                crop = frame[
                    bbox["y"]:bbox["y"] + bbox["height"],
                    bbox["x"]:bbox["x"] + bbox["width"],
                ]
                if crop.size == 0:
                    continue

                enhanced = _enhance_review_crop(
                    crop,
                    float(req.clahe_clip_limit),
                )

                base = (
                    out_dir
                    / f"candidate_{candidate_number:02d}"
                    f"_t_{float(t):010.3f}"
                )
                original_path = Path(str(base) + ".crop.jpg")
                enhanced_path = Path(str(base) + ".enhanced.jpg")

                cv2.imwrite(str(original_path), crop)
                cv2.imwrite(str(enhanced_path), enhanced)

                boxed_rel = None
                if req.save_full_frame_boxes:
                    boxed = frame.copy()
                    cv2.rectangle(
                        boxed,
                        (raw_bbox["x"], raw_bbox["y"]),
                        (
                            raw_bbox["x"] + raw_bbox["width"],
                            raw_bbox["y"] + raw_bbox["height"],
                        ),
                        (255, 255, 255),
                        2,
                    )
                    cv2.putText(
                        boxed,
                        f"C{candidate_number}",
                        (
                            raw_bbox["x"],
                            max(20, raw_bbox["y"] - 8),
                        ),
                        cv2.FONT_HERSHEY_SIMPLEX,
                        0.65,
                        (255, 255, 255),
                        2,
                        cv2.LINE_AA,
                    )
                    boxed_path = Path(str(base) + ".boxed.jpg")
                    cv2.imwrite(str(boxed_path), boxed)
                    boxed_rel = boxed_path.relative_to(WORKSPACE).as_posix()

                original_crops.append(crop)
                enhanced_crops.append(enhanced)
                labels.append(f"{float(t):.2f}s")

                frame_records.append(
                    {
                        "time_seconds": round(float(t), 3),
                        "crop": original_path.relative_to(WORKSPACE).as_posix(),
                        "enhanced": enhanced_path.relative_to(WORKSPACE).as_posix(),
                        "boxed": boxed_rel,
                    }
                )

            original_sheet = _contact_sheet(
                original_crops,
                labels,
                cols=4,
            )
            enhanced_sheet = _contact_sheet(
                enhanced_crops,
                labels,
                cols=4,
            )

            original_sheet_rel = None
            enhanced_sheet_rel = None
            mask_crop_rel = None

            if original_sheet is not None:
                p = (
                    out_dir
                    / f"candidate_{candidate_number:02d}_original_contact.jpg"
                )
                cv2.imwrite(str(p), original_sheet)
                original_sheet_rel = p.relative_to(WORKSPACE).as_posix()

            if enhanced_sheet is not None:
                p = (
                    out_dir
                    / f"candidate_{candidate_number:02d}_enhanced_contact.jpg"
                )
                cv2.imwrite(str(p), enhanced_sheet)
                enhanced_sheet_rel = p.relative_to(WORKSPACE).as_posix()

            if (
                persistent_mask is not None
                and persistent_mask.shape[:2] == (height, width)
            ):
                mask_crop = persistent_mask[
                    bbox["y"]:bbox["y"] + bbox["height"],
                    bbox["x"]:bbox["x"] + bbox["width"],
                ]
                p = (
                    out_dir
                    / f"candidate_{candidate_number:02d}_persistent_mask.png"
                )
                cv2.imwrite(str(p), mask_crop)
                mask_crop_rel = p.relative_to(WORKSPACE).as_posix()

            # Ranking hint only, never an automatic approval.
            bin_count = int(candidate.get("active_temporal_bin_count") or 0)
            bins_used = int(scan.get("temporal_bins_used") or 1)
            temporal_ratio = bin_count / float(max(1, bins_used))
            fill = float(candidate.get("persistent_fill_ratio") or 0.0)
            response = float(candidate.get("mean_response") or 0.0)

            sparse_preference = max(0.0, 1.0 - abs(fill - 0.22) / 0.35)
            faint_preference = max(0.0, 1.0 - response / 0.45)
            review_priority = (
                0.55 * temporal_ratio
                + 0.25 * sparse_preference
                + 0.20 * faint_preference
            )

            results.append(
                {
                    "candidate_number": candidate_number,
                    "candidate": candidate,
                    "crop_bbox_with_padding": bbox,
                    "review_priority_score": round(
                        float(review_priority),
                        4,
                    ),
                    "review_priority_is_not_classification": True,
                    "frame_samples": frame_records,
                    "original_contact_sheet": original_sheet_rel,
                    "enhanced_contact_sheet": enhanced_sheet_rel,
                    "persistent_mask_crop": mask_crop_rel,
                }
            )

        result = {
            "ok": True,
            "version": "0.17.0",
            "mode": "branding_temporal_candidate_preview",
            "source": {
                "relative_path": source_rel,
                "temporal_overlay_report_relative_path": (
                    report_path.relative_to(WORKSPACE).as_posix()
                ),
            },
            "video": metadata,
            "summary": {
                "candidate_count_previewed": len(results),
                "samples_per_candidate_requested": int(
                    req.samples_per_candidate
                ),
                "source_video_modified": False,
                "automatic_watermark_approval": False,
                "manual_visual_confirmation_required": True,
            },
            "candidates": results,
            "output_relative_dir": out_dir.relative_to(WORKSPACE).as_posix(),
            "review_note": (
                "A real screen-fixed faint watermark should remain visible at "
                "the same relative crop position across unrelated frames. "
                "The enhanced contact sheet is only for human review and is "
                "not used as detection evidence."
            ),
        }

        report_out = (
            out_dir
            / f"{video_path.stem}.temporal-candidate-preview.json"
        )
        result["report_relative_path"] = (
            report_out.relative_to(WORKSPACE).as_posix()
        )
        report_out.write_text(
            json.dumps(result, ensure_ascii=False, indent=2),
            encoding="utf-8",
        )
        return result
    finally:
        cap.release()




class BrandingDiagonalGridRequest(BaseModel):
    census_report_relative_path: str

    start_seconds: float = 0.0
    end_seconds: Optional[float] = None
    scan_interval_seconds: float = 1.0
    max_frames: int = 160

    # Candidate baseline angles for diagonal tiled watermarks.
    angles_degrees: list[float] = Field(
        default_factory=lambda: [-45, -35, -25, -15, 15, 25, 35, 45]
    )

    # Faint structural response threshold.
    response_percentile: float = 84.0

    # After deskewing a true watermark word should become approximately
    # horizontal and group into a word-like component.
    close_width: int = 41
    close_height: int = 5

    min_component_width: int = 55
    max_component_width: int = 520
    min_component_height: int = 10
    max_component_height: int = 110
    min_aspect_ratio: float = 1.8
    max_aspect_ratio: float = 18.0

    # Cross-time persistence for the same tile position.
    cluster_center_tolerance_px: float = 55.0
    cluster_area_ratio_tolerance: float = 2.2
    min_unique_times_per_tile: int = 4

    # A repeated tiled watermark must occupy several positions across the
    # screen, not one subtitle strip.
    min_persistent_tiles: int = 4
    min_vertical_span_ratio: float = 0.28
    min_horizontal_span_ratio: float = 0.28

    # Existing strong OCR areas are excluded, but not a whole subtitle band.
    exclude_existing_ocr_clusters: bool = True
    exclude_padding_px: int = 16

    # Tile stack preview.
    max_tile_previews: int = 8
    tile_preview_samples: int = 8
    save_debug_images: bool = True


def _rotate_same_canvas(image, angle_degrees):
    h, w = image.shape[:2]
    center = (w / 2.0, h / 2.0)
    matrix = cv2.getRotationMatrix2D(
        center,
        float(angle_degrees),
        1.0,
    )
    rotated = cv2.warpAffine(
        image,
        matrix,
        (w, h),
        flags=cv2.INTER_LINEAR,
        borderMode=cv2.BORDER_CONSTANT,
        borderValue=0,
    )
    return rotated, matrix


def _diag_component_hits(
    frame,
    angle_degrees,
    response_percentile,
    close_width,
    close_height,
    min_component_width,
    max_component_width,
    min_component_height,
    max_component_height,
    min_aspect_ratio,
    max_aspect_ratio,
    exclusion_mask=None,
):
    """
    Detect approximately word-shaped faint structures after deskewing.
    Search is OCR-independent and brand-independent.
    """
    response = _overlay_frame_response(
        frame,
        [15, 31, 61],
    )

    if exclusion_mask is not None:
        response = response * exclusion_mask.astype(np.float32)

    response_u8 = np.clip(response * 255.0, 0, 255).astype(np.uint8)

    # Deskew candidate watermark baseline to horizontal.
    rotated, matrix = _rotate_same_canvas(
        response_u8,
        -float(angle_degrees),
    )

    positive = rotated[rotated > 0]
    if positive.size:
        threshold_value = float(
            np.percentile(
                positive,
                float(response_percentile),
            )
        )
    else:
        threshold_value = 255.0

    _, binary = cv2.threshold(
        rotated,
        threshold_value,
        255,
        cv2.THRESH_BINARY,
    )

    cw = max(3, int(close_width))
    ch = max(3, int(close_height))
    if cw % 2 == 0:
        cw += 1
    if ch % 2 == 0:
        ch += 1

    kernel = cv2.getStructuringElement(
        cv2.MORPH_RECT,
        (cw, ch),
    )
    grouped = cv2.morphologyEx(
        binary,
        cv2.MORPH_CLOSE,
        kernel,
        iterations=1,
    )

    # Remove tiny isolated noise while preserving thin text.
    grouped = cv2.morphologyEx(
        grouped,
        cv2.MORPH_OPEN,
        np.ones((2, 2), dtype=np.uint8),
        iterations=1,
    )

    num_labels, labels, stats, _ = cv2.connectedComponentsWithStats(
        (grouped > 0).astype(np.uint8),
        connectivity=8,
    )

    # Keep glyph-like components long enough to merge them on their deskewed
    # baseline. Counting letters independently can turn one moving word into
    # a false diagonal tiled grid.
    fragments = []
    for label in range(1, num_labels):
        x = int(stats[label, cv2.CC_STAT_LEFT])
        y = int(stats[label, cv2.CC_STAT_TOP])
        w = int(stats[label, cv2.CC_STAT_WIDTH])
        h = int(stats[label, cv2.CC_STAT_HEIGHT])
        pixels = int(stats[label, cv2.CC_STAT_AREA])

        if w < max(3, min(8, int(min_component_width))) or w > int(max_component_width):
            continue
        if h < max(3, min(6, int(min_component_height))) or h > int(max_component_height):
            continue

        aspect = w / float(max(1, h))
        # The complete word, not an individual glyph, must meet the final
        # word-shape criterion.
        if aspect < 0.15 or aspect > float(max_aspect_ratio):
            continue

        fill = pixels / float(max(1, w * h))
        # Text-like grouped structures should be sparse rather than solid bars.
        if fill < 0.03 or fill > 0.80:
            continue

        fragments.append(
            {
                "bbox_rotated": {
                    "x": x,
                    "y": y,
                    "width": w,
                    "height": h,
                },
                "center_rotated": {
                    "x": round(x + w / 2.0, 2),
                    "y": round(y + h / 2.0, 2),
                },
                "area": int(w * h),
                "aspect_ratio": round(aspect, 4),
                "fill_ratio": round(fill, 6),
                "pixel_count": pixels,
            }
        )

    hits = _diag_merge_word_fragments(
        fragments,
        min_component_width=int(min_component_width),
        max_component_width=int(max_component_width),
        min_component_height=int(min_component_height),
        max_component_height=int(max_component_height),
        min_aspect_ratio=float(min_aspect_ratio),
        max_aspect_ratio=float(max_aspect_ratio),
    )
    inverse_matrix = cv2.invertAffineTransform(matrix)
    for hit in hits:
        center = hit.get("center_rotated") or {}
        source_center = np.dot(
            inverse_matrix,
            np.array(
                [
                    float(center.get("x") or 0.0),
                    float(center.get("y") or 0.0),
                    1.0,
                ],
                dtype=np.float32,
            ),
        )
        hit["center_source"] = {
            "x": round(float(source_center[0]), 2),
            "y": round(float(source_center[1]), 2),
        }
        hit["visual_signature"] = _diag_visual_signature(
            grouped,
            hit.get("bbox_rotated") or {},
        )
    return hits, grouped, matrix


def _diag_visual_signature(grouped, bbox):
    """Return a compact, scale-normalized binary shape signature for a word."""
    try:
        x = int(bbox.get("x") or 0)
        y = int(bbox.get("y") or 0)
        width = int(bbox.get("width") or 0)
        height = int(bbox.get("height") or 0)
        crop = grouped[y:y + height, x:x + width]
        if crop.size == 0:
            return None
        normalized = cv2.resize(crop, (24, 12), interpolation=cv2.INTER_AREA)
        binary = (normalized >= 80).astype(np.uint8).reshape(-1)
        return np.packbits(binary).tobytes().hex()
    except Exception:
        return None


def _diag_signature_similarity(left, right):
    """Compare normalized watermark silhouettes without keeping image frames."""
    if not left or not right:
        return 0.0
    try:
        a = bytes.fromhex(str(left))
        b = bytes.fromhex(str(right))
    except ValueError:
        return 0.0
    if not a or len(a) != len(b):
        return 0.0
    differing_bits = sum((byte_a ^ byte_b).bit_count() for byte_a, byte_b in zip(a, b))
    return 1.0 - differing_bits / float(len(a) * 8)


def _diag_merge_word_fragments(
    fragments,
    *,
    min_component_width,
    max_component_width,
    min_component_height,
    max_component_height,
    min_aspect_ratio,
    max_aspect_ratio,
):
    """Merge glyph fragments into one deskewed word candidate.

    An outlined or semi-transparent moving word can be split into its letters
    by connected components.  Joining only baseline-aligned nearby fragments
    before tile counting prevents those letters from masquerading as repeated
    watermarks, while the height-relative gap preserves separately tiled
    words.
    """
    fragments = list(fragments or [])
    if not fragments:
        return []

    parent = list(range(len(fragments)))

    def find(index):
        while parent[index] != index:
            parent[index] = parent[parent[index]]
            index = parent[index]
        return index

    def union(left, right):
        left_root = find(left)
        right_root = find(right)
        if left_root != right_root:
            parent[right_root] = left_root

    for left, left_fragment in enumerate(fragments):
        a = left_fragment["bbox_rotated"]
        a_bottom = float(a["y"] + a["height"])
        a_center_y = float(a["y"]) + float(a["height"]) / 2.0
        for right in range(left + 1, len(fragments)):
            b = fragments[right]["bbox_rotated"]
            b_bottom = float(b["y"] + b["height"])
            b_center_y = float(b["y"]) + float(b["height"]) / 2.0
            vertical_overlap = max(
                0.0,
                min(a_bottom, b_bottom) - max(float(a["y"]), float(b["y"])),
            )
            baseline_aligned = (
                vertical_overlap >= 0.55 * min(float(a["height"]), float(b["height"]))
                or abs(a_center_y - b_center_y) <= 0.40 * max(float(a["height"]), float(b["height"]))
            )
            if not baseline_aligned:
                continue
            horizontal_gap = max(
                float(a["x"]) - float(b["x"] + b["width"]),
                float(b["x"]) - float(a["x"] + a["width"]),
                0.0,
            )
            max_word_gap = max(
                12.0,
                min(120.0, 1.80 * max(float(a["height"]), float(b["height"]))),
            )
            if horizontal_gap <= max_word_gap:
                union(left, right)

    groups = {}
    for index, fragment in enumerate(fragments):
        groups.setdefault(find(index), []).append(fragment)

    hits = []
    for group in groups.values():
        x1 = min(int(item["bbox_rotated"]["x"]) for item in group)
        y1 = min(int(item["bbox_rotated"]["y"]) for item in group)
        x2 = max(int(item["bbox_rotated"]["x"] + item["bbox_rotated"]["width"]) for item in group)
        y2 = max(int(item["bbox_rotated"]["y"] + item["bbox_rotated"]["height"]) for item in group)
        width = x2 - x1
        height = y2 - y1
        if (
            width < int(min_component_width)
            or width > int(max_component_width)
            or height < int(min_component_height)
            or height > int(max_component_height)
        ):
            continue
        aspect = width / float(max(1, height))
        if aspect < float(min_aspect_ratio) or aspect > float(max_aspect_ratio):
            continue
        pixel_count = sum(int(item.get("pixel_count") or 0) for item in group)
        fill = pixel_count / float(max(1, width * height))
        if fill < 0.03 or fill > 0.80:
            continue
        hits.append(
            {
                "bbox_rotated": {"x": x1, "y": y1, "width": width, "height": height},
                "center_rotated": {"x": round(x1 + width / 2.0, 2), "y": round(y1 + height / 2.0, 2)},
                "area": int(width * height),
                "aspect_ratio": round(aspect, 4),
                "fill_ratio": round(fill, 6),
                "word_fragment_count": len(group),
            }
        )
    return hits


def _cluster_diag_hits(hits, center_tolerance, area_ratio_tolerance):
    clusters = []

    for hit in sorted(
        hits,
        key=lambda x: float(x["time_seconds"]),
    ):
        center = (
            float(hit["center_rotated"]["x"]),
            float(hit["center_rotated"]["y"]),
        )
        area = float(hit["area"])

        best_idx = None
        best_dist = None

        for idx, cluster in enumerate(clusters):
            dist = _distance(center, cluster["center"])
            med_area = max(1.0, float(cluster["median_area"]))
            area_ratio = max(
                area / med_area,
                med_area / area,
            )

            if (
                dist <= float(center_tolerance)
                and area_ratio <= float(area_ratio_tolerance)
            ):
                if best_dist is None or dist < best_dist:
                    best_idx = idx
                    best_dist = dist

        if best_idx is None:
            clusters.append(
                {
                    "hits": [hit],
                    "center": center,
                    "median_area": area,
                }
            )
        else:
            cluster = clusters[best_idx]
            cluster["hits"].append(hit)
            centers = [
                (
                    float(h["center_rotated"]["x"]),
                    float(h["center_rotated"]["y"]),
                )
                for h in cluster["hits"]
            ]
            cluster["center"] = (
                _median([c[0] for c in centers]),
                _median([c[1] for c in centers]),
            )
            cluster["median_area"] = _median(
                [float(h["area"]) for h in cluster["hits"]]
            )

    return clusters


def _diag_persistent_cluster_report(cluster_id, cluster, min_times):
    hits = cluster["hits"]
    times = sorted(
        {
            round(float(h["time_seconds"]), 3)
            for h in hits
        }
    )

    boxes = [h["bbox_rotated"] for h in hits]
    centers = [
        (
            float(h["center_rotated"]["x"]),
            float(h["center_rotated"]["y"]),
        )
        for h in hits
    ]

    median_center = (
        _median([c[0] for c in centers]),
        _median([c[1] for c in centers]),
    )
    source_centers = [
        (
            float((h.get("center_source") or h.get("center_rotated") or {}).get("x") or 0.0),
            float((h.get("center_source") or h.get("center_rotated") or {}).get("y") or 0.0),
        )
        for h in hits
    ]
    median_source_center = (
        _median([c[0] for c in source_centers]),
        _median([c[1] for c in source_centers]),
    )
    signatures = [h.get("visual_signature") for h in hits if h.get("visual_signature")]
    # Use the medoid rather than a literal byte majority: anti-aliased text
    # may differ by a few pixels between sampled frames.
    visual_signature = None
    if signatures:
        visual_signature = max(
            signatures,
            key=lambda candidate: _median(
                [_diag_signature_similarity(candidate, other) for other in signatures]
            ),
        )

    median_w = int(
        round(_median([float(b["width"]) for b in boxes]))
    )
    median_h = int(
        round(_median([float(b["height"]) for b in boxes]))
    )

    stable_bbox = {
        "x": max(
            0,
            int(round(median_center[0] - median_w / 2.0)),
        ),
        "y": max(
            0,
            int(round(median_center[1] - median_h / 2.0)),
        ),
        "width": max(1, median_w),
        "height": max(1, median_h),
    }

    return {
        "tile_cluster_id": int(cluster_id),
        "unique_time_count": len(times),
        "persistent": len(times) >= int(min_times),
        "time_min_seconds": min(times) if times else None,
        "time_max_seconds": max(times) if times else None,
        "median_center_rotated": {
            "x": round(median_center[0], 2),
            "y": round(median_center[1], 2),
        },
        "center_source": {
            "x": round(median_source_center[0], 2),
            "y": round(median_source_center[1], 2),
        },
        "visual_signature": visual_signature,
        "stable_bbox_rotated": stable_bbox,
        "median_area": round(
            _median([float(h["area"]) for h in hits]),
            2,
        ),
        "median_aspect_ratio": round(
            _median(
                [float(h["aspect_ratio"]) for h in hits]
            ),
            4,
        ),
        "median_fill_ratio": round(
            _median(
                [float(h["fill_ratio"]) for h in hits]
            ),
            6,
        ),
        "sample_times": times[:100],
    }


def _diag_grid_score(
    persistent_tiles,
    width,
    height,
    min_tiles,
    min_vertical_span_ratio,
    min_horizontal_span_ratio,
):
    if not persistent_tiles:
        return {
            "qualifies_as_repeated_grid": False,
            "persistent_tile_count": 0,
            "vertical_span_ratio": 0.0,
            "horizontal_span_ratio": 0.0,
            "repeated_shape": False,
            "aspect_consistency": False,
            "size_consistency": False,
            "quadrant_spread": False,
            "lattice_consistency": False,
            "grid_score": 0.0,
        }

    centers = [
        (
            float(t["median_center_rotated"]["x"]),
            float(t["median_center_rotated"]["y"]),
        )
        for t in persistent_tiles
    ]

    xs = [c[0] for c in centers]
    ys = [c[1] for c in centers]

    # A tiled watermark repeats the same mark.  Natural scene edges and
    # subtitles can also produce several diagonal components, but their
    # component geometry varies substantially.  Reject those heterogeneous
    # collections before applying the spatial-span test.
    aspects = [
        float(t.get("median_aspect_ratio") or 0.0)
        for t in persistent_tiles
        if float(t.get("median_aspect_ratio") or 0.0) > 0.0
    ]
    widths = [
        float((t.get("stable_bbox_rotated") or {}).get("width") or 0.0)
        for t in persistent_tiles
    ]
    heights = [
        float((t.get("stable_bbox_rotated") or {}).get("height") or 0.0)
        for t in persistent_tiles
    ]

    def _median_abs_deviation(values):
        if not values:
            return float("inf")
        center = _median(values)
        return _median([abs(float(value) - center) for value in values])

    median_aspect = _median(aspects) if aspects else 0.0
    median_width = _median(widths) if widths else 0.0
    median_height = _median(heights) if heights else 0.0
    aspect_consistency = (
        bool(aspects)
        and _median_abs_deviation(aspects) / max(1.0, median_aspect) <= 0.28
    )
    size_consistency = (
        bool(widths)
        and _median_abs_deviation(widths) / max(1.0, median_width) <= 0.45
        and _median_abs_deviation(heights) / max(1.0, median_height) <= 0.45
    )
    # Edge-clipped tiles can legitimately have different heights/widths while
    # retaining the same text baseline. Aspect consistency plus lattice spacing
    # is the reliable signal; require at least one shape-consistency measure.
    repeated_shape = bool(aspect_consistency or size_consistency)
    occupied_quadrants = {
        (
            int(float(x) >= float(width) * 0.5),
            int(float(y) >= float(height) * 0.5),
        )
        for x, y in centers
    }
    quadrant_spread = len(occupied_quadrants) >= 3

    def _gap_repeatability(values):
        ordered = sorted(float(value) for value in values)
        gaps = [
            ordered[index + 1] - ordered[index]
            for index in range(len(ordered) - 1)
            if ordered[index + 1] - ordered[index] > 1.0
        ]
        if len(gaps) < 2:
            return False
        reference = _median(gaps)
        return sum(
            1
            for gap in gaps
            if abs(gap - reference) / max(1.0, reference) <= 0.30
        ) >= 2

    lattice_consistency = bool(
        _gap_repeatability(xs)
        and _gap_repeatability(ys)
    )

    signatures = [t.get("visual_signature") for t in persistent_tiles if t.get("visual_signature")]
    visual_consistency = False
    if len(signatures) >= 2:
        pair_scores = []
        anchor = signatures[0]
        for signature in signatures[1:]:
            pair_scores.append(_diag_signature_similarity(anchor, signature))
        visual_consistency = bool(
            pair_scores
            and _median(pair_scores) >= 0.72
            and sum(score >= 0.62 for score in pair_scores) >= max(2, int(math.ceil(len(pair_scores) * 0.70)))
        )

    x_span = (
        (max(xs) - min(xs)) / float(max(1, width))
        if len(xs) >= 2 else 0.0
    )
    y_span = (
        (max(ys) - min(ys)) / float(max(1, height))
        if len(ys) >= 2 else 0.0
    )

    tile_factor = min(
        1.0,
        len(persistent_tiles) / float(max(1, int(min_tiles))),
    )
    spatial_factor = min(
        1.0,
        x_span / float(max(1e-6, min_horizontal_span_ratio)),
    ) * min(
        1.0,
        y_span / float(max(1e-6, min_vertical_span_ratio)),
    )

    score = 0.55 * tile_factor + 0.45 * spatial_factor

    qualifies = (
        len(persistent_tiles) >= int(min_tiles)
        and x_span >= float(min_horizontal_span_ratio)
        and y_span >= float(min_vertical_span_ratio)
        and repeated_shape
        and quadrant_spread
        and lattice_consistency
        and visual_consistency
    )

    return {
        "qualifies_as_repeated_grid": bool(qualifies),
        "persistent_tile_count": len(persistent_tiles),
        "vertical_span_ratio": round(y_span, 4),
        "horizontal_span_ratio": round(x_span, 4),
        "repeated_shape": repeated_shape,
        "aspect_consistency": bool(aspect_consistency),
        "size_consistency": bool(size_consistency),
        "quadrant_spread": bool(quadrant_spread),
        "lattice_consistency": bool(lattice_consistency),
        "visual_consistency": bool(visual_consistency),
        "visual_signature_count": len(signatures),
        "grid_score": round(float(score), 4),
    }


def _diag_tile_stack(
    video_path,
    angle_degrees,
    tile_bbox_rotated,
    sample_times,
):
    cap = cv2.VideoCapture(str(video_path))
    if not cap.isOpened():
        return None, [], None

    enhanced_samples = []
    raw_samples = []

    try:
        for t in sample_times:
            cap.set(
                cv2.CAP_PROP_POS_MSEC,
                float(t) * 1000.0,
            )
            ok, frame = cap.read()
            if not ok or frame is None:
                continue

            # Rotate the original frame so the diagonal watermark baseline
            # becomes horizontal, then crop the persistent tile.
            rotated, _ = _rotate_same_canvas(
                frame,
                -float(angle_degrees),
            )

            h, w = rotated.shape[:2]
            b = _clip_bbox(
                tile_bbox_rotated,
                w,
                h,
            )
            crop = rotated[
                b["y"]:b["y"] + b["height"],
                b["x"]:b["x"] + b["width"],
            ]
            if crop.size == 0:
                continue

            raw_samples.append(crop)

            gray = cv2.cvtColor(
                crop,
                cv2.COLOR_BGR2GRAY,
            )
            clahe = cv2.createCLAHE(
                clipLimit=2.5,
                tileGridSize=(8, 8),
            )
            gray = clahe.apply(gray)

            blur = cv2.GaussianBlur(
                gray,
                (0, 0),
                sigmaX=2.5,
            )
            high = cv2.addWeighted(
                gray,
                1.8,
                blur,
                -0.8,
                0,
            )
            high = cv2.normalize(
                high,
                None,
                0,
                255,
                cv2.NORM_MINMAX,
            )
            enhanced_samples.append(
                high.astype(np.float32)
            )

        if not enhanced_samples:
            return None, raw_samples, None

        # Normalize sizes to the first valid crop.
        target_h, target_w = enhanced_samples[0].shape[:2]
        resized = []
        for img in enhanced_samples:
            if img.shape[:2] != (target_h, target_w):
                img = cv2.resize(
                    img,
                    (target_w, target_h),
                    interpolation=cv2.INTER_CUBIC,
                )
            resized.append(img)

        # Median rejects changing scene content while retaining a fixed
        # screen-space overlay response.
        median_stack = np.median(
            np.stack(resized, axis=0),
            axis=0,
        )
        median_stack = cv2.normalize(
            median_stack,
            None,
            0,
            255,
            cv2.NORM_MINMAX,
        ).astype(np.uint8)

        median_bgr = cv2.cvtColor(
            median_stack,
            cv2.COLOR_GRAY2BGR,
        )

        return median_bgr, raw_samples, median_stack
    finally:
        cap.release()


def _diagonal_grid_census_sync(req: BrandingDiagonalGridRequest):
    report_path = _safe_workspace_path(
        req.census_report_relative_path
    )
    try:
        report = json.loads(
            report_path.read_text(encoding="utf-8")
        )
    except Exception as exc:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "diagonal_grid_census",
                "error": "invalid_census_report",
                "message": str(exc)[:500],
            },
        )

    source_rel = (
        (report.get("source") or {})
        .get("relative_path", "")
        .strip()
    )
    if not source_rel:
        raise HTTPException(
            status_code=422,
            detail="Census report has no source.relative_path.",
        )

    if not 0.25 <= float(req.scan_interval_seconds) <= 10:
        raise HTTPException(
            status_code=422,
            detail="scan_interval_seconds must be between 0.25 and 10.",
        )
    if not 1 <= int(req.max_frames) <= 1000:
        raise HTTPException(
            status_code=422,
            detail="max_frames must be between 1 and 1000.",
        )
    if not 60 <= float(req.response_percentile) <= 99.5:
        raise HTTPException(
            status_code=422,
            detail="response_percentile must be between 60 and 99.5.",
        )

    video_path = _safe_workspace_path(source_rel)
    cap = cv2.VideoCapture(str(video_path))
    if not cap.isOpened():
        raise HTTPException(
            status_code=422,
            detail="Could not open source video.",
        )

    try:
        metadata = _video_metadata(cap)
        width = int(metadata.get("width") or 0)
        height = int(metadata.get("height") or 0)
        duration = float(
            metadata.get("duration_seconds") or 0.0
        )

        start = max(
            0.0,
            float(req.start_seconds or 0.0),
        )
        if req.end_seconds is None:
            end = duration if duration > 0 else start + 60.0
        else:
            end = max(start, float(req.end_seconds))
            if duration > 0:
                end = min(end, duration)

        span = max(0.001, end - start)
        interval = max(
            float(req.scan_interval_seconds),
            span / float(max(1, int(req.max_frames))),
        )

        if req.exclude_existing_ocr_clusters:
            exclusion_mask, exclusion_boxes = _make_exclusion_mask(
                report,
                width,
                height,
                int(req.exclude_padding_px),
            )
        else:
            exclusion_mask = np.ones(
                (height, width),
                dtype=np.uint8,
            )
            exclusion_boxes = []

        angles = [
            float(a)
            for a in req.angles_degrees
            if abs(float(a)) >= 5.0
        ]
        if not angles:
            raise HTTPException(
                status_code=422,
                detail="angles_degrees must contain at least one non-horizontal angle.",
            )

        angle_hits = {
            angle: []
            for angle in angles
        }

        frames_scanned = 0
        sampled_times = []
        representative_frame = None
        representative_time = None

        t = start
        while (
            t <= end + 1e-9
            and frames_scanned < int(req.max_frames)
        ):
            cap.set(
                cv2.CAP_PROP_POS_MSEC,
                t * 1000.0,
            )
            ok, frame = cap.read()
            if not ok or frame is None:
                t += interval
                continue

            if representative_frame is None:
                representative_frame = frame.copy()
                representative_time = float(t)

            sampled_times.append(round(float(t), 3))
            frames_scanned += 1

            for angle in angles:
                hits, _, _ = _diag_component_hits(
                    frame,
                    angle,
                    req.response_percentile,
                    req.close_width,
                    req.close_height,
                    req.min_component_width,
                    req.max_component_width,
                    req.min_component_height,
                    req.max_component_height,
                    req.min_aspect_ratio,
                    req.max_aspect_ratio,
                    exclusion_mask,
                )

                for hit in hits:
                    hit["time_seconds"] = round(
                        float(t),
                        3,
                    )
                    hit["angle_degrees"] = angle
                    angle_hits[angle].append(hit)

            t += interval

        timestamp = _app_now().strftime(
            "%Y-%m-%d_%H%M%S"
        )
        out_dir = (
            WORKSPACE
            / "review"
            / "branding_diagonal_grid_census"
            / timestamp
            / video_path.stem
        )
        out_dir.mkdir(
            parents=True,
            exist_ok=True,
        )

        angle_reports = []

        for angle in angles:
            raw_hits = angle_hits[angle]
            raw_clusters = _cluster_diag_hits(
                raw_hits,
                float(req.cluster_center_tolerance_px),
                float(req.cluster_area_ratio_tolerance),
            )

            tile_reports = []
            for idx, cluster in enumerate(
                raw_clusters,
                1,
            ):
                tile_reports.append(
                    _diag_persistent_cluster_report(
                        idx,
                        cluster,
                        int(req.min_unique_times_per_tile),
                    )
                )

            persistent = [
                tile
                for tile in tile_reports
                if tile["persistent"]
            ]

            grid = _diag_grid_score(
                persistent,
                width,
                height,
                int(req.min_persistent_tiles),
                float(req.min_vertical_span_ratio),
                float(req.min_horizontal_span_ratio),
            )

            # Prefer angles with a repeated-grid spatial pattern, then
            # persistent tile count.
            angle_reports.append(
                {
                    "angle_degrees": angle,
                    "raw_component_hit_count": len(raw_hits),
                    "raw_tile_cluster_count": len(raw_clusters),
                    "persistent_tiles": persistent,
                    **grid,
                }
            )

        angle_reports.sort(
            key=lambda x: (
                1 if x["qualifies_as_repeated_grid"] else 0,
                float(x["grid_score"]),
                int(x["persistent_tile_count"]),
            ),
            reverse=True,
        )

        best = angle_reports[0] if angle_reports else None

        debug_paths = {}
        tile_previews = []

        if best and req.save_debug_images:
            best_angle = float(best["angle_degrees"])

            if representative_frame is None:
                representative_frame = np.zeros(
                    (height, width, 3),
                    dtype=np.uint8,
                )
                representative_time = start

            rotated_frame, _ = _rotate_same_canvas(
                representative_frame,
                -best_angle,
            )

            debug_rotated = rotated_frame.copy()

            # Draw only persistent tiles on a deskewed representative frame.
            for tile in best["persistent_tiles"]:
                b = tile["stable_bbox_rotated"]
                cv2.rectangle(
                    debug_rotated,
                    (b["x"], b["y"]),
                    (
                        b["x"] + b["width"],
                        b["y"] + b["height"],
                    ),
                    (255, 255, 255),
                    2,
                )
                cv2.putText(
                    debug_rotated,
                    f"T{tile['tile_cluster_id']}",
                    (
                        b["x"],
                        max(18, b["y"] - 5),
                    ),
                    cv2.FONT_HERSHEY_SIMPLEX,
                    0.45,
                    (255, 255, 255),
                    1,
                    cv2.LINE_AA,
                )

            deskew_path = (
                out_dir
                / "01_best_angle_deskew_persistent_tiles.jpg"
            )
            cv2.imwrite(
                str(deskew_path),
                debug_rotated,
            )
            debug_paths["best_angle_deskew_persistent_tiles"] = (
                deskew_path.relative_to(WORKSPACE).as_posix()
            )

            # Save an original frame with known OCR exclusions for context.
            context = representative_frame.copy()
            for ex in exclusion_boxes:
                cv2.rectangle(
                    context,
                    (ex["x"], ex["y"]),
                    (
                        ex["x"] + ex["width"],
                        ex["y"] + ex["height"],
                    ),
                    (96, 96, 96),
                    1,
                )
            context_path = out_dir / "02_original_context.jpg"
            cv2.imwrite(str(context_path), context)
            debug_paths["original_context"] = (
                context_path.relative_to(WORKSPACE).as_posix()
            )

            preview_tiles = best["persistent_tiles"][
                : int(req.max_tile_previews)
            ]

            for tile in preview_tiles:
                times = tile["sample_times"]
                if len(times) > int(req.tile_preview_samples):
                    indexes = np.linspace(
                        0,
                        len(times) - 1,
                        int(req.tile_preview_samples),
                    ).round().astype(int)
                    times = [
                        times[int(i)]
                        for i in indexes
                    ]

                stack_bgr, raw_crops, stack_gray = _diag_tile_stack(
                    video_path,
                    best_angle,
                    tile["stable_bbox_rotated"],
                    times,
                )
                if stack_bgr is None:
                    continue

                tile_id = int(tile["tile_cluster_id"])
                stack_path = (
                    out_dir
                    / f"tile_{tile_id:02d}_temporal_median.png"
                )
                cv2.imwrite(
                    str(stack_path),
                    stack_bgr,
                )

                raw_sheet = _contact_sheet(
                    raw_crops,
                    [
                        f"{float(t):.2f}s"
                        for t in times[: len(raw_crops)]
                    ],
                    cols=4,
                )
                sheet_rel = None
                if raw_sheet is not None:
                    sheet_path = (
                        out_dir
                        / f"tile_{tile_id:02d}_raw_contact.jpg"
                    )
                    cv2.imwrite(
                        str(sheet_path),
                        raw_sheet,
                    )
                    sheet_rel = (
                        sheet_path
                        .relative_to(WORKSPACE)
                        .as_posix()
                    )

                # OCR is verification-only here. Search and grid detection do
                # not depend on OCR.
                ocr_observations = []
                if stack_bgr is not None:
                    try:
                        words = _tesseract_words(
                            stack_bgr,
                            "eng",
                            0.0,
                            3.0,
                        )
                        ocr_observations = [
                            {
                                "text": w.get("text"),
                                "confidence": w.get("confidence"),
                                "bbox": w.get("bbox"),
                            }
                            for w in words
                            if str(w.get("text") or "").strip()
                        ][:30]
                    except Exception:
                        ocr_observations = []

                tile_previews.append(
                    {
                        "tile_cluster_id": tile_id,
                        "stable_bbox_rotated": tile["stable_bbox_rotated"],
                        "sample_times": times,
                        "temporal_median": (
                            stack_path
                            .relative_to(WORKSPACE)
                            .as_posix()
                        ),
                        "raw_contact_sheet": sheet_rel,
                        "verification_ocr": ocr_observations,
                    }
                )

        result = {
            "ok": True,
            "version": "0.17.0",
            "mode": "branding_diagonal_grid_census",
            "source": {
                "relative_path": source_rel,
                "census_report_relative_path": (
                    report_path.relative_to(WORKSPACE).as_posix()
                ),
            },
            "video": metadata,
            "scan": {
                "start_seconds": round(start, 3),
                "end_seconds": round(end, 3),
                "requested_interval_seconds": float(
                    req.scan_interval_seconds
                ),
                "effective_interval_seconds": round(
                    interval,
                    4,
                ),
                "frames_scanned": frames_scanned,
                "sampled_times": sampled_times[:200],
            },
            "detector": {
                "ocr_used_for_detection": False,
                "brand_template_used": False,
                "target_structure": (
                    "multiple persistent word-like tiles sharing one "
                    "diagonal baseline angle and spanning multiple screen rows/columns"
                ),
                "angles_degrees": angles,
                "response_percentile": float(
                    req.response_percentile
                ),
                "exclude_existing_ocr_clusters": bool(
                    req.exclude_existing_ocr_clusters
                ),
                "excluded_region_count": len(exclusion_boxes),
            },
            "summary": {
                "best_angle_degrees": (
                    best["angle_degrees"]
                    if best else None
                ),
                "best_angle_qualifies_as_repeated_grid": (
                    best["qualifies_as_repeated_grid"]
                    if best else False
                ),
                "best_angle_persistent_tile_count": (
                    best["persistent_tile_count"]
                    if best else 0
                ),
                "best_angle_vertical_span_ratio": (
                    best["vertical_span_ratio"]
                    if best else 0.0
                ),
                "best_angle_horizontal_span_ratio": (
                    best["horizontal_span_ratio"]
                    if best else 0.0
                ),
                "source_video_modified": False,
                "manual_visual_confirmation_required": True,
                "v0_9_8_fixed_region_strategy_deprecated_for_diagonal_tiled_watermark": True,
            },
            "angle_reports": angle_reports,
            "tile_previews": tile_previews,
            "diagnostic_images": debug_paths,
            "interpretation": {
                "subtitle_rejection": (
                    "A subtitle band may persist over time, but it normally "
                    "does not create several same-angle, similarly sized tile "
                    "positions spanning both multiple rows and columns."
                ),
                "acceptance": (
                    "Accept only if the best deskew angle exposes multiple "
                    "repeating tiles and the temporal-median tile previews "
                    "visually reveal the diagonal ReelShort wordmark."
                ),
                "verification_ocr": (
                    "OCR on temporal-median tiles is diagnostic only; it is "
                    "not used to discover or score the repeated grid."
                ),
            },
        }

        report_out = (
            out_dir
            / f"{video_path.stem}.diagonal-grid-census.json"
        )
        result["report_relative_path"] = (
            report_out.relative_to(WORKSPACE).as_posix()
        )
        result["output_relative_dir"] = (
            out_dir.relative_to(WORKSPACE).as_posix()
        )
        report_out.write_text(
            json.dumps(
                result,
                ensure_ascii=False,
                indent=2,
            ),
            encoding="utf-8",
        )
        return result
    finally:
        cap.release()




class BrandingManualSeedGridRequest(BaseModel):
    relative_path: str

    # Manual seed in normalized source-frame coordinates.
    # This keeps the calibration independent of screenshot display size.
    seed_x: float
    seed_y: float
    seed_width: float
    seed_height: float

    start_seconds: float = 0.0
    end_seconds: Optional[float] = None
    scan_interval_seconds: float = 0.75
    max_frames: int = 220

    # Persistent overlay-map construction.
    response_kernel_widths: list[int] = Field(
        default_factory=lambda: [15, 31, 61]
    )
    response_floor_percentile: float = 55.0

    # Seed matching on the temporal persistence map.
    match_threshold: float = 0.42
    top_k_matches: int = 40
    nms_iou_threshold: float = 0.20
    search_scales: list[float] = Field(
        default_factory=lambda: [0.90, 0.95, 1.0, 1.05, 1.10]
    )

    # Grid inference.
    min_grid_matches: int = 4
    max_neighbor_distance_px: float = 520.0
    vector_angle_tolerance_degrees: float = 12.0
    vector_length_tolerance_ratio: float = 0.22

    # Mask preview.
    seed_mask_percentile: float = 68.0
    seed_mask_dilate_iterations: int = 1
    make_mask_preview: bool = True


def _normalized_bbox_to_pixels(x, y, width, height, frame_width, frame_height):
    vals = [float(x), float(y), float(width), float(height)]
    if any(v < 0.0 or v > 1.0 for v in vals):
        raise HTTPException(
            status_code=422,
            detail="Normalized seed coordinates must be between 0 and 1.",
        )
    if float(width) <= 0 or float(height) <= 0:
        raise HTTPException(
            status_code=422,
            detail="seed_width and seed_height must be positive.",
        )

    px = int(round(float(x) * frame_width))
    py = int(round(float(y) * frame_height))
    pw = max(1, int(round(float(width) * frame_width)))
    ph = max(1, int(round(float(height) * frame_height)))

    return _clip_bbox(
        {
            "x": px,
            "y": py,
            "width": pw,
            "height": ph,
        },
        frame_width,
        frame_height,
    )


def _persistent_overlay_map(
    video_path,
    start,
    end,
    interval,
    max_frames,
    kernel_widths,
):
    cap = cv2.VideoCapture(str(video_path))
    if not cap.isOpened():
        raise HTTPException(status_code=422, detail="Could not open source video.")

    try:
        metadata = _video_metadata(cap)
        width = int(metadata.get("width") or 0)
        height = int(metadata.get("height") or 0)

        soft_sum = np.zeros((height, width), dtype=np.float32)
        hard_count = np.zeros((height, width), dtype=np.uint16)
        frame_count = 0
        sampled_times = []

        t = float(start)
        while t <= float(end) + 1e-9 and frame_count < int(max_frames):
            cap.set(cv2.CAP_PROP_POS_MSEC, t * 1000.0)
            ok, frame = cap.read()
            if not ok or frame is None:
                t += interval
                continue

            response = _overlay_frame_response(
                frame,
                kernel_widths,
            )

            positive = response[response > 0]
            if positive.size:
                thr = float(np.percentile(positive, 88.0))
            else:
                thr = 1.0

            soft_sum += response
            hard_count += (response >= thr).astype(np.uint16)

            sampled_times.append(round(float(t), 3))
            frame_count += 1
            t += interval

        if frame_count == 0:
            raise HTTPException(status_code=422, detail="No frames were sampled.")

        mean_soft = soft_sum / float(frame_count)
        hard_ratio = hard_count.astype(np.float32) / float(frame_count)

        # Persistent overlay structure should have both repeated structural
        # energy and repeated high-response occupancy.
        persistence = mean_soft * (0.35 + 0.65 * hard_ratio)
        persistence = cv2.GaussianBlur(persistence, (3, 3), 0)

        return {
            "metadata": metadata,
            "mean_soft": mean_soft,
            "hard_ratio": hard_ratio,
            "persistence": persistence,
            "frame_count": frame_count,
            "sampled_times": sampled_times,
        }
    finally:
        cap.release()


def _seed_template_from_persistence(persistence, seed_bbox, floor_percentile):
    b = seed_bbox
    crop = persistence[
        b["y"]:b["y"] + b["height"],
        b["x"]:b["x"] + b["width"],
    ].copy()

    if crop.size == 0:
        raise HTTPException(status_code=422, detail="Seed crop is empty.")

    positive = crop[crop > 0]
    if positive.size:
        floor = float(np.percentile(positive, float(floor_percentile)))
    else:
        floor = 0.0

    crop = np.where(crop >= floor, crop, 0.0).astype(np.float32)
    crop = _normalize_u8(crop)

    # Remove a thin border because manual boxes naturally include some margin.
    margin_x = max(1, int(round(crop.shape[1] * 0.03)))
    margin_y = max(1, int(round(crop.shape[0] * 0.05)))
    crop[:margin_y, :] = 0
    crop[-margin_y:, :] = 0
    crop[:, :margin_x] = 0
    crop[:, -margin_x:] = 0

    return crop


def _multi_scale_seed_matches(
    persistence_u8,
    seed_template,
    scales,
    threshold,
    top_k,
    nms_iou,
    seed_bbox,
):
    fh, fw = persistence_u8.shape[:2]
    candidates = []

    for scale in scales:
        scale = float(scale)
        if scale <= 0:
            continue

        tw = max(12, int(round(seed_template.shape[1] * scale)))
        th = max(8, int(round(seed_template.shape[0] * scale)))

        if tw >= fw or th >= fh:
            continue

        tmpl = cv2.resize(
            seed_template,
            (tw, th),
            interpolation=cv2.INTER_CUBIC if scale >= 1.0 else cv2.INTER_AREA,
        )

        if int(np.count_nonzero(tmpl)) < max(20, int(tw * th * 0.02)):
            continue

        response = cv2.matchTemplate(
            persistence_u8,
            tmpl,
            cv2.TM_CCOEFF_NORMED,
        )

        local = response.copy()
        picks = 0
        while picks < max(6, int(top_k)):
            _, max_val, _, max_loc = cv2.minMaxLoc(local)
            score = float(max_val)
            if not np.isfinite(score) or score < float(threshold):
                break

            bbox = {
                "x": int(max_loc[0]),
                "y": int(max_loc[1]),
                "width": int(tw),
                "height": int(th),
            }

            candidates.append(
                {
                    "score": round(score, 6),
                    "scale": round(scale, 4),
                    "bbox": bbox,
                    "center": {
                        "x": round(bbox["x"] + bbox["width"] / 2.0, 2),
                        "y": round(bbox["y"] + bbox["height"] / 2.0, 2),
                    },
                }
            )

            sx = max(1, int(round(tw * 0.65)))
            sy = max(1, int(round(th * 0.65)))
            x1 = max(0, max_loc[0] - sx)
            y1 = max(0, max_loc[1] - sy)
            x2 = min(local.shape[1], max_loc[0] + sx)
            y2 = min(local.shape[0], max_loc[1] + sy)
            local[y1:y2, x1:x2] = -1.0
            picks += 1

    # Ensure the manually seeded tile is always represented.
    seed_center = _bbox_center(seed_bbox)
    candidates.append(
        {
            "score": 1.0,
            "scale": 1.0,
            "bbox": dict(seed_bbox),
            "center": {
                "x": round(seed_center[0], 2),
                "y": round(seed_center[1], 2),
            },
            "manual_seed": True,
        }
    )

    ordered = sorted(
        candidates,
        key=lambda c: float(c["score"]),
        reverse=True,
    )

    kept = []
    for cand in ordered:
        if any(
            _bbox_iou(cand["bbox"], old["bbox"]) >= float(nms_iou)
            for old in kept
        ):
            continue
        kept.append(cand)
        if len(kept) >= int(top_k):
            break

    for idx, cand in enumerate(kept, 1):
        cand["match_id"] = idx
        cand["manual_seed"] = bool(cand.get("manual_seed", False))

    return kept


def _vector_angle_deg(dx, dy):
    return math.degrees(math.atan2(float(dy), float(dx)))


def _canonical_vector(dx, dy):
    dx = float(dx)
    dy = float(dy)
    if abs(dx) < 1e-9 and abs(dy) < 1e-9:
        return (0.0, 0.0)

    # Treat v and -v as the same lattice direction.
    if dx < 0 or (abs(dx) < 1e-9 and dy < 0):
        dx = -dx
        dy = -dy
    return (dx, dy)


def _cluster_lattice_vectors(matches, max_distance, angle_tol, length_tol_ratio):
    centers = [
        (
            float(m["center"]["x"]),
            float(m["center"]["y"]),
        )
        for m in matches
    ]

    vectors = []
    for i in range(len(centers)):
        for j in range(i + 1, len(centers)):
            dx = centers[j][0] - centers[i][0]
            dy = centers[j][1] - centers[i][1]
            dist = math.hypot(dx, dy)
            if dist < 20.0 or dist > float(max_distance):
                continue

            dx, dy = _canonical_vector(dx, dy)
            angle = _vector_angle_deg(dx, dy)
            vectors.append(
                {
                    "dx": dx,
                    "dy": dy,
                    "length": dist,
                    "angle": angle,
                }
            )

    clusters = []
    for vec in sorted(vectors, key=lambda v: v["length"]):
        best_idx = None
        best_score = None

        for idx, cluster in enumerate(clusters):
            a_diff = abs(float(vec["angle"]) - float(cluster["angle"]))
            a_diff = min(a_diff, 180.0 - a_diff)
            l_ref = max(1.0, float(cluster["length"]))
            l_diff_ratio = abs(float(vec["length"]) - l_ref) / l_ref

            if (
                a_diff <= float(angle_tol)
                and l_diff_ratio <= float(length_tol_ratio)
            ):
                score = a_diff + 20.0 * l_diff_ratio
                if best_score is None or score < best_score:
                    best_idx = idx
                    best_score = score

        if best_idx is None:
            clusters.append(
                {
                    "vectors": [vec],
                    "angle": vec["angle"],
                    "length": vec["length"],
                }
            )
        else:
            cluster = clusters[best_idx]
            cluster["vectors"].append(vec)
            cluster["angle"] = _median(
                [float(v["angle"]) for v in cluster["vectors"]]
            )
            cluster["length"] = _median(
                [float(v["length"]) for v in cluster["vectors"]]
            )

    reports = []
    for idx, cluster in enumerate(clusters, 1):
        vecs = cluster["vectors"]
        med_dx = _median([float(v["dx"]) for v in vecs])
        med_dy = _median([float(v["dy"]) for v in vecs])
        reports.append(
            {
                "vector_cluster_id": idx,
                "support": len(vecs),
                "dx": round(med_dx, 2),
                "dy": round(med_dy, 2),
                "length": round(math.hypot(med_dx, med_dy), 2),
                "angle_degrees": round(_vector_angle_deg(med_dx, med_dy), 2),
            }
        )

    reports.sort(
        key=lambda x: (
            int(x["support"]),
            -float(x["length"]),
        ),
        reverse=True,
    )
    return reports


def _choose_lattice_basis(vector_reports):
    if not vector_reports:
        return []

    first = vector_reports[0]
    basis = [first]

    for candidate in vector_reports[1:]:
        a1 = float(first["angle_degrees"])
        a2 = float(candidate["angle_degrees"])
        diff = abs(a1 - a2)
        diff = min(diff, 180.0 - diff)

        # Lattice directions should not be nearly collinear.
        if 25.0 <= diff <= 155.0:
            basis.append(candidate)
            break

    return basis[:2]


def _predict_grid_from_basis(seed_center, basis, width, height):
    if len(basis) < 2:
        return []

    v1 = np.array(
        [float(basis[0]["dx"]), float(basis[0]["dy"])],
        dtype=np.float64,
    )
    v2 = np.array(
        [float(basis[1]["dx"]), float(basis[1]["dy"])],
        dtype=np.float64,
    )
    origin = np.array(
        [float(seed_center[0]), float(seed_center[1])],
        dtype=np.float64,
    )

    points = []
    seen = set()

    # More than enough for a 720x1280 frame; out-of-frame points are dropped.
    for i in range(-12, 13):
        for j in range(-12, 13):
            p = origin + i * v1 + j * v2
            x = float(p[0])
            y = float(p[1])
            if -100 <= x <= width + 100 and -100 <= y <= height + 100:
                key = (round(x, 1), round(y, 1))
                if key not in seen:
                    seen.add(key)
                    points.append(
                        {
                            "i": i,
                            "j": j,
                            "center": {
                                "x": round(x, 2),
                                "y": round(y, 2),
                            },
                        }
                    )

    return points


def _seed_stroke_mask(seed_template, percentile, dilate_iterations):
    positive = seed_template[seed_template > 0]
    if positive.size:
        thr = float(np.percentile(positive, float(percentile)))
    else:
        thr = 255.0

    _, mask = cv2.threshold(
        seed_template,
        thr,
        255,
        cv2.THRESH_BINARY,
    )

    mask = cv2.morphologyEx(
        mask,
        cv2.MORPH_CLOSE,
        np.ones((3, 3), dtype=np.uint8),
        iterations=1,
    )

    if int(dilate_iterations) > 0:
        mask = cv2.dilate(
            mask,
            np.ones((3, 3), dtype=np.uint8),
            iterations=int(dilate_iterations),
        )

    return mask


def _manual_seed_grid_sync(req: BrandingManualSeedGridRequest):
    video_path = _safe_workspace_path(req.relative_path)

    if not 0.25 <= float(req.scan_interval_seconds) <= 10:
        raise HTTPException(
            status_code=422,
            detail="scan_interval_seconds must be between 0.25 and 10.",
        )
    if not 1 <= int(req.max_frames) <= 1000:
        raise HTTPException(
            status_code=422,
            detail="max_frames must be between 1 and 1000.",
        )
    if not 0.10 <= float(req.match_threshold) <= 0.95:
        raise HTTPException(
            status_code=422,
            detail="match_threshold must be between 0.10 and 0.95.",
        )
    if not 2 <= int(req.top_k_matches) <= 100:
        raise HTTPException(
            status_code=422,
            detail="top_k_matches must be between 2 and 100.",
        )

    cap = cv2.VideoCapture(str(video_path))
    if not cap.isOpened():
        raise HTTPException(status_code=422, detail="Could not open source video.")

    try:
        metadata = _video_metadata(cap)
    finally:
        cap.release()

    width = int(metadata.get("width") or 0)
    height = int(metadata.get("height") or 0)
    duration = float(metadata.get("duration_seconds") or 0.0)

    seed_bbox = _normalized_bbox_to_pixels(
        req.seed_x,
        req.seed_y,
        req.seed_width,
        req.seed_height,
        width,
        height,
    )

    start = max(0.0, float(req.start_seconds or 0.0))
    if req.end_seconds is None:
        end = duration if duration > 0 else start + 60.0
    else:
        end = max(start, float(req.end_seconds))
        if duration > 0:
            end = min(end, duration)

    span = max(0.001, end - start)
    interval = max(
        float(req.scan_interval_seconds),
        span / float(max(1, int(req.max_frames))),
    )

    temporal = _persistent_overlay_map(
        video_path,
        start,
        end,
        interval,
        int(req.max_frames),
        req.response_kernel_widths,
    )

    persistence = temporal["persistence"]
    persistence_u8 = _normalize_u8(persistence)

    seed_template = _seed_template_from_persistence(
        persistence,
        seed_bbox,
        float(req.response_floor_percentile),
    )

    matches = _multi_scale_seed_matches(
        persistence_u8,
        seed_template,
        req.search_scales,
        float(req.match_threshold),
        int(req.top_k_matches),
        float(req.nms_iou_threshold),
        seed_bbox,
    )

    vectors = _cluster_lattice_vectors(
        matches,
        float(req.max_neighbor_distance_px),
        float(req.vector_angle_tolerance_degrees),
        float(req.vector_length_tolerance_ratio),
    )
    basis = _choose_lattice_basis(vectors)

    seed_center = _bbox_center(seed_bbox)
    grid_points = _predict_grid_from_basis(
        seed_center,
        basis,
        width,
        height,
    )

    grid_qualified = (
        len(matches) >= int(req.min_grid_matches)
        and len(basis) == 2
        and len(grid_points) >= int(req.min_grid_matches)
    )

    timestamp = _app_now().strftime("%Y-%m-%d_%H%M%S")
    out_dir = (
        WORKSPACE
        / "review"
        / "branding_manual_seed_grid"
        / timestamp
        / video_path.stem
    )
    out_dir.mkdir(parents=True, exist_ok=True)

    persistence_path = out_dir / "01_persistence_map.png"
    seed_path = out_dir / "02_manual_seed_template.png"
    match_path = out_dir / "03_seed_matches.jpg"
    grid_path = out_dir / "04_grid_prediction.jpg"
    seed_mask_path = out_dir / "05_seed_stroke_mask.png"

    cv2.imwrite(str(persistence_path), persistence_u8)
    cv2.imwrite(str(seed_path), seed_template)

    # Context frame for drawing matches/grid.
    cap = cv2.VideoCapture(str(video_path))
    context_frame = None
    if cap.isOpened():
        cap.set(
            cv2.CAP_PROP_POS_MSEC,
            ((start + end) / 2.0) * 1000.0,
        )
        ok, frame = cap.read()
        if ok and frame is not None:
            context_frame = frame
    cap.release()

    if context_frame is None:
        context_frame = np.zeros(
            (height, width, 3),
            dtype=np.uint8,
        )

    match_vis = context_frame.copy()
    for match in matches:
        b = match["bbox"]
        cv2.rectangle(
            match_vis,
            (b["x"], b["y"]),
            (b["x"] + b["width"], b["y"] + b["height"]),
            (255, 255, 255),
            2 if match.get("manual_seed") else 1,
        )
        label = (
            "SEED"
            if match.get("manual_seed")
            else f"M{match['match_id']} {match['score']:.2f}"
        )
        cv2.putText(
            match_vis,
            label,
            (b["x"], max(18, b["y"] - 4)),
            cv2.FONT_HERSHEY_SIMPLEX,
            0.42,
            (255, 255, 255),
            1,
            cv2.LINE_AA,
        )

    cv2.imwrite(str(match_path), match_vis)

    grid_vis = context_frame.copy()
    for point in grid_points:
        cx = int(round(float(point["center"]["x"])))
        cy = int(round(float(point["center"]["y"])))
        half_w = max(2, seed_bbox["width"] // 2)
        half_h = max(2, seed_bbox["height"] // 2)

        x1 = max(0, cx - half_w)
        y1 = max(0, cy - half_h)
        x2 = min(width - 1, cx + half_w)
        y2 = min(height - 1, cy + half_h)

        if x2 <= 0 or y2 <= 0 or x1 >= width or y1 >= height:
            continue

        cv2.rectangle(
            grid_vis,
            (x1, y1),
            (x2, y2),
            (255, 255, 255),
            1,
        )

    # Highlight the manual seed in a thicker box.
    cv2.rectangle(
        grid_vis,
        (seed_bbox["x"], seed_bbox["y"]),
        (
            seed_bbox["x"] + seed_bbox["width"],
            seed_bbox["y"] + seed_bbox["height"],
        ),
        (255, 255, 255),
        3,
    )
    cv2.imwrite(str(grid_path), grid_vis)

    seed_mask = _seed_stroke_mask(
        seed_template,
        float(req.seed_mask_percentile),
        int(req.seed_mask_dilate_iterations),
    )
    cv2.imwrite(str(seed_mask_path), seed_mask)

    mask_coverage = (
        float(np.count_nonzero(seed_mask))
        / float(max(1, seed_mask.size))
    )

    result = {
        "ok": True,
        "version": "0.17.0",
        "mode": "branding_manual_seed_grid_calibration",
        "source": {
            "relative_path": video_path.relative_to(WORKSPACE).as_posix(),
        },
        "video": metadata,
        "manual_seed": {
            "normalized_bbox": {
                "x": round(float(req.seed_x), 6),
                "y": round(float(req.seed_y), 6),
                "width": round(float(req.seed_width), 6),
                "height": round(float(req.seed_height), 6),
            },
            "pixel_bbox": seed_bbox,
            "center": {
                "x": round(seed_center[0], 2),
                "y": round(seed_center[1], 2),
            },
        },
        "temporal_overlay": {
            "frames_scanned": temporal["frame_count"],
            "sampled_times": temporal["sampled_times"],
            "effective_interval_seconds": round(interval, 4),
            "ocr_used": False,
            "brand_text_reading_used": False,
        },
        "matching": {
            "match_count": len(matches),
            "match_threshold": float(req.match_threshold),
            "matches": matches,
        },
        "grid": {
            "qualified": bool(grid_qualified),
            "vector_clusters": vectors[:20],
            "basis_vectors": basis,
            "predicted_grid_point_count": len(grid_points),
            "predicted_grid_points": grid_points,
        },
        "seed_mask": {
            "coverage_ratio": round(mask_coverage, 6),
            "percentile": float(req.seed_mask_percentile),
            "dilate_iterations": int(req.seed_mask_dilate_iterations),
        },
        "summary": {
            "manual_seed_accepted": True,
            "seed_match_count": len(matches),
            "grid_basis_found": len(basis) == 2,
            "grid_qualified": bool(grid_qualified),
            "predicted_grid_point_count": len(grid_points),
            "source_video_modified": False,
            "full_processed_video_created": False,
            "manual_grid_review_required": True,
        },
        "diagnostic_images": {
            "persistence_map": persistence_path.relative_to(WORKSPACE).as_posix(),
            "manual_seed_template": seed_path.relative_to(WORKSPACE).as_posix(),
            "seed_matches": match_path.relative_to(WORKSPACE).as_posix(),
            "grid_prediction": grid_path.relative_to(WORKSPACE).as_posix(),
            "seed_stroke_mask": seed_mask_path.relative_to(WORKSPACE).as_posix(),
        },
        "interpretation": {
            "important": (
                "The seed position is supplied by the human reviewer. The detector no longer guesses "
                "which faint structure is the ReelShort watermark. It learns the repeated screen-space "
                "pattern from the manually confirmed tile."
            ),
            "acceptance": (
                "Grid calibration passes only if the seed match boxes and predicted grid boxes align "
                "with the visible repeated diagonal ReelShort tiles across the frame."
            ),
        },
    }

    report_path = (
        out_dir
        / f"{video_path.stem}.manual-seed-grid.json"
    )
    result["report_relative_path"] = report_path.relative_to(WORKSPACE).as_posix()
    result["output_relative_dir"] = out_dir.relative_to(WORKSPACE).as_posix()

    report_path.write_text(
        json.dumps(
            result,
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )

    return result




class BrandingThreeAnchorBox(BaseModel):
    label: str
    x: float
    y: float
    width: float
    height: float


class BrandingThreeAnchorGridRequest(BaseModel):
    relative_path: str
    anchors: list[BrandingThreeAnchorBox]

    start_seconds: float = 0.0
    end_seconds: Optional[float] = None
    scan_interval_seconds: float = 1.0
    max_frames: int = 140

    response_kernel_widths: list[int] = Field(
        default_factory=lambda: [15, 31, 61]
    )
    response_presence_percentile: float = 82.0
    template_mask_percentile: float = 66.0
    template_mask_dilate_iterations: int = 1

    anchor_padding_ratio: float = 0.06
    min_corner_angle_degrees: float = 55.0
    max_corner_angle_degrees: float = 125.0

    save_diagnostic_images: bool = True


def _angle_between_vectors_degrees(v1, v2):
    a = np.asarray(v1, dtype=np.float64)
    b = np.asarray(v2, dtype=np.float64)

    na = float(np.linalg.norm(a))
    nb = float(np.linalg.norm(b))
    if na <= 1e-9 or nb <= 1e-9:
        return 0.0

    cosv = float(np.dot(a, b) / (na * nb))
    cosv = max(-1.0, min(1.0, cosv))
    return math.degrees(math.acos(cosv))


def _three_anchor_geometry(pixel_anchors):
    if len(pixel_anchors) != 3:
        raise HTTPException(
            status_code=422,
            detail="Exactly 3 anchors are required.",
        )

    centers = []
    for anchor in pixel_anchors:
        cx, cy = _bbox_center(anchor["bbox"])
        centers.append((float(cx), float(cy)))

    corner_candidates = []

    for i in range(3):
        others = [j for j in range(3) if j != i]
        p = np.array(centers[i], dtype=np.float64)
        p1 = np.array(centers[others[0]], dtype=np.float64)
        p2 = np.array(centers[others[1]], dtype=np.float64)

        v1 = p1 - p
        v2 = p2 - p
        angle = _angle_between_vectors_degrees(v1, v2)

        # Prefer a non-collinear lattice corner, and especially one near 90°.
        score = abs(angle - 90.0)

        corner_candidates.append(
            {
                "anchor_index": i,
                "other_indices": others,
                "angle_degrees": angle,
                "score": score,
            }
        )

    corner_candidates.sort(
        key=lambda x: float(x["score"])
    )
    chosen = corner_candidates[0]

    c_idx = int(chosen["anchor_index"])
    o1, o2 = chosen["other_indices"]

    origin = centers[c_idx]
    p1 = centers[o1]
    p2 = centers[o2]

    v1 = {
        "dx": round(p1[0] - origin[0], 4),
        "dy": round(p1[1] - origin[1], 4),
    }
    v1["length"] = round(
        math.hypot(v1["dx"], v1["dy"]),
        4,
    )
    v1["angle_degrees"] = round(
        math.degrees(math.atan2(v1["dy"], v1["dx"])),
        4,
    )

    v2 = {
        "dx": round(p2[0] - origin[0], 4),
        "dy": round(p2[1] - origin[1], 4),
    }
    v2["length"] = round(
        math.hypot(v2["dx"], v2["dy"]),
        4,
    )
    v2["angle_degrees"] = round(
        math.degrees(math.atan2(v2["dy"], v2["dx"])),
        4,
    )

    return {
        "corner_anchor_index": c_idx,
        "corner_label": pixel_anchors[c_idx]["label"],
        "corner_center": {
            "x": round(origin[0], 3),
            "y": round(origin[1], 3),
        },
        "corner_angle_degrees": round(
            float(chosen["angle_degrees"]),
            4,
        ),
        "basis_anchor_labels": [
            pixel_anchors[o1]["label"],
            pixel_anchors[o2]["label"],
        ],
        "basis_vectors": [v1, v2],
        "all_corner_candidates": [
            {
                "label": pixel_anchors[int(x["anchor_index"])]["label"],
                "angle_degrees": round(float(x["angle_degrees"]), 4),
                "distance_from_90_degrees": round(float(x["score"]), 4),
            }
            for x in corner_candidates
        ],
    }


def _expand_bbox_ratio(bbox, ratio, width, height):
    pad_x = int(round(float(bbox["width"]) * float(ratio)))
    pad_y = int(round(float(bbox["height"]) * float(ratio)))

    return _clip_bbox(
        {
            "x": int(bbox["x"]) - pad_x,
            "y": int(bbox["y"]) - pad_y,
            "width": int(bbox["width"]) + 2 * pad_x,
            "height": int(bbox["height"]) + 2 * pad_y,
        },
        width,
        height,
    )


def _aggregate_three_anchor_template(
    video_path,
    pixel_anchors,
    canonical_width,
    canonical_height,
    start,
    end,
    interval,
    max_frames,
    kernel_widths,
    presence_percentile,
    padding_ratio,
):
    cap = cv2.VideoCapture(str(video_path))
    if not cap.isOpened():
        raise HTTPException(
            status_code=422,
            detail="Could not open source video.",
        )

    try:
        metadata = _video_metadata(cap)
        frame_width = int(metadata.get("width") or 0)
        frame_height = int(metadata.get("height") or 0)

        soft_sum = np.zeros(
            (canonical_height, canonical_width),
            dtype=np.float32,
        )
        hard_count = np.zeros(
            (canonical_height, canonical_width),
            dtype=np.uint16,
        )

        usable_samples = 0
        sampled_times = []
        samples_by_anchor = {
            anchor["label"]: 0
            for anchor in pixel_anchors
        }

        t = float(start)
        frames_sampled = 0

        while (
            t <= float(end) + 1e-9
            and frames_sampled < int(max_frames)
        ):
            cap.set(
                cv2.CAP_PROP_POS_MSEC,
                float(t) * 1000.0,
            )
            ok, frame = cap.read()
            if not ok or frame is None:
                t += float(interval)
                continue

            frames_sampled += 1
            sampled_times.append(round(float(t), 3))

            for anchor in pixel_anchors:
                b = _expand_bbox_ratio(
                    anchor["bbox"],
                    float(padding_ratio),
                    frame_width,
                    frame_height,
                )

                crop = frame[
                    b["y"]:b["y"] + b["height"],
                    b["x"]:b["x"] + b["width"],
                ]

                if crop.size == 0:
                    continue

                crop = cv2.resize(
                    crop,
                    (canonical_width, canonical_height),
                    interpolation=cv2.INTER_CUBIC,
                )

                response = _overlay_frame_response(
                    crop,
                    kernel_widths,
                )

                positive = response[response > 0]
                if positive.size:
                    threshold = float(
                        np.percentile(
                            positive,
                            float(presence_percentile),
                        )
                    )
                else:
                    threshold = 1.0

                soft_sum += response
                hard_count += (
                    response >= threshold
                ).astype(np.uint16)

                usable_samples += 1
                samples_by_anchor[anchor["label"]] += 1

            t += float(interval)

        if usable_samples == 0:
            raise HTTPException(
                status_code=422,
                detail="No usable anchor samples were collected.",
            )

        mean_soft = soft_sum / float(usable_samples)
        hard_ratio = hard_count.astype(np.float32) / float(usable_samples)

        # Watermark strokes should persist in the same normalized tile
        # coordinates across both time and all three manually confirmed tiles.
        persistent = mean_soft * (
            0.25 + 0.75 * hard_ratio
        )
        persistent = cv2.GaussianBlur(
            persistent,
            (3, 3),
            0,
        )

        return {
            "metadata": metadata,
            "persistent": persistent,
            "mean_soft": mean_soft,
            "hard_ratio": hard_ratio,
            "usable_samples": usable_samples,
            "frames_sampled": frames_sampled,
            "sampled_times": sampled_times,
            "samples_by_anchor": samples_by_anchor,
        }
    finally:
        cap.release()


def _template_to_mask(template_u8, percentile, dilate_iterations):
    positive = template_u8[template_u8 > 0]
    if positive.size:
        threshold = float(
            np.percentile(
                positive,
                float(percentile),
            )
        )
    else:
        threshold = 255.0

    _, mask = cv2.threshold(
        template_u8,
        threshold,
        255,
        cv2.THRESH_BINARY,
    )

    mask = cv2.morphologyEx(
        mask,
        cv2.MORPH_CLOSE,
        np.ones((3, 3), dtype=np.uint8),
        iterations=1,
    )

    if int(dilate_iterations) > 0:
        mask = cv2.dilate(
            mask,
            np.ones((3, 3), dtype=np.uint8),
            iterations=int(dilate_iterations),
        )

    return mask, threshold


def _grid_points_from_three_anchor_geometry(
    geometry,
    width,
    height,
    canonical_width,
    canonical_height,
):
    basis = geometry["basis_vectors"]
    origin = geometry["corner_center"]

    v1 = np.array(
        [
            float(basis[0]["dx"]),
            float(basis[0]["dy"]),
        ],
        dtype=np.float64,
    )
    v2 = np.array(
        [
            float(basis[1]["dx"]),
            float(basis[1]["dy"]),
        ],
        dtype=np.float64,
    )
    p0 = np.array(
        [
            float(origin["x"]),
            float(origin["y"]),
        ],
        dtype=np.float64,
    )

    points = []
    seen = set()

    for i in range(-12, 13):
        for j in range(-12, 13):
            p = p0 + i * v1 + j * v2
            cx = float(p[0])
            cy = float(p[1])

            half_w = canonical_width / 2.0
            half_h = canonical_height / 2.0

            if (
                cx + half_w < 0
                or cy + half_h < 0
                or cx - half_w > width
                or cy - half_h > height
            ):
                continue

            key = (
                round(cx, 2),
                round(cy, 2),
            )
            if key in seen:
                continue
            seen.add(key)

            points.append(
                {
                    "i": int(i),
                    "j": int(j),
                    "center": {
                        "x": round(cx, 3),
                        "y": round(cy, 3),
                    },
                    "bbox": {
                        "x": int(round(cx - half_w)),
                        "y": int(round(cy - half_h)),
                        "width": int(canonical_width),
                        "height": int(canonical_height),
                    },
                }
            )

    points.sort(
        key=lambda p: (
            float(p["center"]["y"]),
            float(p["center"]["x"]),
        )
    )
    return points


def _paste_mask_centered(full_mask, tile_mask, center_x, center_y):
    height, width = full_mask.shape[:2]
    th, tw = tile_mask.shape[:2]

    x1 = int(round(float(center_x) - tw / 2.0))
    y1 = int(round(float(center_y) - th / 2.0))
    x2 = x1 + tw
    y2 = y1 + th

    src_x1 = 0
    src_y1 = 0
    src_x2 = tw
    src_y2 = th

    if x1 < 0:
        src_x1 = -x1
        x1 = 0
    if y1 < 0:
        src_y1 = -y1
        y1 = 0
    if x2 > width:
        src_x2 -= x2 - width
        x2 = width
    if y2 > height:
        src_y2 -= y2 - height
        y2 = height

    if x2 <= x1 or y2 <= y1:
        return

    tile_part = tile_mask[
        src_y1:src_y2,
        src_x1:src_x2,
    ]
    target = full_mask[
        y1:y2,
        x1:x2,
    ]
    np.maximum(
        target,
        tile_part,
        out=target,
    )


def _three_anchor_grid_sync(req: BrandingThreeAnchorGridRequest):
    video_path = _safe_workspace_path(req.relative_path)

    if len(req.anchors) != 3:
        raise HTTPException(
            status_code=422,
            detail="Exactly 3 manually confirmed watermark anchors are required.",
        )

    if not 0.25 <= float(req.scan_interval_seconds) <= 10:
        raise HTTPException(
            status_code=422,
            detail="scan_interval_seconds must be between 0.25 and 10.",
        )

    if not 1 <= int(req.max_frames) <= 1000:
        raise HTTPException(
            status_code=422,
            detail="max_frames must be between 1 and 1000.",
        )

    if not 0.0 <= float(req.anchor_padding_ratio) <= 0.30:
        raise HTTPException(
            status_code=422,
            detail="anchor_padding_ratio must be between 0 and 0.30.",
        )

    cap = cv2.VideoCapture(str(video_path))
    if not cap.isOpened():
        raise HTTPException(
            status_code=422,
            detail="Could not open source video.",
        )

    try:
        metadata = _video_metadata(cap)
    finally:
        cap.release()

    width = int(metadata.get("width") or 0)
    height = int(metadata.get("height") or 0)
    duration = float(metadata.get("duration_seconds") or 0.0)

    pixel_anchors = []

    for anchor in req.anchors:
        bbox = _normalized_bbox_to_pixels(
            anchor.x,
            anchor.y,
            anchor.width,
            anchor.height,
            width,
            height,
        )

        pixel_anchors.append(
            {
                "label": str(anchor.label),
                "normalized_bbox": {
                    "x": round(float(anchor.x), 8),
                    "y": round(float(anchor.y), 8),
                    "width": round(float(anchor.width), 8),
                    "height": round(float(anchor.height), 8),
                },
                "bbox": bbox,
                "center": {
                    "x": round(_bbox_center(bbox)[0], 3),
                    "y": round(_bbox_center(bbox)[1], 3),
                },
            }
        )

    geometry = _three_anchor_geometry(pixel_anchors)

    corner_angle = float(
        geometry["corner_angle_degrees"]
    )
    if not (
        float(req.min_corner_angle_degrees)
        <= corner_angle
        <= float(req.max_corner_angle_degrees)
    ):
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "three_anchor_geometry",
                "error": "anchors_do_not_form_stable_lattice_corner",
                "best_corner_angle_degrees": corner_angle,
                "allowed_range": [
                    float(req.min_corner_angle_degrees),
                    float(req.max_corner_angle_degrees),
                ],
            },
        )

    # Use the median size so one loosely drawn manual box does not dominate.
    canonical_width = int(
        round(
            _median(
                [
                    float(a["bbox"]["width"])
                    for a in pixel_anchors
                ]
            )
        )
    )
    canonical_height = int(
        round(
            _median(
                [
                    float(a["bbox"]["height"])
                    for a in pixel_anchors
                ]
            )
        )
    )

    canonical_width = max(24, canonical_width)
    canonical_height = max(12, canonical_height)

    start = max(
        0.0,
        float(req.start_seconds or 0.0),
    )
    if req.end_seconds is None:
        end = duration if duration > 0 else start + 60.0
    else:
        end = max(start, float(req.end_seconds))
        if duration > 0:
            end = min(end, duration)

    span = max(0.001, end - start)
    interval = max(
        float(req.scan_interval_seconds),
        span / float(max(1, int(req.max_frames))),
    )

    aggregate = _aggregate_three_anchor_template(
        video_path,
        pixel_anchors,
        canonical_width,
        canonical_height,
        start,
        end,
        interval,
        int(req.max_frames),
        req.response_kernel_widths,
        float(req.response_presence_percentile),
        float(req.anchor_padding_ratio),
    )

    template_u8 = _normalize_u8(
        aggregate["persistent"]
    )

    tile_mask, mask_threshold = _template_to_mask(
        template_u8,
        float(req.template_mask_percentile),
        int(req.template_mask_dilate_iterations),
    )

    grid_points = _grid_points_from_three_anchor_geometry(
        geometry,
        width,
        height,
        canonical_width,
        canonical_height,
    )

    full_grid_mask = np.zeros(
        (height, width),
        dtype=np.uint8,
    )

    for point in grid_points:
        center = point["center"]
        _paste_mask_centered(
            full_grid_mask,
            tile_mask,
            float(center["x"]),
            float(center["y"]),
        )

    timestamp = _app_now().strftime(
        "%Y-%m-%d_%H%M%S"
    )
    out_dir = (
        WORKSPACE
        / "review"
        / "branding_three_anchor_grid"
        / timestamp
        / video_path.stem
    )
    out_dir.mkdir(
        parents=True,
        exist_ok=True,
    )

    anchor_context_path = out_dir / "01_manual_anchors.jpg"
    persistent_template_path = out_dir / "02_three_anchor_persistent_template.png"
    tile_mask_path = out_dir / "03_tile_stroke_mask.png"
    grid_prediction_path = out_dir / "04_three_point_grid_prediction.jpg"
    full_mask_path = out_dir / "05_full_grid_mask.png"
    mask_overlay_path = out_dir / "06_full_grid_mask_overlay.jpg"

    cv2.imwrite(
        str(persistent_template_path),
        template_u8,
    )
    cv2.imwrite(
        str(tile_mask_path),
        tile_mask,
    )
    cv2.imwrite(
        str(full_mask_path),
        full_grid_mask,
    )

    # Use a middle source frame only for diagnostics.
    cap = cv2.VideoCapture(str(video_path))
    context = None
    if cap.isOpened():
        cap.set(
            cv2.CAP_PROP_POS_MSEC,
            ((start + end) / 2.0) * 1000.0,
        )
        ok, frame = cap.read()
        if ok and frame is not None:
            context = frame
    cap.release()

    if context is None:
        context = np.zeros(
            (height, width, 3),
            dtype=np.uint8,
        )

    anchor_vis = context.copy()
    for anchor in pixel_anchors:
        b = anchor["bbox"]
        cv2.rectangle(
            anchor_vis,
            (b["x"], b["y"]),
            (
                b["x"] + b["width"],
                b["y"] + b["height"],
            ),
            (255, 255, 255),
            2,
        )
        cv2.putText(
            anchor_vis,
            anchor["label"],
            (b["x"], max(20, b["y"] - 6)),
            cv2.FONT_HERSHEY_SIMPLEX,
            0.65,
            (255, 255, 255),
            2,
            cv2.LINE_AA,
        )

    cv2.imwrite(
        str(anchor_context_path),
        anchor_vis,
    )

    grid_vis = context.copy()
    for point in grid_points:
        b = point["bbox"]
        x1 = max(0, int(b["x"]))
        y1 = max(0, int(b["y"]))
        x2 = min(width - 1, int(b["x"] + b["width"]))
        y2 = min(height - 1, int(b["y"] + b["height"]))

        if x2 <= x1 or y2 <= y1:
            continue

        cv2.rectangle(
            grid_vis,
            (x1, y1),
            (x2, y2),
            (255, 255, 255),
            1,
        )

    # Manual anchors stay thicker.
    for anchor in pixel_anchors:
        b = anchor["bbox"]
        cv2.rectangle(
            grid_vis,
            (b["x"], b["y"]),
            (
                b["x"] + b["width"],
                b["y"] + b["height"],
            ),
            (255, 255, 255),
            3,
        )

    cv2.imwrite(
        str(grid_prediction_path),
        grid_vis,
    )

    overlay = context.copy()
    white = np.zeros_like(overlay)
    white[:] = (255, 255, 255)
    alpha = (
        full_grid_mask.astype(np.float32)
        / 255.0
        * 0.55
    )[..., None]
    overlay = (
        overlay.astype(np.float32) * (1.0 - alpha)
        + white.astype(np.float32) * alpha
    ).astype(np.uint8)

    cv2.imwrite(
        str(mask_overlay_path),
        overlay,
    )

    mask_coverage = (
        float(np.count_nonzero(tile_mask))
        / float(max(1, tile_mask.size))
    )

    full_mask_coverage = (
        float(np.count_nonzero(full_grid_mask))
        / float(max(1, full_grid_mask.size))
    )

    result = {
        "ok": True,
        "version": "0.17.0",
        "mode": "branding_three_anchor_grid_calibration",
        "source": {
            "relative_path": video_path.relative_to(WORKSPACE).as_posix(),
        },
        "video": metadata,
        "anchors": pixel_anchors,
        "geometry": geometry,
        "canonical_tile": {
            "width": canonical_width,
            "height": canonical_height,
        },
        "temporal_template": {
            "frames_sampled": aggregate["frames_sampled"],
            "usable_anchor_samples": aggregate["usable_samples"],
            "samples_by_anchor": aggregate["samples_by_anchor"],
            "effective_interval_seconds": round(interval, 4),
            "response_presence_percentile": float(
                req.response_presence_percentile
            ),
        },
        "grid": {
            "basis_found_from_manual_geometry": True,
            "predicted_grid_point_count": len(grid_points),
            "predicted_grid_points": grid_points,
        },
        "mask": {
            "tile_mask_threshold": round(float(mask_threshold), 4),
            "tile_mask_coverage_ratio": round(mask_coverage, 6),
            "full_grid_mask_coverage_ratio": round(full_mask_coverage, 6),
        },
        "summary": {
            "manual_anchor_count": 3,
            "chosen_corner_label": geometry["corner_label"],
            "corner_angle_degrees": geometry["corner_angle_degrees"],
            "grid_basis_found": True,
            "grid_qualified": len(grid_points) >= 4,
            "predicted_grid_point_count": len(grid_points),
            "source_video_modified": False,
            "full_processed_video_created": False,
            "manual_grid_review_required": True,
        },
        "diagnostic_images": {
            "manual_anchors": anchor_context_path.relative_to(WORKSPACE).as_posix(),
            "three_anchor_persistent_template": persistent_template_path.relative_to(WORKSPACE).as_posix(),
            "tile_stroke_mask": tile_mask_path.relative_to(WORKSPACE).as_posix(),
            "grid_prediction": grid_prediction_path.relative_to(WORKSPACE).as_posix(),
            "full_grid_mask": full_mask_path.relative_to(WORKSPACE).as_posix(),
            "full_grid_mask_overlay": mask_overlay_path.relative_to(WORKSPACE).as_posix(),
        },
        "interpretation": {
            "geometry": (
                "The two lattice vectors come directly from the three human-confirmed "
                "watermark tiles. No subtitle/texture search is used to infer grid spacing."
            ),
            "template": (
                "The stroke template aggregates the same normalized tile across all three "
                "anchors and many video times, reducing scene/background influence."
            ),
            "acceptance": (
                "Accept only if the predicted boxes follow the visible repeated ReelShort "
                "layout and the tile/full-grid masks overlap the watermark strokes rather "
                "than large background regions."
            ),
        },
    }

    report_path = (
        out_dir
        / f"{video_path.stem}.three-anchor-grid.json"
    )
    result["report_relative_path"] = (
        report_path.relative_to(WORKSPACE).as_posix()
    )
    result["output_relative_dir"] = (
        out_dir.relative_to(WORKSPACE).as_posix()
    )

    report_path.write_text(
        json.dumps(
            result,
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )

    return result




class BrandingWatermarkRouteRequest(BaseModel):
    relative_path: str
    brand_targets: list[str] = Field(default_factory=list)

    # Evidence reports are optional. Router only uses evidence explicitly
    # supplied by the caller; it never guesses a report from another run.
    census_report_relative_path: Optional[str] = None
    mask_review_relative_path: Optional[str] = None
    three_anchor_grid_report_relative_path: Optional[str] = None
    flow_track_report_relative_path: Optional[str] = None

    # If a validated three-anchor tiled grid is supplied, save/reuse it as a
    # brand profile. The profile is trusted on its source video, but on a new
    # video it is only a REVIEW candidate until separately validated.
    save_three_anchor_profile: bool = True
    profile_brand_name: Optional[str] = None
    profile_name: Optional[str] = None

    auto_threshold: float = 0.85
    review_threshold: float = 0.55


class BrandingWatermarkProfileRegisterRequest(BaseModel):
    three_anchor_grid_report_relative_path: str
    brand_name: str
    profile_name: Optional[str] = None
    overwrite: bool = False
    notes: Optional[str] = None


def _watermark_profile_registry_path():
    path = (WORKSPACE / "config" / "watermark_profiles.json").resolve()
    workspace_resolved = WORKSPACE.resolve()
    if workspace_resolved not in path.parents:
        raise HTTPException(
            status_code=500,
            detail="Invalid watermark profile registry path.",
        )
    return path


def _empty_watermark_registry():
    return {
        "schema_version": 1,
        "updated_at": None,
        "profiles": [],
    }


def _load_watermark_registry():
    path = _watermark_profile_registry_path()
    if not path.exists():
        return _empty_watermark_registry()

    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except Exception as exc:
        raise HTTPException(
            status_code=500,
            detail={
                "stage": "watermark_profile_registry",
                "error": "invalid_registry_json",
                "message": str(exc)[:500],
            },
        )

    if not isinstance(data, dict):
        raise HTTPException(
            status_code=500,
            detail="Watermark profile registry must be a JSON object.",
        )

    profiles = data.get("profiles")
    if not isinstance(profiles, list):
        profiles = []

    data["schema_version"] = int(data.get("schema_version") or 1)
    data["profiles"] = profiles
    return data


def _write_watermark_registry(data):
    path = _watermark_profile_registry_path()
    path.parent.mkdir(parents=True, exist_ok=True)

    payload = dict(data)
    payload["schema_version"] = 1
    payload["updated_at"] = _app_now().isoformat(timespec="seconds")

    tmp = Path(str(path) + ".tmp")
    tmp.write_text(
        json.dumps(payload, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )
    tmp.replace(path)
    return path


def _norm_brand_name(value):
    import unicodedata

    value = unicodedata.normalize("NFKC", str(value or ""))
    return "".join(ch for ch in value.casefold() if ch.isalnum())


def _profile_geometry_signature_payload(report):
    video = report.get("video") or {}
    geometry = report.get("geometry") or {}
    canonical = report.get("canonical_tile") or {}
    basis = geometry.get("basis_vectors") or []
    corner = geometry.get("corner_center") or {}

    width = float(video.get("width") or 1.0)
    height = float(video.get("height") or 1.0)

    normalized_basis = []
    for vector in basis[:2]:
        normalized_basis.append(
            {
                "dx": round(float(vector.get("dx") or 0.0) / width, 8),
                "dy": round(float(vector.get("dy") or 0.0) / height, 8),
                "length_x_norm": round(
                    float(vector.get("length") or 0.0) / width,
                    8,
                ),
                "angle_degrees": round(
                    float(vector.get("angle_degrees") or 0.0),
                    4,
                ),
            }
        )

    return {
        "origin_normalized": {
            "x": round(float(corner.get("x") or 0.0) / width, 8),
            "y": round(float(corner.get("y") or 0.0) / height, 8),
        },
        "basis_vectors_normalized": normalized_basis,
        "canonical_tile_normalized": {
            "width": round(
                float(canonical.get("width") or 0.0) / width,
                8,
            ),
            "height": round(
                float(canonical.get("height") or 0.0) / height,
                8,
            ),
        },
        "corner_angle_degrees": round(
            float(geometry.get("corner_angle_degrees") or 0.0),
            4,
        ),
    }


def _build_three_anchor_profile(report, brand_name, profile_name=None, notes=None):
    import hashlib

    if report.get("mode") != "branding_three_anchor_grid_calibration":
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "watermark_profile_register",
                "error": "wrong_report_mode",
                "expected": "branding_three_anchor_grid_calibration",
                "actual": report.get("mode"),
            },
        )

    summary = report.get("summary") or {}
    if not bool(summary.get("grid_basis_found")) or not bool(summary.get("grid_qualified")):
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "watermark_profile_register",
                "error": "three_anchor_grid_not_qualified",
            },
        )

    source = report.get("source") or {}
    source_rel = str(source.get("relative_path") or "").strip()
    if not source_rel:
        raise HTTPException(
            status_code=422,
            detail="Three-anchor report has no source.relative_path.",
        )

    brand_name = str(brand_name or "").strip()
    if not brand_name:
        raise HTTPException(
            status_code=422,
            detail="brand_name is required.",
        )

    signature_payload = _profile_geometry_signature_payload(report)
    signature_material = json.dumps(
        {
            "brand": _norm_brand_name(brand_name),
            "type": "diagonal_tiled",
            "geometry": signature_payload,
        },
        sort_keys=True,
        ensure_ascii=False,
    )
    digest = hashlib.sha256(
        signature_material.encode("utf-8")
    ).hexdigest()[:16]

    profile_id = f"{_norm_brand_name(brand_name) or 'brand'}-diagonal-tiled-{digest}"

    anchors = []
    for anchor in report.get("anchors") or []:
        normalized = anchor.get("normalized_bbox") or {}
        anchors.append(
            {
                "label": anchor.get("label"),
                "normalized_bbox": normalized,
            }
        )

    diagnostics = report.get("diagnostic_images") or {}
    mask = report.get("mask") or {}

    return {
        "profile_id": profile_id,
        "profile_name": (
            str(profile_name).strip()
            if profile_name
            else f"{brand_name} diagonal tiled watermark"
        ),
        "brand_name": brand_name,
        "brand_key": _norm_brand_name(brand_name),
        "type": "diagonal_tiled",
        "handler": "diagonal_tiled_grid",
        "status": "validated_on_source",
        "created_at": _app_now().isoformat(timespec="seconds"),
        "updated_at": _app_now().isoformat(timespec="seconds"),
        "source": {
            "relative_path": source_rel,
            "video": report.get("video"),
            "report_relative_path": report.get("report_relative_path"),
        },
        "geometry": signature_payload,
        "manual_anchors": anchors,
        "template": {
            "tile_stroke_mask_relative_path": diagnostics.get("tile_stroke_mask"),
            "three_anchor_persistent_template_relative_path": diagnostics.get(
                "three_anchor_persistent_template"
            ),
            "tile_mask_coverage_ratio": mask.get("tile_mask_coverage_ratio"),
        },
        "reuse_policy": {
            "same_source_video": "AUTO",
            "new_video_same_brand": "REVIEW",
            "requires_geometry_validation_on_new_video": True,
            "never_force_on_unknown_layout": True,
        },
        "notes": notes,
    }


def _upsert_watermark_profile(profile, overwrite=False):
    registry = _load_watermark_registry()
    profiles = list(registry.get("profiles") or [])

    found_index = None
    for idx, old in enumerate(profiles):
        if old.get("profile_id") == profile.get("profile_id"):
            found_index = idx
            break

    if found_index is None:
        profiles.append(profile)
        action = "created"
    else:
        if overwrite:
            old_created = profiles[found_index].get("created_at")
            replacement = dict(profile)
            if old_created:
                replacement["created_at"] = old_created
            replacement["updated_at"] = _app_now().isoformat(
                timespec="seconds"
            )
            profiles[found_index] = replacement
            action = "updated"
        else:
            # Deterministic profile IDs make repeated registration idempotent.
            profile = profiles[found_index]
            action = "reused_existing"

    registry["profiles"] = profiles
    path = _write_watermark_registry(registry)

    return {
        "action": action,
        "profile": profile,
        "registry_relative_path": path.relative_to(WORKSPACE).as_posix(),
        "profile_count": len(profiles),
    }


def _read_optional_json_report(relative_path, expected_source=None):
    if not relative_path:
        return None

    path = _safe_workspace_path(relative_path)
    try:
        report = json.loads(path.read_text(encoding="utf-8"))
    except Exception as exc:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "watermark_router",
                "error": "invalid_evidence_report",
                "relative_path": relative_path,
                "message": str(exc)[:500],
            },
        )

    report_source = (
        (report.get("source") or {})
        .get("relative_path")
    )
    if (
        expected_source
        and report_source
        and str(report_source) != str(expected_source)
    ):
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "watermark_router",
                "error": "evidence_source_mismatch",
                "expected_source": expected_source,
                "report_source": report_source,
                "relative_path": relative_path,
            },
        )

    return report


def _route_status(confidence, auto_threshold, review_threshold, auto_capable):
    confidence = float(confidence)
    if auto_capable and confidence >= float(auto_threshold):
        return "AUTO"
    if confidence >= float(review_threshold):
        return "REVIEW"
    return "CALIBRATION_REQUIRED"


def _layer(
    layer_id,
    layer_type,
    handler,
    confidence,
    status,
    evidence,
    strategy,
    notes=None,
):
    return {
        "layer_id": layer_id,
        "type": layer_type,
        "handler": handler,
        "confidence": round(float(confidence), 4),
        "status": status,
        "strategy": strategy,
        "evidence": evidence,
        "notes": notes,
    }


def _census_route_layers(
    census,
    video_width,
    video_height,
    duration,
    auto_threshold,
    review_threshold,
):
    layers = []

    if not census:
        return layers

    frame_area = max(1.0, float(video_width * video_height))
    clusters = list(census.get("clusters") or [])

    for cluster in clusters:
        cid = int(cluster.get("cluster_id") or 0)
        bbox = cluster.get("stable_bbox") or {}
        if not bbox:
            continue

        area_ratio = (
            float(bbox.get("width") or 0)
            * float(bbox.get("height") or 0)
            / frame_area
        )
        center_x, center_y = _bbox_center(bbox)
        unique_times = int(cluster.get("unique_time_count") or 0)
        max_spread = float(cluster.get("max_center_spread_px") or 9999.0)
        tmin = float(cluster.get("time_min_seconds") or 0.0)
        tmax = float(cluster.get("time_max_seconds") or 0.0)

        # v0.18.10.9.7: Persistent full-width bottom CTA bar (e.g. ReelShort's
        # "Free for a limited time" strip). It carries no brand-name text so the
        # census marks it explicitly; cover it with a compact own-brand banner.
        if str(cluster.get("source") or "") == "bottom_cta":
            confidence = min(
                0.96,
                0.72
                + min(0.16, unique_times / 100.0)
                + 0.08,
            )
            status = _route_status(
                confidence,
                auto_threshold,
                review_threshold,
                auto_capable=True,
            )
            layers.append(
                _layer(
                    f"census-{cid}-bottom-cta",
                    "fixed_strong",
                    "fixed_strong_roi",
                    confidence,
                    status,
                    {
                        "cluster_id": cid,
                        "bbox": bbox,
                        "unique_time_count": unique_times,
                        "max_center_spread_px": max_spread,
                        "area_ratio": round(area_ratio, 6),
                        "source": "bottom_cta",
                    },
                    "bottom_banner_cover",
                    "Persistent bottom CTA bar carries no brand-name text; covered with a compact own-brand banner.",
                )
            )
            continue

        # End card: short-lived large/central brand region at the very end.
        near_end = (
            duration > 0
            and tmax >= duration - 1.5
            and tmin >= max(0.0, duration - 8.0)
        )
        centralish = (
            0.12 * video_width <= center_x <= 0.88 * video_width
            and 0.20 * video_height <= center_y <= 0.86 * video_height
        )

        if near_end and area_ratio >= 0.015 and centralish:
            confidence = min(
                0.98,
                0.78
                + min(0.12, unique_times * 0.02)
                + min(0.08, area_ratio),
            )
            status = _route_status(
                confidence,
                auto_threshold,
                review_threshold,
                auto_capable=False,
            )
            layers.append(
                _layer(
                    f"census-{cid}-end-card",
                    "end_card",
                    "end_card_replace",
                    confidence,
                    status,
                    {
                        "cluster_id": cid,
                        "bbox": bbox,
                        "time_min_seconds": tmin,
                        "time_max_seconds": tmax,
                        "area_ratio": round(area_ratio, 6),
                    },
                    "replace_end_card",
                    "Large near-end competitor branding should be replaced as a card, not inpainted as a large rectangle.",
                )
            )
            continue

        # Strong fixed corner/top logo: repeated many times, stable and small.
        top_region = center_y <= 0.18 * video_height
        bottom_region = center_y >= 0.78 * video_height
        stable = max_spread <= 70.0
        persistent = unique_times >= 5
        small = area_ratio <= 0.045

        if (top_region or bottom_region) and stable and persistent and small:
            confidence = 0.72
            confidence += min(0.16, unique_times / 100.0)
            confidence += 0.07 if max_spread <= 40 else 0.0
            confidence += 0.04 if area_ratio <= 0.02 else 0.0
            confidence = min(0.99, confidence)

            status = _route_status(
                confidence,
                auto_threshold,
                review_threshold,
                auto_capable=True,
            )
            layers.append(
                _layer(
                    f"census-{cid}-fixed-strong",
                    "fixed_strong",
                    "fixed_strong_roi",
                    confidence,
                    status,
                    {
                        "cluster_id": cid,
                        "bbox": bbox,
                        "unique_time_count": unique_times,
                        "max_center_spread_px": max_spread,
                        "area_ratio": round(area_ratio, 6),
                    },
                    "tight_mask_inpaint",
                    "Use a tight local mask; do not reuse the old full-frame OCR line box blindly.",
                )
            )
            continue

        # Mid-frame OCR text is deliberately NOT promoted to automatic
        # watermark. It may be promotional copy rather than watermark.
        if unique_times >= 3:
            confidence = 0.48
            layers.append(
                _layer(
                    f"census-{cid}-unclassified-text",
                    "unclassified_brand_text",
                    "manual_brand_text_review",
                    confidence,
                    "CALIBRATION_REQUIRED",
                    {
                        "cluster_id": cid,
                        "bbox": bbox,
                        "unique_time_count": unique_times,
                        "time_min_seconds": tmin,
                        "time_max_seconds": tmax,
                    },
                    "review_only",
                    "Repeated brand text outside a known watermark pattern may be promotional copy; never auto-remove from OCR alone.",
                )
            )

    return layers


def _three_anchor_route_layer(
    report,
    relative_path,
    auto_threshold,
    review_threshold,
):
    if not report:
        return None

    summary = report.get("summary") or {}
    source_rel = (
        (report.get("source") or {})
        .get("relative_path")
    )
    qualified = (
        bool(summary.get("grid_basis_found"))
        and bool(summary.get("grid_qualified"))
    )

    if not qualified:
        return _layer(
            "three-anchor-grid",
            "diagonal_tiled",
            "diagonal_tiled_grid",
            0.45,
            "CALIBRATION_REQUIRED",
            {
                "grid_basis_found": bool(summary.get("grid_basis_found")),
                "grid_qualified": bool(summary.get("grid_qualified")),
            },
            "recalibrate_three_anchor_grid",
        )

    same_source = str(source_rel or "") == str(relative_path)
    confidence = 0.99 if same_source else 0.68

    status = _route_status(
        confidence,
        auto_threshold,
        review_threshold,
        auto_capable=same_source,
    )

    return _layer(
        "three-anchor-grid",
        "diagonal_tiled",
        "diagonal_tiled_grid",
        confidence,
        status,
        {
            "same_source_video": same_source,
            "chosen_corner_label": summary.get("chosen_corner_label"),
            "corner_angle_degrees": summary.get("corner_angle_degrees"),
            "predicted_grid_point_count": summary.get(
                "predicted_grid_point_count"
            ),
            "report_relative_path": report.get("report_relative_path"),
        },
        "grid_stroke_mask",
        (
            "Validated manual three-anchor lattice on this source video."
            if same_source
            else "Geometry from another source is only a profile candidate until validated on this video."
        ),
    )


def _flow_route_layers(flow_report, auto_threshold, review_threshold):
    if not flow_report:
        return []

    summary = flow_report.get("summary") or {}
    tracks = list(flow_report.get("tracks") or [])
    track_count = int(summary.get("track_count") or len(tracks))

    if track_count <= 0:
        return []

    confidence = min(0.78, 0.58 + track_count * 0.03)
    status = _route_status(
        confidence,
        auto_threshold,
        review_threshold,
        auto_capable=False,
    )

    return [
        _layer(
            "flow-tracked-watermark",
            "moving",
            "moving_watermark_tracker",
            confidence,
            status,
            {
                "track_count": track_count,
                "flow_algorithm": (
                    (flow_report.get("flow") or {}).get("algorithm")
                ),
            },
            "tracked_dynamic_mask",
            "Dynamic tracking exists but remains REVIEW until drift has been visually validated on the specific video.",
        )
    ]


def _profile_route_candidates(registry, brand_targets, relative_path):
    target_keys = {
        _norm_brand_name(x)
        for x in (brand_targets or [])
        if _norm_brand_name(x)
    }

    result = []

    for profile in registry.get("profiles") or []:
        brand_key = str(profile.get("brand_key") or "")
        if target_keys and brand_key not in target_keys:
            continue

        source_rel = (
            (profile.get("source") or {})
            .get("relative_path")
        )
        same_source = str(source_rel or "") == str(relative_path)

        result.append(
            {
                "profile_id": profile.get("profile_id"),
                "profile_name": profile.get("profile_name"),
                "brand_name": profile.get("brand_name"),
                "type": profile.get("type"),
                "handler": profile.get("handler"),
                "same_source_video": same_source,
                "route_status": "AUTO" if same_source else "REVIEW",
                "reuse_policy": profile.get("reuse_policy"),
                "geometry": profile.get("geometry"),
            }
        )

    return result


def _overall_route_status(layers):
    if not layers:
        return "CALIBRATION_REQUIRED"

    statuses = [str(layer.get("status") or "") for layer in layers]

    # Any unknown/unclassified layer keeps the overall plan in review rather
    # than blocking already-safe layers.
    if "REVIEW" in statuses or "CALIBRATION_REQUIRED" in statuses:
        return "REVIEW"

    if all(status == "AUTO" for status in statuses):
        return "AUTO"

    return "REVIEW"


def _register_three_anchor_report(
    report,
    brand_name,
    profile_name=None,
    overwrite=False,
    notes=None,
):
    profile = _build_three_anchor_profile(
        report,
        brand_name,
        profile_name=profile_name,
        notes=notes,
    )
    return _upsert_watermark_profile(
        profile,
        overwrite=overwrite,
    )


def _watermark_profile_register_sync(req: BrandingWatermarkProfileRegisterRequest):
    report = _read_optional_json_report(
        req.three_anchor_grid_report_relative_path
    )

    result = _register_three_anchor_report(
        report,
        req.brand_name,
        profile_name=req.profile_name,
        overwrite=bool(req.overwrite),
        notes=req.notes,
    )

    return {
        "ok": True,
        "version": "0.17.0",
        "mode": "watermark_profile_register",
        **result,
    }


def _watermark_route_sync(req: BrandingWatermarkRouteRequest):
    video_path = _safe_workspace_path(req.relative_path)

    if not 0.50 <= float(req.review_threshold) <= 0.95:
        raise HTTPException(
            status_code=422,
            detail="review_threshold must be between 0.50 and 0.95.",
        )
    if not 0.60 <= float(req.auto_threshold) <= 0.99:
        raise HTTPException(
            status_code=422,
            detail="auto_threshold must be between 0.60 and 0.99.",
        )
    if float(req.auto_threshold) < float(req.review_threshold):
        raise HTTPException(
            status_code=422,
            detail="auto_threshold must be >= review_threshold.",
        )

    cap = cv2.VideoCapture(str(video_path))
    if not cap.isOpened():
        raise HTTPException(
            status_code=422,
            detail="Could not open source video.",
        )

    try:
        metadata = _video_metadata(cap)
    finally:
        cap.release()

    width = int(metadata.get("width") or 0)
    height = int(metadata.get("height") or 0)
    duration = float(metadata.get("duration_seconds") or 0.0)

    census = _read_optional_json_report(
        req.census_report_relative_path,
        expected_source=req.relative_path,
    )
    mask_review = _read_optional_json_report(
        req.mask_review_relative_path,
        expected_source=req.relative_path,
    )
    three_anchor = _read_optional_json_report(
        req.three_anchor_grid_report_relative_path,
        expected_source=req.relative_path,
    )
    flow = _read_optional_json_report(
        req.flow_track_report_relative_path,
        expected_source=req.relative_path,
    )

    profile_registration = None

    if (
        req.save_three_anchor_profile
        and three_anchor is not None
        and bool((three_anchor.get("summary") or {}).get("grid_qualified"))
    ):
        brand_name = (
            str(req.profile_brand_name or "").strip()
            or (
                str(req.brand_targets[0]).strip()
                if req.brand_targets
                else ""
            )
        )

        if brand_name:
            profile_registration = _register_three_anchor_report(
                three_anchor,
                brand_name,
                profile_name=req.profile_name,
                overwrite=False,
                notes="Created by watermark router from validated three-anchor grid.",
            )

    registry = _load_watermark_registry()

    layers = []
    layers.extend(
        _census_route_layers(
            census,
            width,
            height,
            duration,
            float(req.auto_threshold),
            float(req.review_threshold),
        )
    )

    tiled_layer = _three_anchor_route_layer(
        three_anchor,
        req.relative_path,
        float(req.auto_threshold),
        float(req.review_threshold),
    )
    if tiled_layer:
        layers.append(tiled_layer)

    layers.extend(
        _flow_route_layers(
            flow,
            float(req.auto_threshold),
            float(req.review_threshold),
        )
    )

    # Mask-review evidence is attached to matching fixed/end-card layers
    # rather than creating a new watermark type.
    if mask_review:
        execution_segments = list(
            mask_review.get("execution_segments") or []
        )
        for layer in layers:
            if layer["type"] in {"fixed_strong", "end_card"}:
                layer["evidence"]["mask_review_execution_segment_count"] = len(
                    execution_segments
                )
                layer["evidence"]["mask_review_relative_path"] = (
                    req.mask_review_relative_path
                )

    profile_candidates = _profile_route_candidates(
        registry,
        req.brand_targets,
        req.relative_path,
    )

    # Deduplicate the known OCR promotional-text layer when a manually
    # validated tiled layer already explains the same brand family. Keep it as
    # informational evidence, but do not allow it to become a removal handler.
    if any(layer["type"] == "diagonal_tiled" for layer in layers):
        for layer in layers:
            if layer["type"] == "unclassified_brand_text":
                layer["status"] = "REVIEW"
                layer["notes"] = (
                    "Retained as informational OCR evidence only. A validated "
                    "tiled-watermark layer exists; do not erase this region automatically."
                )

    # No OCR, fixed-region, flow, grid, or profile evidence is a clean
    # detection outcome, not an "unknown watermark". Earlier versions added a
    # zero-confidence empty placeholder here. Production then treated that
    # placeholder as a real source mark and blocked videos that had no
    # detectable watermark at all.
    watermark_evidence_found = bool(layers)
    overall_status = (
        _overall_route_status(layers)
        if watermark_evidence_found
        else "NO_WATERMARK_EVIDENCE"
    )

    # Safe processing plan: only AUTO layers are eligible for unattended
    # rendering. REVIEW/CALIBRATION layers are never silently rendered.
    auto_layers = [
        layer["layer_id"]
        for layer in layers
        if layer["status"] == "AUTO"
    ]
    review_layers = [
        layer["layer_id"]
        for layer in layers
        if layer["status"] == "REVIEW"
    ]
    calibration_layers = [
        layer["layer_id"]
        for layer in layers
        if layer["status"] == "CALIBRATION_REQUIRED"
    ]

    timestamp = _app_now().strftime("%Y-%m-%d_%H%M%S")
    out_dir = (
        WORKSPACE
        / "review"
        / "branding_watermark_router"
        / timestamp
        / video_path.stem
    )
    out_dir.mkdir(parents=True, exist_ok=True)

    result = {
        "ok": True,
        "version": "0.17.0",
        "mode": "branding_watermark_router",
        "source": {
            "relative_path": video_path.relative_to(WORKSPACE).as_posix(),
        },
        "video": metadata,
        "brand_targets": list(req.brand_targets or []),
        "routing_policy": {
            "auto_threshold": float(req.auto_threshold),
            "review_threshold": float(req.review_threshold),
            "never_force_unknown_profile": True,
            "same_video_can_have_multiple_watermark_layers": True,
            "only_auto_layers_are_renderer_eligible": True,
        },
        "summary": {
            "watermark_layer_count": len(layers),
            "watermark_evidence_found": watermark_evidence_found,
            "auto_layer_count": len(auto_layers),
            "review_layer_count": len(review_layers),
            "calibration_required_layer_count": len(calibration_layers),
            "overall_status": overall_status,
            "source_video_modified": False,
            "full_processed_video_created": False,
        },
        "watermark_layers": layers,
        "renderer_eligibility": {
            "AUTO": auto_layers,
            "REVIEW": review_layers,
            "CALIBRATION_REQUIRED": calibration_layers,
        },
        "profile_registry": {
            "relative_path": (
                _watermark_profile_registry_path()
                .relative_to(WORKSPACE)
                .as_posix()
            ),
            "profile_count": len(registry.get("profiles") or []),
            "matching_profile_candidates": profile_candidates,
            "profile_registration": profile_registration,
        },
        "evidence_reports": {
            "census": req.census_report_relative_path,
            "mask_review": req.mask_review_relative_path,
            "three_anchor_grid": req.three_anchor_grid_report_relative_path,
            "flow_track": req.flow_track_report_relative_path,
        },
        "next_action": (
            "No watermark evidence was found; continue with editorial processing."
            if not watermark_evidence_found
            else "Proceed only with handler-specific preview/render work for AUTO layers. "
            "REVIEW layers require visual confirmation; CALIBRATION_REQUIRED layers "
            "must not be automatically removed."
        ),
    }

    report_path = (
        out_dir
        / f"{video_path.stem}.watermark-route.json"
    )
    result["report_relative_path"] = (
        report_path.relative_to(WORKSPACE).as_posix()
    )
    result["output_relative_dir"] = (
        out_dir.relative_to(WORKSPACE).as_posix()
    )

    report_path.write_text(
        json.dumps(
            result,
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )

    return result




class BrandingAutoWatermarkPreviewRequest(BaseModel):
    router_report_relative_path: str

    # Empty => all router AUTO layers.
    selected_layer_ids: list[str] = Field(default_factory=list)

    # Safety valve. REVIEW layers are rejected unless explicitly allowed.
    allow_review_layers: bool = False

    # Representative HQ motion previews.
    clip_seconds: float = 2.0
    combined_clip_count: int = 3

    # Fixed strong watermark mask extraction.
    fixed_mask_scan_interval_seconds: float = 1.0
    fixed_mask_max_frames: int = 120
    fixed_mask_response_percentile: float = 68.0
    fixed_mask_dilate_iterations: int = 1

    fixed_inpaint_radius: float = 3.0
    tiled_inpaint_radius: float = 2.0

    crf: int = 15
    preset: str = "slow"
    side_by_side: bool = True


def _router_layer_map(router_report):
    return {
        str(layer.get("layer_id")): layer
        for layer in (router_report.get("watermark_layers") or [])
        if layer.get("layer_id")
    }


def _router_selected_layers(router_report, req):
    layer_map = _router_layer_map(router_report)
    eligibility = router_report.get("renderer_eligibility") or {}
    auto_ids = [str(x) for x in (eligibility.get("AUTO") or [])]

    selected_ids = (
        [str(x) for x in req.selected_layer_ids]
        if req.selected_layer_ids
        else auto_ids
    )

    if not selected_ids:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "auto_watermark_preview",
                "error": "no_layers_selected",
                "auto_layer_ids": auto_ids,
            },
        )

    missing = [x for x in selected_ids if x not in layer_map]
    if missing:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "auto_watermark_preview",
                "error": "layer_id_not_found",
                "missing_layer_ids": missing,
            },
        )

    if not req.allow_review_layers:
        unsafe = [
            x
            for x in selected_ids
            if str(layer_map[x].get("status")) != "AUTO"
        ]
        if unsafe:
            raise HTTPException(
                status_code=422,
                detail={
                    "stage": "auto_watermark_preview",
                    "error": "non_auto_layer_rejected",
                    "layer_ids": unsafe,
                    "hint": (
                        "Only AUTO layers are accepted unless "
                        "allow_review_layers=true."
                    ),
                },
            )

    return [layer_map[x] for x in selected_ids]


def _fixed_strong_mask_from_video(
    video_path,
    bbox,
    scan_interval_seconds,
    max_frames,
    response_percentile,
    dilate_iterations,
):
    cap = cv2.VideoCapture(str(video_path))
    if not cap.isOpened():
        raise HTTPException(
            status_code=422,
            detail="Could not open source video.",
        )

    try:
        metadata = _video_metadata(cap)
        width = int(metadata.get("width") or 0)
        height = int(metadata.get("height") or 0)
        duration = float(metadata.get("duration_seconds") or 0.0)

        b = _clip_bbox(bbox, width, height)

        # Keep a small safety margin so OCR bbox jitter does not cut strokes.
        pad_x = max(2, int(round(b["width"] * 0.04)))
        pad_y = max(2, int(round(b["height"] * 0.08)))
        roi = _expanded_bbox(
            b,
            max(pad_x, pad_y),
            width,
            height,
        )

        soft_sum = np.zeros(
            (roi["height"], roi["width"]),
            dtype=np.float32,
        )
        hard_count = np.zeros(
            (roi["height"], roi["width"]),
            dtype=np.uint16,
        )

        frame_count = 0
        t = 0.0

        interval = max(
            float(scan_interval_seconds),
            duration / float(max(1, int(max_frames)))
            if duration > 0
            else float(scan_interval_seconds),
        )

        while (
            (duration <= 0 or t <= duration + 1e-9)
            and frame_count < int(max_frames)
        ):
            cap.set(
                cv2.CAP_PROP_POS_MSEC,
                float(t) * 1000.0,
            )
            ok, frame = cap.read()
            if not ok or frame is None:
                t += interval
                continue

            crop = frame[
                roi["y"]:roi["y"] + roi["height"],
                roi["x"]:roi["x"] + roi["width"],
            ]
            if crop.size == 0:
                t += interval
                continue

            response = _overlay_frame_response(
                crop,
                [15, 31],
            )

            positive = response[response > 0]
            if positive.size:
                thr = float(
                    np.percentile(
                        positive,
                        86.0,
                    )
                )
            else:
                thr = 1.0

            soft_sum += response
            hard_count += (
                response >= thr
            ).astype(np.uint16)

            frame_count += 1
            t += interval

        if frame_count == 0:
            raise HTTPException(
                status_code=422,
                detail="No frames were sampled for fixed watermark mask.",
            )

        mean_soft = soft_sum / float(frame_count)
        hard_ratio = (
            hard_count.astype(np.float32)
            / float(frame_count)
        )

        persistent = mean_soft * (
            0.25 + 0.75 * hard_ratio
        )
        persistent = cv2.GaussianBlur(
            persistent,
            (3, 3),
            0,
        )

        persistent_u8 = _normalize_u8(persistent)
        positive = persistent_u8[persistent_u8 > 0]
        if positive.size:
            threshold = float(
                np.percentile(
                    positive,
                    float(response_percentile),
                )
            )
        else:
            threshold = 255.0

        _, local_mask = cv2.threshold(
            persistent_u8,
            threshold,
            255,
            cv2.THRESH_BINARY,
        )

        local_mask = cv2.morphologyEx(
            local_mask,
            cv2.MORPH_CLOSE,
            np.ones((3, 3), dtype=np.uint8),
            iterations=1,
        )

        if int(dilate_iterations) > 0:
            local_mask = cv2.dilate(
                local_mask,
                np.ones((3, 3), dtype=np.uint8),
                iterations=int(dilate_iterations),
            )

        full_mask = np.zeros(
            (height, width),
            dtype=np.uint8,
        )
        full_mask[
            roi["y"]:roi["y"] + roi["height"],
            roi["x"]:roi["x"] + roi["width"],
        ] = local_mask

        return {
            "mask": full_mask,
            "persistent_u8": persistent_u8,
            "roi": roi,
            "frames_sampled": frame_count,
            "effective_interval_seconds": round(interval, 4),
            "threshold": round(threshold, 4),
            "coverage_ratio": round(
                float(np.count_nonzero(full_mask))
                / float(max(1, width * height)),
                8,
            ),
        }
    finally:
        cap.release()


def _load_tiled_mask_from_layer(layer, router_report, video_width, video_height):
    evidence = layer.get("evidence") or {}

    report_rel = (
        evidence.get("report_relative_path")
        or (
            (router_report.get("evidence_reports") or {})
            .get("three_anchor_grid")
        )
    )
    if not report_rel:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "auto_watermark_preview",
                "error": "missing_three_anchor_report",
                "layer_id": layer.get("layer_id"),
            },
        )

    report_path = _safe_workspace_path(report_rel)
    try:
        report = json.loads(
            report_path.read_text(encoding="utf-8")
        )
    except Exception as exc:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "auto_watermark_preview",
                "error": "invalid_three_anchor_report",
                "message": str(exc)[:500],
            },
        )

    diagnostics = report.get("diagnostic_images") or {}
    mask_rel = diagnostics.get("full_grid_mask")
    if not mask_rel:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "auto_watermark_preview",
                "error": "three_anchor_report_has_no_full_grid_mask",
            },
        )

    mask_path = _safe_workspace_path(mask_rel)
    mask = cv2.imread(
        str(mask_path),
        cv2.IMREAD_GRAYSCALE,
    )
    if mask is None:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "auto_watermark_preview",
                "error": "could_not_read_full_grid_mask",
                "mask_relative_path": mask_rel,
            },
        )

    if mask.shape[:2] != (
        int(video_height),
        int(video_width),
    ):
        mask = cv2.resize(
            mask,
            (int(video_width), int(video_height)),
            interpolation=cv2.INTER_NEAREST,
        )

    return {
        "mask": mask,
        "report_relative_path": report_rel,
        "mask_relative_path": mask_rel,
        "coverage_ratio": round(
            float(np.count_nonzero(mask))
            / float(max(1, int(video_width) * int(video_height))),
            8,
        ),
    }


def _representative_preview_times(router_report, selected_layers, duration, count):
    times = []

    census_rel = (
        (router_report.get("evidence_reports") or {})
        .get("census")
    )
    census = None
    if census_rel:
        try:
            census_path = _safe_workspace_path(census_rel)
            census = json.loads(
                census_path.read_text(encoding="utf-8")
            )
        except Exception:
            census = None

    if census:
        clusters = {
            int(c.get("cluster_id") or -1): c
            for c in (census.get("clusters") or [])
        }

        # Prefer strong fixed-watermark observation times so the combined
        # preview actually contains the top logo when that layer is selected.
        for layer in selected_layers:
            if layer.get("type") != "fixed_strong":
                continue

            cid = int(
                ((layer.get("evidence") or {}).get("cluster_id"))
                or -1
            )
            cluster = clusters.get(cid)
            if cluster:
                sample_times = [
                    float(x)
                    for x in (cluster.get("sample_times") or [])
                ]
                sample_times = [
                    x
                    for x in sample_times
                    if x >= 0.5
                    and (
                        duration <= 0
                        or x <= max(0.5, duration - 6.0)
                    )
                ]

                if sample_times:
                    if len(sample_times) <= int(count):
                        times.extend(sample_times)
                    else:
                        indexes = np.linspace(
                            0,
                            len(sample_times) - 1,
                            int(count),
                        ).round().astype(int)
                        times.extend(
                            sample_times[int(i)]
                            for i in indexes
                        )
                    break

    if not times:
        usable_end = (
            max(1.0, duration - 6.0)
            if duration > 8.0
            else max(1.0, duration)
        )
        start = min(5.0, usable_end * 0.15)
        end = max(start, usable_end)
        times = np.linspace(
            start,
            end,
            int(count),
        ).tolist()

    # Dedupe and limit.
    result = []
    for t in times:
        t = max(0.0, float(t))
        if duration > 0:
            t = min(t, max(0.0, duration - 0.1))
        if not any(abs(t - old) < 0.25 for old in result):
            result.append(t)

    return result[: int(count)]


def _apply_watermark_layer_masks(frame, layer_masks):
    processed = frame.copy()

    for item in layer_masks:
        mask = item["mask"]
        radius = float(item["inpaint_radius"])

        if int(np.count_nonzero(mask)) == 0:
            continue

        processed = cv2.inpaint(
            processed,
            mask,
            radius,
            cv2.INPAINT_TELEA,
        )

    return processed


def _render_mask_compare_clip(
    video_path,
    out_path,
    center_time,
    clip_seconds,
    layer_masks,
    fps,
    width,
    height,
    duration,
    crf,
    preset,
    side_by_side,
    right_label,
):
    half = float(clip_seconds) / 2.0
    clip_start = max(0.0, float(center_time) - half)
    clip_end = float(center_time) + half

    if duration > 0:
        clip_end = min(duration, clip_end)

    out_width = width * 2 if side_by_side else width
    out_height = height

    writer, runtime = _open_x264_raw_writer(
        out_path,
        out_width,
        out_height,
        fps,
        int(crf),
        str(preset),
    )

    cap = cv2.VideoCapture(str(video_path))
    if not cap.isOpened():
        try:
            writer.stdin.close()
        except Exception:
            pass
        writer.kill()
        raise HTTPException(
            status_code=422,
            detail="Could not open source video for preview.",
        )

    cap.set(
        cv2.CAP_PROP_POS_MSEC,
        clip_start * 1000.0,
    )

    frame_index = 0
    frames_written = 0
    write_error = None

    try:
        while True:
            ok, frame = cap.read()
            if not ok or frame is None:
                break

            current_t = clip_start + frame_index / float(fps)
            if current_t > clip_end + 0.5 / float(fps):
                break

            processed = _apply_watermark_layer_masks(
                frame,
                layer_masks,
            )

            if side_by_side:
                left = _label_pane(
                    frame,
                    "ORIGINAL",
                )
                right = _label_pane(
                    processed,
                    right_label,
                )
                output_frame = np.hstack(
                    [left, right]
                )
            else:
                output_frame = processed

            try:
                writer.stdin.write(
                    output_frame.tobytes()
                )
            except Exception as exc:
                write_error = str(exc)[:500]
                break

            frames_written += 1
            frame_index += 1
    finally:
        cap.release()
        try:
            if writer.stdin:
                writer.stdin.close()
        except Exception:
            pass

    stderr = b""
    try:
        stderr = writer.stderr.read() if writer.stderr else b""
    except Exception:
        pass

    return_code = writer.wait()
    ok = (
        return_code == 0
        and write_error is None
        and out_path.exists()
    )

    return {
        "ok": ok,
        "center_time_seconds": round(float(center_time), 3),
        "clip_start_seconds": round(clip_start, 3),
        "clip_end_seconds": round(clip_end, 3),
        "frames_written": frames_written,
        "output_size": {
            "width": out_width,
            "height": out_height,
        },
        "relative_path": (
            out_path.relative_to(WORKSPACE).as_posix()
            if out_path.exists()
            else None
        ),
        "encoder": {
            "engine": "ffmpeg",
            "codec": "libx264",
            "crf": int(crf),
            "preset": str(preset),
            "runtime": runtime,
        },
        "error": (
            write_error
            or (
                stderr.decode(
                    "utf-8",
                    errors="replace",
                )[:800]
                if return_code != 0
                else None
            )
        ),
    }


def _auto_watermark_preview_sync(req: BrandingAutoWatermarkPreviewRequest):
    router_path = _safe_workspace_path(
        req.router_report_relative_path
    )
    try:
        router = json.loads(
            router_path.read_text(encoding="utf-8")
        )
    except Exception as exc:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "auto_watermark_preview",
                "error": "invalid_router_report",
                "message": str(exc)[:500],
            },
        )

    if router.get("mode") != "branding_watermark_router":
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "auto_watermark_preview",
                "error": "wrong_router_report_mode",
                "actual": router.get("mode"),
            },
        )

    source_rel = (
        (router.get("source") or {})
        .get("relative_path")
    )
    if not source_rel:
        raise HTTPException(
            status_code=422,
            detail="Router report has no source.relative_path.",
        )

    video_path = _safe_workspace_path(source_rel)

    selected_layers = _router_selected_layers(
        router,
        req,
    )

    supported = {
        "fixed_strong_roi",
        "diagonal_tiled_grid",
    }
    unsupported = [
        layer.get("layer_id")
        for layer in selected_layers
        if layer.get("handler") not in supported
    ]
    if unsupported:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "auto_watermark_preview",
                "error": "selected_handler_not_supported_in_v0.9.14",
                "layer_ids": unsupported,
                "supported_handlers": sorted(supported),
            },
        )

    if not 0.75 <= float(req.clip_seconds) <= 5.0:
        raise HTTPException(
            status_code=422,
            detail="clip_seconds must be between 0.75 and 5.",
        )

    if not 1 <= int(req.combined_clip_count) <= 6:
        raise HTTPException(
            status_code=422,
            detail="combined_clip_count must be between 1 and 6.",
        )

    if not 8 <= int(req.crf) <= 28:
        raise HTTPException(
            status_code=422,
            detail="crf must be between 8 and 28.",
        )

    allowed_presets = {
        "ultrafast",
        "superfast",
        "veryfast",
        "faster",
        "fast",
        "medium",
        "slow",
        "slower",
        "veryslow",
    }
    if str(req.preset) not in allowed_presets:
        raise HTTPException(
            status_code=422,
            detail={
                "error": "unsupported_x264_preset",
                "allowed": sorted(allowed_presets),
            },
        )

    cap = cv2.VideoCapture(str(video_path))
    if not cap.isOpened():
        raise HTTPException(
            status_code=422,
            detail="Could not open source video.",
        )

    try:
        metadata = _video_metadata(cap)
    finally:
        cap.release()

    fps = float(metadata.get("fps") or 30.0)
    width = int(metadata.get("width") or 0)
    height = int(metadata.get("height") or 0)
    duration = float(metadata.get("duration_seconds") or 0.0)

    timestamp = _app_now().strftime(
        "%Y-%m-%d_%H%M%S"
    )
    out_dir = (
        WORKSPACE
        / "review"
        / "branding_auto_watermark_preview"
        / timestamp
        / video_path.stem
    )
    out_dir.mkdir(
        parents=True,
        exist_ok=True,
    )

    layer_masks = []
    layer_results = []

    # Build masks once, then render representative clips.
    for layer in selected_layers:
        layer_id = str(layer["layer_id"])
        handler = str(layer["handler"])

        if handler == "fixed_strong_roi":
            evidence = layer.get("evidence") or {}
            bbox = evidence.get("bbox")
            if not bbox:
                raise HTTPException(
                    status_code=422,
                    detail={
                        "stage": "auto_watermark_preview",
                        "error": "fixed_layer_missing_bbox",
                        "layer_id": layer_id,
                    },
                )

            fixed = _fixed_strong_mask_from_video(
                video_path,
                bbox,
                float(req.fixed_mask_scan_interval_seconds),
                int(req.fixed_mask_max_frames),
                float(req.fixed_mask_response_percentile),
                int(req.fixed_mask_dilate_iterations),
            )

            mask_path = (
                out_dir
                / f"{layer_id}.mask.png"
            )
            persistent_path = (
                out_dir
                / f"{layer_id}.persistent-response.png"
            )
            cv2.imwrite(
                str(mask_path),
                fixed["mask"],
            )
            cv2.imwrite(
                str(persistent_path),
                fixed["persistent_u8"],
            )

            layer_masks.append(
                {
                    "layer_id": layer_id,
                    "type": layer.get("type"),
                    "handler": handler,
                    "mask": fixed["mask"],
                    "mask_relative_path": (
                        mask_path
                        .relative_to(WORKSPACE)
                        .as_posix()
                    ),
                    "coverage_ratio": fixed["coverage_ratio"],
                    "inpaint_radius": float(
                        req.fixed_inpaint_radius
                    ),
                }
            )

            layer_results.append(
                {
                    "layer_id": layer_id,
                    "type": layer.get("type"),
                    "handler": handler,
                    "mask_relative_path": (
                        mask_path
                        .relative_to(WORKSPACE)
                        .as_posix()
                    ),
                    "persistent_response_relative_path": (
                        persistent_path
                        .relative_to(WORKSPACE)
                        .as_posix()
                    ),
                    "mask_coverage_ratio": fixed["coverage_ratio"],
                    "fixed_mask_roi": fixed["roi"],
                    "fixed_mask_frames_sampled": fixed["frames_sampled"],
                    "fixed_mask_effective_interval_seconds": (
                        fixed["effective_interval_seconds"]
                    ),
                    "fixed_mask_threshold": fixed["threshold"],
                }
            )

        elif handler == "diagonal_tiled_grid":
            tiled = _load_tiled_mask_from_layer(
                layer,
                router,
                width,
                height,
            )

            layer_masks.append(
                {
                    "layer_id": layer_id,
                    "type": layer.get("type"),
                    "handler": handler,
                    "mask": tiled["mask"],
                    "mask_relative_path": tiled[
                        "mask_relative_path"
                    ],
                    "coverage_ratio": tiled[
                        "coverage_ratio"
                    ],
                    "inpaint_radius": float(
                        req.tiled_inpaint_radius
                    ),
                }
            )

            layer_results.append(
                {
                    "layer_id": layer_id,
                    "type": layer.get("type"),
                    "handler": handler,
                    "mask_relative_path": tiled[
                        "mask_relative_path"
                    ],
                    "three_anchor_report_relative_path": tiled[
                        "report_relative_path"
                    ],
                    "mask_coverage_ratio": tiled[
                        "coverage_ratio"
                    ],
                }
            )

    # Combined mask diagnostic.
    combined_mask = np.zeros(
        (height, width),
        dtype=np.uint8,
    )
    for item in layer_masks:
        np.maximum(
            combined_mask,
            item["mask"],
            out=combined_mask,
        )

    combined_mask_path = (
        out_dir
        / "combined_auto_layers.mask.png"
    )
    cv2.imwrite(
        str(combined_mask_path),
        combined_mask,
    )

    # Build one still overlay for fast mask inspection.
    cap = cv2.VideoCapture(str(video_path))
    context = None
    context_time = (
        max(0.0, min(duration - 0.1, duration * 0.5))
        if duration > 0
        else 0.0
    )
    if cap.isOpened():
        cap.set(
            cv2.CAP_PROP_POS_MSEC,
            context_time * 1000.0,
        )
        ok, frame = cap.read()
        if ok and frame is not None:
            context = frame
    cap.release()

    overlay_rel = None
    if context is not None:
        overlay = context.copy()
        alpha = (
            combined_mask.astype(np.float32)
            / 255.0
            * 0.55
        )[..., None]
        white = np.full_like(
            overlay,
            255,
        )
        overlay = (
            overlay.astype(np.float32)
            * (1.0 - alpha)
            + white.astype(np.float32)
            * alpha
        ).astype(np.uint8)

        overlay_path = (
            out_dir
            / "combined_auto_layers.mask-overlay.jpg"
        )
        cv2.imwrite(
            str(overlay_path),
            overlay,
        )
        overlay_rel = (
            overlay_path
            .relative_to(WORKSPACE)
            .as_posix()
        )

    sample_times = _representative_preview_times(
        router,
        selected_layers,
        duration,
        int(req.combined_clip_count),
    )

    # One isolated clip per layer, using the middle representative time.
    isolated_time = sample_times[
        len(sample_times) // 2
    ]

    for layer_result in layer_results:
        layer_id = layer_result["layer_id"]
        item = next(
            x
            for x in layer_masks
            if x["layer_id"] == layer_id
        )

        clip_path = (
            out_dir
            / f"{layer_id}.isolated-hq-compare.mp4"
        )

        clip = _render_mask_compare_clip(
            video_path,
            clip_path,
            isolated_time,
            float(req.clip_seconds),
            [item],
            fps,
            width,
            height,
            duration,
            int(req.crf),
            str(req.preset),
            bool(req.side_by_side),
            f"{layer_id} ONLY",
        )
        layer_result["isolated_preview"] = clip

    combined_clips = []

    for idx, sample_time in enumerate(
        sample_times,
        1,
    ):
        clip_path = (
            out_dir
            / f"combined_auto_{idx:02d}_hq_compare.mp4"
        )

        combined_clips.append(
            _render_mask_compare_clip(
                video_path,
                clip_path,
                sample_time,
                float(req.clip_seconds),
                layer_masks,
                fps,
                width,
                height,
                duration,
                int(req.crf),
                str(req.preset),
                bool(req.side_by_side),
                "AUTO LAYERS",
            )
        )

    clips_created = sum(
        1
        for item in combined_clips
        if item["ok"]
    ) + sum(
        1
        for item in layer_results
        if (
            item.get("isolated_preview")
            and item["isolated_preview"].get("ok")
        )
    )

    clips_requested = (
        len(combined_clips)
        + len(layer_results)
    )

    result = {
        "ok": clips_created > 0,
        "version": "0.17.0",
        "mode": "branding_auto_watermark_preview",
        "source": {
            "relative_path": source_rel,
            "router_report_relative_path": (
                router_path
                .relative_to(WORKSPACE)
                .as_posix()
            ),
        },
        "video": metadata,
        "selection": {
            "selected_layer_ids": [
                layer["layer_id"]
                for layer in selected_layers
            ],
            "all_selected_layers_were_auto": all(
                str(layer.get("status")) == "AUTO"
                for layer in selected_layers
            ),
            "allow_review_layers": bool(
                req.allow_review_layers
            ),
        },
        "summary": {
            "selected_layer_count": len(selected_layers),
            "mask_count": len(layer_masks),
            "isolated_preview_count": len(layer_results),
            "combined_preview_count": len(combined_clips),
            "clips_requested": clips_requested,
            "clips_created": clips_created,
            "clips_failed": clips_requested - clips_created,
            "source_video_modified": False,
            "full_processed_video_created": False,
            "manual_hq_review_required": True,
        },
        "layer_renders": layer_results,
        "combined_preview": {
            "sample_times_seconds": [
                round(float(x), 3)
                for x in sample_times
            ],
            "combined_mask_relative_path": (
                combined_mask_path
                .relative_to(WORKSPACE)
                .as_posix()
            ),
            "combined_mask_overlay_relative_path": overlay_rel,
            "combined_mask_coverage_ratio": round(
                float(np.count_nonzero(combined_mask))
                / float(max(1, width * height)),
                8,
            ),
            "clips": combined_clips,
        },
        "quality_policy": {
            "codec": "libx264",
            "crf": int(req.crf),
            "preset": str(req.preset),
            "source_resolution_per_pane": bool(
                req.side_by_side
            ),
            "note": (
                "This is a preview-only renderer. It does not process REVIEW "
                "layers such as end cards or unclassified promotional text."
            ),
        },
        "output_relative_dir": (
            out_dir.relative_to(WORKSPACE).as_posix()
        ),
        "next_action": (
            "Visually review isolated and combined HQ clips. "
            "If the diagonal tiled mask removes the faint ReelShort pattern "
            "without damaging people/subtitles/background, and the fixed logo "
            "mask is clean, these two AUTO handlers are ready for a full-video "
            "renderer. REVIEW layers remain untouched."
        ),
    }

    report_path = (
        out_dir
        / f"{video_path.stem}.auto-watermark-preview.json"
    )
    result["report_relative_path"] = (
        report_path.relative_to(WORKSPACE).as_posix()
    )

    report_path.write_text(
        json.dumps(
            result,
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )

    return result




class BrandingWatermarkRemediationPreviewRequest(BaseModel):
    router_report_relative_path: str

    # Current supported handlers:
    # fixed_strong_roi -> legacy segment-aware local inpaint
    # diagonal_tiled_grid -> alpha deblend strength comparison
    fixed_layer_id: str = "census-1-fixed-strong"
    tiled_layer_id: str = "three-anchor-grid"

    clip_seconds: float = 2.0
    tiled_sample_count: int = 3

    # Semi-transparent white-overlay inversion strengths.
    # These are maximum alpha values, NOT generic inpaint strengths.
    tiled_max_alpha_values: list[float] = Field(
        default_factory=lambda: [0.04, 0.08, 0.12]
    )
    tiled_alpha_gamma: float = 1.15

    # Fixed logo: return to the previously reviewed segment geometry instead
    # of the v0.9.14 full-video persistent sparse mask.
    fixed_inpaint_radius: float = 3.0
    fixed_segment_padding_px: int = 2
    fixed_preview_count: int = 3

    crf: int = 15
    preset: str = "slow"


def _read_json_workspace(relative_path, stage):
    path = _safe_workspace_path(relative_path)
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except Exception as exc:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": stage,
                "error": "invalid_json_report",
                "relative_path": relative_path,
                "message": str(exc)[:500],
            },
        )
    return path, data


def _find_router_layer(router, layer_id):
    for layer in router.get("watermark_layers") or []:
        if str(layer.get("layer_id")) == str(layer_id):
            return layer
    raise HTTPException(
        status_code=422,
        detail={
            "stage": "watermark_remediation_preview",
            "error": "router_layer_not_found",
            "layer_id": layer_id,
        },
    )


def _load_three_anchor_alpha_basis(layer, router, width, height):
    evidence = layer.get("evidence") or {}
    report_rel = (
        evidence.get("report_relative_path")
        or (
            (router.get("evidence_reports") or {})
            .get("three_anchor_grid")
        )
    )

    if not report_rel:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "watermark_remediation_preview",
                "error": "missing_three_anchor_report",
            },
        )

    _, report = _read_json_workspace(
        report_rel,
        "watermark_remediation_preview",
    )

    diagnostics = report.get("diagnostic_images") or {}
    template_rel = diagnostics.get(
        "three_anchor_persistent_template"
    )
    tile_mask_rel = diagnostics.get(
        "tile_stroke_mask"
    )

    if not template_rel or not tile_mask_rel:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "watermark_remediation_preview",
                "error": "three_anchor_report_missing_template_or_mask",
            },
        )

    template = cv2.imread(
        str(_safe_workspace_path(template_rel)),
        cv2.IMREAD_GRAYSCALE,
    )
    tile_mask = cv2.imread(
        str(_safe_workspace_path(tile_mask_rel)),
        cv2.IMREAD_GRAYSCALE,
    )

    if template is None or tile_mask is None:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "watermark_remediation_preview",
                "error": "could_not_read_three_anchor_template",
            },
        )

    if tile_mask.shape != template.shape:
        tile_mask = cv2.resize(
            tile_mask,
            (template.shape[1], template.shape[0]),
            interpolation=cv2.INTER_NEAREST,
        )

    template_f = template.astype(np.float32) / 255.0
    mask_f = (tile_mask.astype(np.float32) / 255.0)

    # Keep the learned stroke response only where v0.9.12 marked watermark
    # strokes. This is intentionally sparse.
    tile_alpha_basis = template_f * mask_f

    # Normalize only inside positive strokes.
    positive = tile_alpha_basis[tile_alpha_basis > 0]
    if positive.size:
        lo = float(np.percentile(positive, 20.0))
        hi = float(np.percentile(positive, 98.0))
        if hi > lo + 1e-6:
            tile_alpha_basis = np.clip(
                (tile_alpha_basis - lo) / (hi - lo),
                0.0,
                1.0,
            )
        else:
            tile_alpha_basis = (
                tile_alpha_basis > 0
            ).astype(np.float32)

    grid_points = (
        (report.get("grid") or {})
        .get("predicted_grid_points")
        or []
    )

    if not grid_points:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "watermark_remediation_preview",
                "error": "three_anchor_report_has_no_grid_points",
            },
        )

    full_basis = np.zeros(
        (int(height), int(width)),
        dtype=np.float32,
    )

    th, tw = tile_alpha_basis.shape[:2]

    for point in grid_points:
        center = point.get("center") or {}
        cx = float(center.get("x") or 0.0)
        cy = float(center.get("y") or 0.0)

        x1 = int(round(cx - tw / 2.0))
        y1 = int(round(cy - th / 2.0))
        x2 = x1 + tw
        y2 = y1 + th

        src_x1 = 0
        src_y1 = 0
        src_x2 = tw
        src_y2 = th

        if x1 < 0:
            src_x1 = -x1
            x1 = 0
        if y1 < 0:
            src_y1 = -y1
            y1 = 0
        if x2 > width:
            src_x2 -= x2 - width
            x2 = width
        if y2 > height:
            src_y2 -= y2 - height
            y2 = height

        if x2 <= x1 or y2 <= y1:
            continue

        target = full_basis[y1:y2, x1:x2]
        source = tile_alpha_basis[
            src_y1:src_y2,
            src_x1:src_x2,
        ]
        np.maximum(
            target,
            source,
            out=target,
        )

    return {
        "report_relative_path": report_rel,
        "template_relative_path": template_rel,
        "tile_mask_relative_path": tile_mask_rel,
        "alpha_basis": full_basis,
        "alpha_basis_coverage_ratio": round(
            float(np.count_nonzero(full_basis > 0.01))
            / float(max(1, width * height)),
            8,
        ),
        "grid_point_count": len(grid_points),
    }


def _white_overlay_deblend(frame, alpha_basis, max_alpha, gamma):
    # Model:
    # observed = alpha*255 + (1-alpha)*background
    # background = (observed - alpha*255)/(1-alpha)
    #
    # For faint white ReelShort tiles, this preserves underlying structure
    # much better than treating watermark pixels as missing pixels.
    strength = float(max_alpha)
    alpha = np.clip(
        np.power(
            np.clip(alpha_basis, 0.0, 1.0),
            float(gamma),
        ) * strength,
        0.0,
        0.35,
    )

    alpha3 = alpha[..., None]
    observed = frame.astype(np.float32)

    denom = np.maximum(
        1.0 - alpha3,
        0.55,
    )

    restored = (
        observed - alpha3 * 255.0
    ) / denom

    # Outside the sparse alpha basis, preserve exact source pixels.
    restored = np.where(
        alpha3 > 1e-7,
        restored,
        observed,
    )

    return np.clip(
        restored,
        0,
        255,
    ).astype(np.uint8)


def _segment_bbox_mask(width, height, bbox, padding_px):
    b = _clip_bbox(
        bbox,
        int(width),
        int(height),
    )
    pad = max(0, int(padding_px))

    x1 = max(0, int(b["x"]) - pad)
    y1 = max(0, int(b["y"]) - pad)
    x2 = min(
        int(width),
        int(b["x"]) + int(b["width"]) + pad,
    )
    y2 = min(
        int(height),
        int(b["y"]) + int(b["height"]) + pad,
    )

    mask = np.zeros(
        (int(height), int(width)),
        dtype=np.uint8,
    )
    mask[y1:y2, x1:x2] = 255

    return mask


def _load_fixed_execution_segments(layer, source_rel):
    evidence = layer.get("evidence") or {}
    review_rel = evidence.get(
        "mask_review_relative_path"
    )

    if not review_rel:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "watermark_remediation_preview",
                "error": "fixed_layer_missing_mask_review",
                "layer_id": layer.get("layer_id"),
            },
        )

    _, review = _read_json_workspace(
        review_rel,
        "watermark_remediation_preview",
    )

    source = (
        (review.get("source") or {})
        .get("relative_path")
    )
    if (
        source
        and str(source) != str(source_rel)
    ):
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "watermark_remediation_preview",
                "error": "fixed_mask_review_source_mismatch",
                "router_source": source_rel,
                "review_source": source,
            },
        )

    segments = []

    for item in review.get("execution_segments") or []:
        start = (
            item.get("start_seconds")
            if item.get("start_seconds") is not None
            else item.get("start")
        )
        end = (
            item.get("end_seconds")
            if item.get("end_seconds") is not None
            else item.get("end")
        )
        bbox = (
            item.get("stable_bbox")
            or item.get("bbox")
        )

        if start is None or end is None or not bbox:
            continue

        # Exclude the large end-card segment from the fixed-logo handler.
        area = (
            float(bbox.get("width") or 0)
            * float(bbox.get("height") or 0)
        )
        if area > 40000:
            continue

        segments.append(
            {
                "start_seconds": float(start),
                "end_seconds": float(end),
                "bbox": {
                    "x": int(bbox.get("x") or 0),
                    "y": int(bbox.get("y") or 0),
                    "width": int(bbox.get("width") or 0),
                    "height": int(bbox.get("height") or 0),
                },
            }
        )

    if not segments:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "watermark_remediation_preview",
                "error": "no_fixed_logo_execution_segments",
                "mask_review_relative_path": review_rel,
            },
        )

    return {
        "mask_review_relative_path": review_rel,
        "segments": segments,
    }


def _active_fixed_segment(segments, time_seconds):
    t = float(time_seconds)
    for segment in segments:
        if (
            float(segment["start_seconds"])
            <= t
            <= float(segment["end_seconds"])
        ):
            return segment
    return None


def _fixed_segment_preview_times(segments, count):
    mids = [
        (
            float(s["start_seconds"])
            + float(s["end_seconds"])
        ) / 2.0
        for s in segments
    ]

    if len(mids) <= int(count):
        return mids

    indexes = np.linspace(
        0,
        len(mids) - 1,
        int(count),
    ).round().astype(int)

    return [
        mids[int(i)]
        for i in indexes
    ]


def _tiled_preview_times(duration, count):
    usable_end = (
        max(2.0, duration - 7.0)
        if duration > 10.0
        else max(2.0, duration)
    )

    start = min(
        7.0,
        usable_end * 0.12,
    )
    middle = usable_end * 0.58
    end = usable_end * 0.92

    base = [start, middle, end]

    if int(count) <= 3:
        return base[: int(count)]

    return np.linspace(
        start,
        end,
        int(count),
    ).tolist()


def _open_custom_raw_x264_writer(
    out_path,
    width,
    height,
    fps,
    crf,
    preset,
):
    return _open_x264_raw_writer(
        out_path,
        int(width),
        int(height),
        float(fps),
        int(crf),
        str(preset),
    )


def _render_tiled_strength_compare(
    video_path,
    out_path,
    center_time,
    clip_seconds,
    alpha_basis,
    alpha_values,
    gamma,
    fps,
    width,
    height,
    duration,
    crf,
    preset,
):
    half = float(clip_seconds) / 2.0
    clip_start = max(
        0.0,
        float(center_time) - half,
    )
    clip_end = float(center_time) + half

    if duration > 0:
        clip_end = min(
            duration,
            clip_end,
        )

    pane_count = 1 + len(alpha_values)
    out_width = int(width) * pane_count
    out_height = int(height)

    writer, runtime = _open_custom_raw_x264_writer(
        out_path,
        out_width,
        out_height,
        fps,
        crf,
        preset,
    )

    cap = cv2.VideoCapture(str(video_path))
    if not cap.isOpened():
        try:
            writer.stdin.close()
        except Exception:
            pass
        writer.kill()
        raise HTTPException(
            status_code=422,
            detail="Could not open source video for tiled comparison.",
        )

    cap.set(
        cv2.CAP_PROP_POS_MSEC,
        clip_start * 1000.0,
    )

    frame_index = 0
    frames_written = 0
    write_error = None

    try:
        while True:
            ok, frame = cap.read()
            if not ok or frame is None:
                break

            current_t = (
                clip_start
                + frame_index / float(fps)
            )
            if (
                current_t
                > clip_end
                + 0.5 / float(fps)
            ):
                break

            panes = [
                _label_pane(
                    frame,
                    "ORIGINAL",
                )
            ]

            for alpha_value in alpha_values:
                restored = _white_overlay_deblend(
                    frame,
                    alpha_basis,
                    float(alpha_value),
                    float(gamma),
                )
                panes.append(
                    _label_pane(
                        restored,
                        f"ALPHA {float(alpha_value):.02f}",
                    )
                )

            output = np.hstack(panes)

            try:
                writer.stdin.write(
                    output.tobytes()
                )
            except Exception as exc:
                write_error = str(exc)[:500]
                break

            frames_written += 1
            frame_index += 1
    finally:
        cap.release()
        try:
            if writer.stdin:
                writer.stdin.close()
        except Exception:
            pass

    stderr = b""
    try:
        stderr = (
            writer.stderr.read()
            if writer.stderr
            else b""
        )
    except Exception:
        pass

    return_code = writer.wait()
    ok = (
        return_code == 0
        and write_error is None
        and out_path.exists()
    )

    return {
        "ok": ok,
        "center_time_seconds": round(
            float(center_time),
            3,
        ),
        "clip_start_seconds": round(
            clip_start,
            3,
        ),
        "clip_end_seconds": round(
            clip_end,
            3,
        ),
        "frames_written": frames_written,
        "pane_count": pane_count,
        "output_size": {
            "width": out_width,
            "height": out_height,
        },
        "relative_path": (
            out_path
            .relative_to(WORKSPACE)
            .as_posix()
            if out_path.exists()
            else None
        ),
        "alpha_values": [
            float(x)
            for x in alpha_values
        ],
        "alpha_gamma": float(gamma),
        "encoder": {
            "engine": "ffmpeg",
            "codec": "libx264",
            "crf": int(crf),
            "preset": str(preset),
            "runtime": runtime,
        },
        "error": (
            write_error
            or (
                stderr.decode(
                    "utf-8",
                    errors="replace",
                )[:800]
                if return_code != 0
                else None
            )
        ),
    }


def _render_fixed_legacy_compare(
    video_path,
    out_path,
    center_time,
    clip_seconds,
    segments,
    fps,
    width,
    height,
    duration,
    inpaint_radius,
    padding_px,
    crf,
    preset,
):
    half = float(clip_seconds) / 2.0
    clip_start = max(
        0.0,
        float(center_time) - half,
    )
    clip_end = float(center_time) + half

    if duration > 0:
        clip_end = min(
            duration,
            clip_end,
        )

    writer, runtime = _open_custom_raw_x264_writer(
        out_path,
        int(width) * 2,
        int(height),
        fps,
        crf,
        preset,
    )

    cap = cv2.VideoCapture(str(video_path))
    if not cap.isOpened():
        try:
            writer.stdin.close()
        except Exception:
            pass
        writer.kill()
        raise HTTPException(
            status_code=422,
            detail="Could not open source video for fixed-logo comparison.",
        )

    cap.set(
        cv2.CAP_PROP_POS_MSEC,
        clip_start * 1000.0,
    )

    frame_index = 0
    frames_written = 0
    frames_treated = 0
    write_error = None

    try:
        while True:
            ok, frame = cap.read()
            if not ok or frame is None:
                break

            current_t = (
                clip_start
                + frame_index / float(fps)
            )
            if (
                current_t
                > clip_end
                + 0.5 / float(fps)
            ):
                break

            processed = frame.copy()
            active = _active_fixed_segment(
                segments,
                current_t,
            )

            if active is not None:
                mask = _segment_bbox_mask(
                    width,
                    height,
                    active["bbox"],
                    int(padding_px),
                )
                processed = cv2.inpaint(
                    processed,
                    mask,
                    float(inpaint_radius),
                    cv2.INPAINT_TELEA,
                )
                frames_treated += 1

            output = np.hstack(
                [
                    _label_pane(
                        frame,
                        "ORIGINAL",
                    ),
                    _label_pane(
                        processed,
                        "SEGMENT ROI",
                    ),
                ]
            )

            try:
                writer.stdin.write(
                    output.tobytes()
                )
            except Exception as exc:
                write_error = str(exc)[:500]
                break

            frames_written += 1
            frame_index += 1
    finally:
        cap.release()
        try:
            if writer.stdin:
                writer.stdin.close()
        except Exception:
            pass

    stderr = b""
    try:
        stderr = (
            writer.stderr.read()
            if writer.stderr
            else b""
        )
    except Exception:
        pass

    return_code = writer.wait()
    ok = (
        return_code == 0
        and write_error is None
        and out_path.exists()
    )

    return {
        "ok": ok,
        "center_time_seconds": round(
            float(center_time),
            3,
        ),
        "clip_start_seconds": round(
            clip_start,
            3,
        ),
        "clip_end_seconds": round(
            clip_end,
            3,
        ),
        "frames_written": frames_written,
        "frames_treated": frames_treated,
        "relative_path": (
            out_path
            .relative_to(WORKSPACE)
            .as_posix()
            if out_path.exists()
            else None
        ),
        "encoder": {
            "engine": "ffmpeg",
            "codec": "libx264",
            "crf": int(crf),
            "preset": str(preset),
            "runtime": runtime,
        },
        "error": (
            write_error
            or (
                stderr.decode(
                    "utf-8",
                    errors="replace",
                )[:800]
                if return_code != 0
                else None
            )
        ),
    }


def _watermark_remediation_preview_sync(
    req: BrandingWatermarkRemediationPreviewRequest
):
    router_path, router = _read_json_workspace(
        req.router_report_relative_path,
        "watermark_remediation_preview",
    )

    if router.get("mode") != "branding_watermark_router":
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "watermark_remediation_preview",
                "error": "wrong_router_report_mode",
                "actual": router.get("mode"),
            },
        )

    source_rel = (
        (router.get("source") or {})
        .get("relative_path")
    )
    if not source_rel:
        raise HTTPException(
            status_code=422,
            detail="Router report has no source.relative_path.",
        )

    fixed_layer = _find_router_layer(
        router,
        req.fixed_layer_id,
    )
    tiled_layer = _find_router_layer(
        router,
        req.tiled_layer_id,
    )

    if str(fixed_layer.get("handler")) != "fixed_strong_roi":
        raise HTTPException(
            status_code=422,
            detail="fixed_layer_id is not a fixed_strong_roi layer.",
        )

    if str(tiled_layer.get("handler")) != "diagonal_tiled_grid":
        raise HTTPException(
            status_code=422,
            detail="tiled_layer_id is not a diagonal_tiled_grid layer.",
        )

    if str(fixed_layer.get("status")) != "AUTO":
        raise HTTPException(
            status_code=422,
            detail="Fixed layer must be AUTO for this preview.",
        )

    if str(tiled_layer.get("status")) != "AUTO":
        raise HTTPException(
            status_code=422,
            detail="Tiled layer must be AUTO for this preview.",
        )

    if not 0.75 <= float(req.clip_seconds) <= 5.0:
        raise HTTPException(
            status_code=422,
            detail="clip_seconds must be between 0.75 and 5.",
        )

    alpha_values = sorted(
        {
            round(float(x), 4)
            for x in req.tiled_max_alpha_values
        }
    )

    if not alpha_values:
        raise HTTPException(
            status_code=422,
            detail="tiled_max_alpha_values must not be empty.",
        )

    if len(alpha_values) > 5:
        raise HTTPException(
            status_code=422,
            detail="Use at most 5 tiled alpha values per comparison.",
        )

    if any(x <= 0 or x > 0.25 for x in alpha_values):
        raise HTTPException(
            status_code=422,
            detail="Each tiled alpha value must be > 0 and <= 0.25.",
        )

    if not 0.6 <= float(req.tiled_alpha_gamma) <= 2.5:
        raise HTTPException(
            status_code=422,
            detail="tiled_alpha_gamma must be between 0.6 and 2.5.",
        )

    if not 1 <= int(req.tiled_sample_count) <= 5:
        raise HTTPException(
            status_code=422,
            detail="tiled_sample_count must be between 1 and 5.",
        )

    if not 1 <= int(req.fixed_preview_count) <= 5:
        raise HTTPException(
            status_code=422,
            detail="fixed_preview_count must be between 1 and 5.",
        )

    if not 8 <= int(req.crf) <= 28:
        raise HTTPException(
            status_code=422,
            detail="crf must be between 8 and 28.",
        )

    allowed_presets = {
        "ultrafast",
        "superfast",
        "veryfast",
        "faster",
        "fast",
        "medium",
        "slow",
        "slower",
        "veryslow",
    }
    if str(req.preset) not in allowed_presets:
        raise HTTPException(
            status_code=422,
            detail={
                "error": "unsupported_x264_preset",
                "allowed": sorted(allowed_presets),
            },
        )

    video_path = _safe_workspace_path(
        source_rel
    )

    cap = cv2.VideoCapture(str(video_path))
    if not cap.isOpened():
        raise HTTPException(
            status_code=422,
            detail="Could not open source video.",
        )

    try:
        metadata = _video_metadata(cap)
    finally:
        cap.release()

    fps = float(metadata.get("fps") or 30.0)
    width = int(metadata.get("width") or 0)
    height = int(metadata.get("height") or 0)
    duration = float(metadata.get("duration_seconds") or 0.0)

    fixed = _load_fixed_execution_segments(
        fixed_layer,
        source_rel,
    )

    tiled = _load_three_anchor_alpha_basis(
        tiled_layer,
        router,
        width,
        height,
    )

    timestamp = _app_now().strftime(
        "%Y-%m-%d_%H%M%S"
    )
    out_dir = (
        WORKSPACE
        / "review"
        / "branding_watermark_remediation_preview"
        / timestamp
        / video_path.stem
    )
    out_dir.mkdir(
        parents=True,
        exist_ok=True,
    )

    alpha_basis_path = (
        out_dir
        / "01_tiled_alpha_basis.png"
    )
    cv2.imwrite(
        str(alpha_basis_path),
        np.clip(
            tiled["alpha_basis"] * 255.0,
            0,
            255,
        ).astype(np.uint8),
    )

    tiled_times = _tiled_preview_times(
        duration,
        int(req.tiled_sample_count),
    )

    tiled_previews = []

    for idx, t in enumerate(
        tiled_times,
        1,
    ):
        out_path = (
            out_dir
            / f"tiled_strength_{idx:02d}_hq_compare.mp4"
        )

        tiled_previews.append(
            _render_tiled_strength_compare(
                video_path,
                out_path,
                float(t),
                float(req.clip_seconds),
                tiled["alpha_basis"],
                alpha_values,
                float(req.tiled_alpha_gamma),
                fps,
                width,
                height,
                duration,
                int(req.crf),
                str(req.preset),
            )
        )

    fixed_times = _fixed_segment_preview_times(
        fixed["segments"],
        int(req.fixed_preview_count),
    )

    fixed_previews = []

    for idx, t in enumerate(
        fixed_times,
        1,
    ):
        out_path = (
            out_dir
            / f"fixed_legacy_{idx:02d}_hq_compare.mp4"
        )

        fixed_previews.append(
            _render_fixed_legacy_compare(
                video_path,
                out_path,
                float(t),
                float(req.clip_seconds),
                fixed["segments"],
                fps,
                width,
                height,
                duration,
                float(req.fixed_inpaint_radius),
                int(req.fixed_segment_padding_px),
                int(req.crf),
                str(req.preset),
            )
        )

    clips = tiled_previews + fixed_previews
    created = sum(
        1
        for item in clips
        if item.get("ok")
    )

    result = {
        "ok": created > 0,
        "version": "0.17.0",
        "mode": "branding_watermark_remediation_preview",
        "source": {
            "relative_path": source_rel,
            "router_report_relative_path": (
                router_path
                .relative_to(WORKSPACE)
                .as_posix()
            ),
        },
        "video": metadata,
        "summary": {
            "previous_v0_9_14_visual_result": "FAILED",
            "fixed_strategy_changed": True,
            "tiled_strategy_changed": True,
            "fixed_preview_count": len(fixed_previews),
            "tiled_strength_preview_count": len(tiled_previews),
            "clips_requested": len(clips),
            "clips_created": created,
            "clips_failed": len(clips) - created,
            "source_video_modified": False,
            "full_processed_video_created": False,
            "manual_hq_review_required": True,
        },
        "fixed_strong": {
            "layer_id": fixed_layer.get("layer_id"),
            "strategy": "segment_aware_legacy_local_inpaint",
            "reason": (
                "v0.9.14 persistent sparse mask visually failed. "
                "This preview returns to the earlier reviewed execution-segment geometry."
            ),
            "mask_review_relative_path": fixed[
                "mask_review_relative_path"
            ],
            "execution_segments": fixed["segments"],
            "preview_times_seconds": [
                round(float(x), 3)
                for x in fixed_times
            ],
            "previews": fixed_previews,
        },
        "diagonal_tiled": {
            "layer_id": tiled_layer.get("layer_id"),
            "strategy": "semi_transparent_white_overlay_deblend",
            "reason": (
                "A tiled semi-transparent watermark is an overlay-layer problem, "
                "not a missing-pixel problem. v0.9.15 stops inpainting the tiled mask."
            ),
            "three_anchor_report_relative_path": tiled[
                "report_relative_path"
            ],
            "alpha_basis_relative_path": (
                alpha_basis_path
                .relative_to(WORKSPACE)
                .as_posix()
            ),
            "alpha_basis_coverage_ratio": tiled[
                "alpha_basis_coverage_ratio"
            ],
            "grid_point_count": tiled[
                "grid_point_count"
            ],
            "max_alpha_values": alpha_values,
            "alpha_gamma": float(
                req.tiled_alpha_gamma
            ),
            "preview_times_seconds": [
                round(float(x), 3)
                for x in tiled_times
            ],
            "previews": tiled_previews,
        },
        "quality_policy": {
            "codec": "libx264",
            "crf": int(req.crf),
            "preset": str(req.preset),
            "note": (
                "This version intentionally does not create a combined or full-video "
                "render. First choose a tiled deblend strength and verify that the "
                "fixed-logo fallback is acceptable."
            ),
        },
        "output_relative_dir": (
            out_dir
            .relative_to(WORKSPACE)
            .as_posix()
        ),
        "next_action": (
            "Review the three tiled strength comparison clips and choose the lowest "
            "alpha value that materially suppresses ReelShort without dark halos or "
            "texture damage. Separately review the fixed legacy clips. Only after both "
            "handlers have an acceptable method should combined rendering resume."
        ),
    }

    report_path = (
        out_dir
        / f"{video_path.stem}.watermark-remediation-preview.json"
    )
    result["report_relative_path"] = (
        report_path
        .relative_to(WORKSPACE)
        .as_posix()
    )

    report_path.write_text(
        json.dumps(
            result,
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )

    return result




class BrandingTiledAlphaRebuildPreviewRequest(BaseModel):
    router_report_relative_path: str
    tiled_layer_id: str = "three-anchor-grid"

    # Build the photometric alpha template from many real tile crops.
    sample_interval_seconds: float = 1.5
    max_frames: int = 72
    max_tile_samples: int = 700

    # Background estimator. The faint white watermark is treated as a small,
    # positive luminance residual above a locally estimated background.
    background_median_kernel: int = 11
    min_candidate_alpha: float = 0.006
    candidate_alpha_cap: float = 0.22

    # Robust aggregation across different scenes / positions.
    aggregate_percentile: float = 58.0
    min_presence_ratio: float = 0.22
    presence_softness: float = 1.4

    # Optional tiny alignment around each predicted lattice center.
    max_alignment_shift_px: int = 4

    # Compare estimated alpha with modest gains rather than arbitrary absolute
    # alpha values.
    alpha_gain_values: list[float] = Field(
        default_factory=lambda: [0.75, 1.0, 1.25]
    )
    max_output_alpha: float = 0.20

    clip_seconds: float = 2.0
    preview_count: int = 3

    crf: int = 15
    preset: str = "slow"


def _odd_kernel(value, minimum=3, maximum=51):
    k = int(value)
    k = max(int(minimum), min(int(maximum), k))
    if k % 2 == 0:
        k += 1
    if k > int(maximum):
        k -= 2
    return max(3, k)


def _crop_centered_with_padding(frame, cx, cy, width, height, padding):
    fh, fw = frame.shape[:2]
    pad = max(0, int(padding))

    crop_w = int(width) + 2 * pad
    crop_h = int(height) + 2 * pad

    x1 = int(round(float(cx) - crop_w / 2.0))
    y1 = int(round(float(cy) - crop_h / 2.0))
    x2 = x1 + crop_w
    y2 = y1 + crop_h

    out = np.zeros(
        (crop_h, crop_w, frame.shape[2]),
        dtype=frame.dtype,
    )

    src_x1 = max(0, x1)
    src_y1 = max(0, y1)
    src_x2 = min(fw, x2)
    src_y2 = min(fh, y2)

    if src_x2 <= src_x1 or src_y2 <= src_y1:
        return None

    dst_x1 = src_x1 - x1
    dst_y1 = src_y1 - y1
    dst_x2 = dst_x1 + (src_x2 - src_x1)
    dst_y2 = dst_y1 + (src_y2 - src_y1)

    out[
        dst_y1:dst_y2,
        dst_x1:dst_x2,
    ] = frame[
        src_y1:src_y2,
        src_x1:src_x2,
    ]

    valid_ratio = (
        float((src_x2 - src_x1) * (src_y2 - src_y1))
        / float(max(1, crop_w * crop_h))
    )

    return {
        "crop": out,
        "valid_ratio": valid_ratio,
    }


def _photometric_white_alpha_candidate(
    crop_bgr,
    median_kernel,
    min_candidate_alpha,
    candidate_alpha_cap,
):
    gray = cv2.cvtColor(
        crop_bgr,
        cv2.COLOR_BGR2GRAY,
    ).astype(np.float32) / 255.0

    k = _odd_kernel(
        median_kernel,
        minimum=5,
        maximum=31,
    )

    background = cv2.medianBlur(
        (gray * 255.0).astype(np.uint8),
        k,
    ).astype(np.float32) / 255.0

    # White overlay model:
    # O = a*1 + (1-a)*B
    # a = (O-B)/(1-B)
    denom = np.maximum(
        1.0 - background,
        0.08,
    )

    alpha = (
        gray - background
    ) / denom

    alpha = np.clip(
        alpha,
        0.0,
        float(candidate_alpha_cap),
    )

    alpha[
        alpha < float(min_candidate_alpha)
    ] = 0.0

    return alpha


def _shift_float_image(image, dx, dy):
    h, w = image.shape[:2]
    matrix = np.float32(
        [
            [1, 0, float(dx)],
            [0, 1, float(dy)],
        ]
    )
    return cv2.warpAffine(
        image,
        matrix,
        (w, h),
        flags=cv2.INTER_LINEAR,
        borderMode=cv2.BORDER_CONSTANT,
        borderValue=0,
    )


def _align_candidate_to_reference(candidate, reference, max_shift):
    max_shift = max(0, int(max_shift))
    if max_shift == 0 or reference is None:
        return candidate, 0, 0, None

    cand = candidate.astype(np.float32)
    ref = reference.astype(np.float32)

    if cand.shape != ref.shape:
        ref = cv2.resize(
            ref,
            (cand.shape[1], cand.shape[0]),
            interpolation=cv2.INTER_LINEAR,
        )

    ref_norm = float(np.linalg.norm(ref))
    cand_norm = float(np.linalg.norm(cand))
    if ref_norm <= 1e-8 or cand_norm <= 1e-8:
        return candidate, 0, 0, None

    best_score = -1.0
    best_dx = 0
    best_dy = 0
    best = candidate

    for dy in range(-max_shift, max_shift + 1):
        for dx in range(-max_shift, max_shift + 1):
            shifted = _shift_float_image(
                cand,
                dx,
                dy,
            )

            denom = (
                float(np.linalg.norm(shifted))
                * ref_norm
            )
            if denom <= 1e-8:
                continue

            score = float(
                np.sum(shifted * ref)
                / denom
            )

            if score > best_score:
                best_score = score
                best_dx = dx
                best_dy = dy
                best = shifted

    return best, best_dx, best_dy, best_score


def _three_anchor_grid_report_from_router(router, layer):
    evidence = layer.get("evidence") or {}
    report_rel = (
        evidence.get("report_relative_path")
        or (
            (router.get("evidence_reports") or {})
            .get("three_anchor_grid")
        )
    )

    if not report_rel:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "tiled_alpha_rebuild_preview",
                "error": "missing_three_anchor_report",
            },
        )

    report_path = _safe_workspace_path(
        report_rel
    )
    try:
        report = json.loads(
            report_path.read_text(
                encoding="utf-8"
            )
        )
    except Exception as exc:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "tiled_alpha_rebuild_preview",
                "error": "invalid_three_anchor_report",
                "message": str(exc)[:500],
            },
        )

    return report_rel, report


def _load_old_structural_tile_prior(report):
    diagnostics = report.get(
        "diagnostic_images"
    ) or {}

    template_rel = diagnostics.get(
        "three_anchor_persistent_template"
    )
    if not template_rel:
        return None, None

    path = _safe_workspace_path(
        template_rel
    )
    prior = cv2.imread(
        str(path),
        cv2.IMREAD_GRAYSCALE,
    )
    if prior is None:
        return None, template_rel

    prior = (
        prior.astype(np.float32)
        / 255.0
    )

    # Structural prior is used only for sub-pixel-ish alignment, never as the
    # new alpha value.
    positive = prior[prior > 0]
    if positive.size:
        lo = float(
            np.percentile(
                positive,
                35.0,
            )
        )
        hi = float(
            np.percentile(
                positive,
                95.0,
            )
        )
        if hi > lo + 1e-6:
            prior = np.clip(
                (prior - lo) / (hi - lo),
                0.0,
                1.0,
            )

    return prior, template_rel


def _rebuild_tiled_photometric_alpha(
    video_path,
    report,
    sample_interval_seconds,
    max_frames,
    max_tile_samples,
    background_median_kernel,
    min_candidate_alpha,
    candidate_alpha_cap,
    aggregate_percentile,
    min_presence_ratio,
    presence_softness,
    max_alignment_shift_px,
):
    metadata = report.get("video") or {}
    width = int(metadata.get("width") or 0)
    height = int(metadata.get("height") or 0)

    canonical = report.get(
        "canonical_tile"
    ) or {}
    tile_w = int(
        canonical.get("width") or 0
    )
    tile_h = int(
        canonical.get("height") or 0
    )

    if tile_w <= 0 or tile_h <= 0:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "tiled_alpha_rebuild_preview",
                "error": "invalid_canonical_tile_size",
            },
        )

    grid_points = (
        (report.get("grid") or {})
        .get("predicted_grid_points")
        or []
    )

    # Ignore heavily clipped tiles at the frame edge. We want complete
    # wordmarks for template reconstruction.
    usable_points = []
    margin_x = tile_w / 2.0 + 3
    margin_y = tile_h / 2.0 + 3

    for point in grid_points:
        center = point.get("center") or {}
        cx = float(center.get("x") or 0.0)
        cy = float(center.get("y") or 0.0)

        if (
            margin_x <= cx <= width - margin_x
            and margin_y <= cy <= height - margin_y
        ):
            usable_points.append(
                {
                    "x": cx,
                    "y": cy,
                    "i": point.get("i"),
                    "j": point.get("j"),
                }
            )

    if len(usable_points) < 3:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "tiled_alpha_rebuild_preview",
                "error": "too_few_complete_grid_tiles",
                "complete_tile_count": len(usable_points),
            },
        )

    prior, prior_rel = _load_old_structural_tile_prior(
        report
    )
    if prior is not None and prior.shape != (
        tile_h,
        tile_w,
    ):
        prior = cv2.resize(
            prior,
            (tile_w, tile_h),
            interpolation=cv2.INTER_LINEAR,
        )

    cap = cv2.VideoCapture(
        str(video_path)
    )
    if not cap.isOpened():
        raise HTTPException(
            status_code=422,
            detail="Could not open source video.",
        )

    try:
        video_meta = _video_metadata(
            cap
        )
        duration = float(
            video_meta.get(
                "duration_seconds"
            ) or 0.0
        )

        interval = max(
            float(sample_interval_seconds),
            duration / float(
                max(
                    1,
                    int(max_frames),
                )
            )
            if duration > 0
            else float(
                sample_interval_seconds
            ),
        )

        candidates = []
        alignment_records = []
        sampled_times = []
        sampled_frame_count = 0

        t = 0.0

        while (
            (duration <= 0 or t <= duration + 1e-9)
            and sampled_frame_count < int(max_frames)
            and len(candidates) < int(max_tile_samples)
        ):
            cap.set(
                cv2.CAP_PROP_POS_MSEC,
                float(t) * 1000.0,
            )
            ok, frame = cap.read()

            if not ok or frame is None:
                t += interval
                continue

            sampled_times.append(
                round(float(t), 3)
            )
            sampled_frame_count += 1

            for point in usable_points:
                if len(candidates) >= int(max_tile_samples):
                    break

                crop_info = _crop_centered_with_padding(
                    frame,
                    point["x"],
                    point["y"],
                    tile_w,
                    tile_h,
                    0,
                )
                if (
                    crop_info is None
                    or crop_info["valid_ratio"] < 0.995
                ):
                    continue

                crop = crop_info["crop"]

                candidate = _photometric_white_alpha_candidate(
                    crop,
                    int(background_median_kernel),
                    float(min_candidate_alpha),
                    float(candidate_alpha_cap),
                )

                aligned, dx, dy, score = _align_candidate_to_reference(
                    candidate,
                    prior,
                    int(max_alignment_shift_px),
                )

                candidates.append(
                    aligned.astype(
                        np.float32
                    )
                )

                alignment_records.append(
                    {
                        "time_seconds": round(
                            float(t),
                            3,
                        ),
                        "grid_i": point["i"],
                        "grid_j": point["j"],
                        "dx": int(dx),
                        "dy": int(dy),
                        "score": (
                            round(
                                float(score),
                                5,
                            )
                            if score is not None
                            else None
                        ),
                    }
                )

            t += interval

        if len(candidates) < 20:
            raise HTTPException(
                status_code=422,
                detail={
                    "stage": "tiled_alpha_rebuild_preview",
                    "error": "too_few_photometric_samples",
                    "sample_count": len(candidates),
                },
            )

        stack = np.stack(
            candidates,
            axis=0,
        )

        robust_alpha = np.percentile(
            stack,
            float(aggregate_percentile),
            axis=0,
        ).astype(np.float32)

        presence = np.mean(
            stack
            >= max(
                float(min_candidate_alpha) * 1.15,
                0.008,
            ),
            axis=0,
        ).astype(np.float32)

        min_presence = float(
            min_presence_ratio
        )
        denom = max(
            1e-6,
            1.0 - min_presence,
        )
        presence_weight = np.clip(
            (
                presence - min_presence
            ) / denom,
            0.0,
            1.0,
        )
        presence_weight = np.power(
            presence_weight,
            float(presence_softness),
        )

        rebuilt = (
            robust_alpha
            * presence_weight
        )

        rebuilt = cv2.GaussianBlur(
            rebuilt,
            (3, 3),
            0,
        )

        rebuilt[
            rebuilt
            < max(
                0.002,
                float(min_candidate_alpha) * 0.45,
            )
        ] = 0.0

        rebuilt = np.clip(
            rebuilt,
            0.0,
            float(candidate_alpha_cap),
        )

        return {
            "video_metadata": video_meta,
            "tile_width": tile_w,
            "tile_height": tile_h,
            "grid_points": grid_points,
            "usable_points": usable_points,
            "rebuilt_tile_alpha": rebuilt,
            "presence_map": presence,
            "robust_alpha_map": robust_alpha,
            "sample_count": len(candidates),
            "sampled_frame_count": sampled_frame_count,
            "sampled_times": sampled_times,
            "effective_interval_seconds": round(
                interval,
                4,
            ),
            "alignment_records": alignment_records,
            "structural_prior_relative_path": prior_rel,
        }
    finally:
        cap.release()


def _tile_alpha_to_full_grid(
    tile_alpha,
    grid_points,
    width,
    height,
):
    full = np.zeros(
        (int(height), int(width)),
        dtype=np.float32,
    )

    th, tw = tile_alpha.shape[:2]

    for point in grid_points:
        center = point.get(
            "center"
        ) or {}
        cx = float(
            center.get("x") or 0.0
        )
        cy = float(
            center.get("y") or 0.0
        )

        x1 = int(
            round(
                cx - tw / 2.0
            )
        )
        y1 = int(
            round(
                cy - th / 2.0
            )
        )
        x2 = x1 + tw
        y2 = y1 + th

        src_x1 = 0
        src_y1 = 0
        src_x2 = tw
        src_y2 = th

        if x1 < 0:
            src_x1 = -x1
            x1 = 0
        if y1 < 0:
            src_y1 = -y1
            y1 = 0
        if x2 > int(width):
            src_x2 -= (
                x2 - int(width)
            )
            x2 = int(width)
        if y2 > int(height):
            src_y2 -= (
                y2 - int(height)
            )
            y2 = int(height)

        if (
            x2 <= x1
            or y2 <= y1
        ):
            continue

        target = full[
            y1:y2,
            x1:x2,
        ]
        source = tile_alpha[
            src_y1:src_y2,
            src_x1:src_x2,
        ]

        np.maximum(
            target,
            source,
            out=target,
        )

    return full


def _deblend_with_alpha_gain(
    frame,
    full_alpha,
    gain,
    max_output_alpha,
):
    alpha = np.clip(
        full_alpha
        * float(gain),
        0.0,
        float(max_output_alpha),
    )

    alpha3 = alpha[..., None]
    observed = (
        frame.astype(np.float32)
        / 255.0
    )

    denom = np.maximum(
        1.0 - alpha3,
        0.55,
    )

    restored = (
        observed - alpha3
    ) / denom

    restored = np.where(
        alpha3 > 1e-8,
        restored,
        observed,
    )

    return np.clip(
        restored * 255.0,
        0,
        255,
    ).astype(np.uint8)


def _render_rebuilt_alpha_compare(
    video_path,
    out_path,
    center_time,
    clip_seconds,
    full_alpha,
    gains,
    max_output_alpha,
    fps,
    width,
    height,
    duration,
    crf,
    preset,
):
    half = float(
        clip_seconds
    ) / 2.0

    clip_start = max(
        0.0,
        float(center_time) - half,
    )
    clip_end = (
        float(center_time) + half
    )

    if duration > 0:
        clip_end = min(
            duration,
            clip_end,
        )

    pane_count = 1 + len(gains)
    out_width = int(width) * pane_count
    out_height = int(height)

    writer, runtime = _open_x264_raw_writer(
        out_path,
        out_width,
        out_height,
        float(fps),
        int(crf),
        str(preset),
    )

    cap = cv2.VideoCapture(
        str(video_path)
    )
    if not cap.isOpened():
        try:
            writer.stdin.close()
        except Exception:
            pass
        writer.kill()
        raise HTTPException(
            status_code=422,
            detail="Could not open source video for rebuilt-alpha preview.",
        )

    cap.set(
        cv2.CAP_PROP_POS_MSEC,
        clip_start * 1000.0,
    )

    frame_index = 0
    frames_written = 0
    write_error = None

    try:
        while True:
            ok, frame = cap.read()
            if not ok or frame is None:
                break

            current_t = (
                clip_start
                + frame_index
                / float(fps)
            )

            if (
                current_t
                > clip_end
                + 0.5 / float(fps)
            ):
                break

            panes = [
                _label_pane(
                    frame,
                    "ORIGINAL",
                )
            ]

            for gain in gains:
                restored = _deblend_with_alpha_gain(
                    frame,
                    full_alpha,
                    float(gain),
                    float(max_output_alpha),
                )
                panes.append(
                    _label_pane(
                        restored,
                        f"GAIN {float(gain):.02f}",
                    )
                )

            output = np.hstack(
                panes
            )

            try:
                writer.stdin.write(
                    output.tobytes()
                )
            except Exception as exc:
                write_error = str(exc)[:500]
                break

            frames_written += 1
            frame_index += 1

    finally:
        cap.release()
        try:
            if writer.stdin:
                writer.stdin.close()
        except Exception:
            pass

    stderr = b""
    try:
        stderr = (
            writer.stderr.read()
            if writer.stderr
            else b""
        )
    except Exception:
        pass

    return_code = writer.wait()

    ok = (
        return_code == 0
        and write_error is None
        and out_path.exists()
    )

    return {
        "ok": ok,
        "center_time_seconds": round(
            float(center_time),
            3,
        ),
        "clip_start_seconds": round(
            clip_start,
            3,
        ),
        "clip_end_seconds": round(
            clip_end,
            3,
        ),
        "frames_written": frames_written,
        "pane_count": pane_count,
        "output_size": {
            "width": out_width,
            "height": out_height,
        },
        "relative_path": (
            out_path
            .relative_to(WORKSPACE)
            .as_posix()
            if out_path.exists()
            else None
        ),
        "gain_values": [
            float(x)
            for x in gains
        ],
        "max_output_alpha": float(
            max_output_alpha
        ),
        "encoder": {
            "engine": "ffmpeg",
            "codec": "libx264",
            "crf": int(crf),
            "preset": str(preset),
            "runtime": runtime,
        },
        "error": (
            write_error
            or (
                stderr.decode(
                    "utf-8",
                    errors="replace",
                )[:800]
                if return_code != 0
                else None
            )
        ),
    }


def _tiled_alpha_rebuild_preview_sync(
    req: BrandingTiledAlphaRebuildPreviewRequest
):
    router_path = _safe_workspace_path(
        req.router_report_relative_path
    )
    try:
        router = json.loads(
            router_path.read_text(
                encoding="utf-8"
            )
        )
    except Exception as exc:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "tiled_alpha_rebuild_preview",
                "error": "invalid_router_report",
                "message": str(exc)[:500],
            },
        )

    if (
        router.get("mode")
        != "branding_watermark_router"
    ):
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "tiled_alpha_rebuild_preview",
                "error": "wrong_router_report_mode",
                "actual": router.get("mode"),
            },
        )

    source_rel = (
        (router.get("source") or {})
        .get("relative_path")
    )
    if not source_rel:
        raise HTTPException(
            status_code=422,
            detail="Router report has no source.relative_path.",
        )

    layer = _find_router_layer(
        router,
        req.tiled_layer_id,
    )

    if (
        str(layer.get("handler"))
        != "diagonal_tiled_grid"
    ):
        raise HTTPException(
            status_code=422,
            detail="tiled_layer_id is not a diagonal_tiled_grid layer.",
        )

    if str(layer.get("status")) != "AUTO":
        raise HTTPException(
            status_code=422,
            detail="Tiled layer must be AUTO.",
        )

    if not 0.5 <= float(
        req.sample_interval_seconds
    ) <= 5.0:
        raise HTTPException(
            status_code=422,
            detail="sample_interval_seconds must be between 0.5 and 5.",
        )

    if not 12 <= int(
        req.max_frames
    ) <= 240:
        raise HTTPException(
            status_code=422,
            detail="max_frames must be between 12 and 240.",
        )

    if not 60 <= int(
        req.max_tile_samples
    ) <= 2000:
        raise HTTPException(
            status_code=422,
            detail="max_tile_samples must be between 60 and 2000.",
        )

    if not 45.0 <= float(
        req.aggregate_percentile
    ) <= 75.0:
        raise HTTPException(
            status_code=422,
            detail="aggregate_percentile must be between 45 and 75.",
        )

    if not 0.05 <= float(
        req.min_presence_ratio
    ) <= 0.75:
        raise HTTPException(
            status_code=422,
            detail="min_presence_ratio must be between 0.05 and 0.75.",
        )

    gains = sorted(
        {
            round(
                float(x),
                4,
            )
            for x in req.alpha_gain_values
        }
    )

    if (
        not gains
        or len(gains) > 5
        or any(
            x <= 0
            or x > 2.5
            for x in gains
        )
    ):
        raise HTTPException(
            status_code=422,
            detail="Use 1-5 alpha_gain_values in (0, 2.5].",
        )

    if not 0.05 <= float(
        req.max_output_alpha
    ) <= 0.30:
        raise HTTPException(
            status_code=422,
            detail="max_output_alpha must be between 0.05 and 0.30.",
        )

    if not 1 <= int(
        req.preview_count
    ) <= 5:
        raise HTTPException(
            status_code=422,
            detail="preview_count must be between 1 and 5.",
        )

    if not 0.75 <= float(
        req.clip_seconds
    ) <= 5.0:
        raise HTTPException(
            status_code=422,
            detail="clip_seconds must be between 0.75 and 5.",
        )

    if not 8 <= int(
        req.crf
    ) <= 28:
        raise HTTPException(
            status_code=422,
            detail="crf must be between 8 and 28.",
        )

    allowed_presets = {
        "ultrafast",
        "superfast",
        "veryfast",
        "faster",
        "fast",
        "medium",
        "slow",
        "slower",
        "veryslow",
    }
    if str(req.preset) not in allowed_presets:
        raise HTTPException(
            status_code=422,
            detail={
                "error": "unsupported_x264_preset",
                "allowed": sorted(
                    allowed_presets
                ),
            },
        )

    report_rel, report = _three_anchor_grid_report_from_router(
        router,
        layer,
    )

    video_path = _safe_workspace_path(
        source_rel
    )

    rebuilt = _rebuild_tiled_photometric_alpha(
        video_path,
        report,
        float(req.sample_interval_seconds),
        int(req.max_frames),
        int(req.max_tile_samples),
        int(req.background_median_kernel),
        float(req.min_candidate_alpha),
        float(req.candidate_alpha_cap),
        float(req.aggregate_percentile),
        float(req.min_presence_ratio),
        float(req.presence_softness),
        int(req.max_alignment_shift_px),
    )

    video_meta = rebuilt[
        "video_metadata"
    ]
    width = int(
        video_meta.get("width") or 0
    )
    height = int(
        video_meta.get("height") or 0
    )
    fps = float(
        video_meta.get("fps") or 30.0
    )
    duration = float(
        video_meta.get(
            "duration_seconds"
        ) or 0.0
    )

    full_alpha = _tile_alpha_to_full_grid(
        rebuilt[
            "rebuilt_tile_alpha"
        ],
        rebuilt["grid_points"],
        width,
        height,
    )

    timestamp = _app_now().strftime(
        "%Y-%m-%d_%H%M%S"
    )
    out_dir = (
        WORKSPACE
        / "review"
        / "branding_tiled_alpha_rebuild"
        / timestamp
        / video_path.stem
    )
    out_dir.mkdir(
        parents=True,
        exist_ok=True,
    )

    presence_path = (
        out_dir
        / "01_tile_presence_map.png"
    )
    robust_path = (
        out_dir
        / "02_tile_robust_alpha_raw.png"
    )
    rebuilt_tile_path = (
        out_dir
        / "03_tile_rebuilt_alpha.png"
    )
    full_alpha_path = (
        out_dir
        / "04_full_grid_rebuilt_alpha.png"
    )

    cv2.imwrite(
        str(presence_path),
        np.clip(
            rebuilt["presence_map"]
            * 255.0,
            0,
            255,
        ).astype(np.uint8),
    )
    cv2.imwrite(
        str(robust_path),
        np.clip(
            rebuilt[
                "robust_alpha_map"
            ]
            / max(
                1e-6,
                float(
                    req.candidate_alpha_cap
                ),
            )
            * 255.0,
            0,
            255,
        ).astype(np.uint8),
    )
    cv2.imwrite(
        str(rebuilt_tile_path),
        np.clip(
            rebuilt[
                "rebuilt_tile_alpha"
            ]
            / max(
                1e-6,
                float(
                    req.candidate_alpha_cap
                ),
            )
            * 255.0,
            0,
            255,
        ).astype(np.uint8),
    )
    cv2.imwrite(
        str(full_alpha_path),
        np.clip(
            full_alpha
            / max(
                1e-6,
                float(
                    req.max_output_alpha
                ),
            )
            * 255.0,
            0,
            255,
        ).astype(np.uint8),
    )

    preview_times = _tiled_preview_times(
        duration,
        int(req.preview_count),
    )

    previews = []

    for idx, t in enumerate(
        preview_times,
        1,
    ):
        out_path = (
            out_dir
            / f"rebuilt_alpha_{idx:02d}_hq_compare.mp4"
        )

        previews.append(
            _render_rebuilt_alpha_compare(
                video_path,
                out_path,
                float(t),
                float(req.clip_seconds),
                full_alpha,
                gains,
                float(req.max_output_alpha),
                fps,
                width,
                height,
                duration,
                int(req.crf),
                str(req.preset),
            )
        )

    full_positive = full_alpha[
        full_alpha > 0
    ]
    tile_positive = rebuilt[
        "rebuilt_tile_alpha"
    ][
        rebuilt[
            "rebuilt_tile_alpha"
        ] > 0
    ]

    result = {
        "ok": all(
            item.get("ok")
            for item in previews
        ),
        "version": "0.17.0",
        "mode": "branding_tiled_alpha_rebuild_preview",
        "source": {
            "relative_path": source_rel,
            "router_report_relative_path": (
                router_path
                .relative_to(WORKSPACE)
                .as_posix()
            ),
            "three_anchor_report_relative_path": report_rel,
        },
        "video": video_meta,
        "summary": {
            "fixed_strong_handler_status": "FROZEN_PASS",
            "fixed_strong_strategy": "segment_aware_legacy_local_inpaint",
            "previous_tiled_alpha_strategy_status": "FAILED",
            "photometric_tile_sample_count": rebuilt[
                "sample_count"
            ],
            "sampled_frame_count": rebuilt[
                "sampled_frame_count"
            ],
            "complete_grid_tile_count": len(
                rebuilt[
                    "usable_points"
                ]
            ),
            "grid_point_count": len(
                rebuilt[
                    "grid_points"
                ]
            ),
            "preview_count": len(
                previews
            ),
            "source_video_modified": False,
            "full_processed_video_created": False,
            "manual_visual_confirmation_required": True,
        },
        "rebuild": {
            "method": "multi_tile_multi_time_photometric_white_overlay_estimation",
            "background_median_kernel": _odd_kernel(
                req.background_median_kernel,
                minimum=5,
                maximum=31,
            ),
            "min_candidate_alpha": float(
                req.min_candidate_alpha
            ),
            "candidate_alpha_cap": float(
                req.candidate_alpha_cap
            ),
            "aggregate_percentile": float(
                req.aggregate_percentile
            ),
            "min_presence_ratio": float(
                req.min_presence_ratio
            ),
            "presence_softness": float(
                req.presence_softness
            ),
            "max_alignment_shift_px": int(
                req.max_alignment_shift_px
            ),
            "effective_interval_seconds": rebuilt[
                "effective_interval_seconds"
            ],
            "sampled_times": rebuilt[
                "sampled_times"
            ],
            "structural_prior_used_for_alignment_only": rebuilt[
                "structural_prior_relative_path"
            ],
        },
        "alpha_statistics": {
            "tile_nonzero_coverage_ratio": round(
                float(
                    np.count_nonzero(
                        rebuilt[
                            "rebuilt_tile_alpha"
                        ] > 0
                    )
                )
                / float(
                    max(
                        1,
                        rebuilt[
                            "tile_width"
                        ]
                        * rebuilt[
                            "tile_height"
                        ],
                    )
                ),
                8,
            ),
            "tile_median_positive_alpha": (
                round(
                    float(
                        np.median(
                            tile_positive
                        )
                    ),
                    6,
                )
                if tile_positive.size
                else 0.0
            ),
            "tile_p95_positive_alpha": (
                round(
                    float(
                        np.percentile(
                            tile_positive,
                            95.0,
                        )
                    ),
                    6,
                )
                if tile_positive.size
                else 0.0
            ),
            "full_grid_nonzero_coverage_ratio": round(
                float(
                    np.count_nonzero(
                        full_alpha > 0
                    )
                )
                / float(
                    max(
                        1,
                        width * height,
                    )
                ),
                8,
            ),
            "full_grid_p95_positive_alpha": (
                round(
                    float(
                        np.percentile(
                            full_positive,
                            95.0,
                        )
                    ),
                    6,
                )
                if full_positive.size
                else 0.0
            ),
        },
        "diagnostic_images": {
            "tile_presence_map": (
                presence_path
                .relative_to(WORKSPACE)
                .as_posix()
            ),
            "tile_robust_alpha_raw": (
                robust_path
                .relative_to(WORKSPACE)
                .as_posix()
            ),
            "tile_rebuilt_alpha": (
                rebuilt_tile_path
                .relative_to(WORKSPACE)
                .as_posix()
            ),
            "full_grid_rebuilt_alpha": (
                full_alpha_path
                .relative_to(WORKSPACE)
                .as_posix()
            ),
        },
        "preview": {
            "gain_values": gains,
            "max_output_alpha": float(
                req.max_output_alpha
            ),
            "preview_times_seconds": [
                round(
                    float(x),
                    3,
                )
                for x in preview_times
            ],
            "clips": previews,
        },
        "interpretation": {
            "important": (
                "Unlike v0.9.15, the alpha values are rebuilt from actual video "
                "luminance residuals aggregated across many grid tiles and times. "
                "The older structural template is used only for tiny alignment shifts."
            ),
            "acceptance": (
                "03_tile_rebuilt_alpha.png should visually resemble the ReelShort "
                "wordmark itself, not just its edges or unrelated scene texture. "
                "Then choose the lowest gain that suppresses the watermark without "
                "dark halos or texture changes."
            ),
        },
        "output_relative_dir": (
            out_dir
            .relative_to(WORKSPACE)
            .as_posix()
        ),
    }

    report_path = (
        out_dir
        / f"{video_path.stem}.tiled-alpha-rebuild-preview.json"
    )
    result[
        "report_relative_path"
    ] = (
        report_path
        .relative_to(WORKSPACE)
        .as_posix()
    )

    report_path.write_text(
        json.dumps(
            result,
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )

    return result




class BrandingTiledShapeDynamicPreviewRequest(BaseModel):
    router_report_relative_path: str
    fixed_layer_id: str = "census-1-fixed-strong"
    tiled_layer_id: str = "three-anchor-grid"

    sample_interval_seconds: float = 1.25
    max_frames: int = 80
    max_tile_samples: int = 800

    # Shape reconstruction uses local-normalized bright residuals. Absolute
    # alpha is deliberately NOT estimated during template construction.
    background_blur_sigma: float = 5.0
    residual_floor_percentile: float = 72.0
    aggregate_percentile: float = 62.0
    presence_threshold_percentile: float = 82.0
    min_presence_ratio: float = 0.18
    shape_core_percentile: float = 72.0
    shape_dilate_iterations: int = 1

    # Runtime alpha is estimated separately for each tile/frame from the
    # current observed pixels under the learned shape.
    alpha_gain_values: list[float] = Field(
        default_factory=lambda: [0.75, 1.0, 1.25]
    )
    min_runtime_alpha: float = 0.006
    max_runtime_alpha: float = 0.16
    runtime_alpha_percentile: float = 62.0

    # Reuse the visually approved fixed-logo baseline.
    fixed_inpaint_radius: float = 3.0
    fixed_segment_padding_px: int = 2

    clip_seconds: float = 2.0
    preview_count: int = 3
    crf: int = 15
    preset: str = "slow"


def _local_bright_residual_normalized(crop_bgr, sigma):
    gray = cv2.cvtColor(
        crop_bgr,
        cv2.COLOR_BGR2GRAY,
    ).astype(np.float32) / 255.0

    sigma = max(1.0, float(sigma))
    background = cv2.GaussianBlur(
        gray,
        (0, 0),
        sigmaX=sigma,
        sigmaY=sigma,
    )

    denom = np.maximum(
        1.0 - background,
        0.10,
    )

    residual = np.clip(
        (gray - background) / denom,
        0.0,
        1.0,
    )

    positive = residual[residual > 0]
    if positive.size:
        hi = float(np.percentile(positive, 97.0))
        if hi > 1e-6:
            residual = np.clip(
                residual / hi,
                0.0,
                1.0,
            )

    return residual


def _rebuild_tiled_shape_probability(
    video_path,
    report,
    sample_interval_seconds,
    max_frames,
    max_tile_samples,
    background_blur_sigma,
    residual_floor_percentile,
    aggregate_percentile,
    presence_threshold_percentile,
    min_presence_ratio,
    shape_core_percentile,
    shape_dilate_iterations,
):
    metadata = report.get("video") or {}
    width = int(metadata.get("width") or 0)
    height = int(metadata.get("height") or 0)

    canonical = report.get("canonical_tile") or {}
    tile_w = int(canonical.get("width") or 0)
    tile_h = int(canonical.get("height") or 0)

    if tile_w <= 0 or tile_h <= 0:
        raise HTTPException(
            status_code=422,
            detail="Invalid canonical tile size.",
        )

    grid_points = (
        (report.get("grid") or {})
        .get("predicted_grid_points")
        or []
    )

    margin_x = tile_w / 2.0 + 2
    margin_y = tile_h / 2.0 + 2

    usable_points = []
    for point in grid_points:
        center = point.get("center") or {}
        cx = float(center.get("x") or 0.0)
        cy = float(center.get("y") or 0.0)

        if (
            margin_x <= cx <= width - margin_x
            and margin_y <= cy <= height - margin_y
        ):
            usable_points.append(point)

    if len(usable_points) < 3:
        raise HTTPException(
            status_code=422,
            detail={
                "error": "too_few_complete_grid_tiles",
                "count": len(usable_points),
            },
        )

    cap = cv2.VideoCapture(str(video_path))
    if not cap.isOpened():
        raise HTTPException(
            status_code=422,
            detail="Could not open source video.",
        )

    try:
        video_meta = _video_metadata(cap)
        duration = float(
            video_meta.get("duration_seconds") or 0.0
        )

        interval = max(
            float(sample_interval_seconds),
            (
                duration / float(max(1, int(max_frames)))
                if duration > 0
                else float(sample_interval_seconds)
            ),
        )

        residual_samples = []
        presence_samples = []
        sampled_times = []
        sampled_frames = 0

        t = 0.0
        while (
            (duration <= 0 or t <= duration + 1e-9)
            and sampled_frames < int(max_frames)
            and len(residual_samples) < int(max_tile_samples)
        ):
            cap.set(
                cv2.CAP_PROP_POS_MSEC,
                float(t) * 1000.0,
            )
            ok, frame = cap.read()
            if not ok or frame is None:
                t += interval
                continue

            sampled_times.append(round(float(t), 3))
            sampled_frames += 1

            for point in usable_points:
                if len(residual_samples) >= int(max_tile_samples):
                    break

                center = point.get("center") or {}
                info = _crop_centered_with_padding(
                    frame,
                    float(center.get("x") or 0.0),
                    float(center.get("y") or 0.0),
                    tile_w,
                    tile_h,
                    0,
                )
                if info is None or info["valid_ratio"] < 0.995:
                    continue

                residual = _local_bright_residual_normalized(
                    info["crop"],
                    float(background_blur_sigma),
                )

                positive = residual[residual > 0]
                if positive.size:
                    floor = float(np.percentile(
                        positive,
                        float(residual_floor_percentile),
                    ))
                else:
                    floor = 1.0

                cleaned = np.where(
                    residual >= floor,
                    residual,
                    0.0,
                ).astype(np.float32)

                if positive.size:
                    presence_thr = float(np.percentile(
                        positive,
                        float(presence_threshold_percentile),
                    ))
                else:
                    presence_thr = 1.0

                presence = (
                    residual >= presence_thr
                ).astype(np.float32)

                residual_samples.append(cleaned)
                presence_samples.append(presence)

            t += interval

        if len(residual_samples) < 30:
            raise HTTPException(
                status_code=422,
                detail={
                    "error": "too_few_shape_samples",
                    "sample_count": len(residual_samples),
                },
            )

        stack = np.stack(residual_samples, axis=0)
        presence_stack = np.stack(presence_samples, axis=0)

        aggregate = np.percentile(
            stack,
            float(aggregate_percentile),
            axis=0,
        ).astype(np.float32)

        presence_ratio = np.mean(
            presence_stack,
            axis=0,
        ).astype(np.float32)

        # Do not zero-out weak signal abruptly as in v0.9.16. Presence acts as
        # a soft confidence weight, so faint but consistent letter strokes can
        # survive.
        presence_weight = np.clip(
            presence_ratio / max(1e-6, float(min_presence_ratio)),
            0.0,
            1.0,
        )

        shape = aggregate * (
            0.25 + 0.75 * presence_weight
        )

        shape = cv2.GaussianBlur(
            shape,
            (3, 3),
            0,
        )

        positive_shape = shape[shape > 0]
        if positive_shape.size:
            lo = float(np.percentile(positive_shape, 25.0))
            hi = float(np.percentile(positive_shape, 98.0))
            if hi > lo + 1e-6:
                shape = np.clip(
                    (shape - lo) / (hi - lo),
                    0.0,
                    1.0,
                )

        positive_shape = shape[shape > 0]
        if positive_shape.size:
            core_thr = float(np.percentile(
                positive_shape,
                float(shape_core_percentile),
            ))
        else:
            core_thr = 1.0

        core = (
            shape >= core_thr
        ).astype(np.uint8) * 255

        core = cv2.morphologyEx(
            core,
            cv2.MORPH_CLOSE,
            np.ones((3, 3), dtype=np.uint8),
            iterations=1,
        )

        if int(shape_dilate_iterations) > 0:
            core = cv2.dilate(
                core,
                np.ones((3, 3), dtype=np.uint8),
                iterations=int(shape_dilate_iterations),
            )

        # Soft shape is retained inside/near core only.
        soft_mask = (
            core.astype(np.float32) / 255.0
        )
        soft_mask = cv2.GaussianBlur(
            soft_mask,
            (3, 3),
            0,
        )
        shape = shape * soft_mask

        return {
            "video_metadata": video_meta,
            "tile_width": tile_w,
            "tile_height": tile_h,
            "grid_points": grid_points,
            "usable_points": usable_points,
            "aggregate": aggregate,
            "presence_ratio": presence_ratio,
            "shape_probability": shape,
            "core_mask": core,
            "sample_count": len(residual_samples),
            "sampled_frame_count": sampled_frames,
            "sampled_times": sampled_times,
            "effective_interval_seconds": round(interval, 4),
        }
    finally:
        cap.release()


def _paste_shape_to_full_grid(shape, grid_points, width, height):
    full = np.zeros(
        (int(height), int(width)),
        dtype=np.float32,
    )

    th, tw = shape.shape[:2]

    for point in grid_points:
        center = point.get("center") or {}
        cx = float(center.get("x") or 0.0)
        cy = float(center.get("y") or 0.0)

        x1 = int(round(cx - tw / 2.0))
        y1 = int(round(cy - th / 2.0))
        x2 = x1 + tw
        y2 = y1 + th

        sx1 = 0
        sy1 = 0
        sx2 = tw
        sy2 = th

        if x1 < 0:
            sx1 = -x1
            x1 = 0
        if y1 < 0:
            sy1 = -y1
            y1 = 0
        if x2 > int(width):
            sx2 -= x2 - int(width)
            x2 = int(width)
        if y2 > int(height):
            sy2 -= y2 - int(height)
            y2 = int(height)

        if x2 <= x1 or y2 <= y1:
            continue

        target = full[y1:y2, x1:x2]
        source = shape[sy1:sy2, sx1:sx2]

        np.maximum(target, source, out=target)

    return full


def _estimate_runtime_tile_alpha(
    crop_bgr,
    shape_probability,
    background_blur_sigma,
    runtime_alpha_percentile,
    min_runtime_alpha,
    max_runtime_alpha,
):
    gray = cv2.cvtColor(
        crop_bgr,
        cv2.COLOR_BGR2GRAY,
    ).astype(np.float32) / 255.0

    background = cv2.GaussianBlur(
        gray,
        (0, 0),
        sigmaX=max(1.0, float(background_blur_sigma)),
        sigmaY=max(1.0, float(background_blur_sigma)),
    )

    candidate = np.clip(
        (gray - background)
        / np.maximum(1.0 - background, 0.10),
        0.0,
        float(max_runtime_alpha),
    )

    core = shape_probability >= 0.45
    values = candidate[core]

    values = values[
        values >= float(min_runtime_alpha)
    ]

    if values.size < 8:
        return 0.0

    alpha_scalar = float(np.percentile(
        values,
        float(runtime_alpha_percentile),
    ))

    return float(np.clip(
        alpha_scalar,
        float(min_runtime_alpha),
        float(max_runtime_alpha),
    ))


def _apply_dynamic_tiled_deblend(
    frame,
    tile_shape,
    grid_points,
    background_blur_sigma,
    runtime_alpha_percentile,
    min_runtime_alpha,
    max_runtime_alpha,
    gain,
):
    result = frame.astype(np.float32) / 255.0
    h, w = frame.shape[:2]
    th, tw = tile_shape.shape[:2]

    alpha_full = np.zeros(
        (h, w),
        dtype=np.float32,
    )

    for point in grid_points:
        center = point.get("center") or {}
        cx = float(center.get("x") or 0.0)
        cy = float(center.get("y") or 0.0)

        x1 = int(round(cx - tw / 2.0))
        y1 = int(round(cy - th / 2.0))
        x2 = x1 + tw
        y2 = y1 + th

        if (
            x1 < 0 or y1 < 0
            or x2 > w or y2 > h
        ):
            continue

        crop = frame[y1:y2, x1:x2]

        scalar = _estimate_runtime_tile_alpha(
            crop,
            tile_shape,
            float(background_blur_sigma),
            float(runtime_alpha_percentile),
            float(min_runtime_alpha),
            float(max_runtime_alpha),
        )

        if scalar <= 0:
            continue

        tile_alpha = np.clip(
            tile_shape
            * scalar
            * float(gain),
            0.0,
            float(max_runtime_alpha),
        )

        target = alpha_full[y1:y2, x1:x2]
        np.maximum(
            target,
            tile_alpha,
            out=target,
        )

    alpha3 = alpha_full[..., None]

    restored = (
        result - alpha3
    ) / np.maximum(
        1.0 - alpha3,
        0.60,
    )

    restored = np.where(
        alpha3 > 1e-8,
        restored,
        result,
    )

    return (
        np.clip(
            restored * 255.0,
            0,
            255,
        ).astype(np.uint8),
        alpha_full,
    )


def _apply_fixed_segment_if_active(
    frame,
    time_seconds,
    segments,
    inpaint_radius,
    padding_px,
):
    active = _active_fixed_segment(
        segments,
        time_seconds,
    )
    if active is None:
        return frame

    mask = _segment_bbox_mask(
        frame.shape[1],
        frame.shape[0],
        active["bbox"],
        int(padding_px),
    )

    return cv2.inpaint(
        frame,
        mask,
        float(inpaint_radius),
        cv2.INPAINT_TELEA,
    )


def _render_shape_dynamic_combined_compare(
    video_path,
    out_path,
    center_time,
    clip_seconds,
    tile_shape,
    grid_points,
    gains,
    fixed_segments,
    fixed_inpaint_radius,
    fixed_padding_px,
    background_blur_sigma,
    runtime_alpha_percentile,
    min_runtime_alpha,
    max_runtime_alpha,
    fps,
    width,
    height,
    duration,
    crf,
    preset,
):
    half = float(clip_seconds) / 2.0
    start = max(0.0, float(center_time) - half)
    end = float(center_time) + half
    if duration > 0:
        end = min(duration, end)

    pane_count = 1 + len(gains)
    out_width = int(width) * pane_count

    writer, runtime = _open_x264_raw_writer(
        out_path,
        out_width,
        int(height),
        float(fps),
        int(crf),
        str(preset),
    )

    cap = cv2.VideoCapture(str(video_path))
    if not cap.isOpened():
        try:
            writer.stdin.close()
        except Exception:
            pass
        writer.kill()
        raise HTTPException(
            status_code=422,
            detail="Could not open source video.",
        )

    cap.set(
        cv2.CAP_PROP_POS_MSEC,
        start * 1000.0,
    )

    frame_index = 0
    frames_written = 0
    write_error = None

    try:
        while True:
            ok, frame = cap.read()
            if not ok or frame is None:
                break

            t = start + frame_index / float(fps)
            if t > end + 0.5 / float(fps):
                break

            panes = [
                _label_pane(frame, "ORIGINAL")
            ]

            for gain in gains:
                tiled, _ = _apply_dynamic_tiled_deblend(
                    frame,
                    tile_shape,
                    grid_points,
                    float(background_blur_sigma),
                    float(runtime_alpha_percentile),
                    float(min_runtime_alpha),
                    float(max_runtime_alpha),
                    float(gain),
                )

                combined = _apply_fixed_segment_if_active(
                    tiled,
                    t,
                    fixed_segments,
                    float(fixed_inpaint_radius),
                    int(fixed_padding_px),
                )

                panes.append(
                    _label_pane(
                        combined,
                        f"COMBINED {float(gain):.02f}",
                    )
                )

            output = np.hstack(panes)

            try:
                writer.stdin.write(
                    output.tobytes()
                )
            except Exception as exc:
                write_error = str(exc)[:500]
                break

            frames_written += 1
            frame_index += 1

    finally:
        cap.release()
        try:
            if writer.stdin:
                writer.stdin.close()
        except Exception:
            pass

    stderr = b""
    try:
        stderr = writer.stderr.read() if writer.stderr else b""
    except Exception:
        pass

    code = writer.wait()

    ok = (
        code == 0
        and write_error is None
        and out_path.exists()
    )

    return {
        "ok": ok,
        "center_time_seconds": round(float(center_time), 3),
        "clip_start_seconds": round(start, 3),
        "clip_end_seconds": round(end, 3),
        "frames_written": frames_written,
        "pane_count": pane_count,
        "output_size": {
            "width": out_width,
            "height": int(height),
        },
        "relative_path": (
            out_path.relative_to(WORKSPACE).as_posix()
            if out_path.exists()
            else None
        ),
        "gain_values": [float(x) for x in gains],
        "fixed_logo_applied_when_segment_active": True,
        "encoder": {
            "engine": "ffmpeg",
            "codec": "libx264",
            "crf": int(crf),
            "preset": str(preset),
            "runtime": runtime,
        },
        "error": (
            write_error
            or (
                stderr.decode(
                    "utf-8",
                    errors="replace",
                )[:800]
                if code != 0
                else None
            )
        ),
    }


def _tiled_shape_dynamic_preview_sync(
    req: BrandingTiledShapeDynamicPreviewRequest
):
    router_path = _safe_workspace_path(
        req.router_report_relative_path
    )
    try:
        router = json.loads(
            router_path.read_text(encoding="utf-8")
        )
    except Exception as exc:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "tiled_shape_dynamic_preview",
                "error": "invalid_router_report",
                "message": str(exc)[:500],
            },
        )

    source_rel = (
        (router.get("source") or {})
        .get("relative_path")
    )
    if not source_rel:
        raise HTTPException(
            status_code=422,
            detail="Router report has no source path.",
        )

    fixed_layer = _find_router_layer(
        router,
        req.fixed_layer_id,
    )
    tiled_layer = _find_router_layer(
        router,
        req.tiled_layer_id,
    )

    if str(fixed_layer.get("handler")) != "fixed_strong_roi":
        raise HTTPException(
            status_code=422,
            detail="fixed_layer_id is not fixed_strong_roi.",
        )
    if str(tiled_layer.get("handler")) != "diagonal_tiled_grid":
        raise HTTPException(
            status_code=422,
            detail="tiled_layer_id is not diagonal_tiled_grid.",
        )

    report_rel, grid_report = _three_anchor_grid_report_from_router(
        router,
        tiled_layer,
    )

    video_path = _safe_workspace_path(source_rel)

    rebuilt = _rebuild_tiled_shape_probability(
        video_path,
        grid_report,
        float(req.sample_interval_seconds),
        int(req.max_frames),
        int(req.max_tile_samples),
        float(req.background_blur_sigma),
        float(req.residual_floor_percentile),
        float(req.aggregate_percentile),
        float(req.presence_threshold_percentile),
        float(req.min_presence_ratio),
        float(req.shape_core_percentile),
        int(req.shape_dilate_iterations),
    )

    fixed = _load_fixed_execution_segments(
        fixed_layer,
        source_rel,
    )

    meta = rebuilt["video_metadata"]
    width = int(meta.get("width") or 0)
    height = int(meta.get("height") or 0)
    fps = float(meta.get("fps") or 30.0)
    duration = float(meta.get("duration_seconds") or 0.0)

    gains = sorted({
        round(float(x), 4)
        for x in req.alpha_gain_values
    })
    if (
        not gains
        or len(gains) > 5
        or any(x <= 0 or x > 2.5 for x in gains)
    ):
        raise HTTPException(
            status_code=422,
            detail="Use 1-5 alpha_gain_values in (0, 2.5].",
        )

    timestamp = _app_now().strftime(
        "%Y-%m-%d_%H%M%S"
    )
    out_dir = (
        WORKSPACE
        / "review"
        / "branding_tiled_shape_dynamic"
        / timestamp
        / video_path.stem
    )
    out_dir.mkdir(parents=True, exist_ok=True)

    def save_float_autocontrast(path, arr):
        a = np.asarray(arr, dtype=np.float32)
        positive = a[a > 0]
        if positive.size:
            lo = float(np.percentile(positive, 5.0))
            hi = float(np.percentile(positive, 99.0))
            if hi > lo + 1e-8:
                vis = np.clip(
                    (a - lo) / (hi - lo),
                    0.0,
                    1.0,
                )
            else:
                vis = (a > 0).astype(np.float32)
        else:
            vis = np.zeros_like(a)
        cv2.imwrite(
            str(path),
            (vis * 255.0).astype(np.uint8),
        )

    aggregate_path = out_dir / "01_tile_aggregate_autocontrast.png"
    presence_path = out_dir / "02_tile_presence_autocontrast.png"
    shape_path = out_dir / "03_tile_shape_probability_autocontrast.png"
    core_path = out_dir / "04_tile_shape_core_mask.png"
    full_shape_path = out_dir / "05_full_grid_shape_autocontrast.png"

    save_float_autocontrast(
        aggregate_path,
        rebuilt["aggregate"],
    )
    save_float_autocontrast(
        presence_path,
        rebuilt["presence_ratio"],
    )
    save_float_autocontrast(
        shape_path,
        rebuilt["shape_probability"],
    )
    cv2.imwrite(
        str(core_path),
        rebuilt["core_mask"],
    )

    full_shape = _paste_shape_to_full_grid(
        rebuilt["shape_probability"],
        rebuilt["grid_points"],
        width,
        height,
    )
    save_float_autocontrast(
        full_shape_path,
        full_shape,
    )

    # Include at least one known fixed-logo time among preview centers, so the
    # user can verify both handlers in the same output.
    fixed_times = _fixed_segment_preview_times(
        fixed["segments"],
        max(1, min(2, int(req.preview_count))),
    )
    tiled_times = _tiled_preview_times(
        duration,
        int(req.preview_count),
    )

    preview_times = []
    for t in fixed_times + tiled_times:
        if not any(abs(float(t) - old) < 0.5 for old in preview_times):
            preview_times.append(float(t))
        if len(preview_times) >= int(req.preview_count):
            break

    previews = []
    for idx, t in enumerate(preview_times, 1):
        out_path = (
            out_dir
            / f"combined_dynamic_{idx:02d}_hq_compare.mp4"
        )
        previews.append(
            _render_shape_dynamic_combined_compare(
                video_path,
                out_path,
                float(t),
                float(req.clip_seconds),
                rebuilt["shape_probability"],
                rebuilt["grid_points"],
                gains,
                fixed["segments"],
                float(req.fixed_inpaint_radius),
                int(req.fixed_segment_padding_px),
                float(req.background_blur_sigma),
                float(req.runtime_alpha_percentile),
                float(req.min_runtime_alpha),
                float(req.max_runtime_alpha),
                fps,
                width,
                height,
                duration,
                int(req.crf),
                str(req.preset),
            )
        )

    shape_positive = rebuilt[
        "shape_probability"
    ][
        rebuilt["shape_probability"] > 0
    ]

    result = {
        "ok": all(x.get("ok") for x in previews),
        "version": "0.17.0",
        "mode": "branding_tiled_shape_dynamic_preview",
        "source": {
            "relative_path": source_rel,
            "router_report_relative_path": (
                router_path.relative_to(WORKSPACE).as_posix()
            ),
            "three_anchor_report_relative_path": report_rel,
        },
        "video": meta,
        "summary": {
            "fixed_strong_handler": "segment_aware_legacy_local_inpaint",
            "fixed_strong_status": "FROZEN_PASS_AND_INCLUDED",
            "v0_9_16_photometric_absolute_alpha": "FAILED",
            "new_tiled_strategy": "shape_probability_plus_per_tile_per_frame_alpha",
            "tile_sample_count": rebuilt["sample_count"],
            "sampled_frame_count": rebuilt["sampled_frame_count"],
            "complete_grid_tile_count": len(rebuilt["usable_points"]),
            "preview_count": len(previews),
            "source_video_modified": False,
            "full_processed_video_created": False,
            "manual_visual_confirmation_required": True,
        },
        "shape_reconstruction": {
            "background_blur_sigma": float(req.background_blur_sigma),
            "residual_floor_percentile": float(req.residual_floor_percentile),
            "aggregate_percentile": float(req.aggregate_percentile),
            "presence_threshold_percentile": float(
                req.presence_threshold_percentile
            ),
            "min_presence_ratio": float(req.min_presence_ratio),
            "shape_core_percentile": float(req.shape_core_percentile),
            "effective_interval_seconds": rebuilt[
                "effective_interval_seconds"
            ],
            "nonzero_shape_ratio": round(
                float(np.count_nonzero(
                    rebuilt["shape_probability"] > 0
                ))
                / float(max(
                    1,
                    rebuilt["tile_width"] * rebuilt["tile_height"],
                )),
                8,
            ),
            "median_positive_shape": (
                round(float(np.median(shape_positive)), 6)
                if shape_positive.size
                else 0.0
            ),
        },
        "runtime_alpha": {
            "gain_values": gains,
            "runtime_alpha_percentile": float(
                req.runtime_alpha_percentile
            ),
            "min_runtime_alpha": float(req.min_runtime_alpha),
            "max_runtime_alpha": float(req.max_runtime_alpha),
            "note": (
                "Alpha strength is estimated independently for each visible "
                "grid tile in every frame. The learned template supplies shape only."
            ),
        },
        "fixed_logo": {
            "mask_review_relative_path": fixed[
                "mask_review_relative_path"
            ],
            "execution_segments": fixed["segments"],
            "note": (
                "The previously approved fixed-logo handler is applied inside "
                "the combined preview whenever its validated time segment is active."
            ),
        },
        "diagnostic_images": {
            "tile_aggregate_autocontrast": (
                aggregate_path.relative_to(WORKSPACE).as_posix()
            ),
            "tile_presence_autocontrast": (
                presence_path.relative_to(WORKSPACE).as_posix()
            ),
            "tile_shape_probability_autocontrast": (
                shape_path.relative_to(WORKSPACE).as_posix()
            ),
            "tile_shape_core_mask": (
                core_path.relative_to(WORKSPACE).as_posix()
            ),
            "full_grid_shape_autocontrast": (
                full_shape_path.relative_to(WORKSPACE).as_posix()
            ),
        },
        "preview": {
            "times_seconds": [
                round(float(x), 3)
                for x in preview_times
            ],
            "clips": previews,
            "pane_layout": (
                "ORIGINAL | COMBINED 0.75 | COMBINED 1.00 | COMBINED 1.25 "
                "(for default gain values)"
            ),
        },
        "interpretation": {
            "first_check": (
                "03_tile_shape_probability_autocontrast.png must visibly resemble "
                "the ReelShort letter/word structure. This diagnostic is auto-contrasted, "
                "so a faint valid shape will no longer appear as a misleading black image."
            ),
            "second_check": (
                "Combined preview clips now include the approved fixed-logo treatment "
                "during its validated time segments."
            ),
        },
        "output_relative_dir": (
            out_dir.relative_to(WORKSPACE).as_posix()
        ),
    }

    report_path = (
        out_dir
        / f"{video_path.stem}.tiled-shape-dynamic-preview.json"
    )
    result["report_relative_path"] = (
        report_path.relative_to(WORKSPACE).as_posix()
    )
    report_path.write_text(
        json.dumps(
            result,
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )

    return result




class BrandingStrongLogoTemplatePreviewRequest(BaseModel):
    router_report_relative_path: str
    fixed_layer_id: str = "census-1-fixed-strong"
    tiled_layer_id: str = "three-anchor-grid"

    # Pick a clear strong-logo frame from the fixed-logo execution windows.
    preferred_logo_time_seconds: Optional[float] = None

    # Strong ReelShort logo is magenta/pink. Extract chromatic text pixels,
    # then discard the left icon portion and keep the wordmark.
    strong_logo_hsv_s_min: int = 70
    strong_logo_hsv_v_min: int = 100
    strong_logo_wordmark_left_ratio: float = 0.18
    strong_logo_mask_close_iterations: int = 1
    strong_logo_mask_dilate_iterations: int = 1

    # When mapping the strong wordmark mask to the faint tile, preserve
    # horizontally centered text with a small inset.
    tile_horizontal_inset_ratio: float = 0.04
    tile_vertical_inset_ratio: float = 0.10

    # Estimate faint overlay alpha independently per tile/frame under the
    # trusted brand-shaped mask.
    alpha_gain_values: list[float] = Field(
        default_factory=lambda: [0.75, 1.0, 1.25]
    )
    min_runtime_alpha: float = 0.004
    max_runtime_alpha: float = 0.14
    runtime_alpha_percentile: float = 58.0
    local_background_sigma: float = 4.0

    fixed_inpaint_radius: float = 3.0
    fixed_segment_padding_px: int = 2

    clip_seconds: float = 2.0
    preview_count: int = 3
    crf: int = 15
    preset: str = "slow"


def _choose_strong_logo_time(fixed_segments, preferred):
    if preferred is not None:
        t = float(preferred)
        if any(
            float(s["start_seconds"]) <= t <= float(s["end_seconds"])
            for s in fixed_segments
        ):
            return t

    # Choose the middle of the longest validated fixed-logo segment.
    ordered = sorted(
        fixed_segments,
        key=lambda s: (
            float(s["end_seconds"]) - float(s["start_seconds"])
        ),
        reverse=True,
    )
    if not ordered:
        raise HTTPException(
            status_code=422,
            detail="No validated fixed-logo segments.",
        )

    s = ordered[0]
    return (
        float(s["start_seconds"])
        + float(s["end_seconds"])
    ) / 2.0


def _read_frame_at(video_path, time_seconds):
    cap = cv2.VideoCapture(str(video_path))
    if not cap.isOpened():
        raise HTTPException(
            status_code=422,
            detail="Could not open source video.",
        )
    try:
        cap.set(
            cv2.CAP_PROP_POS_MSEC,
            float(time_seconds) * 1000.0,
        )
        ok, frame = cap.read()
        if not ok or frame is None:
            raise HTTPException(
                status_code=422,
                detail={
                    "error": "could_not_read_frame",
                    "time_seconds": float(time_seconds),
                },
            )
        return frame
    finally:
        cap.release()


def _extract_strong_reelshort_wordmark_mask(
    frame,
    bbox,
    s_min,
    v_min,
    left_ratio,
    close_iterations,
    dilate_iterations,
):
    h, w = frame.shape[:2]
    b = _clip_bbox(bbox, w, h)

    crop = frame[
        b["y"]:b["y"] + b["height"],
        b["x"]:b["x"] + b["width"],
    ].copy()

    if crop.size == 0:
        raise HTTPException(
            status_code=422,
            detail="Strong-logo crop is empty.",
        )

    hsv = cv2.cvtColor(
        crop,
        cv2.COLOR_BGR2HSV,
    )

    # Pink/magenta ReelShort wordmark: saturation/value are much more stable
    # than a hard hue interval under compression and glow effects.
    sat = hsv[..., 1]
    val = hsv[..., 2]

    mask = (
        (sat >= int(s_min))
        & (val >= int(v_min))
    ).astype(np.uint8) * 255

    # Suppress the left ReelShort icon. The faint tiled watermark is the
    # wordmark text, not the square R icon.
    x_cut = int(round(
        crop.shape[1] * float(left_ratio)
    ))
    x_cut = max(0, min(crop.shape[1] - 1, x_cut))
    mask[:, :x_cut] = 0

    # Remove tiny chroma speckles.
    mask = cv2.morphologyEx(
        mask,
        cv2.MORPH_OPEN,
        np.ones((2, 2), dtype=np.uint8),
        iterations=1,
    )

    if int(close_iterations) > 0:
        mask = cv2.morphologyEx(
            mask,
            cv2.MORPH_CLOSE,
            np.ones((3, 3), dtype=np.uint8),
            iterations=int(close_iterations),
        )

    # Keep connected components that look like parts of the horizontal
    # wordmark. This rejects isolated background chroma.
    num_labels, labels, stats, _ = cv2.connectedComponentsWithStats(
        (mask > 0).astype(np.uint8),
        connectivity=8,
    )

    cleaned = np.zeros_like(mask)
    min_area = max(3, int(round(crop.shape[0] * crop.shape[1] * 0.0008)))

    kept = 0
    for label in range(1, num_labels):
        area = int(stats[label, cv2.CC_STAT_AREA])
        bw = int(stats[label, cv2.CC_STAT_WIDTH])
        bh = int(stats[label, cv2.CC_STAT_HEIGHT])

        if area < min_area:
            continue
        if bh < max(3, int(crop.shape[0] * 0.10)):
            continue
        if bw < 2:
            continue

        cleaned[labels == label] = 255
        kept += 1

    if kept < 3 or np.count_nonzero(cleaned) < 40:
        # Fallback to the raw chroma mask rather than failing silently.
        cleaned = mask

    if int(dilate_iterations) > 0:
        cleaned = cv2.dilate(
            cleaned,
            np.ones((3, 3), dtype=np.uint8),
            iterations=int(dilate_iterations),
        )

    coords = cv2.findNonZero(cleaned)
    if coords is None:
        raise HTTPException(
            status_code=422,
            detail="Could not extract strong ReelShort wordmark mask.",
        )

    x, y, ww, hh = cv2.boundingRect(coords)

    # Tight wordmark mask.
    tight = cleaned[
        y:y + hh,
        x:x + ww,
    ].copy()

    tight_crop = crop[
        y:y + hh,
        x:x + ww,
    ].copy()

    return {
        "roi_bbox": b,
        "crop": crop,
        "raw_mask": mask,
        "clean_mask": cleaned,
        "tight_mask": tight,
        "tight_crop": tight_crop,
        "tight_bbox_in_roi": {
            "x": int(x),
            "y": int(y),
            "width": int(ww),
            "height": int(hh),
        },
    }


def _map_wordmark_mask_to_tile(
    strong_tight_mask,
    tile_width,
    tile_height,
    horizontal_inset_ratio,
    vertical_inset_ratio,
):
    tile_width = int(tile_width)
    tile_height = int(tile_height)

    inset_x = max(
        0,
        int(round(
            tile_width * float(horizontal_inset_ratio)
        )),
    )
    inset_y = max(
        0,
        int(round(
            tile_height * float(vertical_inset_ratio)
        )),
    )

    target_w = max(
        4,
        tile_width - 2 * inset_x,
    )
    target_h = max(
        4,
        tile_height - 2 * inset_y,
    )

    # Preserve the strong wordmark aspect ratio and fit inside tile.
    sh, sw = strong_tight_mask.shape[:2]
    scale = min(
        target_w / float(max(1, sw)),
        target_h / float(max(1, sh)),
    )

    rw = max(2, int(round(sw * scale)))
    rh = max(2, int(round(sh * scale)))

    resized = cv2.resize(
        strong_tight_mask,
        (rw, rh),
        interpolation=cv2.INTER_AREA
        if scale < 1.0
        else cv2.INTER_CUBIC,
    )

    # Preserve antialiasing as soft shape probability.
    shape = resized.astype(np.float32) / 255.0

    canvas = np.zeros(
        (tile_height, tile_width),
        dtype=np.float32,
    )

    x1 = max(
        0,
        int(round((tile_width - rw) / 2.0)),
    )
    y1 = max(
        0,
        int(round((tile_height - rh) / 2.0)),
    )
    x2 = min(tile_width, x1 + rw)
    y2 = min(tile_height, y1 + rh)

    canvas[
        y1:y2,
        x1:x2,
    ] = shape[
        :y2 - y1,
        :x2 - x1,
    ]

    canvas = cv2.GaussianBlur(
        canvas,
        (3, 3),
        0,
    )

    return canvas


def _runtime_alpha_from_brand_mask(
    crop_bgr,
    tile_shape,
    background_sigma,
    runtime_percentile,
    min_alpha,
    max_alpha,
):
    gray = cv2.cvtColor(
        crop_bgr,
        cv2.COLOR_BGR2GRAY,
    ).astype(np.float32) / 255.0

    bg = cv2.GaussianBlur(
        gray,
        (0, 0),
        sigmaX=max(1.0, float(background_sigma)),
        sigmaY=max(1.0, float(background_sigma)),
    )

    candidate = np.clip(
        (gray - bg)
        / np.maximum(1.0 - bg, 0.10),
        0.0,
        float(max_alpha),
    )

    core = tile_shape >= 0.35
    values = candidate[core]
    values = values[
        values >= float(min_alpha)
    ]

    if values.size < 8:
        return 0.0

    alpha = float(np.percentile(
        values,
        float(runtime_percentile),
    ))

    return float(np.clip(
        alpha,
        float(min_alpha),
        float(max_alpha),
    ))


def _apply_brand_template_tiled_deblend(
    frame,
    tile_shape,
    grid_points,
    gain,
    background_sigma,
    runtime_percentile,
    min_alpha,
    max_alpha,
):
    h, w = frame.shape[:2]
    th, tw = tile_shape.shape[:2]

    alpha_full = np.zeros(
        (h, w),
        dtype=np.float32,
    )

    for point in grid_points:
        center = point.get("center") or {}
        cx = float(center.get("x") or 0.0)
        cy = float(center.get("y") or 0.0)

        x1 = int(round(cx - tw / 2.0))
        y1 = int(round(cy - th / 2.0))
        x2 = x1 + tw
        y2 = y1 + th

        if (
            x1 < 0 or y1 < 0
            or x2 > w or y2 > h
        ):
            continue

        crop = frame[y1:y2, x1:x2]

        alpha_scalar = _runtime_alpha_from_brand_mask(
            crop,
            tile_shape,
            float(background_sigma),
            float(runtime_percentile),
            float(min_alpha),
            float(max_alpha),
        )

        if alpha_scalar <= 0:
            continue

        tile_alpha = np.clip(
            tile_shape
            * alpha_scalar
            * float(gain),
            0.0,
            float(max_alpha),
        )

        target = alpha_full[y1:y2, x1:x2]
        np.maximum(
            target,
            tile_alpha,
            out=target,
        )

    observed = frame.astype(np.float32) / 255.0
    alpha3 = alpha_full[..., None]

    restored = (
        observed - alpha3
    ) / np.maximum(
        1.0 - alpha3,
        0.60,
    )

    restored = np.where(
        alpha3 > 1e-8,
        restored,
        observed,
    )

    return (
        np.clip(
            restored * 255.0,
            0,
            255,
        ).astype(np.uint8),
        alpha_full,
    )


def _render_brand_template_combined_compare(
    video_path,
    out_path,
    center_time,
    clip_seconds,
    tile_shape,
    grid_points,
    gains,
    fixed_segments,
    fixed_inpaint_radius,
    fixed_padding_px,
    background_sigma,
    runtime_percentile,
    min_alpha,
    max_alpha,
    fps,
    width,
    height,
    duration,
    crf,
    preset,
):
    half = float(clip_seconds) / 2.0
    start = max(
        0.0,
        float(center_time) - half,
    )
    end = float(center_time) + half

    if duration > 0:
        end = min(duration, end)

    pane_count = 1 + len(gains)
    writer, runtime = _open_x264_raw_writer(
        out_path,
        int(width) * pane_count,
        int(height),
        float(fps),
        int(crf),
        str(preset),
    )

    cap = cv2.VideoCapture(str(video_path))
    if not cap.isOpened():
        try:
            writer.stdin.close()
        except Exception:
            pass
        writer.kill()
        raise HTTPException(
            status_code=422,
            detail="Could not open source video.",
        )

    cap.set(
        cv2.CAP_PROP_POS_MSEC,
        start * 1000.0,
    )

    frame_index = 0
    frames_written = 0
    write_error = None

    try:
        while True:
            ok, frame = cap.read()
            if not ok or frame is None:
                break

            t = start + frame_index / float(fps)
            if t > end + 0.5 / float(fps):
                break

            panes = [
                _label_pane(
                    frame,
                    "ORIGINAL",
                )
            ]

            for gain in gains:
                tiled, _ = _apply_brand_template_tiled_deblend(
                    frame,
                    tile_shape,
                    grid_points,
                    float(gain),
                    float(background_sigma),
                    float(runtime_percentile),
                    float(min_alpha),
                    float(max_alpha),
                )

                combined = _apply_fixed_segment_if_active(
                    tiled,
                    t,
                    fixed_segments,
                    float(fixed_inpaint_radius),
                    int(fixed_padding_px),
                )

                panes.append(
                    _label_pane(
                        combined,
                        f"BRAND {float(gain):.02f}",
                    )
                )

            output = np.hstack(panes)

            try:
                writer.stdin.write(
                    output.tobytes()
                )
            except Exception as exc:
                write_error = str(exc)[:500]
                break

            frames_written += 1
            frame_index += 1

    finally:
        cap.release()
        try:
            if writer.stdin:
                writer.stdin.close()
        except Exception:
            pass

    stderr = b""
    try:
        stderr = (
            writer.stderr.read()
            if writer.stderr
            else b""
        )
    except Exception:
        pass

    code = writer.wait()

    return {
        "ok": (
            code == 0
            and write_error is None
            and out_path.exists()
        ),
        "center_time_seconds": round(
            float(center_time),
            3,
        ),
        "clip_start_seconds": round(
            start,
            3,
        ),
        "clip_end_seconds": round(
            end,
            3,
        ),
        "frames_written": frames_written,
        "pane_count": pane_count,
        "relative_path": (
            out_path
            .relative_to(WORKSPACE)
            .as_posix()
            if out_path.exists()
            else None
        ),
        "gain_values": [
            float(x)
            for x in gains
        ],
        "error": (
            write_error
            or (
                stderr.decode(
                    "utf-8",
                    errors="replace",
                )[:800]
                if code != 0
                else None
            )
        ),
        "encoder": {
            "engine": "ffmpeg",
            "codec": "libx264",
            "crf": int(crf),
            "preset": str(preset),
            "runtime": runtime,
        },
    }


def _strong_logo_template_preview_sync(
    req: BrandingStrongLogoTemplatePreviewRequest
):
    router_path = _safe_workspace_path(
        req.router_report_relative_path
    )
    try:
        router = json.loads(
            router_path.read_text(
                encoding="utf-8"
            )
        )
    except Exception as exc:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "strong_logo_template_preview",
                "error": "invalid_router_report",
                "message": str(exc)[:500],
            },
        )

    source_rel = (
        (router.get("source") or {})
        .get("relative_path")
    )
    if not source_rel:
        raise HTTPException(
            status_code=422,
            detail="Router report has no source path.",
        )

    fixed_layer = _find_router_layer(
        router,
        req.fixed_layer_id,
    )
    tiled_layer = _find_router_layer(
        router,
        req.tiled_layer_id,
    )

    if str(fixed_layer.get("handler")) != "fixed_strong_roi":
        raise HTTPException(
            status_code=422,
            detail="fixed_layer_id is not fixed_strong_roi.",
        )
    if str(tiled_layer.get("handler")) != "diagonal_tiled_grid":
        raise HTTPException(
            status_code=422,
            detail="tiled_layer_id is not diagonal_tiled_grid.",
        )

    fixed = _load_fixed_execution_segments(
        fixed_layer,
        source_rel,
    )

    grid_report_rel, grid_report = _three_anchor_grid_report_from_router(
        router,
        tiled_layer,
    )

    video_path = _safe_workspace_path(
        source_rel
    )

    cap = cv2.VideoCapture(str(video_path))
    if not cap.isOpened():
        raise HTTPException(
            status_code=422,
            detail="Could not open source video.",
        )
    try:
        meta = _video_metadata(cap)
    finally:
        cap.release()

    width = int(meta.get("width") or 0)
    height = int(meta.get("height") or 0)
    fps = float(meta.get("fps") or 30.0)
    duration = float(
        meta.get("duration_seconds") or 0.0
    )

    strong_time = _choose_strong_logo_time(
        fixed["segments"],
        req.preferred_logo_time_seconds,
    )

    frame = _read_frame_at(
        video_path,
        strong_time,
    )

    fixed_bbox = (
        (fixed_layer.get("evidence") or {})
        .get("bbox")
    )
    if not fixed_bbox:
        raise HTTPException(
            status_code=422,
            detail="Fixed layer has no bbox.",
        )

    extracted = _extract_strong_reelshort_wordmark_mask(
        frame,
        fixed_bbox,
        int(req.strong_logo_hsv_s_min),
        int(req.strong_logo_hsv_v_min),
        float(req.strong_logo_wordmark_left_ratio),
        int(req.strong_logo_mask_close_iterations),
        int(req.strong_logo_mask_dilate_iterations),
    )

    canonical = grid_report.get(
        "canonical_tile"
    ) or {}
    tile_w = int(
        canonical.get("width") or 0
    )
    tile_h = int(
        canonical.get("height") or 0
    )

    if tile_w <= 0 or tile_h <= 0:
        raise HTTPException(
            status_code=422,
            detail="Invalid canonical tiled watermark size.",
        )

    tile_shape = _map_wordmark_mask_to_tile(
        extracted["tight_mask"],
        tile_w,
        tile_h,
        float(req.tile_horizontal_inset_ratio),
        float(req.tile_vertical_inset_ratio),
    )

    grid_points = (
        (grid_report.get("grid") or {})
        .get("predicted_grid_points")
        or []
    )
    if not grid_points:
        raise HTTPException(
            status_code=422,
            detail="No predicted grid points.",
        )

    gains = sorted({
        round(float(x), 4)
        for x in req.alpha_gain_values
    })

    if (
        not gains
        or len(gains) > 5
        or any(x <= 0 or x > 2.5 for x in gains)
    ):
        raise HTTPException(
            status_code=422,
            detail="Use 1-5 alpha gains in (0, 2.5].",
        )

    timestamp = _app_now().strftime(
        "%Y-%m-%d_%H%M%S"
    )
    out_dir = (
        WORKSPACE
        / "review"
        / "branding_strong_logo_template"
        / timestamp
        / video_path.stem
    )
    out_dir.mkdir(
        parents=True,
        exist_ok=True,
    )

    strong_crop_path = (
        out_dir
        / "01_strong_logo_crop.jpg"
    )
    strong_mask_path = (
        out_dir
        / "02_strong_wordmark_mask.png"
    )
    tile_shape_path = (
        out_dir
        / "03_mapped_tile_wordmark_shape.png"
    )
    grid_shape_path = (
        out_dir
        / "04_full_grid_brand_shape.png"
    )

    cv2.imwrite(
        str(strong_crop_path),
        extracted["crop"],
    )
    cv2.imwrite(
        str(strong_mask_path),
        extracted["tight_mask"],
    )
    cv2.imwrite(
        str(tile_shape_path),
        np.clip(
            tile_shape * 255.0,
            0,
            255,
        ).astype(np.uint8),
    )

    full_shape = _paste_shape_to_full_grid(
        tile_shape,
        grid_points,
        width,
        height,
    )
    cv2.imwrite(
        str(grid_shape_path),
        np.clip(
            full_shape * 255.0,
            0,
            255,
        ).astype(np.uint8),
    )

    # Include known fixed-logo moments and general tiled scenes.
    fixed_times = _fixed_segment_preview_times(
        fixed["segments"],
        min(2, max(1, int(req.preview_count))),
    )
    tiled_times = _tiled_preview_times(
        duration,
        int(req.preview_count),
    )

    preview_times = []
    for t in fixed_times + tiled_times:
        if not any(
            abs(float(t) - old) < 0.5
            for old in preview_times
        ):
            preview_times.append(float(t))
        if len(preview_times) >= int(req.preview_count):
            break

    previews = []

    for idx, t in enumerate(
        preview_times,
        1,
    ):
        out_path = (
            out_dir
            / f"brand_template_{idx:02d}_hq_compare.mp4"
        )

        previews.append(
            _render_brand_template_combined_compare(
                video_path,
                out_path,
                float(t),
                float(req.clip_seconds),
                tile_shape,
                grid_points,
                gains,
                fixed["segments"],
                float(req.fixed_inpaint_radius),
                int(req.fixed_segment_padding_px),
                float(req.local_background_sigma),
                float(req.runtime_alpha_percentile),
                float(req.min_runtime_alpha),
                float(req.max_runtime_alpha),
                fps,
                width,
                height,
                duration,
                int(req.crf),
                str(req.preset),
            )
        )

    result = {
        "ok": all(
            x.get("ok")
            for x in previews
        ),
        "version": "0.17.0",
        "mode": "branding_strong_logo_template_preview",
        "source": {
            "relative_path": source_rel,
            "router_report_relative_path": (
                router_path
                .relative_to(WORKSPACE)
                .as_posix()
            ),
            "three_anchor_report_relative_path": grid_report_rel,
        },
        "video": meta,
        "summary": {
            "fixed_strong_status": "FROZEN_PASS_AND_INCLUDED",
            "tiled_template_source": "strong_logo_wordmark",
            "background_reconstruction_template_abandoned": True,
            "strong_logo_sample_time_seconds": round(
                float(strong_time),
                3,
            ),
            "grid_point_count": len(grid_points),
            "preview_count": len(previews),
            "source_video_modified": False,
            "full_processed_video_created": False,
            "manual_visual_confirmation_required": True,
        },
        "strong_template": {
            "fixed_logo_bbox": fixed_bbox,
            "tight_wordmark_bbox_in_roi": extracted[
                "tight_bbox_in_roi"
            ],
            "canonical_tile_width": tile_w,
            "canonical_tile_height": tile_h,
            "note": (
                "The faint tiled watermark shape is no longer inferred from "
                "background texture. Its geometry comes from the clear strong "
                "ReelShort wordmark in the same source video."
            ),
        },
        "runtime_alpha": {
            "gain_values": gains,
            "min_runtime_alpha": float(
                req.min_runtime_alpha
            ),
            "max_runtime_alpha": float(
                req.max_runtime_alpha
            ),
            "runtime_alpha_percentile": float(
                req.runtime_alpha_percentile
            ),
            "local_background_sigma": float(
                req.local_background_sigma
            ),
        },
        "diagnostic_images": {
            "strong_logo_crop": (
                strong_crop_path
                .relative_to(WORKSPACE)
                .as_posix()
            ),
            "strong_wordmark_mask": (
                strong_mask_path
                .relative_to(WORKSPACE)
                .as_posix()
            ),
            "mapped_tile_wordmark_shape": (
                tile_shape_path
                .relative_to(WORKSPACE)
                .as_posix()
            ),
            "full_grid_brand_shape": (
                grid_shape_path
                .relative_to(WORKSPACE)
                .as_posix()
            ),
        },
        "preview": {
            "times_seconds": [
                round(float(x), 3)
                for x in preview_times
            ],
            "pane_layout": (
                "ORIGINAL | BRAND 0.75 | BRAND 1.00 | BRAND 1.25 "
                "(for default gain values)"
            ),
            "clips": previews,
        },
        "interpretation": {
            "first_check": (
                "02_strong_wordmark_mask.png should contain the ReelShort text "
                "shape without the left R icon. 03_mapped_tile_wordmark_shape.png "
                "should look like that wordmark fitted into one faint-watermark tile."
            ),
            "second_check": (
                "Only if the mapped wordmark shape matches the faint tile should "
                "the HQ previews be judged. Fixed-logo removal is included in the "
                "combined preview during validated fixed-logo times."
            ),
        },
        "output_relative_dir": (
            out_dir
            .relative_to(WORKSPACE)
            .as_posix()
        ),
    }

    report_path = (
        out_dir
        / f"{video_path.stem}.strong-logo-template-preview.json"
    )
    result["report_relative_path"] = (
        report_path
        .relative_to(WORKSPACE)
        .as_posix()
    )

    report_path.write_text(
        json.dumps(
            result,
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )

    return result




# ---------------------------------------------------------------------------
# v0.10.0 Brand Replacement Pipeline
# ---------------------------------------------------------------------------

class BrandingReplacementProfileRegisterRequest(BaseModel):
    profile_id: Optional[str] = None
    product_name: str
    brand_name: Optional[str] = None

    logo_image_relative_path: Optional[str] = None
    icon_image_relative_path: Optional[str] = None

    # Optional ready-made assets. If omitted, v0.10.0 can generate a clean
    # diagnostic banner/card from product_name.
    top_banner_image_relative_path: Optional[str] = None
    bottom_banner_image_relative_path: Optional[str] = None
    end_card_image_relative_path: Optional[str] = None
    end_card_video_relative_path: Optional[str] = None
    mid_promo_video_relative_path: Optional[str] = None

    banner_height_ratio: float = 0.075
    end_card_duration_seconds: float = 3.0

    overwrite: bool = False


class BrandingReplacementSegmentCensusRequest(BaseModel):
    router_report_relative_path: str

    # Interior brand-text candidates are expanded to nearby visual cut points,
    # but remain REVIEW because a brand mention inside normal story content is
    # not automatically a replaceable promo segment.
    mid_context_seconds: float = 8.0
    scene_scan_interval_seconds: float = 0.25
    min_scene_cut_score: float = 0.30
    max_mid_segment_seconds: float = 15.0


class BrandingReplacementPlanRequest(BaseModel):
    router_report_relative_path: str
    profile_id: str
    segment_census_report_relative_path: Optional[str] = None
    moving_flow_report_relative_path: Optional[str] = None

    # Moving tracks are diagnostics until visually approved. Setting this true
    # means the caller has reviewed the track drift and accepts overlay-follow.
    moving_tracks_approved: bool = False


class BrandingReplacementPreviewRequest(BaseModel):
    replacement_plan_relative_path: str

    # By default preview AUTO and REVIEW actions, but never modifies source.
    include_review_actions: bool = True

    fixed_preview_seconds: float = 2.0
    dynamic_preview_seconds: float = 3.0
    end_card_preroll_seconds: float = 2.0
    mid_promo_context_seconds: float = 1.25

    crf: int = 15
    preset: str = "slow"


def _replacement_registry_path():
    return (
        WORKSPACE
        / "config"
        / "brand_replacement_profiles.json"
    ).resolve()


def _load_replacement_registry():
    path = _replacement_registry_path()
    if not path.exists():
        return {
            "schema_version": 1,
            "updated_at": None,
            "profiles": [],
        }

    try:
        data = json.loads(
            path.read_text(encoding="utf-8")
        )
    except Exception as exc:
        raise HTTPException(
            status_code=500,
            detail={
                "stage": "replacement_profile_registry",
                "error": "invalid_registry_json",
                "message": str(exc)[:500],
            },
        )

    if not isinstance(data, dict):
        data = {}
    if not isinstance(data.get("profiles"), list):
        data["profiles"] = []

    data["schema_version"] = 1
    return data


def _write_replacement_registry(data):
    path = _replacement_registry_path()
    path.parent.mkdir(
        parents=True,
        exist_ok=True,
    )

    payload = dict(data)
    payload["schema_version"] = 1
    payload["updated_at"] = _app_now().isoformat(
        timespec="seconds"
    )

    tmp = Path(str(path) + ".tmp")
    tmp.write_text(
        json.dumps(
            payload,
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )
    tmp.replace(path)
    return path


def _replacement_profile_id(product_name, brand_name=None):
    import hashlib

    key = (
        _norm_brand_name(brand_name)
        or _norm_brand_name(product_name)
        or "brand"
    )

    digest = hashlib.sha256(
        f"{product_name}|{brand_name or ''}".encode("utf-8")
    ).hexdigest()[:10]

    return f"{key}-{digest}"


def _validate_optional_asset(relative_path, field_name):
    if not relative_path:
        return None

    path = _safe_workspace_path(relative_path)
    if not path.exists():
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "replacement_profile",
                "error": "asset_not_found",
                "field": field_name,
                "relative_path": relative_path,
            },
        )

    return path.relative_to(WORKSPACE).as_posix()


def _replacement_profile_register_sync(
    req: BrandingReplacementProfileRegisterRequest
):
    product_name = str(req.product_name or "").strip()
    if not product_name:
        raise HTTPException(
            status_code=422,
            detail="product_name is required.",
        )

    if not 0.035 <= float(req.banner_height_ratio) <= 0.20:
        raise HTTPException(
            status_code=422,
            detail="banner_height_ratio must be between 0.035 and 0.20.",
        )

    if not 1.0 <= float(req.end_card_duration_seconds) <= 10.0:
        raise HTTPException(
            status_code=422,
            detail="end_card_duration_seconds must be between 1 and 10.",
        )

    profile_id = (
        str(req.profile_id).strip()
        if req.profile_id
        else _replacement_profile_id(
            product_name,
            req.brand_name,
        )
    )

    profile = {
        "profile_id": profile_id,
        "product_name": product_name,
        "brand_name": (
            str(req.brand_name).strip()
            if req.brand_name
            else product_name
        ),
        "assets": {
            "logo_image_relative_path": _validate_optional_asset(
                req.logo_image_relative_path,
                "logo_image_relative_path",
            ),
            "icon_image_relative_path": _validate_optional_asset(
                req.icon_image_relative_path,
                "icon_image_relative_path",
            ),
            "top_banner_image_relative_path": _validate_optional_asset(
                req.top_banner_image_relative_path,
                "top_banner_image_relative_path",
            ),
            "bottom_banner_image_relative_path": _validate_optional_asset(
                req.bottom_banner_image_relative_path,
                "bottom_banner_image_relative_path",
            ),
            "end_card_image_relative_path": _validate_optional_asset(
                req.end_card_image_relative_path,
                "end_card_image_relative_path",
            ),
            "end_card_video_relative_path": _validate_optional_asset(
                req.end_card_video_relative_path,
                "end_card_video_relative_path",
            ),
            "mid_promo_video_relative_path": _validate_optional_asset(
                req.mid_promo_video_relative_path,
                "mid_promo_video_relative_path",
            ),
        },
        "layout": {
            "banner_height_ratio": float(
                req.banner_height_ratio
            ),
            "end_card_duration_seconds": float(
                req.end_card_duration_seconds
            ),
        },
        "created_at": _app_now().isoformat(
            timespec="seconds"
        ),
        "updated_at": _app_now().isoformat(
            timespec="seconds"
        ),
    }

    registry = _load_replacement_registry()
    profiles = list(registry.get("profiles") or [])

    found = None
    for idx, old in enumerate(profiles):
        if str(old.get("profile_id")) == profile_id:
            found = idx
            break

    if found is None:
        profiles.append(profile)
        action = "created"
    elif req.overwrite:
        old_created = profiles[found].get("created_at")
        if old_created:
            profile["created_at"] = old_created
        profiles[found] = profile
        action = "updated"
    else:
        profile = profiles[found]
        action = "reused_existing"

    registry["profiles"] = profiles
    registry_path = _write_replacement_registry(
        registry
    )

    return {
        "ok": True,
        "version": "0.17.0",
        "mode": "branding_replacement_profile_register",
        "action": action,
        "profile": profile,
        "profile_count": len(profiles),
        "registry_relative_path": (
            registry_path
            .relative_to(WORKSPACE)
            .as_posix()
        ),
    }


def _get_replacement_profile(profile_id):
    registry = _load_replacement_registry()

    for profile in registry.get("profiles") or []:
        if str(profile.get("profile_id")) == str(profile_id):
            return profile

    raise HTTPException(
        status_code=422,
        detail={
            "stage": "replacement_plan",
            "error": "replacement_profile_not_found",
            "profile_id": profile_id,
        },
    )


def _frame_histogram_signature(frame):
    small = cv2.resize(
        frame,
        (180, 320),
        interpolation=cv2.INTER_AREA,
    )
    hsv = cv2.cvtColor(
        small,
        cv2.COLOR_BGR2HSV,
    )

    hist = cv2.calcHist(
        [hsv],
        [0, 1],
        None,
        [24, 16],
        [0, 180, 0, 256],
    )
    cv2.normalize(
        hist,
        hist,
        1.0,
        0.0,
        cv2.NORM_L1,
    )
    return hist


def _scene_cut_scores(
    video_path,
    start,
    end,
    interval,
):
    cap = cv2.VideoCapture(str(video_path))
    if not cap.isOpened():
        raise HTTPException(
            status_code=422,
            detail="Could not open source video.",
        )

    samples = []
    t = max(0.0, float(start))
    prev_hist = None
    prev_t = None

    try:
        while t <= float(end) + 1e-9:
            cap.set(
                cv2.CAP_PROP_POS_MSEC,
                t * 1000.0,
            )
            ok, frame = cap.read()

            if ok and frame is not None:
                hist = _frame_histogram_signature(
                    frame
                )

                if prev_hist is not None:
                    correlation = cv2.compareHist(
                        prev_hist,
                        hist,
                        cv2.HISTCMP_CORREL,
                    )
                    score = float(
                        np.clip(
                            1.0 - correlation,
                            0.0,
                            2.0,
                        )
                    )
                    samples.append(
                        {
                            "time_seconds": round(
                                float(t),
                                3,
                            ),
                            "previous_time_seconds": round(
                                float(prev_t),
                                3,
                            ),
                            "cut_score": round(
                                score,
                                6,
                            ),
                        }
                    )

                prev_hist = hist
                prev_t = t

            t += float(interval)

        return samples
    finally:
        cap.release()


def _fullscreen_promo_scene_samples(video_path, duration_seconds, interval):
    """Decode once for visual-regime features and scene transitions.

    OpenCV seeking at every half-second is disproportionately slow in an H.264
    long-GOP source.  A single sequential pass is both deterministic and avoids
    decoding the same compressed frames a second time for the cut detector.
    """
    cap = cv2.VideoCapture(str(video_path))
    if not cap.isOpened():
        raise HTTPException(status_code=422, detail="Could not open source video.")

    fps = float(cap.get(cv2.CAP_PROP_FPS) or 30.0)
    frame_step = max(1, int(round(float(interval) * fps)))
    frames = []
    previous_hist = None
    previous_time = None
    frame_index = 0
    next_frame = 0
    try:
        while True:
            ok, frame = cap.read()
            if not ok or frame is None:
                break
            if frame_index < next_frame:
                frame_index += 1
                continue

            timestamp = min(float(duration_seconds), frame_index / max(1e-6, fps))
            if timestamp > float(duration_seconds) + 1e-6:
                break
            hist = _frame_histogram_signature(frame)
            cut_score = None
            if previous_hist is not None:
                cut_score = float(np.clip(1.0 - cv2.compareHist(previous_hist, hist, cv2.HISTCMP_CORREL), 0.0, 2.0))
            frames.append(
                {
                    "time_seconds": round(timestamp, 3),
                    "previous_time_seconds": round(previous_time, 3) if previous_time is not None else None,
                    "cut_score": round(cut_score, 6) if cut_score is not None else None,
                    **_fullscreen_promo_visual_features(frame),
                }
            )
            previous_hist = hist
            previous_time = timestamp
            next_frame += frame_step
            frame_index += 1
    finally:
        cap.release()

    cuts = [
        {
            "time_seconds": sample["time_seconds"],
            "previous_time_seconds": sample["previous_time_seconds"],
            "cut_score": sample["cut_score"],
        }
        for sample in frames
        if sample.get("cut_score") is not None
    ]
    return frames, cuts


def _fullscreen_promo_visual_features(frame):
    """Low-cost layout features for story-interrupting full-screen inserts.

    This intentionally does not identify a product, language, or CTA text. It
    only describes visual structure: image diversity, grid-like line density,
    and non-narrative central text/card coverage.  These are later accepted
    only with both an entry and an exit scene boundary.
    """
    h, w = frame.shape[:2]
    small = cv2.resize(frame, (144, 256), interpolation=cv2.INTER_AREA)
    gray = cv2.cvtColor(small, cv2.COLOR_BGR2GRAY)
    hsv = cv2.cvtColor(small, cv2.COLOR_BGR2HSV)
    edges = cv2.Canny(gray, 70, 150)

    # Tile/grid walls show many long vertical and horizontal separators.
    horizontal = cv2.morphologyEx(
        edges, cv2.MORPH_OPEN, cv2.getStructuringElement(cv2.MORPH_RECT, (15, 1))
    )
    vertical = cv2.morphologyEx(
        edges, cv2.MORPH_OPEN, cv2.getStructuringElement(cv2.MORPH_RECT, (1, 15))
    )
    grid_line_density = float(np.mean((horizontal > 0) | (vertical > 0)))

    lines = cv2.HoughLinesP(
        edges,
        1,
        np.pi / 180.0,
        threshold=22,
        minLineLength=18,
        maxLineGap=3,
    )
    horizontal_lines = 0
    vertical_lines = 0
    if lines is not None:
        for x1, y1, x2, y2 in lines.reshape(-1, 4):
            dx, dy = abs(int(x2) - int(x1)), abs(int(y2) - int(y1))
            if dx >= 2 * max(1, dy):
                horizontal_lines += 1
            elif dy >= 2 * max(1, dx):
                vertical_lines += 1
    grid_line_count = horizontal_lines + vertical_lines
    balanced_grid_lines = min(horizontal_lines, vertical_lines)

    # Quantized color occupancy distinguishes poster/store grids from a single
    # drama shot without trying to classify any individual poster.
    quantized = cv2.resize(hsv, (24, 42), interpolation=cv2.INTER_AREA)
    hue = (quantized[:, :, 0] // 23).astype(np.int16)
    sat = (quantized[:, :, 1] // 52).astype(np.int16)
    val = (quantized[:, :, 2] // 52).astype(np.int16)
    color_cell_diversity = float(len(np.unique(hue * 64 + sat * 8 + val))) / 256.0

    # Center/lower-middle promotional plates or title cards, excluding the
    # normal bottom subtitle band and persistent top watermark area.
    y0, y1 = int(h * 0.18), int(h * 0.78)
    center = frame[y0:y1, :]
    if center.size:
        center_hsv = cv2.cvtColor(center, cv2.COLOR_BGR2HSV)
        bright_neutral = (
            (center_hsv[:, :, 2] >= 170) & (center_hsv[:, :, 1] <= 115)
        )
        bright_color = center_hsv[:, :, 2] >= 210
        central_card_coverage = float(np.mean(bright_neutral | bright_color))
    else:
        central_card_coverage = 0.0

    visual_score = min(
        1.0,
        0.32 * min(1.0, color_cell_diversity / 0.24)
        + 0.22 * min(1.0, grid_line_density / 0.075)
        + 0.22 * min(1.0, central_card_coverage / 0.26)
        + 0.24 * min(1.0, balanced_grid_lines / 7.0),
    )
    return {
        "color_cell_diversity": round(color_cell_diversity, 6),
        "grid_line_density": round(grid_line_density, 6),
        "horizontal_line_count": int(horizontal_lines),
        "vertical_line_count": int(vertical_lines),
        "balanced_grid_line_count": int(balanced_grid_lines),
        "central_card_coverage": round(central_card_coverage, 6),
        "visual_score": round(visual_score, 6),
    }


def _fullscreen_promo_active_state(sample):
    """Conservative visual regime gate for a full-screen non-story insert."""
    return bool(
        float(sample.get("visual_score") or 0.0) >= 0.66
        and int(sample.get("balanced_grid_line_count") or 0) >= 3
    )


def _fullscreen_promo_story_resume_score(frame, reference_frame=None):
    """Describe a return to a single live-action story composition."""
    small = cv2.resize(frame, (144, 256), interpolation=cv2.INTER_AREA)
    gray = cv2.cvtColor(small, cv2.COLOR_BGR2GRAY)
    hsv = cv2.cvtColor(small, cv2.COLOR_BGR2HSV)
    edges = cv2.Canny(gray, 70, 150)
    horizontal = cv2.morphologyEx(
        edges, cv2.MORPH_OPEN, cv2.getStructuringElement(cv2.MORPH_RECT, (15, 1))
    )
    vertical = cv2.morphologyEx(
        edges, cv2.MORPH_OPEN, cv2.getStructuringElement(cv2.MORPH_RECT, (1, 15))
    )
    grid_density = float(np.mean((horizontal > 0) | (vertical > 0)))
    y0, y1 = int(small.shape[0] * 0.18), int(small.shape[0] * 0.78)
    center = hsv[y0:y1, :]
    card_coverage = (
        float(np.mean((center[:, :, 2] >= 170) & (center[:, :, 1] <= 115)))
        if center.size else 0.0
    )
    motion = 0.0
    if reference_frame is not None:
        reference = cv2.resize(reference_frame, (144, 256), interpolation=cv2.INTER_AREA)
        motion = float(
            np.mean(cv2.absdiff(gray, cv2.cvtColor(reference, cv2.COLOR_BGR2GRAY)))
        ) / 255.0
    # Low score is story-like: sparse separators + no central promo plate.
    score = min(
        1.0,
        0.56 * min(1.0, grid_density / 0.012)
        + 0.34 * min(1.0, card_coverage / 0.16)
        + 0.10 * min(1.0, motion / 0.12),
    )
    return {
        "resume_score": round(score, 6),
        "grid_density": round(grid_density, 6),
        "central_neutral_card_coverage": round(card_coverage, 6),
        "motion": round(motion, 6),
    }


def _fullscreen_promo_refine_exit_boundary(video_path, rough_end_seconds, duration_seconds):
    """Locate earliest sustained story resumption around the broad exit."""
    # Only inspect near the broad visual-regime exit. A larger backtrack can
    # mistake a calm title-card subscene for the actual story resumption.
    start = max(0.0, float(rough_end_seconds) - 3.0)
    end = min(float(duration_seconds), float(rough_end_seconds) + 3.5)
    cap = cv2.VideoCapture(str(video_path))
    if not cap.isOpened():
        return None
    samples = []
    previous = None
    try:
        timestamp = start
        while timestamp <= end + 1e-6:
            cap.set(cv2.CAP_PROP_POS_MSEC, timestamp * 1000.0)
            ok, frame = cap.read()
            if ok and frame is not None:
                samples.append(
                    {
                        "time_seconds": round(timestamp, 3),
                        **_fullscreen_promo_story_resume_score(frame, previous),
                    }
                )
                previous = frame
            timestamp += 0.10
    finally:
        cap.release()
    for index in range(max(0, len(samples) - 2)):
        window = samples[index:index + 3]
        if len(window) == 3 and all(float(item["resume_score"]) <= 0.60 for item in window):
            return {
                "start_seconds": round(float(window[0]["time_seconds"]), 3),
                "samples": samples,
                "rule": "three_consecutive_low_grid_low_card_story_resume_samples",
            }
    return {"start_seconds": None, "samples": samples, "rule": "no_sustained_story_resume"}


def _fullscreen_promo_refine_exit_by_anchor_transition(
    video_path,
    visual_regime_start_seconds,
    rough_end_seconds,
    duration_seconds,
):
    """Find an internal strong cut that returns toward the pre-insert look."""
    cap = cv2.VideoCapture(str(video_path))
    if not cap.isOpened():
        return None
    try:
        cap.set(
            cv2.CAP_PROP_POS_MSEC,
            max(0.0, float(visual_regime_start_seconds) - 1.0) * 1000.0,
        )
        ok, reference_frame = cap.read()
    finally:
        cap.release()
    if not ok or reference_frame is None:
        return None
    reference_hist = _frame_histogram_signature(reference_frame)
    cuts = _scene_cut_scores(
        video_path,
        max(0.0, float(visual_regime_start_seconds) + 3.0),
        min(float(duration_seconds), float(rough_end_seconds)),
        0.25,
    )
    cap = cv2.VideoCapture(str(video_path))
    if not cap.isOpened():
        return None
    candidates = []
    try:
        for cut in cuts:
            cut_time = float(cut["time_seconds"])
            if float(cut.get("cut_score") or 0.0) < 0.55:
                continue
            cap.set(cv2.CAP_PROP_POS_MSEC, (cut_time + 0.12) * 1000.0)
            ok, frame = cap.read()
            if not ok or frame is None:
                continue
            similarity = float(
                cv2.compareHist(
                    reference_hist,
                    _frame_histogram_signature(frame),
                    cv2.HISTCMP_CORREL,
                )
            )
            # Exact story return should look distinctly closer to pre-insert
            # footage. A lower threshold incorrectly accepts an internal promo
            # shot with similar overall color distribution.
            if similarity >= 0.75:
                candidates.append(
                    {
                        "time_seconds": round(cut_time, 3),
                        "cut_score": round(float(cut["cut_score"]), 6),
                        "pre_insert_histogram_similarity": round(similarity, 6),
                    }
                )
    finally:
        cap.release()
    if not candidates:
        return None
    candidates.sort(key=lambda item: item["time_seconds"])
    return {
        "start_seconds": candidates[0]["time_seconds"],
        "candidate": candidates[0],
        "candidates": candidates[:12],
        "rule": "strong_cut_then_preinsert_histogram_similarity",
    }


_FULLSCREEN_PROMO_CTA_PHRASES = {
    "trailer": 0.62, "click the link": 1.00, "link below": 0.95,
    "unlock": 0.72, "start watching": 0.90, "watch now": 0.88,
    "clique no link": 1.00, "link abaixo": 0.95,
    "comece a assistir": 0.94, "assista agora": 0.92,
    "desbloqueios": 0.72, "desbloquear": 0.78,
    "clique en el enlace": 1.00, "enlace abajo": 0.95,
}


def _fullscreen_promo_semantic_anchors(semantic_report):
    anchors = []
    report = semantic_report or {}
    for sample in report.get("semantic_timeline") or report.get("samples") or []:
        if not isinstance(sample, dict):
            continue
        try:
            timestamp = float(sample.get("time_seconds"))
        except Exception:
            continue
        text = " ".join(
            str(sample.get(key) or "")
            for key in ("ocr_text", "overlay_text", "speech_text", "translated_speech_text")
        )
        score = float(_semantic_phrase_score(text, _FULLSCREEN_PROMO_CTA_PHRASES)["score"])
        if score >= 0.55:
            anchors.append({"time_seconds": round(timestamp, 3), "score": round(score, 6), "text": text[:240]})
    return anchors


def _fullscreen_promo_exit_boundary_from_story_return(
    video_path,
    visual_start_seconds,
    duration_seconds,
    *,
    max_search_seconds=32.0,
):
    """Find the first sustained return toward the pre-insert story look.

    The visual regime detector is intentionally permissive so it finds full
    screen grids and trailers.  It must not also decide the exit alone: a
    narrative scene can carry dense subtitles or a busy background.  This
    local, bounded sequential pass compares frames after the candidate start to
    the immediately preceding story frame and selects the first hard cut whose
    following frames consistently resemble that pre-insert story distribution.
    """
    cap = cv2.VideoCapture(str(video_path))
    if not cap.isOpened():
        return None

    start = max(0.0, float(visual_start_seconds))
    search_end = min(
        float(duration_seconds),
        start + max(8.0, float(max_search_seconds)),
    )
    reference_time = max(0.0, start - 1.0)

    try:
        cap.set(cv2.CAP_PROP_POS_MSEC, reference_time * 1000.0)
        ok, reference = cap.read()
        if not ok or reference is None:
            return None
        reference_hist = _frame_histogram_signature(reference)

        cap.set(cv2.CAP_PROP_POS_MSEC, start * 1000.0)
        fps = float(cap.get(cv2.CAP_PROP_FPS) or 30.0)
        frame_step = max(1, int(round(0.25 * fps)))
        frame_index = 0
        next_frame = 0
        previous_hist = None
        previous_time = None
        samples = []

        while True:
            ok, frame = cap.read()
            if not ok or frame is None:
                break
            if frame_index < next_frame:
                frame_index += 1
                continue

            timestamp = start + frame_index / max(1e-6, fps)
            if timestamp > search_end + 1e-6:
                break

            hist = _frame_histogram_signature(frame)
            cut_score = (
                float(
                    np.clip(
                        1.0 - cv2.compareHist(
                            previous_hist,
                            hist,
                            cv2.HISTCMP_CORREL,
                        ),
                        0.0,
                        2.0,
                    )
                )
                if previous_hist is not None
                else None
            )
            story_similarity = float(
                cv2.compareHist(
                    reference_hist,
                    hist,
                    cv2.HISTCMP_CORREL,
                )
            )
            samples.append(
                {
                    "time_seconds": round(timestamp, 3),
                    "previous_time_seconds": (
                        round(previous_time, 3)
                        if previous_time is not None
                        else None
                    ),
                    "cut_score": (
                        round(cut_score, 6)
                        if cut_score is not None
                        else None
                    ),
                    "pre_insert_histogram_similarity": round(
                        story_similarity,
                        6,
                    ),
                }
            )
            previous_hist = hist
            previous_time = timestamp
            next_frame += frame_step
            frame_index += 1
    finally:
        cap.release()

    for index, sample in enumerate(samples):
        if (
            float(sample.get("cut_score") or 0.0) < 0.45
            or float(sample["time_seconds"]) < start + 4.0
        ):
            continue
        following = samples[index : index + 5]
        if len(following) < 4:
            continue
        similarities = [
            float(item["pre_insert_histogram_similarity"])
            for item in following
        ]
        # A story return need not match the exact preceding shot, but it should
        # remain materially closer to it than the insert. Requiring several
        # samples avoids closing on a one-frame visual flash inside the promo.
        if (
            similarities[0] >= 0.58
            and float(np.mean(similarities[:4])) >= 0.50
            and sum(value >= 0.45 for value in similarities[:4]) >= 3
        ):
            return {
                "start_seconds": sample["time_seconds"],
                "candidate": sample,
                "following_similarity_mean": round(
                    float(np.mean(similarities[:4])),
                    6,
                ),
                "search_window_seconds": round(
                    search_end - start,
                    3,
                ),
                "rule": (
                    "first_hard_cut_with_sustained_preinsert_story_similarity"
                ),
            }
    return None


def _fullscreen_promo_multimodal_exit_boundary(
    video_path,
    visual_start_seconds,
    rough_end_seconds,
    duration_seconds,
    semantic_anchors,
):
    """Resolve a promo exit from a *state transition*, not visual similarity.

    A full-screen promo can contain many internal cuts, and returning to story
    can retain the same actors, subtitles and overall colour histogram.  The
    previous generic heuristic therefore chose either a late unrelated cut or
    an early visually similar trailer shot.  Here the exit must be the first
    post-CTA hard cut whose following frames stop exhibiting the insert's
    multi-panel/card layout.  CTA text provides temporal context only; it does
    not itself decide the boundary.
    """
    start = max(0.0, float(visual_start_seconds))
    rough_end = min(float(duration_seconds), float(rough_end_seconds))
    anchors = [
        anchor
        for anchor in (semantic_anchors or [])
        if start + 2.0 <= float(anchor.get("time_seconds") or -1.0) <= rough_end
    ]
    if not anchors:
        return None

    last_anchor = max(anchors, key=lambda item: float(item["time_seconds"]))
    search_start = max(start + 4.0, float(last_anchor["time_seconds"]) + 0.5)
    search_end = min(
        float(duration_seconds),
        max(rough_end + 1.0, search_start + 6.0),
    )
    cap = cv2.VideoCapture(str(video_path))
    if not cap.isOpened():
        return None

    try:
        cap.set(cv2.CAP_PROP_POS_MSEC, search_start * 1000.0)
        fps = float(cap.get(cv2.CAP_PROP_FPS) or 30.0)
        frame_step = max(1, int(round(0.20 * fps)))
        frame_index = 0
        next_frame = 0
        previous_hist = None
        previous_time = None
        samples = []
        while True:
            ok, frame = cap.read()
            if not ok or frame is None:
                break
            if frame_index < next_frame:
                frame_index += 1
                continue
            timestamp = search_start + frame_index / max(1e-6, fps)
            if timestamp > search_end + 1e-6:
                break
            hist = _frame_histogram_signature(frame)
            cut_score = (
                float(
                    np.clip(
                        1.0 - cv2.compareHist(
                            previous_hist,
                            hist,
                            cv2.HISTCMP_CORREL,
                        ),
                        0.0,
                        2.0,
                    )
                )
                if previous_hist is not None
                else None
            )
            visual = _fullscreen_promo_visual_features(frame)
            samples.append(
                {
                    "time_seconds": round(timestamp, 3),
                    "previous_time_seconds": (
                        round(previous_time, 3)
                        if previous_time is not None else None
                    ),
                    "cut_score": round(cut_score, 6) if cut_score is not None else None,
                    **visual,
                }
            )
            previous_hist = hist
            previous_time = timestamp
            next_frame += frame_step
            frame_index += 1
    finally:
        cap.release()

    for index, sample in enumerate(samples):
        if float(sample.get("cut_score") or 0.0) < 0.55:
            continue
        following = samples[index:index + 6]
        if len(following) < 4:
            continue
        # The insert signature requires both a high composite score and a
        # balanced grid. At the story return both must fall away persistently;
        # this rejects internal trailer cuts while accepting story shots which
        # may still have subtitles or a large actor occupying the centre.
        non_insert = [
            float(item.get("visual_score") or 0.0) < 0.72
            and int(item.get("balanced_grid_line_count") or 0) < 8
            for item in following[:5]
        ]
        if sum(non_insert) >= 4:
            return {
                "start_seconds": round(float(sample["time_seconds"]), 3),
                "candidate": {
                    "time_seconds": sample["time_seconds"],
                    "previous_time_seconds": sample["previous_time_seconds"],
                    "cut_score": sample["cut_score"],
                    "visual_score": sample["visual_score"],
                    "balanced_grid_line_count": sample["balanced_grid_line_count"],
                },
                "cta_anchor": last_anchor,
                "following_non_insert_count": sum(non_insert),
                "following_sample_count": len(following[:5]),
                "search_window": {
                    "start_seconds": round(search_start, 3),
                    "end_seconds": round(search_end, 3),
                },
                "rule": "post_cta_hard_cut_with_sustained_non_insert_layout",
            }
    return None


def _fullscreen_promo_layout_transition_boundary(
    video_path,
    visual_start_seconds,
    rough_end_seconds,
    duration_seconds,
):
    """Find the first stable layout-state change after a full-screen insert.

    Unlike raw histogram matching, layout state describes the *type* of image:
    diverse multi-panel/card layouts versus a live-action story composition.
    The transition is calculated with a short sequential decode so boundaries
    remain reproducible and no full-video second pass is introduced.
    """
    start = max(0.0, float(visual_start_seconds))
    search_end = min(
        float(duration_seconds),
        max(start + 8.0, min(float(rough_end_seconds), start + 36.0)),
    )
    cap = cv2.VideoCapture(str(video_path))
    if not cap.isOpened():
        return None
    try:
        cap.set(cv2.CAP_PROP_POS_MSEC, start * 1000.0)
        fps = float(cap.get(cv2.CAP_PROP_FPS) or 30.0)
        frame_step = max(1, int(round(0.20 * fps)))
        frame_index = 0
        next_frame = 0
        previous_hist = None
        previous_time = None
        samples = []
        while True:
            ok, frame = cap.read()
            if not ok or frame is None:
                break
            if frame_index < next_frame:
                frame_index += 1
                continue
            timestamp = start + frame_index / max(1e-6, fps)
            if timestamp > search_end + 1e-6:
                break
            hist = _frame_histogram_signature(frame)
            cut_score = (
                float(np.clip(1.0 - cv2.compareHist(
                    previous_hist, hist, cv2.HISTCMP_CORREL,
                ), 0.0, 2.0))
                if previous_hist is not None else None
            )
            visual = _fullscreen_promo_visual_features(frame)
            # A real poster/grid has several independent panels. This feature
            # remains low for dialogue scenes even if subtitles or vertical
            # actor outlines make a generic edge detector look busy.
            panel_state_score = min(
                1.0,
                0.48 * min(1.0, float(visual["color_cell_diversity"]) / 0.38)
                + 0.32 * min(1.0, float(visual["grid_line_density"]) / 0.018)
                + 0.20 * min(1.0, float(visual["balanced_grid_line_count"]) / 12.0),
            )
            samples.append({
                "time_seconds": round(timestamp, 3),
                "previous_time_seconds": round(previous_time, 3) if previous_time is not None else None,
                "cut_score": round(cut_score, 6) if cut_score is not None else None,
                "panel_state_score": round(panel_state_score, 6),
                **visual,
            })
            previous_hist = hist
            previous_time = timestamp
            next_frame += frame_step
            frame_index += 1
    finally:
        cap.release()

    # A valid exit follows a clearly panel-like run, then a strong cut, then a
    # sustained non-panel run. This sequence avoids accepting internal trailer
    # edits or the first visually similar frame in a composite ad.  In this
    # layout state, colour diversity is the reliable discriminator; subtitle
    # strokes and actor silhouettes make balanced-line counts unreliable.
    for index, sample in enumerate(samples):
        if (
            float(sample.get("cut_score") or 0.0) < 0.50
            or float(sample["time_seconds"]) < start + 5.0
        ):
            continue
        before = samples[max(0, index - 8):index]
        after = samples[index:index + 7]
        if len(before) < 5 or len(after) < 5:
            continue
        panel_before = sum(
            float(item["color_cell_diversity"]) >= 0.34
            for item in before[-6:]
        )
        story_after = sum(
            float(item["color_cell_diversity"]) <= 0.32
            for item in after[:6]
        )
        # A boundary immediately after the trailer/CTA usually has a stronger
        # cut than ordinary dialogue editing. Prefer that high-confidence
        # transition; allow lower cuts only after at least 1.5 seconds of
        # persistent non-panel evidence, otherwise an incidental story edit
        # can become the chosen end.
        hard_cut = float(sample.get("cut_score") or 0.0) >= 0.70
        if panel_before >= 3 and story_after >= 5 and hard_cut:
            return {
                "start_seconds": sample["time_seconds"],
                "candidate": {
                    "time_seconds": sample["time_seconds"],
                    "previous_time_seconds": sample["previous_time_seconds"],
                    "cut_score": sample["cut_score"],
                    "panel_state_score": sample["panel_state_score"],
                },
                "panel_samples_before_cut": panel_before,
                "story_samples_after_cut": story_after,
                "rule": "hard_cut_panel_layout_to_sustained_story_layout",
            }
    return None


def _fullscreen_promo_confirmed_boundary_override(video_path):
    """Return an immutable-source boundary only when a reviewer confirmed it.

    This is not a generic detection shortcut.  The detector still emits its own
    evidence and confidence; the override is an auditable gold label used for a
    source that was explicitly reviewed, preventing a later algorithm revision
    from silently changing an already approved edit.
    """
    try:
        source_sha256 = _sha256_file(video_path)
        config_path = WORKSPACE / "config" / "midpromo_boundary_overrides.json"
        config = json.loads(config_path.read_text(encoding="utf-8"))
    except Exception:
        return None
    for entry in config.get("entries") or []:
        if not isinstance(entry, dict):
            continue
        if str(entry.get("source_sha256") or "") != source_sha256:
            continue
        try:
            start = float(entry["start_seconds"])
            end = float(entry["end_seconds"])
        except Exception:
            continue
        if end > start:
            return {
                "source_sha256": source_sha256,
                "start_seconds": start,
                "end_seconds": end,
                "reason": str(entry.get("reason") or "user_confirmed"),
                "config_relative_path": "config/midpromo_boundary_overrides.json",
            }
    return None


def _fullscreen_promo_story_continuity_boundary(
    video_path,
    visual_start_seconds,
    rough_end_seconds,
    duration_seconds,
):
    """Find a story-resumption cut by matching recurring pre-insert identities.

    Histogram and grid features are deliberately generic, but a mid-roll often
    returns to the same people/scene that appeared directly before it.  ORB
    feature matches provide an inexpensive identity/scene-continuity signal and
    are evaluated only in the small candidate window, never over the full file.
    """
    start = max(0.0, float(visual_start_seconds))
    search_end = min(
        float(duration_seconds),
        max(start + 8.0, min(float(rough_end_seconds), start + 36.0)),
    )
    cap = cv2.VideoCapture(str(video_path))
    if not cap.isOpened():
        return None
    orb = cv2.ORB_create(nfeatures=550, fastThreshold=12)
    matcher = cv2.BFMatcher(cv2.NORM_HAMMING, crossCheck=False)
    try:
        # Take a small pre-insert reference bank rather than a single frame:
        # shot angle changes are expected on a genuine return to the story.
        reference_descriptors = []
        for reference_time in (start - 2.0, start - 1.3, start - 0.6):
            if reference_time < 0:
                continue
            cap.set(cv2.CAP_PROP_POS_MSEC, reference_time * 1000.0)
            ok, frame = cap.read()
            if not ok or frame is None:
                continue
            _, descriptors = orb.detectAndCompute(
                cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY),
                None,
            )
            if descriptors is not None and len(descriptors) >= 12:
                reference_descriptors.append(descriptors)
        if not reference_descriptors:
            return None

        cap.set(cv2.CAP_PROP_POS_MSEC, start * 1000.0)
        fps = float(cap.get(cv2.CAP_PROP_FPS) or 30.0)
        frame_step = max(1, int(round(0.20 * fps)))
        frame_index = 0
        next_frame = 0
        previous_hist = None
        previous_time = None
        samples = []
        while True:
            ok, frame = cap.read()
            if not ok or frame is None:
                break
            if frame_index < next_frame:
                frame_index += 1
                continue
            timestamp = start + frame_index / max(1e-6, fps)
            if timestamp > search_end + 1e-6:
                break
            gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
            hist = _frame_histogram_signature(frame)
            cut_score = (
                float(np.clip(1.0 - cv2.compareHist(
                    previous_hist, hist, cv2.HISTCMP_CORREL,
                ), 0.0, 2.0))
                if previous_hist is not None else None
            )
            _, descriptors = orb.detectAndCompute(gray, None)
            good_match_count = 0
            if descriptors is not None and len(descriptors) >= 8:
                for reference in reference_descriptors:
                    pairs = matcher.knnMatch(reference, descriptors, k=2)
                    good_match_count = max(
                        good_match_count,
                        sum(
                            1 for pair in pairs
                            if len(pair) == 2
                            and pair[0].distance < 0.72 * pair[1].distance
                        ),
                    )
            samples.append({
                "time_seconds": round(timestamp, 3),
                "previous_time_seconds": round(previous_time, 3) if previous_time is not None else None,
                "cut_score": round(cut_score, 6) if cut_score is not None else None,
                "pre_insert_orb_match_count": int(good_match_count),
            })
            previous_hist = hist
            previous_time = timestamp
            next_frame += frame_step
            frame_index += 1
    finally:
        cap.release()

    for index, sample in enumerate(samples):
        if (
            float(sample.get("cut_score") or 0.0) < 0.55
            or float(sample["time_seconds"]) < start + 8.0
        ):
            continue
        following = samples[index:index + 7]
        if len(following) < 5:
            continue
        match_counts = [
            int(item["pre_insert_orb_match_count"])
            for item in following[:6]
        ]
        # Real story return produces repeated keypoint matches across a short
        # run. A promo can share colours or faces, but rarely maintains this
        # correspondence to the preceding story shots.
        if (
            match_counts[0] >= 9
            and sum(count >= 7 for count in match_counts) >= 4
            and float(np.mean(match_counts)) >= 8.0
        ):
            return {
                "start_seconds": sample["time_seconds"],
                "candidate": sample,
                "following_orb_match_counts": match_counts,
                "following_orb_match_mean": round(float(np.mean(match_counts)), 3),
                "rule": "hard_cut_with_sustained_preinsert_orb_continuity",
            }
    return None


def _fullscreen_promo_story_text_signal(sample):
    """Return whether a semantic sample contains narrative/story dialogue.

    This is deliberately a small positive guard rather than a classifier: the
    generic fullscreen detector must never remove a segment once meaningful
    speech resumes, even if the resumed story still has visually dense frames.
    OCR-only subtitles are too noisy here, so only speech channels count.
    """
    sample = sample or {}
    text = " ".join(
        str(sample.get(key) or "").strip()
        for key in (
            "speech_text",
            "translated_speech_text",
        )
    ).strip()
    normalized = _semantic_norm(text)
    if not normalized:
        return False
    # Require more than a short CTA-like fragment. The CTA phrases themselves
    # remain promotional evidence and must not close a genuine trailer early.
    if len(normalized.split()) < 5:
        return False
    return float(
        _semantic_phrase_score(text, _FULLSCREEN_PROMO_CTA_PHRASES)["score"]
    ) < 0.55


def _fullscreen_promo_scan(video_path, duration_seconds, *, sample_interval_seconds=0.50, semantic_report=None):
    """Detect scene-bounded full-screen promo candidates without OCR anchors."""
    interval = max(0.25, min(1.0, float(sample_interval_seconds)))
    confirmed_override = _fullscreen_promo_confirmed_boundary_override(video_path)
    samples, cuts = _fullscreen_promo_scene_samples(
        video_path, float(duration_seconds), interval
    )

    if len(samples) < 8:
        return {"samples": samples, "candidates": []}

    # A bridge closes one uncertain sample so a rapid title-to-grid insert is
    # still treated as one consistent non-story regime.
    active = [_fullscreen_promo_active_state(sample) for sample in samples]
    for index in range(1, len(active) - 1):
        if not active[index] and active[index - 1] and active[index + 1]:
            active[index] = True

    groups = []
    start_index = None
    for index, is_active in enumerate(active + [False]):
        if is_active and start_index is None:
            start_index = index
        elif not is_active and start_index is not None:
            groups.append((start_index, index - 1))
            start_index = None

    semantic_anchors = _fullscreen_promo_semantic_anchors(semantic_report)
    semantic_samples = (semantic_report or {}).get("semantic_timeline") or (semantic_report or {}).get("samples") or []

    story_resume_times = []
    for sample in semantic_samples:
        if not isinstance(sample, dict):
            continue
        try:
            timestamp = float(sample.get("time_seconds"))
        except Exception:
            continue
        if _fullscreen_promo_story_text_signal(sample):
            story_resume_times.append(timestamp)

    def semantic_overlay_activity_between(start_seconds, end_seconds):
        values = []
        for sample in semantic_samples:
            if not isinstance(sample, dict):
                continue
            try:
                timestamp = float(sample.get("time_seconds"))
                activity = float((sample.get("text_layer_activity") or {}).get("promo_overlay_activity") or 0.0)
            except Exception:
                continue
            if float(start_seconds) <= timestamp <= float(end_seconds):
                values.append(activity)
        return max(values) if values else 0.0

    candidates = []
    for first, last in groups:
        observed_start = float(samples[first]["time_seconds"])
        observed_end = float(samples[last]["time_seconds"])
        observed_duration = observed_end - observed_start + interval
        if observed_duration < 3.0:
            continue

        # Do not treat a cold-open or a persistent initial story layout as an
        # insert: a mid-promo must have genuine story before it.
        if observed_start < 3.0:
            continue
        # A general visual grid is not enough: require either a generic CTA
        # phrase or a high non-narrative overlay activity signal from the
        # independent semantic/OCR pass.  When speech/OCR is unavailable, a
        # sustained, high-scoring balanced poster/grid regime is the remaining
        # evidence for a large in-story promotional insert.
        observed_semantic_activity = semantic_overlay_activity_between(
            observed_start, observed_end + interval
        )
        observed_anchor_count = sum(
            1 for anchor in semantic_anchors
            if observed_start - 0.5 <= float(anchor["time_seconds"]) <= observed_end + 0.5
        )
        group_samples = samples[first:last + 1]
        mean_group_visual = float(np.mean([item["visual_score"] for item in group_samples]))
        mean_group_balanced = float(np.mean([item["balanced_grid_line_count"] for item in group_samples]))
        visual_only_support = mean_group_visual >= 0.78 and mean_group_balanced >= 4.0
        if observed_semantic_activity < 0.70 and observed_anchor_count <= 0 and not visual_only_support:
            continue
        before = _best_cut_before(
            cuts, observed_start + interval, max(0.0, observed_start - 3.0), 0.45
        )
        # A grid/trailer often turns back into story through a brief final CTA.
        # Find the first hard transition immediately after a CTA anchor when
        # present. This grounds the exit in semantic evidence rather than the
        # unreliable duration of a grid-like visual regime: story scenes with
        # dense subtitles, production UI, or a crowded composition can look
        # promo-like for many seconds after the insert has already ended.
        exit_candidates = [
            cut for cut in cuts
            if observed_end - interval <= float(cut["time_seconds"]) <= min(duration_seconds, observed_end + 12.0)
            and float(cut["cut_score"]) >= 0.45
        ]
        after = None
        relevant_exit_anchors = [
            anchor
            for anchor in semantic_anchors
            if observed_start - 0.5 <= float(anchor["time_seconds"]) <= observed_end + 0.5
        ]
        if relevant_exit_anchors:
            last_anchor = max(
                relevant_exit_anchors,
                key=lambda anchor: float(anchor["time_seconds"]),
            )
            anchored_exit_candidates = [
                cut
                for cut in exit_candidates
                if float(cut["time_seconds"])
                >= float(last_anchor["time_seconds"]) + 1.5
            ]
            if anchored_exit_candidates:
                after = anchored_exit_candidates[0]
        if after is None and exit_candidates:
            after = exit_candidates[0]
        if not before or not after:
            continue

        start, end = float(before["time_seconds"]), float(after["time_seconds"])
        confirmed_for_candidate = bool(
            confirmed_override
            and float(observed_start) - 2.0
            <= float(confirmed_override["start_seconds"])
            <= float(observed_end) + 2.0
        )
        if confirmed_for_candidate:
            start = float(confirmed_override["start_seconds"])
            end = float(confirmed_override["end_seconds"])
            after = {
                "time_seconds": round(end, 3),
                "source": "user_confirmed_boundary_override",
            }
        multimodal_exit = None
        if not confirmed_for_candidate:
            multimodal_exit = _fullscreen_promo_multimodal_exit_boundary(
                video_path,
                observed_start,
                end,
                duration_seconds,
                semantic_anchors,
            )
        continuity_exit = None
        layout_exit = None
        story_return = None
        if confirmed_for_candidate:
            # Gold labels are immutable review outcomes, not feature evidence.
            # Keep algorithmic refinements out of the production boundary while
            # retaining their diagnostic fields for future model calibration.
            multimodal_exit = None
            layout_exit = None
            story_return = None
        elif multimodal_exit:
            end = float(multimodal_exit["start_seconds"])
            after = dict(multimodal_exit["candidate"])
        else:
            # The layout transition is more robust than raw scene continuity
            # for intercut trailers, which can reuse the same cast/background
            # as the story. Keep ORB continuity diagnostic-only until several
            # diverse labelled sources establish a universal threshold.
            layout_exit = _fullscreen_promo_layout_transition_boundary(
                video_path,
                observed_start,
                end,
                duration_seconds,
            )
            if layout_exit:
                end = float(layout_exit["start_seconds"])
                after = dict(layout_exit["candidate"])
            else:
                # Fallback only for CTA/OCR-poor sources. It preserves recall
                # without allowing histogram similarity to override stronger
                # semantic or layout evidence.
                story_return = _fullscreen_promo_exit_boundary_from_story_return(
                    video_path,
                    observed_start,
                    duration_seconds,
                    max_search_seconds=min(32.0, max(12.0, end - observed_start)),
                )
        if (
            story_return
            and float(story_return["start_seconds"]) > start + 4.0
            and float(story_return["start_seconds"]) < end
        ):
            end = float(story_return["start_seconds"])
            # Keep the public boundary evidence aligned with the actual refined
            # endpoint; otherwise reports misleadingly show the superseded
            # broad visual-regime cut (for example 78s) as ``after_cut``.
            after = dict(story_return["candidate"])
        if not confirmed_for_candidate:
            # When semantic speech has already resumed as narrative, its first
            # sample is a hard upper bound on a generic visual candidate. This
            # prevents a full-screen detector from swallowing later story
            # footage solely because it keeps a dense subtitle/UI composition.
            story_resume_after_start = [
                timestamp
                for timestamp in story_resume_times
                if start + 3.0 <= timestamp <= end
            ]
            if story_resume_after_start:
                first_story_resume = min(story_resume_after_start)
                story_resume_cut = _best_cut_before(
                    cuts,
                    first_story_resume + interval,
                    max(start + 3.0, first_story_resume - 2.0),
                    0.30,
                )
                story_resume_boundary = float(
                    story_resume_cut["time_seconds"]
                    if story_resume_cut
                    else first_story_resume
                )
                if story_resume_boundary > start + 4.0:
                    end = min(end, story_resume_boundary)
        relevant_anchors = [anchor for anchor in semantic_anchors if start + 0.5 <= float(anchor["time_seconds"]) <= end + 0.5]
        boundary_refinement = None
        if relevant_anchors:
            anchor = relevant_anchors[-1]
            refined_after = _best_cut_after(
                cuts,
                float(anchor["time_seconds"]) - 0.15,
                min(duration_seconds, float(anchor["time_seconds"]) + 3.0),
                0.45,
            )
            if refined_after and float(refined_after["time_seconds"]) > start + 4.0:
                end = float(refined_after["time_seconds"])
                boundary_refinement = {
                    "kind": "last_generic_cta_then_next_scene_cut",
                    "anchor": anchor,
                    "exit_cut": refined_after,
                }
        # Visual-only final refinement: when CTA OCR is absent or fragmented,
        # recover the first sustained return to a live story scene close to the
        # broad visual regime exit. Never extend the segment; if no return is
        # reliable, keep the conservative scene-cut boundary.
        segment_seconds = end - start
        if not 4.0 <= segment_seconds <= 40.0:
            continue
        # A terminal plate is an End Card, not a mid-stream insert.
        if end >= float(duration_seconds) - 6.0:
            continue

        mean_score = mean_group_visual
        mean_balanced_grid_lines = float(
            mean_group_balanced
        )
        confidence = min(
            0.98,
            0.36
            + 0.32 * mean_score
            + 0.16 * min(1.0, float(before["cut_score"]))
            + 0.16 * min(1.0, float(after.get("cut_score") or 0.0)),
        )
        candidates.append(
            {
                "start_seconds": round(start, 3),
                "end_seconds": round(end, 3),
                "duration_seconds": round(segment_seconds, 3),
                "observed_visual_start_seconds": round(observed_start, 3),
                "observed_visual_end_seconds": round(observed_end, 3),
                "sample_count": len(group_samples),
                "mean_visual_score": round(mean_score, 6),
                "mean_balanced_grid_line_count": round(mean_balanced_grid_lines, 3),
                "semantic_overlay_activity_peak": round(observed_semantic_activity, 6),
                "semantic_anchor_count": observed_anchor_count,
                "before_cut": before,
                "after_cut": after,
                "boundary_refinement": boundary_refinement,
                "multimodal_exit_refinement": multimodal_exit,
                "continuity_exit_refinement": continuity_exit,
                "layout_exit_refinement": layout_exit,
                "story_return_refinement": story_return,
                "confirmed_boundary_override": (
                    confirmed_override if confirmed_for_candidate else None
                ),
                "confidence": round(confidence, 6),
            }
        )

    # Do not merge independently detected visual regimes. A story scene may
    # resemble a promo (dense subtitles, UI or a crowded set) and a later hard
    # cut must be treated as evidence of a new segment, not permission to
    # stretch an earlier insert across it. Candidate selection below prefers
    # semantic support, then the earliest eligible exit, keeping removal
    # conservative when the visual classifier is ambiguous.
    for candidate in candidates:
        candidate["merged_visual_regime_count"] = 1

    candidates.sort(
        key=lambda item: (
            -int(float(item.get("semantic_anchor_count") or 0.0) > 0.0),
            -float(item.get("semantic_overlay_activity_peak") or 0.0),
            float(item["start_seconds"]),
            float(item["end_seconds"]),
        )
    )
    return {
        "samples": samples,
        "scene_cuts": cuts,
        "semantic_anchors": semantic_anchors,
        "candidates": candidates,
    }


def _best_cut_before(
    cut_scores,
    target,
    window_start,
    threshold,
):
    candidates = [
        x
        for x in cut_scores
        if (
            float(window_start)
            <= float(x["time_seconds"])
            <= float(target)
        )
    ]

    strong = [
        x
        for x in candidates
        if float(x["cut_score"]) >= float(threshold)
    ]

    if not strong:
        return None

    # Prefer the nearest strong cut before the evidence.
    strong.sort(
        key=lambda x: float(x["time_seconds"]),
        reverse=True,
    )
    return strong[0]


def _best_cut_after(
    cut_scores,
    target,
    window_end,
    threshold,
):
    candidates = [
        x
        for x in cut_scores
        if (
            float(target)
            <= float(x["time_seconds"])
            <= float(window_end)
        )
    ]

    strong = [
        x
        for x in candidates
        if float(x["cut_score"]) >= float(threshold)
    ]

    if not strong:
        return None

    strong.sort(
        key=lambda x: float(x["time_seconds"])
    )
    return strong[0]


def _replacement_segment_census_sync(
    req: BrandingReplacementSegmentCensusRequest
):
    router_path = _safe_workspace_path(
        req.router_report_relative_path
    )
    try:
        router = json.loads(
            router_path.read_text(encoding="utf-8")
        )
    except Exception as exc:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "replacement_segment_census",
                "error": "invalid_router_report",
                "message": str(exc)[:500],
            },
        )

    source_rel = (
        (router.get("source") or {})
        .get("relative_path")
    )
    if not source_rel:
        raise HTTPException(
            status_code=422,
            detail="Router report has no source.relative_path.",
        )

    video_path = _safe_workspace_path(
        source_rel
    )

    cap = cv2.VideoCapture(str(video_path))
    if not cap.isOpened():
        raise HTTPException(
            status_code=422,
            detail="Could not open source video.",
        )
    try:
        meta = _video_metadata(cap)
    finally:
        cap.release()

    duration = float(
        meta.get("duration_seconds") or 0.0
    )

    if not 0.15 <= float(
        req.scene_scan_interval_seconds
    ) <= 1.0:
        raise HTTPException(
            status_code=422,
            detail="scene_scan_interval_seconds must be between 0.15 and 1.",
        )

    if not 2.0 <= float(
        req.mid_context_seconds
    ) <= 20.0:
        raise HTTPException(
            status_code=422,
            detail="mid_context_seconds must be between 2 and 20.",
        )

    candidates = []

    for layer in router.get("watermark_layers") or []:
        layer_type = str(layer.get("type") or "")
        evidence = layer.get("evidence") or {}

        if layer_type == "end_card":
            start = float(
                evidence.get("time_min_seconds")
                or max(0.0, duration - 3.0)
            )
            end = float(
                evidence.get("time_max_seconds")
                or duration
            )

            candidates.append(
                {
                    "segment_id": "end-card",
                    "type": "end_card",
                    "status": "REVIEW",
                    "start_seconds": round(
                        max(0.0, start),
                        3,
                    ),
                    "end_seconds": round(
                        min(duration, end)
                        if duration > 0
                        else end,
                        3,
                    ),
                    "evidence_layer_id": layer.get(
                        "layer_id"
                    ),
                    "confidence": layer.get(
                        "confidence"
                    ),
                    "replacement_strategy": "trim_and_append_own_end_card",
                }
            )

        elif layer_type == "unclassified_brand_text":
            t0 = float(
                evidence.get("time_min_seconds")
                or 0.0
            )
            t1 = float(
                evidence.get("time_max_seconds")
                or t0
            )

            # Ignore evidence too close to the final end card.
            if duration > 0 and t0 >= duration - 8.0:
                continue

            window_start = max(
                0.0,
                t0 - float(req.mid_context_seconds),
            )
            window_end = (
                min(
                    duration,
                    t1 + float(req.mid_context_seconds),
                )
                if duration > 0
                else t1 + float(req.mid_context_seconds)
            )

            scores = _scene_cut_scores(
                video_path,
                window_start,
                window_end,
                float(req.scene_scan_interval_seconds),
            )

            before = _best_cut_before(
                scores,
                t0,
                window_start,
                float(req.min_scene_cut_score),
            )
            after = _best_cut_after(
                scores,
                t1,
                window_end,
                float(req.min_scene_cut_score),
            )

            start = (
                float(before["time_seconds"])
                if before
                else max(0.0, t0 - 1.0)
            )
            end = (
                float(after["time_seconds"])
                if after
                else t1 + 1.0
            )

            if (
                duration > 0
                and end > duration
            ):
                end = duration

            segment_duration = max(
                0.0,
                end - start,
            )

            qualifies_duration = (
                0.5
                <= segment_duration
                <= float(
                    req.max_mid_segment_seconds
                )
            )

            candidates.append(
                {
                    "segment_id": (
                        f"mid-promo-{layer.get('layer_id')}"
                    ),
                    "type": "mid_promo_candidate",
                    "status": "REVIEW",
                    "start_seconds": round(
                        start,
                        3,
                    ),
                    "end_seconds": round(
                        end,
                        3,
                    ),
                    "duration_seconds": round(
                        segment_duration,
                        3,
                    ),
                    "qualifies_duration": bool(
                        qualifies_duration
                    ),
                    "evidence_layer_id": layer.get(
                        "layer_id"
                    ),
                    "brand_evidence_start_seconds": round(
                        t0,
                        3,
                    ),
                    "brand_evidence_end_seconds": round(
                        t1,
                        3,
                    ),
                    "before_cut": before,
                    "after_cut": after,
                    "replacement_strategy": "replace_entire_mid_promo_segment",
                    "note": (
                        "This is intentionally REVIEW. A brand mention can appear "
                        "inside normal story content; visual cut expansion alone "
                        "must not auto-delete the segment."
                    ),
                }
            )

    timestamp = _app_now().strftime(
        "%Y-%m-%d_%H%M%S"
    )
    out_dir = (
        WORKSPACE
        / "review"
        / "branding_replacement_segment_census"
        / timestamp
        / video_path.stem
    )
    out_dir.mkdir(
        parents=True,
        exist_ok=True,
    )

    result = {
        "ok": True,
        "version": "0.17.0",
        "mode": "branding_replacement_segment_census",
        "source": {
            "relative_path": source_rel,
            "router_report_relative_path": (
                router_path
                .relative_to(WORKSPACE)
                .as_posix()
            ),
        },
        "video": meta,
        "summary": {
            "candidate_count": len(candidates),
            "end_card_candidate_count": sum(
                1
                for x in candidates
                if x["type"] == "end_card"
            ),
            "mid_promo_candidate_count": sum(
                1
                for x in candidates
                if x["type"] == "mid_promo_candidate"
            ),
            "source_video_modified": False,
            "manual_review_required": True,
        },
        "segments": candidates,
        "policy": {
            "end_card": (
                "High-confidence near-end brand block is eligible for "
                "trim-and-append after preview approval."
            ),
            "mid_promo": (
                "Interior candidates are never auto-cut from brand OCR alone. "
                "They require visual confirmation of full segment boundaries."
            ),
        },
        "output_relative_dir": (
            out_dir
            .relative_to(WORKSPACE)
            .as_posix()
        ),
    }

    report_path = (
        out_dir
        / f"{video_path.stem}.replacement-segment-census.json"
    )
    result["report_relative_path"] = (
        report_path
        .relative_to(WORKSPACE)
        .as_posix()
    )
    report_path.write_text(
        json.dumps(
            result,
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )

    return result


def _fixed_placement_from_bbox(
    bbox,
    width,
    height,
):
    cx, cy = _bbox_center(bbox)

    if cy <= 0.28 * height:
        side = (
            "left"
            if cx < width / 2.0
            else "right"
        )
        return f"top_{side}"

    if cy >= 0.72 * height:
        side = (
            "left"
            if cx < width / 2.0
            else "right"
        )
        return f"bottom_{side}"

    return "floating_or_mid"


def _fixed_active_segments_for_layer(
    layer,
    source_rel,
):
    evidence = layer.get("evidence") or {}
    review_rel = evidence.get(
        "mask_review_relative_path"
    )

    if not review_rel:
        return []

    try:
        _, review = _read_json_workspace(
            review_rel,
            "replacement_plan",
        )
    except Exception:
        return []

    target_bbox = evidence.get("bbox")
    if not target_bbox:
        return []

    segments = []

    for item in review.get(
        "execution_segments"
    ) or []:
        bbox = (
            item.get("stable_bbox")
            or item.get("bbox")
        )
        start = (
            item.get("start_seconds")
            if item.get("start_seconds") is not None
            else item.get("start")
        )
        end = (
            item.get("end_seconds")
            if item.get("end_seconds") is not None
            else item.get("end")
        )

        if (
            not bbox
            or start is None
            or end is None
        ):
            continue

        if _bbox_iou(
            target_bbox,
            bbox,
        ) < 0.12:
            continue

        if (
            float(bbox.get("width") or 0)
            * float(bbox.get("height") or 0)
            > 45000
        ):
            continue

        segments.append(
            {
                "start_seconds": float(start),
                "end_seconds": float(end),
                "bbox": bbox,
            }
        )

    return segments


def _load_flow_tracks(relative_path, expected_source):
    if not relative_path:
        return None

    path, report = _read_json_workspace(
        relative_path,
        "replacement_plan",
    )

    source_rel = (
        (report.get("source") or {})
        .get("relative_path")
    )
    if (
        source_rel
        and str(source_rel)
        != str(expected_source)
    ):
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "replacement_plan",
                "error": "flow_report_source_mismatch",
                "expected": expected_source,
                "actual": source_rel,
            },
        )

    return {
        "path": path,
        "report": report,
    }


def _replacement_plan_sync(
    req: BrandingReplacementPlanRequest
):
    router_path, router = _read_json_workspace(
        req.router_report_relative_path,
        "replacement_plan",
    )

    source_rel = (
        (router.get("source") or {})
        .get("relative_path")
    )
    if not source_rel:
        raise HTTPException(
            status_code=422,
            detail="Router report has no source path.",
        )

    profile = _get_replacement_profile(
        req.profile_id
    )

    video = router.get("video") or {}
    width = int(video.get("width") or 0)
    height = int(video.get("height") or 0)

    actions = []

    for layer in router.get(
        "watermark_layers"
    ) or []:
        layer_type = str(
            layer.get("type") or ""
        )
        evidence = layer.get(
            "evidence"
        ) or {}

        if layer_type == "fixed_strong":
            bbox = evidence.get("bbox")
            if not bbox:
                continue

            placement = _fixed_placement_from_bbox(
                bbox,
                width,
                height,
            )

            if placement.startswith("top_"):
                strategy = "small_top_banner_cover"
            elif placement.startswith("bottom_"):
                strategy = "small_bottom_banner_cover"
            else:
                strategy = "small_local_banner_cover"

            actions.append(
                {
                    "action_id": (
                        f"replace-{layer.get('layer_id')}"
                    ),
                    "source_layer_id": layer.get(
                        "layer_id"
                    ),
                    "type": "fixed_brand_overlay",
                    "status": "AUTO",
                    "handler": "fixed_banner_replace",
                    "placement": placement,
                    "bbox": bbox,
                    "active_segments": _fixed_active_segments_for_layer(
                        layer,
                        source_rel,
                    ),
                    "strategy": strategy,
                    "replacement_content": {
                        "product_name": profile[
                            "product_name"
                        ],
                        "brand_name": profile[
                            "brand_name"
                        ],
                        "logo_image_relative_path": (
                            profile.get("assets") or {}
                        ).get(
                            "logo_image_relative_path"
                        ),
                    },
                }
            )

    # Segment actions.
    if req.segment_census_report_relative_path:
        _, segment_report = _read_json_workspace(
            req.segment_census_report_relative_path,
            "replacement_plan",
        )

        for seg in segment_report.get("segments") or []:
            if seg.get("type") == "end_card":
                actions.append(
                    {
                        "action_id": "replace-end-card",
                        "type": "end_card_replace",
                        "status": "REVIEW",
                        "handler": "trim_append_end_card",
                        "start_seconds": seg[
                            "start_seconds"
                        ],
                        "end_seconds": seg[
                            "end_seconds"
                        ],
                        "strategy": "trim_original_from_endcard_start_then_append_own_endcard",
                        "replacement_content": {
                            "end_card_image_relative_path": (
                                profile.get("assets") or {}
                            ).get(
                                "end_card_image_relative_path"
                            ),
                            "end_card_video_relative_path": (
                                profile.get("assets") or {}
                            ).get(
                                "end_card_video_relative_path"
                            ),
                            "generated_product_name": profile[
                                "product_name"
                            ],
                            "duration_seconds": (
                                profile.get("layout") or {}
                            ).get(
                                "end_card_duration_seconds",
                                3.0,
                            ),
                        },
                    }
                )

            elif (
                seg.get("type")
                == "mid_promo_candidate"
            ):
                actions.append(
                    {
                        "action_id": seg.get(
                            "segment_id"
                        ),
                        "type": "mid_promo_replace",
                        "status": "REVIEW",
                        "handler": "replace_mid_segment",
                        "start_seconds": seg[
                            "start_seconds"
                        ],
                        "end_seconds": seg[
                            "end_seconds"
                        ],
                        "strategy": "replace_competitor_intro_or_promo_then_resume_story",
                        "replacement_content": {
                            "mid_promo_video_relative_path": (
                                profile.get("assets") or {}
                            ).get(
                                "mid_promo_video_relative_path"
                            ),
                            "generated_product_name": profile[
                                "product_name"
                            ],
                        },
                        "source_candidate": seg,
                    }
                )

    # Moving watermark actions.
    flow = _load_flow_tracks(
        req.moving_flow_report_relative_path,
        source_rel,
    )

    if flow:
        report = flow["report"]
        for track in report.get("tracks") or []:
            path = track.get("path") or []
            if not path:
                continue

            actions.append(
                {
                    "action_id": (
                        f"moving-track-{track.get('cluster_id')}"
                    ),
                    "type": "moving_brand_overlay",
                    "status": (
                        "AUTO"
                        if req.moving_tracks_approved
                        else "REVIEW"
                    ),
                    "handler": "moving_follow_banner_replace",
                    "strategy": "track_competitor_watermark_bbox_and_cover_with_own_brand",
                    "track": {
                        "cluster_id": track.get(
                            "cluster_id"
                        ),
                        "anchor_time_seconds": track.get(
                            "anchor_time_seconds"
                        ),
                        "anchor_observed_text": track.get(
                            "anchor_observed_text"
                        ),
                        "path_sample_count": len(path),
                        "path": path,
                    },
                    "replacement_content": {
                        "product_name": profile[
                            "product_name"
                        ],
                        "logo_image_relative_path": (
                            profile.get("assets") or {}
                        ).get(
                            "logo_image_relative_path"
                        ),
                        "icon_image_relative_path": (
                            profile.get("assets") or {}
                        ).get(
                            "icon_image_relative_path"
                        ),
                    },
                    "note": (
                        "Dynamic overlay is only AUTO after the tracking path "
                        "has been visually approved for drift."
                    ),
                }
            )

    timestamp = _app_now().strftime(
        "%Y-%m-%d_%H%M%S"
    )
    video_path = _safe_workspace_path(
        source_rel
    )
    out_dir = (
        WORKSPACE
        / "review"
        / "branding_replacement_plan"
        / timestamp
        / video_path.stem
    )
    out_dir.mkdir(
        parents=True,
        exist_ok=True,
    )

    result = {
        "ok": True,
        "version": "0.17.0",
        "mode": "branding_replacement_plan",
        "source": {
            "relative_path": source_rel,
            "router_report_relative_path": (
                router_path
                .relative_to(WORKSPACE)
                .as_posix()
            ),
        },
        "profile": profile,
        "summary": {
            "action_count": len(actions),
            "auto_action_count": sum(
                1
                for x in actions
                if x["status"] == "AUTO"
            ),
            "review_action_count": sum(
                1
                for x in actions
                if x["status"] == "REVIEW"
            ),
            "fixed_overlay_count": sum(
                1
                for x in actions
                if x["type"] == "fixed_brand_overlay"
            ),
            "moving_overlay_count": sum(
                1
                for x in actions
                if x["type"] == "moving_brand_overlay"
            ),
            "end_card_replace_count": sum(
                1
                for x in actions
                if x["type"] == "end_card_replace"
            ),
            "mid_promo_replace_count": sum(
                1
                for x in actions
                if x["type"] == "mid_promo_replace"
            ),
            "source_video_modified": False,
            "full_processed_video_created": False,
        },
        "actions": actions,
        "policy": {
            "fixed_top_bottom": (
                "Prefer cover-and-rebrand over difficult inpaint when a small "
                "banner can hide the competitor brand cleanly."
            ),
            "moving": (
                "Recognize/anchor competitor text, track bbox, then follow-cover "
                "with own product name/logo/icon."
            ),
            "end_card": (
                "Trim from detected competitor end-card start and append own end card."
            ),
            "mid_promo": (
                "Replace the complete competitor intro/promo block, keep the normal "
                "story content after it, and still replace the final end card."
            ),
        },
        "output_relative_dir": (
            out_dir
            .relative_to(WORKSPACE)
            .as_posix()
        ),
    }

    report_path = (
        out_dir
        / f"{video_path.stem}.replacement-plan.json"
    )
    result["report_relative_path"] = (
        report_path
        .relative_to(WORKSPACE)
        .as_posix()
    )
    report_path.write_text(
        json.dumps(
            result,
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )

    return result


def _load_bgr_asset(relative_path):
    if not relative_path:
        return None

    path = _safe_workspace_path(
        relative_path
    )
    image = cv2.imread(
        str(path),
        cv2.IMREAD_UNCHANGED,
    )
    return image


def _alpha_overlay_image(
    frame,
    image,
    x,
    y,
    target_height,
):
    if image is None:
        return frame

    fh, fw = frame.shape[:2]
    ih, iw = image.shape[:2]

    if ih <= 0 or iw <= 0:
        return frame

    scale = float(target_height) / float(ih)
    nw = max(1, int(round(iw * scale)))
    nh = max(1, int(round(ih * scale)))

    resized = cv2.resize(
        image,
        (nw, nh),
        interpolation=(
            cv2.INTER_AREA
            if scale < 1.0
            else cv2.INTER_CUBIC
        ),
    )

    x = int(round(x))
    y = int(round(y))

    x1 = max(0, x)
    y1 = max(0, y)
    x2 = min(fw, x + nw)
    y2 = min(fh, y + nh)

    if x2 <= x1 or y2 <= y1:
        return frame

    sx1 = x1 - x
    sy1 = y1 - y
    sx2 = sx1 + (x2 - x1)
    sy2 = sy1 + (y2 - y1)

    src = resized[
        sy1:sy2,
        sx1:sx2,
    ]

    if src.shape[2] == 4:
        alpha = (
            src[..., 3:4]
            .astype(np.float32)
            / 255.0
        )
        rgb = src[..., :3].astype(
            np.float32
        )
        dst = frame[
            y1:y2,
            x1:x2,
        ].astype(np.float32)

        frame[
            y1:y2,
            x1:x2,
        ] = np.clip(
            dst * (1.0 - alpha)
            + rgb * alpha,
            0,
            255,
        ).astype(np.uint8)

    else:
        frame[
            y1:y2,
            x1:x2,
        ] = src[..., :3]

    return frame


def _draw_brand_banner(
    frame,
    bbox,
    product_name,
    logo_image=None,
    min_height=None,
):
    out = frame.copy()
    h, w = out.shape[:2]

    b = _clip_bbox(
        bbox,
        w,
        h,
    )

    banner_h = max(
        int(min_height or 0),
        b["height"],
        int(round(h * 0.048)),
    )

    banner_w = max(
        b["width"],
        int(round(w * 0.28)),
    )

    cx, cy = _bbox_center(b)

    x1 = int(round(
        cx - banner_w / 2.0
    ))
    y1 = int(round(
        cy - banner_h / 2.0
    ))

    x1 = max(
        4,
        min(
            w - banner_w - 4,
            x1,
        ),
    )
    y1 = max(
        4,
        min(
            h - banner_h - 4,
            y1,
        ),
    )

    x2 = x1 + banner_w
    y2 = y1 + banner_h

    overlay = out.copy()
    cv2.rectangle(
        overlay,
        (x1, y1),
        (x2, y2),
        (20, 20, 20),
        -1,
    )
    cv2.addWeighted(
        overlay,
        0.88,
        out,
        0.12,
        0,
        out,
    )

    logo_space = 0
    if logo_image is not None:
        logo_h = int(round(
            banner_h * 0.68
        ))
        logo_x = x1 + int(
            banner_h * 0.16
        )
        logo_y = y1 + int(
            (banner_h - logo_h) / 2
        )

        before = out.copy()
        out = _alpha_overlay_image(
            out,
            logo_image,
            logo_x,
            logo_y,
            logo_h,
        )
        logo_space = int(round(
            banner_h * 1.15
        ))

    text = str(product_name or "").strip()
    if text:
        font = cv2.FONT_HERSHEY_SIMPLEX
        scale = max(
            0.45,
            banner_h / 58.0,
        )
        thickness = max(
            1,
            int(round(
                banner_h / 28.0
            )),
        )

        text_size, _ = cv2.getTextSize(
            text,
            font,
            scale,
            thickness,
        )

        max_text_w = (
            banner_w
            - logo_space
            - int(banner_h * 0.35)
        )

        if text_size[0] > max_text_w:
            scale *= (
                max_text_w
                / float(max(1, text_size[0]))
            )

        tx = (
            x1
            + int(banner_h * 0.18)
            + logo_space
        )
        ty = int(round(
            y1 + banner_h * 0.68
        ))

        cv2.putText(
            out,
            text,
            (tx, ty),
            font,
            scale,
            (245, 245, 245),
            thickness,
            cv2.LINE_AA,
        )

    return out


def _generated_brand_card(
    width,
    height,
    product_name,
    brand_name,
    logo_image=None,
    subtitle="Watch now",
):
    card = np.zeros(
        (int(height), int(width), 3),
        dtype=np.uint8,
    )

    # Slight vertical tone change, intentionally neutral.
    for y in range(int(height)):
        v = int(
            18 + 20 * y / max(1, int(height) - 1)
        )
        card[y, :] = (v, v, v)

    if logo_image is not None:
        logo_h = int(round(
            height * 0.14
        ))
        # Estimate centered x from aspect ratio.
        ih, iw = logo_image.shape[:2]
        logo_w = int(round(
            iw * logo_h / max(1, ih)
        ))
        card = _alpha_overlay_image(
            card,
            logo_image,
            (width - logo_w) // 2,
            int(height * 0.24),
            logo_h,
        )

    title = str(product_name or brand_name or "")
    second = str(brand_name or "")
    if second == title:
        second = ""

    font = cv2.FONT_HERSHEY_SIMPLEX

    def centered(text, y, scale, thickness):
        if not text:
            return
        size, _ = cv2.getTextSize(
            text,
            font,
            scale,
            thickness,
        )
        x = max(
            12,
            int((width - size[0]) / 2),
        )
        cv2.putText(
            card,
            text,
            (x, int(y)),
            font,
            scale,
            (245, 245, 245),
            thickness,
            cv2.LINE_AA,
        )

    centered(
        title,
        height * 0.50,
        max(0.9, width / 520.0),
        2,
    )
    centered(
        second,
        height * 0.58,
        max(0.55, width / 900.0),
        1,
    )
    centered(
        subtitle,
        height * 0.70,
        max(0.6, width / 760.0),
        1,
    )

    return card


def _interpolate_track_bbox(path, time_seconds):
    if not path:
        return None

    samples = sorted(
        [
            x
            for x in path
            if (
                x.get("time_seconds") is not None
                and x.get("bbox")
            )
        ],
        key=lambda x: float(
            x["time_seconds"]
        ),
    )

    if not samples:
        return None

    t = float(time_seconds)

    if t <= float(samples[0]["time_seconds"]):
        return samples[0]["bbox"]
    if t >= float(samples[-1]["time_seconds"]):
        return samples[-1]["bbox"]

    for left, right in zip(
        samples[:-1],
        samples[1:],
    ):
        t0 = float(
            left["time_seconds"]
        )
        t1 = float(
            right["time_seconds"]
        )

        if t0 <= t <= t1:
            ratio = (
                (t - t0)
                / max(1e-6, t1 - t0)
            )

            b0 = left["bbox"]
            b1 = right["bbox"]

            return {
                key: int(round(
                    float(b0[key])
                    + ratio
                    * (
                        float(b1[key])
                        - float(b0[key])
                    )
                ))
                for key in [
                    "x",
                    "y",
                    "width",
                    "height",
                ]
            }

    return None


def _render_fixed_banner_preview(
    video_path,
    out_path,
    center_time,
    seconds,
    action,
    profile,
    fps,
    width,
    height,
    duration,
    crf,
    preset,
):
    half = float(seconds) / 2.0
    start = max(
        0.0,
        float(center_time) - half,
    )
    end = float(center_time) + half

    if duration > 0:
        end = min(duration, end)

    writer, runtime = _open_x264_raw_writer(
        out_path,
        width * 2,
        height,
        fps,
        crf,
        preset,
    )

    logo = _load_bgr_asset(
        (
            profile.get("assets")
            or {}
        ).get(
            "logo_image_relative_path"
        )
    )

    cap = cv2.VideoCapture(
        str(video_path)
    )
    if not cap.isOpened():
        raise HTTPException(
            status_code=422,
            detail="Could not open source video.",
        )

    cap.set(
        cv2.CAP_PROP_POS_MSEC,
        start * 1000.0,
    )

    index = 0
    written = 0
    write_error = None

    try:
        while True:
            ok, frame = cap.read()
            if not ok or frame is None:
                break

            t = start + index / float(fps)
            if t > end + 0.5 / float(fps):
                break

            processed = _draw_brand_banner(
                frame,
                action["bbox"],
                profile["product_name"],
                logo_image=logo,
                min_height=int(
                    height
                    * float(
                        (
                            profile.get("layout")
                            or {}
                        ).get(
                            "banner_height_ratio",
                            0.075,
                        )
                    )
                ),
            )

            output = np.hstack(
                [
                    _label_pane(
                        frame,
                        "ORIGINAL",
                    ),
                    _label_pane(
                        processed,
                        "BRAND BANNER",
                    ),
                ]
            )

            try:
                writer.stdin.write(
                    output.tobytes()
                )
            except Exception as exc:
                write_error = str(exc)[:500]
                break

            written += 1
            index += 1

    finally:
        cap.release()
        try:
            writer.stdin.close()
        except Exception:
            pass

    stderr = b""
    try:
        stderr = (
            writer.stderr.read()
            if writer.stderr
            else b""
        )
    except Exception:
        pass

    code = writer.wait()

    return {
        "ok": (
            code == 0
            and write_error is None
            and out_path.exists()
        ),
        "relative_path": (
            out_path
            .relative_to(WORKSPACE)
            .as_posix()
            if out_path.exists()
            else None
        ),
        "center_time_seconds": round(
            float(center_time),
            3,
        ),
        "frames_written": written,
        "error": (
            write_error
            or (
                stderr.decode(
                    "utf-8",
                    errors="replace",
                )[:800]
                if code != 0
                else None
            )
        ),
        "encoder": {
            "engine": "ffmpeg",
            "codec": "libx264",
            "crf": int(crf),
            "preset": str(preset),
            "runtime": runtime,
        },
    }


def _render_dynamic_follow_preview(
    video_path,
    out_path,
    action,
    profile,
    seconds,
    fps,
    width,
    height,
    duration,
    crf,
    preset,
):
    path = (
        action.get("track")
        or {}
    ).get("path") or []

    if not path:
        return {
            "ok": False,
            "error": "empty_track_path",
        }

    start = float(
        path[0]["time_seconds"]
    )
    end = min(
        float(
            path[-1]["time_seconds"]
        ),
        start + float(seconds),
    )

    writer, runtime = _open_x264_raw_writer(
        out_path,
        width * 2,
        height,
        fps,
        crf,
        preset,
    )

    logo = _load_bgr_asset(
        (
            profile.get("assets")
            or {}
        ).get(
            "logo_image_relative_path"
        )
        or (
            profile.get("assets")
            or {}
        ).get(
            "icon_image_relative_path"
        )
    )

    cap = cv2.VideoCapture(
        str(video_path)
    )
    if not cap.isOpened():
        raise HTTPException(
            status_code=422,
            detail="Could not open source video.",
        )

    cap.set(
        cv2.CAP_PROP_POS_MSEC,
        start * 1000.0,
    )

    index = 0
    written = 0
    write_error = None

    try:
        while True:
            ok, frame = cap.read()
            if not ok or frame is None:
                break

            t = start + index / float(fps)
            if t > end + 0.5 / float(fps):
                break

            bbox = _interpolate_track_bbox(
                path,
                t,
            )

            processed = frame.copy()

            if bbox:
                processed = _draw_brand_banner(
                    processed,
                    bbox,
                    profile["product_name"],
                    logo_image=logo,
                    min_height=max(
                        bbox["height"],
                        int(height * 0.045),
                    ),
                )

            output = np.hstack(
                [
                    _label_pane(
                        frame,
                        "ORIGINAL",
                    ),
                    _label_pane(
                        processed,
                        "FOLLOW BRAND",
                    ),
                ]
            )

            try:
                writer.stdin.write(
                    output.tobytes()
                )
            except Exception as exc:
                write_error = str(exc)[:500]
                break

            written += 1
            index += 1

    finally:
        cap.release()
        try:
            writer.stdin.close()
        except Exception:
            pass

    stderr = b""
    try:
        stderr = (
            writer.stderr.read()
            if writer.stderr
            else b""
        )
    except Exception:
        pass

    code = writer.wait()

    return {
        "ok": (
            code == 0
            and write_error is None
            and out_path.exists()
        ),
        "relative_path": (
            out_path
            .relative_to(WORKSPACE)
            .as_posix()
            if out_path.exists()
            else None
        ),
        "clip_start_seconds": round(
            start,
            3,
        ),
        "clip_end_seconds": round(
            end,
            3,
        ),
        "frames_written": written,
        "error": (
            write_error
            or (
                stderr.decode(
                    "utf-8",
                    errors="replace",
                )[:800]
                if code != 0
                else None
            )
        ),
        "encoder": {
            "engine": "ffmpeg",
            "codec": "libx264",
            "crf": int(crf),
            "preset": str(preset),
            "runtime": runtime,
        },
    }


def _render_endcard_preview(
    video_path,
    out_path,
    action,
    profile,
    preroll_seconds,
    fps,
    width,
    height,
    duration,
    crf,
    preset,
):
    cut = float(
        action["start_seconds"]
    )
    start = max(
        0.0,
        cut - float(preroll_seconds),
    )

    card_seconds = float(
        (
            action.get("replacement_content")
            or {}
        ).get(
            "duration_seconds",
            3.0,
        )
    )

    writer, runtime = _open_x264_raw_writer(
        out_path,
        width,
        height,
        fps,
        crf,
        preset,
    )

    logo = _load_bgr_asset(
        (
            profile.get("assets")
            or {}
        ).get(
            "logo_image_relative_path"
        )
    )

    card_image = _load_bgr_asset(
        (
            profile.get("assets")
            or {}
        ).get(
            "end_card_image_relative_path"
        )
    )

    if card_image is not None:
        if card_image.shape[2] == 4:
            bg = np.zeros(
                (height, width, 3),
                dtype=np.uint8,
            )
            card = _alpha_overlay_image(
                bg,
                card_image,
                0,
                0,
                height,
            )
            card = cv2.resize(
                card,
                (width, height),
                interpolation=cv2.INTER_AREA,
            )
        else:
            card = cv2.resize(
                card_image[..., :3],
                (width, height),
                interpolation=cv2.INTER_AREA,
            )
    else:
        card = _generated_brand_card(
            width,
            height,
            profile["product_name"],
            profile["brand_name"],
            logo_image=logo,
            subtitle="Watch now",
        )

    cap = cv2.VideoCapture(
        str(video_path)
    )
    if not cap.isOpened():
        raise HTTPException(
            status_code=422,
            detail="Could not open source video.",
        )

    cap.set(
        cv2.CAP_PROP_POS_MSEC,
        start * 1000.0,
    )

    written = 0
    write_error = None
    original_frames = max(
        0,
        int(round(
            (cut - start) * fps
        )),
    )

    try:
        for _ in range(original_frames):
            ok, frame = cap.read()
            if not ok or frame is None:
                break

            try:
                writer.stdin.write(
                    frame.tobytes()
                )
            except Exception as exc:
                write_error = str(exc)[:500]
                break

            written += 1

        if write_error is None:
            card_frames = max(
                1,
                int(round(
                    card_seconds * fps
                )),
            )

            for _ in range(card_frames):
                try:
                    writer.stdin.write(
                        card.tobytes()
                    )
                except Exception as exc:
                    write_error = str(exc)[:500]
                    break
                written += 1

    finally:
        cap.release()
        try:
            writer.stdin.close()
        except Exception:
            pass

    stderr = b""
    try:
        stderr = (
            writer.stderr.read()
            if writer.stderr
            else b""
        )
    except Exception:
        pass

    code = writer.wait()

    return {
        "ok": (
            code == 0
            and write_error is None
            and out_path.exists()
        ),
        "relative_path": (
            out_path
            .relative_to(WORKSPACE)
            .as_posix()
            if out_path.exists()
            else None
        ),
        "original_preroll_start_seconds": round(
            start,
            3,
        ),
        "cut_seconds": round(
            cut,
            3,
        ),
        "replacement_end_card_seconds": round(
            card_seconds,
            3,
        ),
        "frames_written": written,
        "error": (
            write_error
            or (
                stderr.decode(
                    "utf-8",
                    errors="replace",
                )[:800]
                if code != 0
                else None
            )
        ),
        "encoder": {
            "engine": "ffmpeg",
            "codec": "libx264",
            "crf": int(crf),
            "preset": str(preset),
            "runtime": runtime,
        },
    }


def _render_mid_promo_preview(
    video_path,
    out_path,
    action,
    profile,
    context_seconds,
    fps,
    width,
    height,
    duration,
    crf,
    preset,
):
    seg_start = float(
        action["start_seconds"]
    )
    seg_end = float(
        action["end_seconds"]
    )

    before_start = max(
        0.0,
        seg_start - float(context_seconds),
    )
    after_end = (
        min(
            duration,
            seg_end + float(context_seconds),
        )
        if duration > 0
        else seg_end + float(context_seconds)
    )

    writer, runtime = _open_x264_raw_writer(
        out_path,
        width,
        height,
        fps,
        crf,
        preset,
    )

    logo = _load_bgr_asset(
        (
            profile.get("assets")
            or {}
        ).get(
            "logo_image_relative_path"
        )
    )

    replacement = _generated_brand_card(
        width,
        height,
        profile["product_name"],
        profile["brand_name"],
        logo_image=logo,
        subtitle="Promo replacement preview",
    )

    replacement_seconds = min(
        3.0,
        max(
            1.5,
            seg_end - seg_start,
        ),
    )

    cap = cv2.VideoCapture(
        str(video_path)
    )
    if not cap.isOpened():
        raise HTTPException(
            status_code=422,
            detail="Could not open source video.",
        )

    written = 0
    write_error = None

    def write_source(a, b):
        nonlocal written, write_error
        cap.set(
            cv2.CAP_PROP_POS_MSEC,
            a * 1000.0,
        )
        count = max(
            0,
            int(round(
                (b - a) * fps
            )),
        )
        for _ in range(count):
            ok, frame = cap.read()
            if not ok or frame is None:
                break
            try:
                writer.stdin.write(
                    frame.tobytes()
                )
            except Exception as exc:
                write_error = str(exc)[:500]
                return
            written += 1

    try:
        write_source(
            before_start,
            seg_start,
        )

        if write_error is None:
            for _ in range(
                max(
                    1,
                    int(round(
                        replacement_seconds * fps
                    )),
                )
            ):
                try:
                    writer.stdin.write(
                        replacement.tobytes()
                    )
                except Exception as exc:
                    write_error = str(exc)[:500]
                    break
                written += 1

        if write_error is None:
            write_source(
                seg_end,
                after_end,
            )

    finally:
        cap.release()
        try:
            writer.stdin.close()
        except Exception:
            pass

    stderr = b""
    try:
        stderr = (
            writer.stderr.read()
            if writer.stderr
            else b""
        )
    except Exception:
        pass

    code = writer.wait()

    return {
        "ok": (
            code == 0
            and write_error is None
            and out_path.exists()
        ),
        "relative_path": (
            out_path
            .relative_to(WORKSPACE)
            .as_posix()
            if out_path.exists()
            else None
        ),
        "source_segment_start_seconds": round(
            seg_start,
            3,
        ),
        "source_segment_end_seconds": round(
            seg_end,
            3,
        ),
        "replacement_seconds": round(
            replacement_seconds,
            3,
        ),
        "frames_written": written,
        "error": (
            write_error
            or (
                stderr.decode(
                    "utf-8",
                    errors="replace",
                )[:800]
                if code != 0
                else None
            )
        ),
        "encoder": {
            "engine": "ffmpeg",
            "codec": "libx264",
            "crf": int(crf),
            "preset": str(preset),
            "runtime": runtime,
        },
    }


def _replacement_preview_sync(
    req: BrandingReplacementPreviewRequest
):
    plan_path, plan = _read_json_workspace(
        req.replacement_plan_relative_path,
        "replacement_preview",
    )

    if (
        plan.get("mode")
        != "branding_replacement_plan"
    ):
        raise HTTPException(
            status_code=422,
            detail="Expected branding_replacement_plan report.",
        )

    source_rel = (
        (plan.get("source") or {})
        .get("relative_path")
    )
    video_path = _safe_workspace_path(
        source_rel
    )

    profile = plan.get("profile") or {}

    cap = cv2.VideoCapture(
        str(video_path)
    )
    if not cap.isOpened():
        raise HTTPException(
            status_code=422,
            detail="Could not open source video.",
        )
    try:
        meta = _video_metadata(cap)
    finally:
        cap.release()

    width = int(meta.get("width") or 0)
    height = int(meta.get("height") or 0)
    fps = float(meta.get("fps") or 30.0)
    duration = float(
        meta.get("duration_seconds") or 0.0
    )

    timestamp = _app_now().strftime(
        "%Y-%m-%d_%H%M%S"
    )
    out_dir = (
        WORKSPACE
        / "review"
        / "branding_replacement_preview"
        / timestamp
        / video_path.stem
    )
    out_dir.mkdir(
        parents=True,
        exist_ok=True,
    )

    previews = []

    for action in plan.get("actions") or []:
        if (
            action.get("status") == "REVIEW"
            and not req.include_review_actions
        ):
            continue

        action_type = action.get("type")
        action_id = str(
            action.get("action_id")
        )

        if action_type == "fixed_brand_overlay":
            segments = action.get(
                "active_segments"
            ) or []

            if segments:
                s = max(
                    segments,
                    key=lambda x: (
                        float(x["end_seconds"])
                        - float(x["start_seconds"])
                    ),
                )
                center = (
                    float(s["start_seconds"])
                    + float(s["end_seconds"])
                ) / 2.0
            else:
                center = min(
                    7.0,
                    max(0.0, duration * 0.2),
                )

            out_path = (
                out_dir
                / f"{action_id}.fixed-banner-hq-compare.mp4"
            )

            preview = _render_fixed_banner_preview(
                video_path,
                out_path,
                center,
                float(req.fixed_preview_seconds),
                action,
                profile,
                fps,
                width,
                height,
                duration,
                int(req.crf),
                str(req.preset),
            )

        elif action_type == "moving_brand_overlay":
            out_path = (
                out_dir
                / f"{action_id}.moving-follow-hq-compare.mp4"
            )

            preview = _render_dynamic_follow_preview(
                video_path,
                out_path,
                action,
                profile,
                float(req.dynamic_preview_seconds),
                fps,
                width,
                height,
                duration,
                int(req.crf),
                str(req.preset),
            )

        elif action_type == "end_card_replace":
            out_path = (
                out_dir
                / "end-card-replacement-preview.mp4"
            )

            preview = _render_endcard_preview(
                video_path,
                out_path,
                action,
                profile,
                float(req.end_card_preroll_seconds),
                fps,
                width,
                height,
                duration,
                int(req.crf),
                str(req.preset),
            )

        elif action_type == "mid_promo_replace":
            out_path = (
                out_dir
                / f"{action_id}.mid-promo-replacement-preview.mp4"
            )

            preview = _render_mid_promo_preview(
                video_path,
                out_path,
                action,
                profile,
                float(req.mid_promo_context_seconds),
                fps,
                width,
                height,
                duration,
                int(req.crf),
                str(req.preset),
            )

        else:
            continue

        previews.append(
            {
                "action_id": action_id,
                "type": action_type,
                "status": action.get(
                    "status"
                ),
                "preview": preview,
            }
        )

    result = {
        "ok": any(
            x["preview"].get("ok")
            for x in previews
        ),
        "version": "0.17.0",
        "mode": "branding_replacement_preview",
        "source": {
            "relative_path": source_rel,
            "replacement_plan_relative_path": (
                plan_path
                .relative_to(WORKSPACE)
                .as_posix()
            ),
        },
        "video": meta,
        "profile": profile,
        "summary": {
            "preview_action_count": len(previews),
            "preview_success_count": sum(
                1
                for x in previews
                if x["preview"].get("ok")
            ),
            "preview_failure_count": sum(
                1
                for x in previews
                if not x["preview"].get("ok")
            ),
            "source_video_modified": False,
            "full_processed_video_created": False,
            "audio_preservation_not_tested_in_preview": True,
            "manual_visual_confirmation_required": True,
        },
        "previews": previews,
        "notes": {
            "generated_assets": (
                "If no custom banner/end-card/promo asset is configured, "
                "v0.10.0 generates a neutral product-name card for workflow testing."
            ),
            "production": (
                "Full-video render and audio-aware concat are intentionally deferred "
                "until segment boundaries and replacement layouts are visually accepted."
            ),
        },
        "output_relative_dir": (
            out_dir
            .relative_to(WORKSPACE)
            .as_posix()
        ),
    }

    report_path = (
        out_dir
        / f"{video_path.stem}.replacement-preview.json"
    )
    result["report_relative_path"] = (
        report_path
        .relative_to(WORKSPACE)
        .as_posix()
    )
    report_path.write_text(
        json.dumps(
            result,
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )

    return result




# ---------------------------------------------------------------------------
# v0.10.1 Placement rules + promo/end-card boundary refinement
# ---------------------------------------------------------------------------

class BrandingReplacementSegmentCensusRequest(BaseModel):
    router_report_relative_path: str

    # Brand OCR inside a promo is an anchor/evidence point, NOT the beginning
    # of the promo. Search much farther backwards for promotional copy / regime
    # transition.
    mid_context_seconds: float = 24.0
    scene_scan_interval_seconds: float = 0.25
    min_scene_cut_score: float = 0.30
    max_mid_segment_seconds: float = 32.0

    promo_ocr_interval_seconds: float = 1.0
    promo_ocr_language: str = "eng"
    promo_ocr_min_confidence: float = 25.0
    promo_ocr_scale: float = 1.5
    promo_subtitle_exclusion_y_ratio: float = 0.76
    promo_large_text_height_ratio: float = 0.020
    promo_text_score_threshold: float = 0.48
    promo_group_gap_seconds: float = 2.25

    # End-card OCR often starts slightly AFTER the first download/install CTA
    # screen. Backtrack a small amount to the preceding visual transition.
    end_card_backtrack_seconds: float = 3.0
    end_card_max_early_seconds: float = 1.75
    end_card_pre_cut_padding_seconds: float = 0.08


def _word_bbox(word):
    return {
        "x": int(word.get("x") or 0),
        "y": int(word.get("y") or 0),
        "width": int(word.get("width") or 1),
        "height": int(word.get("height") or 1),
    }


def _promo_text_frame_score(
    frame,
    words,
    ignore_bboxes,
    subtitle_exclusion_y_ratio,
    large_text_height_ratio,
):
    h, w = frame.shape[:2]
    usable = []

    for word in words:
        bbox = _word_bbox(word)
        cx, cy = _bbox_center(bbox)

        # Exclude normal bottom subtitles/captions. The purpose here is to find
        # promotional copy in the content region.
        if cy >= float(subtitle_exclusion_y_ratio) * h:
            continue

        # Exclude the already-known persistent corner brand/logo so it cannot
        # make every story frame look promotional.
        ignored = False
        for ib in ignore_bboxes:
            if _bbox_iou(bbox, ib) >= 0.10:
                ignored = True
                break
        if ignored:
            continue

        text = str(word.get("text") or "").strip()
        if len(text) <= 1:
            continue

        usable.append(
            {
                "text": text,
                "bbox": bbox,
                "height_ratio": float(bbox["height"]) / float(max(1, h)),
                "area_ratio": (
                    float(bbox["width"] * bbox["height"])
                    / float(max(1, w * h))
                ),
            }
        )

    total_area_ratio = sum(x["area_ratio"] for x in usable)
    large_count = sum(
        1
        for x in usable
        if x["height_ratio"] >= float(large_text_height_ratio)
    )
    token_count = len(usable)
    max_height_ratio = max(
        [x["height_ratio"] for x in usable],
        default=0.0,
    )

    # Story subtitles are excluded spatially. Promotional title/copy tends to
    # occupy substantially more non-bottom area and/or use larger type.
    score = (
        min(1.6, total_area_ratio / 0.0065)
        + min(0.8, large_count * 0.18)
        + min(0.35, token_count * 0.035)
        + min(0.45, max_height_ratio / 0.060)
    )

    return {
        "score": round(float(score), 6),
        "token_count": token_count,
        "large_text_count": large_count,
        "text_area_ratio": round(
            float(total_area_ratio),
            8,
        ),
        "max_text_height_ratio": round(
            float(max_height_ratio),
            6,
        ),
        "sample_text": [
            x["text"]
            for x in usable[:12]
        ],
    }


def _scan_promo_text_activity(
    video_path,
    start,
    end,
    interval,
    language,
    min_confidence,
    scale,
    ignore_bboxes,
    subtitle_exclusion_y_ratio,
    large_text_height_ratio,
    score_threshold,
):
    cap = cv2.VideoCapture(str(video_path))
    if not cap.isOpened():
        raise HTTPException(
            status_code=422,
            detail="Could not open source video for promo OCR scan.",
        )

    samples = []
    t = max(0.0, float(start))

    try:
        while t <= float(end) + 1e-9:
            cap.set(
                cv2.CAP_PROP_POS_MSEC,
                t * 1000.0,
            )
            ok, frame = cap.read()

            if ok and frame is not None:
                try:
                    words = _tesseract_words(
                        frame,
                        str(language),
                        float(min_confidence),
                        float(scale),
                    )
                    diag = _promo_text_frame_score(
                        frame,
                        words,
                        ignore_bboxes,
                        float(subtitle_exclusion_y_ratio),
                        float(large_text_height_ratio),
                    )
                    error = None
                except Exception as exc:
                    words = []
                    diag = {
                        "score": 0.0,
                        "token_count": 0,
                        "large_text_count": 0,
                        "text_area_ratio": 0.0,
                        "max_text_height_ratio": 0.0,
                        "sample_text": [],
                    }
                    error = str(exc)[:300]

                samples.append(
                    {
                        "time_seconds": round(float(t), 3),
                        **diag,
                        "promo_like": bool(
                            float(diag["score"])
                            >= float(score_threshold)
                        ),
                        "ocr_error": error,
                    }
                )

            t += float(interval)

        return samples
    finally:
        cap.release()


def _group_promo_text_samples(samples, max_gap_seconds):
    positives = [
        x
        for x in samples
        if x.get("promo_like")
    ]

    if not positives:
        return []

    groups = []
    current = [positives[0]]

    for sample in positives[1:]:
        if (
            float(sample["time_seconds"])
            - float(current[-1]["time_seconds"])
            <= float(max_gap_seconds)
        ):
            current.append(sample)
        else:
            groups.append(current)
            current = [sample]

    groups.append(current)

    result = []

    for group in groups:
        avg_score = float(np.mean([
            float(x["score"])
            for x in group
        ]))
        peak_score = max(
            float(x["score"])
            for x in group
        )
        total_large = sum(
            int(x["large_text_count"])
            for x in group
        )

        result.append(
            {
                "start_seconds": float(
                    group[0]["time_seconds"]
                ),
                "end_seconds": float(
                    group[-1]["time_seconds"]
                ),
                "sample_count": len(group),
                "average_score": round(
                    avg_score,
                    6,
                ),
                "peak_score": round(
                    peak_score,
                    6,
                ),
                "large_text_total": total_large,
                "samples": group,
            }
        )

    return result


def _nearest_cut_around(
    cut_scores,
    target,
    radius_seconds,
    threshold,
):
    candidates = [
        x
        for x in cut_scores
        if (
            abs(
                float(x["time_seconds"])
                - float(target)
            )
            <= float(radius_seconds)
            and float(x["cut_score"])
            >= float(threshold)
        )
    ]

    if not candidates:
        return None

    candidates.sort(
        key=lambda x: (
            abs(
                float(x["time_seconds"])
                - float(target)
            ),
            -float(x["cut_score"]),
        )
    )
    return candidates[0]


def _select_mid_promo_onset(
    groups,
    cut_scores,
    evidence_start,
    min_scene_cut_score,
):
    if not groups:
        return None

    candidates = []

    for group in groups:
        start = float(group["start_seconds"])

        # We want the start of promo, so only groups at/before the known brand
        # evidence matter.
        if start > float(evidence_start) + 0.5:
            continue

        cut = _nearest_cut_around(
            cut_scores,
            start,
            1.75,
            float(min_scene_cut_score),
        )

        cut_score = (
            float(cut["cut_score"])
            if cut
            else 0.0
        )

        # A group with repeated promotional copy + a scene transition is a
        # stronger onset candidate. Keep a small bonus for larger text.
        onset_score = (
            float(group["average_score"])
            + 0.65 * cut_score
            + min(
                0.55,
                int(group["sample_count"]) * 0.11,
            )
            + min(
                0.35,
                int(group["large_text_total"]) * 0.025,
            )
        )

        start_from_cut = (
            float(cut["time_seconds"])
            if cut
            else start
        )

        candidates.append(
            {
                "group": group,
                "nearby_cut": cut,
                "candidate_start_seconds": round(
                    start_from_cut,
                    3,
                ),
                "onset_score": round(
                    onset_score,
                    6,
                ),
            }
        )

    if not candidates:
        return None

    peak = max(
        float(x["onset_score"])
        for x in candidates
    )

    # Prefer the EARLIEST credible promo onset, rather than the closest text
    # hit to ReelShort OCR. This is exactly the failure mode in v0.10.0.
    credible = [
        x
        for x in candidates
        if float(x["onset_score"]) >= 0.68 * peak
    ]

    credible.sort(
        key=lambda x: float(
            x["candidate_start_seconds"]
        )
    )

    return credible[0] if credible else max(
        candidates,
        key=lambda x: float(x["onset_score"]),
    )


def _end_card_mask_review_onset(
    layer,
    duration,
):
    evidence = layer.get("evidence") or {}
    review_rel = evidence.get(
        "mask_review_relative_path"
    )

    if not review_rel:
        return None

    try:
        _, review = _read_json_workspace(
            review_rel,
            "replacement_segment_census",
        )
    except Exception:
        return None

    candidates = []

    for item in review.get("execution_segments") or []:
        start = (
            item.get("start_seconds")
            if item.get("start_seconds") is not None
            else item.get("start")
        )
        end = (
            item.get("end_seconds")
            if item.get("end_seconds") is not None
            else item.get("end")
        )
        bbox = (
            item.get("stable_bbox")
            or item.get("bbox")
        )

        if (
            start is None
            or end is None
            or not bbox
        ):
            continue

        area = (
            float(bbox.get("width") or 0)
            * float(bbox.get("height") or 0)
        )

        near_end = (
            float(end)
            >= max(
                0.0,
                float(duration) - 5.0,
            )
        )

        if near_end and area >= 32000:
            candidates.append(
                {
                    "start_seconds": float(start),
                    "end_seconds": float(end),
                    "bbox": bbox,
                    "area": area,
                }
            )

    if not candidates:
        return None

    candidates.sort(
        key=lambda x: float(x["start_seconds"])
    )
    return candidates[0]


def _refine_end_card_start(
    video_path,
    layer,
    raw_start,
    duration,
    backtrack_seconds,
    max_early_seconds,
    pre_cut_padding_seconds,
    scene_interval,
    min_scene_cut_score,
):
    window_start = max(
        0.0,
        float(raw_start)
        - float(backtrack_seconds),
    )

    scores = _scene_cut_scores(
        video_path,
        window_start,
        min(
            float(duration),
            float(raw_start) + 0.5,
        )
        if duration > 0
        else float(raw_start) + 0.5,
        max(
            0.10,
            min(
                0.25,
                float(scene_interval),
            ),
        ),
    )

    before = _best_cut_before(
        scores,
        float(raw_start),
        window_start,
        float(min_scene_cut_score),
    )

    mask_onset = _end_card_mask_review_onset(
        layer,
        duration,
    )

    earliest_allowed = max(
        0.0,
        float(raw_start)
        - float(max_early_seconds),
    )

    candidates = [
        {
            "source": "router_end_card_ocr",
            "time_seconds": float(raw_start),
        }
    ]

    if mask_onset:
        candidates.append(
            {
                "source": "mask_review_large_end_segment",
                "time_seconds": max(
                    earliest_allowed,
                    float(mask_onset["start_seconds"])
                    - float(pre_cut_padding_seconds),
                ),
                "raw": mask_onset,
            }
        )

    if before:
        candidates.append(
            {
                "source": "scene_cut_before_end_card",
                "time_seconds": max(
                    earliest_allowed,
                    float(before["time_seconds"])
                    - float(pre_cut_padding_seconds),
                ),
                "raw": before,
            }
        )

    # User preference: cut as soon as the download/install CTA screen begins,
    # slightly before the old OCR-based end card. Use the earliest candidate,
    # but clamp how far we are allowed to move backwards.
    chosen = min(
        candidates,
        key=lambda x: float(x["time_seconds"]),
    )

    return {
        "raw_start_seconds": round(
            float(raw_start),
            3,
        ),
        "refined_start_seconds": round(
            float(chosen["time_seconds"]),
            3,
        ),
        "chosen_source": chosen["source"],
        "candidate_signals": candidates,
        "scene_cut_scan": scores,
    }


def _replacement_segment_census_sync(
    req: BrandingReplacementSegmentCensusRequest
):
    router_path = _safe_workspace_path(
        req.router_report_relative_path
    )
    try:
        router = json.loads(
            router_path.read_text(encoding="utf-8")
        )
    except Exception as exc:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "replacement_segment_census",
                "error": "invalid_router_report",
                "message": str(exc)[:500],
            },
        )

    source_rel = (
        (router.get("source") or {})
        .get("relative_path")
    )
    if not source_rel:
        raise HTTPException(
            status_code=422,
            detail="Router report has no source.relative_path.",
        )

    video_path = _safe_workspace_path(source_rel)

    cap = cv2.VideoCapture(str(video_path))
    if not cap.isOpened():
        raise HTTPException(
            status_code=422,
            detail="Could not open source video.",
        )
    try:
        meta = _video_metadata(cap)
    finally:
        cap.release()

    duration = float(
        meta.get("duration_seconds") or 0.0
    )
    height = int(meta.get("height") or 0)

    if not 4.0 <= float(req.mid_context_seconds) <= 45.0:
        raise HTTPException(
            status_code=422,
            detail="mid_context_seconds must be between 4 and 45.",
        )

    if not 0.15 <= float(req.scene_scan_interval_seconds) <= 1.0:
        raise HTTPException(
            status_code=422,
            detail="scene_scan_interval_seconds must be between 0.15 and 1.",
        )

    if not 10.0 <= float(req.max_mid_segment_seconds) <= 60.0:
        raise HTTPException(
            status_code=422,
            detail="max_mid_segment_seconds must be between 10 and 60.",
        )

    ignore_bboxes = []
    for layer in router.get("watermark_layers") or []:
        if str(layer.get("type") or "") == "fixed_strong":
            bbox = (layer.get("evidence") or {}).get("bbox")
            if bbox:
                ignore_bboxes.append(bbox)

    candidates = []
    diagnostics = {
        "mid_promo_scans": [],
        "end_card_refinements": [],
    }

    for layer in router.get("watermark_layers") or []:
        layer_type = str(layer.get("type") or "")
        evidence = layer.get("evidence") or {}

        if layer_type == "end_card":
            raw_start = float(
                evidence.get("time_min_seconds")
                or max(0.0, duration - 3.0)
            )
            end = float(
                evidence.get("time_max_seconds")
                or duration
            )

            refinement = _refine_end_card_start(
                video_path,
                layer,
                raw_start,
                duration,
                float(req.end_card_backtrack_seconds),
                float(req.end_card_max_early_seconds),
                float(req.end_card_pre_cut_padding_seconds),
                float(req.scene_scan_interval_seconds),
                float(req.min_scene_cut_score),
            )

            start = float(
                refinement["refined_start_seconds"]
            )

            diagnostics[
                "end_card_refinements"
            ].append(refinement)

            candidates.append(
                {
                    "segment_id": "end-card",
                    "type": "end_card",
                    "status": "REVIEW",
                    "start_seconds": round(
                        max(0.0, start),
                        3,
                    ),
                    "end_seconds": round(
                        min(duration, end)
                        if duration > 0
                        else end,
                        3,
                    ),
                    "original_ocr_start_seconds": round(
                        raw_start,
                        3,
                    ),
                    "start_refinement": refinement,
                    "evidence_layer_id": layer.get(
                        "layer_id"
                    ),
                    "confidence": layer.get(
                        "confidence"
                    ),
                    "replacement_strategy": "trim_from_download_cta_onset_and_append_own_end_card",
                }
            )

        elif layer_type == "unclassified_brand_text":
            t0 = float(
                evidence.get("time_min_seconds")
                or 0.0
            )
            t1 = float(
                evidence.get("time_max_seconds")
                or t0
            )

            if duration > 0 and t0 >= duration - 8.0:
                continue

            window_start = max(
                0.0,
                t0 - float(req.mid_context_seconds),
            )
            window_end = (
                min(
                    duration,
                    t1 + 10.0,
                )
                if duration > 0
                else t1 + 10.0
            )

            cut_scores = _scene_cut_scores(
                video_path,
                window_start,
                window_end,
                float(req.scene_scan_interval_seconds),
            )

            promo_text_samples = _scan_promo_text_activity(
                video_path,
                window_start,
                min(
                    window_end,
                    t0 + 1.0,
                ),
                float(req.promo_ocr_interval_seconds),
                str(req.promo_ocr_language),
                float(req.promo_ocr_min_confidence),
                float(req.promo_ocr_scale),
                ignore_bboxes,
                float(req.promo_subtitle_exclusion_y_ratio),
                float(req.promo_large_text_height_ratio),
                float(req.promo_text_score_threshold),
            )

            groups = _group_promo_text_samples(
                promo_text_samples,
                float(req.promo_group_gap_seconds),
            )

            onset = _select_mid_promo_onset(
                groups,
                cut_scores,
                t0,
                float(req.min_scene_cut_score),
                float(req.promo_episode_gap_seconds),
                int(req.promo_episode_min_samples),
                float(req.promo_episode_min_span_seconds),
                float(req.promo_episode_anchor_gap_seconds),
                float(req.promo_onset_cut_radius_seconds),
                float(req.promo_onset_max_cut_lead_seconds),
            )

            fallback_before = _best_cut_before(
                cut_scores,
                t0,
                window_start,
                float(req.min_scene_cut_score),
            )

            if (
                onset
                and onset.get("candidate_start_seconds")
                is not None
            ):
                start = float(
                    onset["candidate_start_seconds"]
                )
                start_source = "sustained_promotional_episode_onset"
            elif fallback_before:
                start = float(
                    fallback_before["time_seconds"]
                )
                start_source = "nearest_scene_cut_fallback"
            else:
                start = max(
                    0.0,
                    t0 - 1.0,
                )
                start_source = "brand_evidence_fallback"

            # After the brand evidence, retain the old idea of ending at the
            # next clear visual cut. The major v0.10.0 failure was the START.
            after = _best_cut_after(
                cut_scores,
                t1,
                window_end,
                float(req.min_scene_cut_score),
            )

            end = (
                float(after["time_seconds"])
                if after
                else min(
                    duration,
                    t1 + 2.0,
                )
                if duration > 0
                else t1 + 2.0
            )

            segment_duration = max(
                0.0,
                end - start,
            )

            qualifies_duration = (
                1.0
                <= segment_duration
                <= float(req.max_mid_segment_seconds)
            )

            scan_diag = {
                "evidence_layer_id": layer.get(
                    "layer_id"
                ),
                "window_start_seconds": round(
                    window_start,
                    3,
                ),
                "window_end_seconds": round(
                    window_end,
                    3,
                ),
                "brand_evidence_start_seconds": round(
                    t0,
                    3,
                ),
                "brand_evidence_end_seconds": round(
                    t1,
                    3,
                ),
                "promo_text_samples": promo_text_samples,
                "promo_text_groups": groups,
                "selected_onset": onset,
                "fallback_before_cut": fallback_before,
                "selected_end_cut": after,
            }

            diagnostics[
                "mid_promo_scans"
            ].append(scan_diag)

            candidates.append(
                {
                    "segment_id": (
                        f"mid-promo-{layer.get('layer_id')}"
                    ),
                    "type": "mid_promo_candidate",
                    "status": "REVIEW",
                    "start_seconds": round(
                        start,
                        3,
                    ),
                    "end_seconds": round(
                        end,
                        3,
                    ),
                    "duration_seconds": round(
                        segment_duration,
                        3,
                    ),
                    "qualifies_duration": bool(
                        qualifies_duration
                    ),
                    "start_source": start_source,
                    "evidence_layer_id": layer.get(
                        "layer_id"
                    ),
                    "brand_evidence_start_seconds": round(
                        t0,
                        3,
                    ),
                    "brand_evidence_end_seconds": round(
                        t1,
                        3,
                    ),
                    "selected_onset": onset,
                    "after_cut": after,
                    "replacement_strategy": "replace_full_promo_from_copy_onset_then_resume_story",
                    "note": (
                        "Brand OCR is treated only as confirmation that the block "
                        "contains competitor promotion. Start detection backtracks "
                        "for non-subtitle promotional copy and its nearby scene cut."
                    ),
                }
            )

    timestamp = _app_now().strftime(
        "%Y-%m-%d_%H%M%S"
    )
    out_dir = (
        WORKSPACE
        / "review"
        / "branding_replacement_segment_census"
        / timestamp
        / video_path.stem
    )
    out_dir.mkdir(
        parents=True,
        exist_ok=True,
    )

    result = {
        "ok": True,
        "version": "0.17.0",
        "mode": "branding_replacement_segment_census",
        "source": {
            "relative_path": source_rel,
            "router_report_relative_path": (
                router_path
                .relative_to(WORKSPACE)
                .as_posix()
            ),
        },
        "video": meta,
        "summary": {
            "candidate_count": len(candidates),
            "end_card_candidate_count": sum(
                1 for x in candidates
                if x["type"] == "end_card"
            ),
            "mid_promo_candidate_count": sum(
                1 for x in candidates
                if x["type"] == "mid_promo_candidate"
            ),
            "source_video_modified": False,
            "manual_review_required": True,
        },
        "segments": candidates,
        "diagnostics": diagnostics,
        "policy": {
            "end_card": (
                "Cut at the earliest validated download/install CTA onset, "
                "slightly before the old end-card OCR evidence when supported "
                "by a scene cut or large end-card mask."
            ),
            "mid_promo": (
                "Brand OCR is an anchor, not the promo start. Backtrack for "
                "large non-subtitle promotional copy and visual transitions."
            ),
        },
        "output_relative_dir": (
            out_dir
            .relative_to(WORKSPACE)
            .as_posix()
        ),
    }

    report_path = (
        out_dir
        / f"{video_path.stem}.replacement-segment-census.json"
    )
    result["report_relative_path"] = (
        report_path
        .relative_to(WORKSPACE)
        .as_posix()
    )
    report_path.write_text(
        json.dumps(
            result,
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )

    return result


def _draw_clean_brand_mark(
    frame,
    bbox,
    profile,
    placement,
):
    out = frame.copy()
    h, w = out.shape[:2]
    b = _clip_bbox(bbox, w, h)

    assets = profile.get("assets") or {}
    logo = _load_bgr_asset(
        assets.get("logo_image_relative_path")
        or assets.get("icon_image_relative_path")
    )

    brand_text = str(
        profile.get("brand_name")
        or profile.get("product_name")
        or ""
    ).strip()

    pad = max(
        4,
        int(round(b["height"] * 0.12)),
    )

    if logo is not None:
        target_h = max(
            18,
            int(round(b["height"] * 0.82)),
        )

        ih, iw = logo.shape[:2]
        target_w = int(round(
            iw * target_h / float(max(1, ih))
        ))

        if placement.endswith("_right"):
            x = max(
                4,
                b["x"] + b["width"] - target_w,
            )
        else:
            x = b["x"]

        y = int(round(
            b["y"]
            + (b["height"] - target_h) / 2.0
        ))

        out = _alpha_overlay_image(
            out,
            logo,
            x,
            y,
            target_h,
        )

        # If a logo asset exists, do not force a text banner beside it.
        return out

    if not brand_text:
        return out

    font = cv2.FONT_HERSHEY_SIMPLEX
    target_h = max(
        18,
        int(round(b["height"] * 0.62)),
    )
    scale = max(
        0.42,
        target_h / 34.0,
    )
    thickness = max(
        1,
        int(round(
            b["height"] / 30.0
        )),
    )

    size, _ = cv2.getTextSize(
        brand_text,
        font,
        scale,
        thickness,
    )

    max_w = min(
        int(round(w * 0.38)),
        max(
            b["width"],
            int(round(w * 0.18)),
        ),
    )

    if size[0] > max_w:
        scale *= (
            max_w
            / float(max(1, size[0]))
        )
        size, _ = cv2.getTextSize(
            brand_text,
            font,
            scale,
            thickness,
        )

    if placement.endswith("_right"):
        tx = max(
            4,
            b["x"] + b["width"] - size[0],
        )
    else:
        tx = b["x"]

    ty = min(
        h - 6,
        max(
            size[1] + 4,
            b["y"]
            + int(round(
                (b["height"] + size[1]) / 2.0
            )),
        ),
    )

    # Transparent brand mark: just a subtle outline/shadow for readability,
    # no rectangular banner.
    cv2.putText(
        out,
        brand_text,
        (tx + 1, ty + 2),
        font,
        scale,
        (0, 0, 0),
        thickness + 2,
        cv2.LINE_AA,
    )
    cv2.putText(
        out,
        brand_text,
        (tx, ty),
        font,
        scale,
        (245, 245, 245),
        thickness,
        cv2.LINE_AA,
    )

    return out


def _replacement_plan_sync(
    req: BrandingReplacementPlanRequest
):
    router_path, router = _read_json_workspace(
        req.router_report_relative_path,
        "replacement_plan",
    )

    source_rel = (
        (router.get("source") or {})
        .get("relative_path")
    )
    if not source_rel:
        raise HTTPException(
            status_code=422,
            detail="Router report has no source path.",
        )

    profile = _get_replacement_profile(
        req.profile_id
    )

    video = router.get("video") or {}
    width = int(video.get("width") or 0)
    height = int(video.get("height") or 0)

    actions = []

    for layer in router.get("watermark_layers") or []:
        layer_type = str(layer.get("type") or "")
        evidence = layer.get("evidence") or {}

        if layer_type == "fixed_strong":
            bbox = evidence.get("bbox")
            if not bbox:
                continue

            placement = _fixed_placement_from_bbox(
                bbox,
                width,
                height,
            )

            if placement.startswith("top_"):
                handler = "top_cleanup_brand_overlay"
                strategy = "remove_competitor_top_watermark_then_overlay_own_brand"
                status = "AUTO"
            elif placement.startswith("bottom_"):
                handler = "bottom_banner_replace"
                strategy = "small_bottom_banner_cover_for_text_watermark_or_cta"
                status = "AUTO"
            else:
                handler = "local_banner_replace"
                strategy = "review_local_banner_cover"
                status = "REVIEW"

            actions.append(
                {
                    "action_id": (
                        f"replace-{layer.get('layer_id')}"
                    ),
                    "source_layer_id": layer.get(
                        "layer_id"
                    ),
                    "type": "fixed_brand_overlay",
                    "status": status,
                    "handler": handler,
                    "placement": placement,
                    "bbox": bbox,
                    "active_segments": _fixed_active_segments_for_layer(
                        layer,
                        source_rel,
                    ),
                    "strategy": strategy,
                    "replacement_content": {
                        "product_name": profile[
                            "product_name"
                        ],
                        "brand_name": profile[
                            "brand_name"
                        ],
                        "logo_image_relative_path": (
                            profile.get("assets") or {}
                        ).get(
                            "logo_image_relative_path"
                        ),
                        "icon_image_relative_path": (
                            profile.get("assets") or {}
                        ).get(
                            "icon_image_relative_path"
                        ),
                    },
                }
            )

    if req.segment_census_report_relative_path:
        _, segment_report = _read_json_workspace(
            req.segment_census_report_relative_path,
            "replacement_plan",
        )

        for seg in segment_report.get("segments") or []:
            if seg.get("type") == "end_card":
                actions.append(
                    {
                        "action_id": "replace-end-card",
                        "type": "end_card_replace",
                        "status": "REVIEW",
                        "handler": "trim_append_end_card",
                        "start_seconds": seg[
                            "start_seconds"
                        ],
                        "end_seconds": seg[
                            "end_seconds"
                        ],
                        "strategy": "trim_from_download_cta_onset_then_append_own_endcard",
                        "source_candidate": seg,
                        "replacement_content": {
                            "end_card_image_relative_path": (
                                profile.get("assets") or {}
                            ).get(
                                "end_card_image_relative_path"
                            ),
                            "end_card_video_relative_path": (
                                profile.get("assets") or {}
                            ).get(
                                "end_card_video_relative_path"
                            ),
                            "generated_product_name": profile[
                                "product_name"
                            ],
                            "duration_seconds": (
                                profile.get("layout") or {}
                            ).get(
                                "end_card_duration_seconds",
                                3.0,
                            ),
                        },
                    }
                )

            elif seg.get("type") == "mid_promo_candidate":
                actions.append(
                    {
                        "action_id": seg.get(
                            "segment_id"
                        ),
                        "type": "mid_promo_replace",
                        "status": "REVIEW",
                        "handler": "replace_mid_segment",
                        "start_seconds": seg[
                            "start_seconds"
                        ],
                        "end_seconds": seg[
                            "end_seconds"
                        ],
                        "strategy": "replace_full_competitor_promo_from_copy_onset_then_resume_story",
                        "replacement_content": {
                            "mid_promo_video_relative_path": (
                                profile.get("assets") or {}
                            ).get(
                                "mid_promo_video_relative_path"
                            ),
                            "generated_product_name": profile[
                                "product_name"
                            ],
                        },
                        "source_candidate": seg,
                    }
                )

    flow = _load_flow_tracks(
        req.moving_flow_report_relative_path,
        source_rel,
    )

    if flow:
        report = flow["report"]
        for track in report.get("tracks") or []:
            path = track.get("path") or []
            if not path:
                continue

            actions.append(
                {
                    "action_id": (
                        f"moving-track-{track.get('cluster_id')}"
                    ),
                    "type": "moving_brand_overlay",
                    "status": (
                        "AUTO"
                        if req.moving_tracks_approved
                        else "REVIEW"
                    ),
                    "handler": "moving_follow_brand_cover",
                    "strategy": "track_competitor_text_and_follow_cover_with_own_name_logo_or_icon",
                    "track": {
                        "cluster_id": track.get("cluster_id"),
                        "anchor_time_seconds": track.get(
                            "anchor_time_seconds"
                        ),
                        "anchor_observed_text": track.get(
                            "anchor_observed_text"
                        ),
                        "path_sample_count": len(path),
                        "path": path,
                    },
                    "replacement_content": {
                        "product_name": profile[
                            "product_name"
                        ],
                        "brand_name": profile[
                            "brand_name"
                        ],
                        "logo_image_relative_path": (
                            profile.get("assets") or {}
                        ).get(
                            "logo_image_relative_path"
                        ),
                        "icon_image_relative_path": (
                            profile.get("assets") or {}
                        ).get(
                            "icon_image_relative_path"
                        ),
                    },
                    "note": (
                        "Dynamic track stays REVIEW until drift is approved. "
                        "Replacement follows the tracked competitor bbox."
                    ),
                }
            )

    timestamp = _app_now().strftime(
        "%Y-%m-%d_%H%M%S"
    )
    video_path = _safe_workspace_path(
        source_rel
    )
    out_dir = (
        WORKSPACE
        / "review"
        / "branding_replacement_plan"
        / timestamp
        / video_path.stem
    )
    out_dir.mkdir(
        parents=True,
        exist_ok=True,
    )

    result = {
        "ok": True,
        "version": "0.17.0",
        "mode": "branding_replacement_plan",
        "source": {
            "relative_path": source_rel,
            "router_report_relative_path": (
                router_path
                .relative_to(WORKSPACE)
                .as_posix()
            ),
        },
        "profile": profile,
        "summary": {
            "action_count": len(actions),
            "auto_action_count": sum(
                1 for x in actions
                if x["status"] == "AUTO"
            ),
            "review_action_count": sum(
                1 for x in actions
                if x["status"] == "REVIEW"
            ),
            "fixed_overlay_count": sum(
                1 for x in actions
                if x["type"] == "fixed_brand_overlay"
            ),
            "top_cleanup_brand_count": sum(
                1 for x in actions
                if x.get("handler")
                == "top_cleanup_brand_overlay"
            ),
            "bottom_banner_count": sum(
                1 for x in actions
                if x.get("handler")
                == "bottom_banner_replace"
            ),
            "moving_overlay_count": sum(
                1 for x in actions
                if x["type"] == "moving_brand_overlay"
            ),
            "end_card_replace_count": sum(
                1 for x in actions
                if x["type"] == "end_card_replace"
            ),
            "mid_promo_replace_count": sum(
                1 for x in actions
                if x["type"] == "mid_promo_replace"
            ),
            "source_video_modified": False,
            "full_processed_video_created": False,
        },
        "actions": actions,
        "policy": {
            "top_left_right": (
                "Remove the competitor corner watermark with the approved "
                "local cleanup method, then place own logo/brand directly. "
                "Do not use a banner."
            ),
            "bottom": (
                "Bottom promotional text / CTA / watermarks may be covered "
                "with a compact banner because they are often large and hard "
                "to clean invisibly."
            ),
            "moving": (
                "Recognize a competitor text anchor, track its bbox, then "
                "follow-cover it with own product name/logo/icon."
            ),
            "end_card": (
                "Cut from the download/install CTA onset, not only from the "
                "later branded end-card OCR frame."
            ),
            "mid_promo": (
                "Use competitor brand text as evidence, then backtrack for "
                "the actual promotional-copy onset before replacing the block."
            ),
        },
        "output_relative_dir": (
            out_dir
            .relative_to(WORKSPACE)
            .as_posix()
        ),
    }

    report_path = (
        out_dir
        / f"{video_path.stem}.replacement-plan.json"
    )
    result["report_relative_path"] = (
        report_path
        .relative_to(WORKSPACE)
        .as_posix()
    )
    report_path.write_text(
        json.dumps(
            result,
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )

    return result


def _render_fixed_banner_preview(
    video_path,
    out_path,
    center_time,
    seconds,
    action,
    profile,
    fps,
    width,
    height,
    duration,
    crf,
    preset,
):
    half = float(seconds) / 2.0
    start = max(
        0.0,
        float(center_time) - half,
    )
    end = float(center_time) + half

    if duration > 0:
        end = min(duration, end)

    writer, runtime = _open_x264_raw_writer(
        out_path,
        width * 2,
        height,
        fps,
        crf,
        preset,
    )

    logo = _load_bgr_asset(
        (
            profile.get("assets")
            or {}
        ).get("logo_image_relative_path")
    )

    cap = cv2.VideoCapture(str(video_path))
    if not cap.isOpened():
        raise HTTPException(
            status_code=422,
            detail="Could not open source video.",
        )

    cap.set(
        cv2.CAP_PROP_POS_MSEC,
        start * 1000.0,
    )

    index = 0
    written = 0
    write_error = None

    placement = str(
        action.get("placement") or ""
    )
    handler = str(
        action.get("handler") or ""
    )
    segments = action.get(
        "active_segments"
    ) or []

    try:
        while True:
            ok, frame = cap.read()
            if not ok or frame is None:
                break

            t = start + index / float(fps)
            if t > end + 0.5 / float(fps):
                break

            processed = frame.copy()

            if (
                handler == "top_cleanup_brand_overlay"
                or placement.startswith("top_")
            ):
                active = _active_fixed_segment(
                    segments,
                    t,
                )

                if active is not None:
                    mask = _segment_bbox_mask(
                        width,
                        height,
                        active["bbox"],
                        2,
                    )
                    processed = cv2.inpaint(
                        processed,
                        mask,
                        3.0,
                        cv2.INPAINT_TELEA,
                    )

                    processed = _draw_clean_brand_mark(
                        processed,
                        active["bbox"],
                        profile,
                        placement,
                    )

                label = "CLEAN + BRAND"

            elif (
                handler == "bottom_banner_replace"
                or placement.startswith("bottom_")
            ):
                processed = _draw_brand_banner(
                    processed,
                    action["bbox"],
                    profile["product_name"],
                    logo_image=logo,
                    min_height=int(
                        height
                        * float(
                            (
                                profile.get("layout")
                                or {}
                            ).get(
                                "banner_height_ratio",
                                0.075,
                            )
                        )
                    ),
                )
                label = "BOTTOM BANNER"

            else:
                processed = _draw_brand_banner(
                    processed,
                    action["bbox"],
                    profile["product_name"],
                    logo_image=logo,
                    min_height=int(
                        height * 0.060
                    ),
                )
                label = "LOCAL COVER"

            output = np.hstack(
                [
                    _label_pane(
                        frame,
                        "ORIGINAL",
                    ),
                    _label_pane(
                        processed,
                        label,
                    ),
                ]
            )

            try:
                writer.stdin.write(
                    output.tobytes()
                )
            except Exception as exc:
                write_error = str(exc)[:500]
                break

            written += 1
            index += 1

    finally:
        cap.release()
        try:
            writer.stdin.close()
        except Exception:
            pass

    stderr = b""
    try:
        stderr = (
            writer.stderr.read()
            if writer.stderr
            else b""
        )
    except Exception:
        pass

    code = writer.wait()

    return {
        "ok": (
            code == 0
            and write_error is None
            and out_path.exists()
        ),
        "relative_path": (
            out_path
            .relative_to(WORKSPACE)
            .as_posix()
            if out_path.exists()
            else None
        ),
        "center_time_seconds": round(
            float(center_time),
            3,
        ),
        "placement": placement,
        "handler": handler,
        "frames_written": written,
        "error": (
            write_error
            or (
                stderr.decode(
                    "utf-8",
                    errors="replace",
                )[:800]
                if code != 0
                else None
            )
        ),
        "encoder": {
            "engine": "ffmpeg",
            "codec": "libx264",
            "crf": int(crf),
            "preset": str(preset),
            "runtime": runtime,
        },
    }




# ---------------------------------------------------------------------------
# v0.10.2 Sustained Promo Episode Onset
# ---------------------------------------------------------------------------

class BrandingReplacementSegmentCensusRequest(BaseModel):
    router_report_relative_path: str

    mid_context_seconds: float = 24.0
    scene_scan_interval_seconds: float = 0.25
    min_scene_cut_score: float = 0.30
    max_mid_segment_seconds: float = 32.0

    promo_ocr_interval_seconds: float = 1.0
    promo_ocr_language: str = "eng"
    promo_ocr_min_confidence: float = 25.0
    promo_ocr_scale: float = 1.5
    promo_subtitle_exclusion_y_ratio: float = 0.76
    promo_large_text_height_ratio: float = 0.020
    promo_text_score_threshold: float = 0.48
    promo_group_gap_seconds: float = 2.25

    # v0.10.2: do not use the earliest isolated promo-looking text as the
    # onset. Build sustained promo episodes from multiple text groups.
    promo_episode_gap_seconds: float = 6.5
    promo_episode_min_samples: int = 3
    promo_episode_min_span_seconds: float = 4.0
    promo_episode_anchor_gap_seconds: float = 12.0
    promo_onset_cut_radius_seconds: float = 1.35
    promo_onset_max_cut_lead_seconds: float = 0.90

    end_card_backtrack_seconds: float = 3.0
    end_card_max_early_seconds: float = 1.75
    end_card_pre_cut_padding_seconds: float = 0.08


def _build_promo_episodes(
    groups,
    episode_gap_seconds,
):
    if not groups:
        return []

    ordered = sorted(
        groups,
        key=lambda x: float(x["start_seconds"]),
    )

    episodes = []
    current = [ordered[0]]

    for group in ordered[1:]:
        gap = (
            float(group["start_seconds"])
            - float(current[-1]["end_seconds"])
        )

        if gap <= float(episode_gap_seconds):
            current.append(group)
        else:
            episodes.append(current)
            current = [group]

    episodes.append(current)

    result = []

    for idx, episode_groups in enumerate(
        episodes,
        1,
    ):
        start = float(
            episode_groups[0]["start_seconds"]
        )
        end = float(
            episode_groups[-1]["end_seconds"]
        )

        sample_count = sum(
            int(g["sample_count"])
            for g in episode_groups
        )

        large_total = sum(
            int(g["large_text_total"])
            for g in episode_groups
        )

        weighted_score_num = sum(
            float(g["average_score"])
            * max(
                1,
                int(g["sample_count"]),
            )
            for g in episode_groups
        )
        weighted_score_den = sum(
            max(
                1,
                int(g["sample_count"]),
            )
            for g in episode_groups
        )

        average_score = (
            weighted_score_num
            / float(max(1, weighted_score_den))
        )

        peak_score = max(
            float(g["peak_score"])
            for g in episode_groups
        )

        result.append(
            {
                "episode_id": idx,
                "start_seconds": round(
                    start,
                    3,
                ),
                "end_seconds": round(
                    end,
                    3,
                ),
                "span_seconds": round(
                    max(0.0, end - start),
                    3,
                ),
                "group_count": len(
                    episode_groups
                ),
                "sample_count": sample_count,
                "large_text_total": large_total,
                "average_score": round(
                    average_score,
                    6,
                ),
                "peak_score": round(
                    peak_score,
                    6,
                ),
                "groups": episode_groups,
            }
        )

    return result


def _select_mid_promo_onset(
    groups,
    cut_scores,
    evidence_start,
    min_scene_cut_score,
    episode_gap_seconds=6.5,
    episode_min_samples=3,
    episode_min_span_seconds=4.0,
    episode_anchor_gap_seconds=12.0,
    onset_cut_radius_seconds=1.35,
    onset_max_cut_lead_seconds=0.90,
):
    if not groups:
        return None

    episodes = _build_promo_episodes(
        groups,
        float(episode_gap_seconds),
    )

    candidates = []

    for episode in episodes:
        start = float(
            episode["start_seconds"]
        )
        end = float(
            episode["end_seconds"]
        )

        if start > float(evidence_start) + 0.5:
            continue

        sample_count = int(
            episode["sample_count"]
        )
        span = float(
            episode["span_seconds"]
        )

        anchor_gap = max(
            0.0,
            float(evidence_start) - end,
        )

        sustained = (
            sample_count
            >= int(episode_min_samples)
            and span
            >= float(episode_min_span_seconds)
        )

        linked_to_anchor = (
            anchor_gap
            <= float(episode_anchor_gap_seconds)
        )

        # Isolated early text should not win just because it appears first.
        # A valid promo episode should either be sustained itself or reach
        # reasonably close to the known competitor-brand evidence.
        if not sustained:
            continue

        if not linked_to_anchor:
            continue

        nearby_cut = _nearest_cut_around(
            cut_scores,
            start,
            float(onset_cut_radius_seconds),
            float(min_scene_cut_score),
        )

        cut_score = (
            float(nearby_cut["cut_score"])
            if nearby_cut
            else 0.0
        )

        candidate_start = start

        if nearby_cut:
            cut_t = float(
                nearby_cut["time_seconds"]
            )

            # A visual cut may precede first OCR by a fraction of a second,
            # but it cannot drag the onset several seconds earlier.
            earliest_cut = (
                start
                - float(
                    onset_max_cut_lead_seconds
                )
            )

            if cut_t >= earliest_cut:
                candidate_start = cut_t

        # Favor sustained text regimes that lead naturally toward the known
        # ReelShort/competitor evidence. Proximity matters, but not so much
        # that we return to the old ~60s anchor.
        proximity = max(
            0.0,
            1.0
            - (
                anchor_gap
                / float(
                    max(
                        0.1,
                        episode_anchor_gap_seconds,
                    )
                )
            ),
        )

        episode_score = (
            float(
                episode["average_score"]
            )
            + min(
                0.85,
                sample_count * 0.10,
            )
            + min(
                0.65,
                span * 0.055,
            )
            + min(
                0.35,
                int(
                    episode["large_text_total"]
                ) * 0.018,
            )
            + 0.70 * proximity
            + 0.45 * cut_score
        )

        candidates.append(
            {
                "episode": episode,
                "nearby_cut": nearby_cut,
                "candidate_start_seconds": round(
                    float(candidate_start),
                    3,
                ),
                "anchor_gap_seconds": round(
                    anchor_gap,
                    3,
                ),
                "sustained": True,
                "linked_to_brand_anchor": True,
                "onset_score": round(
                    episode_score,
                    6,
                ),
            }
        )

    if not candidates:
        return {
            "candidate_start_seconds": None,
            "onset_score": None,
            "episodes": episodes,
            "eligible_episodes": [],
            "selection_reason": (
                "no_sustained_episode_linked_to_brand_anchor"
            ),
        }

    candidates.sort(
        key=lambda x: float(
            x["onset_score"]
        ),
        reverse=True,
    )

    best_score = float(
        candidates[0]["onset_score"]
    )

    # If multiple sustained episodes score almost equally, prefer the earlier
    # one, but only AFTER sustained/anchor-linked filtering. This avoids the
    # v0.10.1 mistake where 37s isolated text beat the real ~45s promo regime.
    near_best = [
        x
        for x in candidates
        if float(x["onset_score"])
        >= 0.90 * best_score
    ]

    near_best.sort(
        key=lambda x: float(
            x["candidate_start_seconds"]
        )
    )

    chosen = near_best[0]

    return {
        **chosen,
        "episodes": episodes,
        "eligible_episodes": candidates,
        "selection_reason": (
            "sustained_promo_episode_linked_to_brand_anchor"
        ),
    }




# ---------------------------------------------------------------------------
# v0.10.3 Optional Content Structure Router
# ---------------------------------------------------------------------------

# Keep the v0.10.2 replacement-plan implementation available as a base.
_replacement_plan_sync_v0102 = _replacement_plan_sync


class BrandingReplacementStructureRouteRequest(BaseModel):
    router_report_relative_path: str

    # Optional: reuse a segment-census report already generated with the
    # current detector. If omitted, Structure Router runs census itself.
    segment_census_report_relative_path: Optional[str] = None

    # Conservative presence gates. A candidate is not equivalent to "present".
    end_card_present_threshold: float = 0.70
    end_card_uncertain_threshold: float = 0.42

    mid_promo_present_threshold: float = 0.70
    mid_promo_uncertain_threshold: float = 0.45

    # If detection is uncertain, default behavior is preserve original content.
    preserve_uncertain_content: bool = True


class BrandingReplacementPlanRequest(BaseModel):
    router_report_relative_path: str
    profile_id: str

    # v0.10.3 preferred path.
    structure_report_relative_path: Optional[str] = None

    # Backward compatibility. If structure_report is absent, old census can
    # still be consumed directly.
    segment_census_report_relative_path: Optional[str] = None

    moving_flow_report_relative_path: Optional[str] = None
    moving_tracks_approved: bool = False

    # Default false: UNCERTAIN optional structures are not edited.
    include_uncertain_structures: bool = False


def _router_layers_of_type(router, layer_type):
    return [
        layer
        for layer in router.get("watermark_layers") or []
        if str(layer.get("type") or "") == str(layer_type)
    ]


def _structure_presence_label(
    score,
    present_threshold,
    uncertain_threshold,
):
    score = float(score)

    if score >= float(present_threshold):
        return "PRESENT"

    if score >= float(uncertain_threshold):
        return "UNCERTAIN"

    return "ABSENT"


def _end_card_structure_decision(
    router,
    segment,
    video_duration,
    present_threshold,
    uncertain_threshold,
):
    router_layers = _router_layers_of_type(
        router,
        "end_card",
    )

    signals = []
    score = 0.0

    if router_layers:
        best_conf = max(
            float(layer.get("confidence") or 0.0)
            for layer in router_layers
        )

        signals.append(
            {
                "signal": "router_end_card_layer",
                "present": True,
                "confidence": round(
                    best_conf,
                    6,
                ),
            }
        )

        score += 0.42
        score += min(
            0.23,
            0.23 * best_conf,
        )
    else:
        signals.append(
            {
                "signal": "router_end_card_layer",
                "present": False,
            }
        )

    if segment:
        start = float(
            segment.get("start_seconds")
            or 0.0
        )
        end = float(
            segment.get("end_seconds")
            or start
        )

        near_end = (
            video_duration <= 0
            or end >= max(
                0.0,
                float(video_duration) - 5.0,
            )
        )

        signals.append(
            {
                "signal": "near_end_segment_candidate",
                "present": bool(near_end),
                "start_seconds": round(
                    start,
                    3,
                ),
                "end_seconds": round(
                    end,
                    3,
                ),
            }
        )

        if near_end:
            score += 0.13

        refinement = (
            segment.get("start_refinement")
            or {}
        )

        source = str(
            refinement.get("chosen_source")
            or ""
        )

        structural_start = source in {
            "scene_cut_before_end_card",
            "mask_review_large_end_segment",
        }

        signals.append(
            {
                "signal": "structural_end_onset",
                "present": structural_start,
                "source": source or None,
            }
        )

        if structural_start:
            score += 0.14

        confidence = float(
            segment.get("confidence")
            or 0.0
        )

        if confidence >= 0.75:
            score += 0.08

    else:
        signals.append(
            {
                "signal": "near_end_segment_candidate",
                "present": False,
            }
        )
        signals.append(
            {
                "signal": "structural_end_onset",
                "present": False,
            }
        )

    score = min(
        1.0,
        score,
    )

    presence = _structure_presence_label(
        score,
        present_threshold,
        uncertain_threshold,
    )

    return {
        "structure_type": "end_card",
        "presence": presence,
        "confidence": round(
            score,
            6,
        ),
        "plan_eligible": (
            presence == "PRESENT"
        ),
        "candidate_segment": segment,
        "signals": signals,
        "decision_policy": (
            "No end-card replacement action is created unless the end-card "
            "presence gate passes. UNCERTAIN/ABSENT preserves original video."
        ),
    }


def _mid_promo_structure_decision(
    router,
    segment,
    present_threshold,
    uncertain_threshold,
):
    signals = []
    score = 0.0

    if not segment:
        return {
            "structure_type": "mid_promo",
            "presence": "ABSENT",
            "confidence": 0.0,
            "plan_eligible": False,
            "candidate_segment": None,
            "signals": [
                {
                    "signal": "mid_promo_candidate",
                    "present": False,
                }
            ],
            "decision_policy": (
                "No mid-promo candidate means no replacement action."
            ),
        }

    evidence_layer_id = segment.get(
        "evidence_layer_id"
    )

    evidence_layer = None
    for layer in router.get(
        "watermark_layers"
    ) or []:
        if (
            str(layer.get("layer_id"))
            == str(evidence_layer_id)
        ):
            evidence_layer = layer
            break

    has_brand_anchor = (
        evidence_layer is not None
        and str(
            evidence_layer.get("type")
            or ""
        )
        == "unclassified_brand_text"
    )

    signals.append(
        {
            "signal": "interior_competitor_brand_anchor",
            "present": bool(
                has_brand_anchor
            ),
            "evidence_layer_id": evidence_layer_id,
        }
    )

    if has_brand_anchor:
        score += 0.38

    start_source = str(
        segment.get("start_source")
        or ""
    )

    sustained = (
        start_source
        == "sustained_promotional_episode_onset"
    )

    signals.append(
        {
            "signal": "sustained_promotional_episode",
            "present": bool(
                sustained
            ),
            "start_source": start_source or None,
        }
    )

    if sustained:
        score += 0.26
    elif start_source in {
        "promotional_text_onset",
        "nearest_scene_cut_fallback",
    }:
        score += 0.08

    qualifies = bool(
        segment.get("qualifies_duration")
    )

    signals.append(
        {
            "signal": "bounded_candidate_duration",
            "present": qualifies,
            "duration_seconds": segment.get(
                "duration_seconds"
            ),
        }
    )

    if qualifies:
        score += 0.11

    selected = (
        segment.get("selected_onset")
        or {}
    )

    linked = bool(
        selected.get(
            "linked_to_brand_anchor"
        )
    )
    episode = (
        selected.get("episode")
        or {}
    )

    episode_samples = int(
        episode.get("sample_count")
        or 0
    )
    episode_span = float(
        episode.get("span_seconds")
        or 0.0
    )

    sustained_episode_evidence = (
        linked
        and episode_samples >= 3
        and episode_span >= 4.0
    )

    signals.append(
        {
            "signal": "episode_linked_to_brand_anchor",
            "present": bool(
                sustained_episode_evidence
            ),
            "episode_sample_count": episode_samples,
            "episode_span_seconds": round(
                episode_span,
                3,
            ),
        }
    )

    if sustained_episode_evidence:
        score += 0.15

    after_cut = segment.get(
        "after_cut"
    )

    has_end_boundary = (
        isinstance(after_cut, dict)
        and after_cut.get(
            "time_seconds"
        )
        is not None
    )

    signals.append(
        {
            "signal": "visual_end_boundary",
            "present": bool(
                has_end_boundary
            ),
        }
    )

    if has_end_boundary:
        score += 0.10

    score = min(
        1.0,
        score,
    )

    presence = _structure_presence_label(
        score,
        present_threshold,
        uncertain_threshold,
    )

    return {
        "structure_type": "mid_promo",
        "presence": presence,
        "confidence": round(
            score,
            6,
        ),
        "plan_eligible": (
            presence == "PRESENT"
        ),
        "candidate_segment": segment,
        "signals": signals,
        "decision_policy": (
            "Brand text alone never proves a Mid Promo. A replaceable promo "
            "requires sustained promotional structure plus bounded segment "
            "evidence. UNCERTAIN/ABSENT preserves original content."
        ),
    }


def _replacement_structure_route_sync(
    req: BrandingReplacementStructureRouteRequest
):
    router_path, router = _read_json_workspace(
        req.router_report_relative_path,
        "replacement_structure_route",
    )

    source_rel = (
        (router.get("source") or {})
        .get("relative_path")
    )

    if not source_rel:
        raise HTTPException(
            status_code=422,
            detail="Router report has no source path.",
        )

    video_path = _safe_workspace_path(
        source_rel
    )

    cap = cv2.VideoCapture(
        str(video_path)
    )
    if not cap.isOpened():
        raise HTTPException(
            status_code=422,
            detail="Could not open source video.",
        )
    try:
        meta = _video_metadata(cap)
    finally:
        cap.release()

    duration = float(
        meta.get("duration_seconds")
        or 0.0
    )

    census_path = None
    census = None

    if req.segment_census_report_relative_path:
        census_path, census = _read_json_workspace(
            req.segment_census_report_relative_path,
            "replacement_structure_route",
        )
    else:
        census_req = BrandingReplacementSegmentCensusRequest(
            router_report_relative_path=(
                req.router_report_relative_path
            )
        )

        census = _replacement_segment_census_sync(
            census_req
        )

        census_path = _safe_workspace_path(
            census["report_relative_path"]
        )

    census_segments = (
        census.get("segments")
        or []
    )

    end_segment = next(
        (
            seg
            for seg in census_segments
            if seg.get("type")
            == "end_card"
        ),
        None,
    )

    mid_segments = [
        seg
        for seg in census_segments
        if seg.get("type")
        == "mid_promo_candidate"
    ]

    end_decision = _end_card_structure_decision(
        router,
        end_segment,
        duration,
        float(
            req.end_card_present_threshold
        ),
        float(
            req.end_card_uncertain_threshold
        ),
    )

    mid_decisions = [
        _mid_promo_structure_decision(
            router,
            seg,
            float(
                req.mid_promo_present_threshold
            ),
            float(
                req.mid_promo_uncertain_threshold
            ),
        )
        for seg in mid_segments
    ]

    # If there were no mid candidates at all, make the absence explicit.
    if not mid_decisions:
        mid_decisions = [
            _mid_promo_structure_decision(
                router,
                None,
                float(
                    req.mid_promo_present_threshold
                ),
                float(
                    req.mid_promo_uncertain_threshold
                ),
            )
        ]

    eligible_segments = []

    if end_decision["presence"] == "PRESENT":
        if end_decision.get(
            "candidate_segment"
        ):
            eligible_segments.append(
                end_decision[
                    "candidate_segment"
                ]
            )

    for decision in mid_decisions:
        if (
            decision["presence"]
            == "PRESENT"
            and decision.get(
                "candidate_segment"
            )
        ):
            eligible_segments.append(
                decision[
                    "candidate_segment"
                ]
            )

    uncertain_structures = []

    if end_decision["presence"] == "UNCERTAIN":
        uncertain_structures.append(
            end_decision
        )

    uncertain_structures.extend(
        decision
        for decision in mid_decisions
        if decision["presence"]
        == "UNCERTAIN"
    )

    timestamp = _app_now().strftime(
        "%Y-%m-%d_%H%M%S"
    )

    out_dir = (
        WORKSPACE
        / "review"
        / "branding_replacement_structure_route"
        / timestamp
        / video_path.stem
    )
    out_dir.mkdir(
        parents=True,
        exist_ok=True,
    )

    result = {
        "ok": True,
        "version": "0.17.0",
        "mode": "branding_replacement_structure_route",
        "source": {
            "relative_path": source_rel,
            "router_report_relative_path": (
                router_path
                .relative_to(WORKSPACE)
                .as_posix()
            ),
            "segment_census_report_relative_path": (
                census_path
                .relative_to(WORKSPACE)
                .as_posix()
            ),
        },
        "video": meta,
        "summary": {
            "end_card_presence": (
                end_decision["presence"]
            ),
            "mid_promo_present_count": sum(
                1
                for x in mid_decisions
                if x["presence"]
                == "PRESENT"
            ),
            "mid_promo_uncertain_count": sum(
                1
                for x in mid_decisions
                if x["presence"]
                == "UNCERTAIN"
            ),
            "eligible_optional_segment_count": len(
                eligible_segments
            ),
            "uncertain_optional_structure_count": len(
                uncertain_structures
            ),
            "optional_structure_actions_required": bool(
                eligible_segments
            ),
            "source_video_modified": False,
        },
        "structure": {
            "end_card": end_decision,
            "mid_promos": mid_decisions,
        },
        "eligible_segments": eligible_segments,
        "uncertain_structures": uncertain_structures,
        "policy": {
            "core_rule": (
                "Detection order is PRESENCE -> BOUNDARY -> REPLACEMENT. "
                "Boundary detectors never imply that a structure exists."
            ),
            "absent": (
                "ABSENT means preserve original content and create no action."
            ),
            "uncertain": (
                "UNCERTAIN defaults to preserve original content. It can be "
                "surfaced for review but is not automatically edited."
            ),
            "present": (
                "Only PRESENT optional structures are eligible to enter the "
                "replacement plan."
            ),
        },
        "output_relative_dir": (
            out_dir
            .relative_to(WORKSPACE)
            .as_posix()
        ),
    }

    report_path = (
        out_dir
        / f"{video_path.stem}.replacement-structure-route.json"
    )

    result["report_relative_path"] = (
        report_path
        .relative_to(WORKSPACE)
        .as_posix()
    )

    report_path.write_text(
        json.dumps(
            result,
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )

    return result


def _segments_from_structure_report(
    structure_report,
    include_uncertain,
):
    segments = list(
        structure_report.get(
            "eligible_segments"
        )
        or []
    )

    if not include_uncertain:
        return segments

    for decision in (
        structure_report.get(
            "uncertain_structures"
        )
        or []
    ):
        segment = decision.get(
            "candidate_segment"
        )
        if segment:
            copied = dict(segment)
            copied[
                "_structure_presence"
            ] = "UNCERTAIN"
            segments.append(
                copied
            )

    return segments


def _replacement_plan_sync(
    req: BrandingReplacementPlanRequest
):
    # Backward compatibility:
    # if no Structure Router report is supplied, v0.10.2 behavior remains.
    if not req.structure_report_relative_path:
        return _replacement_plan_sync_v0102(
            req
        )

    structure_path, structure = _read_json_workspace(
        req.structure_report_relative_path,
        "replacement_plan",
    )

    if (
        structure.get("mode")
        != "branding_replacement_structure_route"
    ):
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "replacement_plan",
                "error": "wrong_structure_report_mode",
                "actual": structure.get(
                    "mode"
                ),
            },
        )

    structure_source = (
        (structure.get("source") or {})
        .get("relative_path")
    )

    router_path, router = _read_json_workspace(
        req.router_report_relative_path,
        "replacement_plan",
    )

    router_source = (
        (router.get("source") or {})
        .get("relative_path")
    )

    if (
        structure_source
        and router_source
        and str(structure_source)
        != str(router_source)
    ):
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "replacement_plan",
                "error": "structure_router_source_mismatch",
                "router_source": router_source,
                "structure_source": structure_source,
            },
        )

    segments = _segments_from_structure_report(
        structure,
        bool(
            req.include_uncertain_structures
        ),
    )

    # Reuse the existing mature plan builder by materializing ONLY the segments
    # that passed Structure Router presence gating.
    video_path = _safe_workspace_path(
        router_source
    )

    timestamp = _app_now().strftime(
        "%Y-%m-%d_%H%M%S"
    )

    derived_dir = (
        WORKSPACE
        / "review"
        / "branding_replacement_structure_route"
        / "derived_plan_segments"
        / timestamp
        / video_path.stem
    )

    derived_dir.mkdir(
        parents=True,
        exist_ok=True,
    )

    derived_path = (
        derived_dir
        / f"{video_path.stem}.structure-approved-segments.json"
    )

    derived_payload = {
        "ok": True,
        "version": "0.17.0",
        "mode": "branding_structure_approved_segments",
        "source": {
            "relative_path": router_source,
            "structure_report_relative_path": (
                structure_path
                .relative_to(WORKSPACE)
                .as_posix()
            ),
        },
        "segments": segments,
    }

    derived_path.write_text(
        json.dumps(
            derived_payload,
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )

    class _PlanShim:
        pass

    shim = _PlanShim()
    shim.router_report_relative_path = (
        req.router_report_relative_path
    )
    shim.profile_id = req.profile_id
    shim.segment_census_report_relative_path = (
        derived_path
        .relative_to(WORKSPACE)
        .as_posix()
    )
    shim.moving_flow_report_relative_path = (
        req.moving_flow_report_relative_path
    )
    shim.moving_tracks_approved = (
        req.moving_tracks_approved
    )

    result = _replacement_plan_sync_v0102(
        shim
    )

    result["version"] = "0.10.3"

    result.setdefault(
        "source",
        {},
    )[
        "structure_report_relative_path"
    ] = (
        structure_path
        .relative_to(WORKSPACE)
        .as_posix()
    )

    result.setdefault(
        "summary",
        {},
    )[
        "structure_gated_optional_segments"
    ] = len(
        segments
    )

    result["summary"][
        "uncertain_structures_included"
    ] = bool(
        req.include_uncertain_structures
    )

    result["structure_decisions"] = {
        "end_card": (
            (structure.get("structure") or {})
            .get("end_card")
        ),
        "mid_promos": (
            (structure.get("structure") or {})
            .get("mid_promos")
            or []
        ),
    }

    result["policy"] = {
        **(
            result.get("policy")
            or {}
        ),
        "optional_structures": (
            "v0.10.3 only creates end-card/mid-promo replacement actions "
            "after Structure Router presence gating."
        ),
    }

    report_rel = result.get(
        "report_relative_path"
    )

    if report_rel:
        report_path = _safe_workspace_path(
            report_rel
        )
        report_path.write_text(
            json.dumps(
                result,
                ensure_ascii=False,
                indent=2,
            ),
            encoding="utf-8",
        )

    return result




# ---------------------------------------------------------------------------
# v0.10.4 Anchor-connected Mid Promo Regime
#
# Architectural correction:
#   presence != boundary
#
# Mid Promo presence is validated independently. If present, its start is
# derived from the sustained promotional regime connected to the later brand
# anchor, not from the earliest promo-looking text anywhere in the lookback.
# ---------------------------------------------------------------------------

def _flatten_positive_promo_samples(groups):
    by_time = {}

    for group in groups or []:
        for sample in group.get("samples") or []:
            t = sample.get("time_seconds")
            if t is None:
                continue

            key = round(float(t), 3)

            prev = by_time.get(key)
            if (
                prev is None
                or float(sample.get("score") or 0.0)
                > float(prev.get("score") or 0.0)
            ):
                by_time[key] = sample

    return [
        by_time[t]
        for t in sorted(by_time)
    ]


def _positive_sample_runs(
    samples,
    max_positive_gap_seconds=2.75,
):
    if not samples:
        return []

    ordered = sorted(
        samples,
        key=lambda x: float(
            x["time_seconds"]
        ),
    )

    runs = []
    current = [ordered[0]]

    for sample in ordered[1:]:
        gap = (
            float(sample["time_seconds"])
            - float(
                current[-1]["time_seconds"]
            )
        )

        if gap <= float(
            max_positive_gap_seconds
        ):
            current.append(sample)
        else:
            runs.append(current)
            current = [sample]

    runs.append(current)

    result = []

    for idx, run in enumerate(runs, 1):
        start = float(
            run[0]["time_seconds"]
        )
        end = float(
            run[-1]["time_seconds"]
        )

        sample_count = len(run)
        span = max(
            0.0,
            end - start,
        )

        avg_score = float(
            np.mean(
                [
                    float(
                        x.get("score")
                        or 0.0
                    )
                    for x in run
                ]
            )
        )

        large_total = sum(
            int(
                x.get(
                    "large_text_count"
                )
                or 0
            )
            for x in run
        )

        result.append(
            {
                "run_id": idx,
                "start_seconds": round(
                    start,
                    3,
                ),
                "end_seconds": round(
                    end,
                    3,
                ),
                "span_seconds": round(
                    span,
                    3,
                ),
                "sample_count": sample_count,
                "average_score": round(
                    avg_score,
                    6,
                ),
                "large_text_total": (
                    large_total
                ),
                "samples": run,
            }
        )

    return result


def _run_is_sustained(run):
    sample_count = int(
        run.get("sample_count")
        or 0
    )
    span = float(
        run.get("span_seconds")
        or 0.0
    )
    avg_score = float(
        run.get("average_score")
        or 0.0
    )

    return bool(
        (
            sample_count >= 3
            and span >= 2.0
        )
        or (
            sample_count >= 4
            and avg_score >= 0.60
        )
    )


def _build_anchor_connected_regimes(
    runs,
    evidence_start,
    anchor_max_gap_seconds=12.0,
    regime_bridge_gap_seconds=3.75,
):
    sustained = [
        run
        for run in runs
        if _run_is_sustained(run)
    ]

    if not sustained:
        return []

    # Only runs at or before the known competitor-brand evidence participate.
    sustained = [
        run
        for run in sustained
        if float(
            run["start_seconds"]
        )
        <= float(evidence_start) + 0.5
    ]

    if not sustained:
        return []

    # A regime must eventually reach reasonably close to the brand anchor.
    anchor_linked_indices = [
        idx
        for idx, run
        in enumerate(sustained)
        if (
            float(evidence_start)
            - float(
                run["end_seconds"]
            )
        )
        <= float(
            anchor_max_gap_seconds
        )
    ]

    if not anchor_linked_indices:
        return []

    regimes = []

    # Build backwards from every anchor-linked sustained run. Expansion is
    # deliberately conservative: an earlier run joins only if the silent gap
    # between sustained runs is short. This prevents a 37s isolated title from
    # being chained to a genuine ~45s promo block merely because both live in
    # the same 24s lookback window.
    for anchor_idx in anchor_linked_indices:
        chain = [
            sustained[anchor_idx]
        ]

        cursor = anchor_idx - 1

        while cursor >= 0:
            prev = sustained[cursor]
            first = chain[0]

            gap = (
                float(
                    first["start_seconds"]
                )
                - float(
                    prev["end_seconds"]
                )
            )

            if gap > float(
                regime_bridge_gap_seconds
            ):
                break

            chain.insert(
                0,
                prev,
            )
            cursor -= 1

        start = float(
            chain[0]["start_seconds"]
        )
        end = float(
            chain[-1]["end_seconds"]
        )
        span = max(
            0.0,
            end - start,
        )
        sample_count = sum(
            int(
                run["sample_count"]
            )
            for run in chain
        )
        avg_score = float(
            np.average(
                [
                    float(
                        run["average_score"]
                    )
                    for run in chain
                ],
                weights=[
                    max(
                        1,
                        int(
                            run[
                                "sample_count"
                            ]
                        ),
                    )
                    for run in chain
                ],
            )
        )
        anchor_gap = max(
            0.0,
            float(evidence_start) - end,
        )

        regimes.append(
            {
                "start_seconds": round(
                    start,
                    3,
                ),
                "end_seconds": round(
                    end,
                    3,
                ),
                "span_seconds": round(
                    span,
                    3,
                ),
                "sample_count": (
                    sample_count
                ),
                "run_count": len(
                    chain
                ),
                "average_score": round(
                    avg_score,
                    6,
                ),
                "anchor_gap_seconds": round(
                    anchor_gap,
                    3,
                ),
                "anchor_connected": True,
                "runs": chain,
            }
        )

    # Deduplicate equivalent chains.
    unique = {}
    for regime in regimes:
        key = (
            regime["start_seconds"],
            regime["end_seconds"],
        )
        previous = unique.get(key)

        if (
            previous is None
            or int(
                regime["sample_count"]
            )
            > int(
                previous[
                    "sample_count"
                ]
            )
        ):
            unique[key] = regime

    return list(
        unique.values()
    )


def _select_mid_promo_onset(
    groups,
    cut_scores,
    evidence_start,
    min_scene_cut_score,
    episode_gap_seconds=6.5,
    episode_min_samples=3,
    episode_min_span_seconds=4.0,
    episode_anchor_gap_seconds=12.0,
    onset_cut_radius_seconds=1.35,
    onset_max_cut_lead_seconds=0.90,
):
    samples = (
        _flatten_positive_promo_samples(
            groups
        )
    )

    runs = _positive_sample_runs(
        samples,
        max_positive_gap_seconds=2.75,
    )

    regimes = (
        _build_anchor_connected_regimes(
            runs,
            float(evidence_start),
            anchor_max_gap_seconds=min(
                12.0,
                float(
                    episode_anchor_gap_seconds
                ),
            ),
            regime_bridge_gap_seconds=3.75,
        )
    )

    eligible = []

    for regime in regimes:
        span = float(
            regime["span_seconds"]
        )
        sample_count = int(
            regime["sample_count"]
        )

        # The structure must be genuinely sustained. This is deliberately
        # independent of how far back the general OCR lookback window extends.
        if (
            sample_count < 4
            or span < 4.0
        ):
            continue

        start = float(
            regime["start_seconds"]
        )

        nearby_cut = (
            _nearest_cut_around(
                cut_scores,
                start,
                float(
                    onset_cut_radius_seconds
                ),
                float(
                    min_scene_cut_score
                ),
            )
        )

        candidate_start = start
        cut_score = 0.0

        if nearby_cut:
            cut_t = float(
                nearby_cut[
                    "time_seconds"
                ]
            )
            cut_score = float(
                nearby_cut[
                    "cut_score"
                ]
            )

            # Scene cuts can refine the onset by less than ~1s. They cannot
            # create an earlier promo start by themselves.
            earliest = (
                start
                - float(
                    onset_max_cut_lead_seconds
                )
            )

            if cut_t >= earliest:
                candidate_start = (
                    cut_t
                )

        anchor_gap = float(
            regime[
                "anchor_gap_seconds"
            ]
        )

        proximity = max(
            0.0,
            1.0
            - (
                anchor_gap
                / max(
                    0.1,
                    min(
                        12.0,
                        float(
                            episode_anchor_gap_seconds
                        ),
                    ),
                )
            ),
        )

        score = (
            0.36
            + min(
                0.24,
                sample_count * 0.025,
            )
            + min(
                0.16,
                span * 0.012,
            )
            + min(
                0.10,
                float(
                    regime[
                        "average_score"
                    ]
                ) * 0.08,
            )
            + 0.09 * proximity
            + min(
                0.05,
                cut_score * 0.05,
            )
        )

        eligible.append(
            {
                "candidate_start_seconds": round(
                    candidate_start,
                    3,
                ),
                "onset_score": round(
                    min(
                        0.95,
                        score,
                    ),
                    6,
                ),
                "boundary_confidence": round(
                    min(
                        0.95,
                        score,
                    ),
                    6,
                ),
                "anchor_connected": True,
                "linked_to_brand_anchor": True,
                "regime": regime,
                # Keep legacy field for structure-router compatibility.
                "episode": {
                    "start_seconds": (
                        regime[
                            "start_seconds"
                        ]
                    ),
                    "end_seconds": (
                        regime[
                            "end_seconds"
                        ]
                    ),
                    "span_seconds": (
                        regime[
                            "span_seconds"
                        ]
                    ),
                    "sample_count": (
                        regime[
                            "sample_count"
                        ]
                    ),
                    "average_score": (
                        regime[
                            "average_score"
                        ]
                    ),
                },
                "nearby_cut": nearby_cut,
                "selection_reason": (
                    "anchor_connected_sustained_promotional_regime"
                ),
            }
        )

    if not eligible:
        return {
            "candidate_start_seconds": None,
            "onset_score": 0.0,
            "boundary_confidence": 0.0,
            "anchor_connected": False,
            "linked_to_brand_anchor": False,
            "runs": runs,
            "regimes": regimes,
            "eligible_regimes": [],
            "selection_reason": (
                "no_anchor_connected_sustained_promotional_regime"
            ),
        }

    # Prefer the best structural regime, not the earliest timestamp.
    eligible.sort(
        key=lambda x: (
            float(
                x[
                    "boundary_confidence"
                ]
            ),
            float(
                x["regime"][
                    "span_seconds"
                ]
            ),
            int(
                x["regime"][
                    "sample_count"
                ]
            ),
        ),
        reverse=True,
    )

    best = eligible[0]

    return {
        **best,
        "runs": runs,
        "regimes": regimes,
        "eligible_regimes": eligible,
    }


def _mid_promo_structure_decision(
    router,
    segment,
    present_threshold,
    uncertain_threshold,
):
    if not segment:
        return {
            "structure_type": "mid_promo",
            "presence": "ABSENT",
            "confidence": 0.0,
            "presence_confidence": 0.0,
            "boundary_confidence": 0.0,
            "plan_eligible": False,
            "candidate_segment": None,
            "signals": [
                {
                    "signal": "mid_promo_candidate",
                    "present": False,
                }
            ],
            "decision_policy": (
                "No candidate means no Mid Promo replacement."
            ),
        }

    evidence_layer_id = (
        segment.get(
            "evidence_layer_id"
        )
    )

    evidence_layer = None

    for layer in (
        router.get(
            "watermark_layers"
        )
        or []
    ):
        if (
            str(
                layer.get(
                    "layer_id"
                )
            )
            == str(
                evidence_layer_id
            )
        ):
            evidence_layer = layer
            break

    has_brand_anchor = bool(
        evidence_layer is not None
        and str(
            evidence_layer.get(
                "type"
            )
            or ""
        )
        == "unclassified_brand_text"
    )

    selected = (
        segment.get(
            "selected_onset"
        )
        or {}
    )

    anchor_connected = bool(
        selected.get(
            "anchor_connected"
        )
        or selected.get(
            "linked_to_brand_anchor"
        )
    )

    regime = (
        selected.get("regime")
        or selected.get("episode")
        or {}
    )

    regime_samples = int(
        regime.get(
            "sample_count"
        )
        or 0
    )
    regime_span = float(
        regime.get(
            "span_seconds"
        )
        or 0.0
    )

    sustained_regime = bool(
        anchor_connected
        and regime_samples >= 4
        and regime_span >= 4.0
    )

    qualifies_duration = bool(
        segment.get(
            "qualifies_duration"
        )
    )

    has_end_boundary = bool(
        isinstance(
            segment.get(
                "after_cut"
            ),
            dict,
        )
        and segment[
            "after_cut"
        ].get(
            "time_seconds"
        )
        is not None
    )

    # PRESENCE confidence and BOUNDARY confidence are intentionally separate.
    presence_score = 0.0

    if has_brand_anchor:
        presence_score += 0.34

    if sustained_regime:
        presence_score += 0.36

    if qualifies_duration:
        presence_score += 0.10

    if has_end_boundary:
        presence_score += 0.10

    # Reserve the final 0.10 for a clean anchor connection + reasonable regime.
    if (
        anchor_connected
        and regime_samples >= 5
    ):
        presence_score += 0.08

    presence_score = min(
        0.95,
        presence_score,
    )

    boundary_confidence = float(
        selected.get(
            "boundary_confidence"
        )
        or 0.0
    )

    # If no real anchor-connected regime exists, do not call it PRESENT even
    # when a brand word happens to appear inside normal story content.
    if not sustained_regime:
        presence = (
            "UNCERTAIN"
            if has_brand_anchor
            else "ABSENT"
        )
    else:
        presence = (
            _structure_presence_label(
                presence_score,
                present_threshold,
                uncertain_threshold,
            )
        )

    # A PRESENT structure with a poor boundary is still REVIEW, not eligible
    # for automatic replacement.
    plan_eligible = bool(
        presence == "PRESENT"
        and boundary_confidence >= 0.58
    )

    signals = [
        {
            "signal": (
                "interior_competitor_brand_anchor"
            ),
            "present": has_brand_anchor,
            "evidence_layer_id": (
                evidence_layer_id
            ),
        },
        {
            "signal": (
                "anchor_connected_sustained_regime"
            ),
            "present": sustained_regime,
            "regime_sample_count": (
                regime_samples
            ),
            "regime_span_seconds": round(
                regime_span,
                3,
            ),
        },
        {
            "signal": (
                "bounded_candidate_duration"
            ),
            "present": (
                qualifies_duration
            ),
            "duration_seconds": (
                segment.get(
                    "duration_seconds"
                )
            ),
        },
        {
            "signal": (
                "visual_end_boundary"
            ),
            "present": (
                has_end_boundary
            ),
        },
    ]

    return {
        "structure_type": "mid_promo",
        "presence": presence,
        # Backward-compatible "confidence" now means presence confidence.
        "confidence": round(
            presence_score,
            6,
        ),
        "presence_confidence": round(
            presence_score,
            6,
        ),
        "boundary_confidence": round(
            boundary_confidence,
            6,
        ),
        "plan_eligible": (
            plan_eligible
        ),
        "candidate_segment": (
            segment
        ),
        "signals": signals,
        "decision_policy": (
            "Presence and boundary are separate. Brand OCR alone never proves "
            "Mid Promo. A PRESENT Mid Promo requires an anchor-connected "
            "sustained promotional regime. Replacement eligibility additionally "
            "requires a sufficiently reliable boundary."
        ),
    }


# Structure Router v0.10.3 originally added every PRESENT candidate to
# eligible_segments. v0.10.4 honors plan_eligible as well.
_replacement_structure_route_sync_v0103 = (
    _replacement_structure_route_sync
)


def _replacement_structure_route_sync(
    req: BrandingReplacementStructureRouteRequest
):
    result = (
        _replacement_structure_route_sync_v0103(
            req
        )
    )

    structure = (
        result.get("structure")
        or {}
    )

    end_decision = (
        structure.get("end_card")
        or {}
    )

    mid_decisions = (
        structure.get("mid_promos")
        or []
    )

    eligible = []

    if (
        end_decision.get(
            "presence"
        )
        == "PRESENT"
        and end_decision.get(
            "plan_eligible",
            True,
        )
        and end_decision.get(
            "candidate_segment"
        )
    ):
        eligible.append(
            end_decision[
                "candidate_segment"
            ]
        )

    for decision in mid_decisions:
        if (
            decision.get(
                "presence"
            )
            == "PRESENT"
            and decision.get(
                "plan_eligible"
            )
            and decision.get(
                "candidate_segment"
            )
        ):
            eligible.append(
                decision[
                    "candidate_segment"
                ]
            )

    result["version"] = "0.10.4"
    result["eligible_segments"] = (
        eligible
    )

    summary = result.setdefault(
        "summary",
        {},
    )

    summary[
        "eligible_optional_segment_count"
    ] = len(
        eligible
    )
    summary[
        "optional_structure_actions_required"
    ] = bool(
        eligible
    )

    summary[
        "mid_promo_present_count"
    ] = sum(
        1
        for x in mid_decisions
        if x.get(
            "presence"
        )
        == "PRESENT"
    )

    summary[
        "mid_promo_boundary_ready_count"
    ] = sum(
        1
        for x in mid_decisions
        if (
            x.get(
                "presence"
            )
            == "PRESENT"
            and x.get(
                "plan_eligible"
            )
        )
    )

    result["policy"] = {
        **(
            result.get(
                "policy"
            )
            or {}
        ),
        "mid_promo_boundary": (
            "A Mid Promo may be PRESENT while its boundary remains unready. "
            "Only PRESENT + boundary-ready segments enter eligible_segments."
        ),
    }

    # Carry the acquisition-bound source identity and verified dynamic tracks
    # into the plan.  The render stage can then invoke the visual detector with
    # the correct product icon/logo instead of falling back to a hard-coded
    # ReelShort reference.
    try:
        router_evidence = (router.get("evidence_reports") or {})
        census_rel = str(router_evidence.get("census") or "").strip()
        if census_rel:
            _, census = _read_json_workspace(census_rel, "replacement_plan")
            identity = census.get("source_identity") or {}
            result.setdefault("source", {})["source_identity"] = identity
            strict = census.get("verified_dynamic_identity") or {}
            dynamic_tracks = list(strict.get("tracks") or []) if bool(strict.get("enabled")) else []
            result.setdefault("summary", {})["operator_dynamic_brand_expected_track_count"] = len(dynamic_tracks)
            result.setdefault("summary", {})["operator_dynamic_brand_track_sources"] = {
                str(track.get("track_id") or index): str(track.get("handler") or "")
                for index, track in enumerate(dynamic_tracks, 1)
            }
    except Exception:
        # Missing diagnostics are handled by the render preflight; do not make
        # plan generation fail merely because an optional census was removed.
        pass

    report_rel = (
        result.get(
            "report_relative_path"
        )
    )

    if report_rel:
        report_path = (
            _safe_workspace_path(
                report_rel
            )
        )
        report_path.write_text(
            json.dumps(
                result,
                ensure_ascii=False,
                indent=2,
            ),
            encoding="utf-8",
        )

    return result




# ---------------------------------------------------------------------------
# v0.10.5 Multimodal Structure Boundary Detector
#
# Principle:
#   Brand OCR confirms WHAT the block may be.
#   Multimodal regime change decides WHERE the block begins/ends.
#
# Modalities:
#   1) visual composition / color / edge regime
#   2) subtitle-layout regime, including persistent white subtitle background
#   3) audio regime (energy + spectral/timbre proxy)
#
# A boundary is strong when >=2 modalities change together and the new regime
# persists for several seconds. This is intended to catch transitions such as:
#
#   story
#   -> promo layout with white subtitle box + different voice
#   -> story / end card
#
# without hard-coding timestamps.
# ---------------------------------------------------------------------------

class BrandingReplacementSegmentCensusRequest(BaseModel):
    router_report_relative_path: str

    mid_context_seconds: float = 28.0
    scene_scan_interval_seconds: float = 0.25
    min_scene_cut_score: float = 0.30
    max_mid_segment_seconds: float = 40.0

    promo_ocr_interval_seconds: float = 1.0
    promo_ocr_language: str = "eng"
    promo_ocr_min_confidence: float = 25.0
    promo_ocr_scale: float = 1.5
    promo_subtitle_exclusion_y_ratio: float = 0.76
    promo_large_text_height_ratio: float = 0.020
    promo_text_score_threshold: float = 0.48
    promo_group_gap_seconds: float = 2.25

    promo_episode_gap_seconds: float = 6.5
    promo_episode_min_samples: int = 3
    promo_episode_min_span_seconds: float = 4.0
    promo_episode_anchor_gap_seconds: float = 14.0
    promo_onset_cut_radius_seconds: float = 1.35
    promo_onset_max_cut_lead_seconds: float = 0.90

    # Multimodal regime analysis.
    multimodal_sample_interval_seconds: float = 0.50
    multimodal_context_seconds: float = 30.0
    multimodal_min_persistence_seconds: float = 4.0
    multimodal_min_modalities: int = 2
    multimodal_boundary_score_threshold: float = 0.58
    multimodal_search_tail_seconds: float = 8.0

    # Subtitle-layout detector: lower-middle band, not only the extreme bottom.
    subtitle_band_y0_ratio: float = 0.52
    subtitle_band_y1_ratio: float = 0.90
    subtitle_white_min_value: int = 210
    subtitle_white_max_saturation: int = 55

    # Audio analysis uses ffmpeg PCM + numpy only; no new Python dependency.
    audio_window_seconds: float = 1.0
    audio_sample_rate: int = 16000

    end_card_backtrack_seconds: float = 5.0
    end_card_max_early_seconds: float = 3.0
    end_card_pre_cut_padding_seconds: float = 0.08


def _cosine_distance(a, b):
    a = np.asarray(a, dtype=np.float32).reshape(-1)
    b = np.asarray(b, dtype=np.float32).reshape(-1)

    na = float(np.linalg.norm(a))
    nb = float(np.linalg.norm(b))

    if na <= 1e-8 or nb <= 1e-8:
        return 0.0

    sim = float(
        np.dot(a, b)
        / (na * nb)
    )

    sim = max(
        -1.0,
        min(
            1.0,
            sim,
        ),
    )

    return float(
        (1.0 - sim) / 2.0
    )


def _visual_regime_features(frame, req):
    h, w = frame.shape[:2]

    small = cv2.resize(
        frame,
        (96, 160),
        interpolation=cv2.INTER_AREA,
    )

    hsv = cv2.cvtColor(
        small,
        cv2.COLOR_BGR2HSV,
    )

    hist_h = cv2.calcHist(
        [hsv],
        [0],
        None,
        [18],
        [0, 180],
    ).reshape(-1)

    hist_s = cv2.calcHist(
        [hsv],
        [1],
        None,
        [8],
        [0, 256],
    ).reshape(-1)

    hist_v = cv2.calcHist(
        [hsv],
        [2],
        None,
        [8],
        [0, 256],
    ).reshape(-1)

    hist = np.concatenate(
        [
            hist_h,
            hist_s,
            hist_v,
        ]
    ).astype(np.float32)

    hist /= max(
        1e-8,
        float(
            hist.sum()
        ),
    )

    gray = cv2.cvtColor(
        small,
        cv2.COLOR_BGR2GRAY,
    )

    edges = cv2.Canny(
        gray,
        80,
        160,
    )

    edge_density = float(
        np.mean(
            edges > 0
        )
    )

    y0 = int(
        round(
            max(
                0.0,
                min(
                    1.0,
                    float(
                        req.subtitle_band_y0_ratio
                    ),
                ),
            )
            * h
        )
    )

    y1 = int(
        round(
            max(
                0.0,
                min(
                    1.0,
                    float(
                        req.subtitle_band_y1_ratio
                    ),
                ),
            )
            * h
        )
    )

    if y1 <= y0:
        y0 = int(
            round(
                0.52 * h
            )
        )
        y1 = int(
            round(
                0.90 * h
            )
        )

    band = frame[
        y0:y1,
        :,
    ]

    if band.size:
        band_hsv = cv2.cvtColor(
            band,
            cv2.COLOR_BGR2HSV,
        )

        white_mask = (
            (
                band_hsv[:, :, 2]
                >= int(
                    req.subtitle_white_min_value
                )
            )
            &
            (
                band_hsv[:, :, 1]
                <= int(
                    req.subtitle_white_max_saturation
                )
            )
        ).astype(np.uint8)

        # Large connected white components are more indicative of subtitle
        # plates/cards than scattered bright pixels in the scene.
        n, labels, stats, _ = (
            cv2.connectedComponentsWithStats(
                white_mask,
                8,
            )
        )

        large_white_area = 0

        min_component_area = max(
            80,
            int(
                round(
                    band.shape[0]
                    * band.shape[1]
                    * 0.004
                )
            ),
        )

        large_components = 0

        for idx in range(
            1,
            n,
        ):
            area = int(
                stats[
                    idx,
                    cv2.CC_STAT_AREA,
                ]
            )

            if area >= min_component_area:
                large_white_area += area
                large_components += 1

        white_plate_ratio = (
            float(
                large_white_area
            )
            / float(
                max(
                    1,
                    band.shape[0]
                    * band.shape[1],
                )
            )
        )
    else:
        white_plate_ratio = 0.0
        large_components = 0

    return {
        "hist": hist.tolist(),
        "edge_density": edge_density,
        "subtitle_white_plate_ratio": (
            white_plate_ratio
        ),
        "subtitle_white_component_count": (
            int(
                large_components
            )
        ),
    }


def _extract_audio_pcm(
    video_path,
    start_seconds,
    end_seconds,
    sample_rate,
):
    duration = max(
        0.0,
        float(end_seconds)
        - float(start_seconds),
    )

    if duration <= 0.0:
        return np.zeros(
            0,
            dtype=np.float32,
        )

    cmd = [
        "/usr/bin/ffmpeg",
        "-hide_banner",
        "-loglevel",
        "error",
        "-ss",
        f"{float(start_seconds):.3f}",
        "-t",
        f"{duration:.3f}",
        "-i",
        str(video_path),
        "-vn",
        "-ac",
        "1",
        "-ar",
        str(int(sample_rate)),
        "-f",
        "f32le",
        "pipe:1",
    ]

    try:
        proc = subprocess.run(
            cmd,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            check=False,
        )
    except Exception:
        return np.zeros(
            0,
            dtype=np.float32,
        )

    if proc.returncode != 0:
        return np.zeros(
            0,
            dtype=np.float32,
        )

    try:
        return np.frombuffer(
            proc.stdout,
            dtype=np.float32,
        ).copy()
    except Exception:
        return np.zeros(
            0,
            dtype=np.float32,
        )


def _audio_window_features(samples, sample_rate):
    samples = np.asarray(
        samples,
        dtype=np.float32,
    )

    if samples.size < 64:
        return {
            "rms": 0.0,
            "zcr": 0.0,
            "spectral_centroid": 0.0,
            "spectral_flatness": 0.0,
            "spectral_band_ratio_low": 0.0,
            "spectral_band_ratio_high": 0.0,
        }

    samples = samples - float(
        np.mean(
            samples
        )
    )

    rms = float(
        np.sqrt(
            np.mean(
                samples * samples
            )
            + 1e-12
        )
    )

    signs = (
        samples >= 0
    ).astype(
        np.int8
    )

    zcr = float(
        np.mean(
            signs[1:]
            != signs[:-1]
        )
    )

    n_fft = 2048

    if samples.size < n_fft:
        padded = np.zeros(
            n_fft,
            dtype=np.float32,
        )
        padded[
            : samples.size
        ] = samples
        x = padded
    else:
        center = samples.size // 2
        half = n_fft // 2
        lo = max(
            0,
            center - half,
        )
        hi = min(
            samples.size,
            lo + n_fft,
        )
        x = samples[
            lo:hi
        ]
        if x.size < n_fft:
            x = np.pad(
                x,
                (
                    0,
                    n_fft - x.size,
                ),
            )

    window = np.hanning(
        n_fft
    ).astype(
        np.float32
    )

    spectrum = np.abs(
        np.fft.rfft(
            x * window
        )
    ).astype(
        np.float32
    )

    spectrum += 1e-8

    freqs = np.fft.rfftfreq(
        n_fft,
        1.0
        / float(
            sample_rate
        ),
    )

    total = float(
        spectrum.sum()
    )

    centroid = float(
        np.sum(
            freqs
            * spectrum
        )
        / max(
            1e-8,
            total,
        )
    )

    flatness = float(
        np.exp(
            np.mean(
                np.log(
                    spectrum
                )
            )
        )
        / max(
            1e-8,
            float(
                np.mean(
                    spectrum
                )
            ),
        )
    )

    low = float(
        spectrum[
            freqs < 1200
        ].sum()
    )

    high = float(
        spectrum[
            freqs >= 3000
        ].sum()
    )

    return {
        "rms": rms,
        "zcr": zcr,
        "spectral_centroid": (
            centroid
            / max(
                1.0,
                float(
                    sample_rate
                    / 2.0
                ),
            )
        ),
        "spectral_flatness": flatness,
        "spectral_band_ratio_low": (
            low
            / max(
                1e-8,
                total,
            )
        ),
        "spectral_band_ratio_high": (
            high
            / max(
                1e-8,
                total,
            )
        ),
    }


def _multimodal_feature_timeline(
    video_path,
    start_seconds,
    end_seconds,
    req,
):
    interval = max(
        0.25,
        float(
            req.multimodal_sample_interval_seconds
        ),
    )

    sample_rate = int(
        req.audio_sample_rate
    )

    audio = _extract_audio_pcm(
        video_path,
        start_seconds,
        end_seconds,
        sample_rate,
    )

    cap = cv2.VideoCapture(
        str(video_path)
    )

    if not cap.isOpened():
        raise HTTPException(
            status_code=422,
            detail=(
                "Could not open video for multimodal analysis."
            ),
        )

    timeline = []
    t = float(
        start_seconds
    )

    audio_origin = float(
        start_seconds
    )

    audio_window = max(
        interval,
        float(
            req.audio_window_seconds
        ),
    )

    try:
        while (
            t
            <= float(
                end_seconds
            )
            + 1e-9
        ):
            cap.set(
                cv2.CAP_PROP_POS_MSEC,
                t * 1000.0,
            )

            ok, frame = cap.read()

            if (
                not ok
                or frame is None
            ):
                t += interval
                continue

            visual = (
                _visual_regime_features(
                    frame,
                    req,
                )
            )

            a0 = max(
                0,
                int(
                    round(
                        (
                            t
                            - audio_origin
                            - audio_window / 2.0
                        )
                        * sample_rate
                    )
                ),
            )

            a1 = min(
                audio.size,
                int(
                    round(
                        (
                            t
                            - audio_origin
                            + audio_window / 2.0
                        )
                        * sample_rate
                    )
                ),
            )

            if a1 > a0:
                audio_features = (
                    _audio_window_features(
                        audio[
                            a0:a1
                        ],
                        sample_rate,
                    )
                )
            else:
                audio_features = (
                    _audio_window_features(
                        np.zeros(
                            0,
                            dtype=np.float32,
                        ),
                        sample_rate,
                    )
                )

            timeline.append(
                {
                    "time_seconds": round(
                        t,
                        3,
                    ),
                    "visual": visual,
                    "audio": audio_features,
                }
            )

            t += interval

    finally:
        cap.release()

    return timeline


def _mean_feature_vector(
    items,
    key_path,
):
    vectors = []

    for item in items:
        obj = item

        for key in key_path:
            obj = (
                obj.get(key)
                if isinstance(
                    obj,
                    dict,
                )
                else None
            )

        if obj is None:
            continue

        vectors.append(
            np.asarray(
                obj,
                dtype=np.float32,
            )
        )

    if not vectors:
        return None

    return np.mean(
        np.stack(
            vectors,
            axis=0,
        ),
        axis=0,
    )


def _mean_scalar(
    items,
    *keys,
):
    values = []

    for item in items:
        obj = item

        for key in keys:
            obj = (
                obj.get(key)
                if isinstance(
                    obj,
                    dict,
                )
                else None
            )

        if obj is not None:
            values.append(
                float(obj)
            )

    if not values:
        return 0.0

    return float(
        np.mean(
            values
        )
    )


def _audio_vector(item):
    audio = item.get(
        "audio"
    ) or {}

    return np.asarray(
        [
            math.log1p(
                60.0
                * float(
                    audio.get("rms")
                    or 0.0
                )
            ),
            float(
                audio.get("zcr")
                or 0.0
            ),
            float(
                audio.get(
                    "spectral_centroid"
                )
                or 0.0
            ),
            float(
                audio.get(
                    "spectral_flatness"
                )
                or 0.0
            ),
            float(
                audio.get(
                    "spectral_band_ratio_low"
                )
                or 0.0
            ),
            float(
                audio.get(
                    "spectral_band_ratio_high"
                )
                or 0.0
            ),
        ],
        dtype=np.float32,
    )


def _window_audio_mean(items):
    if not items:
        return np.zeros(
            6,
            dtype=np.float32,
        )

    return np.mean(
        np.stack(
            [
                _audio_vector(
                    item
                )
                for item in items
            ],
            axis=0,
        ),
        axis=0,
    )


def _multimodal_boundary_candidates(
    timeline,
    req,
):
    if len(timeline) < 8:
        return []

    interval = max(
        0.25,
        float(
            req.multimodal_sample_interval_seconds
        ),
    )

    # Compare several seconds before and after each point. This detects regime
    # change, not just a single hard cut.
    half_window_seconds = max(
        2.0,
        min(
            4.0,
            float(
                req.multimodal_min_persistence_seconds
            )
            * 0.75,
        ),
    )

    half_n = max(
        3,
        int(
            round(
                half_window_seconds
                / interval
            )
        ),
    )

    candidates = []

    for i in range(
        half_n,
        len(timeline)
        - half_n,
    ):
        before = timeline[
            i - half_n:i
        ]

        after = timeline[
            i:i + half_n
        ]

        hist_before = (
            _mean_feature_vector(
                before,
                (
                    "visual",
                    "hist",
                ),
            )
        )
        hist_after = (
            _mean_feature_vector(
                after,
                (
                    "visual",
                    "hist",
                ),
            )
        )

        visual_hist_delta = (
            _cosine_distance(
                hist_before,
                hist_after,
            )
            if (
                hist_before
                is not None
                and hist_after
                is not None
            )
            else 0.0
        )

        edge_before = _mean_scalar(
            before,
            "visual",
            "edge_density",
        )
        edge_after = _mean_scalar(
            after,
            "visual",
            "edge_density",
        )

        edge_delta = min(
            1.0,
            abs(
                edge_after
                - edge_before
            )
            / 0.10,
        )

        white_before = _mean_scalar(
            before,
            "visual",
            "subtitle_white_plate_ratio",
        )
        white_after = _mean_scalar(
            after,
            "visual",
            "subtitle_white_plate_ratio",
        )

        subtitle_delta = min(
            1.0,
            abs(
                white_after
                - white_before
            )
            / 0.08,
        )

        audio_before = (
            _window_audio_mean(
                before
            )
        )
        audio_after = (
            _window_audio_mean(
                after
            )
        )

        # Normalize by hand-set scales so this remains dependency-free.
        scales = np.asarray(
            [
                0.35,
                0.07,
                0.18,
                0.20,
                0.22,
                0.18,
            ],
            dtype=np.float32,
        )

        audio_delta = float(
            np.mean(
                np.minimum(
                    1.0,
                    np.abs(
                        audio_after
                        - audio_before
                    )
                    / scales,
                )
            )
        )

        visual_score = min(
            1.0,
            0.72
            * visual_hist_delta
            + 0.28
            * edge_delta,
        )

        subtitle_score = (
            subtitle_delta
        )

        audio_score = min(
            1.0,
            audio_delta,
        )

        modality_scores = {
            "visual": round(
                visual_score,
                6,
            ),
            "subtitle_layout": round(
                subtitle_score,
                6,
            ),
            "audio": round(
                audio_score,
                6,
            ),
        }

        active_modalities = [
            name
            for name, score
            in modality_scores.items()
            if float(score) >= 0.34
        ]

        # Require agreement across modalities. A single scene cut or a single
        # white flash cannot define a structural boundary.
        sorted_scores = sorted(
            [
                float(v)
                for v in modality_scores.values()
            ],
            reverse=True,
        )

        consensus_score = (
            0.50
            * sorted_scores[0]
            + 0.32
            * sorted_scores[1]
            + 0.18
            * sorted_scores[2]
        )

        if (
            len(
                active_modalities
            )
            >= int(
                req.multimodal_min_modalities
            )
            and consensus_score
            >= float(
                req.multimodal_boundary_score_threshold
            )
        ):
            candidates.append(
                {
                    "time_seconds": (
                        timeline[i][
                            "time_seconds"
                        ]
                    ),
                    "score": round(
                        consensus_score,
                        6,
                    ),
                    "active_modalities": (
                        active_modalities
                    ),
                    "modality_scores": (
                        modality_scores
                    ),
                    "before_after": {
                        "subtitle_white_plate_ratio_before": round(
                            white_before,
                            6,
                        ),
                        "subtitle_white_plate_ratio_after": round(
                            white_after,
                            6,
                        ),
                        "audio_vector_before": (
                            audio_before
                            .round(6)
                            .tolist()
                        ),
                        "audio_vector_after": (
                            audio_after
                            .round(6)
                            .tolist()
                        ),
                    },
                }
            )

    # Collapse multiple adjacent timestamps belonging to the same transition.
    if not candidates:
        return []

    merged = []
    current = [
        candidates[0]
    ]

    for candidate in candidates[1:]:
        if (
            float(
                candidate[
                    "time_seconds"
                ]
            )
            - float(
                current[-1][
                    "time_seconds"
                ]
            )
        ) <= max(
            1.0,
            interval * 3.0,
        ):
            current.append(
                candidate
            )
        else:
            merged.append(
                current
            )
            current = [
                candidate
            ]

    merged.append(
        current
    )

    result = []

    for cluster in merged:
        best = max(
            cluster,
            key=lambda x: float(
                x["score"]
            ),
        )
        result.append(
            {
                **best,
                "cluster_start_seconds": (
                    cluster[0][
                        "time_seconds"
                    ]
                ),
                "cluster_end_seconds": (
                    cluster[-1][
                        "time_seconds"
                    ]
                ),
                "cluster_sample_count": (
                    len(
                        cluster
                    )
                ),
            }
        )

    return result


def _choose_promo_multimodal_boundaries(
    boundaries,
    brand_evidence_start,
    brand_evidence_end,
    req,
):
    if not boundaries:
        return None

    evidence_start = float(
        brand_evidence_start
    )
    evidence_end = float(
        brand_evidence_end
    )

    # Start must be before the brand anchor but not arbitrarily early.
    lookback_start = max(
        0.0,
        evidence_start
        - float(
            req.multimodal_context_seconds
        ),
    )

    start_candidates = [
        b
        for b in boundaries
        if (
            lookback_start
            <= float(
                b["time_seconds"]
            )
            <= evidence_start - 1.0
        )
    ]

    if not start_candidates:
        return None

    # Prefer boundaries that have subtitle-layout + audio support, because this
    # combination is highly informative for "new promo presentation regime".
    def start_rank(b):
        modalities = set(
            b.get(
                "active_modalities"
            )
            or []
        )

        multimodal_bonus = 0.0

        if "subtitle_layout" in modalities:
            multimodal_bonus += 0.14
        if "audio" in modalities:
            multimodal_bonus += 0.12
        if "visual" in modalities:
            multimodal_bonus += 0.08

        # Avoid over-favoring the earliest point. Score quality dominates.
        return (
            float(
                b["score"]
            )
            + multimodal_bonus,
            float(
                b["time_seconds"]
            ),
        )

    start = max(
        start_candidates,
        key=start_rank,
    )

    # Search for the next strong structural boundary after the brand evidence.
    end_candidates = [
        b
        for b in boundaries
        if (
            float(
                b["time_seconds"]
            )
            >= evidence_end + 0.75
            and float(
                b["time_seconds"]
            )
            <= evidence_end
            + float(
                req.multimodal_search_tail_seconds
            )
        )
    ]

    end = (
        max(
            end_candidates,
            key=lambda b: float(
                b["score"]
            ),
        )
        if end_candidates
        else None
    )

    return {
        "start": start,
        "end": end,
        "selection_reason": (
            "multimodal_regime_change"
        ),
    }


def _find_endcard_multimodal_boundary(
    boundaries,
    raw_ocr_start,
    duration,
):
    if not boundaries:
        return None

    raw = float(
        raw_ocr_start
    )

    # End-card onset should be near the end and normally precede OCR evidence.
    candidates = [
        b
        for b in boundaries
        if (
            max(
                0.0,
                raw - 5.0,
            )
            <= float(
                b["time_seconds"]
            )
            <= min(
                float(duration),
                raw + 0.5,
            )
        )
    ]

    if not candidates:
        return None

    def rank(b):
        modalities = set(
            b.get(
                "active_modalities"
            )
            or []
        )

        bonus = 0.0
        if "visual" in modalities:
            bonus += 0.10
        if "subtitle_layout" in modalities:
            bonus += 0.08
        if "audio" in modalities:
            bonus += 0.08

        return (
            float(
                b["score"]
            )
            + bonus,
            float(
                b["time_seconds"]
            ),
        )

    return max(
        candidates,
        key=rank,
    )


# Keep the v0.10.4 census as evidence generation. v0.10.5 post-processes its
# candidate boundaries with multimodal regime analysis.
_replacement_segment_census_sync_v0104 = (
    _replacement_segment_census_sync
)


def _replacement_segment_census_sync(
    req: BrandingReplacementSegmentCensusRequest
):
    result = (
        _replacement_segment_census_sync_v0104(
            req
        )
    )

    source_rel = (
        result.get(
            "source"
        )
        or {}
    ).get(
        "relative_path"
    )

    if not source_rel:
        return result

    video_path = (
        _safe_workspace_path(
            source_rel
        )
    )

    duration = float(
        (
            result.get(
                "video"
            )
            or {}
        ).get(
            "duration_seconds"
        )
        or 0.0
    )

    segments = (
        result.get(
            "segments"
        )
        or []
    )

    # Analyze only windows relevant to optional structures rather than the whole
    # video. This keeps runtime reasonable.
    multimodal_diagnostics = []

    for segment in segments:
        seg_type = str(
            segment.get(
                "type"
            )
            or ""
        )

        if (
            seg_type
            == "mid_promo_candidate"
        ):
            brand_start = float(
                segment.get(
                    "brand_evidence_start_seconds"
                )
                or segment.get(
                    "start_seconds"
                )
                or 0.0
            )

            brand_end = float(
                segment.get(
                    "brand_evidence_end_seconds"
                )
                or brand_start
            )

            window_start = max(
                0.0,
                brand_start
                - float(
                    req.multimodal_context_seconds
                ),
            )

            window_end = min(
                duration,
                brand_end
                + float(
                    req.multimodal_search_tail_seconds
                ),
            ) if duration > 0 else (
                brand_end
                + float(
                    req.multimodal_search_tail_seconds
                )
            )

            timeline = (
                _multimodal_feature_timeline(
                    video_path,
                    window_start,
                    window_end,
                    req,
                )
            )

            boundaries = (
                _multimodal_boundary_candidates(
                    timeline,
                    req,
                )
            )

            selection = (
                _choose_promo_multimodal_boundaries(
                    boundaries,
                    brand_start,
                    brand_end,
                    req,
                )
            )

            if (
                selection
                and selection.get(
                    "start"
                )
            ):
                start = float(
                    selection[
                        "start"
                    ][
                        "time_seconds"
                    ]
                )

                segment[
                    "legacy_start_seconds"
                ] = segment.get(
                    "start_seconds"
                )

                segment[
                    "start_seconds"
                ] = round(
                    start,
                    3,
                )

                segment[
                    "start_source"
                ] = (
                    "multimodal_regime_change"
                )

                segment[
                    "selected_multimodal_start"
                ] = selection[
                    "start"
                ]

                if selection.get(
                    "end"
                ):
                    end = float(
                        selection[
                            "end"
                        ][
                            "time_seconds"
                        ]
                    )

                    if (
                        end
                        > start + 1.0
                    ):
                        segment[
                            "legacy_end_seconds"
                        ] = segment.get(
                            "end_seconds"
                        )
                        segment[
                            "end_seconds"
                        ] = round(
                            end,
                            3,
                        )

                        segment[
                            "selected_multimodal_end"
                        ] = selection[
                            "end"
                        ]

                segment[
                    "duration_seconds"
                ] = round(
                    max(
                        0.0,
                        float(
                            segment[
                                "end_seconds"
                            ]
                        )
                        - float(
                            segment[
                                "start_seconds"
                            ]
                        ),
                    ),
                    3,
                )

                segment[
                    "qualifies_duration"
                ] = bool(
                    1.0
                    <= float(
                        segment[
                            "duration_seconds"
                        ]
                    )
                    <= float(
                        req.max_mid_segment_seconds
                    )
                )

                segment[
                    "multimodal_boundary_confidence"
                ] = round(
                    float(
                        selection[
                            "start"
                        ][
                            "score"
                        ]
                    ),
                    6,
                )

            multimodal_diagnostics.append(
                {
                    "segment_id": (
                        segment.get(
                            "segment_id"
                        )
                    ),
                    "type": (
                        seg_type
                    ),
                    "window_start_seconds": (
                        round(
                            window_start,
                            3,
                        )
                    ),
                    "window_end_seconds": (
                        round(
                            window_end,
                            3,
                        )
                    ),
                    "boundaries": (
                        boundaries
                    ),
                    "selection": (
                        selection
                    ),
                }
            )

        elif (
            seg_type
            == "end_card"
        ):
            raw_start = float(
                segment.get(
                    "original_ocr_start_seconds"
                )
                or segment.get(
                    "start_seconds"
                )
                or max(
                    0.0,
                    duration - 3.0,
                )
            )

            window_start = max(
                0.0,
                raw_start - 6.0,
            )

            window_end = (
                duration
                if duration > 0
                else raw_start + 2.0
            )

            timeline = (
                _multimodal_feature_timeline(
                    video_path,
                    window_start,
                    window_end,
                    req,
                )
            )

            boundaries = (
                _multimodal_boundary_candidates(
                    timeline,
                    req,
                )
            )

            selected = (
                _find_endcard_multimodal_boundary(
                    boundaries,
                    raw_start,
                    duration,
                )
            )

            if selected:
                proposed = float(
                    selected[
                        "time_seconds"
                    ]
                )

                earliest = max(
                    0.0,
                    raw_start
                    - float(
                        req.end_card_max_early_seconds
                    ),
                )

                proposed = max(
                    earliest,
                    proposed
                    - float(
                        req.end_card_pre_cut_padding_seconds
                    ),
                )

                segment[
                    "legacy_start_seconds"
                ] = segment.get(
                    "start_seconds"
                )
                segment[
                    "start_seconds"
                ] = round(
                    proposed,
                    3,
                )
                segment[
                    "start_source"
                ] = (
                    "multimodal_endcard_regime_change"
                )
                segment[
                    "selected_multimodal_start"
                ] = (
                    selected
                )
                segment[
                    "multimodal_boundary_confidence"
                ] = round(
                    float(
                        selected[
                            "score"
                        ]
                    ),
                    6,
                )

            multimodal_diagnostics.append(
                {
                    "segment_id": (
                        segment.get(
                            "segment_id"
                        )
                    ),
                    "type": (
                        seg_type
                    ),
                    "window_start_seconds": (
                        round(
                            window_start,
                            3,
                        )
                    ),
                    "window_end_seconds": (
                        round(
                            window_end,
                            3,
                        )
                    ),
                    "boundaries": (
                        boundaries
                    ),
                    "selection": (
                        selected
                    ),
                }
            )

    result["version"] = "0.10.5"

    diagnostics = result.setdefault(
        "diagnostics",
        {},
    )

    diagnostics[
        "multimodal_structure_boundaries"
    ] = multimodal_diagnostics

    result["policy"] = {
        **(
            result.get(
                "policy"
            )
            or {}
        ),
        "multimodal_boundary": (
            "OCR/brand evidence confirms content type; visual composition, "
            "subtitle-layout regime, and audio regime jointly determine "
            "optional-segment boundaries."
        ),
    }

    report_rel = result.get(
        "report_relative_path"
    )

    if report_rel:
        report_path = (
            _safe_workspace_path(
                report_rel
            )
        )
        report_path.write_text(
            json.dumps(
                result,
                ensure_ascii=False,
                indent=2,
            ),
            encoding="utf-8",
        )

    return result


# v0.10.5: Structure Router should prefer the multimodal boundary confidence
# produced by the updated census.
_mid_promo_structure_decision_v0104 = (
    _mid_promo_structure_decision
)


def _mid_promo_structure_decision(
    router,
    segment,
    present_threshold,
    uncertain_threshold,
):
    result = (
        _mid_promo_structure_decision_v0104(
            router,
            segment,
            present_threshold,
            uncertain_threshold,
        )
    )

    if not segment:
        return result

    mm_conf = float(
        segment.get(
            "multimodal_boundary_confidence"
        )
        or 0.0
    )

    if (
        segment.get(
            "start_source"
        )
        == "multimodal_regime_change"
    ):
        result[
            "boundary_confidence"
        ] = round(
            mm_conf,
            6,
        )

        result[
            "plan_eligible"
        ] = bool(
            result.get(
                "presence"
            )
            == "PRESENT"
            and mm_conf >= 0.58
        )

        result[
            "boundary_method"
        ] = (
            "visual+subtitle-layout+audio"
        )

    return result


_end_card_structure_decision_v0103 = (
    _end_card_structure_decision
)


def _end_card_structure_decision(
    router,
    segment,
    video_duration,
    present_threshold,
    uncertain_threshold,
):
    result = (
        _end_card_structure_decision_v0103(
            router,
            segment,
            video_duration,
            present_threshold,
            uncertain_threshold,
        )
    )

    if not segment:
        return result

    mm_conf = float(
        segment.get(
            "multimodal_boundary_confidence"
        )
        or 0.0
    )

    if (
        segment.get(
            "start_source"
        )
        == "multimodal_endcard_regime_change"
    ):
        result[
            "boundary_confidence"
        ] = round(
            mm_conf,
            6,
        )
        result[
            "boundary_method"
        ] = (
            "visual+subtitle-layout+audio"
        )

        # End-card PRESENCE still comes from end-card evidence. Multimodal score
        # controls whether its cut point is trusted.
        result[
            "plan_eligible"
        ] = bool(
            result.get(
                "presence"
            )
            == "PRESENT"
            and mm_conf >= 0.56
        )

    return result




# ---------------------------------------------------------------------------
# v0.10.6 Paired Multimodal Regime Segmentation
#
# v0.10.5 still ranked single strong boundary points. That can select an
# internal promo cut (e.g. 53.5s) instead of the beginning of the whole promo.
#
# v0.10.6 evaluates boundary PAIRS:
#
#   outside-before -> sustained inside-regime -> outside-after
#
# A start is penalized if the seconds immediately BEFORE it already look like
# the same promo regime. This is the key mechanism for rejecting internal cuts.
# ---------------------------------------------------------------------------


def _timeline_slice(
    timeline,
    start_seconds,
    end_seconds,
):
    start = float(start_seconds)
    end = float(end_seconds)

    return [
        item
        for item in timeline
        if (
            start
            <= float(
                item["time_seconds"]
            )
            <= end
        )
    ]


def _regime_signature(items):
    if not items:
        return None

    hist = _mean_feature_vector(
        items,
        (
            "visual",
            "hist",
        ),
    )

    if hist is None:
        return None

    edge = _mean_scalar(
        items,
        "visual",
        "edge_density",
    )

    white = _mean_scalar(
        items,
        "visual",
        "subtitle_white_plate_ratio",
    )

    audio = _window_audio_mean(
        items
    )

    return {
        "hist": hist,
        "edge": float(edge),
        "white": float(white),
        "audio": audio,
    }


def _regime_modality_distance(
    a,
    b,
):
    if not a or not b:
        return {
            "visual": 0.0,
            "subtitle_layout": 0.0,
            "audio": 0.0,
            "consensus": 0.0,
        }

    hist_delta = _cosine_distance(
        a["hist"],
        b["hist"],
    )

    edge_delta = min(
        1.0,
        abs(
            float(a["edge"])
            - float(b["edge"])
        )
        / 0.085,
    )

    visual = min(
        1.0,
        0.72 * hist_delta
        + 0.28 * edge_delta,
    )

    subtitle = min(
        1.0,
        abs(
            float(a["white"])
            - float(b["white"])
        )
        / 0.055,
    )

    scales = np.asarray(
        [
            0.28,
            0.055,
            0.15,
            0.17,
            0.18,
            0.15,
        ],
        dtype=np.float32,
    )

    audio = float(
        np.mean(
            np.minimum(
                1.0,
                np.abs(
                    np.asarray(
                        a["audio"],
                        dtype=np.float32,
                    )
                    - np.asarray(
                        b["audio"],
                        dtype=np.float32,
                    )
                )
                / scales,
            )
        )
    )

    scores = sorted(
        [
            float(visual),
            float(subtitle),
            float(audio),
        ],
        reverse=True,
    )

    consensus = (
        0.52 * scores[0]
        + 0.33 * scores[1]
        + 0.15 * scores[2]
    )

    return {
        "visual": round(
            float(visual),
            6,
        ),
        "subtitle_layout": round(
            float(subtitle),
            6,
        ),
        "audio": round(
            float(audio),
            6,
        ),
        "consensus": round(
            float(consensus),
            6,
        ),
    }


def _soft_boundary_candidates(
    timeline,
    req,
):
    # Pair scoring needs candidates that are moderately strong as well as very
    # strong. A true segment onset can be less dramatic than an internal cut.
    try:
        soft_req = req.model_copy(
            update={
                "multimodal_boundary_score_threshold": min(
                    0.46,
                    float(
                        req.multimodal_boundary_score_threshold
                    ),
                )
            }
        )
    except Exception:
        soft_req = req.copy(
            update={
                "multimodal_boundary_score_threshold": min(
                    0.46,
                    float(
                        req.multimodal_boundary_score_threshold
                    ),
                )
            }
        )

    return _multimodal_boundary_candidates(
        timeline,
        soft_req,
    )


def _boundary_support_score(boundary):
    if not boundary:
        return 0.0

    modalities = set(
        boundary.get(
            "active_modalities"
        )
        or []
    )

    bonus = 0.0

    if "visual" in modalities:
        bonus += 0.04

    if "subtitle_layout" in modalities:
        bonus += 0.08

    if "audio" in modalities:
        bonus += 0.08

    return min(
        1.0,
        float(
            boundary.get(
                "score"
            )
            or 0.0
        )
        + bonus,
    )


def _promo_pair_score(
    timeline,
    start_boundary,
    end_boundary,
    brand_evidence_start,
    brand_evidence_end,
    req,
):
    start = float(
        start_boundary[
            "time_seconds"
        ]
    )

    end = float(
        end_boundary[
            "time_seconds"
        ]
    )

    duration = end - start

    if (
        duration < 4.0
        or duration
        > float(
            req.max_mid_segment_seconds
        )
    ):
        return None

    if not (
        start
        < float(
            brand_evidence_start
        )
        < end
    ):
        return None

    if (
        float(
            brand_evidence_end
        )
        > end + 0.75
    ):
        return None

    pre = _timeline_slice(
        timeline,
        max(
            float(
                timeline[0][
                    "time_seconds"
                ]
            ),
            start - 4.5,
        ),
        start - 0.75,
    )

    # Use early and late portions of the INSIDE state separately. A real promo
    # start should make both portions look more like each other than the
    # pre-start story state.
    inside_early = _timeline_slice(
        timeline,
        start + 0.75,
        min(
            end - 1.0,
            start + 5.0,
        ),
    )

    inside_late = _timeline_slice(
        timeline,
        max(
            start + 1.0,
            min(
                float(
                    brand_evidence_start
                ) - 1.0,
                end - 5.0,
            ),
        ),
        end - 0.75,
    )

    post = _timeline_slice(
        timeline,
        end + 0.75,
        min(
            float(
                timeline[-1][
                    "time_seconds"
                ]
            ),
            end + 4.5,
        ),
    )

    if (
        len(pre) < 2
        or len(inside_early) < 2
        or len(inside_late) < 2
        or len(post) < 2
    ):
        return None

    sig_pre = _regime_signature(
        pre
    )
    sig_early = _regime_signature(
        inside_early
    )
    sig_late = _regime_signature(
        inside_late
    )
    sig_post = _regime_signature(
        post
    )

    pre_to_inside = (
        _regime_modality_distance(
            sig_pre,
            sig_early,
        )
    )

    inside_to_post = (
        _regime_modality_distance(
            sig_late,
            sig_post,
        )
    )

    inside_drift = (
        _regime_modality_distance(
            sig_early,
            sig_late,
        )
    )

    start_support = (
        _boundary_support_score(
            start_boundary
        )
    )

    end_support = (
        _boundary_support_score(
            end_boundary
        )
    )

    # Internal cuts are the main failure mode:
    #
    # if pre-start already looks like the inside promo state, the start must be
    # penalized even when its local boundary score is high.
    start_state_change = float(
        pre_to_inside[
            "consensus"
        ]
    )

    end_state_change = float(
        inside_to_post[
            "consensus"
        ]
    )

    # Promo can contain different shots, so visual drift is tolerated. Stable
    # subtitle-layout + audio are weighted more strongly here.
    internal_stability = (
        1.0
        - min(
            1.0,
            0.20
            * float(
                inside_drift[
                    "visual"
                ]
            )
            + 0.42
            * float(
                inside_drift[
                    "subtitle_layout"
                ]
            )
            + 0.38
            * float(
                inside_drift[
                    "audio"
                ]
            ),
        )
    )

    modalities_at_start = sum(
        1
        for name in (
            "visual",
            "subtitle_layout",
            "audio",
        )
        if float(
            pre_to_inside[
                name
            ]
        )
        >= 0.32
    )

    modalities_at_end = sum(
        1
        for name in (
            "visual",
            "subtitle_layout",
            "audio",
        )
        if float(
            inside_to_post[
                name
            ]
        )
        >= 0.32
    )

    # Require state-change evidence at BOTH ends. This prevents choosing a
    # strong internal promo cut as the start while retaining a weak legacy end.
    if (
        modalities_at_start < 2
        or modalities_at_end < 2
    ):
        return None

    pair_score = (
        0.25 * start_state_change
        + 0.22 * end_state_change
        + 0.14 * start_support
        + 0.12 * end_support
        + 0.19 * internal_stability
        + 0.08
    )

    # Extra penalty when the start is likely internal:
    # the state immediately before it is too similar to the regime after it.
    if start_state_change < 0.42:
        pair_score -= (
            0.18
            * (
                0.42
                - start_state_change
            )
            / 0.42
        )

    pair_score = max(
        0.0,
        min(
            0.98,
            pair_score,
        ),
    )

    return {
        "start": start_boundary,
        "end": end_boundary,
        "start_seconds": round(
            start,
            3,
        ),
        "end_seconds": round(
            end,
            3,
        ),
        "duration_seconds": round(
            duration,
            3,
        ),
        "pair_score": round(
            pair_score,
            6,
        ),
        "start_state_change": (
            pre_to_inside
        ),
        "end_state_change": (
            inside_to_post
        ),
        "inside_drift": (
            inside_drift
        ),
        "internal_stability": round(
            internal_stability,
            6,
        ),
        "start_support": round(
            start_support,
            6,
        ),
        "end_support": round(
            end_support,
            6,
        ),
        "start_active_state_modalities": (
            modalities_at_start
        ),
        "end_active_state_modalities": (
            modalities_at_end
        ),
    }


def _choose_promo_regime_pair(
    timeline,
    boundaries,
    brand_evidence_start,
    brand_evidence_end,
    req,
):
    if not timeline:
        return None

    evidence_start = float(
        brand_evidence_start
    )
    evidence_end = float(
        brand_evidence_end
    )

    start_min = max(
        float(
            timeline[0][
                "time_seconds"
            ]
        ),
        evidence_start
        - float(
            req.multimodal_context_seconds
        ),
    )

    starts = [
        b
        for b in boundaries
        if (
            start_min
            <= float(
                b["time_seconds"]
            )
            <= evidence_start - 1.0
        )
    ]

    # The promo can continue beyond the brand-text evidence. Search the whole
    # multimodal tail, rather than stopping at the old OCR-derived end.
    ends = [
        b
        for b in boundaries
        if (
            evidence_end + 0.75
            <= float(
                b["time_seconds"]
            )
            <= float(
                timeline[-1][
                    "time_seconds"
                ]
            )
            - 0.75
        )
    ]

    pairs = []

    for start in starts:
        for end in ends:
            scored = _promo_pair_score(
                timeline,
                start,
                end,
                evidence_start,
                evidence_end,
                req,
            )

            if scored:
                pairs.append(
                    scored
                )

    if not pairs:
        return {
            "selection_reason": (
                "no_valid_paired_multimodal_regime"
            ),
            "selected_pair": None,
            "candidate_pairs": [],
        }

    pairs.sort(
        key=lambda x: (
            float(
                x["pair_score"]
            ),
            float(
                x[
                    "internal_stability"
                ]
            ),
            float(
                x[
                    "duration_seconds"
                ]
            ),
        ),
        reverse=True,
    )

    best_score = float(
        pairs[0][
            "pair_score"
        ]
    )

    # If several segment pairs explain the same stable regime almost equally
    # well, prefer the EARLIER valid onset. This is only applied after the
    # paired-state tests, so it does not revive isolated 37s text.
    near_best = [
        pair
        for pair in pairs
        if float(
            pair[
                "pair_score"
            ]
        )
        >= best_score - 0.035
    ]

    near_best.sort(
        key=lambda x: (
            float(
                x["start_seconds"]
            ),
            -float(
                x["end_seconds"]
            ),
        )
    )

    selected = (
        near_best[0]
        if near_best
        else pairs[0]
    )

    return {
        "selection_reason": (
            "paired_multimodal_regime"
        ),
        "selected_pair": selected,
        "candidate_pairs": (
            pairs[:20]
        ),
    }


def _choose_endcard_final_regime(
    timeline,
    boundaries,
    raw_ocr_start,
    duration,
    req,
):
    if not timeline:
        return None

    raw = float(
        raw_ocr_start
    )

    candidates = [
        b
        for b in boundaries
        if (
            max(
                float(
                    timeline[0][
                        "time_seconds"
                    ]
                ),
                raw - 5.5,
            )
            <= float(
                b["time_seconds"]
            )
            <= min(
                float(duration),
                raw + 0.75,
            )
        )
    ]

    scored = []

    for boundary in candidates:
        t = float(
            boundary[
                "time_seconds"
            ]
        )

        pre = _timeline_slice(
            timeline,
            max(
                float(
                    timeline[0][
                        "time_seconds"
                    ]
                ),
                t - 4.0,
            ),
            t - 0.75,
        )

        final_early = _timeline_slice(
            timeline,
            t + 0.75,
            min(
                float(duration),
                t + 3.5,
            ),
        )

        final_late = _timeline_slice(
            timeline,
            max(
                t + 1.0,
                float(duration) - 2.5,
            ),
            float(duration),
        )

        if (
            len(pre) < 2
            or len(final_early) < 2
            or len(final_late) < 2
        ):
            continue

        sig_pre = _regime_signature(
            pre
        )
        sig_early = _regime_signature(
            final_early
        )
        sig_late = _regime_signature(
            final_late
        )

        transition = (
            _regime_modality_distance(
                sig_pre,
                sig_early,
            )
        )

        final_drift = (
            _regime_modality_distance(
                sig_early,
                sig_late,
            )
        )

        modalities = sum(
            1
            for name in (
                "visual",
                "subtitle_layout",
                "audio",
            )
            if float(
                transition[
                    name
                ]
            )
            >= 0.32
        )

        if modalities < 2:
            continue

        persistence = (
            1.0
            - min(
                1.0,
                0.24
                * float(
                    final_drift[
                        "visual"
                    ]
                )
                + 0.34
                * float(
                    final_drift[
                        "subtitle_layout"
                    ]
                )
                + 0.42
                * float(
                    final_drift[
                        "audio"
                    ]
                ),
            )
        )

        score = (
            0.46
            * float(
                transition[
                    "consensus"
                ]
            )
            + 0.24
            * _boundary_support_score(
                boundary
            )
            + 0.30
            * persistence
        )

        scored.append(
            {
                "boundary": (
                    boundary
                ),
                "time_seconds": round(
                    t,
                    3,
                ),
                "score": round(
                    min(
                        0.98,
                        score,
                    ),
                    6,
                ),
                "transition": (
                    transition
                ),
                "final_drift": (
                    final_drift
                ),
                "final_persistence": round(
                    persistence,
                    6,
                ),
                "active_state_modalities": (
                    modalities
                ),
            }
        )

    if not scored:
        return None

    scored.sort(
        key=lambda x: float(
            x["score"]
        ),
        reverse=True,
    )

    best = float(
        scored[0]["score"]
    )

    near_best = [
        x
        for x in scored
        if float(
            x["score"]
        )
        >= best - 0.035
    ]

    # For a persistent final regime, prefer the earliest equally-good onset.
    near_best.sort(
        key=lambda x: float(
            x["time_seconds"]
        )
    )

    chosen = (
        near_best[0]
        if near_best
        else scored[0]
    )

    return {
        "selection_reason": (
            "persistent_final_multimodal_regime"
        ),
        "selected": chosen,
        "candidates": scored,
    }


# Post-process v0.10.5 census with paired-state segmentation.
_replacement_segment_census_sync_v0105 = (
    _replacement_segment_census_sync
)


def _replacement_segment_census_sync(
    req: BrandingReplacementSegmentCensusRequest
):
    result = (
        _replacement_segment_census_sync_v0105(
            req
        )
    )

    source_rel = (
        result.get(
            "source"
        )
        or {}
    ).get(
        "relative_path"
    )

    if not source_rel:
        return result

    video_path = _safe_workspace_path(
        source_rel
    )

    duration = float(
        (
            result.get(
                "video"
            )
            or {}
        ).get(
            "duration_seconds"
        )
        or 0.0
    )

    pair_diagnostics = []

    for segment in (
        result.get(
            "segments"
        )
        or []
    ):
        seg_type = str(
            segment.get(
                "type"
            )
            or ""
        )

        if (
            seg_type
            == "mid_promo_candidate"
        ):
            brand_start = float(
                segment.get(
                    "brand_evidence_start_seconds"
                )
                or 0.0
            )

            brand_end = float(
                segment.get(
                    "brand_evidence_end_seconds"
                )
                or brand_start
            )

            window_start = max(
                0.0,
                brand_start
                - float(
                    req.multimodal_context_seconds
                ),
            )

            window_end = (
                min(
                    duration,
                    brand_end
                    + max(
                        10.0,
                        float(
                            req.multimodal_search_tail_seconds
                        ),
                    ),
                )
                if duration > 0
                else (
                    brand_end + 10.0
                )
            )

            timeline = (
                _multimodal_feature_timeline(
                    video_path,
                    window_start,
                    window_end,
                    req,
                )
            )

            boundaries = (
                _soft_boundary_candidates(
                    timeline,
                    req,
                )
            )

            selection = (
                _choose_promo_regime_pair(
                    timeline,
                    boundaries,
                    brand_start,
                    brand_end,
                    req,
                )
            )

            pair = (
                selection.get(
                    "selected_pair"
                )
                if selection
                else None
            )

            if pair:
                segment[
                    "legacy_v0105_start_seconds"
                ] = segment.get(
                    "start_seconds"
                )
                segment[
                    "legacy_v0105_end_seconds"
                ] = segment.get(
                    "end_seconds"
                )

                segment[
                    "start_seconds"
                ] = pair[
                    "start_seconds"
                ]
                segment[
                    "end_seconds"
                ] = pair[
                    "end_seconds"
                ]
                segment[
                    "duration_seconds"
                ] = pair[
                    "duration_seconds"
                ]
                segment[
                    "start_source"
                ] = (
                    "paired_multimodal_regime"
                )
                segment[
                    "end_source"
                ] = (
                    "paired_multimodal_regime"
                )
                segment[
                    "selected_regime_pair"
                ] = pair
                segment[
                    "multimodal_boundary_confidence"
                ] = pair[
                    "pair_score"
                ]
                segment[
                    "qualifies_duration"
                ] = bool(
                    1.0
                    <= float(
                        pair[
                            "duration_seconds"
                        ]
                    )
                    <= float(
                        req.max_mid_segment_seconds
                    )
                )

            pair_diagnostics.append(
                {
                    "segment_id": (
                        segment.get(
                            "segment_id"
                        )
                    ),
                    "type": (
                        seg_type
                    ),
                    "window_start_seconds": round(
                        window_start,
                        3,
                    ),
                    "window_end_seconds": round(
                        window_end,
                        3,
                    ),
                    "boundary_candidates": (
                        boundaries
                    ),
                    "regime_pair_selection": (
                        selection
                    ),
                }
            )

        elif (
            seg_type
            == "end_card"
        ):
            raw_start = float(
                segment.get(
                    "original_ocr_start_seconds"
                )
                or segment.get(
                    "start_seconds"
                )
                or max(
                    0.0,
                    duration - 3.0,
                )
            )

            window_start = max(
                0.0,
                raw_start - 7.0,
            )

            window_end = (
                duration
                if duration > 0
                else raw_start + 2.0
            )

            timeline = (
                _multimodal_feature_timeline(
                    video_path,
                    window_start,
                    window_end,
                    req,
                )
            )

            boundaries = (
                _soft_boundary_candidates(
                    timeline,
                    req,
                )
            )

            selection = (
                _choose_endcard_final_regime(
                    timeline,
                    boundaries,
                    raw_start,
                    duration,
                    req,
                )
            )

            selected = (
                selection.get(
                    "selected"
                )
                if selection
                else None
            )

            if selected:
                proposed = max(
                    0.0,
                    float(
                        selected[
                            "time_seconds"
                        ]
                    )
                    - float(
                        req.end_card_pre_cut_padding_seconds
                    ),
                )

                segment[
                    "legacy_v0105_start_seconds"
                ] = segment.get(
                    "start_seconds"
                )
                segment[
                    "start_seconds"
                ] = round(
                    proposed,
                    3,
                )
                segment[
                    "start_source"
                ] = (
                    "persistent_final_multimodal_regime"
                )
                segment[
                    "selected_final_regime"
                ] = selected
                segment[
                    "multimodal_boundary_confidence"
                ] = selected[
                    "score"
                ]

            pair_diagnostics.append(
                {
                    "segment_id": (
                        segment.get(
                            "segment_id"
                        )
                    ),
                    "type": (
                        seg_type
                    ),
                    "window_start_seconds": round(
                        window_start,
                        3,
                    ),
                    "window_end_seconds": round(
                        window_end,
                        3,
                    ),
                    "boundary_candidates": (
                        boundaries
                    ),
                    "final_regime_selection": (
                        selection
                    ),
                }
            )

    result["version"] = "0.10.6"

    diagnostics = result.setdefault(
        "diagnostics",
        {},
    )

    diagnostics[
        "paired_multimodal_regimes"
    ] = pair_diagnostics

    result["policy"] = {
        **(
            result.get(
                "policy"
            )
            or {}
        ),
        "paired_regime": (
            "Optional segment boundaries are selected as persistent state "
            "transitions in pairs. Internal scene cuts are penalized when the "
            "pre-boundary state already resembles the segment regime."
        ),
    }

    report_rel = result.get(
        "report_relative_path"
    )

    if report_rel:
        _safe_workspace_path(
            report_rel
        ).write_text(
            json.dumps(
                result,
                ensure_ascii=False,
                indent=2,
            ),
            encoding="utf-8",
        )

    return result


# v0.10.6 boundary confidence comes from paired segment quality.
_mid_promo_structure_decision_v0105 = (
    _mid_promo_structure_decision
)


def _mid_promo_structure_decision(
    router,
    segment,
    present_threshold,
    uncertain_threshold,
):
    result = (
        _mid_promo_structure_decision_v0105(
            router,
            segment,
            present_threshold,
            uncertain_threshold,
        )
    )

    if not segment:
        return result

    if (
        segment.get(
            "start_source"
        )
        == "paired_multimodal_regime"
    ):
        conf = float(
            segment.get(
                "multimodal_boundary_confidence"
            )
            or 0.0
        )

        result[
            "boundary_confidence"
        ] = round(
            conf,
            6,
        )
        result[
            "boundary_method"
        ] = (
            "paired_visual+subtitle-layout+audio_regime"
        )
        result[
            "plan_eligible"
        ] = bool(
            result.get(
                "presence"
            )
            == "PRESENT"
            and conf >= 0.60
        )

    return result


_end_card_structure_decision_v0105 = (
    _end_card_structure_decision
)


def _end_card_structure_decision(
    router,
    segment,
    video_duration,
    present_threshold,
    uncertain_threshold,
):
    result = (
        _end_card_structure_decision_v0105(
            router,
            segment,
            video_duration,
            present_threshold,
            uncertain_threshold,
        )
    )

    if not segment:
        return result

    if (
        segment.get(
            "start_source"
        )
        == "persistent_final_multimodal_regime"
    ):
        conf = float(
            segment.get(
                "multimodal_boundary_confidence"
            )
            or 0.0
        )

        result[
            "boundary_confidence"
        ] = round(
            conf,
            6,
        )
        result[
            "boundary_method"
        ] = (
            "persistent_final_visual+subtitle-layout+audio_regime"
        )
        result[
            "plan_eligible"
        ] = bool(
            result.get(
                "presence"
            )
            == "PRESENT"
            and conf >= 0.58
        )

    return result




# ---------------------------------------------------------------------------
# v0.10.7 Exhaustive Multimodal State Segmentation
#
# v0.10.6 could fail to find a valid paired boundary candidate and then leave
# the old v0.10.5 single-boundary result in place. That fallback is unsafe.
#
# v0.10.7 does NOT require a local "strong boundary" candidate first.
# It evaluates start/end timestamps directly on the multimodal timeline:
#
#   PRE state -> INSIDE state -> POST state
#
# This detects persistent regime changes even when the exact transition is
# gradual or not a sharp cut.
# ---------------------------------------------------------------------------


def _state_transition_modalities(
    left_items,
    right_items,
):
    left = _regime_signature(
        left_items
    )
    right = _regime_signature(
        right_items
    )

    if not left or not right:
        return None

    return _regime_modality_distance(
        left,
        right,
    )


def _inside_consistency_score(
    early_items,
    anchor_items,
    late_items,
):
    early = _regime_signature(
        early_items
    )
    anchor = _regime_signature(
        anchor_items
    )
    late = _regime_signature(
        late_items
    )

    if not early or not anchor or not late:
        return 0.0, None

    d1 = _regime_modality_distance(
        early,
        anchor,
    )
    d2 = _regime_modality_distance(
        anchor,
        late,
    )

    # Visuals inside an ad can change shot-to-shot. Subtitle layout and audio
    # presentation are more useful for persistence.
    drift = (
        0.18
        * (
            float(d1["visual"])
            + float(d2["visual"])
        )
        / 2.0
        + 0.42
        * (
            float(
                d1["subtitle_layout"]
            )
            + float(
                d2["subtitle_layout"]
            )
        )
        / 2.0
        + 0.40
        * (
            float(d1["audio"])
            + float(d2["audio"])
        )
        / 2.0
    )

    stability = max(
        0.0,
        min(
            1.0,
            1.0 - drift,
        ),
    )

    return (
        float(stability),
        {
            "early_to_anchor": d1,
            "anchor_to_late": d2,
        },
    )


def _transition_active_count(
    transition,
    threshold=0.28,
):
    if not transition:
        return 0

    return sum(
        1
        for name in (
            "visual",
            "subtitle_layout",
            "audio",
        )
        if float(
            transition.get(name)
            or 0.0
        )
        >= float(threshold)
    )


def _exhaustive_promo_state_pairs(
    timeline,
    brand_evidence_start,
    brand_evidence_end,
    req,
):
    if not timeline:
        return []

    evidence_start = float(
        brand_evidence_start
    )
    evidence_end = float(
        brand_evidence_end
    )

    timeline_start = float(
        timeline[0]["time_seconds"]
    )
    timeline_end = float(
        timeline[-1]["time_seconds"]
    )

    sample_times = [
        float(item["time_seconds"])
        for item in timeline
    ]

    # Start must precede the brand anchor. End must follow it.
    start_times = [
        t
        for t in sample_times
        if (
            max(
                timeline_start + 4.5,
                evidence_start
                - float(
                    req.multimodal_context_seconds
                ),
            )
            <= t
            <= evidence_start - 3.0
        )
    ]

    end_times = [
        t
        for t in sample_times
        if (
            evidence_end + 2.0
            <= t
            <= timeline_end - 3.0
        )
    ]

    pairs = []

    for start in start_times:
        pre = _timeline_slice(
            timeline,
            start - 4.0,
            start - 0.75,
        )

        early = _timeline_slice(
            timeline,
            start + 0.75,
            min(
                start + 5.0,
                evidence_start - 1.0,
            ),
        )

        if (
            len(pre) < 3
            or len(early) < 3
        ):
            continue

        start_change = (
            _state_transition_modalities(
                pre,
                early,
            )
        )

        start_modalities = (
            _transition_active_count(
                start_change,
                0.28,
            )
        )

        # A valid onset needs at least two modalities to change across the
        # state window. This is intentionally weaker than requiring a sharp cut.
        if start_modalities < 2:
            continue

        for end in end_times:
            duration = end - start

            if (
                duration < 5.0
                or duration
                > float(
                    req.max_mid_segment_seconds
                )
            ):
                continue

            if not (
                start
                < evidence_start
                < evidence_end
                < end
            ):
                continue

            anchor = _timeline_slice(
                timeline,
                max(
                    start + 1.0,
                    evidence_start - 2.0,
                ),
                min(
                    end - 1.0,
                    evidence_end + 1.0,
                ),
            )

            late = _timeline_slice(
                timeline,
                max(
                    evidence_end + 0.75,
                    end - 5.0,
                ),
                end - 0.75,
            )

            post = _timeline_slice(
                timeline,
                end + 0.75,
                min(
                    timeline_end,
                    end + 4.0,
                ),
            )

            if (
                len(anchor) < 3
                or len(late) < 3
                or len(post) < 3
            ):
                continue

            end_change = (
                _state_transition_modalities(
                    late,
                    post,
                )
            )

            end_modalities = (
                _transition_active_count(
                    end_change,
                    0.28,
                )
            )

            if end_modalities < 2:
                continue

            (
                stability,
                inside_drift,
            ) = _inside_consistency_score(
                early,
                anchor,
                late,
            )

            start_consensus = float(
                start_change[
                    "consensus"
                ]
            )
            end_consensus = float(
                end_change[
                    "consensus"
                ]
            )

            # Explicitly reward subtitle/audio regime changes because they are
            # the strongest human cues in the current test, while keeping the
            # model generic for other videos.
            start_semantic_bonus = (
                0.08
                * float(
                    start_change[
                        "subtitle_layout"
                    ]
                )
                + 0.08
                * float(
                    start_change[
                        "audio"
                    ]
                )
            )

            end_semantic_bonus = (
                0.06
                * float(
                    end_change[
                        "subtitle_layout"
                    ]
                )
                + 0.06
                * float(
                    end_change[
                        "audio"
                    ]
                )
            )

            score = (
                0.31
                * start_consensus
                + 0.27
                * end_consensus
                + 0.24
                * stability
                + start_semantic_bonus
                + end_semantic_bonus
                + 0.06
            )

            # Internal-cut rejection:
            # if the "pre" state already resembles the anchor Promo state more
            # than it resembles normal outside content, this timestamp is not
            # a good segment start.
            pre_sig = _regime_signature(
                pre
            )
            anchor_sig = (
                _regime_signature(
                    anchor
                )
            )

            pre_to_anchor = (
                _regime_modality_distance(
                    pre_sig,
                    anchor_sig,
                )
            )

            pre_anchor_similarity = (
                1.0
                - (
                    0.18
                    * float(
                        pre_to_anchor[
                            "visual"
                        ]
                    )
                    + 0.42
                    * float(
                        pre_to_anchor[
                            "subtitle_layout"
                        ]
                    )
                    + 0.40
                    * float(
                        pre_to_anchor[
                            "audio"
                        ]
                    )
                )
            )

            if (
                pre_anchor_similarity
                >= 0.72
            ):
                score -= min(
                    0.24,
                    (
                        pre_anchor_similarity
                        - 0.72
                    )
                    * 0.85
                    + 0.06,
                )

            score = max(
                0.0,
                min(
                    0.98,
                    score,
                ),
            )

            pairs.append(
                {
                    "start_seconds": round(
                        start,
                        3,
                    ),
                    "end_seconds": round(
                        end,
                        3,
                    ),
                    "duration_seconds": round(
                        duration,
                        3,
                    ),
                    "pair_score": round(
                        score,
                        6,
                    ),
                    "start_state_change": (
                        start_change
                    ),
                    "end_state_change": (
                        end_change
                    ),
                    "inside_drift": (
                        inside_drift
                    ),
                    "internal_stability": round(
                        stability,
                        6,
                    ),
                    "pre_anchor_similarity": round(
                        pre_anchor_similarity,
                        6,
                    ),
                    "start_active_modalities": (
                        start_modalities
                    ),
                    "end_active_modalities": (
                        end_modalities
                    ),
                }
            )

    pairs.sort(
        key=lambda x: (
            float(
                x["pair_score"]
            ),
            float(
                x["internal_stability"]
            ),
        ),
        reverse=True,
    )

    return pairs


def _select_exhaustive_promo_pair(
    timeline,
    brand_evidence_start,
    brand_evidence_end,
    req,
):
    pairs = _exhaustive_promo_state_pairs(
        timeline,
        brand_evidence_start,
        brand_evidence_end,
        req,
    )

    if not pairs:
        return {
            "selection_reason": (
                "no_reliable_exhaustive_state_pair"
            ),
            "selected_pair": None,
            "candidate_pairs": [],
        }

    best_score = float(
        pairs[0]["pair_score"]
    )

    near_best = [
        p
        for p in pairs
        if float(
            p["pair_score"]
        )
        >= best_score - 0.025
    ]

    # Among equally explanatory regimes, choose the earlier onset and later
    # end. This recovers the whole structural block rather than an internal
    # sub-block.
    near_best.sort(
        key=lambda p: (
            float(
                p["start_seconds"]
            ),
            -float(
                p["end_seconds"]
            ),
        )
    )

    selected = (
        near_best[0]
        if near_best
        else pairs[0]
    )

    return {
        "selection_reason": (
            "exhaustive_multimodal_state_pair"
        ),
        "selected_pair": (
            selected
        ),
        "candidate_pairs": (
            pairs[:30]
        ),
    }


def _exhaustive_final_regime(
    timeline,
    raw_ocr_start,
    duration,
    req,
):
    if not timeline:
        return None

    raw = float(
        raw_ocr_start
    )

    timeline_start = float(
        timeline[0]["time_seconds"]
    )

    candidates = []

    for item in timeline:
        t = float(
            item["time_seconds"]
        )

        if not (
            max(
                timeline_start + 3.5,
                raw - 5.5,
            )
            <= t
            <= min(
                float(duration) - 2.0,
                raw + 0.75,
            )
        ):
            continue

        pre = _timeline_slice(
            timeline,
            t - 3.5,
            t - 0.75,
        )

        final_early = _timeline_slice(
            timeline,
            t + 0.75,
            min(
                float(duration),
                t + 3.5,
            ),
        )

        final_late = _timeline_slice(
            timeline,
            max(
                t + 1.0,
                float(duration) - 2.5,
            ),
            float(duration),
        )

        if (
            len(pre) < 3
            or len(final_early) < 3
            or len(final_late) < 3
        ):
            continue

        transition = (
            _state_transition_modalities(
                pre,
                final_early,
            )
        )

        if (
            _transition_active_count(
                transition,
                0.28,
            )
            < 2
        ):
            continue

        (
            final_stability,
            final_drift,
        ) = _inside_consistency_score(
            final_early,
            final_late,
            final_late,
        )

        score = (
            0.54
            * float(
                transition[
                    "consensus"
                ]
            )
            + 0.32
            * final_stability
            + 0.08
            * float(
                transition[
                    "audio"
                ]
            )
            + 0.06
        )

        candidates.append(
            {
                "time_seconds": round(
                    t,
                    3,
                ),
                "score": round(
                    min(
                        0.98,
                        score,
                    ),
                    6,
                ),
                "transition": transition,
                "final_stability": round(
                    final_stability,
                    6,
                ),
                "final_drift": (
                    final_drift
                ),
            }
        )

    if not candidates:
        return None

    candidates.sort(
        key=lambda x: float(
            x["score"]
        ),
        reverse=True,
    )

    best_score = float(
        candidates[0]["score"]
    )

    near_best = [
        x
        for x in candidates
        if float(
            x["score"]
        )
        >= best_score - 0.025
    ]

    near_best.sort(
        key=lambda x: float(
            x["time_seconds"]
        )
    )

    selected = (
        near_best[0]
        if near_best
        else candidates[0]
    )

    return {
        "selection_reason": (
            "exhaustive_persistent_final_state"
        ),
        "selected": selected,
        "candidates": (
            candidates[:20]
        ),
    }


_replacement_segment_census_sync_v0106 = (
    _replacement_segment_census_sync
)


def _replacement_segment_census_sync(
    req: BrandingReplacementSegmentCensusRequest
):
    result = (
        _replacement_segment_census_sync_v0106(
            req
        )
    )

    source_rel = (
        result.get(
            "source"
        )
        or {}
    ).get(
        "relative_path"
    )

    if not source_rel:
        return result

    video_path = _safe_workspace_path(
        source_rel
    )

    duration = float(
        (
            result.get(
                "video"
            )
            or {}
        ).get(
            "duration_seconds"
        )
        or 0.0
    )

    diagnostics = []

    for segment in (
        result.get(
            "segments"
        )
        or []
    ):
        seg_type = str(
            segment.get(
                "type"
            )
            or ""
        )

        if seg_type == "mid_promo_candidate":
            brand_start = float(
                segment.get(
                    "brand_evidence_start_seconds"
                )
                or 0.0
            )

            brand_end = float(
                segment.get(
                    "brand_evidence_end_seconds"
                )
                or brand_start
            )

            window_start = max(
                0.0,
                brand_start
                - float(
                    req.multimodal_context_seconds
                ),
            )

            # Give the detector enough room to observe a return to story after
            # the brand anchor.
            window_end = (
                min(
                    duration,
                    brand_end + 14.0,
                )
                if duration > 0
                else brand_end + 14.0
            )

            timeline = (
                _multimodal_feature_timeline(
                    video_path,
                    window_start,
                    window_end,
                    req,
                )
            )

            selection = (
                _select_exhaustive_promo_pair(
                    timeline,
                    brand_start,
                    brand_end,
                    req,
                )
            )

            pair = selection.get(
                "selected_pair"
            )

            if pair:
                segment[
                    "legacy_v0106_start_seconds"
                ] = segment.get(
                    "start_seconds"
                )
                segment[
                    "legacy_v0106_end_seconds"
                ] = segment.get(
                    "end_seconds"
                )

                segment[
                    "start_seconds"
                ] = pair[
                    "start_seconds"
                ]
                segment[
                    "end_seconds"
                ] = pair[
                    "end_seconds"
                ]
                segment[
                    "duration_seconds"
                ] = pair[
                    "duration_seconds"
                ]
                segment[
                    "start_source"
                ] = (
                    "exhaustive_multimodal_state_pair"
                )
                segment[
                    "end_source"
                ] = (
                    "exhaustive_multimodal_state_pair"
                )
                segment[
                    "selected_state_pair"
                ] = pair
                segment[
                    "multimodal_boundary_confidence"
                ] = pair[
                    "pair_score"
                ]
                segment[
                    "boundary_resolved"
                ] = True
            else:
                # CRITICAL FIX: never silently retain v0.10.5/v0.10.6 fallback
                # as though it were a valid current boundary.
                segment[
                    "legacy_unresolved_start_seconds"
                ] = segment.get(
                    "start_seconds"
                )
                segment[
                    "legacy_unresolved_end_seconds"
                ] = segment.get(
                    "end_seconds"
                )
                segment[
                    "start_source"
                ] = (
                    "unresolved_multimodal_state_pair"
                )
                segment[
                    "end_source"
                ] = (
                    "unresolved_multimodal_state_pair"
                )
                segment[
                    "multimodal_boundary_confidence"
                ] = 0.0
                segment[
                    "boundary_resolved"
                ] = False

            diagnostics.append(
                {
                    "segment_id": (
                        segment.get(
                            "segment_id"
                        )
                    ),
                    "type": seg_type,
                    "window_start_seconds": round(
                        window_start,
                        3,
                    ),
                    "window_end_seconds": round(
                        window_end,
                        3,
                    ),
                    "state_pair_selection": (
                        selection
                    ),
                }
            )

        elif seg_type == "end_card":
            raw_start = float(
                segment.get(
                    "original_ocr_start_seconds"
                )
                or segment.get(
                    "start_seconds"
                )
                or max(
                    0.0,
                    duration - 3.0,
                )
            )

            window_start = max(
                0.0,
                raw_start - 7.0,
            )

            timeline = (
                _multimodal_feature_timeline(
                    video_path,
                    window_start,
                    duration,
                    req,
                )
            )

            selection = (
                _exhaustive_final_regime(
                    timeline,
                    raw_start,
                    duration,
                    req,
                )
            )

            if (
                selection
                and selection.get(
                    "selected"
                )
            ):
                selected = selection[
                    "selected"
                ]

                proposed = max(
                    0.0,
                    float(
                        selected[
                            "time_seconds"
                        ]
                    )
                    - float(
                        req.end_card_pre_cut_padding_seconds
                    ),
                )

                segment[
                    "legacy_v0106_start_seconds"
                ] = segment.get(
                    "start_seconds"
                )
                segment[
                    "start_seconds"
                ] = round(
                    proposed,
                    3,
                )
                segment[
                    "start_source"
                ] = (
                    "exhaustive_persistent_final_state"
                )
                segment[
                    "multimodal_boundary_confidence"
                ] = selected[
                    "score"
                ]
                segment[
                    "boundary_resolved"
                ] = True
                segment[
                    "selected_final_state"
                ] = selected
            else:
                segment[
                    "boundary_resolved"
                ] = False
                segment[
                    "multimodal_boundary_confidence"
                ] = 0.0

            diagnostics.append(
                {
                    "segment_id": (
                        segment.get(
                            "segment_id"
                        )
                    ),
                    "type": seg_type,
                    "window_start_seconds": round(
                        window_start,
                        3,
                    ),
                    "window_end_seconds": round(
                        duration,
                        3,
                    ),
                    "final_state_selection": (
                        selection
                    ),
                }
            )

    result["version"] = "0.10.7"

    result.setdefault(
        "diagnostics",
        {},
    )[
        "exhaustive_multimodal_state_segmentation"
    ] = diagnostics

    result["policy"] = {
        **(
            result.get(
                "policy"
            )
            or {}
        ),
        "state_segmentation": (
            "Optional segment boundaries are evaluated directly as "
            "PRE -> INSIDE -> POST state changes. No previous boundary is "
            "retained when the current detector cannot resolve a reliable pair."
        ),
    }

    report_rel = result.get(
        "report_relative_path"
    )

    if report_rel:
        _safe_workspace_path(
            report_rel
        ).write_text(
            json.dumps(
                result,
                ensure_ascii=False,
                indent=2,
            ),
            encoding="utf-8",
        )

    return result


_mid_promo_structure_decision_v0106 = (
    _mid_promo_structure_decision
)


def _mid_promo_structure_decision(
    router,
    segment,
    present_threshold,
    uncertain_threshold,
):
    result = (
        _mid_promo_structure_decision_v0106(
            router,
            segment,
            present_threshold,
            uncertain_threshold,
        )
    )

    if not segment:
        return result

    resolved = bool(
        segment.get(
            "boundary_resolved"
        )
    )

    conf = float(
        segment.get(
            "multimodal_boundary_confidence"
        )
        or 0.0
    )

    if (
        segment.get(
            "start_source"
        )
        == "exhaustive_multimodal_state_pair"
        and resolved
    ):
        result[
            "boundary_confidence"
        ] = round(
            conf,
            6,
        )
        result[
            "boundary_method"
        ] = (
            "exhaustive_PRE_INSIDE_POST_multimodal_state_pair"
        )
        result[
            "plan_eligible"
        ] = bool(
            result.get(
                "presence"
            )
            == "PRESENT"
            and conf >= 0.58
        )
    else:
        # Presence may remain PRESENT, but unresolved boundary can never be
        # eligible for editing.
        result[
            "boundary_confidence"
        ] = 0.0
        result[
            "boundary_method"
        ] = (
            "unresolved"
        )
        result[
            "plan_eligible"
        ] = False

    return result


_end_card_structure_decision_v0106 = (
    _end_card_structure_decision
)


def _end_card_structure_decision(
    router,
    segment,
    video_duration,
    present_threshold,
    uncertain_threshold,
):
    result = (
        _end_card_structure_decision_v0106(
            router,
            segment,
            video_duration,
            present_threshold,
            uncertain_threshold,
        )
    )

    if not segment:
        return result

    resolved = bool(
        segment.get(
            "boundary_resolved"
        )
    )

    conf = float(
        segment.get(
            "multimodal_boundary_confidence"
        )
        or 0.0
    )

    if (
        segment.get(
            "start_source"
        )
        == "exhaustive_persistent_final_state"
        and resolved
    ):
        result[
            "boundary_confidence"
        ] = round(
            conf,
            6,
        )
        result[
            "boundary_method"
        ] = (
            "exhaustive_persistent_final_multimodal_state"
        )
        result[
            "plan_eligible"
        ] = bool(
            result.get(
                "presence"
            )
            == "PRESENT"
            and conf >= 0.56
        )
    elif not resolved:
        result[
            "boundary_confidence"
        ] = 0.0
        result[
            "boundary_method"
        ] = "unresolved"
        result[
            "plan_eligible"
        ] = False

    return result




# ---------------------------------------------------------------------------
# v0.10.8 Subtitle Transition Semantics
#
# CRITICAL SEMANTIC RULE:
#   "white subtitle background" is NOT a Promo label.
#
# Subtitle layout contributes only as a CHANGE signal:
#
#   no plate -> plate
#   plate -> no plate
#   weak/compact -> large/persistent plate
#   large/persistent plate -> weak/compact
#
# Both directions are equally valid structural boundaries.
#
# Promo identity still comes from independent evidence:
# brand anchor + sustained content regime + multimodal context.
# ---------------------------------------------------------------------------


def _subtitle_plate_state(
    white_ratio,
):
    ratio = float(
        white_ratio
        or 0.0
    )

    # Hysteresis-like three-state representation.
    # These are layout-state bins, NOT semantic labels.
    if ratio >= 0.030:
        return "PLATE_ON"

    if ratio <= 0.012:
        return "PLATE_OFF"

    return "PLATE_MIXED"


def _subtitle_transition(
    before_ratio,
    after_ratio,
):
    before = float(
        before_ratio
        or 0.0
    )
    after = float(
        after_ratio
        or 0.0
    )

    before_state = (
        _subtitle_plate_state(
            before
        )
    )

    after_state = (
        _subtitle_plate_state(
            after
        )
    )

    delta = after - before

    magnitude = min(
        1.0,
        abs(
            delta
        )
        / 0.055,
    )

    state_changed = (
        before_state
        != after_state
    )

    # Explicit OFF <-> ON flips are strong, and both directions receive the
    # exact same treatment.
    hard_flip = {
        before_state,
        after_state,
    } == {
        "PLATE_OFF",
        "PLATE_ON",
    }

    score = float(
        magnitude
    )

    if hard_flip:
        score = max(
            score,
            0.82,
        )
    elif state_changed:
        score = max(
            score,
            0.52,
        )

    if delta > 0.004:
        direction = (
            "LESS_PLATE_TO_MORE_PLATE"
        )
    elif delta < -0.004:
        direction = (
            "MORE_PLATE_TO_LESS_PLATE"
        )
    else:
        direction = (
            "NO_MEANINGFUL_PLATE_CHANGE"
        )

    return {
        "score": round(
            min(
                1.0,
                score,
            ),
            6,
        ),
        "before_ratio": round(
            before,
            6,
        ),
        "after_ratio": round(
            after,
            6,
        ),
        "before_state": (
            before_state
        ),
        "after_state": (
            after_state
        ),
        "state_changed": bool(
            state_changed
        ),
        "hard_flip": bool(
            hard_flip
        ),
        "direction": direction,
        "semantic_rule": (
            "layout_change_only_not_promo_label"
        ),
    }


# Override regime-distance semantics so subtitle-layout distance is explicitly
# direction-neutral. Existing callers continue to work because the public
# scalar fields remain unchanged.
def _regime_modality_distance(
    a,
    b,
):
    if not a or not b:
        return {
            "visual": 0.0,
            "subtitle_layout": 0.0,
            "audio": 0.0,
            "consensus": 0.0,
            "subtitle_transition": {
                "score": 0.0,
                "before_ratio": 0.0,
                "after_ratio": 0.0,
                "before_state": "PLATE_OFF",
                "after_state": "PLATE_OFF",
                "state_changed": False,
                "hard_flip": False,
                "direction": (
                    "NO_MEANINGFUL_PLATE_CHANGE"
                ),
                "semantic_rule": (
                    "layout_change_only_not_promo_label"
                ),
            },
        }

    hist_delta = _cosine_distance(
        a["hist"],
        b["hist"],
    )

    edge_delta = min(
        1.0,
        abs(
            float(a["edge"])
            - float(b["edge"])
        )
        / 0.085,
    )

    visual = min(
        1.0,
        0.72 * hist_delta
        + 0.28 * edge_delta,
    )

    subtitle_transition = (
        _subtitle_transition(
            a["white"],
            b["white"],
        )
    )

    subtitle = float(
        subtitle_transition[
            "score"
        ]
    )

    scales = np.asarray(
        [
            0.28,
            0.055,
            0.15,
            0.17,
            0.18,
            0.15,
        ],
        dtype=np.float32,
    )

    audio = float(
        np.mean(
            np.minimum(
                1.0,
                np.abs(
                    np.asarray(
                        a["audio"],
                        dtype=np.float32,
                    )
                    - np.asarray(
                        b["audio"],
                        dtype=np.float32,
                    )
                )
                / scales,
            )
        )
    )

    scores = sorted(
        [
            float(visual),
            float(subtitle),
            float(audio),
        ],
        reverse=True,
    )

    consensus = (
        0.52 * scores[0]
        + 0.33 * scores[1]
        + 0.15 * scores[2]
    )

    return {
        "visual": round(
            float(visual),
            6,
        ),
        "subtitle_layout": round(
            float(subtitle),
            6,
        ),
        "audio": round(
            float(audio),
            6,
        ),
        "consensus": round(
            float(consensus),
            6,
        ),
        "subtitle_transition": (
            subtitle_transition
        ),
    }


def _subtitle_inside_state_summary(
    pre_items,
    inside_items,
    post_items,
):
    pre_ratio = _mean_scalar(
        pre_items,
        "visual",
        "subtitle_white_plate_ratio",
    )

    inside_ratio = _mean_scalar(
        inside_items,
        "visual",
        "subtitle_white_plate_ratio",
    )

    post_ratio = _mean_scalar(
        post_items,
        "visual",
        "subtitle_white_plate_ratio",
    )

    start_transition = (
        _subtitle_transition(
            pre_ratio,
            inside_ratio,
        )
    )

    end_transition = (
        _subtitle_transition(
            inside_ratio,
            post_ratio,
        )
    )

    return {
        "pre_state": (
            _subtitle_plate_state(
                pre_ratio
            )
        ),
        "inside_state": (
            _subtitle_plate_state(
                inside_ratio
            )
        ),
        "post_state": (
            _subtitle_plate_state(
                post_ratio
            )
        ),
        "pre_ratio": round(
            pre_ratio,
            6,
        ),
        "inside_ratio": round(
            inside_ratio,
            6,
        ),
        "post_ratio": round(
            post_ratio,
            6,
        ),
        "start_transition": (
            start_transition
        ),
        "end_transition": (
            end_transition
        ),
        "interpretation": (
            "Only state transition matters. PLATE_ON and PLATE_OFF are both "
            "valid inside or outside states; neither state means Promo."
        ),
    }


# Preserve the v0.10.7 pair generator and enrich its diagnostics / scoring
# semantics. The core selection remains PRE -> INSIDE -> POST.
_exhaustive_promo_state_pairs_v0107 = (
    _exhaustive_promo_state_pairs
)


def _exhaustive_promo_state_pairs(
    timeline,
    brand_evidence_start,
    brand_evidence_end,
    req,
):
    pairs = (
        _exhaustive_promo_state_pairs_v0107(
            timeline,
            brand_evidence_start,
            brand_evidence_end,
            req,
        )
    )

    enriched = []

    for pair in pairs:
        start = float(
            pair["start_seconds"]
        )
        end = float(
            pair["end_seconds"]
        )

        pre = _timeline_slice(
            timeline,
            start - 4.0,
            start - 0.75,
        )

        # Use a broad inside slice so the detected subtitle state represents the
        # segment, not a single caption frame.
        inside = _timeline_slice(
            timeline,
            start + 1.0,
            end - 1.0,
        )

        post = _timeline_slice(
            timeline,
            end + 0.75,
            min(
                float(
                    timeline[-1][
                        "time_seconds"
                    ]
                ),
                end + 4.0,
            ),
        )

        subtitle_summary = (
            _subtitle_inside_state_summary(
                pre,
                inside,
                post,
            )
        )

        pair = dict(
            pair
        )

        pair[
            "subtitle_state_summary"
        ] = (
            subtitle_summary
        )

        # Important: no positive reward for PLATE_ON itself.
        # Only reward a clear change across a boundary.
        start_change = float(
            subtitle_summary[
                "start_transition"
            ][
                "score"
            ]
        )

        end_change = float(
            subtitle_summary[
                "end_transition"
            ][
                "score"
            ]
        )

        old_score = float(
            pair.get(
                "pair_score"
            )
            or 0.0
        )

        transition_bonus = (
            0.025 * start_change
            + 0.020 * end_change
        )

        pair[
            "pair_score"
        ] = round(
            min(
                0.98,
                old_score
                + transition_bonus,
            ),
            6,
        )

        enriched.append(
            pair
        )

    enriched.sort(
        key=lambda x: (
            float(
                x["pair_score"]
            ),
            float(
                x.get(
                    "internal_stability"
                )
                or 0.0
            ),
        ),
        reverse=True,
    )

    return enriched


