def _semantic_norm(text):
    value = str(
        text
        or ""
    )

    value = unicodedata.normalize(
        "NFKD",
        value,
    )

    value = "".join(
        ch
        for ch in value
        if not unicodedata.combining(
            ch
        )
    )

    value = value.lower()

    value = re.sub(
        r"[^a-z0-9]+",
        " ",
        value,
    )

    return re.sub(
        r"\s+",
        " ",
        value,
    ).strip()


def _semantic_phrase_score(
    text,
    phrase_weights,
):
    norm = _semantic_norm(
        text
    )

    if not norm:
        return {
            "score": 0.0,
            "matches": [],
        }

    matches = []

    for phrase, weight in phrase_weights.items():
        p = _semantic_norm(
            phrase
        )

        if p and p in norm:
            matches.append(
                {
                    "phrase": phrase,
                    "weight": float(
                        weight
                    ),
                }
            )

    if not matches:
        return {
            "score": 0.0,
            "matches": [],
        }

    # Multiple distinct semantic signals reinforce one another without
    # exceeding 1.0.
    matches.sort(
        key=lambda x: float(
            x["weight"]
        ),
        reverse=True,
    )

    score = float(
        matches[0][
            "weight"
        ]
    )

    for extra in matches[1:4]:
        score += (
            0.18
            * float(
                extra[
                    "weight"
                ]
            )
            * (
                1.0
                - min(
                    1.0,
                    score,
                )
            )
        )

    return {
        "score": round(
            min(
                1.0,
                score,
            ),
            6,
        ),
        "matches": matches[
            :8
        ],
    }


def _semantic_ocr_frame(
    frame,
    req,
):
    try:
        words = _tesseract_words(
            frame,
            str(
                req.ocr_language
            ),
            float(
                req.ocr_min_confidence
            ),
            float(
                req.ocr_scale
            ),
        )
    except Exception as exc:
        return {
            "text": "",
            "words": [],
            "error": str(
                exc
            )[:300],
        }

    text = " ".join(
        str(
            word.get(
                "text"
            )
            or ""
        ).strip()
        for word in words
        if str(
            word.get(
                "text"
            )
            or ""
        ).strip()
    )

    return {
        "text": text,
        "words": words,
        "error": None,
    }


def _semantic_overlay_text(
    frame,
    words,
):
    h, w = frame.shape[:2]

    pieces = []

    for word in words or []:
        bbox = _word_bbox(
            word
        )

        _, cy = _bbox_center(
            bbox
        )

        # Ignore persistent top-corner brand/logo OCR and normal bottom
        # narrative subtitles. This region is the extra callout layer.
        if cy <= 0.16 * h:
            continue

        if cy >= 0.82 * h:
            continue

        height_ratio = (
            float(
                bbox["height"]
            )
            / float(
                max(
                    1,
                    h,
                )
            )
        )

        area_ratio = (
            float(
                bbox["width"]
                * bbox["height"]
            )
            / float(
                max(
                    1,
                    w * h,
                )
            )
        )

        if (
            height_ratio >= 0.018
            or area_ratio >= 0.0010
        ):
            value = str(
                word.get(
                    "text"
                )
                or ""
            ).strip()

            if value:
                pieces.append(
                    value
                )

    return " ".join(
        pieces
    )


def _whisper_transcribe_semantic(
    video_path,
    req,
):
    if not bool(
        req.enable_whisper
    ):
        return {
            "status": "DISABLED",
            "segments": [],
            "model": None,
            "language": None,
            "error": None,
        }

    try:
        from faster_whisper import (
            WhisperModel,
        )
    except Exception as exc:
        return {
            "status": "UNAVAILABLE",
            "segments": [],
            "model": None,
            "language": None,
            "error": (
                "faster_whisper import failed: "
                + str(exc)[:300]
            ),
        }

    model_name = (
        str(
            req.whisper_model
            or os.getenv(
                "WHISPER_MODEL",
                "base",
            )
        ).strip()
        or "base"
    )

    # v0.18.10.9.7: Load faster-whisper strictly from the local cache when it is
    # available (model files are mounted at /model-cache and validated before a
    # render starts). A network model lookup must never hold a production edit
    # for minutes; local_files_only makes a missing cache fail fast and offline.
    download_root = str(
        os.getenv("WHISPER_CACHE_DIR") or ""
    ).strip() or None
    local_files_only = (
        os.getenv("WHISPER_LOCAL_FILES_ONLY", "true")
        .strip()
        .lower()
        in {"1", "true", "yes", "on"}
    )

    global _SEMANTIC_WHISPER_MODEL, _SEMANTIC_WHISPER_MODEL_KEY
    try:
        model_key = (
            model_name,
            str(req.whisper_device),
            str(req.whisper_compute_type),
            download_root,
            bool(local_files_only),
        )
        with _SEMANTIC_WHISPER_MODEL_LOCK:
            if _SEMANTIC_WHISPER_MODEL is None or _SEMANTIC_WHISPER_MODEL_KEY != model_key:
                try:
                    cpu_threads = max(1, min(16, int(os.getenv("WHISPER_CPU_THREADS", "4"))))
                except Exception:
                    cpu_threads = 4
                _SEMANTIC_WHISPER_MODEL = WhisperModel(
                    model_name,
                    device=str(req.whisper_device),
                    compute_type=str(req.whisper_compute_type),
                    download_root=download_root,
                    local_files_only=local_files_only,
                    cpu_threads=cpu_threads,
                    num_workers=1,
                )
                _SEMANTIC_WHISPER_MODEL_KEY = model_key
            model = _SEMANTIC_WHISPER_MODEL

        segments_iter, info = (
            model.transcribe(
                str(
                    video_path
                ),
                beam_size=1,
                vad_filter=True,
                condition_on_previous_text=True,
            )
        )

        segments = []

        for seg in segments_iter:
            value = str(
                getattr(
                    seg,
                    "text",
                    "",
                )
                or ""
            ).strip()

            if not value:
                continue

            segments.append(
                {
                    "start_seconds": round(
                        float(
                            getattr(
                                seg,
                                "start",
                                0.0,
                            )
                            or 0.0
                        ),
                        3,
                    ),
                    "end_seconds": round(
                        float(
                            getattr(
                                seg,
                                "end",
                                0.0,
                            )
                            or 0.0
                        ),
                        3,
                    ),
                    "text": value,
                }
            )

        language = getattr(
            info,
            "language",
            None,
        )

        return {
            "status": "OK",
            "segments": segments,
            "model": model_name,
            "language": language,
            "error": None,
        }

    except Exception as exc:
        return {
            "status": "FAILED",
            "segments": [],
            "model": model_name,
            "language": None,
            "error": str(
                exc
            )[:500],
        }


def _speech_at_time(
    whisper_segments,
    t,
    radius=0.75,
):
    t = float(t)

    texts = []

    for seg in whisper_segments or []:
        start = float(
            seg.get(
                "start_seconds"
            )
            or 0.0
        )
        end = float(
            seg.get(
                "end_seconds"
            )
            or start
        )

        if (
            end >= t - float(
                radius
            )
            and start <= t + float(
                radius
            )
        ):
            value = str(
                seg.get(
                    "text"
                )
                or ""
            ).strip()

            if value:
                texts.append(
                    value
                )

    return " ".join(
        texts
    )


def _semantic_router_evidence(
    router,
    t,
    duration,
):
    t = float(t)

    brand_anchor = 0.0
    end_card = 0.0

    for layer in (
        router.get(
            "watermark_layers"
        )
        or []
    ):
        layer_type = str(
            layer.get(
                "type"
            )
            or ""
        )

        evidence = (
            layer.get(
                "evidence"
            )
            or {}
        )

        t0 = evidence.get(
            "time_min_seconds"
        )
        t1 = evidence.get(
            "time_max_seconds"
        )

        if t0 is None:
            continue

        t0 = float(
            t0
        )
        t1 = float(
            t1
            if t1 is not None
            else t0
        )

        if layer_type == "unclassified_brand_text":
            if (
                t0 - 2.0
                <= t
                <= t1 + 2.0
            ):
                brand_anchor = max(
                    brand_anchor,
                    float(
                        layer.get(
                            "confidence"
                        )
                        or 0.65
                    ),
                )

        elif layer_type == "end_card":
            if (
                t0 - 3.0
                <= t
                <= t1 + 1.0
            ):
                end_card = max(
                    end_card,
                    float(
                        layer.get(
                            "confidence"
                        )
                        or 0.75
                    ),
                )

    # Router end-card evidence is only meaningful near the end.
    if (
        duration > 0
        and t
        < duration - 20.0
    ):
        end_card = 0.0

    return {
        "brand_anchor": min(
            1.0,
            brand_anchor,
        ),
        "end_card": min(
            1.0,
            end_card,
        ),
    }


def _semantic_sample_scores(
    full_ocr_text,
    overlay_text,
    speech_text,
    overlay_activity,
    router_evidence,
    t,
    duration,
    req,
):
    ocr_promo = (
        _semantic_phrase_score(
            full_ocr_text,
            _SEMANTIC_PROMO_PHRASES,
        )
    )

    overlay_promo = (
        _semantic_phrase_score(
            overlay_text,
            _SEMANTIC_PROMO_PHRASES,
        )
    )

    speech_promo = (
        _semantic_phrase_score(
            speech_text,
            _SEMANTIC_PROMO_PHRASES,
        )
    )

    ocr_cta = (
        _semantic_phrase_score(
            full_ocr_text,
            _SEMANTIC_CTA_PHRASES,
        )
    )

    overlay_cta = (
        _semantic_phrase_score(
            overlay_text,
            _SEMANTIC_CTA_PHRASES,
        )
    )

    speech_cta = (
        _semantic_phrase_score(
            speech_text,
            _SEMANTIC_CTA_PHRASES,
        )
    )

    promo_text_semantic = max(
        float(
            ocr_promo[
                "score"
            ]
        ),
        float(
            overlay_promo[
                "score"
            ]
        ),
    )

    promo_speech_semantic = float(
        speech_promo[
            "score"
        ]
    )

    cta_semantic = max(
        float(
            ocr_cta[
                "score"
            ]
        ),
        float(
            overlay_cta[
                "score"
            ]
        ),
        float(
            speech_cta[
                "score"
            ]
        ),
    )

    brand_anchor = float(
        router_evidence.get(
            "brand_anchor"
        )
        or 0.0
    )

    router_end = float(
        router_evidence.get(
            "end_card"
        )
        or 0.0
    )

    # Extra overlay activity is deliberately weak. Its semantic text matters
    # much more than merely being present.
    promo = (
        0.42
        * promo_text_semantic
        + 0.34
        * promo_speech_semantic
        + 0.10
        * min(
            1.0,
            float(
                overlay_activity
            ),
        )
        + 0.14
        * brand_anchor
    )

    # Strong phrase semantics should not be diluted too much by absent speech.
    promo = max(
        promo,
        0.72
        * promo_text_semantic,
        0.72
        * promo_speech_semantic,
    )

    near_end = 0.0

    if duration > 0:
        distance_to_end = max(
            0.0,
            float(
                duration
            )
            - float(t),
        )

        near_end = max(
            0.0,
            min(
                1.0,
                (
                    float(
                        req.end_card_search_seconds
                    )
                    - distance_to_end
                )
                / max(
                    1.0,
                    float(
                        req.end_card_search_seconds
                    ),
                )
                + 0.25,
            ),
        )

    end_card = (
        0.48
        * cta_semantic
        + 0.30
        * router_end
        + 0.22
        * near_end
    )

    if router_end >= 0.75:
        end_card = max(
            end_card,
            0.58
            * router_end
            + 0.20
            * near_end,
        )

    # STORY is not a language-specific classifier here. It is a default state
    # when sustained promotional/end-card semantics are absent.
    story = max(
        0.0,
        1.0
        - max(
            promo,
            end_card,
        ),
    )

    return {
        "promo": round(
            min(
                1.0,
                promo,
            ),
            6,
        ),
        "end_card": round(
            min(
                1.0,
                end_card,
            ),
            6,
        ),
        "story": round(
            min(
                1.0,
                story,
            ),
            6,
        ),
        "signals": {
            "ocr_promo": ocr_promo,
            "overlay_promo": (
                overlay_promo
            ),
            "speech_promo": (
                speech_promo
            ),
            "ocr_cta": ocr_cta,
            "overlay_cta": (
                overlay_cta
            ),
            "speech_cta": (
                speech_cta
            ),
            "brand_anchor": round(
                brand_anchor,
                6,
            ),
            "router_end_card": round(
                router_end,
                6,
            ),
            "near_end": round(
                near_end,
                6,
            ),
            "extra_overlay_activity": round(
                float(
                    overlay_activity
                ),
                6,
            ),
        },
    }


def _smooth_semantic_scores(
    timeline,
    radius,
):
    radius = max(
        0,
        int(
            radius
        ),
    )

    if radius <= 0:
        for item in timeline:
            item[
                "smoothed_scores"
            ] = dict(
                item[
                    "semantic_scores"
                ]
            )
        return timeline

    n = len(
        timeline
    )

    for i, item in enumerate(
        timeline
    ):
        lo = max(
            0,
            i - radius,
        )
        hi = min(
            n,
            i + radius + 1,
        )

        window = timeline[
            lo:hi
        ]

        smoothed = {}

        for key in (
            "promo",
            "end_card",
            "story",
        ):
            values = [
                float(
                    x[
                        "semantic_scores"
                    ][key]
                )
                for x in window
            ]

            # Center has slightly more weight to avoid over-smearing edges.
            center_value = float(
                item[
                    "semantic_scores"
                ][key]
            )

            smoothed[key] = round(
                0.55
                * float(
                    np.mean(
                        values
                    )
                )
                + 0.45
                * center_value,
                6,
            )

        item[
            "smoothed_scores"
        ] = smoothed

    return timeline


def _semantic_raw_state(
    item,
    duration,
    req,
):
    scores = item[
        "smoothed_scores"
    ]

    t = float(
        item[
            "time_seconds"
        ]
    )

    if (
        duration > 0
        and t
        >= duration
        - float(
            req.end_card_search_seconds
        )
        and float(
            scores[
                "end_card"
            ]
        )
        >= float(
            req.end_card_score_threshold
        )
        and float(
            scores[
                "end_card"
            ]
        )
        >= float(
            scores[
                "promo"
            ]
        )
        - 0.04
    ):
        return "END_CARD"

    if (
        float(
            scores[
                "promo"
            ]
        )
        >= float(
            req.promo_score_threshold
        )
    ):
        return "PROMO"

    # STORY is the conservative default. UNKNOWN is used only when competing
    # semantic scores are close but both sub-threshold.
    if max(
        float(
            scores[
                "promo"
            ]
        ),
        float(
            scores[
                "end_card"
            ]
        ),
    ) >= 0.38:
        return "UNKNOWN"

    return "STORY"


def _bridge_short_state_gaps(
    labels,
    target_state,
    max_gap_samples,
):
    labels = list(
        labels
    )

    max_gap_samples = max(
        0,
        int(
            max_gap_samples
        ),
    )

    if max_gap_samples <= 0:
        return labels

    i = 0
    n = len(
        labels
    )

    while i < n:
        if labels[i] == target_state:
            i += 1
            continue

        start = i

        while (
            i < n
            and labels[i]
            != target_state
        ):
            i += 1

        end = i - 1

        gap_len = (
            end - start + 1
        )

        left_ok = (
            start - 1 >= 0
            and labels[
                start - 1
            ]
            == target_state
        )

        right_ok = (
            i < n
            and labels[i]
            == target_state
        )

        if (
            left_ok
            and right_ok
            and gap_len
            <= max_gap_samples
        ):
            for j in range(
                start,
                end + 1,
            ):
                labels[j] = (
                    target_state
                )

    return labels


def _state_runs(
    timeline,
    labels,
    state,
    sample_interval,
):
    runs = []

    i = 0
    n = len(
        labels
    )

    while i < n:
        if labels[i] != state:
            i += 1
            continue

        start_idx = i

        while (
            i + 1 < n
            and labels[
                i + 1
            ]
            == state
        ):
            i += 1

        end_idx = i

        first_t = float(
            timeline[
                start_idx
            ][
                "time_seconds"
            ]
        )

        last_t = float(
            timeline[
                end_idx
            ][
                "time_seconds"
            ]
        )

        if start_idx > 0:
            prev_t = float(
                timeline[
                    start_idx - 1
                ][
                    "time_seconds"
                ]
            )
            start_t = (
                prev_t
                + first_t
            ) / 2.0
        else:
            start_t = max(
                0.0,
                first_t
                - sample_interval / 2.0,
            )

        if end_idx + 1 < n:
            next_t = float(
                timeline[
                    end_idx + 1
                ][
                    "time_seconds"
                ]
            )
            end_t = (
                last_t
                + next_t
            ) / 2.0
        else:
            end_t = (
                last_t
                + sample_interval / 2.0
            )

        score_key = (
            "promo"
            if state == "PROMO"
            else "end_card"
        )

        values = [
            float(
                timeline[j][
                    "smoothed_scores"
                ][
                    score_key
                ]
            )
            for j in range(
                start_idx,
                end_idx + 1,
            )
        ]

        runs.append(
            {
                "state": state,
                "start_index": (
                    start_idx
                ),
                "end_index": (
                    end_idx
                ),
                "start_seconds": round(
                    start_t,
                    3,
                ),
                "end_seconds": round(
                    end_t,
                    3,
                ),
                "duration_seconds": round(
                    max(
                        0.0,
                        end_t - start_t,
                    ),
                    3,
                ),
                "mean_semantic_score": round(
                    float(
                        np.mean(
                            values
                        )
                    ),
                    6,
                ),
                "peak_semantic_score": round(
                    float(
                        max(
                            values
                        )
                    ),
                    6,
                ),
            }
        )

        i += 1

    return runs


def _semantic_boundary_refine(
    video_path,
    approx_time,
    router_report_relative_path,
    radius_seconds,
):
    approx = float(
        approx_time
    )

    radius = max(
        0.75,
        float(
            radius_seconds
        ),
    )

    try:
        mm_req = (
            BrandingReplacementSegmentCensusRequest(
                router_report_relative_path=(
                    router_report_relative_path
                ),
                multimodal_sample_interval_seconds=0.25,
                text_layer_scan_interval_seconds=0.5,
            )
        )

        start = max(
            0.0,
            approx - radius,
        )

        end = (
            approx + radius
        )

        timeline = (
            _multimodal_feature_timeline(
                video_path,
                start,
                end,
                mm_req,
            )
        )

        candidates = []

        for item in timeline:
            t = float(
                item[
                    "time_seconds"
                ]
            )

            if (
                t
                <= start + 1.0
                or t
                >= end - 1.0
            ):
                continue

            pre = _timeline_slice(
                timeline,
                t - 1.25,
                t - 0.25,
            )

            post = _timeline_slice(
                timeline,
                t + 0.25,
                t + 1.25,
            )

            if (
                len(pre) < 2
                or len(post) < 2
            ):
                continue

            transition = (
                _state_transition_modalities(
                    pre,
                    post,
                )
            )

            if not transition:
                continue

            score = float(
                transition[
                    "consensus"
                ]
            )

            # Keep refinement local to the semantic state transition.
            locality = max(
                0.0,
                1.0
                - abs(
                    t - approx
                )
                / max(
                    0.1,
                    radius,
                ),
            )

            combined = (
                0.78
                * score
                + 0.22
                * locality
            )

            candidates.append(
                {
                    "time_seconds": round(
                        t,
                        3,
                    ),
                    "transition_score": round(
                        score,
                        6,
                    ),
                    "locality_score": round(
                        locality,
                        6,
                    ),
                    "combined_score": round(
                        combined,
                        6,
                    ),
                    "modalities": (
                        transition
                    ),
                }
            )

        if not candidates:
            return {
                "resolved": False,
                "approx_seconds": round(
                    approx,
                    3,
                ),
                "refined_seconds": round(
                    approx,
                    3,
                ),
                "confidence": 0.0,
                "candidates": [],
            }

        candidates.sort(
            key=lambda x: float(
                x[
                    "combined_score"
                ]
            ),
            reverse=True,
        )

        best = candidates[0]

        return {
            "resolved": True,
            "approx_seconds": round(
                approx,
                3,
            ),
            "refined_seconds": (
                best[
                    "time_seconds"
                ]
            ),
            "confidence": (
                best[
                    "combined_score"
                ]
            ),
            "best_transition": (
                best
            ),
            "candidates": candidates[
                :12
            ],
        }

    except Exception as exc:
        return {
            "resolved": False,
            "approx_seconds": round(
                approx,
                3,
            ),
            "refined_seconds": round(
                approx,
                3,
            ),
            "confidence": 0.0,
            "error": str(
                exc
            )[:500],
            "candidates": [],
        }


def _semantic_structure_census_sync(
    req: BrandingSemanticStructureRequest
):
    router_path, router = (
        _read_json_workspace(
            req.router_report_relative_path,
            "semantic_structure_census",
        )
    )

    source_rel = (
        (router.get(
            "source"
        ) or {}).get(
            "relative_path"
        )
    )

    if not source_rel:
        raise HTTPException(
            status_code=422,
            detail=(
                "Router report has no source.relative_path."
            ),
        )

    video_path = (
        _safe_workspace_path(
            source_rel
        )
    )

    cap = cv2.VideoCapture(
        str(
            video_path
        )
    )

    if not cap.isOpened():
        raise HTTPException(
            status_code=422,
            detail=(
                "Could not open source video."
            ),
        )

    try:
        meta = _video_metadata(
            cap
        )
    finally:
        cap.release()

    duration = float(
        meta.get(
            "duration_seconds"
        )
        or 0.0
    )

    interval = float(
        req.sample_interval_seconds
    )

    if not (
        0.5
        <= interval
        <= 5.0
    ):
        raise HTTPException(
            status_code=422,
            detail=(
                "sample_interval_seconds must be between 0.5 and 5."
            ),
        )

    whisper = (
        _whisper_transcribe_semantic(
            video_path,
            req,
        )
    )

    cap = cv2.VideoCapture(
        str(
            video_path
        )
    )

    if not cap.isOpened():
        raise HTTPException(
            status_code=422,
            detail=(
                "Could not reopen source video."
            ),
        )

    timeline = []

    sample_index = 0
    t = 0.0

    try:
        while (
            t
            <= duration + 1e-6
            if duration > 0
            else sample_index == 0
        ):
            _operator_raise_if_cancelled()
            if (
                sample_index
                >= int(
                    req.max_samples
                )
            ):
                break

            cap.set(
                cv2.CAP_PROP_POS_MSEC,
                t * 1000.0,
            )

            ok, frame = cap.read()

            if (
                not ok
                or frame is None
            ):
                break

            ocr = (
                _semantic_ocr_frame(
                    frame,
                    req,
                )
            )

            overlay_text = (
                _semantic_overlay_text(
                    frame,
                    ocr[
                        "words"
                    ],
                )
            )

            # Reuse the v0.10.9 extra text-layer activity detector with a small
            # attribute shim because its semantics are still useful here.
            class _TLReq:
                pass

            tl_req = _TLReq()
            tl_req.promo_ocr_language = (
                req.ocr_language
            )
            tl_req.promo_ocr_min_confidence = (
                req.ocr_min_confidence
            )
            tl_req.promo_ocr_scale = (
                req.ocr_scale
            )
            tl_req.narrative_subtitle_y_ratio = (
                0.82
            )
            tl_req.persistent_brand_top_y_ratio = (
                0.16
            )
            tl_req.promo_overlay_min_height_ratio = (
                0.020
            )
            tl_req.promo_overlay_large_height_ratio = (
                0.035
            )
            tl_req.promo_overlay_min_area_ratio = (
                0.0012
            )

            try:
                text_layers = (
                    _text_layer_features(
                        frame,
                        tl_req,
                        words=ocr[
                            "words"
                        ],
                    )
                )
            except Exception:
                text_layers = {
                    "promo_overlay_activity": (
                        0.0
                    ),
                }

            speech_text = (
                _speech_at_time(
                    whisper.get(
                        "segments"
                    )
                    or [],
                    t,
                    radius=max(
                        0.75,
                        interval * 0.75,
                    ),
                )
            )

            router_evidence = (
                _semantic_router_evidence(
                    router,
                    t,
                    duration,
                )
            )

            scores = (
                _semantic_sample_scores(
                    ocr["text"],
                    overlay_text,
                    speech_text,
                    float(
                        text_layers.get(
                            "promo_overlay_activity"
                        )
                        or 0.0
                    ),
                    router_evidence,
                    t,
                    duration,
                    req,
                )
            )

            timeline.append(
                {
                    "time_seconds": round(
                        t,
                        3,
                    ),
                    "ocr_text": (
                        ocr[
                            "text"
                        ]
                    ),
                    "overlay_text": (
                        overlay_text
                    ),
                    "speech_text": (
                        speech_text
                    ),
                    "text_layer_activity": {
                        "narrative_subtitle_activity": (
                            text_layers.get(
                                "narrative_subtitle_activity"
                            )
                        ),
                        "promo_overlay_activity": (
                            text_layers.get(
                                "promo_overlay_activity"
                            )
                        ),
                        "sample_overlay_text": (
                            text_layers.get(
                                "sample_overlay_text"
                            )
                        ),
                    },
                    "semantic_scores": {
                        "promo": (
                            scores[
                                "promo"
                            ]
                        ),
                        "end_card": (
                            scores[
                                "end_card"
                            ]
                        ),
                        "story": (
                            scores[
                                "story"
                            ]
                        ),
                    },
                    "semantic_signals": (
                        scores[
                            "signals"
                        ]
                    ),
                }
            )

            sample_index += 1
            t += interval

    finally:
        cap.release()

    _smooth_semantic_scores(
        timeline,
        int(
            req.semantic_smoothing_radius_samples
        ),
    )

    raw_labels = []

    for item in timeline:
        state = (
            _semantic_raw_state(
                item,
                duration,
                req,
            )
        )

        item[
            "raw_state"
        ] = state

        raw_labels.append(
            state
        )

    max_gap_samples = int(
        round(
            float(
                req.max_bridge_gap_seconds
            )
            / max(
                0.1,
                interval,
            )
        )
    )

    labels = (
        _bridge_short_state_gaps(
            raw_labels,
            "PROMO",
            max_gap_samples,
        )
    )

    labels = (
        _bridge_short_state_gaps(
            labels,
            "END_CARD",
            max(
                1,
                max_gap_samples // 2,
            ),
        )
    )

    for item, state in zip(
        timeline,
        labels,
    ):
        item[
            "smoothed_state"
        ] = state

    promo_runs = [
        run
        for run in _state_runs(
            timeline,
            labels,
            "PROMO",
            interval,
        )
        if float(
            run[
                "duration_seconds"
            ]
        )
        >= float(
            req.min_promo_seconds
        )
    ]

    end_runs = [
        run
        for run in _state_runs(
            timeline,
            labels,
            "END_CARD",
            interval,
        )
        if float(
            run[
                "duration_seconds"
            ]
        )
        >= float(
            req.min_end_card_seconds
        )
    ]

    structures = {
        "mid_promos": [],
        "end_card": {
            "presence": "ABSENT",
            "confidence": 0.0,
            "coarse_segment": None,
            "refined_segment": None,
        },
    }

    for idx, run in enumerate(
        promo_runs,
        1,
    ):
        start_refine = (
            _semantic_boundary_refine(
                video_path,
                run[
                    "start_seconds"
                ],
                req.router_report_relative_path,
                req.boundary_refine_radius_seconds,
            )
        )

        end_refine = (
            _semantic_boundary_refine(
                video_path,
                run[
                    "end_seconds"
                ],
                req.router_report_relative_path,
                req.boundary_refine_radius_seconds,
            )
        )

        refined_start = float(
            start_refine[
                "refined_seconds"
            ]
        )

        refined_end = float(
            end_refine[
                "refined_seconds"
            ]
        )

        if (
            refined_end
            <= refined_start
        ):
            refined_start = float(
                run[
                    "start_seconds"
                ]
            )
            refined_end = float(
                run[
                    "end_seconds"
                ]
            )

        boundary_conf = float(
            min(
                float(
                    start_refine.get(
                        "confidence"
                    )
                    or 0.0
                ),
                float(
                    end_refine.get(
                        "confidence"
                    )
                    or 0.0
                ),
            )
        )

        semantic_conf = float(
            run[
                "mean_semantic_score"
            ]
        )

        structures[
            "mid_promos"
        ].append(
            {
                "segment_id": (
                    f"semantic-mid-promo-{idx}"
                ),
                "type": (
                    "mid_promo"
                ),
                "presence": (
                    "PRESENT"
                ),
                "semantic_confidence": round(
                    semantic_conf,
                    6,
                ),
                "boundary_confidence": round(
                    boundary_conf,
                    6,
                ),
                "coarse_segment": (
                    run
                ),
                "refined_segment": {
                    "start_seconds": round(
                        refined_start,
                        3,
                    ),
                    "end_seconds": round(
                        refined_end,
                        3,
                    ),
                    "duration_seconds": round(
                        max(
                            0.0,
                            refined_end
                            - refined_start,
                        ),
                        3,
                    ),
                    "start_refinement": (
                        start_refine
                    ),
                    "end_refinement": (
                        end_refine
                    ),
                },
                "plan_eligible": False,
                "note": (
                    "v0.11.0 semantic route is diagnostic-only; production "
                    "routing is not changed yet."
                ),
            }
        )

    if end_runs:
        # Prefer a run that reaches the end of the video. Otherwise use the
        # latest valid end-card semantic run.
        reaching_end = [
            run
            for run in end_runs
            if (
                duration <= 0
                or float(
                    run[
                        "end_seconds"
                    ]
                )
                >= duration - 1.5
            )
        ]

        chosen_end = (
            reaching_end[-1]
            if reaching_end
            else end_runs[-1]
        )

        start_refine = (
            _semantic_boundary_refine(
                video_path,
                chosen_end[
                    "start_seconds"
                ],
                req.router_report_relative_path,
                req.boundary_refine_radius_seconds,
            )
        )

        refined_start = float(
            start_refine[
                "refined_seconds"
            ]
        )

        structures[
            "end_card"
        ] = {
            "presence": "PRESENT",
            "semantic_confidence": (
                chosen_end[
                    "mean_semantic_score"
                ]
            ),
            "boundary_confidence": (
                start_refine[
                    "confidence"
                ]
            ),
            "coarse_segment": (
                chosen_end
            ),
            "refined_segment": {
                "start_seconds": round(
                    refined_start,
                    3,
                ),
                "end_seconds": round(
                    duration,
                    3,
                ),
                "duration_seconds": round(
                    max(
                        0.0,
                        duration
                        - refined_start,
                    ),
                    3,
                ),
                "start_refinement": (
                    start_refine
                ),
            },
            "plan_eligible": False,
            "note": (
                "v0.11.0 semantic route is diagnostic-only; production "
                "routing is not changed yet."
            ),
        }

    timestamp = _app_now().strftime(
        "%Y-%m-%d_%H%M%S"
    )

    out_dir = (
        WORKSPACE
        / "review"
        / "branding_semantic_structure"
        / timestamp
        / video_path.stem
    )

    out_dir.mkdir(
        parents=True,
        exist_ok=True,
    )

    result = {
        "ok": True,
        "version": "0.17.0",
        "mode": (
            "branding_semantic_structure_census"
        ),
        "source": {
            "relative_path": (
                source_rel
            ),
            "router_report_relative_path": (
                router_path
                .relative_to(
                    WORKSPACE
                )
                .as_posix()
            ),
        },
        "video": meta,
        "semantic_engine": {
            "mode": (
                "local_semantic_prototype"
            ),
            "visual_vlm": {
                "enabled": False,
                "reason": (
                    "v0.11.0 first validates OCR + Whisper semantic states "
                    "without external API keys. VLM is a planned optional "
                    "provider after this test."
                ),
            },
            "ocr": {
                "language": (
                    req.ocr_language
                ),
            },
            "whisper": {
                "status": (
                    whisper[
                        "status"
                    ]
                ),
                "model": (
                    whisper[
                        "model"
                    ]
                ),
                "language": (
                    whisper[
                        "language"
                    ]
                ),
                "segment_count": len(
                    whisper.get(
                        "segments"
                    )
                    or []
                ),
                "error": (
                    whisper[
                        "error"
                    ]
                ),
            },
        },
        "summary": {
            "semantic_sample_count": len(
                timeline
            ),
            "mid_promo_presence": (
                "PRESENT"
                if structures[
                    "mid_promos"
                ]
                else "ABSENT"
            ),
            "mid_promo_count": len(
                structures[
                    "mid_promos"
                ]
            ),
            "end_card_presence": (
                structures[
                    "end_card"
                ][
                    "presence"
                ]
            ),
            "source_video_modified": False,
            "production_plan_modified": False,
            "manual_comparison_required": True,
        },
        "structures": structures,
        "semantic_timeline": timeline,
        "whisper_segments": (
            whisper.get(
                "segments"
            )
            or []
        ),
        "whisper_translated_segments": (
            whisper.get(
                "translated_segments"
            )
            or []
        ),
        "whisper_runtime": {
            "segment_mode": (
                whisper.get(
                    "segment_mode"
                )
            ),
            "pass_count": (
                whisper.get(
                    "whisper_pass_count"
                )
            ),
            "translation_error": (
                whisper.get(
                    "translation_error"
                )
            ),
        },
        "policy": {
            "semantic_first": (
                "OCR and speech semantics identify STORY/PROMO/END_CARD. "
                "Multimodal visual/subtitle/audio/text-layer analysis only "
                "refines the boundaries around semantic state transitions."
            ),
            "subtitle": (
                "White/no-white subtitle state is never a Promo label."
            ),
            "overlay": (
                "Extra text overlay presence is never a Promo label by itself."
            ),
            "optional_structures": (
                "If no sustained semantic PROMO or END_CARD state exists, "
                "the structure is ABSENT."
            ),
        },
        "output_relative_dir": (
            out_dir
            .relative_to(
                WORKSPACE
            )
            .as_posix()
        ),
    }

    report_path = (
        out_dir
        / f"{video_path.stem}.semantic-structure.json"
    )

    result[
        "report_relative_path"
    ] = (
        report_path
        .relative_to(
            WORKSPACE
        )
        .as_posix()
    )

    report_path.write_text(
        json.dumps(
            result,
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )

    return result




# ---------------------------------------------------------------------------
# v0.11.1 Whisper Semantic Episodes
#
# v0.11.0 classified each sampled second too independently. Real Promo speech
# is a discourse episode: some sentences explicitly say "promotion", while
# adjacent sentences merely explain benefits, unlocking, episodes, pricing,
# or CTA. Those neutral-looking sentences still belong to the same Promo.
#
# v0.11.1:
#   1) optionally asks Whisper for English translation as a language-normalized
#      semantic channel
#   2) scores entire Whisper speech segments
#   3) builds continuous PROMO semantic episodes from strong seeds
#   4) extends through explanatory sentences until speech returns to story
#   5) injects episode membership into the per-second semantic timeline
#
# Multimodal visual/subtitle/audio remains BOUNDARY REFINEMENT only.
# ---------------------------------------------------------------------------


class BrandingSemanticStructureRequest(BaseModel):
    router_report_relative_path: str

    sample_interval_seconds: float = 1.0

    ocr_language: str = "eng"
    ocr_min_confidence: float = 22.0
    ocr_scale: float = 1.5

    enable_whisper: bool = True
    whisper_model: Optional[str] = None
    whisper_device: str = "cpu"
    whisper_compute_type: str = "int8"

    # New: Whisper's translation task normalizes multilingual speech to English
    # without adding another NLP model dependency.
    enable_whisper_translation: bool = True

    semantic_smoothing_radius_samples: int = 1
    promo_score_threshold: float = 0.50
    end_card_score_threshold: float = 0.52

    min_promo_seconds: float = 5.0
    min_end_card_seconds: float = 1.5
    max_bridge_gap_seconds: float = 2.0

    end_card_search_seconds: float = 15.0
    boundary_refine_radius_seconds: float = 2.5

    # Speech-episode parameters.
    speech_episode_max_gap_seconds: float = 1.4
    speech_episode_soft_gap_seconds: float = 3.0
    speech_episode_strong_seed_score: float = 0.62
    speech_episode_member_score: float = 0.30
    speech_episode_membership_bonus: float = 0.72

    max_samples: int = 900


# Language-normalized semantic concepts used after Whisper translation.
# These are intent concepts, not exact script templates.
_SEMANTIC_PROMO_EN_CONCEPTS = {
    "promotion": 1.00,
    "watch the full story": 0.98,
    "watch full story": 0.96,
    "watch the full series": 0.98,
    "watch full series": 0.96,
    "all episodes": 0.90,
    "unlock all episodes": 1.00,
    "unlock episodes": 0.94,
    "watch all episodes": 0.94,
    "full episodes": 0.86,
    "continue the story": 0.82,
    "see what happens next": 0.82,
    "watch for free": 0.94,
    "free episodes": 0.86,
    "download the app": 0.98,
    "install the app": 0.98,
    "limited time": 1.00,
    "limited-time": 1.00,
    "special offer": 0.95,
    "offer": 0.64,
    "advertisement": 0.92,
    "small ad": 0.92,
    "watch an ad": 0.95,
    "unlock": 0.88,
    "unlock the full": 0.96,
    "full series": 0.88,
    "complete series": 0.88,
    "for free": 0.86,
    "free": 0.62,
    "no prepayment": 0.82,
    "no prepayments": 0.82,
    "no endless": 0.72,
    "choose any episode": 0.78,
    "any episode": 0.62,
    "from beginning to end": 0.58,
    "more than": 0.42,
    "short films": 0.46,
    "short dramas": 0.52,
    "watch": 0.34,
    "episode": 0.36,
    "series": 0.40,
    "attention": 0.48,
}


_SEMANTIC_CTA_EN_CONCEPTS = {
    "click the link": 1.00,
    "link below": 0.95,
    "click below": 0.95,
    "start watching now": 1.00,
    "watch now": 0.96,
    "download now": 1.00,
    "install now": 1.00,
    "get the app": 0.96,
    "continue watching": 0.90,
    "start watching": 0.88,
}


def _whisper_model_and_segments(
    video_path,
    req,
):
    if not bool(
        req.enable_whisper
    ):
        return {
            "status": "DISABLED",
            "segments": [],
            "translated_segments": [],
            "model": None,
            "language": None,
            "error": None,
            "translation_error": None,
            "segment_mode": "disabled",
            "whisper_pass_count": 0,
        }

    try:
        from faster_whisper import WhisperModel
    except Exception as exc:
        return {
            "status": "UNAVAILABLE",
            "segments": [],
            "translated_segments": [],
            "model": None,
            "language": None,
            "error": (
                "faster_whisper import failed: "
                + str(exc)[:300]
            ),
            "translation_error": None,
            "segment_mode": "unavailable",
            "whisper_pass_count": 0,
        }

    model_name = (
        str(
            req.whisper_model
            or os.getenv(
                "WHISPER_MODEL",
                "base",
            )
        ).strip()
        or "base"
    )

    def collect(
        iterator,
    ):
        values = []

        for seg in iterator:
            _operator_raise_if_cancelled()
            value = str(
                getattr(
                    seg,
                    "text",
                    "",
                )
                or ""
            ).strip()

            if not value:
                continue

            values.append(
                {
                    "start_seconds": round(
                        float(
                            getattr(
                                seg,
                                "start",
                                0.0,
                            )
                            or 0.0
                        ),
                        3,
                    ),
                    "end_seconds": round(
                        float(
                            getattr(
                                seg,
                                "end",
                                0.0,
                            )
                            or 0.0
                        ),
                        3,
                    ),
                    "text": value,
                }
            )

        return values

    # v0.18.10.9.7: Load faster-whisper strictly from the local cache when it is
    # available (model files are mounted at /model-cache and validated before a
    # render starts). A network model lookup must never hold a production edit
    # for minutes; local_files_only makes a missing cache fail fast and offline.
    download_root = str(
        os.getenv("WHISPER_CACHE_DIR") or ""
    ).strip() or None
    local_files_only = (
        os.getenv("WHISPER_LOCAL_FILES_ONLY", "true")
        .strip()
        .lower()
        in {"1", "true", "yes", "on"}
    )

    global _SEMANTIC_WHISPER_MODEL, _SEMANTIC_WHISPER_MODEL_KEY
    try:
        model_key = (
            model_name,
            str(req.whisper_device),
            str(req.whisper_compute_type),
            download_root,
            bool(local_files_only),
        )
        with _SEMANTIC_WHISPER_MODEL_LOCK:
            if _SEMANTIC_WHISPER_MODEL is None or _SEMANTIC_WHISPER_MODEL_KEY != model_key:
                try:
                    cpu_threads = max(1, min(16, int(os.getenv("WHISPER_CPU_THREADS", "4"))))
                except Exception:
                    cpu_threads = 4
                _SEMANTIC_WHISPER_MODEL = WhisperModel(
                    model_name,
                    device=str(req.whisper_device),
                    compute_type=str(req.whisper_compute_type),
                    download_root=download_root,
                    local_files_only=local_files_only,
                    cpu_threads=cpu_threads,
                    num_workers=1,
                )
                _SEMANTIC_WHISPER_MODEL_KEY = model_key
            model = _SEMANTIC_WHISPER_MODEL

        translation_enabled = bool(
            getattr(
                req,
                "enable_whisper_translation",
                False,
            )
        )

        single_pass_translation = bool(
            translation_enabled
            and getattr(
                req,
                "whisper_single_pass_translation",
                False,
            )
        )

        if single_pass_translation:
            # For production semantic classification we need a normalized
            # English discourse channel, not a second verbatim transcript.
            # A single Whisper translate pass supplies both timestamps and
            # semantic text and cuts the expensive ASR work roughly in half.
            translated_iter, info = (
                model.transcribe(
                    str(
                        video_path
                    ),
                    beam_size=1,
                    best_of=1,
                    patience=0.0,
                    vad_filter=True,
                    condition_on_previous_text=False,
                    task="translate",
                )
            )

            translated = collect(
                translated_iter
            )

            return {
                "status": "OK",
                # The v0.11 semantic timeline expects `segments`. In this
                # optimized mode the English translated timeline is the proxy
                # speech channel for semantic classification.
                "segments": (
                    translated
                ),
                "translated_segments": (
                    translated
                ),
                "model": model_name,
                "language": getattr(
                    info,
                    "language",
                    None,
                ),
                "error": None,
                "translation_error": None,
                "segment_mode": (
                    "single_pass_translation_proxy"
                ),
                "whisper_pass_count": 1,
            }

        original_iter, info = (
            model.transcribe(
                str(
                    video_path
                ),
                beam_size=1,
                best_of=1,
                patience=0.0,
                vad_filter=True,
                condition_on_previous_text=False,
                task="transcribe",
            )
        )

        original = collect(
            original_iter
        )

        translated = []
        translation_error = None
        pass_count = 1

        if translation_enabled:
            try:
                translated_iter, _ = (
                    model.transcribe(
                        str(
                            video_path
                        ),
                        beam_size=1,
                        best_of=1,
                        patience=0.0,
                        vad_filter=True,
                        condition_on_previous_text=False,
                        task="translate",
                    )
                )

                translated = collect(
                    translated_iter
                )
                pass_count += 1

            except Exception as exc:
                translation_error = str(
                    exc
                )[:500]

        return {
            "status": "OK",
            "segments": original,
            "translated_segments": translated,
            "model": model_name,
            "language": getattr(
                info,
                "language",
                None,
            ),
            "error": None,
            "translation_error": (
                translation_error
            ),
            "segment_mode": (
                "transcribe_plus_translate"
                if translation_enabled
                else "transcribe_only"
            ),
            "whisper_pass_count": (
                pass_count
            ),
        }

    except Exception as exc:
        return {
            "status": "FAILED",
            "segments": [],
            "translated_segments": [],
            "model": model_name,
            "language": None,
            "error": str(
                exc
            )[:500],
            "translation_error": None,
            "segment_mode": "failed",
            "whisper_pass_count": 0,
        }


# Override the v0.11.0 Whisper helper.
def _whisper_transcribe_semantic(
    video_path,
    req,
):
    return _whisper_model_and_segments(
        video_path,
        req,
    )


def _translated_speech_at_time(
    translated_segments,
    t,
    radius=0.75,
):
    return _speech_at_time(
        translated_segments,
        t,
        radius,
    )


def _speech_segment_semantics(
    original_text,
    translated_text,
):
    combined_en = str(
        translated_text
        or ""
    ).strip()

    original = str(
        original_text
        or ""
    ).strip()

    # English translation is the primary language-normalized channel.
    # Original multilingual phrase matching remains supporting evidence.
    en_promo = _semantic_phrase_score(
        combined_en,
        _SEMANTIC_PROMO_EN_CONCEPTS,
    )

    en_cta = _semantic_phrase_score(
        combined_en,
        _SEMANTIC_CTA_EN_CONCEPTS,
    )

    original_promo = _semantic_phrase_score(
        original,
        _SEMANTIC_PROMO_PHRASES,
    )

    original_cta = _semantic_phrase_score(
        original,
        _SEMANTIC_CTA_PHRASES,
    )

    promo = max(
        float(
            en_promo["score"]
        ),
        0.82
        * float(
            original_promo["score"]
        ),
    )

    cta = max(
        float(
            en_cta["score"]
        ),
        0.82
        * float(
            original_cta["score"]
        ),
    )

    return {
        "promo_score": round(
            min(
                1.0,
                promo,
            ),
            6,
        ),
        "cta_score": round(
            min(
                1.0,
                cta,
            ),
            6,
        ),
        "translated_promo": en_promo,
        "translated_cta": en_cta,
        "original_promo": (
            original_promo
        ),
        "original_cta": (
            original_cta
        ),
    }


def _nearest_translated_text(
    translated_segments,
    start,
    end,
):
    if not translated_segments:
        return ""

    center = (
        float(start)
        + float(end)
    ) / 2.0

    best = None
    best_overlap = -1.0

    for seg in translated_segments:
        s = float(
            seg.get(
                "start_seconds"
            )
            or 0.0
        )
        e = float(
            seg.get(
                "end_seconds"
            )
            or s
        )

        overlap = max(
            0.0,
            min(
                float(end),
                e,
            )
            - max(
                float(start),
                s,
            ),
        )

        if overlap > best_overlap:
            best_overlap = overlap
            best = seg

    if (
        best
        and best_overlap > 0.0
    ):
        return str(
            best.get(
                "text"
            )
            or ""
        ).strip()

    # Fallback to nearest translated segment center.
    best = min(
        translated_segments,
        key=lambda seg: abs(
            (
                float(
                    seg.get(
                        "start_seconds"
                    )
                    or 0.0
                )
                + float(
                    seg.get(
                        "end_seconds"
                    )
                    or 0.0
                )
            )
            / 2.0
            - center
        ),
    )

    return str(
        best.get(
            "text"
        )
        or ""
    ).strip()


def _build_whisper_semantic_segments(
    whisper,
    req,
):
    original = (
        whisper.get(
            "segments"
        )
        or []
    )

    translated = (
        whisper.get(
            "translated_segments"
        )
        or []
    )

    semantic_segments = []

    for idx, seg in enumerate(
        original
    ):
        start = float(
            seg.get(
                "start_seconds"
            )
            or 0.0
        )

        end = float(
            seg.get(
                "end_seconds"
            )
            or start
        )

        original_text = str(
            seg.get(
                "text"
            )
            or ""
        ).strip()

        translated_text = (
            _nearest_translated_text(
                translated,
                start,
                end,
            )
        )

        semantics = (
            _speech_segment_semantics(
                original_text,
                translated_text,
            )
        )

        semantic_segments.append(
            {
                "index": idx,
                "start_seconds": round(
                    start,
                    3,
                ),
                "end_seconds": round(
                    end,
                    3,
                ),
                "duration_seconds": round(
                    max(
                        0.0,
                        end - start,
                    ),
                    3,
                ),
                "original_text": (
                    original_text
                ),
                "translated_text": (
                    translated_text
                ),
                **semantics,
            }
        )

    return semantic_segments


def _semantic_episode_seed_score(
    segment,
):
    return max(
        float(
            segment.get(
                "promo_score"
            )
            or 0.0
        ),
        float(
            segment.get(
                "cta_score"
            )
            or 0.0
        ),
    )


def _soft_explanatory_segment(
    segment,
):
    text = _semantic_norm(
        (
            segment.get(
                "translated_text"
            )
            or ""
        )
        + " "
        + (
            segment.get(
                "original_text"
            )
            or ""
        )
    )

    if not text:
        return False

    # These are broad product/explanation concepts that commonly occur INSIDE
    # a promo after a strong semantic seed. They cannot START a Promo alone.
    concepts = (
        "episode",
        "series",
        "full",
        "complete",
        "free",
        "unlock",
        "watch",
        "advertisement",
        "ad",
        "payment",
        "prepayment",
        "short",
        "link",
        "click",
        "choose",
        "content",
        "film",
        "drama",
        "app",
        "download",
        "install",
        "continue",
        "next episode",
        "all episodes",
        "full story",
        "full series",
        "what happens next",
        "assistir",
        "episodio",
        "serie",
        "gratuit",
        "anuncio",
        "desbloque",
        "pagamento",
        "link",
        "clique",
    )

    return any(
        concept in text
        for concept in concepts
    )


def _build_whisper_promo_episodes(
    semantic_segments,
    req,
):
    if not semantic_segments:
        return []

    strong_threshold = float(
        req.speech_episode_strong_seed_score
    )

    member_threshold = float(
        req.speech_episode_member_score
    )

    strong_indices = [
        idx
        for idx, segment
        in enumerate(
            semantic_segments
        )
        if (
            _semantic_episode_seed_score(
                segment
            )
            >= strong_threshold
        )
    ]

    if not strong_indices:
        return []

    used = set()
    episodes = []

    for seed_idx in strong_indices:
        if seed_idx in used:
            continue

        left = seed_idx
        right = seed_idx

        # Extend backward. A discourse marker such as "Attention" can be
        # included if it immediately precedes a strong promo sentence.
        cursor = seed_idx - 1

        while cursor >= 0:
            current = (
                semantic_segments[
                    cursor
                ]
            )

            next_seg = (
                semantic_segments[
                    cursor + 1
                ]
            )

            gap = max(
                0.0,
                float(
                    next_seg[
                        "start_seconds"
                    ]
                )
                - float(
                    current[
                        "end_seconds"
                    ]
                ),
            )

            seed_score = (
                _semantic_episode_seed_score(
                    current
                )
            )

            norm_text = _semantic_norm(
                (
                    current.get(
                        "translated_text"
                    )
                    or ""
                )
                + " "
                + (
                    current.get(
                        "original_text"
                    )
                    or ""
                )
            )

            discourse_attention = (
                "attention"
                in norm_text
                or "atencao"
                in norm_text
                or "atencion"
                in norm_text
            )

            if (
                gap
                <= float(
                    req.speech_episode_max_gap_seconds
                )
                and (
                    seed_score
                    >= member_threshold
                    or discourse_attention
                    or _soft_explanatory_segment(
                        current
                    )
                )
            ):
                left = cursor
                cursor -= 1
                continue

            break

        # Extend forward through semantically related explanatory speech.
        cursor = seed_idx + 1
        neutral_budget = float(
            req.speech_episode_soft_gap_seconds
        )

        while cursor < len(
            semantic_segments
        ):
            previous = (
                semantic_segments[
                    cursor - 1
                ]
            )

            current = (
                semantic_segments[
                    cursor
                ]
            )

            gap = max(
                0.0,
                float(
                    current[
                        "start_seconds"
                    ]
                )
                - float(
                    previous[
                        "end_seconds"
                    ]
                ),
            )

            if gap > float(
                req.speech_episode_max_gap_seconds
            ):
                break

            seed_score = (
                _semantic_episode_seed_score(
                    current
                )
            )

            related = (
                seed_score
                >= member_threshold
                or _soft_explanatory_segment(
                    current
                )
            )

            if related:
                right = cursor
                neutral_budget = float(
                    req.speech_episode_soft_gap_seconds
                )
                cursor += 1
                continue

            # A truly neutral story sentence ends the episode. Only tolerate a
            # very short neutral bridge if the following segment returns to
            # strong promo semantics.
            next_strong = False

            if cursor + 1 < len(
                semantic_segments
            ):
                following = (
                    semantic_segments[
                        cursor + 1
                    ]
                )

                next_gap = max(
                    0.0,
                    float(
                        following[
                            "start_seconds"
                        ]
                    )
                    - float(
                        current[
                            "end_seconds"
                        ]
                    ),
                )

                next_strong = bool(
                    next_gap
                    <= float(
                        req.speech_episode_max_gap_seconds
                    )
                    and _semantic_episode_seed_score(
                        following
                    )
                    >= strong_threshold
                )

            duration = max(
                0.0,
                float(
                    current[
                        "end_seconds"
                    ]
                )
                - float(
                    current[
                        "start_seconds"
                    ]
                ),
            )

            if (
                next_strong
                and duration
                <= neutral_budget
            ):
                right = cursor
                neutral_budget -= duration
                cursor += 1
                continue

            break

        members = (
            semantic_segments[
                left:right + 1
            ]
        )

        start = float(
            members[0][
                "start_seconds"
            ]
        )

        end = float(
            members[-1][
                "end_seconds"
            ]
        )

        strong_count = sum(
            1
            for member in members
            if (
                _semantic_episode_seed_score(
                    member
                )
                >= strong_threshold
            )
        )

        mean_score = float(
            np.mean(
                [
                    _semantic_episode_seed_score(
                        member
                    )
                    for member in members
                ]
            )
        )

        if (
            end - start
            < float(
                req.min_promo_seconds
            )
            or strong_count < 1
        ):
            continue

        for idx in range(
            left,
            right + 1,
        ):
            used.add(
                idx
            )

        episodes.append(
            {
                "start_seconds": round(
                    start,
                    3,
                ),
                "end_seconds": round(
                    end,
                    3,
                ),
                "duration_seconds": round(
                    max(
                        0.0,
                        end - start,
                    ),
                    3,
                ),
                "segment_count": len(
                    members
                ),
                "strong_seed_count": (
                    strong_count
                ),
                "mean_speech_semantic_score": round(
                    mean_score,
                    6,
                ),
                "segments": (
                    members
                ),
                "selection_reason": (
                    "continuous_whisper_promo_discourse_episode"
                ),
            }
        )

    # Merge overlapping episodes.
    episodes.sort(
        key=lambda x: float(
            x[
                "start_seconds"
            ]
        )
    )

    merged = []

    for episode in episodes:
        if not merged:
            merged.append(
                episode
            )
            continue

        previous = merged[-1]

        gap = (
            float(
                episode[
                    "start_seconds"
                ]
            )
            - float(
                previous[
                    "end_seconds"
                ]
            )
        )

        if gap <= float(
            req.speech_episode_soft_gap_seconds
        ):
            combined_segments = (
                previous[
                    "segments"
                ]
                + [
                    x
                    for x in episode[
                        "segments"
                    ]
                    if x not in previous[
                        "segments"
                    ]
                ]
            )

            previous[
                "end_seconds"
            ] = max(
                float(
                    previous[
                        "end_seconds"
                    ]
                ),
                float(
                    episode[
                        "end_seconds"
                    ]
                ),
            )

            previous[
                "duration_seconds"
            ] = round(
                float(
                    previous[
                        "end_seconds"
                    ]
                )
                - float(
                    previous[
                        "start_seconds"
                    ]
                ),
                3,
            )

            previous[
                "segments"
            ] = (
                combined_segments
            )

            previous[
                "segment_count"
            ] = len(
                combined_segments
            )

            previous[
                "strong_seed_count"
            ] += int(
                episode[
                    "strong_seed_count"
                ]
            )

        else:
            merged.append(
                episode
            )

    return merged


def _promo_episode_at_time(
    episodes,
    t,
):
    t = float(t)

    for episode in episodes or []:
        if (
            float(
                episode[
                    "start_seconds"
                ]
            )
            <= t
            <= float(
                episode[
                    "end_seconds"
                ]
            )
        ):
            return episode

    return None


# Keep v0.11.0 semantic route for OCR/boundary machinery, but replace its final
# semantic output with Whisper-discourse episodes when available.
_semantic_structure_census_sync_v0110 = (
    _semantic_structure_census_sync
)


def _semantic_structure_census_sync(
    req: BrandingSemanticStructureRequest
):
    # Run the v0.11.0 route first. It performs OCR sampling, boundary tools, and
    # emits its original diagnostics.
    result = (
        _semantic_structure_census_sync_v0110(
            req
        )
    )

    source_rel = (
        result.get(
            "source"
        )
        or {}
    ).get(
        "relative_path"
    )

    if not source_rel:
        return result

    video_path = (
        _safe_workspace_path(
            source_rel
        )
    )

    # v0.11.0 already ran Whisper. Reuse the exact timestamped speech channels
    # retained in its result; rerunning the same full video here was a major
    # production performance bug.
    whisper_meta = (
        (
            result.get(
                "semantic_engine"
            )
            or {}
        ).get(
            "whisper"
        )
        or {}
    )

    whisper_runtime = (
        result.get(
            "whisper_runtime"
        )
        or {}
    )

    whisper = {
        "status": (
            whisper_meta.get(
                "status"
            )
            or "OK"
        ),
        "segments": (
            result.get(
                "whisper_segments"
            )
            or []
        ),
        "translated_segments": (
            result.get(
                "whisper_translated_segments"
            )
            or []
        ),
        "model": (
            whisper_meta.get(
                "model"
            )
        ),
        "language": (
            whisper_meta.get(
                "language"
            )
        ),
        "error": (
            whisper_meta.get(
                "error"
            )
        ),
        "translation_error": (
            whisper_runtime.get(
                "translation_error"
            )
        ),
        "segment_mode": (
            whisper_runtime.get(
                "segment_mode"
            )
            or "reused_v0110"
        ),
        "whisper_pass_count": (
            whisper_runtime.get(
                "pass_count"
            )
        ),
    }

    semantic_segments = (
        _build_whisper_semantic_segments(
            whisper,
            req,
        )
    )

    episodes = (
        _build_whisper_promo_episodes(
            semantic_segments,
            req,
        )
    )

    duration = float(
        (
            result.get(
                "video"
            )
            or {}
        ).get(
            "duration_seconds"
        )
        or 0.0
    )

    semantic_structures = []

    for idx, episode in enumerate(
        episodes,
        1,
    ):
        start_refine = (
            _semantic_boundary_refine(
                video_path,
                episode[
                    "start_seconds"
                ],
                req.router_report_relative_path,
                req.boundary_refine_radius_seconds,
            )
        )

        end_refine = (
            _semantic_boundary_refine(
                video_path,
                episode[
                    "end_seconds"
                ],
                req.router_report_relative_path,
                req.boundary_refine_radius_seconds,
            )
        )

        # Semantic boundary is primary. Multimodal refinement is accepted only
        # when it remains close to the semantic transition and has real support.
        refined_start = float(
            episode[
                "start_seconds"
            ]
        )

        refined_end = float(
            episode[
                "end_seconds"
            ]
        )

        if (
            start_refine.get(
                "resolved"
            )
            and abs(
                float(
                    start_refine[
                        "refined_seconds"
                    ]
                )
                - refined_start
            )
            <= 1.75
        ):
            refined_start = float(
                start_refine[
                    "refined_seconds"
                ]
            )

        if (
            end_refine.get(
                "resolved"
            )
            and abs(
                float(
                    end_refine[
                        "refined_seconds"
                    ]
                )
                - refined_end
            )
            <= 1.75
        ):
            refined_end = float(
                end_refine[
                    "refined_seconds"
                ]
            )

        if refined_end <= refined_start:
            refined_start = float(
                episode[
                    "start_seconds"
                ]
            )
            refined_end = float(
                episode[
                    "end_seconds"
                ]
            )

        semantic_structures.append(
            {
                "segment_id": (
                    f"whisper-semantic-promo-{idx}"
                ),
                "type": "mid_promo",
                "presence": "PRESENT",
                "semantic_confidence": (
                    episode[
                        "mean_speech_semantic_score"
                    ]
                ),
                "speech_episode": episode,
                "coarse_segment": {
                    "start_seconds": (
                        episode[
                            "start_seconds"
                        ]
                    ),
                    "end_seconds": (
                        episode[
                            "end_seconds"
                        ]
                    ),
                    "duration_seconds": (
                        episode[
                            "duration_seconds"
                        ]
                    ),
                    "source": (
                        "whisper_semantic_episode"
                    ),
                },
                "refined_segment": {
                    "start_seconds": round(
                        refined_start,
                        3,
                    ),
                    "end_seconds": round(
                        refined_end,
                        3,
                    ),
                    "duration_seconds": round(
                        max(
                            0.0,
                            refined_end
                            - refined_start,
                        ),
                        3,
                    ),
                    "start_source": (
                        "whisper_semantics_then_multimodal_refine"
                    ),
                    "end_source": (
                        "whisper_semantics_then_multimodal_refine"
                    ),
                    "start_refinement": (
                        start_refine
                    ),
                    "end_refinement": (
                        end_refine
                    ),
                },
                "plan_eligible": False,
                "note": (
                    "v0.11.1 remains diagnostic-only."
                ),
            }
        )

    result["version"] = "0.11.1"

    result[
        "semantic_engine"
    ][
        "whisper"
    ] = {
        "status": (
            whisper[
                "status"
            ]
        ),
        "model": (
            whisper[
                "model"
            ]
        ),
        "language": (
            whisper[
                "language"
            ]
        ),
        "segment_count": len(
            whisper.get(
                "segments"
            )
            or []
        ),
        "translation_enabled": bool(
            req.enable_whisper_translation
        ),
        "translated_segment_count": len(
            whisper.get(
                "translated_segments"
            )
            or []
        ),
        "error": (
            whisper[
                "error"
            ]
        ),
        "translation_error": (
            whisper[
                "translation_error"
            ]
        ),
    }

    result[
        "semantic_engine"
    ][
        "speech_semantics"
    ] = {
        "mode": (
            "whisper_continuous_discourse_episode"
        ),
        "semantic_segment_count": len(
            semantic_segments
        ),
        "promo_episode_count": len(
            episodes
        ),
        "language_normalization": (
            "Whisper translate-to-English when available, original text fallback"
        ),
    }

    result[
        "structures"
    ][
        "mid_promos"
    ] = (
        semantic_structures
    )

    result[
        "summary"
    ][
        "mid_promo_presence"
    ] = (
        "PRESENT"
        if semantic_structures
        else "ABSENT"
    )

    result[
        "summary"
    ][
        "mid_promo_count"
    ] = len(
        semantic_structures
    )

    result[
        "whisper_segments"
    ] = (
        whisper.get(
            "segments"
        )
        or []
    )

    result[
        "whisper_translated_segments"
    ] = (
        whisper.get(
            "translated_segments"
        )
        or []
    )

    result[
        "semantic_speech_segments"
    ] = (
        semantic_segments
    )

    result[
        "semantic_speech_episodes"
    ] = (
        episodes
    )

    # Enrich the existing per-second timeline with speech-episode membership.
    membership_bonus = float(
        req.speech_episode_membership_bonus
    )

    for item in (
        result.get(
            "semantic_timeline"
        )
        or []
    ):
        t = float(
            item[
                "time_seconds"
            ]
        )

        translated_text = (
            _translated_speech_at_time(
                whisper.get(
                    "translated_segments"
                )
                or [],
                t,
                radius=max(
                    0.75,
                    float(
                        req.sample_interval_seconds
                    )
                    * 0.75,
                ),
            )
        )

        item[
            "translated_speech_text"
        ] = translated_text

        episode = (
            _promo_episode_at_time(
                episodes,
                t,
            )
        )

        item[
            "speech_episode_state"
        ] = (
            "PROMO"
            if episode
            else None
        )

        if episode:
            item.setdefault(
                "smoothed_scores",
                {},
            )[
                "promo"
            ] = round(
                max(
                    float(
                        item[
                            "smoothed_scores"
                        ].get(
                            "promo",
                            0.0,
                        )
                    ),
                    membership_bonus,
                ),
                6,
            )

            item[
                "smoothed_state"
            ] = "PROMO"

    result["policy"] = {
        **(
            result.get(
                "policy"
            )
            or {}
        ),
        "speech_semantics": (
            "Promotion is modeled as a continuous discourse episode. Strong "
            "semantic sentences seed the episode; adjacent explanatory/CTA "
            "sentences remain inside until speech clearly returns to story."
        ),
    }

    report_rel = (
        result.get(
            "report_relative_path"
        )
    )

    if report_rel:
        _safe_workspace_path(
            report_rel
        ).write_text(
            json.dumps(
                result,
                ensure_ascii=False,
                indent=2,
            ),
            encoding="utf-8",
        )

    return result




# ---------------------------------------------------------------------------
# v0.11.2 Semantic Envelope Guardrail
#
# Semantic episode = CONTENT SAFETY ENVELOPE.
# Multimodal refinement = boundary precision helper.
#
# Promo:
#   final_start may move a little EARLIER than semantic start
#   final_end   may move a little LATER  than semantic end
#   refinement is NOT allowed to shrink inward and remove semantic content.
#
# End Card:
#   a coarse near-end semantic state is not enough for trimming.
#   the final cut must be supported by a confident multimodal transition.
#   otherwise boundary_ready=false and production must preserve source.
# ---------------------------------------------------------------------------


class BrandingSemanticStructureRequest(BaseModel):
    router_report_relative_path: str

    sample_interval_seconds: float = 1.0

    ocr_language: str = "eng"
    ocr_min_confidence: float = 22.0
    ocr_scale: float = 1.5

    enable_whisper: bool = True
    whisper_model: Optional[str] = None
    whisper_device: str = "cpu"
    whisper_compute_type: str = "int8"
    enable_whisper_translation: bool = True

    # Operator production optimization. When translation is required, Whisper
    # runs one translate pass instead of transcribe + translate. The translated
    # segments are also used as the semantic timeline speech channel.
    whisper_single_pass_translation: bool = False

    semantic_smoothing_radius_samples: int = 1
    promo_score_threshold: float = 0.50
    end_card_score_threshold: float = 0.52

    min_promo_seconds: float = 5.0
    min_end_card_seconds: float = 1.5
    max_bridge_gap_seconds: float = 2.0

    end_card_search_seconds: float = 15.0
    boundary_refine_radius_seconds: float = 2.5

    speech_episode_max_gap_seconds: float = 1.4
    speech_episode_soft_gap_seconds: float = 3.0
    speech_episode_strong_seed_score: float = 0.56
    speech_episode_member_score: float = 0.26
    speech_episode_membership_bonus: float = 0.72

    # Guardrail controls.
    semantic_envelope_max_expand_seconds: float = 1.5
    promo_boundary_ready_threshold: float = 0.50
    end_card_boundary_ready_threshold: float = 0.66
    end_card_max_refine_distance_seconds: float = 3.5

    max_samples: int = 900


def _apply_promo_semantic_envelope(
    promo,
    req,
):
    if not promo:
        return promo

    speech_episode = (
        promo.get(
            "speech_episode"
        )
        or {}
    )

    refined = (
        promo.get(
            "refined_segment"
        )
        or {}
    )

    semantic_start = float(
        speech_episode.get(
            "start_seconds"
        )
        or (
            promo.get(
                "coarse_segment"
            )
            or {}
        ).get(
            "start_seconds"
        )
        or 0.0
    )

    semantic_end = float(
        speech_episode.get(
            "end_seconds"
        )
        or (
            promo.get(
                "coarse_segment"
            )
            or {}
        ).get(
            "end_seconds"
        )
        or semantic_start
    )

    raw_refined_start = float(
        refined.get(
            "start_seconds"
        )
        or semantic_start
    )

    raw_refined_end = float(
        refined.get(
            "end_seconds"
        )
        or semantic_end
    )

    max_expand = max(
        0.0,
        float(
            req.semantic_envelope_max_expand_seconds
        ),
    )

    # START: refinement may extend earlier, never later than semantic onset.
    candidate_start = min(
        semantic_start,
        raw_refined_start,
    )

    final_start = max(
        0.0,
        max(
            semantic_start - max_expand,
            candidate_start,
        ),
    )

    # END: refinement may extend later, never earlier than semantic end.
    candidate_end = max(
        semantic_end,
        raw_refined_end,
    )

    final_end = min(
        semantic_end + max_expand,
        candidate_end,
    )

    # Confidence uses actual local refinement support when present. The semantic
    # episode itself protects content even if local refinement is weaker.
    start_ref = (
        refined.get(
            "start_refinement"
        )
        or {}
    )

    end_ref = (
        refined.get(
            "end_refinement"
        )
        or {}
    )

    start_conf = float(
        start_ref.get(
            "confidence"
        )
        or 0.0
    )

    end_conf = float(
        end_ref.get(
            "confidence"
        )
        or 0.0
    )

    semantic_conf = float(
        promo.get(
            "semantic_confidence"
        )
        or 0.0
    )

    # A boundary can still be ready when semantic discourse is very clear and
    # one multimodal edge is modest, but we keep a conservative floor.
    boundary_conf = min(
        1.0,
        0.52 * semantic_conf
        + 0.24 * start_conf
        + 0.24 * end_conf,
    )

    boundary_ready = bool(
        final_end > final_start
        and boundary_conf
        >= float(
            req.promo_boundary_ready_threshold
        )
    )

    promo[
        "semantic_envelope"
    ] = {
        "semantic_start_seconds": round(
            semantic_start,
            3,
        ),
        "semantic_end_seconds": round(
            semantic_end,
            3,
        ),
        "raw_refined_start_seconds": round(
            raw_refined_start,
            3,
        ),
        "raw_refined_end_seconds": round(
            raw_refined_end,
            3,
        ),
        "rule": (
            "Refinement may expand outside the semantic episode within a small "
            "guardrail, but may never shrink inward and remove semantic content."
        ),
    }

    promo[
        "final_segment"
    ] = {
        "start_seconds": round(
            final_start,
            3,
        ),
        "end_seconds": round(
            final_end,
            3,
        ),
        "duration_seconds": round(
            max(
                0.0,
                final_end - final_start,
            ),
            3,
        ),
        "start_source": (
            "semantic_envelope_guardrail"
        ),
        "end_source": (
            "semantic_envelope_guardrail"
        ),
    }

    promo[
        "boundary_confidence"
    ] = round(
        boundary_conf,
        6,
    )

    promo[
        "boundary_ready"
    ] = (
        boundary_ready
    )

    promo[
        "plan_eligible"
    ] = False

    return promo


def _apply_end_card_guardrail(
    end_card,
    req,
):
    if not end_card:
        return end_card

    if (
        str(
            end_card.get(
                "presence"
            )
            or ""
        )
        != "PRESENT"
    ):
        end_card[
            "boundary_ready"
        ] = False
        end_card[
            "plan_eligible"
        ] = False
        return end_card

    coarse = (
        end_card.get(
            "coarse_segment"
        )
        or {}
    )

    refined = (
        end_card.get(
            "refined_segment"
        )
        or {}
    )

    coarse_start = float(
        coarse.get(
            "start_seconds"
        )
        or 0.0
    )

    refined_start = float(
        refined.get(
            "start_seconds"
        )
        or coarse_start
    )

    start_ref = (
        refined.get(
            "start_refinement"
        )
        or {}
    )

    resolved = bool(
        start_ref.get(
            "resolved"
        )
    )

    local_conf = float(
        start_ref.get(
            "confidence"
        )
        or end_card.get(
            "boundary_confidence"
        )
        or 0.0
    )

    semantic_conf = float(
        end_card.get(
            "semantic_confidence"
        )
        or 0.0
    )

    refine_distance = abs(
        refined_start
        - coarse_start
    )

    # For terminal-state trimming, a confident local transition is mandatory.
    boundary_ready = bool(
        resolved
        and local_conf
        >= float(
            req.end_card_boundary_ready_threshold
        )
        and refine_distance
        <= float(
            req.end_card_max_refine_distance_seconds
        )
    )

    combined_conf = min(
        1.0,
        0.42 * semantic_conf
        + 0.58 * local_conf,
    )

    end_card[
        "semantic_envelope"
    ] = {
        "coarse_semantic_start_seconds": round(
            coarse_start,
            3,
        ),
        "multimodal_refined_start_seconds": round(
            refined_start,
            3,
        ),
        "refine_distance_seconds": round(
            refine_distance,
            3,
        ),
        "rule": (
            "End-card trimming requires a confident near-end multimodal "
            "transition. Coarse near-end semantics alone cannot trigger a cut."
        ),
    }

    end_card[
        "boundary_confidence"
    ] = round(
        combined_conf,
        6,
    )

    end_card[
        "boundary_ready"
    ] = (
        boundary_ready
    )

    end_card[
        "final_segment"
    ] = (
        {
            "start_seconds": round(
                refined_start,
                3,
            ),
            "end_seconds": refined.get(
                "end_seconds"
            ),
            "duration_seconds": refined.get(
                "duration_seconds"
            ),
            "start_source": (
                "semantic_plus_confident_terminal_multimodal_transition"
            ),
        }
        if boundary_ready
        else None
    )

    end_card[
        "plan_eligible"
    ] = False

    if not boundary_ready:
        end_card[
            "preserve_original_reason"
        ] = (
            "End-card presence is semantic PRESENT, but the exact trim boundary "
            "is not yet trusted enough for automatic production editing."
        )

    return end_card


_semantic_structure_census_sync_v0111 = (
    _semantic_structure_census_sync
)


def _semantic_structure_census_sync(
    req: BrandingSemanticStructureRequest
):
    result = (
        _semantic_structure_census_sync_v0111(
            req
        )
    )

    structures = (
        result.get(
            "structures"
        )
        or {}
    )

    mid_promos = (
        structures.get(
            "mid_promos"
        )
        or []
    )

    guarded_promos = [
        _apply_promo_semantic_envelope(
            promo,
            req,
        )
        for promo in mid_promos
    ]

    structures[
        "mid_promos"
    ] = guarded_promos

    end_card = (
        structures.get(
            "end_card"
        )
        or {}
    )

    structures[
        "end_card"
    ] = (
        _apply_end_card_guardrail(
            end_card,
            req,
        )
    )

    promo_ready_count = sum(
        1
        for promo in guarded_promos
        if bool(
            promo.get(
                "boundary_ready"
            )
        )
    )

    end_ready = bool(
        (
            structures.get(
                "end_card"
            )
            or {}
        ).get(
            "boundary_ready"
        )
    )

    result["version"] = "0.11.2"

    summary = result.setdefault(
        "summary",
        {},
    )

    summary[
        "mid_promo_boundary_ready_count"
    ] = (
        promo_ready_count
    )

    summary[
        "end_card_boundary_ready"
    ] = (
        end_ready
    )

    summary[
        "semantic_structure_ready_for_plan_integration"
    ] = bool(
        (
            not guarded_promos
            or promo_ready_count
            == len(
                guarded_promos
            )
        )
        and (
            str(
                (
                    structures.get(
                        "end_card"
                    )
                    or {}
                ).get(
                    "presence"
                )
                or ""
            )
            != "PRESENT"
            or end_ready
        )
    )

    result["policy"] = {
        **(
            result.get(
                "policy"
            )
            or {}
        ),
        "semantic_envelope_guardrail": (
            "Semantic episodes protect complete content. Promo multimodal "
            "refinement cannot shrink inside the semantic episode. End Card "
            "requires a confident terminal multimodal transition before any "
            "automatic trim can become eligible."
        ),
    }

    report_rel = (
        result.get(
            "report_relative_path"
        )
    )

    if report_rel:
        _safe_workspace_path(
            report_rel
        ).write_text(
            json.dumps(
                result,
                ensure_ascii=False,
                indent=2,
            ),
            encoding="utf-8",
        )

    return result




# ---------------------------------------------------------------------------
# v0.11.4 Semantic Structure -> Replacement Plan Integration
#
# Production-planning rule:
#   Semantic Structure Report is now the preferred source for optional
#   Mid Promo / End Card replacement segments.
#
#   ONLY:
#       presence == PRESENT
#       boundary_ready == true
#       final_segment exists
#
#   can become a replacement action.
#
#   The plan MUST read final_segment, never coarse_segment/refined_segment.
#
# Backward compatibility:
#   semantic report > legacy Structure Router report > legacy segment census
# ---------------------------------------------------------------------------


class BrandingReplacementPlanRequest(BaseModel):
    router_report_relative_path: str
    profile_id: str

    # v0.11.4 preferred input.
    semantic_structure_report_relative_path: Optional[str] = None

    # Legacy v0.10.3 input.
    structure_report_relative_path: Optional[str] = None

    # Older compatibility input.
    segment_census_report_relative_path: Optional[str] = None

    moving_flow_report_relative_path: Optional[str] = None
    moving_tracks_approved: bool = False

    # Legacy Structure Router only.
    include_uncertain_structures: bool = False

    # Semantic production safety defaults.
    require_semantic_structure_ready: bool = True


def _semantic_final_segment_to_plan_segment(
    structure_type,
    decision,
    ordinal=1,
):
    if not decision:
        return None

    presence = str(
        decision.get(
            "presence"
        )
        or ""
    ).upper()

    boundary_ready = bool(
        decision.get(
            "boundary_ready"
        )
    )

    final_segment = (
        decision.get(
            "final_segment"
        )
        or {}
    )

    if (
        presence != "PRESENT"
        or not boundary_ready
        or not final_segment
    ):
        return None

    try:
        start = float(
            final_segment[
                "start_seconds"
            ]
        )
        end = float(
            final_segment[
                "end_seconds"
            ]
        )
    except Exception:
        return None

    if end <= start:
        return None

    if structure_type == "end_card":
        segment_id = "semantic-end-card"
        segment_type = "end_card"
    else:
        segment_id = (
            decision.get(
                "segment_id"
            )
            or f"semantic-mid-promo-{ordinal}"
        )
        segment_type = "mid_promo_candidate"

    return {
        "segment_id": segment_id,
        "type": segment_type,
        "status": "REVIEW",
        "start_seconds": round(
            start,
            3,
        ),
        "end_seconds": round(
            end,
            3,
        ),
        "duration_seconds": round(
            end - start,
            3,
        ),
        "start_source": (
            final_segment.get(
                "start_source"
            )
            or "semantic_final_segment"
        ),
        "end_source": (
            final_segment.get(
                "end_source"
            )
            or "semantic_final_segment"
        ),
        "_semantic_presence": presence,
        "_semantic_boundary_ready": True,
        "_semantic_confidence": (
            decision.get(
                "semantic_confidence"
            )
        ),
        "_boundary_confidence": (
            decision.get(
                "boundary_confidence"
            )
        ),
        "_semantic_final_segment": (
            final_segment
        ),
        "_semantic_decision": (
            decision
        ),
    }


def _segments_from_semantic_structure_report(
    semantic_report,
):
    structures = (
        semantic_report.get(
            "structures"
        )
        or {}
    )

    segments = []

    end_decision = (
        structures.get(
            "end_card"
        )
        or {}
    )

    end_segment = (
        _semantic_final_segment_to_plan_segment(
            "end_card",
            end_decision,
            1,
        )
    )

    if end_segment:
        segments.append(
            end_segment
        )

    for idx, decision in enumerate(
        structures.get(
            "mid_promos"
        )
        or [],
        1,
    ):
        segment = (
            _semantic_final_segment_to_plan_segment(
                "mid_promo",
                decision,
                idx,
            )
        )

        if segment:
            segments.append(
                segment
            )

    return segments


def _fallback_semantic_brand_segments(semantic_report, duration_override: float = 0.0):
    """Recover obvious terminal/long promo blocks when Whisper/VLM is absent.

    The semantic census is intentionally conservative and can report ABSENT
    when speech recognition is unavailable.  A terminal AppStore/Google Play
    or ``watch exclusively`` card is still unambiguous source branding, so we
    create a reviewable replacement segment from OCR timeline evidence.  This
    is a fallback only; explicit semantic PRESENT segments always win.
    """
    timeline = [
        item for item in (semantic_report.get("semantic_timeline") or [])
        if isinstance(item, dict)
    ]
    video = semantic_report.get("video") or {}
    try:
        duration = float(video.get("duration_seconds") or duration_override or 0.0)
    except Exception:
        duration = 0.0
    if not timeline or duration <= 0.0:
        return []

    cta_terms = (
        "appstore", "google play", "watch exclusively", "download",
        "install now", "watch now", "start watching", "get the app",
    )
    terminal = []
    for item in timeline:
        text = " ".join(
            str(item.get(key) or "")
            for key in ("ocr_text", "overlay_text", "speech_text")
        ).lower().replace(" ", "")
        normalized_terms = [term.replace(" ", "") for term in cta_terms]
        near_end = float(item.get("time_seconds") or 0.0) >= max(0.0, duration - 4.5)
        promo_score = float((item.get("smoothed_scores") or {}).get("promo") or 0.0)
        end_score = float((item.get("smoothed_scores") or {}).get("end_card") or 0.0)
        overlay_activity = float((item.get("text_layer_activity") or {}).get("promo_overlay_activity") or 0.0)
        if near_end and (
            any(term in text for term in normalized_terms)
            or promo_score >= 0.34
            or end_score >= 0.34
            or overlay_activity >= 0.68
        ):
            terminal.append(item)

    segments = []
    if terminal:
        first_time = min(float(item.get("time_seconds") or 0.0) for item in terminal)
        # Backtrack far enough to include the logo/title reveal before the CTA.
        start = max(0.0, min(first_time - 1.75, duration - 4.5))
        segments.append({
            "segment_id": "fallback-terminal-brand-card",
            "type": "end_card",
            "status": "REVIEW",
            "start_seconds": round(start, 3),
            "end_seconds": round(duration, 3),
            "duration_seconds": round(duration - start, 3),
            "start_source": "terminal_brand_ocr_backtrack",
            "end_source": "video_duration",
            "fallback_reason": "terminal_cta_or_store_badge_detected_without_semantic_end_card",
        })

    # Long interior promo/brand episodes are recovered from sustained promo
    # scores when speech is unavailable. Keep this review-only and exclude the
    # terminal card so normal subtitle-heavy story sections are not cut.
    interior = [
        item for item in timeline
        if float(item.get("time_seconds") or 0.0) >= 3.0
        and float(item.get("time_seconds") or 0.0) < duration - 4.5
        and float((item.get("smoothed_scores") or {}).get("promo") or 0.0) >= 0.40
    ]
    if len(interior) >= 2:
        times = [float(item.get("time_seconds") or 0.0) for item in interior]
        if max(times) - min(times) >= 2.0:
            segments.insert(0, {
                "segment_id": "fallback-interior-brand-promo",
                "type": "mid_promo_candidate",
                "status": "REVIEW",
                "start_seconds": round(max(0.0, min(times) - 1.5), 3),
                "end_seconds": round(min(duration, max(times) + 1.5), 3),
                "duration_seconds": round(max(times) - min(times) + 3.0, 3),
                "start_source": "sustained_promo_score_backtrack",
                "end_source": "sustained_promo_score_forward",
                "fallback_reason": "sustained_promo_visual_or_ocr_evidence_without_semantic_episode",
            })
    return segments


_replacement_plan_sync_v0112 = (
    _replacement_plan_sync
)


def _replacement_plan_sync(
    req: BrandingReplacementPlanRequest
):
    # Preferred v0.11.4 path.
    if not req.semantic_structure_report_relative_path:
        result = (
            _replacement_plan_sync_v0112(
                req
            )
        )

        result["version"] = "0.11.4"

        try:
            _, router_payload = _read_json_workspace(
                req.router_report_relative_path, "replacement_plan"
            )
            census_rel = str((router_payload.get("evidence_reports") or {}).get("census") or "").strip()
            if census_rel:
                _, census_payload = _read_json_workspace(census_rel, "replacement_plan")
                result.setdefault("source", {})["source_identity"] = census_payload.get("source_identity") or {}
                strict = census_payload.get("verified_dynamic_identity") or {}
                tracks = list(strict.get("tracks") or []) if bool(strict.get("enabled")) else []
                result.setdefault("summary", {})["operator_dynamic_brand_expected_track_count"] = len(tracks)
                result.setdefault("summary", {})["operator_dynamic_brand_track_sources"] = {
                    str(track.get("track_id") or index): str(track.get("handler") or "")
                    for index, track in enumerate(tracks, 1)
                }
        except Exception:
            pass

        report_rel = result.get(
            "report_relative_path"
        )

        if report_rel:
            _safe_workspace_path(
                report_rel
            ).write_text(
                json.dumps(
                    result,
                    ensure_ascii=False,
                    indent=2,
                ),
                encoding="utf-8",
            )

        return result

    semantic_path, semantic = (
        _read_json_workspace(
            req.semantic_structure_report_relative_path,
            "replacement_plan",
        )
    )

    if (
        semantic.get(
            "mode"
        )
        != "branding_semantic_structure_census"
    ):
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "replacement_plan",
                "error": (
                    "wrong_semantic_structure_report_mode"
                ),
                "actual": semantic.get(
                    "mode"
                ),
                "expected": (
                    "branding_semantic_structure_census"
                ),
            },
        )

    semantic_source = (
        (
            semantic.get(
                "source"
            )
            or {}
        ).get(
            "relative_path"
        )
    )

    router_path, router = (
        _read_json_workspace(
            req.router_report_relative_path,
            "replacement_plan",
        )
    )

    router_source = (
        (
            router.get(
                "source"
            )
            or {}
        ).get(
            "relative_path"
        )
    )

    if (
        semantic_source
        and router_source
        and str(
            semantic_source
        )
        != str(
            router_source
        )
    ):
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "replacement_plan",
                "error": (
                    "semantic_router_source_mismatch"
                ),
                "router_source": (
                    router_source
                ),
                "semantic_source": (
                    semantic_source
                ),
            },
        )

    semantic_ready = bool(
        (
            semantic.get(
                "summary"
            )
            or {}
        ).get(
            "semantic_structure_ready_for_plan_integration"
        )
    )

    if (
        bool(
            req.require_semantic_structure_ready
        )
        and not semantic_ready
    ):
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "replacement_plan",
                "error": (
                    "semantic_structure_not_ready"
                ),
                "message": (
                    "Semantic report is not ready for plan integration. "
                    "PRESENT structures must have boundary_ready=true and "
                    "a final_segment before production planning."
                ),
                "semantic_report_relative_path": (
                    semantic_path
                    .relative_to(
                        WORKSPACE
                    )
                    .as_posix()
                ),
            },
        )

    segments = (
        _segments_from_semantic_structure_report(
            semantic
        )
    )
    # If the semantic engine could not establish a boundary (most commonly
    # because Whisper is unavailable), recover only high-confidence terminal
    # store/CTA branding and sustained interior promo evidence as REVIEW
    # segments.  This prevents the production plan from silently dropping a
    # large logo/advertising block while preserving the human approval gate.
    explicit_types = {str(item.get("type") or "") for item in segments}
    router_duration = float((router.get("video") or {}).get("duration_seconds") or 0.0)
    for fallback in _fallback_semantic_brand_segments(semantic, router_duration):
        if fallback.get("type") in explicit_types:
            continue
        segments.append(fallback)
        explicit_types.add(str(fallback.get("type") or ""))

    video_path = (
        _safe_workspace_path(
            router_source
        )
    )

    timestamp = (
        _app_now().strftime(
            "%Y-%m-%d_%H%M%S"
        )
    )

    derived_dir = (
        WORKSPACE
        / "review"
        / "branding_semantic_structure"
        / "derived_plan_segments"
        / timestamp
        / video_path.stem
    )

    derived_dir.mkdir(
        parents=True,
        exist_ok=True,
    )

    derived_path = (
        derived_dir
        / (
            f"{video_path.stem}"
            ".semantic-approved-segments.json"
        )
    )

    derived_payload = {
        "ok": True,
        "version": "0.17.0",
        "mode": (
            "branding_semantic_approved_segments"
        ),
        "source": {
            "relative_path": (
                router_source
            ),
            "semantic_structure_report_relative_path": (
                semantic_path
                .relative_to(
                    WORKSPACE
                )
                .as_posix()
            ),
        },
        "summary": {
            "segment_count": len(
                segments
            ),
            "mid_promo_count": sum(
                1
                for x in segments
                if x.get(
                    "type"
                )
                == "mid_promo_candidate"
            ),
            "end_card_count": sum(
                1
                for x in segments
                if x.get(
                    "type"
                )
                == "end_card"
            ),
        },
        "segments": segments,
    }

    derived_path.write_text(
        json.dumps(
            derived_payload,
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )

    # Use the mature v0.10.x action builder for:
    # fixed branding, optional semantic segments, and moving tracks.
    # We intentionally bypass the legacy Structure Router path here.
    class _PlanShim:
        pass

    shim = _PlanShim()

    shim.router_report_relative_path = (
        req.router_report_relative_path
    )

    shim.profile_id = (
        req.profile_id
    )

    shim.structure_report_relative_path = (
        None
    )

    shim.segment_census_report_relative_path = (
        derived_path
        .relative_to(
            WORKSPACE
        )
        .as_posix()
    )

    shim.moving_flow_report_relative_path = (
        req.moving_flow_report_relative_path
    )

    shim.moving_tracks_approved = (
        req.moving_tracks_approved
    )

    shim.include_uncertain_structures = False

    # _replacement_plan_sync_v0112 with no structure report falls back to the
    # original mature plan builder and consumes our semantic-approved segments.
    result = (
        _replacement_plan_sync_v0112(
            shim
        )
    )

    result["version"] = "0.11.4"

    result.setdefault(
        "source",
        {},
    )[
        "semantic_structure_report_relative_path"
    ] = (
        semantic_path
        .relative_to(
            WORKSPACE
        )
        .as_posix()
    )

    result["source"][
        "semantic_approved_segments_relative_path"
    ] = (
        derived_path
        .relative_to(
            WORKSPACE
        )
        .as_posix()
    )

    summary = result.setdefault(
        "summary",
        {},
    )

    summary[
        "semantic_structure_ready"
    ] = (
        semantic_ready
    )

    summary[
        "semantic_gated_optional_segments"
    ] = len(
        segments
    )

    summary[
        "semantic_mid_promo_segments"
    ] = sum(
        1
        for x in segments
        if x.get(
            "type"
        )
        == "mid_promo_candidate"
    )

    summary[
        "semantic_end_card_segments"
    ] = sum(
        1
        for x in segments
        if x.get(
            "type"
        )
        == "end_card"
    )

    summary[
        "semantic_final_segment_only"
    ] = True

    # Enrich optional actions so preview / future production renderer can audit
    # exactly which semantic decision created each trim/replacement.
    for action in (
        result.get(
            "actions"
        )
        or []
    ):
        if action.get(
            "type"
        ) not in (
            "mid_promo_replace",
            "end_card_replace",
        ):
            continue

        action[
            "decision_source"
        ] = (
            "semantic_structure_final_segment"
        )

        action[
            "semantic_structure_report_relative_path"
        ] = (
            semantic_path
            .relative_to(
                WORKSPACE
            )
            .as_posix()
        )

        source_candidate = (
            action.get(
                "source_candidate"
            )
            or {}
        )

        action[
            "semantic_boundary_ready"
        ] = bool(
            source_candidate.get(
                "_semantic_boundary_ready"
            )
        )

        action[
            "semantic_presence"
        ] = (
            source_candidate.get(
                "_semantic_presence"
            )
        )

        action[
            "semantic_confidence"
        ] = (
            source_candidate.get(
                "_semantic_confidence"
            )
        )

        action[
            "boundary_confidence"
        ] = (
            source_candidate.get(
                "_boundary_confidence"
            )
        )

    result[
        "semantic_structure_decisions"
    ] = {
        "mid_promos": (
            (
                semantic.get(
                    "structures"
                )
                or {}
            ).get(
                "mid_promos"
            )
            or []
        ),
        "end_card": (
            (
                semantic.get(
                    "structures"
                )
                or {}
            ).get(
                "end_card"
            )
        ),
    }

    result["policy"] = {
        **(
            result.get(
                "policy"
            )
            or {}
        ),
        "semantic_optional_structures": (
            "Optional Mid Promo / End Card actions are created only from "
            "Semantic Structure decisions with presence=PRESENT, "
            "boundary_ready=true, and final_segment. coarse_segment and "
            "refined_segment are never used for production planning."
        ),
        "semantic_absent": (
            "ABSENT semantic structures normally create no action; an explicit "
            "terminal CTA/store-card or sustained promo fallback may create a "
            "REVIEW action when speech/VLM evidence is unavailable."
        ),
        "semantic_unready": (
            "PRESENT but boundary_ready=false creates no optional action when "
            "semantic production safety is required."
        ),
        "preview_before_production": (
            "Semantic-approved optional actions remain REVIEW until the "
            "replacement preview is visually accepted."
        ),
    }

    report_rel = (
        result.get(
            "report_relative_path"
        )
    )

    if report_rel:
        _safe_workspace_path(
            report_rel
        ).write_text(
            json.dumps(
                result,
                ensure_ascii=False,
                indent=2,
            ),
            encoding="utf-8",
        )

    return result




# ---------------------------------------------------------------------------
# v0.11.5 Composed Top Brand Preview
#
# Fixes two preview-composition bugs:
#
# 1) fixed top cleanup was rendered ONLY in the fixed-action comparison.
#    Mid Promo and End Card previews wrote raw source context frames, so the
#    competitor top ReelShort mark reappeared there.
#
# 2) OCR-derived fixed bbox mainly covered the ReelShort wordmark. The small
#    leading brand icon immediately beside the text could remain untouched.
#
# New rule:
#   top fixed-brand replacement is a COMPOSITED GLOBAL LAYER for every source
#   frame used by any preview.
#
#   competitor wordmark bbox
#       + placement-aware icon-side expansion
#       -> local inpaint
#       -> own brand mark
#
# Optional Mid Promo / End Card boundaries are unchanged.
# ---------------------------------------------------------------------------


class BrandingReplacementPreviewRequest(BaseModel):
    replacement_plan_relative_path: str

    include_review_actions: bool = True

    fixed_preview_seconds: float = 2.0
    dynamic_preview_seconds: float = 3.0
    end_card_preroll_seconds: float = 2.0
    mid_promo_context_seconds: float = 1.25

    # v0.11.5: compose accepted top fixed-brand actions into every source
    # context frame used by Mid Promo / End Card previews.
    compose_top_brand_layers: bool = True

    # Sparse OCR/mask execution windows are detection evidence, not proof that
    # the fixed watermark disappears in the gaps. Treat the span between first
    # and last accepted top-fixed evidence as the active fixed-brand regime.
    top_brand_span_guard_seconds: float = 1.75

    # Expand the OCR wordmark box toward the side where the adjacent icon
    # normally sits. This is geometry-relative, not brand-specific pixels.
    top_brand_icon_pad_ratio: float = 0.80
    top_brand_opposite_pad_ratio: float = 0.12
    top_brand_vertical_pad_ratio: float = 0.10

    crf: int = 15
    preset: str = "slow"


def _top_cleanup_bbox(
    bbox,
    width,
    height,
    placement,
    icon_pad_ratio=0.80,
    opposite_pad_ratio=0.12,
    vertical_pad_ratio=0.10,
):
    b = _clip_bbox(
        bbox,
        int(width),
        int(height),
    )

    bh = max(
        1,
        int(b["height"]),
    )

    icon_pad = max(
        12,
        int(round(
            bh * float(icon_pad_ratio)
        )),
    )

    opposite_pad = max(
        3,
        int(round(
            bh * float(opposite_pad_ratio)
        )),
    )

    vertical_pad = max(
        2,
        int(round(
            bh * float(vertical_pad_ratio)
        )),
    )

    placement = str(
        placement or ""
    )

    # For a top-right wordmark, the small logo/icon usually sits immediately
    # before the wordmark (to its left). For top-left, mirror the expansion.
    if placement.endswith("_right"):
        x1 = (
            int(b["x"])
            - icon_pad
        )
        x2 = (
            int(b["x"])
            + int(b["width"])
            + opposite_pad
        )
    elif placement.endswith("_left"):
        x1 = (
            int(b["x"])
            - opposite_pad
        )
        x2 = (
            int(b["x"])
            + int(b["width"])
            + icon_pad
        )
    else:
        x1 = (
            int(b["x"])
            - icon_pad // 2
        )
        x2 = (
            int(b["x"])
            + int(b["width"])
            + icon_pad // 2
        )

    y1 = (
        int(b["y"])
        - vertical_pad
    )

    y2 = (
        int(b["y"])
        + int(b["height"])
        + vertical_pad
    )

    x1 = max(
        0,
        x1,
    )
    y1 = max(
        0,
        y1,
    )
    x2 = min(
        int(width),
        x2,
    )
    y2 = min(
        int(height),
        y2,
    )

    return {
        "x": int(x1),
        "y": int(y1),
        "width": max(
            1,
            int(x2 - x1),
        ),
        "height": max(
            1,
            int(y2 - y1),
        ),
    }


def _top_action_span(
    action,
    duration,
    guard_seconds,
):
    segments = (
        action.get(
            "active_segments"
        )
        or []
    )

    starts = []
    ends = []

    for segment in segments:
        try:
            starts.append(
                float(
                    segment[
                        "start_seconds"
                    ]
                )
            )
            ends.append(
                float(
                    segment[
                        "end_seconds"
                    ]
                )
            )
        except Exception:
            continue

    if starts and ends:
        start = max(
            0.0,
            min(starts)
            - float(
                guard_seconds
            ),
        )

        end = max(ends) + float(
            guard_seconds
        )

        if duration > 0:
            end = min(
                float(duration),
                end,
            )

        return {
            "start_seconds": round(
                start,
                3,
            ),
            "end_seconds": round(
                end,
                3,
            ),
            "source": (
                "span_between_first_last_fixed_evidence_plus_guard"
            ),
        }

    # If a layer has been classified as fixed/top but the legacy mask review
    # has no temporal execution segments, do not silently make it global.
    return None


def _top_action_bbox_at_time(
    action,
    t,
):
    segments = (
        action.get(
            "active_segments"
        )
        or []
    )

    active = _active_fixed_segment(
        segments,
        float(t),
    )

    if (
        active is not None
        and active.get(
            "bbox"
        )
    ):
        return active[
            "bbox"
        ]

    return action.get(
        "bbox"
    )


def _draw_clean_brand_mark(
    frame,
    bbox,
    profile,
    placement,
):
    # v0.11.5: when an own logo asset exists, permit logo + brand text together
    # rather than returning after drawing only the logo.
    out = frame.copy()
    h, w = out.shape[:2]

    b = _clip_bbox(
        bbox,
        w,
        h,
    )

    assets = (
        profile.get(
            "assets"
        )
        or {}
    )

    logo = _load_bgr_asset(
        assets.get(
            "logo_image_relative_path"
        )
        or assets.get(
            "icon_image_relative_path"
        )
    )

    brand_text = str(
        profile.get(
            "brand_name"
        )
        or profile.get(
            "product_name"
        )
        or ""
    ).strip()

    font = cv2.FONT_HERSHEY_SIMPLEX

    # Text metrics first.
    text_scale = max(
        0.42,
        max(
            18,
            int(round(
                b["height"] * 0.56
            )),
        )
        / 34.0,
    )

    thickness = max(
        1,
        int(round(
            b["height"]
            / 30.0
        )),
    )

    if brand_text:
        text_size, _ = cv2.getTextSize(
            brand_text,
            font,
            text_scale,
            thickness,
        )
    else:
        text_size = (
            0,
            0,
        )

    logo_h = 0
    logo_w = 0

    if logo is not None:
        logo_h = max(
            18,
            int(round(
                b["height"]
                * 0.72
            )),
        )

        ih, iw = logo.shape[:2]

        logo_w = max(
            1,
            int(round(
                iw
                * logo_h
                / float(
                    max(
                        1,
                        ih,
                    )
                )
            )),
        )

    gap = (
        max(
            4,
            int(round(
                b["height"]
                * 0.12
            )),
        )
        if (
            logo is not None
            and brand_text
        )
        else 0
    )

    # Fit group to a conservative top-corner width.
    max_group_w = min(
        int(round(
            w * 0.42
        )),
        max(
            int(b["width"]),
            int(round(
                w * 0.18
            )),
        ),
    )

    group_w = (
        logo_w
        + gap
        + text_size[0]
    )

    if (
        brand_text
        and group_w
        > max_group_w
    ):
        allowed_text_w = max(
            20,
            max_group_w
            - logo_w
            - gap,
        )

        if text_size[0] > 0:
            text_scale *= (
                allowed_text_w
                / float(
                    text_size[0]
                )
            )

        text_scale = max(
            0.34,
            text_scale,
        )

        text_size, _ = cv2.getTextSize(
            brand_text,
            font,
            text_scale,
            thickness,
        )

        group_w = (
            logo_w
            + gap
            + text_size[0]
        )

    if str(
        placement or ""
    ).endswith(
        "_right"
    ):
        group_x = max(
            4,
            int(
                b["x"]
                + b["width"]
                - group_w
            ),
        )
    else:
        group_x = max(
            4,
            int(
                b["x"]
            ),
        )

    if logo is not None:
        logo_y = int(round(
            b["y"]
            + (
                b["height"]
                - logo_h
            )
            / 2.0
        ))

        out = _alpha_overlay_image(
            out,
            logo,
            int(group_x),
            int(logo_y),
            int(logo_h),
        )

    if brand_text:
        tx = int(
            group_x
            + logo_w
            + gap
        )

        ty = min(
            h - 6,
            max(
                text_size[1] + 4,
                int(
                    b["y"]
                    + round(
                        (
                            b["height"]
                            + text_size[1]
                        )
                        / 2.0
                    )
                ),
            ),
        )

        cv2.putText(
            out,
            brand_text,
            (
                tx + 1,
                ty + 2,
            ),
            font,
            text_scale,
            (
                0,
                0,
                0,
            ),
            thickness + 2,
            cv2.LINE_AA,
        )

        cv2.putText(
            out,
            brand_text,
            (
                tx,
                ty,
            ),
            font,
            text_scale,
            (
                245,
                245,
                245,
            ),
            thickness,
            cv2.LINE_AA,
        )

    return out


def _apply_top_brand_composition(
    frame,
    t,
    top_actions,
    profile,
    width,
    height,
    duration,
    req,
):
    processed = (
        frame.copy()
    )

    applied = []

    if not bool(
        getattr(
            req,
            "compose_top_brand_layers",
            True,
        )
    ):
        return (
            processed,
            applied,
        )

    for action in (
        top_actions
        or []
    ):
        span = _top_action_span(
            action,
            duration,
            float(
                getattr(
                    req,
                    "top_brand_span_guard_seconds",
                    1.75,
                )
            ),
        )

        if span is None:
            continue

        if not (
            float(
                span[
                    "start_seconds"
                ]
            )
            <= float(t)
            <= float(
                span[
                    "end_seconds"
                ]
            )
        ):
            continue

        base_bbox = (
            _top_action_bbox_at_time(
                action,
                t,
            )
        )

        if not base_bbox:
            continue

        placement = str(
            action.get(
                "placement"
            )
            or ""
        )

        cleanup_bbox = (
            _top_cleanup_bbox(
                base_bbox,
                width,
                height,
                placement,
                float(
                    getattr(
                        req,
                        "top_brand_icon_pad_ratio",
                        0.80,
                    )
                ),
                float(
                    getattr(
                        req,
                        "top_brand_opposite_pad_ratio",
                        0.12,
                    )
                ),
                float(
                    getattr(
                        req,
                        "top_brand_vertical_pad_ratio",
                        0.10,
                    )
                ),
            )
        )

        mask = _segment_bbox_mask(
            width,
            height,
            cleanup_bbox,
            1,
        )

        processed = cv2.inpaint(
            processed,
            mask,
            3.0,
            cv2.INPAINT_TELEA,
        )

        # Keep the own-brand placement aligned to the original wordmark area.
        # The expanded cleanup area exists to remove the adjacent competitor
        # icon, not to shift our replacement text.
        processed = (
            _draw_clean_brand_mark(
                processed,
                base_bbox,
                profile,
                placement,
            )
        )

        applied.append(
            {
                "action_id": (
                    action.get(
                        "action_id"
                    )
                ),
                "placement": (
                    placement
                ),
                "base_bbox": (
                    base_bbox
                ),
                "cleanup_bbox": (
                    cleanup_bbox
                ),
                "span": (
                    span
                ),
            }
        )

    return (
        processed,
        applied,
    )


def _render_fixed_banner_preview(
    video_path,
    out_path,
    center_time,
    seconds,
    action,
    profile,
    fps,
    width,
    height,
    duration,
    crf,
    preset,
    req=None,
):
    half = (
        float(seconds)
        / 2.0
    )

    start = max(
        0.0,
        float(center_time)
        - half,
    )

    end = (
        float(center_time)
        + half
    )

    if duration > 0:
        end = min(
            duration,
            end,
        )

    writer, runtime = (
        _open_x264_raw_writer(
            out_path,
            width * 2,
            height,
            fps,
            crf,
            preset,
        )
    )

    cap = cv2.VideoCapture(
        str(
            video_path
        )
    )

    if not cap.isOpened():
        raise HTTPException(
            status_code=422,
            detail=(
                "Could not open source video."
            ),
        )

    cap.set(
        cv2.CAP_PROP_POS_MSEC,
        start * 1000.0,
    )

    index = 0
    written = 0
    write_error = None

    placement = str(
        action.get(
            "placement"
        )
        or ""
    )

    handler = str(
        action.get(
            "handler"
        )
        or ""
    )

    first_cleanup_bbox = None
    composed_frames = 0

    try:
        while True:
            ok, frame = cap.read()

            if (
                not ok
                or frame is None
            ):
                break

            t = (
                start
                + index
                / float(fps)
            )

            if (
                t
                > end
                + 0.5
                / float(fps)
            ):
                break

            processed = frame.copy()

            if (
                handler
                == "top_cleanup_brand_overlay"
                or placement.startswith(
                    "top_"
                )
            ):
                if req is None:
                    class _PreviewDefaults:
                        compose_top_brand_layers = True
                        top_brand_span_guard_seconds = 1.75
                        top_brand_icon_pad_ratio = 0.80
                        top_brand_opposite_pad_ratio = 0.12
                        top_brand_vertical_pad_ratio = 0.10
                    req_for_comp = _PreviewDefaults()
                else:
                    req_for_comp = req

                processed, applied = (
                    _apply_top_brand_composition(
                        processed,
                        t,
                        [action],
                        profile,
                        width,
                        height,
                        duration,
                        req_for_comp,
                    )
                )

                if applied:
                    composed_frames += 1

                    if first_cleanup_bbox is None:
                        first_cleanup_bbox = (
                            applied[0].get(
                                "cleanup_bbox"
                            )
                        )

                label = (
                    "ICON CLEAN + BRAND"
                )

            elif (
                handler
                == "bottom_banner_replace"
                or placement.startswith(
                    "bottom_"
                )
            ):
                logo = _load_bgr_asset(
                    (
                        profile.get(
                            "assets"
                        )
                        or {}
                    ).get(
                        "logo_image_relative_path"
                    )
                )

                processed = (
                    _draw_brand_banner(
                        processed,
                        action[
                            "bbox"
                        ],
                        profile[
                            "product_name"
                        ],
                        logo_image=logo,
                        min_height=int(
                            height
                            * float(
                                (
                                    profile.get(
                                        "layout"
                                    )
                                    or {}
                                ).get(
                                    "banner_height_ratio",
                                    0.075,
                                )
                            )
                        ),
                    )
                )

                label = (
                    "BOTTOM BANNER"
                )

            else:
                logo = _load_bgr_asset(
                    (
                        profile.get(
                            "assets"
                        )
                        or {}
                    ).get(
                        "logo_image_relative_path"
                    )
                )

                processed = (
                    _draw_brand_banner(
                        processed,
                        action[
                            "bbox"
                        ],
                        profile[
                            "product_name"
                        ],
                        logo_image=logo,
                        min_height=int(
                            height
                            * 0.060
                        ),
                    )
                )

                label = (
                    "LOCAL COVER"
                )

            output = np.hstack(
                [
                    _label_pane(
                        frame,
                        "ORIGINAL",
                    ),
                    _label_pane(
                        processed,
                        label,
                    ),
                ]
            )

            try:
                writer.stdin.write(
                    output.tobytes()
                )
            except Exception as exc:
                write_error = str(
                    exc
                )[:500]
                break

            written += 1
            index += 1

    finally:
        cap.release()

        try:
            writer.stdin.close()
        except Exception:
            pass

    stderr = b""

    try:
        stderr = (
            writer.stderr.read()
            if writer.stderr
            else b""
        )
    except Exception:
        pass

    code = writer.wait()

    return {
        "ok": (
            code == 0
            and write_error is None
            and out_path.exists()
        ),
        "relative_path": (
            out_path
            .relative_to(
                WORKSPACE
            )
            .as_posix()
            if out_path.exists()
            else None
        ),
        "center_time_seconds": round(
            float(
                center_time
            ),
            3,
        ),
        "placement": (
            placement
        ),
        "handler": (
            handler
        ),
        "frames_written": (
            written
        ),
        "top_brand_composed_frames": (
            composed_frames
        ),
        "icon_aware_cleanup_bbox": (
            first_cleanup_bbox
        ),
        "error": (
            write_error
            or (
                stderr.decode(
                    "utf-8",
                    errors="replace",
                )[:800]
                if code != 0
                else None
            )
        ),
        "encoder": {
            "engine": (
                "ffmpeg"
            ),
            "codec": (
                "libx264"
            ),
            "crf": int(
                crf
            ),
            "preset": str(
                preset
            ),
            "runtime": (
                runtime
            ),
        },
    }


def _render_endcard_preview(
    video_path,
    out_path,
    action,
    profile,
    preroll_seconds,
    fps,
    width,
    height,
    duration,
    crf,
    preset,
    top_actions=None,
    req=None,
):
    cut = float(
        action[
            "start_seconds"
        ]
    )

    start = max(
        0.0,
        cut
        - float(
            preroll_seconds
        ),
    )

    card_seconds = float(
        (
            action.get(
                "replacement_content"
            )
            or {}
        ).get(
            "duration_seconds",
            3.0,
        )
    )

    writer, runtime = (
        _open_x264_raw_writer(
            out_path,
            width,
            height,
            fps,
            crf,
            preset,
        )
    )

    assets = (
        profile.get(
            "assets"
        )
        or {}
    )

    logo = _load_bgr_asset(
        assets.get(
            "logo_image_relative_path"
        )
    )

    card_image = _load_bgr_asset(
        assets.get(
            "end_card_image_relative_path"
        )
    )

    if card_image is not None:
        if (
            len(
                card_image.shape
            )
            == 3
            and card_image.shape[2]
            == 4
        ):
            bg = np.zeros(
                (
                    height,
                    width,
                    3,
                ),
                dtype=np.uint8,
            )

            card = _alpha_overlay_image(
                bg,
                card_image,
                0,
                0,
                height,
            )

            card = cv2.resize(
                card,
                (
                    width,
                    height,
                ),
                interpolation=cv2.INTER_AREA,
            )
        else:
            card = cv2.resize(
                card_image[
                    ...,
                    :3
                ],
                (
                    width,
                    height,
                ),
                interpolation=cv2.INTER_AREA,
            )
    else:
        card = (
            _generated_brand_card(
                width,
                height,
                profile[
                    "product_name"
                ],
                profile[
                    "brand_name"
                ],
                logo_image=logo,
                subtitle="Watch now",
            )
        )

        # Placeholder end card should also visibly carry our top brand mark so
        # the user can verify brand consistency across composed previews.
        for top_action in (
            top_actions
            or []
        )[:1]:
            bbox = top_action.get(
                "bbox"
            )

            if bbox:
                card = _draw_clean_brand_mark(
                    card,
                    bbox,
                    profile,
                    top_action.get(
                        "placement"
                    ),
                )

    cap = cv2.VideoCapture(
        str(
            video_path
        )
    )

    if not cap.isOpened():
        raise HTTPException(
            status_code=422,
            detail=(
                "Could not open source video."
            ),
        )

    cap.set(
        cv2.CAP_PROP_POS_MSEC,
        start * 1000.0,
    )

    written = 0
    write_error = None

    original_frames = max(
        0,
        int(round(
            (
                cut
                - start
            )
            * fps
        )),
    )

    top_composed_frames = 0
    first_top_composition = None

    try:
        for idx in range(
            original_frames
        ):
            ok, frame = cap.read()

            if (
                not ok
                or frame is None
            ):
                break

            t = (
                start
                + idx
                / float(fps)
            )

            if (
                req is not None
                and top_actions
            ):
                frame, applied = (
                    _apply_top_brand_composition(
                        frame,
                        t,
                        top_actions,
                        profile,
                        width,
                        height,
                        duration,
                        req,
                    )
                )

                if applied:
                    top_composed_frames += 1

                    if first_top_composition is None:
                        first_top_composition = (
                            applied[0]
                        )

            try:
                writer.stdin.write(
                    frame.tobytes()
                )
            except Exception as exc:
                write_error = str(
                    exc
                )[:500]
                break

            written += 1

        if write_error is None:
            card_frames = max(
                1,
                int(round(
                    card_seconds
                    * fps
                )),
            )

            for _ in range(
                card_frames
            ):
                try:
                    writer.stdin.write(
                        card.tobytes()
                    )
                except Exception as exc:
                    write_error = str(
                        exc
                    )[:500]
                    break

                written += 1

    finally:
        cap.release()

        try:
            writer.stdin.close()
        except Exception:
            pass

    stderr = b""

    try:
        stderr = (
            writer.stderr.read()
            if writer.stderr
            else b""
        )
    except Exception:
        pass

    code = writer.wait()

    return {
        "ok": (
            code == 0
            and write_error is None
            and out_path.exists()
        ),
        "relative_path": (
            out_path
            .relative_to(
                WORKSPACE
            )
            .as_posix()
            if out_path.exists()
            else None
        ),
        "original_preroll_start_seconds": round(
            start,
            3,
        ),
        "cut_seconds": round(
            cut,
            3,
        ),
        "replacement_end_card_seconds": round(
            card_seconds,
            3,
        ),
        "frames_written": (
            written
        ),
        "global_top_brand_composition": {
            "enabled": bool(
                req is not None
                and top_actions
                and getattr(
                    req,
                    "compose_top_brand_layers",
                    True,
                )
            ),
            "source_frames_composed": (
                top_composed_frames
            ),
            "first_composition": (
                first_top_composition
            ),
            "placeholder_card_has_own_top_brand": (
                card_image is None
                and bool(
                    top_actions
                )
            ),
        },
        "error": (
            write_error
            or (
                stderr.decode(
                    "utf-8",
                    errors="replace",
                )[:800]
                if code != 0
                else None
            )
        ),
        "encoder": {
            "engine": "ffmpeg",
            "codec": "libx264",
            "crf": int(
                crf
            ),
            "preset": str(
                preset
            ),
            "runtime": (
                runtime
            ),
        },
    }


def _render_mid_promo_preview(
    video_path,
    out_path,
    action,
    profile,
    context_seconds,
    fps,
    width,
    height,
    duration,
    crf,
    preset,
    top_actions=None,
    req=None,
):
    seg_start = float(
        action[
            "start_seconds"
        ]
    )

    seg_end = float(
        action[
            "end_seconds"
        ]
    )

    before_start = max(
        0.0,
        seg_start
        - float(
            context_seconds
        ),
    )

    after_end = (
        min(
            duration,
            seg_end
            + float(
                context_seconds
            ),
        )
        if duration > 0
        else seg_end
        + float(
            context_seconds
        )
    )

    writer, runtime = (
        _open_x264_raw_writer(
            out_path,
            width,
            height,
            fps,
            crf,
            preset,
        )
    )

    assets = (
        profile.get(
            "assets"
        )
        or {}
    )

    logo = _load_bgr_asset(
        assets.get(
            "logo_image_relative_path"
        )
    )

    replacement = (
        _generated_brand_card(
            width,
            height,
            profile[
                "product_name"
            ],
            profile[
                "brand_name"
            ],
            logo_image=logo,
            subtitle=(
                "Promo replacement preview"
            ),
        )
    )

    # The generated placeholder should visibly include the same own top-brand
    # mark. When a real custom promo video is configured later, its branding is
    # owned by that asset and should not be forcibly overlaid here.
    if not assets.get(
        "mid_promo_video_relative_path"
    ):
        for top_action in (
            top_actions
            or []
        )[:1]:
            bbox = top_action.get(
                "bbox"
            )

            if bbox:
                replacement = (
                    _draw_clean_brand_mark(
                        replacement,
                        bbox,
                        profile,
                        top_action.get(
                            "placement"
                        ),
                    )
                )

    replacement_seconds = min(
        3.0,
        max(
            1.5,
            seg_end
            - seg_start,
        ),
    )

    cap = cv2.VideoCapture(
        str(
            video_path
        )
    )

    if not cap.isOpened():
        raise HTTPException(
            status_code=422,
            detail=(
                "Could not open source video."
            ),
        )

    written = 0
    write_error = None

    top_composed_frames = 0
    first_top_composition = None

    def write_source(
        a,
        b,
    ):
        nonlocal written
        nonlocal write_error
        nonlocal top_composed_frames
        nonlocal first_top_composition

        cap.set(
            cv2.CAP_PROP_POS_MSEC,
            a * 1000.0,
        )

        count = max(
            0,
            int(round(
                (
                    b
                    - a
                )
                * fps
            )),
        )

        for idx in range(
            count
        ):
            ok, frame = cap.read()

            if (
                not ok
                or frame is None
            ):
                break

            t = (
                a
                + idx
                / float(fps)
            )

            if (
                req is not None
                and top_actions
            ):
                frame, applied = (
                    _apply_top_brand_composition(
                        frame,
                        t,
                        top_actions,
                        profile,
                        width,
                        height,
                        duration,
                        req,
                    )
                )

                if applied:
                    top_composed_frames += 1

                    if first_top_composition is None:
                        first_top_composition = (
                            applied[0]
                        )

            try:
                writer.stdin.write(
                    frame.tobytes()
                )
            except Exception as exc:
                write_error = str(
                    exc
                )[:500]
                return

            written += 1

    try:
        write_source(
            before_start,
            seg_start,
        )

        if write_error is None:
            for _ in range(
                max(
                    1,
                    int(round(
                        replacement_seconds
                        * fps
                    )),
                )
            ):
                try:
                    writer.stdin.write(
                        replacement.tobytes()
                    )
                except Exception as exc:
                    write_error = str(
                        exc
                    )[:500]
                    break

                written += 1

        if write_error is None:
            write_source(
                seg_end,
                after_end,
            )

    finally:
        cap.release()

        try:
            writer.stdin.close()
        except Exception:
            pass

    stderr = b""

    try:
        stderr = (
            writer.stderr.read()
            if writer.stderr
            else b""
        )
    except Exception:
        pass

    code = writer.wait()

    return {
        "ok": (
            code == 0
            and write_error is None
            and out_path.exists()
        ),
        "relative_path": (
            out_path
            .relative_to(
                WORKSPACE
            )
            .as_posix()
            if out_path.exists()
            else None
        ),
        "source_segment_start_seconds": round(
            seg_start,
            3,
        ),
        "source_segment_end_seconds": round(
            seg_end,
            3,
        ),
        "replacement_seconds": round(
            replacement_seconds,
            3,
        ),
        "frames_written": (
            written
        ),
        "global_top_brand_composition": {
            "enabled": bool(
                req is not None
                and top_actions
                and getattr(
                    req,
                    "compose_top_brand_layers",
                    True,
                )
            ),
            "source_frames_composed": (
                top_composed_frames
            ),
            "first_composition": (
                first_top_composition
            ),
            "placeholder_card_has_own_top_brand": (
                not bool(
                    assets.get(
                        "mid_promo_video_relative_path"
                    )
                )
                and bool(
                    top_actions
                )
            ),
        },
        "error": (
            write_error
            or (
                stderr.decode(
                    "utf-8",
                    errors="replace",
                )[:800]
                if code != 0
                else None
            )
        ),
        "encoder": {
            "engine": (
                "ffmpeg"
            ),
            "codec": (
                "libx264"
            ),
            "crf": int(
                crf
            ),
            "preset": str(
                preset
            ),
            "runtime": (
                runtime
            ),
        },
    }


def _replacement_preview_sync(
    req: BrandingReplacementPreviewRequest
):
    plan_path, plan = (
        _read_json_workspace(
            req.replacement_plan_relative_path,
            "replacement_preview",
        )
    )

    if (
        plan.get(
            "mode"
        )
        != "branding_replacement_plan"
    ):
        raise HTTPException(
            status_code=422,
            detail=(
                "Expected branding_replacement_plan report."
            ),
        )

    source_rel = (
        (
            plan.get(
                "source"
            )
            or {}
        ).get(
            "relative_path"
        )
    )

    video_path = (
        _safe_workspace_path(
            source_rel
        )
    )

    profile = (
        plan.get(
            "profile"
        )
        or {}
    )

    cap = cv2.VideoCapture(
        str(
            video_path
        )
    )

    if not cap.isOpened():
        raise HTTPException(
            status_code=422,
            detail=(
                "Could not open source video."
            ),
        )

    try:
        meta = _video_metadata(
            cap
        )
    finally:
        cap.release()

    width = int(
        meta.get(
            "width"
        )
        or 0
    )

    height = int(
        meta.get(
            "height"
        )
        or 0
    )

    fps = float(
        meta.get(
            "fps"
        )
        or 30.0
    )

    duration = float(
        meta.get(
            "duration_seconds"
        )
        or 0.0
    )

    actions = (
        plan.get(
            "actions"
        )
        or []
    )

    top_actions = [
        action
        for action in actions
        if (
            action.get(
                "type"
            )
            == "fixed_brand_overlay"
            and (
                action.get(
                    "handler"
                )
                == "top_cleanup_brand_overlay"
                or str(
                    action.get(
                        "placement"
                    )
                    or ""
                ).startswith(
                    "top_"
                )
            )
        )
    ]

    timestamp = (
        _app_now().strftime(
            "%Y-%m-%d_%H%M%S"
        )
    )

    out_dir = (
        WORKSPACE
        / "review"
        / "branding_replacement_preview"
        / timestamp
        / video_path.stem
    )

    out_dir.mkdir(
        parents=True,
        exist_ok=True,
    )

    previews = []

    for action in actions:
        if (
            action.get(
                "status"
            )
            == "REVIEW"
            and not req.include_review_actions
        ):
            continue

        action_type = (
            action.get(
                "type"
            )
        )

        action_id = str(
            action.get(
                "action_id"
            )
        )

        if (
            action_type
            == "fixed_brand_overlay"
        ):
            segments = (
                action.get(
                    "active_segments"
                )
                or []
            )

            if segments:
                s = max(
                    segments,
                    key=lambda x: (
                        float(
                            x[
                                "end_seconds"
                            ]
                        )
                        - float(
                            x[
                                "start_seconds"
                            ]
                        )
                    ),
                )

                center = (
                    float(
                        s[
                            "start_seconds"
                        ]
                    )
                    + float(
                        s[
                            "end_seconds"
                        ]
                    )
                ) / 2.0
            else:
                center = min(
                    7.0,
                    max(
                        0.0,
                        duration
                        * 0.2,
                    ),
                )

            out_path = (
                out_dir
                / (
                    f"{action_id}"
                    ".fixed-brand-hq-compare.mp4"
                )
            )

            preview = (
                _render_fixed_banner_preview(
                    video_path,
                    out_path,
                    center,
                    float(
                        req.fixed_preview_seconds
                    ),
                    action,
                    profile,
                    fps,
                    width,
                    height,
                    duration,
                    int(
                        req.crf
                    ),
                    str(
                        req.preset
                    ),
                    req=req,
                )
            )

        elif (
            action_type
            == "moving_brand_overlay"
        ):
            out_path = (
                out_dir
                / (
                    f"{action_id}"
                    ".moving-follow-hq-compare.mp4"
                )
            )

            preview = (
                _render_dynamic_follow_preview(
                    video_path,
                    out_path,
                    action,
                    profile,
                    float(
                        req.dynamic_preview_seconds
                    ),
                    fps,
                    width,
                    height,
                    duration,
                    int(
                        req.crf
                    ),
                    str(
                        req.preset
                    ),
                )
            )

        elif (
            action_type
            == "end_card_replace"
        ):
            out_path = (
                out_dir
                / (
                    "end-card-replacement-preview.mp4"
                )
            )

            preview = (
                _render_endcard_preview(
                    video_path,
                    out_path,
                    action,
                    profile,
                    float(
                        req.end_card_preroll_seconds
                    ),
                    fps,
                    width,
                    height,
                    duration,
                    int(
                        req.crf
                    ),
                    str(
                        req.preset
                    ),
                    top_actions=(
                        top_actions
                    ),
                    req=req,
                )
            )

        elif (
            action_type
            == "mid_promo_replace"
        ):
            out_path = (
                out_dir
                / (
                    f"{action_id}"
                    ".mid-promo-replacement-preview.mp4"
                )
            )

            preview = (
                _render_mid_promo_preview(
                    video_path,
                    out_path,
                    action,
                    profile,
                    float(
                        req.mid_promo_context_seconds
                    ),
                    fps,
                    width,
                    height,
                    duration,
                    int(
                        req.crf
                    ),
                    str(
                        req.preset
                    ),
                    top_actions=(
                        top_actions
                    ),
                    req=req,
                )
            )

        else:
            continue

        previews.append(
            {
                "action_id": (
                    action_id
                ),
                "type": (
                    action_type
                ),
                "status": (
                    action.get(
                        "status"
                    )
                ),
                "preview": (
                    preview
                ),
            }
        )

    result = {
        "ok": any(
            x[
                "preview"
            ].get(
                "ok"
            )
            for x in previews
        ),
        "version": (
            "0.11.5"
        ),
        "mode": (
            "branding_replacement_preview"
        ),
        "source": {
            "relative_path": (
                source_rel
            ),
            "replacement_plan_relative_path": (
                plan_path
                .relative_to(
                    WORKSPACE
                )
                .as_posix()
            ),
        },
        "video": (
            meta
        ),
        "profile": (
            profile
        ),
        "summary": {
            "preview_action_count": len(
                previews
            ),
            "preview_success_count": sum(
                1
                for x in previews
                if x[
                    "preview"
                ].get(
                    "ok"
                )
            ),
            "preview_failure_count": sum(
                1
                for x in previews
                if not x[
                    "preview"
                ].get(
                    "ok"
                )
            ),
            "top_brand_action_count": len(
                top_actions
            ),
            "top_brand_global_composition_enabled": bool(
                req.compose_top_brand_layers
            ),
            "icon_aware_top_cleanup_enabled": True,
            "source_video_modified": False,
            "full_processed_video_created": False,
            "audio_preservation_not_tested_in_preview": True,
            "manual_visual_confirmation_required": True,
        },
        "previews": (
            previews
        ),
        "notes": {
            "v0.11.5_fix": (
                "Top fixed-brand cleanup is composited into source context "
                "frames of Mid Promo and End Card previews. The cleanup ROI is "
                "expanded toward the adjacent icon so the competitor logo is "
                "removed together with the wordmark."
            ),
            "temporal_policy": (
                "Sparse accepted fixed-mask segments are treated as evidence "
                "for one fixed-brand regime spanning first-to-last evidence "
                "plus a small guard. This prevents OCR misses from causing the "
                "top watermark to reappear between evidence samples."
            ),
            "production": (
                "Still preview-only. Full-video render and audio-aware concat "
                "remain deferred until visual composition is accepted."
            ),
        },
        "output_relative_dir": (
            out_dir
            .relative_to(
                WORKSPACE
            )
            .as_posix()
        ),
    }

    report_path = (
        out_dir
        / (
            f"{video_path.stem}"
            ".replacement-preview.json"
        )
    )

    result[
        "report_relative_path"
    ] = (
        report_path
        .relative_to(
            WORKSPACE
        )
        .as_posix()
    )

    report_path.write_text(
        json.dumps(
            result,
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )

    return result




# ---------------------------------------------------------------------------
# v0.11.6 Selective Icon Cleanup + Mid-Promo Transition Bleed Guard
#
# Fix 1: avoid full-rectangle inpaint on the icon extension area.
#         That can create a colored block/smear on textured backgrounds.
#
#         Keep the accepted wordmark cleanup behavior, but clean the adjacent
#         icon with a selective foreground/saliency mask only.
#
# Fix 2: semantic Promo boundaries define CONTENT range, but visual transition
#         frames may straddle that boundary. Preview rendering may expand a few
#         frames OUTSIDE the semantic range to swallow transition bleed.
#
#         Semantic final_segment remains unchanged.
# ---------------------------------------------------------------------------


class BrandingReplacementPreviewRequest(BaseModel):
    replacement_plan_relative_path: str

    include_review_actions: bool = True

    fixed_preview_seconds: float = 2.0
    dynamic_preview_seconds: float = 3.0
    end_card_preroll_seconds: float = 2.0
    mid_promo_context_seconds: float = 1.25

    compose_top_brand_layers: bool = True
    top_brand_span_guard_seconds: float = 1.75

    # Keep expansion geometry, but use it only to LOCATE the icon-side region.
    top_brand_icon_pad_ratio: float = 0.85
    top_brand_opposite_pad_ratio: float = 0.12
    top_brand_vertical_pad_ratio: float = 0.10

    # New selective icon-mask controls.
    top_icon_saliency_threshold: float = 24.0
    top_icon_saturation_threshold: float = 58.0
    top_icon_bright_threshold: float = 205.0
    top_icon_mask_dilate_pixels: int = 2

    # New Promo transition guard.
    # Semantic range is preserved in the plan. Preview removal may expand
    # outward by this many frames on each side.
    mid_promo_transition_guard_frames: int = 4

    # Optional automatic extension when a strong visual transition cluster is
    # detected adjacent to a semantic boundary.
    mid_promo_auto_transition_scan: bool = True
    mid_promo_transition_scan_seconds: float = 0.30
    mid_promo_transition_score_multiplier: float = 1.65
    mid_promo_transition_max_extra_frames: int = 8

    # Terminal cards often begin with a short logo/name fade before the large
    # scene change that the generic end-card detector locks onto.  Keep this
    # separate from Mid Promo guards: the terminal replacement owns the rest of
    # the source, so a small pre-roll is safer than delivering even one source
    # branding frame at the splice.
    end_card_boundary_guard_frames: int = 12
    end_card_boundary_scan_interval_seconds: float = 0.05

    crf: int = 15
    preset: str = "slow"


def _bbox_rect_mask(
    width,
    height,
    bbox,
    padding=0,
):
    b = _clip_bbox(
        bbox,
        int(width),
        int(height),
    )

    x1 = max(
        0,
        int(b["x"]) - int(padding),
    )
    y1 = max(
        0,
        int(b["y"]) - int(padding),
    )
    x2 = min(
        int(width),
        int(b["x"] + b["width"]) + int(padding),
    )
    y2 = min(
        int(height),
        int(b["y"] + b["height"]) + int(padding),
    )

    mask = np.zeros(
        (
            int(height),
            int(width),
        ),
        dtype=np.uint8,
    )

    cv2.rectangle(
        mask,
        (x1, y1),
        (
            max(
                x1,
                x2 - 1,
            ),
            max(
                y1,
                y2 - 1,
            ),
        ),
        255,
        -1,
    )

    return mask


def _icon_side_bbox(
    wordmark_bbox,
    width,
    height,
    placement,
    icon_pad_ratio,
    vertical_pad_ratio,
):
    b = _clip_bbox(
        wordmark_bbox,
        int(width),
        int(height),
    )

    bh = max(
        1,
        int(b["height"]),
    )

    icon_span = max(
        14,
        int(round(
            bh * float(
                icon_pad_ratio
            )
        )),
    )

    vpad = max(
        2,
        int(round(
            bh * float(
                vertical_pad_ratio
            )
        )),
    )

    placement = str(
        placement or ""
    )

    if placement.endswith(
        "_right"
    ):
        x1 = max(
            0,
            int(b["x"])
            - icon_span,
        )
        x2 = int(
            b["x"]
        )
    elif placement.endswith(
        "_left"
    ):
        x1 = int(
            b["x"]
            + b["width"]
        )
        x2 = min(
            int(width),
            x1 + icon_span,
        )
    else:
        x1 = max(
            0,
            int(b["x"])
            - icon_span // 2,
        )
        x2 = min(
            int(width),
            x1 + icon_span,
        )

    y1 = max(
        0,
        int(b["y"])
        - vpad,
    )

    y2 = min(
        int(height),
        int(
            b["y"]
            + b["height"]
        )
        + vpad,
    )

    return {
        "x": int(x1),
        "y": int(y1),
        "width": max(
            1,
            int(x2 - x1),
        ),
        "height": max(
            1,
            int(y2 - y1),
        ),
    }


def _selective_icon_foreground_mask(
    frame,
    icon_bbox,
    saliency_threshold,
    saturation_threshold,
    bright_threshold,
    dilate_pixels,
):
    h, w = frame.shape[:2]

    b = _clip_bbox(
        icon_bbox,
        w,
        h,
    )

    x1 = int(
        b["x"]
    )
    y1 = int(
        b["y"]
    )
    x2 = int(
        b["x"] + b["width"]
    )
    y2 = int(
        b["y"] + b["height"]
    )

    roi = frame[
        y1:y2,
        x1:x2,
    ]

    mask = np.zeros(
        (
            h,
            w,
        ),
        dtype=np.uint8,
    )

    if roi.size == 0:
        return mask

    # Estimate local background with a fairly wide Gaussian blur.
    bg = cv2.GaussianBlur(
        roi,
        (0, 0),
        sigmaX=max(
            2.0,
            min(
                roi.shape[:2]
            ) / 6.0,
        ),
    )

    diff = cv2.absdiff(
        roi,
        bg,
    )

    diff_gray = cv2.cvtColor(
        diff,
        cv2.COLOR_BGR2GRAY,
    )

    hsv = cv2.cvtColor(
        roi,
        cv2.COLOR_BGR2HSV,
    )

    saturation = hsv[
        ...,
        1
    ]

    value = hsv[
        ...,
        2
    ]

    # General foreground logic:
    # - locally high contrast glyph/icon edge
    # - OR strongly saturated colored logo material
    # - OR very bright glyph material
    #
    # Restrict to the icon-side ROI so textured background elsewhere is never
    # added to this mask.
    local = (
        (
            diff_gray
            >= float(
                saliency_threshold
            )
        )
        | (
            saturation
            >= float(
                saturation_threshold
            )
        )
        | (
            value
            >= float(
                bright_threshold
            )
        )
    ).astype(
        np.uint8
    ) * 255

    # Remove tiny isolated noise before dilation.
    kernel_open = np.ones(
        (
            2,
            2,
        ),
        dtype=np.uint8,
    )

    local = cv2.morphologyEx(
        local,
        cv2.MORPH_OPEN,
        kernel_open,
        iterations=1,
    )

    dilate_pixels = max(
        0,
        int(
            dilate_pixels
        ),
    )

    if dilate_pixels > 0:
        k = (
            dilate_pixels
            * 2
            + 1
        )

        kernel = np.ones(
            (
                k,
                k,
            ),
            dtype=np.uint8,
        )

        local = cv2.dilate(
            local,
            kernel,
            iterations=1,
        )

    # Avoid turning a noisy textured region back into a rectangle.
    # If mask coverage is suspiciously high, keep only the strongest local
    # contrast/saturation pixels.
    coverage = float(
        np.count_nonzero(
            local
        )
    ) / float(
        max(
            1,
            local.size,
        )
    )

    if coverage > 0.62:
        stricter = (
            (
                diff_gray
                >= float(
                    saliency_threshold
                )
                * 1.35
            )
            | (
                saturation
                >= max(
                    78.0,
                    float(
                        saturation_threshold
                    )
                    * 1.25,
                )
            )
            | (
                value
                >= max(
                    225.0,
                    float(
                        bright_threshold
                    ),
                )
            )
        ).astype(
            np.uint8
        ) * 255

        if dilate_pixels > 0:
            k = (
                dilate_pixels
                * 2
                + 1
            )

            kernel = np.ones(
                (
                    k,
                    k,
                ),
                dtype=np.uint8,
            )

            stricter = cv2.dilate(
                stricter,
                kernel,
                iterations=1,
            )

        local = stricter

    mask[
        y1:y2,
        x1:x2,
    ] = local

    return mask


def _apply_top_brand_composition(
    frame,
    t,
    top_actions,
    profile,
    width,
    height,
    duration,
    req,
):
    processed = (
        frame.copy()
    )

    applied = []

    if not bool(
        getattr(
            req,
            "compose_top_brand_layers",
            True,
        )
    ):
        return (
            processed,
            applied,
        )

    for action in (
        top_actions
        or []
    ):
        span = _top_action_span(
            action,
            duration,
            float(
                getattr(
                    req,
                    "top_brand_span_guard_seconds",
                    1.75,
                )
            ),
        )

        if span is None:
            continue

        if not (
            float(
                span[
                    "start_seconds"
                ]
            )
            <= float(t)
            <= float(
                span[
                    "end_seconds"
                ]
            )
        ):
            continue

        base_bbox = (
            _top_action_bbox_at_time(
                action,
                t,
            )
        )

        if not base_bbox:
            continue

        placement = str(
            action.get(
                "placement"
            )
            or ""
        )

        # 1) Preserve the previously successful wordmark cleanup behavior.
        wordmark_mask = (
            _bbox_rect_mask(
                width,
                height,
                base_bbox,
                padding=1,
            )
        )

        processed = cv2.inpaint(
            processed,
            wordmark_mask,
            3.0,
            cv2.INPAINT_TELEA,
        )

        # 2) Clean the adjacent logo/icon selectively instead of inpainting the
        # whole expansion rectangle (which caused colored blocks/smears).
        icon_bbox = (
            _icon_side_bbox(
                base_bbox,
                width,
                height,
                placement,
                float(
                    getattr(
                        req,
                        "top_brand_icon_pad_ratio",
                        0.85,
                    )
                ),
                float(
                    getattr(
                        req,
                        "top_brand_vertical_pad_ratio",
                        0.10,
                    )
                ),
            )
        )

        icon_mask = (
            _selective_icon_foreground_mask(
                processed,
                icon_bbox,
                float(
                    getattr(
                        req,
                        "top_icon_saliency_threshold",
                        24.0,
                    )
                ),
                float(
                    getattr(
                        req,
                        "top_icon_saturation_threshold",
                        58.0,
                    )
                ),
                float(
                    getattr(
                        req,
                        "top_icon_bright_threshold",
                        205.0,
                    )
                ),
                int(
                    getattr(
                        req,
                        "top_icon_mask_dilate_pixels",
                        2,
                    )
                ),
            )
        )

        if np.count_nonzero(
            icon_mask
        ) > 0:
            processed = cv2.inpaint(
                processed,
                icon_mask,
                2.5,
                cv2.INPAINT_TELEA,
            )

        processed = (
            _draw_clean_brand_mark(
                processed,
                base_bbox,
                profile,
                placement,
            )
        )

        applied.append(
            {
                "action_id": (
                    action.get(
                        "action_id"
                    )
                ),
                "placement": (
                    placement
                ),
                "base_bbox": (
                    base_bbox
                ),
                "icon_bbox": (
                    icon_bbox
                ),
                "icon_mask_pixels": int(
                    np.count_nonzero(
                        icon_mask
                    )
                ),
                "span": (
                    span
                ),
            }
        )

    return (
        processed,
        applied,
    )


def _read_frame_at_seconds(
    cap,
    t,
):
    cap.set(
        cv2.CAP_PROP_POS_MSEC,
        max(
            0.0,
            float(t),
        )
        * 1000.0,
    )

    ok, frame = cap.read()

    if not ok or frame is None:
        return None

    return frame


def _frame_change_score(
    a,
    b,
):
    if (
        a is None
        or b is None
    ):
        return 0.0

    ga = cv2.cvtColor(
        a,
        cv2.COLOR_BGR2GRAY,
    )

    gb = cv2.cvtColor(
        b,
        cv2.COLOR_BGR2GRAY,
    )

    # Downscale for stable/cheap transition scoring.
    target_w = 180

    scale = (
        target_w
        / float(
            max(
                1,
                ga.shape[1],
            )
        )
    )

    target_h = max(
        1,
        int(round(
            ga.shape[0]
            * scale
        )),
    )

    ga = cv2.resize(
        ga,
        (
            target_w,
            target_h,
        ),
        interpolation=cv2.INTER_AREA,
    )

    gb = cv2.resize(
        gb,
        (
            target_w,
            target_h,
        ),
        interpolation=cv2.INTER_AREA,
    )

    diff = cv2.absdiff(
        ga,
        gb,
    )

    mean_diff = float(
        np.mean(
            diff
        )
    )

    # Edge-structure difference helps detect spinning/rotation transitions that
    # may not be simple brightness cuts.
    ea = cv2.Canny(
        ga,
        70,
        150,
    )

    eb = cv2.Canny(
        gb,
        70,
        150,
    )

    edge_diff = float(
        np.mean(
            cv2.absdiff(
                ea,
                eb,
            )
        )
    ) / 255.0 * 30.0

    return (
        mean_diff
        + edge_diff
    )


def _transition_guard_for_boundary(
    video_path,
    boundary_seconds,
    fps,
    duration,
    direction,
    req,
):
    base_frames = max(
        0,
        int(
            getattr(
                req,
                "mid_promo_transition_guard_frames",
                4,
            )
        ),
    )

    base_extra = (
        base_frames
        / float(
            max(
                1e-6,
                fps,
            )
        )
    )

    if not bool(
        getattr(
            req,
            "mid_promo_auto_transition_scan",
            True,
        )
    ):
        return {
            "extra_seconds": round(
                base_extra,
                6,
            ),
            "base_guard_frames": (
                base_frames
            ),
            "auto_scan_used": False,
            "detected_extra_frames": 0,
        }

    scan_seconds = max(
        0.05,
        float(
            getattr(
                req,
                "mid_promo_transition_scan_seconds",
                0.30,
            )
        ),
    )

    max_extra_frames = max(
        base_frames,
        int(
            getattr(
                req,
                "mid_promo_transition_max_extra_frames",
                8,
            )
        ),
    )

    frame_dt = 1.0 / float(
        max(
            1e-6,
            fps,
        )
    )

    cap = cv2.VideoCapture(
        str(
            video_path
        )
    )

    if not cap.isOpened():
        return {
            "extra_seconds": round(
                base_extra,
                6,
            ),
            "base_guard_frames": (
                base_frames
            ),
            "auto_scan_used": False,
            "detected_extra_frames": 0,
            "error": (
                "Could not open video for transition scan."
            ),
        }

    try:
        count = max(
            3,
            int(round(
                scan_seconds
                * fps
            )),
        )

        times = []

        if direction == "start":
            # Look backward from the semantic onset. If the last few frames
            # before onset are a transition cluster, remove them too.
            for i in range(
                count,
                -1,
                -1,
            ):
                times.append(
                    max(
                        0.0,
                        float(
                            boundary_seconds
                        )
                        - i
                        * frame_dt,
                    )
                )
        else:
            # Look forward from semantic end.
            for i in range(
                0,
                count + 1,
            ):
                times.append(
                    min(
                        float(
                            duration
                        ),
                        float(
                            boundary_seconds
                        )
                        + i
                        * frame_dt,
                    )
                )

        frames = [
            _read_frame_at_seconds(
                cap,
                t,
            )
            for t in times
        ]

        scores = []

        for i in range(
            1,
            len(frames),
        ):
            scores.append(
                _frame_change_score(
                    frames[
                        i - 1
                    ],
                    frames[
                        i
                    ],
                )
            )

        if not scores:
            detected_frames = 0
        else:
            median = float(
                np.median(
                    scores
                )
            )

            threshold = max(
                7.0,
                median
                * float(
                    getattr(
                        req,
                        "mid_promo_transition_score_multiplier",
                        1.65,
                    )
                ),
            )

            high = [
                score >= threshold
                for score in scores
            ]

            detected_frames = 0

            if direction == "start":
                # Count strong transitions nearest the boundary, walking
                # backward. Allow one weak connector frame inside a cluster.
                weak_budget = 1

                for flag in reversed(
                    high
                ):
                    if flag:
                        detected_frames += 1
                        weak_budget = 1
                    elif (
                        detected_frames > 0
                        and weak_budget > 0
                    ):
                        detected_frames += 1
                        weak_budget -= 1
                    elif detected_frames > 0:
                        break
            else:
                weak_budget = 1

                for flag in high:
                    if flag:
                        detected_frames += 1
                        weak_budget = 1
                    elif (
                        detected_frames > 0
                        and weak_budget > 0
                    ):
                        detected_frames += 1
                        weak_budget -= 1
                    elif detected_frames > 0:
                        break

            detected_frames = min(
                max_extra_frames,
                detected_frames,
            )

        final_frames = max(
            base_frames,
            detected_frames,
        )

        return {
            "extra_seconds": round(
                final_frames
                * frame_dt,
                6,
            ),
            "base_guard_frames": (
                base_frames
            ),
            "auto_scan_used": True,
            "detected_extra_frames": int(
                detected_frames
            ),
            "final_guard_frames": int(
                final_frames
            ),
        }

    finally:
        cap.release()


def _render_mid_promo_preview(
    video_path,
    out_path,
    action,
    profile,
    context_seconds,
    fps,
    width,
    height,
    duration,
    crf,
    preset,
    top_actions=None,
    req=None,
):
    semantic_start = float(
        action[
            "start_seconds"
        ]
    )

    semantic_end = float(
        action[
            "end_seconds"
        ]
    )

    if req is None:
        class _PreviewDefaults:
            compose_top_brand_layers = True
            top_brand_span_guard_seconds = 1.75
            top_brand_icon_pad_ratio = 0.85
            top_brand_vertical_pad_ratio = 0.10
            top_icon_saliency_threshold = 24.0
            top_icon_saturation_threshold = 58.0
            top_icon_bright_threshold = 205.0
            top_icon_mask_dilate_pixels = 2
            mid_promo_transition_guard_frames = 4
            mid_promo_auto_transition_scan = True
            mid_promo_transition_scan_seconds = 0.30
            mid_promo_transition_score_multiplier = 1.65
            mid_promo_transition_max_extra_frames = 8

        req_for_render = (
            _PreviewDefaults()
        )
    else:
        req_for_render = req

    start_guard = (
        _transition_guard_for_boundary(
            video_path,
            semantic_start,
            fps,
            duration,
            "start",
            req_for_render,
        )
    )

    end_guard = (
        _transition_guard_for_boundary(
            video_path,
            semantic_end,
            fps,
            duration,
            "end",
            req_for_render,
        )
    )

    render_start = max(
        0.0,
        semantic_start
        - float(
            start_guard[
                "extra_seconds"
            ]
        ),
    )

    render_end = min(
        float(
            duration
        ),
        semantic_end
        + float(
            end_guard[
                "extra_seconds"
            ]
        ),
    )

    before_start = max(
        0.0,
        render_start
        - float(
            context_seconds
        ),
    )

    after_end = (
        min(
            duration,
            render_end
            + float(
                context_seconds
            ),
        )
        if duration > 0
        else render_end
        + float(
            context_seconds
        )
    )

    writer, runtime = (
        _open_x264_raw_writer(
            out_path,
            width,
            height,
            fps,
            crf,
            preset,
        )
    )

    assets = (
        profile.get(
            "assets"
        )
        or {}
    )

    logo = _load_bgr_asset(
        assets.get(
            "logo_image_relative_path"
        )
    )

    replacement = (
        _generated_brand_card(
            width,
            height,
            profile[
                "product_name"
            ],
            profile[
                "brand_name"
            ],
            logo_image=logo,
            subtitle=(
                "Promo replacement preview"
            ),
        )
    )

    if not assets.get(
        "mid_promo_video_relative_path"
    ):
        for top_action in (
            top_actions
            or []
        )[:1]:
            bbox = top_action.get(
                "bbox"
            )

            if bbox:
                replacement = (
                    _draw_clean_brand_mark(
                        replacement,
                        bbox,
                        profile,
                        top_action.get(
                            "placement"
                        ),
                    )
                )

    replacement_seconds = min(
        3.0,
        max(
            1.5,
            render_end
            - render_start,
        ),
    )

    cap = cv2.VideoCapture(
        str(
            video_path
        )
    )

    if not cap.isOpened():
        raise HTTPException(
            status_code=422,
            detail=(
                "Could not open source video."
            ),
        )

    written = 0
    write_error = None

    top_composed_frames = 0
    first_top_composition = None

    def write_source(
        a,
        b,
    ):
        nonlocal written
        nonlocal write_error
        nonlocal top_composed_frames
        nonlocal first_top_composition

        cap.set(
            cv2.CAP_PROP_POS_MSEC,
            a * 1000.0,
        )

        count = max(
            0,
            int(round(
                (
                    b
                    - a
                )
                * fps
            )),
        )

        for idx in range(
            count
        ):
            ok, frame = cap.read()

            if (
                not ok
                or frame is None
            ):
                break

            t = (
                a
                + idx
                / float(fps)
            )

            if (
                req_for_render is not None
                and top_actions
            ):
                frame, applied = (
                    _apply_top_brand_composition(
                        frame,
                        t,
                        top_actions,
                        profile,
                        width,
                        height,
                        duration,
                        req_for_render,
                    )
                )

                if applied:
                    top_composed_frames += 1

                    if first_top_composition is None:
                        first_top_composition = (
                            applied[0]
                        )

            try:
                writer.stdin.write(
                    frame.tobytes()
                )
            except Exception as exc:
                write_error = str(
                    exc
                )[:500]
                return

            written += 1

    try:
        write_source(
            before_start,
            render_start,
        )

        if write_error is None:
            for _ in range(
                max(
                    1,
                    int(round(
                        replacement_seconds
                        * fps
                    )),
                )
            ):
                try:
                    writer.stdin.write(
                        replacement.tobytes()
                    )
                except Exception as exc:
                    write_error = str(
                        exc
                    )[:500]
                    break

                written += 1

        if write_error is None:
            write_source(
                render_end,
                after_end,
            )

    finally:
        cap.release()

        try:
            writer.stdin.close()
        except Exception:
            pass

    stderr = b""

    try:
        stderr = (
            writer.stderr.read()
            if writer.stderr
            else b""
        )
    except Exception:
        pass

    code = writer.wait()

    return {
        "ok": (
            code == 0
            and write_error is None
            and out_path.exists()
        ),
        "relative_path": (
            out_path
            .relative_to(
                WORKSPACE
            )
            .as_posix()
            if out_path.exists()
            else None
        ),
        "semantic_source_segment": {
            "start_seconds": round(
                semantic_start,
                3,
            ),
            "end_seconds": round(
                semantic_end,
                3,
            ),
        },
        "render_removal_segment": {
            "start_seconds": round(
                render_start,
                3,
            ),
            "end_seconds": round(
                render_end,
                3,
            ),
            "start_guard": (
                start_guard
            ),
            "end_guard": (
                end_guard
            ),
        },
        # Keep old fields for compatibility, but report the actual render cut.
        "source_segment_start_seconds": round(
            render_start,
            3,
        ),
        "source_segment_end_seconds": round(
            render_end,
            3,
        ),
        "replacement_seconds": round(
            replacement_seconds,
            3,
        ),
        "frames_written": (
            written
        ),
        "global_top_brand_composition": {
            "enabled": bool(
                top_actions
                and getattr(
                    req_for_render,
                    "compose_top_brand_layers",
                    True,
                )
            ),
            "source_frames_composed": (
                top_composed_frames
            ),
            "first_composition": (
                first_top_composition
            ),
            "placeholder_card_has_own_top_brand": (
                not bool(
                    assets.get(
                        "mid_promo_video_relative_path"
                    )
                )
                and bool(
                    top_actions
                )
            ),
        },
        "error": (
            write_error
            or (
                stderr.decode(
                    "utf-8",
                    errors="replace",
                )[:800]
                if code != 0
                else None
            )
        ),
        "encoder": {
            "engine": (
                "ffmpeg"
            ),
            "codec": (
                "libx264"
            ),
            "crf": int(
                crf
            ),
            "preset": str(
                preset
            ),
            "runtime": (
                runtime
            ),
        },
    }


# v0.11.5 preview route remains the orchestration layer. This override only
# updates request schema and helper behavior used by that route.
_replacement_preview_sync_v0115 = (
    _replacement_preview_sync
)


def _replacement_preview_sync(
    req: BrandingReplacementPreviewRequest
):
    result = (
        _replacement_preview_sync_v0115(
            req
        )
    )

    result[
        "version"
    ] = "0.11.6"

    summary = result.setdefault(
        "summary",
        {},
    )

    summary[
        "selective_icon_cleanup_enabled"
    ] = True

    summary[
        "mid_promo_transition_bleed_guard_enabled"
    ] = True

    result["notes"] = {
        **(
            result.get(
                "notes"
            )
            or {}
        ),
        "v0.11.6_fix": (
            "Top adjacent icon cleanup now uses a selective foreground mask "
            "instead of full-rectangle inpaint, reducing colored-block artifacts. "
            "Mid Promo rendering may expand a few frames outside the accepted "
            "semantic segment to swallow visual transition/rotation bleed."
        ),
        "semantic_boundary_policy": (
            "Accepted semantic final_segment remains unchanged. Any Promo "
            "transition guard is a render-only outward expansion."
        ),
    }

    report_rel = (
        result.get(
            "report_relative_path"
        )
    )

    if report_rel:
        _safe_workspace_path(
            report_rel
        ).write_text(
            json.dumps(
                result,
                ensure_ascii=False,
                indent=2,
            ),
            encoding="utf-8",
        )

    return result




# ---------------------------------------------------------------------------
# v0.12.0 Draft Full Render
#
# First full-timeline renderer.
#
# Goals:
#   - consume the already accepted Replacement Plan
#   - preserve story video + story audio
#   - apply accepted top fixed-brand cleanup to source story frames
#   - replace Mid Promo as a whole segment
#   - trim competitor End Card and append own End Card
#   - keep semantic boundaries immutable; render-only transition guard may
#     expand Mid Promo outward by a few frames
#   - support real brand assets later without re-running detection
#
# Current diagonal tiled watermark remains intentionally parked.
# ---------------------------------------------------------------------------


class BrandingReplacementRenderRequest(BaseModel):
    replacement_plan_relative_path: str

    include_review_actions: bool = True
    allow_placeholder_assets: bool = True

    # Top brand cleanup/overlay composition.
    watermark_treatment_mode: str = "rebrand_fixed_clean_dynamic"
    compose_top_brand_layers: bool = True
    top_brand_span_guard_seconds: float = 1.75
    top_brand_icon_pad_ratio: float = 0.85
    top_brand_opposite_pad_ratio: float = 0.12
    top_brand_vertical_pad_ratio: float = 0.10
    top_icon_saliency_threshold: float = 24.0
    top_icon_saturation_threshold: float = 58.0
    top_icon_bright_threshold: float = 205.0
    top_icon_mask_dilate_pixels: int = 2

    # Future asset presentation.
    # auto: logo/icon + text when image exists, otherwise text.
    # logo_only: image only when available.
    # icon_text: image + brand text.
    # text_only: generated brand text only.
    top_brand_mode: str = "auto"

    # Mid Promo render-only transition bleed protection.
    mid_promo_transition_guard_frames: int = 4
    mid_promo_auto_transition_scan: bool = True
    mid_promo_transition_scan_seconds: float = 0.30
    mid_promo_transition_score_multiplier: float = 1.65
    mid_promo_transition_max_extra_frames: int = 8

    # Placeholder durations when real assets are absent.
    placeholder_mid_promo_seconds: float = 3.0
    placeholder_end_card_seconds: float = 3.0

    # Encoding/audio normalization.
    # Fast default for the full-frame compositor; callers can still override
    # these fields for archival encodes.
    crf: int = 18
    preset: str = "veryfast"
    audio_sample_rate: int = 48000
    audio_channels: int = 2
    audio_bitrate: str = "160k"

    keep_intermediate_files: bool = False


def _ffprobe_path():
    ffmpeg = shutil.which("ffmpeg")
    if ffmpeg:
        sibling = Path(ffmpeg).with_name("ffprobe")
        if sibling.exists():
            return str(sibling)
    return shutil.which("ffprobe")


def _probe_media(path):
    ffprobe = _ffprobe_path()

    result = {
        "duration_seconds": None,
        "has_video": False,
        "has_audio": False,
        "audio_channels": None,
        "audio_sample_rate": None,
    }

    if not ffprobe:
        # OpenCV fallback for video duration only.
        cap = cv2.VideoCapture(str(path))
        if cap.isOpened():
            try:
                meta = _video_metadata(cap)
                result["duration_seconds"] = float(
                    meta.get("duration_seconds") or 0.0
                )
                result["has_video"] = True
            finally:
                cap.release()
        return result

    p = subprocess.run(
        [
            ffprobe,
            "-v",
            "error",
            "-show_entries",
            "format=duration",
            "-show_streams",
            "-of",
            "json",
            str(path),
        ],
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
    )

    if p.returncode != 0:
        return result

    try:
        payload = json.loads(p.stdout or "{}")
    except Exception:
        return result

    try:
        result["duration_seconds"] = float(
            (payload.get("format") or {}).get("duration")
            or 0.0
        )
    except Exception:
        pass

    for stream in payload.get("streams") or []:
        codec_type = str(stream.get("codec_type") or "")
        if codec_type == "video":
            result["has_video"] = True
        elif codec_type == "audio":
            result["has_audio"] = True
            result["audio_channels"] = stream.get("channels")
            result["audio_sample_rate"] = stream.get("sample_rate")

    return result


def _resolve_optional_asset(relative_path):
    if not relative_path:
        return None

    path = _safe_workspace_path(
        str(relative_path)
    )

    if not path.exists():
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "replacement_render",
                "error": "asset_not_found",
                "relative_path": str(relative_path),
            },
        )

    return path


def _draw_clean_brand_mark_mode(
    frame,
    bbox,
    profile,
    placement,
    mode="auto",
):
    mode = str(mode or "auto").strip().lower()

    if mode not in (
        "auto",
        "logo_only",
        "icon_text",
        "text_only",
    ):
        mode = "auto"

    if mode == "auto":
        return _draw_clean_brand_mark(
            frame,
            bbox,
            profile,
            placement,
        )

    temp_profile = json.loads(
        json.dumps(
            profile,
            ensure_ascii=False,
        )
    )

    assets = temp_profile.setdefault(
        "assets",
        {},
    )

    if mode == "text_only":
        assets["logo_image_relative_path"] = None
        assets["icon_image_relative_path"] = None
        return _draw_clean_brand_mark(
            frame,
            bbox,
            temp_profile,
            placement,
        )

    if mode == "logo_only":
        # Draw only the configured logo/icon and suppress generated text.
        temp_profile["brand_name"] = ""
        temp_profile["product_name"] = ""
        return _draw_clean_brand_mark(
            frame,
            bbox,
            temp_profile,
            placement,
        )

    # icon_text
    return _draw_clean_brand_mark(
        frame,
        bbox,
        temp_profile,
        placement,
    )



def _fast_local_cover_color(frame, bbox):
    h, w = frame.shape[:2]
    b = _clip_bbox(bbox, w, h)
    x0, y0 = int(b["x"]), int(b["y"])
    x1 = min(w, x0 + int(b["width"]))
    y1 = min(h, y0 + int(b["height"]))
    pad = max(3, int(round(min(max(1, int(b["width"])), max(1, int(b["height"]))) * 0.12)))

    samples = []
    for crop in (
        frame[max(0, y0-pad):y0, x0:x1],
        frame[y1:min(h, y1+pad), x0:x1],
        frame[y0:y1, max(0, x0-pad):x0],
        frame[y0:y1, x1:min(w, x1+pad)],
    ):
        if crop.size:
            samples.append(crop.reshape(-1, 3))

    if samples:
        pixels = np.concatenate(samples, axis=0)
    else:
        roi = frame[y0:y1, x0:x1]
        pixels = roi.reshape(-1, 3) if roi.size else np.array([[32, 32, 32]], dtype=np.uint8)

    mean = np.mean(pixels, axis=0)
    return tuple(int(max(0, min(255, round(float(v))))) for v in mean)


def _draw_fast_local_cover_plate(frame, bbox):
    h, w = frame.shape[:2]
    b = _clip_bbox(bbox, w, h)
    color = _fast_local_cover_color(frame, b)
    x0, y0 = int(b["x"]), int(b["y"])
    x1 = min(w - 1, x0 + int(b["width"]))
    y1 = min(h - 1, y0 + int(b["height"]))
    cv2.rectangle(frame, (x0, y0), (x1, y1), color, thickness=-1)
    return frame


def _apply_top_brand_composition_render(
    frame,
    t,
    top_actions,
    profile,
    width,
    height,
    duration,
    req,
):
    # Use v0.11.6 selective cleanup, then optionally redraw in requested mode.
    processed, applied = _apply_top_brand_composition(
        frame,
        t,
        top_actions,
        profile,
        width,
        height,
        duration,
        req,
    )

    mode = str(
        getattr(
            req,
            "top_brand_mode",
            "auto",
        )
        or "auto"
    ).lower()

    if mode == "auto":
        return processed, applied

    # v0.11.6 already drew its default brand mark. For non-auto modes, redo
    # only the small brand area from the cleaned original by replaying cleanup
    # and drawing the requested mode. This is used mainly when real assets are
    # supplied later.
    base = frame.copy()
    reapplied = []

    for action in top_actions or []:
        span = _top_action_span(
            action,
            duration,
            float(
                getattr(
                    req,
                    "top_brand_span_guard_seconds",
                    1.75,
                )
            ),
        )

        if span is None:
            continue

        if not (
            float(span["start_seconds"])
            <= float(t)
            <= float(span["end_seconds"])
        ):
            continue

        base_bbox = _top_action_bbox_at_time(
            action,
            t,
        )

        if not base_bbox:
            continue

        placement = str(
            action.get("placement") or ""
        )

        wordmark_mask = _bbox_rect_mask(
            width,
            height,
            base_bbox,
            padding=1,
        )

        base = cv2.inpaint(
            base,
            wordmark_mask,
            3.0,
            cv2.INPAINT_TELEA,
        )

        icon_bbox = _icon_side_bbox(
            base_bbox,
            width,
            height,
            placement,
            float(
                getattr(
                    req,
                    "top_brand_icon_pad_ratio",
                    0.85,
                )
            ),
            float(
                getattr(
                    req,
                    "top_brand_vertical_pad_ratio",
                    0.10,
                )
            ),
        )

        icon_mask = _selective_icon_foreground_mask(
            base,
            icon_bbox,
            float(
                getattr(
                    req,
                    "top_icon_saliency_threshold",
                    24.0,
                )
            ),
            float(
                getattr(
                    req,
                    "top_icon_saturation_threshold",
                    58.0,
                )
            ),
            float(
                getattr(
                    req,
                    "top_icon_bright_threshold",
                    205.0,
                )
            ),
            int(
                getattr(
                    req,
                    "top_icon_mask_dilate_pixels",
                    2,
                )
            ),
        )

        if np.count_nonzero(icon_mask) > 0:
            base = cv2.inpaint(
                base,
                icon_mask,
                2.5,
                cv2.INPAINT_TELEA,
            )

        base = _draw_clean_brand_mark_mode(
            base,
            base_bbox,
            profile,
            placement,
            mode,
        )

        reapplied.append(
            {
                "action_id": action.get("action_id"),
                "placement": placement,
                "base_bbox": base_bbox,
                "icon_bbox": icon_bbox,
                "icon_mask_pixels": int(
                    np.count_nonzero(icon_mask)
                ),
                "span": span,
                "top_brand_mode": mode,
            }
        )

    return base, reapplied



def _operator_dynamic_brand_tracks_from_census(
    census_report_relative_path,
):
    if not census_report_relative_path:
        return []

    try:
        _, report = _read_json_workspace(
            census_report_relative_path,
            "operator_dynamic_brand_cover",
        )
    except Exception:
        return []

    video = (
        report.get(
            "video"
        )
        or {}
    )

    scan = (
        report.get(
            "scan"
        )
        or {}
    )

    width = int(
        video.get(
            "width"
        )
        or 0
    )

    height = int(
        video.get(
            "height"
        )
        or 0
    )

    duration = float(
        video.get(
            "duration_seconds"
        )
        or 0.0
    )

    effective_interval = float(
        scan.get(
            "effective_interval_seconds"
        )
        or scan.get(
            "requested_interval_seconds"
        )
        or 1.0
    )

    # Strict tracks are rendered only between real observations.  Keep the
    # legacy hold for compatibility reports, but do not use it to extend a
    # verified identity track outside its observed visibility window.
    base_hold_seconds = max(
        0.45,
        min(
            1.15,
            effective_interval * 0.72,
        ),
    )

    tracks = []

    strict_payload = report.get("verified_dynamic_identity") or {}
    # A current census with strict mode enabled is authoritative.  Do not fall
    # back to broad OCR spatial clusters when it yields no valid track: that
    # absence is the safety decision that prevents subtitles/title cards from
    # receiving an own-brand moving cover.  Historical reports without this
    # field retain the compatibility paths below.
    if bool(strict_payload.get("enabled")):
        for strict_track in strict_payload.get("tracks") or []:
            points = []
            for point in strict_track.get("points") or []:
                bbox = point.get("bbox") or {}
                if not bbox:
                    continue
                try:
                    points.append({
                        "time_seconds": round(float(point.get("time_seconds") or 0.0), 3),
                        "bbox": _clip_bbox(bbox, width, height),
                        "similarity": float(point.get("similarity") or point.get("template_score") or 0.0),
                        "ocr_confidence": float(point.get("ocr_confidence") or 0.0),
                        "exact": True,
                        "target": point.get("target") or strict_track.get("target"),
                        "template_relative_path": point.get("template_relative_path"),
                        "edge_reference": bool(point.get("edge_reference")),
                    })
                except Exception:
                    continue
            if len(points) < 3:
                continue
            # Re-validate persisted reports at render time as well.  Reports
            # generated before the stricter visual policy may still contain
            # low-score template tracks; never let a stale report authorize a
            # new watermark overlay.
            is_reviewed_visual = "reviewed_template" in str(strict_track.get("handler") or "") or "reviewed_competitor_watermark_template" in str(strict_track.get("identity_evidence") or "")
            if is_reviewed_visual:
                mean_similarity = sum(float(point.get("similarity") or 0.0) for point in points) / max(1, len(points))
                template_paths = " ".join(
                    str(
                        point.get("template_relative_path")
                        or point.get("identity_evidence")
                        or ""
                    )
                    for point in (strict_track.get("points") or [])
                ).casefold()
                native_edge_evidence = any(
                    "dynamic_watermark_reference_reelshort_v2.png"
                    in str(point.get("template_relative_path") or point.get("identity_evidence") or "")
                    for point in (strict_track.get("points") or [])
                )
                # Semi-transparent source-brand marks have materially lower
                # normalized template scores than opaque edge references. The
                # reviewed source/icon template is still identity-bound, so a
                # 0.30 floor is safe when combined with the strict handler,
                # point-count and area-stability checks below.
                reviewed_source_template = (
                    "source/icon.png" in template_paths
                    or "source\\icon.png" in template_paths
                )
                score_floor = (
                    0.20
                    if native_edge_evidence
                    else 0.30
                    if reviewed_source_template
                    else 0.45
                )
                if mean_similarity < score_floor:
                    continue
                areas = [float(point["bbox"]["width"] * point["bbox"]["height"]) for point in points]
                median_area = float(np.median(areas)) if areas else 0.0
                if median_area > 0.0 and (max(areas) - min(areas)) / median_area > 0.75:
                    continue
            tracks.append({
                "cluster_id": strict_track.get("track_id"),
                "classification": strict_track.get("classification") or "verified_moving_competitor_watermark",
                "recovery_source": strict_track.get("handler") or "verified_identity_dense_track",
                "target": strict_track.get("target"),
                "point_count": len(points),
                "hold_seconds": 0.0,
                "max_interpolation_gap_seconds": float(
                    strict_track.get("max_interpolation_gap_seconds") or 0.32
                ),
                "tracking_policy": strict_track.get("tracking_policy")
                or "verified_identity_only__no_pre_or_post_extrapolation__hide_on_tracking_gap",
                "identity_evidence": strict_track.get("identity_evidence"),
                "movement_px": strict_track.get("movement_px"),
                "points": points,
            })
        return tracks

    # Preferred route: a reviewed visual template identifies the faint alpha
    # wordmark itself, while OCR candidates remain only supporting evidence.
    # This prevents promo cards/subtitles with the word "ReelShort" from being
    # mistaken for a dynamic watermark.
    visual_payload = report.get("dynamic_visual_watermark") or {}
    for visual_track in visual_payload.get("tracks") or []:
        points = []
        for point in visual_track.get("points") or []:
            bbox = point.get("bbox") or {}
            if not bbox:
                continue
            points.append(
                {
                    "time_seconds": round(float(point.get("time_seconds") or 0.0), 3),
                    "bbox": _clip_bbox(bbox, width, height),
                    "similarity": float(point.get("template_score") or 0.0),
                    "ocr_confidence": 0.0,
                    "exact": False,
                    "target": "semi_transparent_visual_watermark",
                }
            )
        if len(points) >= 2:
            tracks.append(
                {
                    "cluster_id": visual_track.get("track_id"),
                    "classification": "semi_transparent_visual_watermark",
                    "recovery_source": "reviewed_alpha_template_track",
                    "target": "semi_transparent_visual_watermark",
                    "point_count": len(points),
                    "hold_seconds": round(
                        max(base_hold_seconds, min(0.80, effective_interval * 0.70)),
                        3,
                    ),
                    "points": points,
                }
            )

    # When the visual detector is enabled, never fall back to OCR-driven
    # moving/recovered tracks. OCR can still identify the top fixed mark, but
    # broad in-scene promo text must not generate a dynamic own-brand cover.
    if bool(visual_payload.get("enabled")):
        return tracks

    for cluster in (
        report.get(
            "clusters"
        )
        or []
    ):
        classification = str(
            cluster.get(
                "classification"
            )
            or ""
        )

        if classification not in {
            "moving_or_transient_candidate",
            "fixed_candidate",
        }:
            continue

        hits = (
            _hits_for_cluster(
                report,
                cluster,
            )
        )

        best_by_time = {}

        for hit in hits:
            try:
                t = round(
                    float(
                        hit.get(
                            "time_seconds"
                        )
                        or 0.0
                    ),
                    3,
                )
            except Exception:
                continue

            bbox = (
                hit.get(
                    "bbox"
                )
                or {}
            )

            if not bbox:
                continue

            score = (
                float(
                    hit.get(
                        "similarity"
                    )
                    or 0.0
                ),
                float(
                    hit.get(
                        "ocr_confidence"
                    )
                    or 0.0
                ),
            )

            previous = (
                best_by_time.get(
                    t
                )
            )

            candidate = {
                "time_seconds": t,
                "bbox": {
                    "x": int(
                        bbox.get(
                            "x"
                        )
                        or 0
                    ),
                    "y": int(
                        bbox.get(
                            "y"
                        )
                        or 0
                    ),
                    "width": max(
                        1,
                        int(
                            bbox.get(
                                "width"
                            )
                            or 1
                        ),
                    ),
                    "height": max(
                        1,
                        int(
                            bbox.get(
                                "height"
                            )
                            or 1
                        ),
                    ),
                },
                "similarity": (
                    score[
                        0
                    ]
                ),
                "ocr_confidence": (
                    score[
                        1
                    ]
                ),
                "exact": bool(
                    hit.get(
                        "exact"
                    )
                ),
                "target": (
                    hit.get(
                        "target"
                    )
                ),
            }

            if (
                previous is None
                or score
                > previous[
                    0
                ]
            ):
                best_by_time[
                    t
                ] = (
                    score,
                    candidate,
                )

        points = [
            pair[
                1
            ]
            for _, pair in sorted(
                best_by_time.items(),
                key=lambda item: (
                    item[
                        0
                    ]
                ),
            )
        ]

        if not points:
            continue

        stable_bbox = (
            cluster.get(
                "stable_bbox"
            )
            or {}
        )

        if stable_bbox:
            center_x, center_y = (
                _bbox_center(
                    stable_bbox
                )
            )
        else:
            center_x, center_y = (
                _bbox_center(
                    points[
                        0
                    ][
                        "bbox"
                    ]
                )
            )

        unique_times = int(
            cluster.get(
                "unique_time_count"
            )
            or len(
                points
            )
        )

        max_spread = float(
            cluster.get(
                "max_center_spread_px"
            )
            or 0.0
        )

        # Persistent canonical top branding is already replaced by the top
        # icon + product-name composition. Do not paint a second own-brand mark
        # over it.
        persistent_canonical_top = (
            classification
            == "fixed_candidate"
            and height > 0
            and center_y
            <= 0.18
            * float(
                height
            )
            and unique_times >= 5
            and max_spread <= 70.0
        )

        if persistent_canonical_top:
            continue

        # Large/central branding that appears only in the final seconds is
        # likely the end card. That is handled by the end-card replacement
        # path, not by a dynamic watermark plate.
        end_card_like = False

        if (
            width > 0
            and height > 0
            and duration > 0
            and stable_bbox
        ):
            area_ratio = (
                float(
                    stable_bbox.get(
                        "width"
                    )
                    or 0
                )
                * float(
                    stable_bbox.get(
                        "height"
                    )
                    or 0
                )
                / max(
                    1.0,
                    float(
                        width
                        * height
                    ),
                )
            )

            tmin = float(
                cluster.get(
                    "time_min_seconds"
                )
                or 0.0
            )

            tmax = float(
                cluster.get(
                    "time_max_seconds"
                )
                or 0.0
            )

            centralish = (
                0.12
                * width
                <= center_x
                <= 0.88
                * width
                and 0.20
                * height
                <= center_y
                <= 0.86
                * height
            )

            end_card_like = (
                tmax
                >= duration
                - 1.5
                and tmin
                >= max(
                    0.0,
                    duration
                    - 8.0,
                )
                and area_ratio
                >= 0.015
                and centralish
            )

        if end_card_like:
            continue

        source = None
        hold_seconds = (
            base_hold_seconds
        )

        # A broad central/low-end terminal logo belongs to the end-card trim
        # path, even when sparse OCR gives it a moving classification.  It is
        # not a dynamic in-story watermark and must not receive an own-brand
        # follow-cover before the end card is replaced.
        terminal_card_track = False
        if width > 0 and height > 0 and duration > 0 and stable_bbox:
            stable_center_x, stable_center_y = _bbox_center(stable_bbox)
            stable_area_ratio = (
                float(stable_bbox.get("width") or 0)
                * float(stable_bbox.get("height") or 0)
                / max(1.0, float(width * height))
            )
            terminal_card_track = bool(
                float(cluster.get("time_max_seconds") or 0.0)
                >= duration - 2.5
                and float(cluster.get("time_min_seconds") or 0.0)
                >= duration - 10.0
                and stable_area_ratio >= 0.012
                and 0.12 * width <= stable_center_x <= 0.88 * width
                and 0.20 * height <= stable_center_y <= 0.90 * height
            )

        if terminal_card_track:
            continue

        if classification == "moving_or_transient_candidate":
            # A one-off OCR match can be title/subtitle text rather than a
            # watermark.  It used to produce an opaque own-brand plate for
            # roughly two seconds, then the fixed bottom banner was applied as
            # well; this is the source of the observed double-logo effect.
            # Production only follows a temporal track with two independent
            # observations.  A real dynamic watermark remains covered, while
            # an ambiguous singleton is left for the review route instead of
            # being force-rebranded.
            if len(points) < 2:
                continue

            source = "moving_or_transient_multi_hit"
            hold_seconds = max(
                base_hold_seconds,
                min(1.0, effective_interval * 0.72),
            )

        else:
            # A moving watermark can pause at one location for several sampled
            # frames and be spatially labelled fixed. Outside the persistent
            # canonical top slot, repeated competitor-brand OCR is safe to
            # route through the compact cover path.
            if len(
                points
            ) < 2:
                continue

            source = (
                "fixed_non_top_brand_recovery"
            )

            hold_seconds = max(
                base_hold_seconds,
                min(
                    1.20,
                    effective_interval
                    * 0.82,
                ),
            )

        tracks.append(
            {
                "cluster_id": (
                    cluster.get(
                        "cluster_id"
                    )
                ),
                "classification": (
                    classification
                ),
                "recovery_source": (
                    source
                ),
                "target": (
                    points[
                        0
                    ].get(
                        "target"
                    )
                ),
                "point_count": len(
                    points
                ),
                "hold_seconds": round(
                    float(
                        hold_seconds
                    ),
                    3,
                ),
                "points": points,
            }
        )

    return tracks




def _operator_temporal_tracks_from_census(census_report_relative_path):
    """Convert the strict census once for the temporal frame-mask worker.

    This is deliberately separate from the legacy moving-cover structure:
    strict census points are pixel boxes whereas ProPainter consumes normalized
    waypoints.  Keeping the conversion at the handoff prevents the renderer
    from silently launching a second, inconsistent detector pass.
    """
    if not census_report_relative_path:
        return []
    try:
        _, report = _read_json_workspace(
            census_report_relative_path, "operator_temporal_census_tracks"
        )
    except Exception:
        return []
    video = report.get("video") or {}
    try:
        width, height = int(video.get("width") or 0), int(video.get("height") or 0)
    except (TypeError, ValueError):
        return []
    if width <= 0 or height <= 0:
        return []
    converted = []
    for index, track in enumerate(_operator_dynamic_brand_tracks_from_census(census_report_relative_path), 1):
        waypoints = []
        for point in track.get("points") or []:
            bbox = point.get("bbox") or {}
            try:
                x0 = max(0.0, min(1.0, float(bbox.get("x")) / width))
                y0 = max(0.0, min(1.0, float(bbox.get("y")) / height))
                x1 = max(x0, min(1.0, (float(bbox.get("x")) + float(bbox.get("width"))) / width))
                y1 = max(y0, min(1.0, (float(bbox.get("y")) + float(bbox.get("height"))) / height))
                waypoint = {
                    "t": round(float(point.get("time_seconds")), 3),
                    "bbox": [x0, y0, x1, y1],
                    "confidence": float(point.get("similarity") or point.get("template_score") or 0.0),
                }
            except (TypeError, ValueError):
                continue
            if x1 > x0 and y1 > y0:
                waypoints.append(waypoint)
        waypoints.sort(key=lambda value: value["t"])
        if len(waypoints) < 2:
            continue
        converted.append({
            "track_id": str(track.get("cluster_id") or f"census-{index:02d}"),
            "visibility_window": [waypoints[0]["t"], waypoints[-1]["t"]],
            "max_interpolation_gap_seconds": float(track.get("max_interpolation_gap_seconds") or 0.32),
            "waypoints": waypoints,
            "point_count": len(waypoints),
            "movement_px": track.get("movement_px"),
            "identity_evidence": track.get("identity_evidence") or "authoritative_census",
        })
    return converted


def _operator_interpolated_dynamic_bbox(
    track,
    t,
    width,
    height,
    max_gap_seconds,
):
    points = (
        track.get(
            "points"
        )
        or []
    )

    if not points:
        return None

    now = float(
        t
    )

    strict_track = str(track.get("tracking_policy") or "").startswith("verified_identity") or str(
        track.get("tracking_policy") or ""
    ).startswith("reviewed_template_identity")
    effective_max_gap = max(
        0.10,
        min(
            10.0,
            float(
                track.get("max_interpolation_gap_seconds")
                or max_gap_seconds
            ),
        ),
    )

    hold_seconds = max(
        0.20,
        float(
            track.get(
                "hold_seconds"
            )
            or 0.55
        ),
    )

    first_t = float(
        points[
            0
        ][
            "time_seconds"
        ]
    )

    last_t = float(
        points[
            -1
        ][
            "time_seconds"
        ]
    )

    # Strong short-lived watermark: one trustworthy census hit should cover a
    # short temporal window instead of being discarded entirely.
    if len(points) == 1:
        if strict_track:
            return None
        if abs(
            now
            - first_t
        ) <= hold_seconds:
            return _clip_bbox(
                points[
                    0
                ][
                    "bbox"
                ],
                int(
                    width
                ),
                int(
                    height
                ),
            )

        return None

    guard = max(
        hold_seconds,
        min(
            0.95,
            max(
                0.20,
                float(
                    max_gap_seconds
                )
                * 0.35,
            ),
        ),
    )

    if strict_track and (now < first_t - 1e-6 or now > last_t + 1e-6):
        return None

    if now < first_t - guard:
        return None

    if now > last_t + guard:
        return None

    if now <= first_t:
        return _clip_bbox(
            points[
                0
            ][
                "bbox"
            ],
            int(
                width
            ),
            int(
                height
            ),
        )

    if now >= last_t:
        return _clip_bbox(
            points[
                -1
            ][
                "bbox"
            ],
            int(
                width
            ),
            int(
                height
            ),
        )

    left = None
    right = None

    for index in range(
        1,
        len(
            points
        ),
    ):
        candidate = (
            points[
                index
            ]
        )

        if float(
            candidate[
                "time_seconds"
            ]
        ) >= now:
            left = (
                points[
                    index
                    - 1
                ]
            )

            right = (
                candidate
            )

            break

    if (
        left is None
        or right is None
    ):
        return None

    lt = float(
        left[
            "time_seconds"
        ]
    )

    rt = float(
        right[
            "time_seconds"
        ]
    )

    gap = (
        rt
        - lt
    )

    if gap <= 1e-6:
        return _clip_bbox(
            left[
                "bbox"
            ],
            int(
                width
            ),
            int(
                height
            ),
        )

    if gap > effective_max_gap:
        if strict_track:
            return None
        # Do not interpolate across a long teleport / missing interval. But do
        # retain a short hold around either trustworthy observed location.
        left_distance = abs(
            now
            - lt
        )

        right_distance = abs(
            rt
            - now
        )

        if min(
            left_distance,
            right_distance,
        ) <= hold_seconds:
            point = (
                left
                if left_distance
                <= right_distance
                else right
            )

            return _clip_bbox(
                point[
                    "bbox"
                ],
                int(
                    width
                ),
                int(
                    height
                ),
            )

        return None

    ratio = max(
        0.0,
        min(
            1.0,
            (
                now
                - lt
            )
            / gap,
        ),
    )

    lb = (
        left[
            "bbox"
        ]
    )

    rb = (
        right[
            "bbox"
        ]
    )

    def interp(
        key,
    ):
        return int(
            round(
                float(
                    lb[
                        key
                    ]
                )
                + (
                    float(
                        rb[
                            key
                        ]
                    )
                    - float(
                        lb[
                            key
                        ]
                    )
                )
                * ratio
            )
        )

    return _clip_bbox(
        {
            "x": interp(
                "x"
            ),
            "y": interp(
                "y"
            ),
            "width": max(
                1,
                interp(
                    "width"
                ),
            ),
            "height": max(
                1,
                interp(
                    "height"
                ),
            ),
        },
        int(
            width
        ),
        int(
            height
        ),
    )




def _operator_expand_bbox_centered(
    bbox,
    width,
    height,
    ratio,
):
    b = _clip_bbox(
        bbox,
        int(
            width
        ),
        int(
            height
        ),
    )

    scale = max(
        1.0,
        float(
            ratio
        ),
    )

    cx = (
        b[
            "x"
        ]
        + b[
            "width"
        ]
        / 2.0
    )

    cy = (
        b[
            "y"
        ]
        + b[
            "height"
        ]
        / 2.0
    )

    nw = max(
        1,
        int(
            round(
                b[
                    "width"
                ]
                * scale
            )
        ),
    )

    nh = max(
        1,
        int(
            round(
                b[
                    "height"
                ]
                * scale
            )
        ),
    )

    return _clip_bbox(
        {
            "x": int(
                round(
                    cx
                    - nw
                    / 2.0
                )
            ),
            "y": int(
                round(
                    cy
                    - nh
                    / 2.0
                )
            ),
            "width": nw,
            "height": nh,
        },
        int(
            width
        ),
        int(
            height
        ),
    )


def _operator_dynamic_wordmark_stroke_mask(frame, bbox):
    """Return a compact glyph mask for a tracked dynamic wordmark.

    Dynamic tracks are OCR/template observations, so their boxes are useful for
    following the mark but must never be treated as a full-frame removal mask.
    This selects only strong local contrast/edge strokes within a lightly
    padded local ROI; a low-coverage or ambiguous result is intentionally
    returned as ``None`` so the renderer can use an opaque replacement plate
    rather than destroy the story beneath a translucent watermark.
    """
    height, width = frame.shape[:2]
    b = _clip_bbox(bbox, width, height)
    x0, y0 = int(b["x"]), int(b["y"])
    x1 = min(width, x0 + int(b["width"]))
    y1 = min(height, y0 + int(b["height"]))
    if x1 - x0 < 8 or y1 - y0 < 6:
        return None

    pad = max(2, int(round(min(x1 - x0, y1 - y0) * 0.08)))
    rx0, ry0 = max(0, x0 - pad), max(0, y0 - pad)
    rx1, ry1 = min(width, x1 + pad), min(height, y1 + pad)
    roi = frame[ry0:ry1, rx0:rx1]
    if roi.size == 0:
        return None

    gray = cv2.cvtColor(roi, cv2.COLOR_BGR2GRAY)
    blur = cv2.GaussianBlur(gray, (0, 0), 3.0)
    contrast = cv2.absdiff(gray, blur)
    edges = cv2.Canny(gray, 48, 132)
    # Use robust local thresholds; the watermark can be either a pale or a
    # dark translucent imprint depending on the background underneath it.
    contrast_floor = max(10, int(round(float(np.percentile(contrast, 82)))))
    contrast_mask = np.where(contrast >= contrast_floor, 255, 0).astype(np.uint8)
    mask = cv2.bitwise_or(contrast_mask, edges)
    mask = cv2.morphologyEx(
        mask,
        cv2.MORPH_OPEN,
        cv2.getStructuringElement(cv2.MORPH_RECT, (2, 2)),
    )
    mask = cv2.dilate(
        mask,
        cv2.getStructuringElement(cv2.MORPH_RECT, (2, 2)),
        iterations=1,
    )

    # Do not let the padding turn background edges into a removal region.
    inner = np.zeros_like(mask)
    inner[y0 - ry0:y1 - ry0, x0 - rx0:x1 - rx0] = 255
    mask = cv2.bitwise_and(mask, inner)
    coverage = float(np.count_nonzero(mask)) / max(1.0, float((x1 - x0) * (y1 - y0)))
    if coverage < 0.012 or coverage > 0.42:
        return None

    full_mask = np.zeros((height, width), dtype=np.uint8)
    full_mask[ry0:ry1, rx0:rx1] = mask
    return {
        "mask": full_mask,
        "coverage_ratio": round(coverage, 4),
        "bbox": b,
    }


def _operator_apply_feathered_local_blur(frame, bbox, sigma):
    """Blur a bounded watermark region without adding a replacement layer."""
    out = frame.copy()
    height, width = out.shape[:2]
    b = _clip_bbox(bbox, width, height)
    x0, y0 = int(b["x"]), int(b["y"])
    x1 = min(width, x0 + int(b["width"]))
    y1 = min(height, y0 + int(b["height"]))
    roi_width, roi_height = x1 - x0, y1 - y0
    if roi_width < 2 or roi_height < 2:
        return out

    roi = out[y0:y1, x0:x1]
    blurred = cv2.GaussianBlur(roi, (0, 0), max(0.8, min(32.0, float(sigma))))
    feather = min(
        max(1, int(round(min(roi_width, roi_height) * 0.12))),
        max(1, min(roi_width, roi_height) // 3),
    )
    alpha_seed = np.zeros((roi_height, roi_width), dtype=np.uint8)
    if roi_width <= feather * 2 or roi_height <= feather * 2:
        alpha_seed[:, :] = 255
    else:
        alpha_seed[feather:roi_height - feather, feather:roi_width - feather] = 255
    alpha = cv2.GaussianBlur(alpha_seed, (0, 0), max(0.8, feather * 0.55)).astype(np.float32) / 255.0
    out[y0:y1, x0:x1] = np.clip(
        roi.astype(np.float32) * (1.0 - alpha[..., None])
        + blurred.astype(np.float32) * alpha[..., None],
        0,
        255,
    ).astype(np.uint8)
    return out


def _operator_apply_dynamic_wordmark_blur(frame, bbox, sigma):
    """Blur only the detected watermark strokes, never the entire tracking box.

    Dynamic template boxes are intentionally generous so a faint alpha wordmark
    can be followed through motion.  Treating that geometry as a full blur ROI
    softens the actor or scene beneath it.  Build a local glyph mask first and
    blend an already-blurred ROI only through that mask; ambiguous masks fall
    back to a smaller centred blur rather than a broad face-sized rectangle.
    """
    out = frame.copy()
    height, width = out.shape[:2]
    b = _clip_bbox(bbox, width, height)
    x0, y0 = int(b["x"]), int(b["y"])
    x1 = min(width, x0 + int(b["width"]))
    y1 = min(height, y0 + int(b["height"]))
    if x1 - x0 < 2 or y1 - y0 < 2:
        return out, {"mask_used": False, "fallback": "too_small"}

    # Use the reviewed wordmark reference as the glyph support whenever it is
    # available. Scene-derived edge/contrast masks are unsafe: on a face they
    # happily select eyes, mouths and hair inside a broad tracking rectangle.
    template_path = WORKSPACE / "config" / "dynamic_watermark_reference_reelshort_v2.png"
    template = cv2.imread(str(template_path), cv2.IMREAD_GRAYSCALE) if template_path.exists() else None
    if template is not None and template.size > 0:
        template_smooth = cv2.GaussianBlur(template, (0, 0), 7.0)
        template_glyph = np.where(
            cv2.absdiff(template, template_smooth) >= 15,
            255,
            0,
        ).astype(np.uint8)
        template_glyph = cv2.morphologyEx(
            template_glyph,
            cv2.MORPH_CLOSE,
            cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (3, 3)),
            iterations=1,
        )
        local_mask = cv2.resize(
            template_glyph,
            (x1 - x0, y1 - y0),
            interpolation=cv2.INTER_LINEAR,
        )
        coverage = float(np.count_nonzero(local_mask)) / max(1.0, float(local_mask.size))
        if 0.006 <= coverage <= 0.55:
            stroke = {"mask": local_mask, "coverage_ratio": coverage, "source": "reviewed_template"}
        else:
            stroke = None
    else:
        stroke = None

    # Fallback candidate extraction stays inside the exact detected wordmark
    # bounds. The generic helper has an intentional padded ROI for its legacy
    # callers; that padding is unsafe here because nearby face/scene detail can
    # be mistaken for a watermark stroke.
    roi = out[y0:y1, x0:x1]
    if stroke is None:
        gray = cv2.cvtColor(roi, cv2.COLOR_BGR2GRAY)
        local_smooth = cv2.GaussianBlur(gray, (0, 0), 2.2)
        local_contrast = cv2.absdiff(gray, local_smooth)
        contrast_floor = max(14, int(round(float(np.percentile(local_contrast, 94)))))
        local_mask = np.where(local_contrast >= contrast_floor, 255, 0).astype(np.uint8)
        local_mask = cv2.morphologyEx(
            local_mask,
            cv2.MORPH_OPEN,
            cv2.getStructuringElement(cv2.MORPH_RECT, (2, 2)),
        )
        coverage = float(np.count_nonzero(local_mask)) / max(1.0, float(local_mask.size))
        if 0.006 <= coverage <= 0.14:
            stroke = {"mask": local_mask, "coverage_ratio": coverage, "source": "local_contrast"}
    if stroke is None:
        # Detection geometry may contain a face or other high-detail story
        # pixels.  A conservative core is a safer fallback than blurring the
        # whole track region when a glyph mask cannot be distinguished.
        core_w = max(2, int(round((x1 - x0) * 0.56)))
        core_h = max(2, int(round((y1 - y0) * 0.40)))
        core = {
            "x": int(round((x0 + x1 - core_w) / 2.0)),
            "y": int(round((y0 + y1 - core_h) / 2.0)),
            "width": core_w,
            "height": core_h,
        }
        return (
            _operator_apply_feathered_local_blur(out, core, min(3.0, float(sigma))),
            {"mask_used": False, "fallback": "conservative_core", "bbox": core},
        )

    blurred = cv2.GaussianBlur(roi, (0, 0), max(0.8, min(32.0, float(sigma))))
    # The feather stays local to actual detected glyph contrast rather than
    # the broad tracked bbox; avoid dilation because it can grow into a face.
    alpha = cv2.GaussianBlur(local_mask, (0, 0), 1.1).astype(np.float32) / 255.0
    out[y0:y1, x0:x1] = np.clip(
        roi.astype(np.float32) * (1.0 - alpha[..., None])
        + blurred.astype(np.float32) * alpha[..., None],
        0,
        255,
    ).astype(np.uint8)
    return out, {
        "mask_used": True,
        "coverage_ratio": float(stroke.get("coverage_ratio") or 0.0),
        "mask_source": stroke.get("source"),
        "bbox": b,
    }


def _operator_apply_dynamic_brand_cover(
    frame,
    t,
    tracks,
    profile,
    width,
    height,
    req,
):
    if not tracks:
        return frame, []
    out = (
        frame.copy()
    )

    applied = []
    # Preserve the physical blur and its receipt identity together. Several
    # verified OCR/template tracks can describe one visible mark on a frame;
    # those tracks need an auditable shared-treatment receipt without applying
    # the blur repeatedly.
    applied_regions = []

    for track in (
        tracks
        or []
    ):
        bbox = (
            _operator_interpolated_dynamic_bbox(
                track,
                t,
                width,
                height,
                float(
                    getattr(
                        req,
                        "dynamic_brand_cover_max_gap_seconds",
                        2.5,
                    )
                ),
            )
        )

        if not bbox:
            continue

        cover = (
            _operator_expand_bbox_centered(
                bbox,
                width,
                height,
                float(
                    getattr(
                        req,
                        "dynamic_brand_cover_expand_ratio",
                        1.08,
                    )
                ),
            )
        )

        # OCR variants and adjacent tracks may describe the same watermark.
        # Apply one blur per physical region so overlaps do not over-soften it.
        shared_cover = next(
            (
                prior
                for prior in applied_regions
                if _bbox_iou(cover, prior["bbox"]) >= 0.55
            ),
            None,
        )
        if shared_cover is not None:
            applied.append(
                {
                    "cluster_id": track.get("cluster_id"),
                    "receipt_key": track.get("_operator_dynamic_receipt_key"),
                    "bbox": shared_cover["bbox"],
                    "treatment": "satisfied_by_shared_dynamic_blur",
                    "shared_blur_receipt_key": shared_cover["receipt_key"],
                    "own_brand_overlay": False,
                }
            )
            continue

        # Detection boxes are tracking geometry, not blur masks. Only the
        # recovered wordmark strokes are softened, so a broad OCR/template
        # box cannot blur a face or the surrounding story frame. A stronger
        # blur is safe because it stays inside the reviewed glyph mask.
        out, blur_detail = _operator_apply_dynamic_wordmark_blur(
            out,
            cover,
            max(12.0, float(getattr(req, "dynamic_watermark_blur_sigma", 5.0))),
        )

        applied_regions.append(
            {
                "bbox": cover,
                "receipt_key": track.get("_operator_dynamic_receipt_key"),
            }
        )

        applied.append(
            {
                "cluster_id": (
                    track.get(
                        "cluster_id"
                    )
                ),
                # Receipt keys are stable even when a historical track did not
                # include a public cluster_id. The renderer uses them to prove
                # every detected dynamic action reached the frame loop.
                "receipt_key": track.get("_operator_dynamic_receipt_key"),
                "bbox": cover,
                "treatment": "feathered_gaussian_blur",
                "blur_sigma": max(12.0, float(getattr(req, "dynamic_watermark_blur_sigma", 5.0))),
                "mask_used": bool(blur_detail.get("mask_used")),
                "fallback": blur_detail.get("fallback"),
                "own_brand_overlay": False,
            }
        )

    return (
        out,
        applied,
    )


def _faint_watermark_anchor_tracks_from_visual_report(
    report_relative_path,
    min_score,
):
    """Turn reviewer-confirmed local template segments into compact tracks."""
    if not report_relative_path:
        return []
    try:
        _, report = _read_json_workspace(
            report_relative_path,
            "faint_watermark_anchor_tracks",
        )
    except Exception:
        return []

    local = report.get("anchor_local_track") or {}
    tracks = []
    for index, segment in enumerate(local.get("segments") or [], 1):
        points = [
            {
                "time_seconds": float(point["time_seconds"]),
                "bbox": dict(point["bbox"]),
            }
            for point in segment.get("points") or []
            if float(point.get("score") or 0.0) >= float(min_score)
            and point.get("bbox")
        ]
        if len(points) < 2:
            continue
        tracks.append(
            {
                "cluster_id": f"faint-reference-{index}",
                "classification": "reviewer_anchor_faint_watermark",
                "recovery_source": "reviewer_anchor_faint_watermark_track",
                "target": "faint_reelshort_watermark",
                "point_count": len(points),
                "hold_seconds": 0.12,
                "points": points,
                "mean_score": segment.get("mean_score"),
                "max_score": segment.get("max_score"),
            }
        )
    return tracks


def _render_visual_base_full(
    video_path,
    out_path,
    top_actions,
    profile,
    meta,
    req,
):
    width = int(meta["width"])
    height = int(meta["height"])
    fps = float(meta["fps"])
    duration = float(meta["duration_seconds"])

    writer, runtime = _open_x264_raw_writer(
        out_path,
        width,
        height,
        fps,
        int(req.crf),
        str(req.preset),
    )

    cap = cv2.VideoCapture(
        str(video_path)
    )

    if not cap.isOpened():
        raise HTTPException(
            status_code=422,
            detail="Could not open source video.",
        )

    frames_written = 0
    top_composed_frames = 0
    write_error = None

    # The canonical top brand is static for the whole story. Prepare its
    # geometry once before the frame loop; per-frame quantile and asset work is
    # pure repetition and was a material contributor to render latency.
    prepared_top_actions = list(top_actions or [])
    for action in prepared_top_actions:
        try:
            action.setdefault(
                "_operator_canonical_text_slot",
                _canonical_top_text_slot(action, width, height, req),
            )
        except Exception:
            pass

    try:
        while True:
            ok, frame = cap.read()

            if not ok or frame is None:
                break

            t = (
                frames_written
                / float(
                    max(
                        1e-6,
                        fps,
                    )
                )
            )

            if top_actions and bool(
                req.compose_top_brand_layers
            ):
                frame, applied = _apply_top_brand_composition_render(
                    frame,
                    t,
                    top_actions,
                    profile,
                    width,
                    height,
                    duration,
                    req,
                )

                if applied:
                    top_composed_frames += 1

            try:
                writer.stdin.write(
                    frame.tobytes()
                )
            except Exception as exc:
                write_error = str(exc)[:500]
                break

            frames_written += 1

    finally:
        cap.release()

        try:
            writer.stdin.close()
        except Exception:
            pass

    stderr = b""

    try:
        stderr = (
            writer.stderr.read()
            if writer.stderr
            else b""
        )
    except Exception:
        pass

    code = writer.wait()

    if (
        code != 0
        or write_error is not None
        or not out_path.exists()
    ):
        raise HTTPException(
            status_code=500,
            detail={
                "stage": "replacement_render_visual_base",
                "error": (
                    write_error
                    or stderr.decode(
                        "utf-8",
                        errors="replace",
                    )[:1000]
                    or f"ffmpeg exited {code}"
                ),
            },
        )

    return {
        "relative_path": out_path.relative_to(
            WORKSPACE
        ).as_posix(),
        "frames_written": frames_written,
        "top_composed_frames": top_composed_frames,
        "encoder": {
            "engine": "ffmpeg",
            "codec": "libx264",
            "crf": int(req.crf),
            "preset": str(req.preset),
            "runtime": runtime,
        },
    }


def _operator_ffmpeg_timeout_seconds():
    try:
        value = int(
            os.getenv(
                "OPERATOR_FFMPEG_TIMEOUT_SECONDS",
                "1200",
            )
        )
    except Exception:
        value = 1200

    return max(
        120,
        min(
            7200,
            value,
        ),
    )


def _run_ffmpeg_checked(
    command,
    stage,
):
    timeout_seconds = _operator_ffmpeg_timeout_seconds()
    started = time.monotonic()

    try:
        p = subprocess.Popen(
            command,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
        )
    except Exception as exc:
        raise HTTPException(
            status_code=500,
            detail={
                "stage": stage,
                "error": "ffmpeg_start_failed",
                "message": str(exc)[:1000],
                "command": command[:20],
            },
        ) from exc

    try:
        while True:
            _operator_raise_if_cancelled()

            returncode = p.poll()
            if returncode is not None:
                break

            if time.monotonic() - started > timeout_seconds:
                try:
                    p.kill()
                except Exception:
                    pass

                try:
                    p.communicate(timeout=5)
                except Exception:
                    pass

                raise HTTPException(
                    status_code=504,
                    detail={
                        "stage": stage,
                        "error": "ffmpeg_timeout",
                        "timeout_seconds": timeout_seconds,
                        "message": (
                            "FFmpeg exceeded the configured render timeout and "
                            "was stopped instead of leaving the Operator task hanging."
                        ),
                        "command": command[:20],
                    },
                )

            time.sleep(0.35)

        stdout, stderr = p.communicate()

    except _OperatorTaskCancelled:
        try:
            p.terminate()
            p.wait(timeout=3)
        except Exception:
            try:
                p.kill()
            except Exception:
                pass
        raise

    if p.returncode != 0:
        raise HTTPException(
            status_code=500,
            detail={
                "stage": stage,
                "error": (
                    stderr[-3000:]
                    if stderr
                    else f"ffmpeg exited {p.returncode}"
                ),
                "command": command[:20],
            },
        )

    class _FFmpegResult:
        pass

    result = _FFmpegResult()
    result.returncode = p.returncode
    result.stdout = stdout
    result.stderr = stderr
    return result


def _source_segment_clip(
    visual_base,
    source_video,
    out_path,
    start,
    end,
    meta,
    source_has_audio,
    req,
):
    duration = max(
        0.0,
        float(end) - float(start),
    )

    if duration <= 0.001:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "replacement_render",
                "error": "invalid_source_segment",
                "start_seconds": start,
                "end_seconds": end,
            },
        )

    ffmpeg = shutil.which("ffmpeg")

    width = int(meta["width"])
    height = int(meta["height"])
    fps = float(meta["fps"])

    cmd = [
        ffmpeg,
        "-y",
        "-ss",
        f"{float(start):.6f}",
        "-t",
        f"{duration:.6f}",
        "-i",
        str(visual_base),
    ]

    if source_has_audio:
        cmd += [
            "-ss",
            f"{float(start):.6f}",
            "-t",
            f"{duration:.6f}",
            "-i",
            str(source_video),
        ]

        audio_input = "[1:a:0]"
    else:
        cmd += [
            "-f",
            "lavfi",
            "-t",
            f"{duration:.6f}",
            "-i",
            (
                "anullsrc=r="
                f"{int(req.audio_sample_rate)}"
                ":cl=stereo"
            ),
        ]

        audio_input = "[1:a:0]"

    filter_complex = (
        f"[0:v:0]"
        f"scale={width}:{height}:flags=lanczos,"
        f"fps={fps:.6f},"
        "setsar=1,"
        "format=yuv420p,"
        "setpts=PTS-STARTPTS[v];"
        f"{audio_input}"
        f"aresample={int(req.audio_sample_rate)},"
        "aformat=channel_layouts=stereo,"
        "asetpts=PTS-STARTPTS[a]"
    )

    cmd += [
        "-filter_complex",
        filter_complex,
        "-map",
        "[v]",
        "-map",
        "[a]",
        "-t",
        f"{duration:.6f}",
        "-c:v",
        "libx264",
        "-crf",
        str(int(req.crf)),
        "-preset",
        str(req.preset),
        "-pix_fmt",
        "yuv420p",
        "-c:a",
        "aac",
        "-b:a",
        str(req.audio_bitrate),
        "-ar",
        str(int(req.audio_sample_rate)),
        "-ac",
        str(int(req.audio_channels)),
        "-movflags",
        "+faststart",
        str(out_path),
    ]

    _run_ffmpeg_checked(
        cmd,
        "replacement_render_source_segment",
    )

    return {
        "path": out_path,
        "duration_seconds": duration,
        "kind": "source",
        "source_start_seconds": float(start),
        "source_end_seconds": float(end),
        "audio_source": (
            "source"
            if source_has_audio
            else "generated_silence"
        ),
    }


def _save_placeholder_card(
    out_path,
    width,
    height,
    profile,
    subtitle,
    top_action=None,
    top_brand_mode="auto",
):
    assets = profile.get("assets") or {}

    logo = _load_bgr_asset(
        assets.get("logo_image_relative_path")
        or assets.get("icon_image_relative_path")
    )

    card = _generated_brand_card(
        width,
        height,
        profile.get("product_name") or "",
        profile.get("brand_name") or "",
        logo_image=logo,
        subtitle=subtitle,
    )

    if top_action and top_action.get("bbox"):
        card = _draw_clean_brand_mark_mode(
            card,
            top_action["bbox"],
            profile,
            top_action.get("placement"),
            top_brand_mode,
        )

    if not cv2.imwrite(
        str(out_path),
        card,
    ):
        raise HTTPException(
            status_code=500,
            detail={
                "stage": "replacement_render",
                "error": "could_not_write_placeholder_card",
                "path": str(out_path),
            },
        )

    return out_path


def _normalize_replacement_clip(
    out_path,
    media_kind,
    asset_path,
    placeholder_image,
    fallback_duration,
    meta,
    req,
):
    ffmpeg = shutil.which("ffmpeg")
    width = int(meta["width"])
    height = int(meta["height"])
    fps = float(meta["fps"])

    media_info = (
        _probe_media(asset_path)
        if asset_path
        else {}
    )

    if media_kind == "video":
        duration = float(
            media_info.get("duration_seconds")
            or fallback_duration
        )

        has_audio = bool(
            media_info.get("has_audio")
        )

        cmd = [
            ffmpeg,
            "-y",
            "-i",
            str(asset_path),
        ]

        if not has_audio:
            cmd += [
                "-f",
                "lavfi",
                "-t",
                f"{duration:.6f}",
                "-i",
                (
                    "anullsrc=r="
                    f"{int(req.audio_sample_rate)}"
                    ":cl=stereo"
                ),
            ]

        audio_input = (
            "[0:a:0]"
            if has_audio
            else "[1:a:0]"
        )

        filter_complex = (
            f"[0:v:0]"
            f"scale={width}:{height}:"
            "force_original_aspect_ratio=increase,"
            f"crop={width}:{height},"
            f"fps={fps:.6f},"
            "setsar=1,"
            "format=yuv420p,"
            "setpts=PTS-STARTPTS[v];"
            f"{audio_input}"
            f"aresample={int(req.audio_sample_rate)},"
            "aformat=channel_layouts=stereo,"
            "asetpts=PTS-STARTPTS[a]"
        )

        cmd += [
            "-filter_complex",
            filter_complex,
            "-map",
            "[v]",
            "-map",
            "[a]",
            "-t",
            f"{duration:.6f}",
            "-c:v",
            "libx264",
            "-crf",
            str(int(req.crf)),
            "-preset",
            str(req.preset),
            "-pix_fmt",
            "yuv420p",
            "-c:a",
            "aac",
            "-b:a",
            str(req.audio_bitrate),
            "-ar",
            str(int(req.audio_sample_rate)),
            "-ac",
            str(int(req.audio_channels)),
            "-movflags",
            "+faststart",
            str(out_path),
        ]

        _run_ffmpeg_checked(
            cmd,
            "replacement_render_normalize_video_asset",
        )

        return {
            "path": out_path,
            "duration_seconds": duration,
            "kind": "replacement_video",
            "asset_path": str(asset_path),
            "audio_source": (
                "replacement_asset"
                if has_audio
                else "generated_silence"
            ),
        }

    # Image or generated placeholder.
    duration = max(
        0.25,
        float(fallback_duration),
    )

    image_path = (
        asset_path
        if media_kind == "image"
        else placeholder_image
    )

    cmd = [
        ffmpeg,
        "-y",
        "-loop",
        "1",
        "-t",
        f"{duration:.6f}",
        "-i",
        str(image_path),
        "-f",
        "lavfi",
        "-t",
        f"{duration:.6f}",
        "-i",
        (
            "anullsrc=r="
            f"{int(req.audio_sample_rate)}"
            ":cl=stereo"
        ),
        "-filter_complex",
        (
            f"[0:v:0]"
            f"scale={width}:{height}:"
            "force_original_aspect_ratio=increase,"
            f"crop={width}:{height},"
            f"fps={fps:.6f},"
            "setsar=1,"
            "format=yuv420p,"
            "setpts=PTS-STARTPTS[v];"
            f"[1:a:0]"
            f"aresample={int(req.audio_sample_rate)},"
            "aformat=channel_layouts=stereo,"
            "asetpts=PTS-STARTPTS[a]"
        ),
        "-map",
        "[v]",
        "-map",
        "[a]",
        "-t",
        f"{duration:.6f}",
        "-c:v",
        "libx264",
        "-crf",
        str(int(req.crf)),
        "-preset",
        str(req.preset),
        "-pix_fmt",
        "yuv420p",
        "-c:a",
        "aac",
        "-b:a",
        str(req.audio_bitrate),
        "-ar",
        str(int(req.audio_sample_rate)),
        "-ac",
        str(int(req.audio_channels)),
        "-movflags",
        "+faststart",
        str(out_path),
    ]

    _run_ffmpeg_checked(
        cmd,
        "replacement_render_normalize_image_or_placeholder",
    )

    return {
        "path": out_path,
        "duration_seconds": duration,
        "kind": (
            "replacement_image"
            if media_kind == "image"
            else "replacement_placeholder"
        ),
        "asset_path": (
            str(asset_path)
            if asset_path
            else None
        ),
        "audio_source": "generated_silence",
    }


def _concat_normalized_clips(
    clips,
    out_path,
):
    concat_file = out_path.with_suffix(
        ".concat.txt"
    )

    lines = []

    for clip in clips:
        escaped = str(
            Path(clip["path"]).resolve()
        ).replace(
            "'",
            "'\\''",
        )

        lines.append(
            f"file '{escaped}'"
        )

    concat_file.write_text(
        "\n".join(lines) + "\n",
        encoding="utf-8",
    )

    ffmpeg = shutil.which("ffmpeg")

    # All clips were normalized to the same H.264/AAC parameters.
    cmd = [
        ffmpeg,
        "-y",
        "-f",
        "concat",
        "-safe",
        "0",
        "-i",
        str(concat_file),
        "-c",
        "copy",
        "-movflags",
        "+faststart",
        str(out_path),
    ]

    p = subprocess.run(
        cmd,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
    )

    if p.returncode != 0:
        # Conservative fallback: re-encode concat if stream-copy concat
        # encounters container extradata/timestamp differences.
        cmd = [
            ffmpeg,
            "-y",
            "-f",
            "concat",
            "-safe",
            "0",
            "-i",
            str(concat_file),
            "-c:v",
            "libx264",
            "-crf",
            "15",
            "-preset",
            "slow",
            "-pix_fmt",
            "yuv420p",
            "-c:a",
            "aac",
            "-b:a",
            "160k",
            "-ar",
            "48000",
            "-ac",
            "2",
            "-movflags",
            "+faststart",
            str(out_path),
        ]

        _run_ffmpeg_checked(
            cmd,
            "replacement_render_concat_reencode",
        )

        concat_mode = "reencode_fallback"
    else:
        concat_mode = "stream_copy"

    return {
        "concat_file": concat_file,
        "mode": concat_mode,
    }


def _replacement_event_diagnostic(event):
    """Return the minimum useful evidence for a timeline conflict report."""
    action = event.get("action") or {}
    source_candidate = action.get("source_candidate") or {}

    return {
        "kind": event.get("kind"),
        "action_id": action.get("action_id"),
        "decision_source": action.get("decision_source"),
        "start_seconds": round(float(event.get("start_seconds") or 0.0), 6),
        "end_seconds": round(float(event.get("end_seconds") or 0.0), 6),
        "semantic_mid_promo_action_id": source_candidate.get(
            "semantic_mid_promo_action_id"
        ),
    }


def _resolve_replacement_timeline_overlaps(timeline_events, fps):
    """Normalize the one deliberate terminal Mid-Promo/End-Card handoff.

    An operator fallback End Card may be created from a semantic Mid Promo's
    terminal tail.  The End Card boundary detector is allowed to move its cut
    earlier to avoid a CTA flash, while Mid Promo render guards are allowed to
    expand later.  Both rules are correct in isolation, but they must never
    produce two destructive replacement intervals for the same source frames.

    We only auto-resolve an overlap when the End Card explicitly names the
    immediately preceding Mid Promo action.  The handoff is then clamped to
    the already-final *render* end of that Mid Promo.  Any other overlap is a
    genuine ambiguous edit and remains a hard failure with actionable details.
    """
    frame_epsilon = 0.5 / max(1.0, float(fps or 0.0))
    normalized = []
    resolutions = []

    for raw_event in sorted(
        timeline_events,
        key=lambda item: float(item.get("start_seconds") or 0.0),
    ):
        event = dict(raw_event)
        start = float(event.get("start_seconds") or 0.0)
        end = float(event.get("end_seconds") or 0.0)

        if end < start - frame_epsilon:
            raise HTTPException(
                status_code=422,
                detail={
                    "stage": "replacement_render",
                    "error": "replacement_interval_invalid",
                    "interval": _replacement_event_diagnostic(event),
                },
            )

        if normalized:
            previous = normalized[-1]
            previous_end = float(previous.get("end_seconds") or 0.0)

            if start < previous_end - frame_epsilon:
                previous_action = previous.get("action") or {}
                event_action = event.get("action") or {}
                source_candidate = event_action.get("source_candidate") or {}
                linked_mid_action_id = source_candidate.get(
                    "semantic_mid_promo_action_id"
                )

                safe_terminal_handoff = (
                    event.get("kind") == "end_card_replace"
                    and previous.get("kind") == "mid_promo_replace"
                    and linked_mid_action_id
                    and linked_mid_action_id == previous_action.get("action_id")
                )

                if not safe_terminal_handoff:
                    raise HTTPException(
                        status_code=422,
                        detail={
                            "stage": "replacement_render",
                            "error": "replacement_intervals_overlap",
                            "event": event.get("kind"),
                            "previous_interval": _replacement_event_diagnostic(
                                previous
                            ),
                            "conflicting_interval": _replacement_event_diagnostic(
                                event
                            ),
                            "overlap_seconds": round(previous_end - start, 6),
                        },
                    )

                requested_start = start
                start = previous_end
                event["start_seconds"] = start
                event["overlap_resolution"] = {
                    "policy": (
                        "semantic_terminal_end_card_clamped_to_"
                        "preceding_mid_promo_render_end"
                    ),
                    "previous_action_id": previous_action.get("action_id"),
                    "requested_start_seconds": round(requested_start, 6),
                    "resolved_start_seconds": round(start, 6),
                    "overlap_seconds_removed": round(previous_end - requested_start, 6),
                }
                resolutions.append(event["overlap_resolution"])

        normalized.append(event)

    return normalized, resolutions


def _operator_fixed_action_vertical_zone(action, width=0, height=0):
    """Return the compositor lane for a fixed watermark action.

    Older planners sometimes emitted a valid bbox but omitted ``placement``.
    Those actions were silently excluded from both the top and bottom passes.
    Geometry is therefore the authoritative fallback; a centre mark is routed
    to the nearest edge lane so it is treated instead of being left visible.
    """
    placement = str((action or {}).get("placement") or "").lower()
    if placement.startswith("top_") or (action or {}).get("handler") == "top_cleanup_brand_overlay":
        return "top"
    if placement.startswith("bottom_"):
        return "bottom"
    bbox = (action or {}).get("bbox") or {}
    if not bbox:
        segments = (action or {}).get("active_segments") or []
        if segments:
            bbox = (segments[0] or {}).get("bbox") or {}
    try:
        y = float(bbox.get("y"))
        box_h = max(1.0, float(bbox.get("height")))
        if height and height > 0:
            return "top" if y + box_h / 2.0 < float(height) * 0.50 else "bottom"
        # Normalized geometry is also accepted in API-created plans.
        if 0.0 <= y <= 1.0 and 0.0 < box_h <= 1.0:
            return "top" if y + box_h / 2.0 < 0.50 else "bottom"
    except (AttributeError, TypeError, ValueError):
        pass
    # Preserve the historical top lane for an action with no usable geometry;
    # this has a renderer and validation path, unlike silently dropping it.
    return "top"


def _replacement_render_sync(
    req: BrandingReplacementRenderRequest
):
    ffmpeg_runtime = _ffmpeg_runtime()

    if not (
        ffmpeg_runtime.get("ffmpeg_path")
        and ffmpeg_runtime.get("libx264_available")
    ):
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "replacement_render",
                "error": "ffmpeg_libx264_required",
                "runtime": ffmpeg_runtime,
            },
        )

    plan_path, plan = _read_json_workspace(
        req.replacement_plan_relative_path,
        "replacement_render",
    )

    if (
        plan.get("mode")
        != "branding_replacement_plan"
    ):
        raise HTTPException(
            status_code=422,
            detail=(
                "Expected branding_replacement_plan report."
            ),
        )

    source_rel = (
        (plan.get("source") or {})
        .get("relative_path")
    )

    video_path = _safe_workspace_path(
        source_rel
    )

    profile = plan.get("profile") or {}
    assets = profile.get("assets") or {}

    cap = cv2.VideoCapture(
        str(video_path)
    )

    if not cap.isOpened():
        raise HTTPException(
            status_code=422,
            detail="Could not open source video.",
        )

    try:
        meta = _video_metadata(cap)
    finally:
        cap.release()

    width = int(meta.get("width") or 0)
    height = int(meta.get("height") or 0)
    fps = float(meta.get("fps") or 30.0)
    duration = float(
        meta.get("duration_seconds") or 0.0
    )

    actions = []

    for action in plan.get("actions") or []:
        if (
            action.get("status") == "REVIEW"
            and not req.include_review_actions
        ):
            continue

        actions.append(action)

    top_actions = [
        action
        for action in actions
        if (
            action.get("type")
            == "fixed_brand_overlay"
            and _operator_fixed_action_vertical_zone(action, width, height) == "top"
        )
    ]

    moving_actions = [
        action
        for action in actions
        if action.get("type")
        == "moving_brand_overlay"
    ]

    bottom_actions = [
        action
        for action in actions
        if (
            action.get("type")
            == "fixed_brand_overlay"
            and _operator_fixed_action_vertical_zone(action, width, height) == "bottom"
        )
    ]

    # v0.18.10.9.6:
    # Moving competitor watermarks are rendered by the newer census-driven
    # dynamic visual-base pass. Bottom fixed overlays are also passed into the
    # visual-base renderer below. Keep a hard failure only when a moving action
    # exists but the production request did not enable the dynamic handler.
    dynamic_cover_ready = bool(
        getattr(
            req,
            "dynamic_brand_cover_enabled",
            False,
        )
        and getattr(
            req,
            "dynamic_brand_cover_census_report_relative_path",
            None,
        )
    )

    if (
        moving_actions
        and not dynamic_cover_ready
    ):
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "replacement_render",
                "error": "moving_action_requires_dynamic_full_render",
                "moving_action_count": len(moving_actions),
                "bottom_action_count": len(bottom_actions),
                "message": (
                    "Moving watermark actions were approved/present, but the "
                    "census-driven dynamic full-render handler was not enabled. "
                    "The renderer will not silently omit them."
                ),
            },
        )

    # The current visual-base function keeps its historical signature. Pass the
    # accepted bottom actions through the request object so the newer renderer
    # can apply them frame-by-frame without changing older call sites.
    setattr(
        req,
        "_full_render_bottom_actions",
        list(
            bottom_actions
        ),
    )

    promo_actions = sorted(
        [
            action
            for action in actions
            if action.get("type")
            == "mid_promo_replace"
        ],
        key=lambda x: float(
            x.get("start_seconds") or 0.0
        ),
    )

    end_actions = sorted(
        [
            action
            for action in actions
            if action.get("type")
            == "end_card_replace"
        ],
        key=lambda x: float(
            x.get("start_seconds") or 0.0
        ),
    )

    if len(end_actions) > 1:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "replacement_render",
                "error": "multiple_end_card_actions_not_supported",
                "count": len(end_actions),
            },
        )

    timestamp = _app_now().strftime(
        "%Y-%m-%d_%H%M%S"
    )

    out_dir = (
        WORKSPACE
        / "output"
        / "branding_replacement_render"
        / timestamp
        / video_path.stem
    )

    temp_dir = out_dir / "_segments"

    out_dir.mkdir(
        parents=True,
        exist_ok=True,
    )

    temp_dir.mkdir(
        parents=True,
        exist_ok=True,
    )

    visual_base = (
        temp_dir
        / f"{video_path.stem}.visual-base.mp4"
    )

    visual_base_report = _render_visual_base_full(
        video_path,
        visual_base,
        top_actions,
        profile,
        meta,
        req,
    )

    if (
        moving_actions
        and dynamic_cover_ready
        and int(
            visual_base_report.get(
                "dynamic_brand_track_count"
            )
            or 0
        )
        <= 0
    ):
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "replacement_render",
                "error": "moving_action_dynamic_track_missing",
                "moving_action_count": len(moving_actions),
                "message": (
                    "Moving watermark actions are present, but the dynamic "
                    "full-render pass resolved zero census tracks. Rendering "
                    "was stopped instead of silently omitting the watermark."
                ),
            },
        )

    if (
        bottom_actions
        and int(
            visual_base_report.get(
                "bottom_brand_cover_frames"
            )
            or 0
        )
        <= 0
    ):
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "replacement_render",
                "error": "bottom_action_not_rendered",
                "bottom_action_count": len(bottom_actions),
                "message": (
                    "Bottom fixed-brand actions are present, but no bottom "
                    "cover frame was rendered."
                ),
            },
        )

    source_media = _probe_media(
        video_path
    )

    source_has_audio = bool(
        source_media.get("has_audio")
    )

    # Resolve real assets once.
    mid_video = _resolve_optional_asset(
        assets.get(
            "mid_promo_video_relative_path"
        )
    )

    end_video = _resolve_optional_asset(
        assets.get(
            "end_card_video_relative_path"
        )
    )

    end_image = _resolve_optional_asset(
        assets.get(
            "end_card_image_relative_path"
        )
    )

    if (
        not req.allow_placeholder_assets
        and promo_actions
        and mid_video is None
    ):
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "replacement_render",
                "error": "mid_promo_asset_required",
            },
        )

    if (
        not req.allow_placeholder_assets
        and end_actions
        and end_video is None
        and end_image is None
    ):
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "replacement_render",
                "error": "end_card_asset_required",
            },
        )

    timeline_events = []

    for action in promo_actions:
        semantic_start = float(
            action["start_seconds"]
        )
        semantic_end = float(
            action["end_seconds"]
        )

        start_guard = _transition_guard_for_boundary(
            video_path,
            semantic_start,
            fps,
            duration,
            "start",
            req,
        )

        end_guard = _transition_guard_for_boundary(
            video_path,
            semantic_end,
            fps,
            duration,
            "end",
            req,
        )

        render_start = max(
            0.0,
            semantic_start
            - float(
                start_guard["extra_seconds"]
            ),
        )

        render_end = min(
            duration,
            semantic_end
            + float(
                end_guard["extra_seconds"]
            ),
        )

        # A source-specific confirmed Mid Promo boundary denotes the material
        # interval, but the outgoing frame can still contain a one-frame
        # competitor CTA/logo flash due to decoder timing.  Expand only the
        # replacement tail by the requested frame guard; never shift the
        # semantic/audited source boundary itself.
        action_source = action.get("source_candidate") or {}
        user_confirmed_boundary = bool(action_source.get("user_confirmed"))
        tail_guard_frames = max(
            0,
            int(
                getattr(req, "mid_promo_tail_guard_frames", 0)
                or 0
            ),
        )
        applied_tail_guard_seconds = 0.0
        if user_confirmed_boundary and tail_guard_frames > 0:
            applied_tail_guard_seconds = (
                float(tail_guard_frames) / max(1e-6, fps)
            )
            render_end = min(duration, render_end + applied_tail_guard_seconds)

        timeline_events.append(
            {
                "kind": "mid_promo_replace",
                "action": action,
                "semantic_start_seconds": semantic_start,
                "semantic_end_seconds": semantic_end,
                "start_seconds": render_start,
                "end_seconds": render_end,
                "start_guard": start_guard,
                "end_guard": end_guard,
                "user_confirmed_boundary": user_confirmed_boundary,
                "tail_guard_frames": tail_guard_frames,
                "tail_guard_seconds": round(applied_tail_guard_seconds, 6),
            }
        )

    if end_actions:
        action = end_actions[0]
        end_boundary = _operator_detect_end_card_start(
            video_path,
            duration,
            float(action["start_seconds"]),
            interval_seconds=float(
                getattr(
                    req,
                    "end_card_boundary_scan_interval_seconds",
                    0.05,
                )
            ),
            fps=fps,
            guard_frames=int(
                getattr(
                    req,
                    "end_card_boundary_guard_frames",
                    12,
                )
                or 0
            ),
        )

        timeline_events.append(
            {
                "kind": "end_card_replace",
                "action": action,
                "start_seconds": float(end_boundary["start_seconds"]),
                "end_seconds": float(
                    action.get("end_seconds")
                    or duration
                ),
                "end_card_boundary": end_boundary,
            }
        )

    timeline_events, overlap_resolutions = (
        _resolve_replacement_timeline_overlaps(
            timeline_events,
            fps,
        )
    )

    normalized_clips = []
    timeline_report = []
    cursor = 0.0
    clip_index = 0

    top_action_for_card = (
        top_actions[0]
        if top_actions
        else None
    )

    for event in timeline_events:
        start = float(
            event["start_seconds"]
        )
        end = float(
            event["end_seconds"]
        )

        if start > cursor + 0.001:
            clip_index += 1
            segment_path = (
                temp_dir
                / f"{clip_index:03d}-source.mp4"
            )

            clip = _source_segment_clip(
                visual_base,
                video_path,
                segment_path,
                cursor,
                start,
                meta,
                source_has_audio,
                req,
            )

            normalized_clips.append(
                clip
            )

            timeline_report.append(
                {
                    "kind": "source_story",
                    "source_start_seconds": round(
                        cursor,
                        3,
                    ),
                    "source_end_seconds": round(
                        start,
                        3,
                    ),
                    "output_duration_seconds": round(
                        clip["duration_seconds"],
                        3,
                    ),
                    "audio_source": clip["audio_source"],
                }
            )

        clip_index += 1

        if event["kind"] == "mid_promo_replace":
            placeholder_path = (
                temp_dir
                / "placeholder-mid-promo.png"
            )

            if mid_video is None:
                _save_placeholder_card(
                    placeholder_path,
                    width,
                    height,
                    profile,
                    "Promo replacement",
                    top_action_for_card,
                    req.top_brand_mode,
                )

                media_kind = "placeholder"
                asset_path = None
            else:
                media_kind = "video"
                asset_path = mid_video

            replacement_path = (
                temp_dir
                / f"{clip_index:03d}-mid-promo.mp4"
            )

            clip = _normalize_replacement_clip(
                replacement_path,
                media_kind,
                asset_path,
                placeholder_path,
                float(
                    req.placeholder_mid_promo_seconds
                ),
                meta,
                req,
            )

            normalized_clips.append(
                clip
            )

            timeline_report.append(
                {
                    "kind": "mid_promo_replace",
                    "semantic_source_segment": {
                        "start_seconds": round(
                            float(
                                event[
                                    "semantic_start_seconds"
                                ]
                            ),
                            3,
                        ),
                        "end_seconds": round(
                            float(
                                event[
                                    "semantic_end_seconds"
                                ]
                            ),
                            3,
                        ),
                    },
                    "render_removal_segment": {
                        "start_seconds": round(
                            start,
                            3,
                        ),
                        "end_seconds": round(
                            end,
                            3,
                        ),
                        "start_guard": event["start_guard"],
                        "end_guard": event["end_guard"],
                        "user_confirmed_boundary": event.get(
                            "user_confirmed_boundary"
                        ),
                        "tail_guard_frames": event.get(
                            "tail_guard_frames"
                        ),
                        "tail_guard_seconds": event.get(
                            "tail_guard_seconds"
                        ),
                    },
                    "replacement_duration_seconds": round(
                        clip["duration_seconds"],
                        3,
                    ),
                    "replacement_kind": clip["kind"],
                    "audio_source": clip["audio_source"],
                }
            )

        elif event["kind"] == "end_card_replace":
            placeholder_path = (
                temp_dir
                / "placeholder-end-card.png"
            )

            if end_video is not None:
                media_kind = "video"
                asset_path = end_video
            elif end_image is not None:
                media_kind = "image"
                asset_path = end_image
            else:
                _save_placeholder_card(
                    placeholder_path,
                    width,
                    height,
                    profile,
                    "Watch now",
                    top_action_for_card,
                    req.top_brand_mode,
                )

                media_kind = "placeholder"
                asset_path = None

            replacement_path = (
                temp_dir
                / f"{clip_index:03d}-end-card.mp4"
            )

            clip = _normalize_replacement_clip(
                replacement_path,
                media_kind,
                asset_path,
                placeholder_path,
                float(
                    (
                        profile.get("layout")
                        or {}
                    ).get(
                        "end_card_duration_seconds",
                        req.placeholder_end_card_seconds,
                    )
                    or req.placeholder_end_card_seconds
                ),
                meta,
                req,
            )

            normalized_clips.append(
                clip
            )

            timeline_report.append(
                {
                    "kind": "end_card_replace",
                    "source_cut_seconds": round(
                        start,
                        3,
                    ),
                    "source_end_seconds": round(
                        end,
                        3,
                    ),
                    "replacement_duration_seconds": round(
                        clip["duration_seconds"],
                        3,
                    ),
                    "replacement_kind": clip["kind"],
                    "audio_source": clip["audio_source"],
                    "boundary": event.get("end_card_boundary"),
                    "overlap_resolution": event.get("overlap_resolution"),
                }
            )

        cursor = end

        if event["kind"] == "end_card_replace":
            # End Card owns the remainder of the source timeline.
            cursor = duration
            break

    if cursor < duration - 0.001:
        clip_index += 1
        segment_path = (
            temp_dir
            / f"{clip_index:03d}-source-tail.mp4"
        )

        clip = _source_segment_clip(
            visual_base,
            video_path,
            segment_path,
            cursor,
            duration,
            meta,
            source_has_audio,
            req,
        )

        normalized_clips.append(
            clip
        )

        timeline_report.append(
            {
                "kind": "source_story",
                "source_start_seconds": round(
                    cursor,
                    3,
                ),
                "source_end_seconds": round(
                    duration,
                    3,
                ),
                "output_duration_seconds": round(
                    clip["duration_seconds"],
                    3,
                ),
                "audio_source": clip["audio_source"],
            }
        )

    if not normalized_clips:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "replacement_render",
                "error": "no_output_clips",
            },
        )

    output_path = (
        out_dir
        / f"{video_path.stem}.draft-processed.mp4"
    )

    # The final clip list is already normalized.  Preserve the original
    # visual-base file in production only until the concat output is verified;
    # this lets the source-story range be stream-copied instead of encoding it
    # again segment-by-segment, removing a major source of render latency.
    if len(normalized_clips) == 1:
        only_clip = normalized_clips[0]
        shutil.copy2(only_clip["path"], output_path)
        concat_report = {
            "concat_file": None,
            "mode": "single_clip_copy",
        }
    else:
        concat_report = _concat_normalized_clips(
            normalized_clips,
            output_path,
        )

    output_media = _probe_media(
        output_path
    )

    output_duration = float(
        output_media.get("duration_seconds")
        or sum(
            float(
                clip.get(
                    "duration_seconds"
                )
                or 0.0
            )
            for clip in normalized_clips
        )
    )

    result = {
        "ok": output_path.exists(),
        "version": "0.17.0",
        "mode": "branding_replacement_render",
        "render_stage": "DRAFT_FULL_RENDER",
        "source": {
            "relative_path": source_rel,
            "replacement_plan_relative_path": (
                plan_path
                .relative_to(
                    WORKSPACE
                )
                .as_posix()
            ),
        },
        "output": {
            "relative_path": (
                output_path
                .relative_to(
                    WORKSPACE
                )
                .as_posix()
            ),
            "duration_seconds": round(
                output_duration,
                3,
            ),
            "has_video": bool(
                output_media.get("has_video")
            ),
            "has_audio": bool(
                output_media.get("has_audio")
            ),
        },
        "video": meta,
        "profile": profile,
        "summary": {
            "top_brand_action_count": len(
                top_actions
            ),
            "moving_brand_action_count": len(
                moving_actions
            ),
            "bottom_brand_action_count": len(
                bottom_actions
            ),
            "mid_promo_replace_count": len(
                promo_actions
            ),
            "end_card_replace_count": len(
                end_actions
            ),
            "source_audio_present": (
                source_has_audio
            ),
            "source_audio_preserved_on_story_segments": True,
            "replacement_audio_policy": (
                "use replacement video audio when present; "
                "otherwise generate silence"
            ),
            "placeholder_assets_used": any(
                item.get("replacement_kind")
                == "replacement_placeholder"
                for item in timeline_report
            ),
            "source_video_modified": False,
            "full_processed_video_created": (
                output_path.exists()
            ),
            "diagonal_tiled_watermark_processed": False,
            "manual_visual_audio_confirmation_required": True,
            "replacement_overlap_resolution_count": len(
                overlap_resolutions
            ),
            "replacement_overlap_resolutions": overlap_resolutions,
        },
        "visual_base": visual_base_report,
        "timeline": timeline_report,
        "concat": {
            "mode": concat_report["mode"],
        },
        "notes": {
            "top_brand_assets": (
                "Later set logo_image_relative_path or icon_image_relative_path "
                "in the Brand Profile. top_brand_mode supports auto, logo_only, "
                "icon_text, and text_only."
            ),
            "semantic_boundaries": (
                "Replacement Plan semantic final_segment values are not changed. "
                "Mid Promo transition guard is render-only outward expansion."
            ),
            "draft": (
                "This is the first audio-aware full render. Keep as DRAFT until "
                "real brand assets and final visual/audio QC are accepted."
            ),
            "parked": (
                "Diagonal tiled watermark removal remains parked and is not "
                "performed by this renderer."
            ),
        },
        "output_relative_dir": (
            out_dir
            .relative_to(
                WORKSPACE
            )
            .as_posix()
        ),
    }

    report_path = (
        out_dir
        / f"{video_path.stem}.replacement-render.json"
    )

    result[
        "report_relative_path"
    ] = (
        report_path
        .relative_to(
            WORKSPACE
        )
        .as_posix()
    )

    report_path.write_text(
        json.dumps(
            result,
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )

    if not bool(
        req.keep_intermediate_files
    ):
        for clip in normalized_clips:
            try:
                Path(
                    clip["path"]
                ).unlink(
                    missing_ok=True
                )
            except Exception:
                pass

        try:
            visual_base.unlink(
                missing_ok=True
            )
        except Exception:
            pass

        concat_file = concat_report.get("concat_file")
        if concat_file:
            try:
                concat_file.unlink(missing_ok=True)
            except Exception:
                pass

        for p in temp_dir.glob(
            "placeholder-*.png"
        ):
            try:
                p.unlink(
                    missing_ok=True
                )
            except Exception:
                pass

        try:
            temp_dir.rmdir()
        except Exception:
            pass

    return result




# ---------------------------------------------------------------------------
# v0.12.1 Fixed-span bootstrap + safer icon mask + diagonal own-brand cover
#         + append own End Card when competitor End Card is absent
# ---------------------------------------------------------------------------


class BrandingReplacementRenderRequest(BaseModel):
    replacement_plan_relative_path: str

    include_review_actions: bool = True
    allow_placeholder_assets: bool = True

    watermark_treatment_mode: str = "rebrand_fixed_clean_dynamic"
    compose_top_brand_layers: bool = True
    top_brand_span_guard_seconds: float = 1.75

    # A top layer already classified as fixed_strong can be bootstrapped to
    # t=0 when its first accepted evidence appears very early in the video.
    top_fixed_bootstrap_to_zero: bool = True
    top_fixed_bootstrap_max_first_evidence_seconds: float = 8.0

    top_brand_icon_pad_ratio: float = 0.85
    top_brand_opposite_pad_ratio: float = 0.12
    top_brand_vertical_pad_ratio: float = 0.10

    top_icon_saliency_threshold: float = 24.0
    top_icon_saturation_threshold: float = 58.0
    top_icon_bright_threshold: float = 205.0
    top_icon_mask_dilate_pixels: int = 2

    top_brand_mode: str = "auto"

    mid_promo_transition_guard_frames: int = 4
    mid_promo_auto_transition_scan: bool = True
    mid_promo_transition_scan_seconds: float = 0.30
    mid_promo_transition_score_multiplier: float = 1.65
    mid_promo_transition_max_extra_frames: int = 8

    # Persistent and diagonal source marks are blurred in place, never
    # replaced with own-brand text, imagery or an opaque plate.
    diagonal_brand_cover_enabled: bool = True
    diagonal_brand_cover_text: Optional[str] = None
    # Per-source deterministic anchors are used when a persistent watermark is
    # visible but no same-source grid calibration has been stored yet. Values
    # are normalized source-frame bbox geometry and are never reused by stem.
    persistent_watermark_anchor_boxes: list[dict[str, float]] = Field(default_factory=list)
    diagonal_brand_cover_angle_degrees: float = 0.0
    diagonal_brand_cover_text_alpha: float = 1.0
    diagonal_brand_cover_plate_alpha: float = 1.0
    diagonal_brand_cover_scale_ratio: float = 0.72
    diagonal_brand_cover_max_points: int = 30
    persistent_watermark_cover_expand_ratio: float = 1.12

    # If semantic/router logic says competitor End Card is ABSENT, keep the
    # original video through its natural end and then append our own End Card.
    append_own_end_card_when_absent: bool = True

    placeholder_mid_promo_seconds: float = 3.0
    placeholder_end_card_seconds: float = 3.0

    crf: int = 15
    preset: str = "slow"
    audio_sample_rate: int = 48000
    audio_channels: int = 2
    audio_bitrate: str = "160k"

    keep_intermediate_files: bool = False

    # Populated automatically from Replacement Plan source by the render
    # wrapper. User normally does not need to supply this in Swagger.
    diagonal_brand_cover_router_report_relative_path: Optional[str] = None


def _top_action_span(
    action,
    duration,
    guard_seconds,
):
    segments = (
        action.get("active_segments")
        or []
    )

    starts = []
    ends = []

    for segment in segments:
        try:
            starts.append(
                float(
                    segment["start_seconds"]
                )
            )
            ends.append(
                float(
                    segment["end_seconds"]
                )
            )
        except Exception:
            continue

    if not starts or not ends:
        # Older plans represent a persistent fixed top layer with its stable
        # bbox but no per-segment OCR receipts. It is still an accepted fixed
        # replacement action, so do not silently skip it for the whole render.
        # Moving layers never reach this helper.
        if action.get("bbox") and _operator_fixed_action_vertical_zone(action) == "top":
            return {
                "start_seconds": 0.0,
                "end_seconds": round(max(0.0, float(duration or 0.0)), 3),
                "source": "fixed_action_without_segment_receipts_full_duration",
            }
        return None

    first_evidence = min(starts)

    # This helper is used only by the accepted top fixed-brand composition.
    # When first evidence is near the beginning, a fixed watermark is treated
    # as already active at t=0 rather than letting OCR sparsity leave an
    # unprocessed startup gap.
    if first_evidence <= 8.0:
        start = 0.0
        start_source = (
            "fixed_strong_early_evidence_bootstrap_to_zero"
        )
    else:
        start = max(
            0.0,
            first_evidence
            - float(guard_seconds),
        )
        start_source = (
            "first_fixed_evidence_minus_guard"
        )

    end = max(ends) + float(
        guard_seconds
    )

    if duration > 0:
        end = min(
            float(duration),
            end,
        )

    return {
        "start_seconds": round(
            start,
            3,
        ),
        "end_seconds": round(
            end,
            3,
        ),
        "first_evidence_seconds": round(
            first_evidence,
            3,
        ),
        "source": start_source,
    }


def _selective_icon_foreground_mask(
    frame,
    icon_bbox,
    saliency_threshold,
    saturation_threshold,
    bright_threshold,
    dilate_pixels,
):
    h, w = frame.shape[:2]

    b = _clip_bbox(
        icon_bbox,
        w,
        h,
    )

    x1 = int(b["x"])
    y1 = int(b["y"])
    x2 = int(
        b["x"] + b["width"]
    )
    y2 = int(
        b["y"] + b["height"]
    )

    roi = frame[
        y1:y2,
        x1:x2,
    ]

    mask = np.zeros(
        (h, w),
        dtype=np.uint8,
    )

    if roi.size == 0:
        return mask

    sigma = max(
        2.0,
        min(
            roi.shape[:2]
        ) / 6.0,
    )

    bg = cv2.GaussianBlur(
        roi,
        (0, 0),
        sigmaX=sigma,
    )

    diff = cv2.absdiff(
        roi,
        bg,
    )

    diff_gray = cv2.cvtColor(
        diff,
        cv2.COLOR_BGR2GRAY,
    )

    hsv = cv2.cvtColor(
        roi,
        cv2.COLOR_BGR2HSV,
    )

    saturation = hsv[..., 1]
    value = hsv[..., 2]

    sal = float(
        saliency_threshold
    )

    # v0.11.6 used:
    #   local contrast OR saturation OR brightness
    #
    # That could classify an entire red/saturated background patch as logo.
    #
    # v0.12.1:
    #   strong local contrast
    #   OR color/brightness WITH at least moderate local contrast
    #
    # Saturation by itself can never create the mask.
    strong_local = (
        diff_gray >= sal
    )

    moderate_local = (
        diff_gray
        >= max(
            8.0,
            sal * 0.52,
        )
    )

    colored_foreground = (
        (
            saturation
            >= float(
                saturation_threshold
            )
        )
        & moderate_local
    )

    bright_foreground = (
        (
            value
            >= float(
                bright_threshold
            )
        )
        & moderate_local
    )

    local = (
        strong_local
        | colored_foreground
        | bright_foreground
    ).astype(
        np.uint8
    ) * 255

    kernel_open = np.ones(
        (2, 2),
        dtype=np.uint8,
    )

    local = cv2.morphologyEx(
        local,
        cv2.MORPH_OPEN,
        kernel_open,
        iterations=1,
    )

    # Remove tiny components and avoid selecting broad flat background.
    count, labels, stats, _ = (
        cv2.connectedComponentsWithStats(
            local,
            8,
        )
    )

    filtered = np.zeros_like(
        local
    )

    roi_area = max(
        1,
        local.size,
    )

    for idx in range(
        1,
        count,
    ):
        area = int(
            stats[
                idx,
                cv2.CC_STAT_AREA,
            ]
        )

        if area < 2:
            continue

        # A "logo component" should not consume most of the ROI.
        if (
            float(area)
            / float(roi_area)
            > 0.42
        ):
            continue

        filtered[
            labels == idx
        ] = 255

    local = filtered

    dilate_pixels = max(
        0,
        int(dilate_pixels),
    )

    if (
        dilate_pixels > 0
        and np.count_nonzero(local)
        > 0
    ):
        k = (
            dilate_pixels
            * 2
            + 1
        )

        kernel = np.ones(
            (k, k),
            dtype=np.uint8,
        )

        local = cv2.dilate(
            local,
            kernel,
            iterations=1,
        )

    # Final safety cap: a selective icon mask must remain selective.
    coverage = float(
        np.count_nonzero(local)
    ) / float(
        max(
            1,
            local.size,
        )
    )

    if coverage > 0.38:
        strict = (
            diff_gray
            >= max(
                18.0,
                sal * 1.20,
            )
        ).astype(
            np.uint8
        ) * 255

        if dilate_pixels > 0:
            k = (
                dilate_pixels
                * 2
                + 1
            )
            kernel = np.ones(
                (k, k),
                dtype=np.uint8,
            )
            strict = cv2.dilate(
                strict,
                kernel,
                iterations=1,
            )

        local = strict

    mask[
        y1:y2,
        x1:x2,
    ] = local

    return mask


def _load_diagonal_brand_cover_geometry(
    req,
    width,
    height,
):
    if not bool(
        getattr(
            req,
            "diagonal_brand_cover_enabled",
            False,
        )
    ):
        return None

    router_rel = getattr(
        req,
        "diagonal_brand_cover_router_report_relative_path",
        None,
    )

    if not router_rel:
        return {
            "available": False,
            "reason": (
                "replacement_plan_has_no_router_report_reference"
            ),
        }

    try:
        _, router = _read_json_workspace(
            router_rel,
            "diagonal_brand_cover",
        )
    except Exception as exc:
        return {
            "available": False,
            "reason": (
                "router_report_unreadable"
            ),
            "error": str(exc)[:300],
        }

    tiled_layers = [
        layer
        for layer in (
            router.get(
                "watermark_layers"
            )
            or []
        )
        if (
            str(
                layer.get("handler")
                or ""
            )
            == "diagonal_tiled_grid"
            and str(
                layer.get("status")
                or ""
            )
            in {"AUTO", "REVIEW", "CALIBRATION_REQUIRED"}
        )
    ]

    if not tiled_layers:
        explicit_anchors = list(
            getattr(req, "persistent_watermark_anchor_boxes", None) or []
        )
        if explicit_anchors:
            points = []
            tile_widths = []
            tile_heights = []
            expand = max(
                1.0,
                float(getattr(req, "persistent_watermark_cover_expand_ratio", 1.12)),
            )
            for raw in explicit_anchors:
                try:
                    x = float(raw["x"])
                    y = float(raw["y"])
                    box_w = float(raw["width"])
                    box_h = float(raw["height"])
                except (KeyError, TypeError, ValueError):
                    continue
                if not (
                    0.0 <= x <= 1.0
                    and 0.0 <= y <= 1.0
                    and box_w > 0.0
                    and box_h > 0.0
                ):
                    continue
                tile_widths.append(box_w * width * expand)
                tile_heights.append(box_h * height * expand)
                points.append(
                    {
                        "id": str(raw.get("id") or f"anchor-{len(points) + 1:02d}"),
                        "center": {
                            "x": int(round((x + box_w / 2.0) * width)),
                            "y": int(round((y + box_h / 2.0) * height)),
                        },
                        # Preserve each anchor's exact rectangle. A collection
                        # may contain a thin centre wordmark and a compact corner
                        # badge; scaling all of them to the largest tile would
                        # over-cover the story frame.
                        "width": max(1, int(round(box_w * width * expand))),
                        "height": max(1, int(round(box_h * height * expand))),
                    }
                )
            if points:
                return {
                    "available": True,
                    "layer_id": "explicit_source_persistent_watermark_anchors",
                    "grid_report_relative_path": None,
                    "points": points,
                    "tile_width": max(40, int(round(max(tile_widths)))),
                    "tile_height": max(18, int(round(max(tile_heights)))),
                    "cover_mode": "opaque_plate_only",
                    "geometry_source": "explicit_source_persistent_watermark_anchors",
                }
        # The source router deliberately classifies a new same-brand layout as
        # CALIBRATION_REQUIRED. Before declining it, look for a profile whose
        # source fingerprint (stem) matches exactly; only that exact-source
        # match may reuse stored geometry automatically.
        registry = _load_watermark_registry()
        source_rel = str(
            ((router.get("source") or {}).get("relative_path") or "")
        )
        source_stem = Path(source_rel).stem
        for profile in (registry.get("profiles") or []):
            if str(profile.get("handler") or "") != "diagonal_tiled_grid":
                continue
            profile_source = str(
                ((profile.get("source") or {}).get("relative_path") or "")
            )
            if source_stem and Path(profile_source).stem == source_stem:
                geometry = profile.get("geometry") or {}
                origin = geometry.get("origin_normalized") or {}
                vectors = geometry.get("basis_vectors_normalized") or []
                tile = geometry.get("canonical_tile_normalized") or {}
                if len(vectors) >= 2 and origin and tile:
                    points = []
                    for row in range(-4, 6):
                        for col in range(-3, 6):
                            x = float(origin.get("x") or 0.0) + row * float(vectors[0].get("dx") or 0.0) + col * float(vectors[1].get("dx") or 0.0)
                            y = float(origin.get("y") or 0.0) + row * float(vectors[0].get("dy") or 0.0) + col * float(vectors[1].get("dy") or 0.0)
                            if -0.08 <= x <= 1.08 and -0.08 <= y <= 1.08:
                                points.append({"center": {"x": int(round(x * width)), "y": int(round(y * height))}})
                    return {
                        "available": bool(points),
                        "layer_id": profile.get("profile_id"),
                        "grid_report_relative_path": ((profile.get("source") or {}).get("report_relative_path")),
                        "points": points[:max(1, int(getattr(req, "diagonal_brand_cover_max_points", 30)))],
                        "tile_width": max(40, int(round(float(tile.get("width") or 0.20) * width))),
                        "tile_height": max(18, int(round(float(tile.get("height") or 0.045) * height))),
                        "geometry_source": "validated_same_source_profile",
                    }
        return {
            "available": False,
            "reason": (
                "no_calibrated_diagonal_tiled_layer"
            ),
        }

    layer = tiled_layers[0]

    try:
        report_rel, report = (
            _three_anchor_grid_report_from_router(
                router,
                layer,
            )
        )
    except Exception as exc:
        return {
            "available": False,
            "reason": (
                "three_anchor_grid_report_unavailable"
            ),
            "error": str(exc)[:300],
        }

    grid = (
        report.get("grid")
        or {}
    )

    points = list(
        grid.get(
            "predicted_grid_points"
        )
        or []
    )

    if not points:
        return {
            "available": False,
            "reason": (
                "grid_has_no_points"
            ),
        }

    max_points = max(
        1,
        int(
            getattr(
                req,
                "diagonal_brand_cover_max_points",
                30,
            )
        ),
    )

    points = points[
        :max_points
    ]

    canonical = (
        report.get(
            "canonical_tile"
        )
        or {}
    )

    tile_w = int(
        canonical.get(
            "width"
        )
        or round(
            width * 0.20
        )
    )

    tile_h = int(
        canonical.get(
            "height"
        )
        or round(
            height * 0.045
        )
    )

    tile_w = max(
        40,
        tile_w,
    )
    tile_h = max(
        18,
        tile_h,
    )

    return {
        "available": True,
        "layer_id": (
            layer.get(
                "layer_id"
            )
            or layer.get(
                "id"
            )
        ),
        "grid_report_relative_path": (
            report_rel
        ),
        "points": points,
        "tile_width": tile_w,
        "tile_height": tile_h,
    }


def _make_diagonal_brand_patch(
    text,
    tile_width,
    tile_height,
    angle_degrees,
    text_alpha,
    plate_alpha,
    scale_ratio,
):
    tile_width = max(
        40,
        int(tile_width),
    )
    tile_height = max(
        18,
        int(tile_height),
    )

    canvas_w = max(
        tile_width * 2,
        120,
    )
    canvas_h = max(
        tile_height * 3,
        72,
    )

    color = np.zeros(
        (
            canvas_h,
            canvas_w,
            3,
        ),
        dtype=np.uint8,
    )

    alpha = np.zeros(
        (
            canvas_h,
            canvas_w,
        ),
        dtype=np.uint8,
    )

    font = cv2.FONT_HERSHEY_SIMPLEX
    thickness = max(
        1,
        int(round(
            tile_height / 24.0
        )),
    )

    scale = max(
        0.34,
        float(
            tile_height
        )
        / 34.0
        * float(
            scale_ratio
        ),
    )

    text = str(
        text or ""
    ).strip()

    if not text:
        text = "BRAND"

    size, _ = cv2.getTextSize(
        text,
        font,
        scale,
        thickness,
    )

    if size[0] > tile_width * 0.94:
        scale *= (
            tile_width
            * 0.94
            / float(
                max(
                    1,
                    size[0],
                )
            )
        )
        scale = max(
            0.28,
            scale,
        )
        size, _ = cv2.getTextSize(
            text,
            font,
            scale,
            thickness,
        )

    cx = canvas_w // 2
    cy = canvas_h // 2

    tx = int(
        cx
        - size[0] / 2
    )
    ty = int(
        cy
        + size[1] / 2
    )

    pad_x = max(
        5,
        int(
            tile_height * 0.20
        ),
    )
    pad_y = max(
        3,
        int(
            tile_height * 0.14
        ),
    )

    plate_x1 = max(
        0,
        tx - pad_x,
    )
    plate_y1 = max(
        0,
        ty
        - size[1]
        - pad_y,
    )
    plate_x2 = min(
        canvas_w - 1,
        tx
        + size[0]
        + pad_x,
    )
    plate_y2 = min(
        canvas_h - 1,
        ty + pad_y,
    )

    # Dark neutral soft plate hides the faint competitor tile underneath.
    cv2.rectangle(
        color,
        (
            plate_x1,
            plate_y1,
        ),
        (
            plate_x2,
            plate_y2,
        ),
        (
            22,
            22,
            22,
        ),
        -1,
    )

    cv2.rectangle(
        alpha,
        (
            plate_x1,
            plate_y1,
        ),
        (
            plate_x2,
            plate_y2,
        ),
        int(
            round(
                255
                * max(
                    0.0,
                    min(
                        1.0,
                        float(
                            plate_alpha
                        ),
                    ),
                )
            )
        ),
        -1,
    )

    # Dark stroke + light own-brand text.
    cv2.putText(
        color,
        text,
        (
            tx + 1,
            ty + 1,
        ),
        font,
        scale,
        (
            0,
            0,
            0,
        ),
        thickness + 2,
        cv2.LINE_AA,
    )

    cv2.putText(
        color,
        text,
        (
            tx,
            ty,
        ),
        font,
        scale,
        (
            245,
            245,
            245,
        ),
        thickness,
        cv2.LINE_AA,
    )

    text_mask = np.zeros_like(
        alpha
    )

    cv2.putText(
        text_mask,
        text,
        (
            tx,
            ty,
        ),
        font,
        scale,
        255,
        thickness + 2,
        cv2.LINE_AA,
    )

    desired_text_alpha = int(
        round(
            255
            * max(
                0.0,
                min(
                    1.0,
                    float(
                        text_alpha
                    ),
                ),
            )
        )
    )

    alpha = np.maximum(
        alpha,
        (
            text_mask.astype(
                np.float32
            )
            / 255.0
            * desired_text_alpha
        ).astype(
            np.uint8
        ),
    )

    rotation = cv2.getRotationMatrix2D(
        (
            canvas_w / 2.0,
            canvas_h / 2.0,
        ),
        float(
            angle_degrees
        ),
        1.0,
    )

    rotated_color = cv2.warpAffine(
        color,
        rotation,
        (
            canvas_w,
            canvas_h,
        ),
        flags=cv2.INTER_LINEAR,
        borderMode=cv2.BORDER_CONSTANT,
        borderValue=(0, 0, 0),
    )

    rotated_alpha = cv2.warpAffine(
        alpha,
        rotation,
        (
            canvas_w,
            canvas_h,
        ),
        flags=cv2.INTER_LINEAR,
        borderMode=cv2.BORDER_CONSTANT,
        borderValue=0,
    )

    return (
        rotated_color,
        rotated_alpha,
    )


def _overlay_rgba_like(
    frame,
    patch,
    alpha,
    center_x,
    center_y,
):
    out = frame

    ph, pw = alpha.shape[:2]
    fh, fw = frame.shape[:2]

    x1 = int(
        round(
            float(center_x)
            - pw / 2.0
        )
    )
    y1 = int(
        round(
            float(center_y)
            - ph / 2.0
        )
    )

    x2 = x1 + pw
    y2 = y1 + ph

    sx1 = 0
    sy1 = 0
    sx2 = pw
    sy2 = ph

    if x1 < 0:
        sx1 = -x1
        x1 = 0
    if y1 < 0:
        sy1 = -y1
        y1 = 0
    if x2 > fw:
        sx2 -= x2 - fw
        x2 = fw
    if y2 > fh:
        sy2 -= y2 - fh
        y2 = fh

    if x2 <= x1 or y2 <= y1:
        return out

    src = patch[
        sy1:sy2,
        sx1:sx2,
    ].astype(
        np.float32
    )

    a = (
        alpha[
            sy1:sy2,
            sx1:sx2,
        ].astype(
            np.float32
        )
        / 255.0
    )[..., None]

    dst = out[
        y1:y2,
        x1:x2,
    ].astype(
        np.float32
    )

    out[
        y1:y2,
        x1:x2,
    ] = np.clip(
        dst
        * (
            1.0 - a
        )
        + src * a,
        0,
        255,
    ).astype(
        np.uint8
    )

    return out


def _apply_diagonal_brand_cover(
    frame,
    geometry,
    profile,
    req,
):
    if not geometry:
        return frame

    if not bool(
        geometry.get(
            "available"
        )
    ):
        return frame

    out = frame.copy()

    for point in (
        geometry.get(
            "points"
        )
        or []
    ):
        center = (
            point.get(
                "center"
            )
            or {}
        )

        try:
            cx = float(
                center["x"]
            )
            cy = float(
                center["y"]
            )
        except Exception:
            continue

        point_width = int(point.get("width") or geometry["tile_width"])
        point_height = int(point.get("height") or geometry["tile_height"])
        point_bbox = {
            "x": int(round(cx - point_width / 2.0)),
            "y": int(round(cy - point_height / 2.0)),
            "width": point_width,
            "height": point_height,
        }
        # Persistent anchors are fixed competitor product UI. Replace them
        # deterministically with the own brand; only moving tracks use repair.
        assets = profile.get("assets") or {}
        logo = _load_bgr_asset(
            assets.get("logo_image_relative_path")
            or assets.get("icon_image_relative_path")
        )
        out = _draw_brand_banner(
            out,
            point_bbox,
            profile.get("product_name") or profile.get("brand_name") or "",
            logo_image=logo,
            min_height=point_height,
        )

    return out



def _operator_bottom_action_bbox_at_time(
    action,
    t,
    duration,
):
    """Return the active bottom bbox at time t, or None when inactive."""
    segments = (
        (action or {}).get(
            "active_segments"
        )
        or []
    )

    if segments:
        for segment in segments:
            try:
                start = float(
                    segment.get(
                        "start_seconds"
                    )
                    or 0.0
                )
                end = float(
                    segment.get(
                        "end_seconds"
                    )
                    or start
                )
            except Exception:
                continue

            if (
                t >= start - 1e-3
                and t <= end + 1e-3
            ):
                return (
                    segment.get(
                        "bbox"
                    )
                    or (action or {}).get(
                        "bbox"
                    )
                )
        return None

    try:
        start = float(
            (action or {}).get(
                "start_seconds"
            )
            or 0.0
        )
    except Exception:
        start = 0.0

    try:
        end = float(
            (action or {}).get(
                "end_seconds"
            )
            or duration
            or 0.0
        )
    except Exception:
        end = float(
            duration
            or 0.0
        )

    if end <= 0:
        end = float(
            duration
            or 0.0
        )

    if (
        t < start - 1e-3
        or (
            end > 0
            and t > end + 1e-3
        )
    ):
        return None

    return (
        (action or {}).get(
            "bbox"
        )
    )


def _operator_inpaint_bbox_fast(frame, bbox, *, padding=2, radius=3.0):
    """Inpaint only the affected ROI instead of the full video frame.

    Full-frame Telea inpainting inside a 25/30-fps render loop is extremely
    expensive (and was the direct cause of the 1200-second render timeout).
    The source mark is confined to ``bbox``, so a padded local crop preserves
    the same result while reducing the pixel workload by orders of magnitude.
    """
    out = frame.copy()
    height, width = out.shape[:2]
    clipped = _clip_bbox(bbox, width, height)
    x1 = max(0, int(clipped["x"]) - int(padding))
    y1 = max(0, int(clipped["y"]) - int(padding))
    x2 = min(width, int(clipped["x"]) + int(clipped["width"]) + int(padding))
    y2 = min(height, int(clipped["y"]) + int(clipped["height"]) + int(padding))
    if x2 <= x1 or y2 <= y1:
        return out
    crop = out[y1:y2, x1:x2]
    local_mask = np.zeros(crop.shape[:2], dtype=np.uint8)
    mx1 = max(0, int(clipped["x"]) - x1)
    my1 = max(0, int(clipped["y"]) - y1)
    mx2 = min(crop.shape[1], mx1 + int(clipped["width"]))
    my2 = min(crop.shape[0], my1 + int(clipped["height"]))
    local_mask[my1:my2, mx1:mx2] = 255
    try:
        out[y1:y2, x1:x2] = cv2.inpaint(
            crop,
            local_mask,
            float(radius),
            cv2.INPAINT_TELEA,
        )
    except Exception:
        pass
    return out


def _operator_rebrand_bottom_fixed_mark(
    frame,
    bbox,
    profile,
):
    """Remove a fixed bottom mark before placing the replacement mark.

    Bottom actions are source-specific UI/logo regions. The old renderer drew
    a minimum-width dark banner straight over the detected geometry, which left
    parts of the original icon/text visible whenever the geometry differed.
    """
    out = frame.copy()
    height, width = out.shape[:2]
    source_bbox = _clip_bbox(bbox, width, height)
    try:
        out = _operator_inpaint_bbox_fast(out, source_bbox, padding=2, radius=3.0)
    except Exception:
        # Never leave source pixels beneath an own-brand replacement because
        # OpenCV cannot repair an edge-of-frame rectangle.
        out = _draw_fast_local_cover_plate(out, source_bbox)

    assets = profile.get("assets") or {}
    logo = _load_bgr_asset(
        assets.get("logo_image_relative_path")
        or assets.get("icon_image_relative_path")
    )
    return _draw_brand_banner(
        out,
        source_bbox,
        profile.get("product_name") or profile.get("brand_name") or "",
        logo_image=logo,
        min_height=int(source_bbox.get("height") or 0),
    )


def _operator_merge_overlapping_bottom_actions(
    actions,
    width,
    height,
):
    """Merge duplicate bottom detections into one render action.

    A single product mark can be detected both as a stable bottom layer and a
    recovered moving/fixed track.  Rendering every overlapping action stacks
    our banner and turns the bottom mark into duplicated text/icons.  Keep the
    most complete action and merge only its temporal evidence.
    """
    merged = []
    for action in actions or []:
        bbox = (action or {}).get("bbox")
        if not bbox:
            continue
        try:
            bbox = _clip_bbox(bbox, int(width), int(height))
        except Exception:
            continue

        duplicate = None
        for existing in merged:
            if _bbox_iou(bbox, existing["bbox"]) >= 0.55:
                duplicate = existing
                break

        if duplicate is None:
            copied = dict(action)
            copied["bbox"] = bbox
            copied["active_segments"] = list(
                action.get("active_segments") or []
            )
            merged.append(copied)
            continue

        existing_segments = duplicate.setdefault("active_segments", [])
        for segment in action.get("active_segments") or []:
            if segment not in existing_segments:
                existing_segments.append(segment)

    return merged


def _operator_filter_dynamic_tracks_covered_by_bottom_actions(
    tracks,
    bottom_actions,
    width,
    height,
):
    """Avoid applying dynamic and bottom-brand covers to the same mark."""
    bottom_boxes = []
    for action in bottom_actions or []:
        bbox = (action or {}).get("bbox")
        if not bbox:
            continue
        try:
            bottom_boxes.append(_clip_bbox(bbox, int(width), int(height)))
        except Exception:
            continue

    if not bottom_boxes:
        return list(tracks or []), []

    kept = []
    skipped = []
    for track in tracks or []:
        points = list((track or {}).get("points") or [])
        observed = []
        for point in points:
            bbox = point.get("bbox")
            if not bbox:
                continue
            try:
                observed.append(_clip_bbox(bbox, int(width), int(height)))
            except Exception:
                continue

        overlap_count = sum(
            1
            for bbox in observed
            if any(_bbox_iou(bbox, bottom) >= 0.20 for bottom in bottom_boxes)
        )
        # A track whose observed positions are predominantly inside the bottom
        # replacement band is not a second moving watermark; the bottom banner
        # is the single authoritative treatment for it.
        if observed and overlap_count >= max(1, int(math.ceil(len(observed) * 0.60))):
            skipped.append(track.get("cluster_id"))
            continue

        kept.append(track)

    return kept, skipped


def _render_visual_base_full(
    video_path,
    out_path,
    top_actions,
    profile,
    meta,
    req,
):
    width = int(
        meta["width"]
    )
    height = int(
        meta["height"]
    )
    fps = float(
        meta["fps"]
    )
    duration = float(
        meta["duration_seconds"]
    )

    dynamic_tracks = (
        _operator_dynamic_brand_tracks_from_census(
            getattr(
                req,
                "dynamic_brand_cover_census_report_relative_path",
                None,
            )
        )
        if bool(
            getattr(
                req,
                "dynamic_brand_cover_enabled",
                False,
            )
        )
        else []
    )
    faint_reference_tracks = _faint_watermark_anchor_tracks_from_visual_report(
        getattr(req, "faint_watermark_visual_report_relative_path", None),
        float(getattr(req, "faint_watermark_visual_min_score", 0.48)),
    )
    if faint_reference_tracks:
        dynamic_tracks = [*dynamic_tracks, *faint_reference_tracks]
    dynamic_tracks_resolved_count = len(dynamic_tracks)

    diagonal_geometry = (
        _load_diagonal_brand_cover_geometry(
            req,
            width,
            height,
        )
    )

    writer, runtime = (
        _open_x264_raw_writer(
            out_path,
            width,
            height,
            fps,
            int(req.crf),
            str(req.preset),
        )
    )

    cap = cv2.VideoCapture(
        str(video_path)
    )

    if not cap.isOpened():
        raise HTTPException(
            status_code=422,
            detail="Could not open source video.",
        )

    frames_written = 0
    top_composed_frames = 0
    top_icon_asset_frames = 0
    top_product_text_frames = 0
    top_icon_treatments = {}
    top_product_name = str(
        profile.get("product_name") or ""
    ).strip()
    dynamic_brand_cover_frames = 0
    dynamic_brand_cover_applications = 0
    dynamic_brand_track_sources = {}

    bottom_actions = _operator_merge_overlapping_bottom_actions(
        list(
            getattr(
                req,
                "_full_render_bottom_actions",
                [],
            )
            or []
        ),
        width,
        height,
    )
    # A bottom banner is applied after the dynamic layer, but its geometry can
    # legitimately vary over time.  Do not globally remove a dynamic track just
    # because most of its sampled boxes overlap that banner: the remaining
    # interval can otherwise leak a verified watermark and has no frame receipt.
    # Rendering the tight dynamic cover first is safe because the opaque bottom
    # treatment remains the final visual layer in its own region.
    dynamic_tracks_skipped_by_bottom = []
    # Keep a per-track receipt instead of only aggregate frame counters. An
    # aggregate can be positive while one of several verified tracks was lost
    # during interpolation, de-duplication, or composition.
    dynamic_brand_receipts = {}
    for index, track in enumerate(dynamic_tracks, 1):
        receipt_key = str(
            track.get("cluster_id")
            or f"dynamic-track-{index:02d}"
        )
        track["_operator_dynamic_receipt_key"] = receipt_key
        dynamic_brand_receipts[receipt_key] = {
            "track_id": receipt_key,
            "frames_rendered": 0,
            "first_render_time": None,
            "last_render_time": None,
        }

    # Pre-compute visibility windows from exactly the same track set as the
    # receipt ledger. Without this gate the renderer interpolates every track on
    # every frame, including long stretches where the source watermark is absent.
    dynamic_track_windows = []
    for _track in dynamic_tracks:
        _points = list(_track.get("points") or [])
        if not _points:
            continue
        try:
            _start = min(float(p.get("time_seconds") or 0.0) for p in _points)
            _end = max(float(p.get("time_seconds") or 0.0) for p in _points)
        except Exception:
            continue
        _gap = float(
            _track.get("max_interpolation_gap_seconds")
            or _track.get("hold_seconds")
            or 0.32
        )
        dynamic_track_windows.append(
            (_track, max(0.0, _start - _gap), min(duration, _end + _gap))
        )

    bottom_brand_cover_frames = 0
    bottom_brand_cover_applications = 0

    for track in dynamic_tracks:
        source = str(
            track.get(
                "recovery_source"
            )
            or track.get(
                "classification"
            )
            or "unknown"
        )

        dynamic_brand_track_sources[
            source
        ] = (
            dynamic_brand_track_sources.get(
                source,
                0,
            )
            + 1
        )

    diagonal_cover_frames = 0
    write_error = None
    render_started_monotonic = (
        time.monotonic()
    )
    render_timeout_seconds = (
        _operator_ffmpeg_timeout_seconds()
    )

    # All static assets are decoded/resized lazily into this request-local
    # cache.  Prebuild the diagonal tile once so no font rendering/rotation
    # occurs inside the frame loop.
    if diagonal_geometry and bool(diagonal_geometry.get("available")):
        _apply_diagonal_brand_cover(
            np.zeros((height, width, 3), dtype=np.uint8),
            diagonal_geometry,
            profile,
            req,
        )

    try:
        while True:
            ok, frame = cap.read()

            if (
                not ok
                or frame is None
            ):
                break

            if (
                frames_written
                % 30
                == 0
            ):
                _operator_raise_if_cancelled()

            if (
                frames_written
                % 30
                == 0
                and (
                    time.monotonic()
                    - render_started_monotonic
                )
                > render_timeout_seconds
            ):
                write_error = (
                    "operator_render_timeout:"
                    + str(
                        render_timeout_seconds
                    )
                )
                try:
                    writer.kill()
                except Exception:
                    pass
                break

            t = (
                frames_written
                / float(
                    max(
                        1e-6,
                        fps,
                    )
                )
            )

            if (
                top_actions
                and bool(
                    req.compose_top_brand_layers
                )
            ):
                frame, applied = (
                    _apply_top_brand_composition_render(
                        frame,
                        t,
                        top_actions,
                        profile,
                        width,
                        height,
                        duration,
                        req,
                    )
                )

                if applied:
                    top_composed_frames += 1

                    treatments = [
                        str(
                            item.get("icon_treatment") or ""
                        )
                        for item in applied
                    ]

                    for treatment in treatments:
                        if not treatment:
                            continue

                        top_icon_treatments[treatment] = (
                            top_icon_treatments.get(
                                treatment,
                                0,
                            )
                            + 1
                        )

                    if any(
                        treatment == "own_icon_asset"
                        for treatment in treatments
                    ):
                        top_icon_asset_frames += 1

                    if (
                        top_product_name
                        and str(
                            getattr(
                                req,
                                "top_brand_mode",
                                "auto",
                            )
                            or "auto"
                        ).lower()
                        != "logo_only"
                    ):
                        top_product_text_frames += 1

            if (
                dynamic_track_windows
                and bool(
                    getattr(
                        req,
                        "dynamic_brand_cover_enabled",
                        False,
                    )
                )
            ):
                active_dynamic_tracks = [
                    track
                    for track, window_start, window_end in dynamic_track_windows
                    if window_start <= t <= window_end
                ]
                if not active_dynamic_tracks:
                    active_dynamic_tracks = []
                frame, dynamic_applied = (
                    _operator_apply_dynamic_brand_cover(
                        frame,
                        t,
                        active_dynamic_tracks,
                        profile,
                        width,
                        height,
                        req,
                    )
                )

                if dynamic_applied:
                    dynamic_brand_cover_frames += 1
                    dynamic_brand_cover_applications += len(
                        dynamic_applied
                    )
                    for application in dynamic_applied:
                        receipt_key = str(application.get("receipt_key") or "")
                        receipt = dynamic_brand_receipts.get(receipt_key)
                        if receipt is None:
                            continue
                        receipt["frames_rendered"] += 1
                        if receipt["first_render_time"] is None:
                            receipt["first_render_time"] = round(float(t), 3)
                        receipt["last_render_time"] = round(float(t), 3)

            bottom_applied = 0
            bottom_regions = []
            if bottom_actions:
                for bottom_action in bottom_actions:
                    bottom_bbox = (
                        _operator_bottom_action_bbox_at_time(
                            bottom_action,
                            t,
                            duration,
                        )
                    )

                    if not bottom_bbox:
                        continue

                    bottom_bbox = _clip_bbox(
                        bottom_bbox,
                        width,
                        height,
                    )
                    if any(
                        _bbox_iou(bottom_bbox, prior) >= 0.55
                        for prior in bottom_regions
                    ):
                        continue

                    # Fixed CTA/product UI is a two-stage replacement: remove
                    # source icon/characters first, then draw one own-brand
                    # mark. The helper's final draw is equivalent to
                    # _draw_brand_banner(source-cleaned-frame, ...).
                    frame = _operator_rebrand_bottom_fixed_mark(
                        frame,
                        bottom_bbox,
                        profile,
                    )
                    bottom_applied += 1
                    bottom_regions.append(bottom_bbox)

                if bottom_applied:
                    bottom_brand_cover_frames += 1
                    bottom_brand_cover_applications += int(
                        bottom_applied
                    )

            if (
                bool(
                    getattr(
                        req,
                        "diagonal_brand_cover_enabled",
                        False,
                    )
                )
                and diagonal_geometry
                and bool(
                    diagonal_geometry.get(
                        "available"
                    )
                )
            ):
                frame = (
                    _apply_diagonal_brand_cover(
                        frame,
                        diagonal_geometry,
                        profile,
                        req,
                    )
                )
                diagonal_cover_frames += 1

            try:
                writer.stdin.write(
                    frame.tobytes()
                )
            except Exception as exc:
                write_error = str(
                    exc
                )[:500]
                break

            frames_written += 1

    finally:
        cap.release()

        try:
            writer.stdin.close()
        except Exception:
            pass

    stderr = b""

    try:
        stderr = (
            writer.stderr.read()
            if writer.stderr
            else b""
        )
    except Exception:
        pass

    code = writer.wait()

    if (
        code != 0
        or write_error is not None
        or not out_path.exists()
    ):
        raise HTTPException(
            status_code=500,
            detail={
                "stage": (
                    "replacement_render_visual_base"
                ),
                "error": (
                    write_error
                    or stderr.decode(
                        "utf-8",
                        errors="replace",
                    )[:1000]
                    or (
                        f"ffmpeg exited {code}"
                    )
                ),
            },
        )

    return {
        "relative_path": (
            out_path
            .relative_to(
                WORKSPACE
            )
            .as_posix()
        ),
        "frames_written": (
            frames_written
        ),
        "top_composed_frames": (
            top_composed_frames
        ),
        "top_icon_asset_frames": (
            top_icon_asset_frames
        ),
        "top_product_text_frames": (
            top_product_text_frames
        ),
        "top_icon_treatments": (
            top_icon_treatments
        ),
        "top_product_name": (
            top_product_name
        ),
        "top_brand_mode": str(
            getattr(
                req,
                "top_brand_mode",
                "auto",
            )
            or "auto"
        ),
        "dynamic_brand_cover_enabled": bool(
            getattr(
                req,
                "dynamic_brand_cover_enabled",
                False,
            )
        ),
        "dynamic_brand_track_count": len(
            dynamic_tracks
        ),
        "dynamic_brand_track_count_before_bottom_dedup": (
            dynamic_tracks_resolved_count
        ),
        "dynamic_brand_track_sources": (
            dynamic_brand_track_sources
        ),
        "dynamic_brand_track_ids": [
            track.get(
                "cluster_id"
            )
            for track in dynamic_tracks
        ],
        "faint_reference_track_count": len(faint_reference_tracks),
        "faint_reference_track_ids": [
            track.get("cluster_id") for track in faint_reference_tracks
        ],
        "dynamic_brand_track_ids_skipped_by_bottom_cover": (
            dynamic_tracks_skipped_by_bottom
        ),
        "dynamic_brand_cover_frames": (
            dynamic_brand_cover_frames
        ),
        "dynamic_brand_cover_applications": (
            dynamic_brand_cover_applications
        ),
        "dynamic_brand_actions_detected": len(dynamic_tracks),
        "dynamic_brand_actions_rendered": sum(
            1
            for receipt in dynamic_brand_receipts.values()
            if int(receipt.get("frames_rendered") or 0) > 0
        ),
        "dynamic_brand_per_track_receipts": list(
            dynamic_brand_receipts.values()
        ),
        "dynamic_brand_receipt_equality": (
            len(dynamic_tracks) > 0
            and all(
                int(receipt.get("frames_rendered") or 0) > 0
                for receipt in dynamic_brand_receipts.values()
            )
        ),
        "bottom_brand_action_count": len(
            bottom_actions
        ),
        "bottom_brand_cover_frames": (
            bottom_brand_cover_frames
        ),
        "bottom_brand_cover_applications": (
            bottom_brand_cover_applications
        ),
        "bottom_brand_treatment": "opaque_own_brand_banner",
        "diagonal_brand_cover": (
            diagonal_geometry
        ),
        "diagonal_brand_cover_frames": (
            diagonal_cover_frames
        ),
        "encoder": {
            "engine": "ffmpeg",
            "codec": "libx264",
            "crf": int(
                req.crf
            ),
            "preset": str(
                req.preset
            ),
            "runtime": runtime,
        },
    }


_replacement_render_sync_v0120 = (
    _replacement_render_sync
)


def _replacement_render_sync(
    req: BrandingReplacementRenderRequest
):
    # Recover the Watermark Router report automatically from the accepted plan.
    plan_path, plan = (
        _read_json_workspace(
            req.replacement_plan_relative_path,
            "replacement_render_v0121",
        )
    )

    router_rel = (
        (
            plan.get(
                "source"
            )
            or {}
        ).get(
            "router_report_relative_path"
        )
    )

    if router_rel:
        req.diagonal_brand_cover_router_report_relative_path = (
            router_rel
        )

    had_end_card_action = any(
        action.get(
            "type"
        )
        == "end_card_replace"
        and (
            action.get(
                "status"
            )
            != "REVIEW"
            or bool(
                req.include_review_actions
            )
        )
        for action in (
            plan.get(
                "actions"
            )
            or []
        )
    )

    result = (
        _replacement_render_sync_v0120(
            req
        )
    )

    result["version"] = "0.12.1"

    # If the source had no competitor End Card action, optionally append our
    # own End Card after the fully preserved source ending.
    if (
        not had_end_card_action
        and bool(
            req.append_own_end_card_when_absent
        )
    ):
        output_rel = (
            (
                result.get(
                    "output"
                )
                or {}
            ).get(
                "relative_path"
            )
        )

        if not output_rel:
            return result

        output_path = (
            _safe_workspace_path(
                output_rel
            )
        )

        profile = (
            result.get(
                "profile"
            )
            or plan.get(
                "profile"
            )
            or {}
        )

        assets = (
            profile.get(
                "assets"
            )
            or {}
        )

        end_video = (
            _resolve_optional_asset(
                assets.get(
                    "end_card_video_relative_path"
                )
            )
        )

        end_image = (
            _resolve_optional_asset(
                assets.get(
                    "end_card_image_relative_path"
                )
            )
        )

        if (
            not bool(
                req.allow_placeholder_assets
            )
            and end_video is None
            and end_image is None
        ):
            raise HTTPException(
                status_code=422,
                detail={
                    "stage": (
                        "replacement_render"
                    ),
                    "error": (
                        "end_card_asset_required_for_append"
                    ),
                },
            )

        video_meta = (
            result.get(
                "video"
            )
            or {}
        )

        width = int(
            video_meta.get(
                "width"
            )
            or 0
        )
        height = int(
            video_meta.get(
                "height"
            )
            or 0
        )

        out_dir = output_path.parent

        append_temp = (
            out_dir
            / "_append_endcard"
        )

        append_temp.mkdir(
            parents=True,
            exist_ok=True,
        )

        placeholder_path = (
            append_temp
            / "placeholder-end-card.png"
        )

        top_actions = [
            action
            for action in (
                plan.get(
                    "actions"
                )
                or []
            )
            if (
                action.get(
                    "type"
                )
                == "fixed_brand_overlay"
                and (
                    action.get(
                        "handler"
                    )
                    == "top_cleanup_brand_overlay"
                    or str(
                        action.get(
                            "placement"
                        )
                        or ""
                    ).startswith(
                        "top_"
                    )
                )
            )
        ]

        if end_video is not None:
            media_kind = "video"
            asset_path = end_video
        elif end_image is not None:
            media_kind = "image"
            asset_path = end_image
        else:
            _save_placeholder_card(
                placeholder_path,
                width,
                height,
                profile,
                "Watch now",
                (
                    top_actions[0]
                    if top_actions
                    else None
                ),
                req.top_brand_mode,
            )
            media_kind = "placeholder"
            asset_path = None

        card_path = (
            append_temp
            / "own-end-card.mp4"
        )

        card_clip = (
            _normalize_replacement_clip(
                card_path,
                media_kind,
                asset_path,
                placeholder_path,
                float(
                    (
                        profile.get(
                            "layout"
                        )
                        or {}
                    ).get(
                        "end_card_duration_seconds",
                        req.placeholder_end_card_seconds,
                    )
                    or req.placeholder_end_card_seconds
                ),
                video_meta,
                req,
            )
        )

        appended_path = (
            out_dir
            / (
                output_path.stem
                + ".append-working.mp4"
            )
        )

        existing_info = (
            _probe_media(
                output_path
            )
        )

        concat_report = (
            _concat_normalized_clips(
                [
                    {
                        "path": (
                            output_path
                        ),
                        "duration_seconds": (
                            existing_info.get(
                                "duration_seconds"
                            )
                            or 0.0
                        ),
                    },
                    card_clip,
                ],
                appended_path,
            )
        )

        if not appended_path.exists():
            raise HTTPException(
                status_code=500,
                detail={
                    "stage": (
                        "replacement_render_append_end_card"
                    ),
                    "error": (
                        "append_output_missing"
                    ),
                },
            )

        output_path.unlink(
            missing_ok=True
        )

        appended_path.replace(
            output_path
        )

        final_info = (
            _probe_media(
                output_path
            )
        )

        result[
            "output"
        ][
            "duration_seconds"
        ] = round(
            float(
                final_info.get(
                    "duration_seconds"
                )
                or 0.0
            ),
            3,
        )

        result[
            "output"
        ][
            "has_video"
        ] = bool(
            final_info.get(
                "has_video"
            )
        )

        result[
            "output"
        ][
            "has_audio"
        ] = bool(
            final_info.get(
                "has_audio"
            )
        )

        result.setdefault(
            "timeline",
            [],
        ).append(
            {
                "kind": (
                    "end_card_append"
                ),
                "competitor_end_card_presence": (
                    "ABSENT_OR_NO_REPLACE_ACTION"
                ),
                "source_preserved_to_natural_end": True,
                "replacement_duration_seconds": round(
                    float(
                        card_clip[
                            "duration_seconds"
                        ]
                    ),
                    3,
                ),
                "replacement_kind": (
                    card_clip[
                        "kind"
                    ]
                ),
                "audio_source": (
                    card_clip[
                        "audio_source"
                    ]
                ),
            }
        )

        result.setdefault(
            "summary",
            {},
        )[
            "own_end_card_appended_when_competitor_absent"
        ] = True

        result[
            "summary"
        ][
            "end_card_append_count"
        ] = 1

        try:
            card_path.unlink(
                missing_ok=True
            )
        except Exception:
            pass

        try:
            placeholder_path.unlink(
                missing_ok=True
            )
        except Exception:
            pass

        try:
            concat_report[
                "concat_file"
            ].unlink(
                missing_ok=True
            )
        except Exception:
            pass

        try:
            append_temp.rmdir()
        except Exception:
            pass

    else:
        result.setdefault(
            "summary",
            {},
        )[
            "own_end_card_appended_when_competitor_absent"
        ] = False

        result[
            "summary"
        ][
            "end_card_append_count"
        ] = 0

    result.setdefault(
        "summary",
        {},
    )[
        "top_fixed_early_evidence_bootstrap_enabled"
    ] = True

    result[
        "summary"
    ][
        "safer_icon_mask_no_saturation_only"
    ] = True

    result[
        "summary"
    ][
        "diagonal_brand_cover_enabled"
    ] = bool(
        req.diagonal_brand_cover_enabled
    )

    result["notes"] = {
        **(
            result.get(
                "notes"
            )
            or {}
        ),
        "v0.12.1_top_start": (
            "Accepted top fixed watermark with first evidence in the startup "
            "window is treated as active from t=0, preventing the first ~5s "
            "from escaping cleanup."
        ),
        "v0.12.1_red_block": (
            "Saturation alone can no longer select the icon cleanup mask. "
            "Colored/bright pixels also need local foreground contrast, "
            "reducing red-background block artifacts."
        ),
        "v0.12.1_diagonal": (
            "Diagonal tiled watermark removal remains parked. Optional "
            "diagonal_brand_cover uses the calibrated tiled grid to overlay "
            "own-brand labels with a soft backing plate."
        ),
        "v0.12.1_end_card_absent": (
            "When there is no competitor end_card_replace action, the full "
            "source ending is preserved and own End Card can be appended."
        ),
    }

    report_rel = (
        result.get(
            "report_relative_path"
        )
    )

    if report_rel:
        _safe_workspace_path(
            report_rel
        ).write_text(
            json.dumps(
                result,
                ensure_ascii=False,
                indent=2,
            ),
            encoding="utf-8",
        )

    return result




# ---------------------------------------------------------------------------
# v0.12.2 Top Icon Cover — no icon inpaint
#
# Repeated colored-block artifacts proved that inpainting the adjacent icon ROI
# is not robust enough across scene colors/textures.
#
# New production rule:
#   competitor wordmark text -> local cleanup/inpaint (already visually useful)
#   competitor leading icon -> direct own-brand cover
#
# If own logo/icon asset exists:
#   overlay that transparent asset over the competitor icon area.
#
# If no asset exists:
#   draw a compact neutral placeholder badge with the first brand character.
#
# The icon region is NEVER inpainted in default mode.
# ---------------------------------------------------------------------------


class BrandingReplacementRenderRequest(BaseModel):
    replacement_plan_relative_path: str

    include_review_actions: bool = True
    allow_placeholder_assets: bool = True

    watermark_treatment_mode: str = "rebrand_fixed_clean_dynamic"
    compose_top_brand_layers: bool = True
    top_brand_span_guard_seconds: float = 1.75

    top_fixed_bootstrap_to_zero: bool = True
    top_fixed_bootstrap_max_first_evidence_seconds: float = 8.0

    top_brand_icon_pad_ratio: float = 0.85
    top_brand_opposite_pad_ratio: float = 0.12
    top_brand_vertical_pad_ratio: float = 0.10

    # Kept for backward-compatible request payloads but no longer used by the
    # default icon treatment.
    top_icon_saliency_threshold: float = 24.0
    top_icon_saturation_threshold: float = 58.0
    top_icon_bright_threshold: float = 205.0
    top_icon_mask_dilate_pixels: int = 2

    # New default: cover competitor icon, do not inpaint it.
    top_icon_treatment_mode: str = "cover"
    top_icon_cover_scale_ratio: float = 0.86
    top_icon_placeholder_badge: bool = True
    top_icon_placeholder_alpha: float = 0.90

    top_brand_mode: str = "auto"

    mid_promo_transition_guard_frames: int = 4
    mid_promo_auto_transition_scan: bool = True
    mid_promo_transition_scan_seconds: float = 0.30
    mid_promo_transition_score_multiplier: float = 1.65
    mid_promo_transition_max_extra_frames: int = 8

    diagonal_brand_cover_enabled: bool = False
    diagonal_brand_cover_text: Optional[str] = None
    diagonal_brand_cover_angle_degrees: float = 0.0
    diagonal_brand_cover_text_alpha: float = 1.0
    diagonal_brand_cover_plate_alpha: float = 1.0
    diagonal_brand_cover_scale_ratio: float = 0.72
    diagonal_brand_cover_max_points: int = 30

    append_own_end_card_when_absent: bool = True

    placeholder_mid_promo_seconds: float = 3.0
    placeholder_end_card_seconds: float = 3.0

    crf: int = 15
    preset: str = "slow"
    audio_sample_rate: int = 48000
    audio_channels: int = 2
    audio_bitrate: str = "160k"

    keep_intermediate_files: bool = False
    diagonal_brand_cover_router_report_relative_path: Optional[str] = None


def _overlay_asset_fit_bbox(
    frame,
    asset,
    bbox,
    scale_ratio=0.86,
):
    if asset is None:
        return frame

    h, w = frame.shape[:2]

    b = _clip_bbox(
        bbox,
        w,
        h,
    )

    target_h = max(
        12,
        int(round(
            b["height"]
            * float(scale_ratio)
        )),
    )

    ih, iw = asset.shape[:2]

    target_w = max(
        1,
        int(round(
            iw
            * target_h
            / float(
                max(
                    1,
                    ih,
                )
            )
        )),
    )

    # Cap width to the icon-side region, but keep aspect ratio.
    max_w = max(
        12,
        int(round(
            b["width"] * 0.96
        )),
    )

    if target_w > max_w:
        ratio = (
            max_w
            / float(target_w)
        )
        target_w = max_w
        target_h = max(
            1,
            int(round(
                target_h * ratio
            )),
        )

    x = int(round(
        b["x"]
        + (
            b["width"]
            - target_w
        )
        / 2.0
    ))

    y = int(round(
        b["y"]
        + (
            b["height"]
            - target_h
        )
        / 2.0
    ))

    return _alpha_overlay_image(
        frame,
        asset,
        x,
        y,
        target_h,
    )


def _draw_placeholder_icon_badge(
    frame,
    bbox,
    profile,
    alpha=0.90,
):
    out = frame.copy()
    h, w = out.shape[:2]

    b = _clip_bbox(
        bbox,
        w,
        h,
    )

    size = max(
        14,
        int(round(
            min(
                b["width"],
                b["height"],
            )
            * 0.86
        )),
    )

    cx = int(round(
        b["x"]
        + b["width"] / 2.0
    ))

    cy = int(round(
        b["y"]
        + b["height"] / 2.0
    ))

    x1 = max(
        0,
        cx - size // 2,
    )
    y1 = max(
        0,
        cy - size // 2,
    )
    x2 = min(
        w,
        x1 + size,
    )
    y2 = min(
        h,
        y1 + size,
    )

    overlay = out.copy()

    radius = max(
        3,
        int(round(
            size * 0.18
        )),
    )

    # Rounded-ish compact badge using rectangle + circles.
    cv2.rectangle(
        overlay,
        (
            x1 + radius,
            y1,
        ),
        (
            x2 - radius,
            y2,
        ),
        (
            24,
            24,
            24,
        ),
        -1,
    )

    cv2.rectangle(
        overlay,
        (
            x1,
            y1 + radius,
        ),
        (
            x2,
            y2 - radius,
        ),
        (
            24,
            24,
            24,
        ),
        -1,
    )

    for px, py in (
        (x1 + radius, y1 + radius),
        (x2 - radius, y1 + radius),
        (x1 + radius, y2 - radius),
        (x2 - radius, y2 - radius),
    ):
        cv2.circle(
            overlay,
            (
                int(px),
                int(py),
            ),
            radius,
            (
                24,
                24,
                24,
            ),
            -1,
            cv2.LINE_AA,
        )

    a = max(
        0.0,
        min(
            1.0,
            float(alpha),
        ),
    )

    out = cv2.addWeighted(
        overlay,
        a,
        out,
        1.0 - a,
        0,
    )

    brand = str(
        profile.get(
            "brand_name"
        )
        or profile.get(
            "product_name"
        )
        or "F"
    ).strip()

    char = (
        brand[0].upper()
        if brand
        else "F"
    )

    font = cv2.FONT_HERSHEY_SIMPLEX
    scale = max(
        0.42,
        size / 42.0,
    )
    thickness = max(
        1,
        int(round(
            size / 20.0
        )),
    )

    text_size, _ = cv2.getTextSize(
        char,
        font,
        scale,
        thickness,
    )

    tx = int(round(
        cx
        - text_size[0] / 2.0
    ))

    ty = int(round(
        cy
        + text_size[1] / 2.0
    ))

    cv2.putText(
        out,
        char,
        (
            tx,
            ty,
        ),
        font,
        scale,
        (
            245,
            245,
            245,
        ),
        thickness,
        cv2.LINE_AA,
    )

    return out


def _cover_competitor_icon(
    frame,
    icon_bbox,
    profile,
    req,
):
    assets = (
        profile.get(
            "assets"
        )
        or {}
    )

    own_asset = _load_bgr_asset(
        assets.get(
            "logo_image_relative_path"
        )
        or assets.get(
            "icon_image_relative_path"
        )
    )

    if own_asset is not None:
        return (
            _overlay_asset_fit_bbox(
                frame,
                own_asset,
                icon_bbox,
                float(
                    getattr(
                        req,
                        "top_icon_cover_scale_ratio",
                        0.86,
                    )
                ),
            ),
            "own_asset",
        )

    if bool(
        getattr(
            req,
            "top_icon_placeholder_badge",
            True,
        )
    ):
        return (
            _draw_placeholder_icon_badge(
                frame,
                icon_bbox,
                profile,
                float(
                    getattr(
                        req,
                        "top_icon_placeholder_alpha",
                        0.90,
                    )
                ),
            ),
            "placeholder_badge",
        )

    return frame, "no_cover"


def _apply_top_brand_composition_render(
    frame,
    t,
    top_actions,
    profile,
    width,
    height,
    duration,
    req,
):
    processed = frame.copy()
    applied = []

    if str(getattr(req, "watermark_treatment_mode", "rebrand_fixed_clean_dynamic")).lower() == "blur_only":
        return processed, applied

    if not bool(
        getattr(
            req,
            "compose_top_brand_layers",
            True,
        )
    ):
        return processed, applied

    mode = str(
        getattr(
            req,
            "top_icon_treatment_mode",
            "cover",
        )
        or "cover"
    ).strip().lower()

    for action in (
        top_actions
        or []
    ):
        span = _top_action_span(
            action,
            duration,
            float(
                getattr(
                    req,
                    "top_brand_span_guard_seconds",
                    1.75,
                )
            ),
        )

        if span is None:
            continue

        if not (
            float(
                span["start_seconds"]
            )
            <= float(t)
            <= float(
                span["end_seconds"]
            )
        ):
            continue

        base_bbox = _top_action_bbox_at_time(
            action,
            t,
        )

        if not base_bbox:
            continue

        placement = str(
            action.get(
                "placement"
            )
            or ""
        )

        # Wordmark text cleanup stays as before.
        wordmark_mask = _bbox_rect_mask(
            width,
            height,
            base_bbox,
            padding=1,
        )

        processed = cv2.inpaint(
            processed,
            wordmark_mask,
            3.0,
            cv2.INPAINT_TELEA,
        )

        icon_bbox = _icon_side_bbox(
            base_bbox,
            width,
            height,
            placement,
            float(
                getattr(
                    req,
                    "top_brand_icon_pad_ratio",
                    0.85,
                )
            ),
            float(
                getattr(
                    req,
                    "top_brand_vertical_pad_ratio",
                    0.10,
                )
            ),
        )

        icon_treatment = "none"

        if mode == "cover":
            processed, icon_treatment = (
                _cover_competitor_icon(
                    processed,
                    icon_bbox,
                    profile,
                    req,
                )
            )

        elif mode == "legacy_cleanup":
            # Kept only as an explicit fallback/debug option.
            icon_mask = (
                _selective_icon_foreground_mask(
                    processed,
                    icon_bbox,
                    float(
                        getattr(
                            req,
                            "top_icon_saliency_threshold",
                            24.0,
                        )
                    ),
                    float(
                        getattr(
                            req,
                            "top_icon_saturation_threshold",
                            58.0,
                        )
                    ),
                    float(
                        getattr(
                            req,
                            "top_icon_bright_threshold",
                            205.0,
                        )
                    ),
                    int(
                        getattr(
                            req,
                            "top_icon_mask_dilate_pixels",
                            2,
                        )
                    ),
                )
            )

            if np.count_nonzero(
                icon_mask
            ) > 0:
                processed = cv2.inpaint(
                    processed,
                    icon_mask,
                    2.5,
                    cv2.INPAINT_TELEA,
                )

            icon_treatment = (
                "legacy_selective_inpaint"
            )

        # Draw own brand text in the old wordmark location.
        processed = _draw_clean_brand_mark_mode(
            processed,
            base_bbox,
            profile,
            placement,
            str(
                getattr(
                    req,
                    "top_brand_mode",
                    "auto",
                )
                or "auto"
            ),
        )

        applied.append(
            {
                "action_id": (
                    action.get(
                        "action_id"
                    )
                ),
                "placement": placement,
                "base_bbox": base_bbox,
                "icon_bbox": icon_bbox,
                "icon_treatment": (
                    icon_treatment
                ),
                "span": span,
            }
        )

    return processed, applied


_replacement_render_sync_v0121 = (
    _replacement_render_sync
)


def _replacement_render_sync(
    req: BrandingReplacementRenderRequest
):
    result = (
        _replacement_render_sync_v0121(
            req
        )
    )

    result["version"] = "0.12.2"

    result.setdefault(
        "summary",
        {},
    )[
        "top_icon_default_treatment"
    ] = (
        str(
            req.top_icon_treatment_mode
        )
    )

    result[
        "summary"
    ][
        "top_icon_inpaint_disabled_by_default"
    ] = (
        str(
            req.top_icon_treatment_mode
        ).lower()
        == "cover"
    )

    result["notes"] = {
        **(
            result.get(
                "notes"
            )
            or {}
        ),
        "v0.12.2_icon_policy": (
            "Competitor leading icon is no longer inpainted by default. "
            "It is directly covered by own logo/icon asset; if no asset exists, "
            "a compact placeholder brand badge is used. This eliminates the "
            "scene-color-dependent red block artifact caused by icon inpainting."
        ),
    }

    report_rel = (
        result.get(
            "report_relative_path"
        )
    )

    if report_rel:
        _safe_workspace_path(
            report_rel
        ).write_text(
            json.dumps(
                result,
                ensure_ascii=False,
                indent=2,
            ),
            encoding="utf-8",
        )

    return result




# ---------------------------------------------------------------------------
# v0.12.3 Canonical Top Slot
#
# Problem confirmed by visual QC:
#   - around some scenes, own replacement text changed position/size because
#     rendering followed time-local OCR/mask bboxes
#   - competitor leading red logo could remain visible because icon coverage
#     was sized from those unstable local boxes
#
# New rule:
#   Detection geometry finds the competitor watermark.
#   It does NOT control the appearance of our own brand.
#
#   All retained source frames use:
#       one canonical text slot
#       one canonical icon slot
#       one fixed own-brand font/layout
#
#   Icon slot gets a strong opaque compact cover plate before own logo/icon.
#   No icon background reconstruction/inpaint is used.
# ---------------------------------------------------------------------------


class BrandingReplacementRenderRequest(BaseModel):
    replacement_plan_relative_path: str

    include_review_actions: bool = True
    allow_placeholder_assets: bool = True

    watermark_treatment_mode: str = "rebrand_fixed_clean_dynamic"
    compose_top_brand_layers: bool = True
    top_brand_span_guard_seconds: float = 1.75

    top_fixed_bootstrap_to_zero: bool = True
    top_fixed_bootstrap_max_first_evidence_seconds: float = 8.0

    # Canonical slot construction.
    top_canonical_slot_enabled: bool = True
    top_canonical_width_quantile: float = 0.75
    top_canonical_height_quantile: float = 0.75
    top_canonical_position_quantile: float = 0.50

    # Cleanup area can be slightly larger than the canonical text slot while
    # the OWN brand remains fixed to canonical geometry.
    top_text_cleanup_expand_x_ratio: float = 0.10
    top_text_cleanup_expand_y_ratio: float = 0.08

    # Stable icon slot, relative to canonical text height.
    top_canonical_icon_width_height_ratio: float = 1.10
    top_canonical_icon_gap_height_ratio: float = 0.10

    # Strong icon cover swallows the competitor icon even if it is slightly
    # larger/shifted in a particular shot.
    top_icon_strong_cover_enabled: bool = True
    top_icon_strong_cover_expand_ratio: float = 1.38
    top_icon_cover_plate_alpha: float = 1.0
    top_icon_cover_plate_padding_ratio: float = 0.08
    top_icon_cover_scale_ratio: float = 0.55

    # Backward-compatible fields; default icon strategy no longer uses inpaint.
    top_brand_icon_pad_ratio: float = 0.85
    top_brand_opposite_pad_ratio: float = 0.12
    top_brand_vertical_pad_ratio: float = 0.10
    top_icon_saliency_threshold: float = 24.0
    top_icon_saturation_threshold: float = 58.0
    top_icon_bright_threshold: float = 205.0
    top_icon_mask_dilate_pixels: int = 2

    top_icon_treatment_mode: str = "cover"
    top_icon_placeholder_badge: bool = True
    top_icon_placeholder_alpha: float = 0.92

    # auto / logo_only / icon_text / text_only
    top_brand_mode: str = "auto"

    mid_promo_transition_guard_frames: int = 4
    mid_promo_auto_transition_scan: bool = True
    mid_promo_transition_scan_seconds: float = 0.30
    mid_promo_transition_score_multiplier: float = 1.65
    mid_promo_transition_max_extra_frames: int = 8

    # Moving/transient competitor watermark cover. This is distinct from the
    # faint diagonal tiled watermark, which remains separately controlled.
    dynamic_brand_cover_enabled: bool = False
    dynamic_brand_cover_census_report_relative_path: Optional[str] = None
    # The operator census already contains strict, source-verified moving
    # tracks. A direct replacement render must consume that evidence too;
    # otherwise a plan can record a dynamic watermark while the full renderer
    # quietly produces zero dynamic-cover frames.
    # Detection evidence may be handed to review, but never auto-rendered.
    # Enable only after an operator explicitly approves source-specific tracks.
    dynamic_brand_cover_auto_from_plan: bool = False
    dynamic_brand_cover_require_receipt_equality: bool = True
    dynamic_brand_cover_max_gap_seconds: float = 2.5
    # Dynamic tracking bboxes are wordmark geometry, not banner geometry. Keep
    # the cleanup plate tight; large expansion was the source of whole-region
    # visual cropping in the previous backtest.
    dynamic_brand_cover_expand_ratio: float = 1.08
    dynamic_watermark_blur_sigma: float = Field(default=5.0, ge=0.8, le=32.0)
    faint_watermark_visual_report_relative_path: Optional[str] = None
    faint_watermark_visual_min_score: float = 0.48

    # Optional phase-1 temporal recovery handoff. When enabled, the source
    # dynamic watermark is repaired into an intermediate video first; the
    # normal fixed/top/bottom/diagonal watermark pipeline then processes that
    # intermediate so all watermark treatments are delivered together.
    dynamic_watermark_temporal_recovery_enabled: bool = False
    dynamic_watermark_temporal_recovery_output_dir_relative_path: Optional[str] = None
    dynamic_watermark_temporal_recovery_strength: float = 1.0
    dynamic_watermark_temporal_recovery_keep_intermediate: bool = False

    # Persistent/diagonal competitor watermark cover. This is enabled by
    # default for replacement renders: a source-specific watermark profile is
    # allowed to render only when its geometry has been validated for this exact
    # source; otherwise geometry resolution remains a hard no-op/review result.
    diagonal_brand_cover_enabled: bool = False
    # A persistent overlay can have several independent components (for this
    # source: top-left show logo, top-right FREE ribbon, and centre wordmark).
    # Their normalized bboxes are recovered from a source-specific layout map,
    # never from a generic brand-wide watermark profile.
    persistent_watermark_auto_from_source_layout: bool = True
    persistent_watermark_layout_relative_path: Optional[str] = None
    persistent_watermark_required: bool = True
    diagonal_brand_cover_text: Optional[str] = None
    # Per-source deterministic anchors are used when a persistent watermark is
    # visible but no same-source grid calibration has been stored yet. Values
    # are normalized source-frame bbox geometry and are never reused by stem.
    persistent_watermark_anchor_boxes: list[dict[str, float]] = Field(default_factory=list)
    # Persistent source marks follow the same blur-only delivery policy as
    # dynamic tracks. These legacy patch fields remain transparent so no brand
    # label or solid replacement plate can be reintroduced by an old caller.
    diagonal_brand_cover_angle_degrees: float = 0.0
    diagonal_brand_cover_text_alpha: float = 1.0
    diagonal_brand_cover_plate_alpha: float = 1.0
    diagonal_brand_cover_scale_ratio: float = 0.72
    diagonal_brand_cover_max_points: int = 30
    persistent_watermark_cover_expand_ratio: float = 1.12
    persistent_watermark_blur_sigma: float = Field(default=7.0, ge=0.8, le=32.0)

    append_own_end_card_when_absent: bool = True

    placeholder_mid_promo_seconds: float = 3.0
    placeholder_end_card_seconds: float = 3.0

    # Fast default for the full-frame compositor; callers can still override
    # these fields for archival encodes.
    crf: int = 18
    preset: str = "veryfast"
    audio_sample_rate: int = 48000
    audio_channels: int = 2
    audio_bitrate: str = "160k"

    keep_intermediate_files: bool = False
    diagonal_brand_cover_router_report_relative_path: Optional[str] = None


def _quantile(values, q, fallback=0.0):
    clean = []

    for value in values:
        try:
            clean.append(
                float(value)
            )
        except Exception:
            pass

    if not clean:
        return float(fallback)

    q = max(
        0.0,
        min(
            1.0,
            float(q),
        ),
    )

    return float(
        np.quantile(
            np.asarray(
                clean,
                dtype=np.float32,
            ),
            q,
        )
    )


def _collect_top_action_bboxes(
    action,
    width,
    height,
):
    boxes = []

    if action.get(
        "bbox"
    ):
        try:
            boxes.append(
                _clip_bbox(
                    action["bbox"],
                    int(width),
                    int(height),
                )
            )
        except Exception:
            pass

    for segment in (
        action.get(
            "active_segments"
        )
        or []
    ):
        bbox = segment.get(
            "bbox"
        )

        if not bbox:
            continue

        try:
            boxes.append(
                _clip_bbox(
                    bbox,
                    int(width),
                    int(height),
                )
            )
        except Exception:
            pass

    # De-duplicate exact geometry so a repeated action bbox does not dominate
    # the robust statistics.
    unique = []
    seen = set()

    for b in boxes:
        key = (
            int(b["x"]),
            int(b["y"]),
            int(b["width"]),
            int(b["height"]),
        )

        if key in seen:
            continue

        seen.add(key)
        unique.append(b)

    return unique


def _canonical_top_text_slot(
    action,
    width,
    height,
    req,
):
    boxes = _collect_top_action_bboxes(
        action,
        width,
        height,
    )

    if not boxes:
        return None

    placement = str(
        action.get(
            "placement"
        )
        or ""
    )

    width_q = _quantile(
        [
            b["width"]
            for b in boxes
        ],
        getattr(
            req,
            "top_canonical_width_quantile",
            0.75,
        ),
        boxes[0]["width"],
    )

    height_q = _quantile(
        [
            b["height"]
            for b in boxes
        ],
        getattr(
            req,
            "top_canonical_height_quantile",
            0.75,
        ),
        boxes[0]["height"],
    )

    pos_q = float(
        getattr(
            req,
            "top_canonical_position_quantile",
            0.50,
        )
    )

    y = _quantile(
        [
            b["y"]
            for b in boxes
        ],
        pos_q,
        boxes[0]["y"],
    )

    # Anchor to the stable outer screen edge instead of local x.
    if placement.endswith(
        "_right"
    ):
        right = _quantile(
            [
                b["x"]
                + b["width"]
                for b in boxes
            ],
            pos_q,
            boxes[0]["x"]
            + boxes[0]["width"],
        )

        x = right - width_q

    elif placement.endswith(
        "_left"
    ):
        x = _quantile(
            [
                b["x"]
                for b in boxes
            ],
            pos_q,
            boxes[0]["x"],
        )

    else:
        center_x = _quantile(
            [
                b["x"]
                + b["width"] / 2.0
                for b in boxes
            ],
            pos_q,
            boxes[0]["x"]
            + boxes[0]["width"] / 2.0,
        )

        x = center_x - width_q / 2.0

    slot = _clip_bbox(
        {
            "x": int(round(x)),
            "y": int(round(y)),
            "width": max(
                1,
                int(round(width_q)),
            ),
            "height": max(
                1,
                int(round(height_q)),
            ),
        },
        int(width),
        int(height),
    )

    return slot


def _canonical_top_icon_slot(
    text_slot,
    placement,
    width,
    height,
    req,
):
    if not text_slot:
        return None

    th = max(
        1,
        int(
            text_slot["height"]
        ),
    )

    icon_w = max(
        18,
        int(round(
            th
            * float(
                getattr(
                    req,
                    "top_canonical_icon_width_height_ratio",
                    1.10,
                )
            )
        )),
    )

    gap = max(
        2,
        int(round(
            th
            * float(
                getattr(
                    req,
                    "top_canonical_icon_gap_height_ratio",
                    0.10,
                )
            )
        )),
    )

    icon_h = max(
        18,
        int(round(
            th * 1.04
        )),
    )

    cy = (
        int(text_slot["y"])
        + int(text_slot["height"])
        / 2.0
    )

    y = int(round(
        cy - icon_h / 2.0
    ))

    placement = str(
        placement
        or ""
    )

    if placement.endswith(
        "_right"
    ):
        x = (
            int(text_slot["x"])
            - gap
            - icon_w
        )
    elif placement.endswith(
        "_left"
    ):
        x = (
            int(text_slot["x"])
            + int(text_slot["width"])
            + gap
        )
    else:
        x = (
            int(text_slot["x"])
            - gap
            - icon_w
        )

    return _clip_bbox(
        {
            "x": int(x),
            "y": int(y),
            "width": int(icon_w),
            "height": int(icon_h),
        },
        int(width),
        int(height),
    )


def _expand_bbox_ratio(
    bbox,
    width,
    height,
    expand_x_ratio,
    expand_y_ratio,
):
    b = _clip_bbox(
        bbox,
        int(width),
        int(height),
    )

    dx = int(round(
        b["width"]
        * float(expand_x_ratio)
    ))

    dy = int(round(
        b["height"]
        * float(expand_y_ratio)
    ))

    return _clip_bbox(
        {
            "x": int(
                b["x"]
                - dx
            ),
            "y": int(
                b["y"]
                - dy
            ),
            "width": int(
                b["width"]
                + dx * 2
            ),
            "height": int(
                b["height"]
                + dy * 2
            ),
        },
        int(width),
        int(height),
    )


def _strong_icon_cover_bbox(
    icon_slot,
    width,
    height,
    req,
):
    b = _clip_bbox(
        icon_slot,
        int(width),
        int(height),
    )

    ratio = max(
        1.0,
        float(
            getattr(
                req,
                "top_icon_strong_cover_expand_ratio",
                1.38,
            )
        ),
    )

    cx = (
        b["x"]
        + b["width"] / 2.0
    )

    cy = (
        b["y"]
        + b["height"] / 2.0
    )

    nw = max(
        1,
        int(round(
            b["width"]
            * ratio
        )),
    )

    nh = max(
        1,
        int(round(
            b["height"]
            * ratio
        )),
    )

    return _clip_bbox(
        {
            "x": int(round(
                cx - nw / 2.0
            )),
            "y": int(round(
                cy - nh / 2.0
            )),
            "width": int(nw),
            "height": int(nh),
        },
        int(width),
        int(height),
    )


def _draw_opaque_icon_plate(
    frame,
    bbox,
    alpha=1.0,
    padding_ratio=0.08,
):
    # Production uses alpha=1.0. Mutate the current frame in place so the
    # per-frame renderer does not allocate another full-resolution copy before
    # the small rounded cover plate is drawn.
    out = frame

    h, w = out.shape[:2]

    b = _clip_bbox(
        bbox,
        w,
        h,
    )

    pad = max(
        1,
        int(round(
            min(
                b["width"],
                b["height"],
            )
            * float(
                padding_ratio
            )
        )),
    )

    x1 = max(
        0,
        int(b["x"]) - pad,
    )
    y1 = max(
        0,
        int(b["y"]) - pad,
    )
    x2 = min(
        w,
        int(
            b["x"]
            + b["width"]
        )
        + pad,
    )
    y2 = min(
        h,
        int(
            b["y"]
            + b["height"]
        )
        + pad,
    )

    if (
        x2 <= x1
        or y2 <= y1
    ):
        return out

    overlay = out.copy()

    radius = max(
        3,
        int(round(
            min(
                x2 - x1,
                y2 - y1,
            )
            * 0.20
        )),
    )

    # Compact rounded dark plate. The key is opacity: it must fully hide the
    # competitor red icon instead of relying on transparent own artwork.
    if float(alpha) >= 0.999:
        cv2.rectangle(
            out,
            (x1 + radius, y1),
            (x2 - radius, y2),
            (20, 20, 20),
            -1,
        )
        cv2.rectangle(
            out,
            (x1, y1 + radius),
            (x2, y2 - radius),
            (20, 20, 20),
            -1,
        )
        for px, py in (
            (x1 + radius, y1 + radius),
            (x2 - radius, y1 + radius),
            (x1 + radius, y2 - radius),
            (x2 - radius, y2 - radius),
        ):
            cv2.circle(out, (int(px), int(py)), radius, (20, 20, 20), -1, cv2.LINE_AA)
        return out

    cv2.rectangle(
        overlay,
        (
            x1 + radius,
            y1,
        ),
        (
            x2 - radius,
            y2,
        ),
        (
            20,
            20,
            20,
        ),
        -1,
    )

    cv2.rectangle(
        overlay,
        (
            x1,
            y1 + radius,
        ),
        (
            x2,
            y2 - radius,
        ),
        (
            20,
            20,
            20,
        ),
        -1,
    )

    for px, py in (
        (x1 + radius, y1 + radius),
        (x2 - radius, y1 + radius),
        (x1 + radius, y2 - radius),
        (x2 - radius, y2 - radius),
    ):
        cv2.circle(
            overlay,
            (
                int(px),
                int(py),
            ),
            radius,
            (
                20,
                20,
                20,
            ),
            -1,
            cv2.LINE_AA,
        )

    a = max(
        0.0,
        min(
            1.0,
            float(alpha),
        ),
    )

    if a >= 0.999:
        out[
            y1:y2,
            x1:x2,
        ] = overlay[
            y1:y2,
            x1:x2,
        ]
    else:
        out = cv2.addWeighted(
            overlay,
            a,
            out,
            1.0 - a,
            0,
        )

    return out


def _draw_canonical_brand_text(
    frame,
    text_slot,
    profile,
    placement,
    req,
):
    mode = str(
        getattr(
            req,
            "top_brand_mode",
            "auto",
        )
        or "auto"
    ).lower()

    # logo_only intentionally suppresses text.
    if mode == "logo_only":
        return frame

    # Production top slot is icon + PRODUCT NAME.
    # brand_name remains only a fallback for old profiles.
    brand_text = str(
        profile.get(
            "product_name"
        )
        or profile.get(
            "brand_name"
        )
        or ""
    ).strip()

    if not brand_text:
        return frame

    out = frame
    h, w = out.shape[:2]
    cache = getattr(req, "_operator_render_asset_cache", None)
    if not isinstance(cache, dict):
        cache = {}
        setattr(req, "_operator_render_asset_cache", cache)

    b = _clip_bbox(text_slot, w, h)
    placement = str(placement or "")
    text_key = (
        brand_text, placement, int(b["x"]), int(b["y"]),
        int(b["width"]), int(b["height"]),
    )
    prepared = cache.get(("brand_text", text_key))
    if prepared is None:
        font = cv2.FONT_HERSHEY_SIMPLEX
        scale = max(0.36, float(b["height"]) / 38.0)
        thickness = max(1, int(round(b["height"] / 30.0)))
        text_size, _ = cv2.getTextSize(brand_text, font, scale, thickness)
        max_text_w = max(20, int(b["width"] * 0.96))
        if text_size[0] > max_text_w:
            scale = max(0.30, scale * max_text_w / float(max(1, text_size[0])))
            text_size, _ = cv2.getTextSize(brand_text, font, scale, thickness)
        tx = int(b["x"] + b["width"] - text_size[0]) if placement.endswith("_right") else int(b["x"])
        ty = min(h - 4, max(text_size[1] + 3, int(round(b["y"] + (b["height"] + text_size[1]) / 2.0))))
        prepared = {"font": font, "scale": scale, "thickness": thickness, "tx": tx, "ty": ty}
        cache[("brand_text", text_key)] = prepared

    font = prepared["font"]
    scale = prepared["scale"]
    thickness = prepared["thickness"]
    tx = prepared["tx"]
    ty = prepared["ty"]

    # Fixed shadow/stroke gives consistent appearance across all scenes.
    cv2.putText(
        out,
        brand_text,
        (
            tx + 1,
            ty + 2,
        ),
        font,
        scale,
        (
            0,
            0,
            0,
        ),
        thickness + 2,
        cv2.LINE_AA,
    )

    cv2.putText(
        out,
        brand_text,
        (
            tx,
            ty,
        ),
        font,
        scale,
        (
            245,
            245,
            245,
        ),
        thickness,
        cv2.LINE_AA,
    )

    return out


def _draw_icon_into_canonical_slot(
    frame,
    icon_slot,
    profile,
    req,
):
    out = frame

    assets = (
        profile.get(
            "assets"
        )
        or {}
    )

    # The static own icon/logo is reused on every frame. Cache only decoded
    # image data on the in-memory request object; no profile or source artifact
    # is changed, and the cache disappears with the render request.
    cache = getattr(req, "_operator_render_asset_cache", None)
    if not isinstance(cache, dict):
        cache = {}
        setattr(req, "_operator_render_asset_cache", cache)

    icon_relative_path = (
        assets.get(
            "icon_image_relative_path"
        )
    )

    logo_relative_path = (
        assets.get(
            "logo_image_relative_path"
        )
    )

    own_asset_kind = None
    own_asset = None

    if icon_relative_path:
        cache_key = ("icon", str(icon_relative_path))
        own_asset = cache.get(cache_key)
        if own_asset is None:
            own_asset = _load_bgr_asset(icon_relative_path)
            if own_asset is not None:
                cache[cache_key] = own_asset

        if own_asset is not None:
            own_asset_kind = (
                "own_icon_asset"
            )

    if (
        own_asset is None
        and logo_relative_path
    ):
        cache_key = ("logo", str(logo_relative_path))
        own_asset = cache.get(cache_key)
        if own_asset is None:
            own_asset = _load_bgr_asset(logo_relative_path)
            if own_asset is not None:
                cache[cache_key] = own_asset

        if own_asset is not None:
            own_asset_kind = (
                "own_logo_asset_fallback"
            )

    if own_asset is not None:
        scale_ratio = float(
            getattr(req, "top_icon_cover_scale_ratio", 0.72)
        )
        slot_key = (
            int(icon_slot.get("x") or 0),
            int(icon_slot.get("y") or 0),
            int(icon_slot.get("width") or 0),
            int(icon_slot.get("height") or 0),
            round(scale_ratio, 4),
            own_asset_kind,
        )
        prepared = cache.get(("icon_prepared", slot_key))
        if prepared is None:
            b = _clip_bbox(icon_slot, out.shape[1], out.shape[0])
            target_h = max(12, int(round(b["height"] * scale_ratio)))
            source_h, source_w = own_asset.shape[:2]
            target_w = max(1, int(round(source_w * target_h / float(max(1, source_h)))))
            max_w = max(12, int(round(b["width"] * 0.96)))
            if target_w > max_w:
                ratio = max_w / float(target_w)
                target_w = max_w
                target_h = max(1, int(round(target_h * ratio)))
            prepared = {
                "asset": cv2.resize(own_asset, (target_w, target_h), interpolation=cv2.INTER_AREA),
                "x": int(round(b["x"] + (b["width"] - target_w) / 2.0)),
                "y": int(round(b["y"] + (b["height"] - target_h) / 2.0)),
                "height": target_h,
            }
            cache[("icon_prepared", slot_key)] = prepared
        out = _alpha_overlay_image(
            out,
            prepared["asset"],
            prepared["x"],
            prepared["y"],
            prepared["height"],
        )

        return (
            out,
            own_asset_kind
            or "own_asset",
        )

    if bool(
        getattr(
            req,
            "top_icon_placeholder_badge",
            True,
        )
    ):
        # Plate is already present. Put a simple brand initial in the canonical
        # icon slot without creating a second badge background.
        brand = str(
            profile.get(
                "brand_name"
            )
            or profile.get(
                "product_name"
            )
            or "F"
        ).strip()

        char = (
            brand[0].upper()
            if brand
            else "F"
        )

        h, w = out.shape[:2]

        b = _clip_bbox(
            icon_slot,
            w,
            h,
        )

        font = cv2.FONT_HERSHEY_SIMPLEX
        scale = max(
            0.40,
            min(
                b["width"],
                b["height"],
            )
            / 42.0,
        )

        thickness = max(
            1,
            int(round(
                min(
                    b["width"],
                    b["height"],
                )
                / 22.0
            )),
        )

        size, _ = cv2.getTextSize(
            char,
            font,
            scale,
            thickness,
        )

        tx = int(round(
            b["x"]
            + (
                b["width"]
                - size[0]
            )
            / 2.0
        ))

        ty = int(round(
            b["y"]
            + (
                b["height"]
                + size[1]
            )
            / 2.0
        ))

        cv2.putText(
            out,
            char,
            (
                tx,
                ty,
            ),
            font,
            scale,
            (
                245,
                245,
                245,
            ),
            thickness,
            cv2.LINE_AA,
        )

        return out, "placeholder_initial"

    return out, "plate_only"


def _top_action_span_v0123(
    action,
    duration,
    req,
):
    segments = (
        action.get(
            "active_segments"
        )
        or []
    )

    starts = []
    ends = []

    for segment in segments:
        try:
            starts.append(
                float(
                    segment[
                        "start_seconds"
                    ]
                )
            )
            ends.append(
                float(
                    segment[
                        "end_seconds"
                    ]
                )
            )
        except Exception:
            continue

    if not starts or not ends:
        # Legacy fixed-layer plans may carry the accepted geometry without
        # per-segment receipts. Treat such a top fixed action as persistent;
        # otherwise the final compositor emits an untouched source watermark.
        if action.get("bbox") and _operator_fixed_action_vertical_zone(action) == "top":
            return {
                "start_seconds": 0.0,
                "end_seconds": round(max(0.0, float(duration or 0.0)), 3),
                "source": "fixed_action_without_segment_receipts_full_duration",
            }
        return None

    first_evidence = min(
        starts
    )

    if (
        bool(
            getattr(
                req,
                "top_fixed_bootstrap_to_zero",
                True,
            )
        )
        and first_evidence
        <= float(
            getattr(
                req,
                "top_fixed_bootstrap_max_first_evidence_seconds",
                8.0,
            )
        )
    ):
        start = 0.0
        start_source = (
            "fixed_early_evidence_bootstrap_to_zero"
        )
    else:
        start = max(
            0.0,
            first_evidence
            - float(
                getattr(
                    req,
                    "top_brand_span_guard_seconds",
                    1.75,
                )
            ),
        )
        start_source = (
            "first_evidence_minus_guard"
        )

    end = max(
        ends
    ) + float(
        getattr(
            req,
            "top_brand_span_guard_seconds",
            1.75,
        )
    )

    if duration > 0:
        end = min(
            float(duration),
            end,
        )

    return {
        "start_seconds": round(
            start,
            3,
        ),
        "end_seconds": round(
            end,
            3,
        ),
        "first_evidence_seconds": round(
            first_evidence,
            3,
        ),
        "source": start_source,
    }


def _apply_top_brand_composition_render(
    frame,
    t,
    top_actions,
    profile,
    width,
    height,
    duration,
    req,
):
    processed = frame.copy()
    applied = []

    if str(getattr(req, "watermark_treatment_mode", "rebrand_fixed_clean_dynamic")).lower() == "blur_only":
        for action in top_actions or []:
            span = _top_action_span_v0123(action, duration, req)
            if span is None or not float(span["start_seconds"]) <= float(t) <= float(span["end_seconds"]):
                continue
            bbox = _top_action_bbox_at_time(action, t)
            if not bbox:
                continue
            processed = _operator_apply_feathered_local_blur(
                processed,
                bbox,
                float(getattr(req, "persistent_watermark_blur_sigma", 7.0)),
            )
            applied.append(
                {
                    "action_id": action.get("action_id"),
                    "bbox": bbox,
                    "treatment": "feathered_gaussian_blur",
                    "own_brand_overlay": False,
                }
            )
        return processed, applied

    if not bool(
        getattr(
            req,
            "compose_top_brand_layers",
            True,
        )
    ):
        return processed, applied

    for action in (
        top_actions
        or []
    ):
        span = _top_action_span_v0123(
            action,
            duration,
            req,
        )

        if span is None:
            continue

        if not (
            float(
                span[
                    "start_seconds"
                ]
            )
            <= float(t)
            <= float(
                span[
                    "end_seconds"
                ]
            )
        ):
            continue

        base_bbox = _top_action_bbox_at_time(action, t)
        if not base_bbox:
            continue

        placement = str(action.get("placement") or "")

        # The fixed-watermark renderer must use the same canonical icon/text
        # path as the production contract.  This function is the final
        # definition in this module and previously regressed to an older
        # wordmark-only implementation: it drew a logo opportunistically but
        # never rendered (or receipted) the configured icon asset.  That made a
        # technically valid MP4 fail the business QC as "competitor-brand
        # treatment was not actually rendered".
        text_slot = action.get("_operator_canonical_text_slot")
        if not text_slot:
            text_slot = _canonical_top_text_slot(action, width, height, req)
            if text_slot:
                action["_operator_canonical_text_slot"] = text_slot
        if not text_slot:
            # A malformed action must not be reported as treated.  The caller's
            # zero-frame QC receipt will safely reject it.
            continue

        icon_slot = action.get("_operator_canonical_icon_slot")
        if not icon_slot:
            icon_slot = _canonical_top_icon_slot(
                text_slot,
                placement,
                width,
                height,
                req,
            )
            if icon_slot:
                action["_operator_canonical_icon_slot"] = icon_slot
        if not icon_slot:
            continue

        # Reconstruct only the observed source wordmark footprint.  The icon
        # gets a deliberately opaque own-brand plate below, which guarantees the
        # competitor mark cannot bleed through transparent artwork.
        cleanup_bbox = _expand_bbox_ratio(
            base_bbox,
            width,
            height,
            float(getattr(req, "top_text_cleanup_expand_x_ratio", 0.10)),
            float(getattr(req, "top_text_cleanup_expand_y_ratio", 0.08)),
        )
        processed = _operator_inpaint_bbox_fast(
            processed,
            cleanup_bbox,
            padding=2,
            radius=3.0,
        )

        icon_cover_bbox = _strong_icon_cover_bbox(
            icon_slot,
            width,
            height,
            req,
        )
        if bool(getattr(req, "top_icon_strong_cover_enabled", True)):
            processed = _draw_opaque_icon_plate(
                processed,
                icon_cover_bbox,
                float(getattr(req, "top_icon_cover_plate_alpha", 1.0)),
                float(getattr(req, "top_icon_cover_plate_padding_ratio", 0.08)),
            )

        processed, icon_treatment = _draw_icon_into_canonical_slot(
            processed,
            icon_slot,
            profile,
            req,
        )
        processed = _draw_canonical_brand_text(
            processed,
            text_slot,
            profile,
            placement,
            req,
        )

        applied.append(
            {
                "action_id": (
                    action.get(
                        "action_id"
                    )
                ),
                "placement": (
                    placement
                ),
                "span": (
                    span
                ),
                "base_bbox": base_bbox,
                "cleanup_bbox": cleanup_bbox,
                "canonical_text_slot": text_slot,
                "icon_bbox": icon_slot,
                "icon_cover_bbox": icon_cover_bbox,
                "icon_treatment": icon_treatment,
                "treatment": "source_cleanup_then_own_brand",
                "canonical_layout": True,
            }
        )

    return processed, applied


_replacement_render_sync_v0122 = (
    _replacement_render_sync
)


def _replacement_render_sync(
    req: BrandingReplacementRenderRequest
):
    # Connect the planner's authoritative census evidence to direct renders.
    # The operator flow supplied these fields explicitly, but /replacement-render
    # callers only supplied a plan and consequently emitted a valid MP4 with
    # zero dynamic-cover frames despite verified dynamic tracks in the census.
    plan_path, plan = _read_json_workspace(
        req.replacement_plan_relative_path,
        "replacement_render_dynamic_handoff",
    )
    plan_summary = plan.get("summary") or {}
    temporal_handoff = None
    original_source_rel = str(((plan.get("source") or {}).get("relative_path") or "")).strip()
    # Temporal repair is meaningful only when the plan/census has a verified
    # moving-watermark trajectory. Production Candidate used to invoke it for
    # every source, including clean sources with zero tracks. That necessarily
    # produced an empty residual QA report, which was then misclassified as a
    # hard repair failure and blocked the entire edit.
    preflight_dynamic_tracks = max(
        0,
        int(plan_summary.get("operator_dynamic_brand_expected_track_count") or 0),
    )
    if preflight_dynamic_tracks <= 0:
        preflight_census_rel = str(
            ((plan.get("source") or {}).get("router_report_relative_path") or "")
        ).strip()
        try:
            if preflight_census_rel:
                _, preflight_router = _read_json_workspace(
                    preflight_census_rel,
                    "replacement_render_dynamic_preflight",
                )
                preflight_census_rel = str(
                    ((preflight_router.get("evidence_reports") or {}).get("census") or "")
                ).strip()
            if preflight_census_rel:
                _, preflight_census = _read_json_workspace(
                    preflight_census_rel,
                    "replacement_render_dynamic_preflight",
                )
                strict = preflight_census.get("verified_dynamic_identity") or {}
                if bool(strict.get("enabled")):
                    preflight_dynamic_tracks = len(strict.get("tracks") or [])
        except Exception:
            # The later normal renderer preflight still handles unreadable
            # reports. Do not turn optional temporal diagnostics into a false
            # source-video failure here.
            preflight_dynamic_tracks = 0

    # Resolve the census path independently of the derived summary count.  A
    # plan may already contain ``operator_dynamic_brand_expected_track_count``
    # and therefore skip the old preflight block above; it still must hand the
    # original strict trajectories to the temporal repair worker.
    authoritative_census_rel = str(
        ((plan.get("source") or {}).get("router_report_relative_path") or "")
    ).strip()
    try:
        if authoritative_census_rel:
            _, authoritative_router = _read_json_workspace(
                authoritative_census_rel,
                "replacement_render_authoritative_temporal_tracks",
            )
            # API callers may provide either the router report or the census
            # report directly.  Do not erase the latter while resolving it.
            if not (authoritative_router.get("verified_dynamic_identity") or {}).get("tracks"):
                authoritative_census_rel = str(
                    ((authoritative_router.get("evidence_reports") or {}).get("census") or "")
                ).strip()
    except Exception:
        authoritative_census_rel = ""
    authoritative_temporal_tracks = _operator_temporal_tracks_from_census(
        authoritative_census_rel
    )

    if (
        bool(getattr(req, "dynamic_watermark_temporal_recovery_enabled", False))
        and original_source_rel
        and preflight_dynamic_tracks > 0
    ):
        # Run the dynamic-watermark temporal stage before the canonical
        # fixed/top/bottom/diagonal compositor. The compositor then sees one
        # intermediate source and produces a single combined output.
        try:
            from .branding_moving_watermark_insight import (
                DynamicWatermarkTemporalRepairRequest,
                dynamic_watermark_temporal_repair_sync,
            )
        except ImportError:  # pragma: no cover
            from branding_moving_watermark_insight import (
                DynamicWatermarkTemporalRepairRequest,
                dynamic_watermark_temporal_repair_sync,
            )
        # The production candidate plan predates source-identity persistence
        # and therefore often contains only the source path.  The preflight
        # census, however, was already run with the product-bound icon/logo
        # template.  Resolve that same identity here before invoking temporal
        # repair; otherwise the repair silently falls back to the generic
        # ReelShort crop and returns zero tracks / unverifiable residuals.
        source_identity = dict(
            (plan.get("source") or {}).get("source_identity")
            or plan.get("source_identity")
            or {}
        )
        if not source_identity or not source_identity.get("icon_relative_path"):
            try:
                source_path_for_identity = _safe_workspace_path(
                    original_source_rel, must_exist=True
                )
                sidecar_path = Path(str(source_path_for_identity) + ".metadata.json")
                if sidecar_path.is_file():
                    sidecar = json.loads(sidecar_path.read_text(encoding="utf-8"))
                    diagnostic = sidecar.get("detail_identity_diagnostic") or {}
                    brand_id = (
                        sidecar.get("brand_id")
                        or diagnostic.get("brand_id")
                    )
                    product_name = (
                        sidecar.get("product_name")
                        or sidecar.get("app_title")
                        or diagnostic.get("product_name")
                        or diagnostic.get("app_title")
                    )
                    source_identity = {
                        **source_identity,
                        "brand_id": source_identity.get("brand_id") or brand_id,
                        "product_name": source_identity.get("product_name") or product_name,
                        "app_title": (
                            source_identity.get("app_title")
                            or sidecar.get("app_title")
                            or diagnostic.get("app_title")
                            or product_name
                        ),
                    }
                    profile_rel = diagnostic.get("brand_profile")
                    if profile_rel:
                        profile_path = _safe_workspace_path(
                            profile_rel, must_exist=True
                        )
                        if profile_path.is_file():
                            profile = json.loads(profile_path.read_text(encoding="utf-8"))
                            icon = profile.get("icon") or {}
                            source_identity.setdefault(
                                "icon_relative_path", icon.get("relative_path")
                            )
                            source_identity.setdefault(
                                "logo_relative_path", icon.get("relative_path")
                            )
                            source_identity["brand_id"] = (
                                source_identity.get("brand_id")
                                or profile.get("brand_id")
                            )
                            source_identity["product_name"] = (
                                source_identity.get("product_name")
                                or profile.get("product_name")
                            )
                            source_identity["app_title"] = (
                                source_identity.get("app_title")
                                or profile.get("app_title")
                                or source_identity.get("product_name")
                            )
            except Exception:
                # Identity recovery is an enhancement to the already-created
                # plan.  Keep the normal generic fallback if a sidecar is
                # malformed; do not turn a readable source into a hard error.
                source_identity = source_identity or {}

        temporal_handoff = dynamic_watermark_temporal_repair_sync(
            DynamicWatermarkTemporalRepairRequest(
                relative_path=original_source_rel,
                competitor_name=str(
                    source_identity.get("product_name")
                    or (plan.get("source") or {}).get("competitor_name")
                    or "ReelShort"
                ),
                source_brand_id=str(source_identity.get("brand_id") or "") or None,
                source_product_name=str(source_identity.get("product_name") or "") or None,
                source_app_title=str(source_identity.get("app_title") or "") or None,
                source_icon_relative_path=source_identity.get("icon_relative_path"),
                source_logo_relative_path=source_identity.get("logo_relative_path"),
                recovery_strength=float(getattr(req, "dynamic_watermark_temporal_recovery_strength", 1.0)),
                # ProPainter is optional on the CPU/MX250 deployment.  The
                # local trajectory clean-plate backend remains explicit in
                # the report and is accepted only when residual QA passes;
                # operators can require ProPainter via the environment flag.
                require_propainter=str(os.getenv("DYNAMIC_WATERMARK_REQUIRE_PROPAINTER", "0")).strip().lower()
                in {"1", "true", "yes", "on"},
                verified_tracks=authoritative_temporal_tracks,
                verified_tracks_source=authoritative_census_rel or None,
                qa_excluded_intervals=[
                    (float(action.get("start_seconds", 0.0)), float(action.get("end_seconds", 0.0)))
                    for action in (plan.get("actions") or [])
                    if action.get("type") in {"mid_promo_replace", "end_card_replace"}
                    and float(action.get("end_seconds", 0.0)) >= float(action.get("start_seconds", 0.0))
                ],
                output_dir_relative_path=getattr(req, "dynamic_watermark_temporal_recovery_output_dir_relative_path", None),
            )
        )
        temporal_output_rel = str(((temporal_handoff.get("output") or {}).get("output_relative_path") or "")).strip()
        if temporal_output_rel:
            import copy
            plan = copy.deepcopy(plan)
            plan.setdefault("source", {})["original_relative_path"] = original_source_rel
            plan["source"]["relative_path"] = temporal_output_rel
            temp_plan_path = _safe_workspace_path(
                "review/dynamic_watermark_temporal_repair/combined-render-plan.json",
                must_exist=False,
            )
            temp_plan_path.parent.mkdir(parents=True, exist_ok=True)
            temp_plan_path.write_text(json.dumps(plan, ensure_ascii=False, indent=2), encoding="utf-8")
            req = req.model_copy(deep=True)
            req.replacement_plan_relative_path = str(temp_plan_path.relative_to(WORKSPACE)).replace("\\", "/")
            # The temporal stage handles the source dynamic mark; do not apply
            # a second in-frame dynamic treatment on the same pixels.
            req.dynamic_brand_cover_enabled = False
            req.dynamic_brand_cover_auto_from_plan = False
            plan_path = temp_plan_path
            plan_summary = plan.get("summary") or {}
            # The dynamic pixels have already been repaired in the temporal
            # intermediate. Keep the original count in a separate audit field
            # but clear the compositor expectation so business QC does not
            # demand a second dynamic-cover pass.
            plan_summary["operator_dynamic_brand_expected_track_count_before_temporal"] = int(
                plan_summary.get("operator_dynamic_brand_expected_track_count") or 0
            )
            plan_summary["operator_dynamic_brand_expected_track_count"] = 0
            plan["summary"] = plan_summary
            temp_plan_path.write_text(
                json.dumps(plan, ensure_ascii=False, indent=2), encoding="utf-8"
            )
            expected_dynamic_tracks = 0
        else:
            raise HTTPException(
                status_code=422,
                detail={
                    "stage": "replacement_render_dynamic_clean_repair",
                    "error": "dynamic_watermark_clean_repair_not_verified",
                    "message": (
                        "The dynamic watermark diagnostic preview did not pass "
                        "residual verification. Rendering is rejected rather than "
                        "falling back to blur or an own-brand overlay."
                    ),
                    "temporal_repair": temporal_handoff,
                },
            )
    elif bool(getattr(req, "dynamic_watermark_temporal_recovery_enabled", False)):
        temporal_handoff = {
            "ok": True,
            "status": "skipped_no_verified_dynamic_tracks",
            "mode": "dynamic_watermark_temporal_clean_repair",
            "source": {"relative_path": original_source_rel},
            "output": None,
            "qa": {
                "status": "not_applicable_no_verified_dynamic_tracks",
                "verified_track_count": 0,
            },
            "notes": [
                "Temporal repair was skipped because the source census contains no verified dynamic watermark tracks.",
                "The original source is retained for the normal fixed-layer and editorial render.",
            ],
        }
    expected_dynamic_tracks = max(
        0,
        int(plan_summary.get("operator_dynamic_brand_expected_track_count") or 0),
    )
    if temporal_handoff and temporal_handoff.get("status") not in {"failed", "encode_failed"}:
        # Dynamic source watermark was already handled by the temporal stage.
        expected_dynamic_tracks = 0
    if expected_dynamic_tracks <= 0:
        # Plans created before the operator summary enrichment can still carry
        # an authoritative router/census reference. Resolve their strict count
        # below rather than treating absence of the derived summary as proof
        # that no moving watermark exists.
        expected_dynamic_tracks = 0
    census_rel = str(
        ((plan.get("source") or {}).get("router_report_relative_path") or "")
    ).strip()
    if census_rel:
        try:
            _, router = _read_json_workspace(
                census_rel,
                "replacement_render_dynamic_handoff",
            )
            census_rel = str(
                ((router.get("evidence_reports") or {}).get("census") or "")
            ).strip()
        except Exception:
            census_rel = ""

    if census_rel and expected_dynamic_tracks <= 0:
        try:
            _, census = _read_json_workspace(
                census_rel,
                "replacement_render_dynamic_handoff",
            )
            strict = census.get("verified_dynamic_identity") or {}
            if bool(strict.get("enabled")):
                expected_dynamic_tracks = len(strict.get("tracks") or [])
        except Exception:
            pass

    if temporal_handoff and temporal_handoff.get("status") == "completed":
        # A verified temporal output has already replaced the dynamic source
        # pixels. Do not re-enable the legacy dynamic compositor from the
        # original plan's census during the second preflight pass.
        expected_dynamic_tracks = 0

    # The source-layout map is deliberately source-specific. It handles the
    # visible persistent overlay components that OCR/identity tracking cannot
    # classify (e.g. non-ReelShort title art, a FREE ribbon and a translucent
    # centre wordmark). Do not reuse a generic diagonal profile for this task.
    if bool(getattr(req, "persistent_watermark_auto_from_source_layout", True)):
        layout_rel = str(
            getattr(req, "persistent_watermark_layout_relative_path", None)
            or "config/persistent_watermark_source_layouts.json"
        ).strip()
        try:
            _, layout_payload = _read_json_workspace(
                layout_rel,
                "replacement_render_persistent_watermark_layout",
            )
            source_rel = str(
                ((plan.get("source") or {}).get("original_relative_path") or
                 (plan.get("source") or {}).get("relative_path") or "")
            ).strip()
            source_layout = (
                (layout_payload.get("sources") or {}).get(source_rel)
                or {}
            )
            anchors = source_layout.get("anchors") or []
            if (
                anchors
                and bool(getattr(req, "persistent_watermark_auto_from_source_layout", True))
                and not list(getattr(req, "persistent_watermark_anchor_boxes", None) or [])
            ):
                req.persistent_watermark_anchor_boxes = list(anchors)
                req.diagonal_brand_cover_enabled = True
                req.persistent_watermark_layout_relative_path = layout_rel
        except Exception:
            pass

    if bool(getattr(req, "dynamic_brand_cover_auto_from_plan", False)) and census_rel:
        if not getattr(req, "dynamic_brand_cover_census_report_relative_path", None):
            req.dynamic_brand_cover_census_report_relative_path = census_rel
        if expected_dynamic_tracks > 0:
            req.dynamic_brand_cover_enabled = True
            # Strict tracks were sampled at this ceiling. Preserve it unless the
            # caller intentionally requested a stricter value.
            req.dynamic_brand_cover_max_gap_seconds = min(
                float(getattr(req, "dynamic_brand_cover_max_gap_seconds", 2.5)),
                0.32,
            )

    # Verified tracks are never allowed to fall through as a review-only count
    # during a render. The production request enables the auto handoff above;
    # a direct caller that deliberately leaves the compositor disabled receives
    # an accurate preflight failure instead of a misleading post-render receipt
    # mismatch (or an incomplete deliverable).
    dynamic_receipt_contract_enabled = bool(
        getattr(req, "dynamic_brand_cover_enabled", False)
        and getattr(req, "dynamic_brand_cover_census_report_relative_path", None)
    )
    if expected_dynamic_tracks > 0 and not bool(
        getattr(req, "dynamic_watermark_temporal_recovery_enabled", False)
    ):
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "replacement_render",
                "error": "dynamic_watermark_clean_repair_required",
                "message": (
                    "Verified moving watermark tracks require temporal clean repair. "
                    "Blur and own-brand overlays are forbidden for dynamic marks."
                ),
            },
        )
    if expected_dynamic_tracks > 0 and not dynamic_receipt_contract_enabled:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "replacement_render",
                "error": "dynamic_watermark_renderer_not_enabled",
                "expected_tracks": expected_dynamic_tracks,
                "message": (
                    "Verified dynamic watermark tracks require the source-specific "
                    "dynamic compositor and census report before rendering. The "
                    "output is rejected rather than delivering untreated tracks."
                ),
            },
        )
    expected_dynamic_receipt_tracks = expected_dynamic_tracks

    result = (
        _replacement_render_sync_v0122(
            req
        )
    )

    visual = result.get("visual_base") or {}
    detected = int(visual.get("dynamic_brand_actions_detected") or 0)
    rendered = int(visual.get("dynamic_brand_actions_rendered") or 0)
    receipt_equality = bool(visual.get("dynamic_brand_receipt_equality"))
    if (
        expected_dynamic_receipt_tracks > 0
        and bool(getattr(req, "dynamic_brand_cover_require_receipt_equality", True))
        and (
            detected != expected_dynamic_receipt_tracks
            or rendered != detected
            or not receipt_equality
        )
    ):
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "replacement_render",
                "error": "dynamic_watermark_render_receipt_mismatch",
                "expected_tracks": expected_dynamic_receipt_tracks,
                "detected_tracks": detected,
                "rendered_tracks": rendered,
                "per_track_receipts": visual.get("dynamic_brand_per_track_receipts") or [],
                "message": (
                    "Verified dynamic watermark tracks were detected but not every "
                    "track received a frame-render receipt. The output is rejected "
                    "instead of silently delivering an incomplete watermark treatment."
                ),
            },
        )

    persistent_geometry = visual.get("diagonal_brand_cover") or {}
    if (
        bool(getattr(req, "persistent_watermark_required", True))
        and list(getattr(req, "persistent_watermark_anchor_boxes", None) or [])
        and (
            not bool(persistent_geometry.get("available"))
            or int(visual.get("diagonal_brand_cover_frames") or 0) <= 0
        )
    ):
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "replacement_render",
                "error": "persistent_watermark_render_receipt_missing",
                "layout_relative_path": getattr(req, "persistent_watermark_layout_relative_path", None),
                "geometry": persistent_geometry,
                "frames_rendered": int(visual.get("diagonal_brand_cover_frames") or 0),
                "message": (
                    "The source-specific persistent watermark layout was configured, "
                    "but its cover did not reach the visual renderer. The output is "
                    "rejected instead of silently preserving the watermark."
                ),
            },
        )

    result["version"] = "0.12.6"

    summary = result.setdefault(
        "summary",
        {},
    )

    summary[
        "canonical_top_slot_enabled"
    ] = bool(
        req.top_canonical_slot_enabled
    )

    summary[
        "strong_opaque_icon_cover_enabled"
    ] = bool(
        req.top_icon_strong_cover_enabled
    )

    summary[
        "top_brand_layout_follows_local_bbox"
    ] = False
    summary["dynamic_brand_cover_auto_handoff_enabled"] = bool(
        getattr(req, "dynamic_brand_cover_auto_from_plan", True)
    )
    summary["dynamic_brand_cover_receipt_equality"] = bool(
        (result.get("visual_base") or {}).get("dynamic_brand_receipt_equality")
    )
    summary["dynamic_brand_cover_receipt_contract_enabled"] = (
        dynamic_receipt_contract_enabled
    )
    summary["dynamic_brand_cover_receipt_contract_expected_tracks"] = int(
        expected_dynamic_receipt_tracks
    )
    summary["dynamic_brand_tracks_held_for_review"] = False
    summary["persistent_visual_watermark_cover_frames"] = int(
        (result.get("visual_base") or {}).get("diagonal_brand_cover_frames") or 0
    )
    summary["persistent_watermark_source_layout_enabled"] = bool(
        list(getattr(req, "persistent_watermark_anchor_boxes", None) or [])
    )
    summary["dynamic_watermark_temporal_recovery_enabled"] = bool(temporal_handoff)
    summary["dynamic_watermark_temporal_recovery_status"] = (
        temporal_handoff.get("status") if temporal_handoff else "disabled"
    )
    if temporal_handoff:
        summary["dynamic_watermark_temporal_recovery_report_relative_path"] = (
            temporal_handoff.get("report_relative_path")
        )
        summary["dynamic_watermark_temporal_recovery_output_relative_path"] = (
            (temporal_handoff.get("output") or {}).get("output_relative_path")
        )

    result["notes"] = {
        **(
            result.get(
                "notes"
            )
            or {}
        ),
        "v0.12.3_canonical_top_slot": (
            "Own top-brand text/icon use one canonical screen slot derived "
            "robustly from accepted top geometry. Per-time detection boxes no "
            "longer control own-brand position, scale, or typography."
        ),
        "v0.12.3_icon_cover": (
            "The canonical competitor-icon area receives a larger fully opaque "
            "compact cover plate before own logo/icon is drawn, so red remnants "
            "cannot show through transparent artwork."
        ),
        "v0.12.3_cleanup_separation": (
            "Detection geometry and cleanup geometry may vary, but own-brand "
            "presentation remains fixed and consistent across the video."
        ),
        "v0.12.4_dynamic_handoff": (
            "Verified moving-watermark tracks are automatically handed from the "
            "plan router census to the dynamic compositor. Every resolved track "
            "requires a per-track frame receipt before delivery."
        ),
        "v0.12.5_persistent_visual_watermark": (
            "The source router's validated same-source diagonal watermark geometry "
            "is applied to the full retained story timeline, rather than treating "
            "only short OCR motion as a dynamic watermark."
        ),
        "v0.12.6_persistent_source_layout": (
            "Source-specific persistent watermark components are covered from a "
            "layout map with a full-render receipt; generic cross-video geometry "
            "is never reused for this treatment."
        ),
    }

    report_rel = (
        result.get(
            "report_relative_path"
        )
    )

    if report_rel:
        _safe_workspace_path(
            report_rel
        ).write_text(
            json.dumps(
                result,
                ensure_ascii=False,
                indent=2,
            ),
            encoding="utf-8",
        )

    return result




# ---------------------------------------------------------------------------
# v0.12.4 Diagonal Own-Brand Cover Preview
#
# The difficult diagonal tiled watermark is still NOT treated as an invisible
# removal problem.
#
# This route previews a safer rebrand strategy:
#   calibrated diagonal tiled grid
#   -> cover each known tile with a light own-brand label
#
# It is preview-only. Full render already has an opt-in diagonal cover layer,
# but it should remain disabled until this visual preview is accepted.
# ---------------------------------------------------------------------------


class BrandingDiagonalCoverPreviewRequest(BaseModel):
    router_report_relative_path: str

    brand_text: str = "floatboat-fde"

    # Leave null to use three representative source times.
    sample_times_seconds: Optional[list[float]] = None

    preview_seconds: float = 1.5

    angle_degrees: float = -25.0
    text_alpha: float = 0.72
    plate_alpha: float = 0.18
    scale_ratio: float = 0.68
    max_points: int = 30

    crf: int = 15
    preset: str = "slow"


def _representative_diagonal_preview_times(
    duration,
    requested,
):
    if requested:
        clean = []

        for value in requested:
            try:
                t = float(value)
            except Exception:
                continue

            t = max(
                0.0,
                min(
                    float(duration),
                    t,
                ),
            )

            clean.append(
                t
            )

        if clean:
            return clean[:6]

    duration = max(
        0.0,
        float(duration),
    )

    if duration <= 5.0:
        return [
            duration / 2.0
        ]

    return [
        min(
            duration - 0.75,
            max(
                1.0,
                duration * 0.16,
            ),
        ),
        min(
            duration - 0.75,
            max(
                1.0,
                duration * 0.48,
            ),
        ),
        min(
            duration - 0.75,
            max(
                1.0,
                duration * 0.82,
            ),
        ),
    ]


def _render_diagonal_cover_compare(
    video_path,
    out_path,
    center_time,
    seconds,
    geometry,
    brand_text,
    fps,
    width,
    height,
    duration,
    req,
):
    start = max(
        0.0,
        float(center_time)
        - float(seconds) / 2.0,
    )

    end = min(
        float(duration),
        float(center_time)
        + float(seconds) / 2.0,
    )

    class _DiagonalShim:
        diagonal_brand_cover_enabled = True
        diagonal_brand_cover_text = brand_text
        diagonal_brand_cover_angle_degrees = float(
            req.angle_degrees
        )
        diagonal_brand_cover_text_alpha = float(
            req.text_alpha
        )
        diagonal_brand_cover_plate_alpha = float(
            req.plate_alpha
        )
        diagonal_brand_cover_scale_ratio = float(
            req.scale_ratio
        )
        diagonal_brand_cover_max_points = int(
            req.max_points
        )

    shim = _DiagonalShim()

    profile = {
        "brand_name": str(
            brand_text
        ),
        "product_name": str(
            brand_text
        ),
        "assets": {},
    }

    writer, runtime = (
        _open_x264_raw_writer(
            out_path,
            int(width) * 2,
            int(height),
            float(fps),
            int(req.crf),
            str(req.preset),
        )
    )

    cap = cv2.VideoCapture(
        str(video_path)
    )

    if not cap.isOpened():
        raise HTTPException(
            status_code=422,
            detail=(
                "Could not open source video."
            ),
        )

    cap.set(
        cv2.CAP_PROP_POS_MSEC,
        start * 1000.0,
    )

    frame_index = 0
    written = 0
    write_error = None

    try:
        while True:
            ok, frame = cap.read()

            if (
                not ok
                or frame is None
            ):
                break

            t = (
                start
                + frame_index
                / float(
                    max(
                        1e-6,
                        fps,
                    )
                )
            )

            if (
                t
                > end
                + 0.5
                / float(
                    max(
                        1e-6,
                        fps,
                    )
                )
            ):
                break

            covered = (
                _apply_diagonal_brand_cover(
                    frame,
                    geometry,
                    profile,
                    shim,
                )
            )

            compare = np.hstack(
                [
                    _label_pane(
                        frame,
                        "ORIGINAL",
                    ),
                    _label_pane(
                        covered,
                        "OWN BRAND COVER",
                    ),
                ]
            )

            try:
                writer.stdin.write(
                    compare.tobytes()
                )
            except Exception as exc:
                write_error = str(
                    exc
                )[:500]
                break

            written += 1
            frame_index += 1

    finally:
        cap.release()

        try:
            writer.stdin.close()
        except Exception:
            pass

    stderr = b""

    try:
        stderr = (
            writer.stderr.read()
            if writer.stderr
            else b""
        )
    except Exception:
        pass

    code = writer.wait()

    return {
        "ok": (
            code == 0
            and write_error is None
            and out_path.exists()
        ),
        "relative_path": (
            out_path
            .relative_to(
                WORKSPACE
            )
            .as_posix()
            if out_path.exists()
            else None
        ),
        "center_time_seconds": round(
            float(center_time),
            3,
        ),
        "start_seconds": round(
            start,
            3,
        ),
        "end_seconds": round(
            end,
            3,
        ),
        "frames_written": int(
            written
        ),
        "error": (
            write_error
            or (
                stderr.decode(
                    "utf-8",
                    errors="replace",
                )[:800]
                if code != 0
                else None
            )
        ),
        "encoder": {
            "engine": "ffmpeg",
            "codec": "libx264",
            "crf": int(
                req.crf
            ),
            "preset": str(
                req.preset
            ),
            "runtime": runtime,
        },
    }


def _diagonal_brand_cover_preview_sync(
    req: BrandingDiagonalCoverPreviewRequest
):
    router_path, router = (
        _read_json_workspace(
            req.router_report_relative_path,
            "diagonal_brand_cover_preview",
        )
    )

    source_rel = (
        (
            router.get(
                "source"
            )
            or {}
        ).get(
            "relative_path"
        )
    )

    if not source_rel:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": (
                    "diagonal_brand_cover_preview"
                ),
                "error": (
                    "router_source_missing"
                ),
            },
        )

    video_path = (
        _safe_workspace_path(
            source_rel
        )
    )

    cap = cv2.VideoCapture(
        str(video_path)
    )

    if not cap.isOpened():
        raise HTTPException(
            status_code=422,
            detail=(
                "Could not open source video."
            ),
        )

    try:
        meta = _video_metadata(
            cap
        )
    finally:
        cap.release()

    class _GeometryShim:
        diagonal_brand_cover_enabled = True
        diagonal_brand_cover_router_report_relative_path = (
            req.router_report_relative_path
        )
        diagonal_brand_cover_max_points = int(
            req.max_points
        )

    geometry = (
        _load_diagonal_brand_cover_geometry(
            _GeometryShim(),
            int(
                meta["width"]
            ),
            int(
                meta["height"]
            ),
        )
    )

    if not (
        geometry
        and bool(
            geometry.get(
                "available"
            )
        )
    ):
        raise HTTPException(
            status_code=422,
            detail={
                "stage": (
                    "diagonal_brand_cover_preview"
                ),
                "error": (
                    "diagonal_grid_not_available"
                ),
                "geometry": geometry,
            },
        )

    times = (
        _representative_diagonal_preview_times(
            float(
                meta[
                    "duration_seconds"
                ]
            ),
            req.sample_times_seconds,
        )
    )

    timestamp = (
        _app_now().strftime(
            "%Y-%m-%d_%H%M%S"
        )
    )

    out_dir = (
        WORKSPACE
        / "review"
        / "branding_diagonal_cover_preview"
        / timestamp
        / video_path.stem
    )

    out_dir.mkdir(
        parents=True,
        exist_ok=True,
    )

    previews = []

    for index, center in enumerate(
        times,
        1,
    ):
        out_path = (
            out_dir
            / (
                f"{video_path.stem}"
                f".diagonal-cover-{index:02d}"
                f"-t{center:.2f}.mp4"
            )
        )

        previews.append(
            _render_diagonal_cover_compare(
                video_path,
                out_path,
                center,
                float(
                    req.preview_seconds
                ),
                geometry,
                str(
                    req.brand_text
                ),
                float(
                    meta["fps"]
                ),
                int(
                    meta["width"]
                ),
                int(
                    meta["height"]
                ),
                float(
                    meta[
                        "duration_seconds"
                    ]
                ),
                req,
            )
        )

    result = {
        "ok": all(
            p.get(
                "ok"
            )
            for p in previews
        ),
        "version": "0.17.0",
        "mode": (
            "branding_diagonal_brand_cover_preview"
        ),
        "source": {
            "relative_path": source_rel,
            "router_report_relative_path": (
                router_path
                .relative_to(
                    WORKSPACE
                )
                .as_posix()
            ),
        },
        "video": meta,
        "settings": {
            "brand_text": str(
                req.brand_text
            ),
            "angle_degrees": float(
                req.angle_degrees
            ),
            "text_alpha": float(
                req.text_alpha
            ),
            "plate_alpha": float(
                req.plate_alpha
            ),
            "scale_ratio": float(
                req.scale_ratio
            ),
            "max_points": int(
                req.max_points
            ),
        },
        "geometry": geometry,
        "summary": {
            "preview_count": len(
                previews
            ),
            "success_count": sum(
                1
                for p in previews
                if p.get(
                    "ok"
                )
            ),
            "failure_count": sum(
                1
                for p in previews
                if not p.get(
                    "ok"
                )
            ),
            "source_video_modified": False,
            "full_processed_video_created": False,
            "diagonal_invisible_removal_attempted": False,
            "manual_visual_confirmation_required": True,
        },
        "previews": previews,
        "output_relative_dir": (
            out_dir
            .relative_to(
                WORKSPACE
            )
            .as_posix()
        ),
        "notes": {
            "policy": (
                "This is a rebrand cover preview, not invisible removal. "
                "The calibrated diagonal grid is reused; own-brand labels are "
                "drawn over the known tiled watermark positions."
            ),
            "production": (
                "Keep diagonal_brand_cover_enabled=false in full render until "
                "these previews are visually accepted."
            ),
        },
    }

    report_path = (
        out_dir
        / (
            f"{video_path.stem}"
            ".diagonal-cover-preview.json"
        )
    )

    result[
        "report_relative_path"
    ] = (
        report_path
        .relative_to(
            WORKSPACE
        )
        .as_posix()
    )

    report_path.write_text(
        json.dumps(
            result,
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )

    return result




# ---------------------------------------------------------------------------
# v0.13.0 Brand Assets + Production Candidate Render
#
# Dark diagonal tiled watermark remains PARKED.
#
# Adds:
#   - brand asset validation / profile update
#   - asset preview report
#   - production-candidate render mode that forbids engineering placeholders
#   - output QC metadata
# ---------------------------------------------------------------------------


class BrandingBrandAssetsUpdateRequest(BaseModel):
    profile_id: str

    logo_image_relative_path: Optional[str] = None
    icon_image_relative_path: Optional[str] = None
    mid_promo_video_relative_path: Optional[str] = None
    end_card_video_relative_path: Optional[str] = None
    end_card_image_relative_path: Optional[str] = None

    # Optional text fields can be updated together with assets.
    product_name: Optional[str] = None
    brand_name: Optional[str] = None

    # How top branding should render when assets exist.
    top_brand_mode: str = "icon_text"

    # Reject paths outside workspace and reject unreadable/invalid media.
    validate_assets: bool = True


class BrandingBrandAssetsPreviewRequest(BaseModel):
    profile_id: str

    preview_seconds: float = 2.0
    crf: int = 15
    preset: str = "slow"


class BrandingProductionCandidateRenderRequest(BrandingReplacementRenderRequest):
    # Production Candidate means no engineering placeholders.
    # Verified moving watermark tracks must pass temporal clean-repair QA; fixed
    # own-brand banners and blur are forbidden fallback paths for moving marks.
    dynamic_watermark_temporal_recovery_enabled: bool = True
    dynamic_watermark_temporal_recovery_keep_intermediate: bool = True
    allow_placeholder_assets: bool = False

    # Production mode metadata only; no semantic re-detection.
    production_candidate: bool = True

    # REVIEW actions are diagnostic suggestions and must never be executed by
    # an unattended production render.  Callers can explicitly opt in only
    # after a human has confirmed the plan.
    include_review_actions: bool = False

    # Require own End Card asset even if competitor End Card is absent.
    require_own_end_card_asset: bool = True

    # Require own Mid Promo asset if the accepted plan contains Mid Promo.
    require_mid_promo_asset_when_present: bool = True

    # Editorial compression is deliberately opt-in.  A compact candidate keeps
    # the source opening, a configurable leading story window and then hands
    # off to the clean own end-card.  This prevents a brand-repair render from
    # silently publishing an overlong 90s+ source cut.
    editorial_max_story_seconds: Optional[float] = None
    editorial_min_story_seconds: float = 0.0

    # A calibrated diagonal/tiled dynamic watermark must be treated in the
    # production pass.  This is cover/rebrand treatment, not a claim of
    # invisible removal.
    diagonal_brand_cover_enabled: bool = True
    # Set true only for a source with a previously validated grid.  New videos
    # that merely resemble a profile stay on the review/calibration path rather
    # than being failed or painted with unvalidated geometry.
    diagonal_dynamic_watermark_required: bool = False
    # Fixed source marks use cleanup followed by the approved own-brand asset.
    # Moving source marks use temporal repair only; they are never covered by
    # own-brand pixels or a blur fallback.
    diagonal_brand_cover_text_alpha: float = 1.0
    diagonal_brand_cover_plate_alpha: float = 1.0
    diagonal_brand_cover_scale_ratio: float = 0.82
    diagonal_brand_cover_max_points: int = 48

    # The semantic/user override boundary is the editorial source of truth.
    # Trim a small additional tail in the render pass so a one-frame CTA or
    # competitor-logo flash at the outgoing boundary cannot survive concat.
    mid_promo_tail_guard_frames: int = 1


def _production_verified_dynamic_track_count(plan: dict[str, Any]) -> int:
    """Return the strict dynamic-track count without treating broad candidates as marks."""
    summary = plan.get("summary") or {}
    count = max(0, int(summary.get("operator_dynamic_brand_expected_track_count") or 0))
    if count > 0:
        return count

    router_rel = str(((plan.get("source") or {}).get("router_report_relative_path") or "")).strip()
    try:
        if router_rel:
            _, router = _read_json_workspace(router_rel, "production_execution_route")
            router_rel = str(((router.get("evidence_reports") or {}).get("census") or "")).strip()
        if router_rel:
            _, census = _read_json_workspace(router_rel, "production_execution_route")
            strict = census.get("verified_dynamic_identity") or {}
            if bool(strict.get("enabled")):
                return len(strict.get("tracks") or [])
    except Exception:
        # A missing optional diagnostic must not turn an otherwise valid edit
        # into a false dynamic-watermark classification.
        pass
    return 0


def _production_router_has_evidence_backed_watermark(router: dict[str, Any]) -> bool:
    """Distinguish a real unclassified watermark from the old empty placeholder."""
    layers = list(router.get("watermark_layers") or [])
    for layer in layers:
        if not isinstance(layer, dict):
            continue
        is_legacy_empty_placeholder = (
            str(layer.get("layer_id") or "") == "unknown-watermark-layout"
            and str(layer.get("type") or "") == "unknown"
            and not (layer.get("evidence") or {})
            and float(layer.get("confidence") or 0.0) <= 0.0
        )
        if not is_legacy_empty_placeholder:
            return True
    return False


def _production_detected_watermark_present(plan: dict[str, Any]) -> bool:
    """Keep evidence-backed unclassified source marks out of the clean-source path."""
    router_rel = str(((plan.get("source") or {}).get("router_report_relative_path") or "")).strip()
    if not router_rel:
        return False
    try:
        _, router = _read_json_workspace(router_rel, "production_execution_route")
        return _production_router_has_evidence_backed_watermark(router)
    except Exception:
        # Lack of a router report is not evidence of a watermark. The normal
        # planner actions and strict dynamic census remain available below.
        return False


def _production_execution_route(
    plan: dict[str, Any],
    verified_dynamic_track_count: int = 0,
    include_review_actions: bool = True,
    detected_watermark_present: bool = False,
) -> dict[str, Any]:
    """Build the single production route: watermark classification, then editorial actions."""
    accepted_actions = [
        action
        for action in (plan.get("actions") or [])
        if action.get("status") != "REVIEW" or bool(include_review_actions)
    ]
    fixed_actions = [
        action for action in accepted_actions
        if action.get("type") == "fixed_brand_overlay"
    ]
    plan_video = ((plan.get("source") or {}).get("video") or {})
    try:
        plan_width = int(plan_video.get("width") or 0)
        plan_height = int(plan_video.get("height") or 0)
    except (TypeError, ValueError):
        plan_width = plan_height = 0
    top_fixed_actions = [
        action for action in fixed_actions
        if _operator_fixed_action_vertical_zone(action, plan_width, plan_height) == "top"
    ]
    bottom_fixed_actions = [
        action for action in fixed_actions
        if _operator_fixed_action_vertical_zone(action, plan_width, plan_height) == "bottom"
    ]
    legacy_moving_actions = [
        action for action in accepted_actions
        if action.get("type") == "moving_brand_overlay"
    ]
    mid_promo_actions = [
        action for action in accepted_actions
        if action.get("type") == "mid_promo_replace"
    ]
    end_card_actions = [
        action for action in accepted_actions
        if action.get("type") == "end_card_replace"
    ]

    fixed_present = bool(fixed_actions)
    dynamic_track_count = max(0, int(verified_dynamic_track_count or 0))
    dynamic_present = dynamic_track_count > 0
    watermark_present = bool(detected_watermark_present) or fixed_present or dynamic_present
    if fixed_present and dynamic_present:
        classification = "fixed_and_dynamic"
    elif fixed_present:
        classification = "fixed_only"
    elif dynamic_present:
        classification = "dynamic_only"
    elif watermark_present:
        classification = "unclassified"
    else:
        classification = "none"

    classification_required = classification == "unclassified"

    return {
        "version": "watermark_then_editorial_v1",
        "watermark": {
            "present": watermark_present,
            "classification": classification,
            "classification_required": classification_required,
            "fixed_present": fixed_present,
            "fixed_action_count": len(fixed_actions),
            "top_fixed_action_count": len(top_fixed_actions),
            "bottom_fixed_action_count": len(bottom_fixed_actions),
            "fixed_strategy": (
                "source_cleanup_then_own_brand" if fixed_present
                else "classification_required" if classification_required
                else "skip_no_fixed_watermark"
            ),
            "dynamic_present": dynamic_present,
            "verified_dynamic_track_count": dynamic_track_count,
            "dynamic_strategy": (
                "temporal_clean_repair_no_overlay" if dynamic_present
                else "classification_required" if classification_required
                else "skip_no_verified_dynamic_watermark"
            ),
            "own_brand_overlay_for_fixed_watermarks": fixed_present,
            "own_brand_overlay_for_dynamic_watermarks": False,
        },
        "editorial": {
            "mid_promo_present": bool(mid_promo_actions),
            "mid_promo_action_count": len(mid_promo_actions),
            "mid_promo_strategy": "replace" if mid_promo_actions else "skip",
            "source_end_card_present": bool(end_card_actions),
            "source_end_card_action_count": len(end_card_actions),
            "end_card_strategy": "replace" if end_card_actions else "append_own",
        },
        "render": {
            # No fixed watermark means no fixed-layer compositor work. Dynamic
            # repair is performed before this compositor from strict tracks.
            "watermark_treatment_mode": "rebrand_fixed_clean_dynamic" if fixed_present else "skip_no_fixed_watermark",
            "compose_top_brand_layers": bool(top_fixed_actions),
            "diagonal_brand_cover_enabled": fixed_present,
            "persistent_watermark_auto_from_source_layout": fixed_present,
            "persistent_watermark_required": fixed_present,
            "dynamic_watermark_temporal_recovery_enabled": dynamic_present,
            # The temporal stage owns all dynamic work; old broad moving
            # actions are intentionally excluded from the downstream renderer.
            "exclude_legacy_moving_actions": bool(legacy_moving_actions),
            "append_own_end_card_when_absent": not bool(end_card_actions),
        },
    }


def _operator_diagonal_tiled_watermark_screen(video_entry):
    """Fast pre-edit gate for repeated diagonal/tiled source watermarks.

    This deliberately reuses the calibrated diagonal detector primitives but
    does not create a render plan. A qualifying repeated grid is a hard source
    exclusion because the current production path cannot promise invisible
    removal for that layout.
    """
    relative_path = str((video_entry or {}).get("relative_path") or "").strip()
    video_path = _safe_workspace_path(relative_path)
    cap = cv2.VideoCapture(str(video_path))
    if not cap.isOpened():
        return {"detected": False, "status": "screen_unavailable", "relative_path": relative_path}

    try:
        metadata = _video_metadata(cap)
        width = int(metadata.get("width") or 0)
        height = int(metadata.get("height") or 0)
        duration = float(metadata.get("duration_seconds") or 0.0)
        if width <= 0 or height <= 0:
            return {"detected": False, "status": "screen_unavailable", "relative_path": relative_path}

        max_frames = 120
        interval = max(0.50, duration / float(max_frames)) if duration > 0 else 0.75
        angles = [-45.0, -35.0, -25.0, -15.0, 15.0, 25.0, 35.0, 45.0]
        angle_hits = {angle: [] for angle in angles}
        sampled_times = []
        frames_scanned = 0
        t = 0.0
        while t <= duration + 1e-9 and frames_scanned < max_frames:
            _operator_raise_if_cancelled()
            cap.set(cv2.CAP_PROP_POS_MSEC, t * 1000.0)
            ok, frame = cap.read()
            if ok and frame is not None:
                sampled_times.append(round(float(t), 3))
                frames_scanned += 1
                for angle in angles:
                    # The first pass resists noisy scene texture. The second
                    # admits faint/compressed tiled marks that otherwise fail
                    # before their repeated same-frame lattice can be scored.
                    # Both passes still flow through the strict persistence,
                    # span and simultaneous-multi-tile gates below, so a
                    # single moving watermark cannot become a tiled discard.
                    pass_specs = (
                        ("strict", 84.0, 41, 5, 55, 520, 10, 110, 1.8, 18.0),
                        ("sensitive", 76.0, 29, 5, 28, 600, 6, 100, 1.25, 26.0),
                    )
                    seen = set()
                    for detector_profile, threshold, block, min_side, min_area, max_area, min_width, max_width, aspect_min, aspect_max in pass_specs:
                        hits, _, _ = _diag_component_hits(
                            frame, angle, threshold, block, min_side, min_area,
                            max_area, min_width, max_width, aspect_min, aspect_max,
                            None,
                        )
                        for hit in hits:
                            center = hit.get("center_rotated") or {}
                            dedupe_key = (
                                round(float(center.get("x") or 0.0) / 12.0),
                                round(float(center.get("y") or 0.0) / 12.0),
                                round(float(hit.get("width") or 0.0) / 8.0),
                                round(float(hit.get("height") or 0.0) / 8.0),
                            )
                            if dedupe_key in seen:
                                continue
                            seen.add(dedupe_key)
                            hit["time_seconds"] = round(float(t), 3)
                            hit["angle_degrees"] = angle
                            hit["detector_profile"] = detector_profile
                            angle_hits[angle].append(hit)
            t += interval

        # A moving watermark leaves historical positions but does not remain
        # at one normalized tile coordinate. Require each tiled candidate to
        # persist across a meaningful portion of the sampled timeline; this is
        # the key separation between a fixed diagonal grid and a moving mark.
        # A tiled watermark can be faint enough that a few cells are missed in
        # each sample.  Require persistence plus same-frame lattice evidence,
        # rather than an arbitrary eight-cell history that made real diagonal
        # grids pass through on new encoders.
        min_persistence_times = max(5, int(math.ceil(frames_scanned * 0.06)))

        angle_reports = []
        for angle in angles:
            clusters = _cluster_diag_hits(angle_hits[angle], 55.0, 2.2)
            persistent = [
                _diag_persistent_cluster_report(index, cluster, min_persistence_times)
                for index, cluster in enumerate(clusters, 1)
            ]
            persistent = [tile for tile in persistent if tile["persistent"]]
            # The pre-edit discard gate is intentionally stricter than the
            # diagnostic census: require at least six repeated marks spanning
            # a substantial part of both axes. This prevents a subtitle band
            # or a couple of diagonal scene edges from discarding a source.
            # Moving marks can leave many historical positions, but they do
            # not form a dense lattice in the same frame. Keep this gate
            # conservative: a true tiled source must expose several persistent
            # tiles and broad coverage before it is discarded.  The mandatory
            # same-frame check below prevents a moving mark's historical path
            # from satisfying this lower sensitivity threshold.
            grid = _diag_grid_score(persistent, width, height, 5, 0.35, 0.35)
            # Mobile-video chrome (bottom navigation, right-side social
            # controls and corner icons) is often detected as a pseudo-grid
            # after rotation.  A real tiled watermark should not have most of
            # its persistent components confined to the outer UI bands.
            edge_band_tiles = sum(
                1
                for tile in persistent
                for center in [tile.get("median_center_rotated") or {}]
                if (
                    float(center.get("y") or 0.0) <= float(height) * 0.10
                    or float(center.get("y") or 0.0) >= float(height) * 0.80
                    or float(center.get("x") or 0.0) <= float(width) * 0.08
                    or float(center.get("x") or 0.0) >= float(width) * 0.92
                )
            )
            edge_band_ratio = edge_band_tiles / float(max(1, len(persistent)))
            grid["edge_band_tile_ratio"] = round(edge_band_ratio, 4)
            if edge_band_ratio >= 0.68:
                grid["qualifies_as_repeated_grid"] = False
                grid["rejection_reason"] = "persistent_components_concentrated_in_ui_edge_bands"
            # UI chrome and subtitles are intentionally excluded from the
            # discard gate. A genuine tiled source must have repeated marks in
            # the content-safe middle area, not merely at top/bottom bands.
            content_tiles = [
                tile
                for tile in persistent
                for center in [tile.get("center_source") or tile.get("median_center_rotated") or {}]
                if float(height) * 0.12 <= float(center.get("y") or 0.0) <= float(height) * 0.88
                and float(width) * 0.06 <= float(center.get("x") or 0.0) <= float(width) * 0.94
            ]
            grid["content_safe_tile_count"] = len(content_tiles)
            if len(content_tiles) < 5:
                grid["qualifies_as_repeated_grid"] = False
                grid["rejection_reason"] = "insufficient_content_safe_tiles_after_ui_exclusion"
            # A moving watermark can leave many historical positions and
            # falsely resemble a tiled grid. A real tiled watermark presents
            # several repeated marks in the *same frame*. Require that this
            # happens on a meaningful fraction of sampled frames.
            per_frame_hits = {}
            for hit in angle_hits[angle]:
                key = round(float(hit.get("time_seconds") or 0.0), 3)
                per_frame_hits.setdefault(key, []).append(hit)
            simultaneous_frames = sum(
                1
                for frame_hits in per_frame_hits.values()
                if len(frame_hits) >= 4
                and (
                    max(float(h["center_rotated"]["x"]) for h in frame_hits)
                    - min(float(h["center_rotated"]["x"]) for h in frame_hits)
                ) >= float(width) * 0.25
                and (
                    max(float(h["center_rotated"]["y"]) for h in frame_hits)
                    - min(float(h["center_rotated"]["y"]) for h in frame_hits)
                ) >= float(height) * 0.20
            )
            simultaneous_ratio = simultaneous_frames / float(max(1, len(sampled_times)))
            grid["simultaneous_multi_tile_frames"] = int(simultaneous_frames)
            grid["simultaneous_multi_tile_ratio"] = round(simultaneous_ratio, 4)
            grid["qualifies_as_repeated_grid"] = bool(
                grid.get("qualifies_as_repeated_grid")
                and simultaneous_ratio >= 0.25
            )
            angle_reports.append({"angle_degrees": angle, **grid})

        angle_reports.sort(
            key=lambda item: (
                1 if item["qualifies_as_repeated_grid"] else 0,
                float(item["grid_score"]),
                int(item["persistent_tile_count"]),
            ),
            reverse=True,
        )
        best = angle_reports[0] if angle_reports else {}
        # Static app chrome (top-left icon, right-side social controls and
        # bottom navigation) can generate convincing rotated components at
        # both +15 and -15 degrees.  A genuine tiled watermark normally has a
        # single dominant orientation.  When equally strong opposite angles
        # qualify, keep the source in the normal editing flow instead of
        # discarding it as a diagonal tiled watermark.
        qualified = [
            item for item in angle_reports
            if item.get("qualifies_as_repeated_grid")
        ]
        opposite_angle_ambiguity = False
        for left in qualified:
            for right in qualified:
                if float(left.get("angle_degrees") or 0.0) >= 0.0 >= float(right.get("angle_degrees") or 0.0):
                    if abs(abs(float(left.get("angle_degrees") or 0.0)) - abs(float(right.get("angle_degrees") or 0.0))) <= 5.0:
                        if float(left.get("grid_score") or 0.0) >= 0.90 and float(right.get("grid_score") or 0.0) >= 0.90:
                            # Suppress only the small, edge-heavy ±15° UI
                            # pattern. A broad persistent lattice is genuine
                            # evidence even if its edge response appears at
                            # the mirrored angle as well.
                            broad_lattice = (
                                min(
                                    int(left.get("persistent_tile_count") or 0),
                                    int(right.get("persistent_tile_count") or 0),
                                ) >= 6
                                and min(
                                    float(left.get("simultaneous_multi_tile_ratio") or 0.0),
                                    float(right.get("simultaneous_multi_tile_ratio") or 0.0),
                                ) >= 0.25
                                and (
                                    bool(left.get("lattice_consistency"))
                                    or bool(right.get("lattice_consistency"))
                                )
                            )
                            near_ui_angle = abs(float(left.get("angle_degrees") or 0.0)) <= 15.0
                            edge_heavy = max(
                                float(left.get("edge_band_tile_ratio") or 0.0),
                                float(right.get("edge_band_tile_ratio") or 0.0),
                            ) >= 0.45
                            if near_ui_angle and edge_heavy and not broad_lattice:
                                opposite_angle_ambiguity = True
                                break
            if opposite_angle_ambiguity:
                break
        if opposite_angle_ambiguity:
            best = dict(best)
            best["qualifies_as_repeated_grid"] = False
            best["rejection_reason"] = "ambiguous_opposite_diagonal_angles_likely_ui_chrome"
        detected = bool(best.get("qualifies_as_repeated_grid"))
        timestamp = _app_now().strftime("%Y-%m-%d_%H%M%S")
        out_dir = WORKSPACE / "review" / "diagonal_watermark_screen" / timestamp / video_path.stem
        out_dir.mkdir(parents=True, exist_ok=True)
        report_path = out_dir / f"{video_path.stem}.diagonal-screen.json"
        report = {
            "ok": True,
            "mode": "diagonal_tiled_watermark_pre_edit_screen",
            "source": {"relative_path": relative_path},
            "video": metadata,
            "scan": {
                "frames_scanned": frames_scanned,
                "sampled_times": sampled_times[:240],
                "effective_interval_seconds": round(interval, 4),
            },
            "summary": {
                "detected": detected,
                "best_angle_degrees": best.get("angle_degrees"),
                "persistent_tile_count": int(best.get("persistent_tile_count") or 0),
                "horizontal_span_ratio": float(best.get("horizontal_span_ratio") or 0.0),
                "vertical_span_ratio": float(best.get("vertical_span_ratio") or 0.0),
                "repeated_shape": bool(best.get("repeated_shape")),
                "aspect_consistency": bool(best.get("aspect_consistency")),
                "size_consistency": bool(best.get("size_consistency")),
                "quadrant_spread": bool(best.get("quadrant_spread")),
                "lattice_consistency": bool(best.get("lattice_consistency")),
                "visual_consistency": bool(best.get("visual_consistency")),
                "content_safe_tile_count": int(best.get("content_safe_tile_count") or 0),
                "grid_score": float(best.get("grid_score") or 0.0),
                "edge_band_tile_ratio": float(best.get("edge_band_tile_ratio") or 0.0),
                "simultaneous_multi_tile_frames": int(
                    best.get("simultaneous_multi_tile_frames") or 0
                ),
                "simultaneous_multi_tile_ratio": float(
                    best.get("simultaneous_multi_tile_ratio") or 0.0
                ),
                "rejection_reason": best.get("rejection_reason"),
            },
            "angle_reports": angle_reports,
            "policy": {
                "action": "discard_before_edit" if detected else "continue_to_edit",
                "reason": "repeated_diagonal_tiled_watermark" if detected else "no_qualified_repeated_diagonal_grid",
            },
        }
        report_path.write_text(json.dumps(report, ensure_ascii=False, indent=2), encoding="utf-8")
        return {
            "detected": detected,
            "status": "detected" if detected else "clear",
            "relative_path": relative_path,
            "report_relative_path": report_path.relative_to(WORKSPACE).as_posix(),
            "summary": report["summary"],
        }
    finally:
        cap.release()


def _brand_profiles_registry_path():
    return (
        WORKSPACE
        / "config"
        / "brand_replacement_profiles.json"
    )


def _load_brand_profiles_registry():
    path = _brand_profiles_registry_path()

    if not path.exists():
        return {
            "profiles": []
        }

    try:
        payload = json.loads(
            path.read_text(
                encoding="utf-8"
            )
        )
    except Exception as exc:
        raise HTTPException(
            status_code=500,
            detail={
                "stage": "brand_assets",
                "error": "profile_registry_unreadable",
                "message": str(exc)[:500],
            },
        )

    if isinstance(
        payload,
        list,
    ):
        payload = {
            "profiles": payload
        }

    if "profiles" not in payload:
        payload["profiles"] = []

    return payload


def _save_brand_profiles_registry(payload):
    path = _brand_profiles_registry_path()
    path.parent.mkdir(
        parents=True,
        exist_ok=True,
    )

    path.write_text(
        json.dumps(
            payload,
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )

    return path


def _find_profile_by_id(
    registry,
    profile_id,
):
    for profile in (
        registry.get("profiles")
        or []
    ):
        if str(
            profile.get("profile_id")
            or ""
        ) == str(profile_id):
            return profile

    return None


def _validate_image_asset(
    rel_path,
):
    if not rel_path:
        return {
            "configured": False,
            "valid": False,
            "relative_path": None,
        }

    path = _safe_workspace_path(
        str(rel_path)
    )

    result = {
        "configured": True,
        "valid": False,
        "relative_path": str(rel_path),
        "exists": path.exists(),
        "kind": "image",
    }

    if not path.exists():
        result["error"] = "file_not_found"
        return result

    image = cv2.imread(
        str(path),
        cv2.IMREAD_UNCHANGED,
    )

    if image is None:
        result["error"] = "image_unreadable"
        return result

    h, w = image.shape[:2]

    result.update(
        {
            "valid": True,
            "width": int(w),
            "height": int(h),
            "channels": (
                int(image.shape[2])
                if len(image.shape) == 3
                else 1
            ),
            "has_alpha": bool(
                len(image.shape) == 3
                and image.shape[2] == 4
            ),
        }
    )

    return result


def _video_asset_visual_integrity(path, media=None):
    """Reject technically playable but visually empty promo/end-card videos."""
    media = media or _probe_media(path)
    duration = float(media.get("duration_seconds") or 0.0)
    if duration <= 0.05:
        return {
            "valid": False,
            "error": "video_duration_unavailable",
            "sample_count": 0,
        }

    sample_times = sorted(
        {
            round(max(0.0, min(duration - 0.02, duration * fraction)), 3)
            for fraction in (0.20, 0.50, 0.80)
        }
    )
    cap = cv2.VideoCapture(str(path))
    if not cap.isOpened():
        return {
            "valid": False,
            "error": "video_unreadable_for_visual_validation",
            "sample_count": 0,
        }

    means = []
    stddevs = []
    try:
        for time_seconds in sample_times:
            cap.set(cv2.CAP_PROP_POS_MSEC, time_seconds * 1000.0)
            ok, frame = cap.read()
            if not ok or frame is None or frame.size == 0:
                continue
            gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
            means.append(float(np.mean(gray)))
            stddevs.append(float(np.std(gray)))
    finally:
        cap.release()

    if not stddevs:
        return {
            "valid": False,
            "error": "video_visual_samples_unreadable",
            "sample_count": 0,
        }

    max_stddev = max(stddevs)
    mean_range = max(means) - min(means)
    # A flat colour card has virtually no spatial variance.  Legitimate end
    # cards may be simple, so this threshold is deliberately conservative.
    visually_empty = max_stddev < 3.0 and mean_range < 3.0
    return {
        "valid": not visually_empty,
        "error": "video_visual_content_blank" if visually_empty else None,
        "sample_count": len(stddevs),
        "sample_mean_range": round(mean_range, 3),
        "sample_max_luma_stddev": round(max_stddev, 3),
    }


def _validate_video_asset(
    rel_path,
):
    if not rel_path:
        return {
            "configured": False,
            "valid": False,
            "relative_path": None,
        }

    path = _safe_workspace_path(
        str(rel_path)
    )

    result = {
        "configured": True,
        "valid": False,
        "relative_path": str(rel_path),
        "exists": path.exists(),
        "kind": "video",
    }

    if not path.exists():
        result["error"] = "file_not_found"
        return result

    media = _probe_media(
        path
    )

    if not media.get(
        "has_video"
    ):
        result["error"] = "video_stream_missing"
        result["media"] = media
        return result

    visual = _video_asset_visual_integrity(path, media)

    result.update(
        {
            "valid": bool(visual.get("valid")),
            "duration_seconds": media.get(
                "duration_seconds"
            ),
            "has_audio": bool(
                media.get(
                    "has_audio"
                )
            ),
            "audio_channels": media.get(
                "audio_channels"
            ),
            "audio_sample_rate": media.get(
                "audio_sample_rate"
            ),
            "visual_integrity": visual,
        }
    )

    if not bool(visual.get("valid")):
        result["error"] = str(
            visual.get("error") or "video_visual_integrity_failed"
        )

    return result


def _validate_brand_assets_base(
    profile,
):
    assets = (
        profile.get("assets")
        or {}
    )

    report = {
        "logo_image": _validate_image_asset(
            assets.get(
                "logo_image_relative_path"
            )
        ),
        "icon_image": _validate_image_asset(
            assets.get(
                "icon_image_relative_path"
            )
        ),
        "mid_promo_video": _validate_video_asset(
            assets.get(
                "mid_promo_video_relative_path"
            )
        ),
        "end_card_video": _validate_video_asset(
            assets.get(
                "end_card_video_relative_path"
            )
        ),
        "end_card_image": _validate_image_asset(
            assets.get(
                "end_card_image_relative_path"
            )
        ),
    }

    report["summary"] = {
        "top_brand_asset_ready": bool(
            report[
                "logo_image"
            ].get("valid")
            or report[
                "icon_image"
            ].get("valid")
        ),
        "mid_promo_asset_ready": bool(
            report[
                "mid_promo_video"
            ].get("valid")
        ),
        "end_card_asset_ready": bool(
            report[
                "end_card_video"
            ].get("valid")
            or report[
                "end_card_image"
            ].get("valid")
        ),
        "configured_asset_count": sum(
            1
            for value in report.values()
            if isinstance(value, dict)
            and value.get(
                "configured"
            )
        ),
        "valid_asset_count": sum(
            1
            for value in report.values()
            if isinstance(value, dict)
            and value.get(
                "valid"
            )
        ),
    }

    return report



def _validate_brand_assets(
    profile,
    *,
    language=None,
    language_code=None,
):
    """
    Validate standard brand slots, with language-specific Mid Promo / End Card
    preferred over the default slot.
    """
    validation = (
        _validate_brand_assets_base(
            profile
        )
    )

    asset_directory = (
        _brand_asset_directory_for_profile(
            profile
        )
    )

    mid_path = (
        _brand_asset_first_existing(
            _brand_asset_language_candidates(
                asset_directory,
                "mid-promo",
                [
                    "mp4",
                ],
                language=language,
                language_code=language_code,
            )
        )
    )

    end_path = (
        _brand_asset_first_existing(
            _brand_asset_language_candidates(
                asset_directory,
                "end-card",
                [
                    "mp4",
                    "png",
                ],
                language=language,
                language_code=language_code,
            )
        )
    )

    summary = (
        validation.setdefault(
            "summary",
            {},
        )
    )

    # Discovery only tells us where an override lives.  Re-run full media and
    # visual validation on those language-specific selections before marking
    # them production-ready.
    selected_mid_validation = (
        _validate_video_asset(
            mid_path.relative_to(WORKSPACE).as_posix()
        )
        if mid_path
        else None
    )
    selected_end_validation = (
        _validate_video_asset(
            end_path.relative_to(WORKSPACE).as_posix()
        )
        if end_path and end_path.suffix.lower() == ".mp4"
        else (
            _validate_image_asset(
                end_path.relative_to(WORKSPACE).as_posix()
            )
            if end_path
            else None
        )
    )

    validation["selected_mid_promo_validation"] = selected_mid_validation
    validation["selected_end_card_validation"] = selected_end_validation

    summary["mid_promo_asset_ready"] = bool(
        selected_mid_validation and selected_mid_validation.get("valid")
    )

    summary["end_card_asset_ready"] = bool(
        selected_end_validation and selected_end_validation.get("valid")
    )

    autodiscovery = (
        validation.setdefault(
            "autodiscovery",
            {},
        )
    )

    autodiscovery[
        "language"
    ] = language

    autodiscovery[
        "language_code"
    ] = (
        _brand_asset_language_code(
            language,
            language_code,
        )
    )

    autodiscovery[
        "mid_promo_selected_relative_path"
    ] = (
        mid_path.relative_to(
            WORKSPACE
        ).as_posix()
        if selected_mid_validation and selected_mid_validation.get("valid")
        else None
    )

    autodiscovery[
        "end_card_selected_relative_path"
    ] = (
        end_path.relative_to(
            WORKSPACE
        ).as_posix()
        if selected_end_validation and selected_end_validation.get("valid")
        else None
    )

    autodiscovery[
        "mid_promo_candidates"
    ] = [
        p.relative_to(
            WORKSPACE
        ).as_posix()
        for p in (
            _brand_asset_language_candidates(
                asset_directory,
                "mid-promo",
                [
                    "mp4",
                ],
                language=language,
                language_code=language_code,
            )
        )
    ]

    autodiscovery[
        "end_card_candidates"
    ] = [
        p.relative_to(
            WORKSPACE
        ).as_posix()
        for p in (
            _brand_asset_language_candidates(
                asset_directory,
                "end-card",
                [
                    "mp4",
                    "png",
                ],
                language=language,
                language_code=language_code,
            )
        )
    ]

    # Keep explicit selected paths where current renderer/profile code can
    # consume them without requiring per-task configuration.
    if selected_mid_validation and selected_mid_validation.get("valid"):
        validation[
            "selected_mid_promo_path"
        ] = str(
            mid_path
        )

    if selected_end_validation and selected_end_validation.get("valid"):
        validation[
            "selected_end_card_path"
        ] = str(
            end_path
        )

    return validation

def _brand_assets_update_sync(
    req: BrandingBrandAssetsUpdateRequest
):
    registry = (
        _load_brand_profiles_registry()
    )

    profile = _find_profile_by_id(
        registry,
        req.profile_id,
    )

    if profile is None:
        raise HTTPException(
            status_code=404,
            detail={
                "stage": "brand_assets",
                "error": "profile_not_found",
                "profile_id": req.profile_id,
            },
        )

    if req.product_name is not None:
        profile["product_name"] = str(
            req.product_name
        )

    if req.brand_name is not None:
        profile["brand_name"] = str(
            req.brand_name
        )

    profile[
        "top_brand_mode"
    ] = str(
        req.top_brand_mode
        or "icon_text"
    )

    assets = profile.setdefault(
        "assets",
        {},
    )

    updates = {
        "logo_image_relative_path": (
            req.logo_image_relative_path
        ),
        "icon_image_relative_path": (
            req.icon_image_relative_path
        ),
        "mid_promo_video_relative_path": (
            req.mid_promo_video_relative_path
        ),
        "end_card_video_relative_path": (
            req.end_card_video_relative_path
        ),
        "end_card_image_relative_path": (
            req.end_card_image_relative_path
        ),
    }

    # Explicit null clears an asset; this endpoint is intended as a full asset
    # snapshot rather than patch semantics.
    for key, value in updates.items():
        assets[key] = value

    validation = _validate_brand_assets(
        profile
    )

    if bool(
        req.validate_assets
    ):
        invalid_configured = []

        for name, item in validation.items():
            if not isinstance(
                item,
                dict,
            ):
                continue

            if (
                item.get("configured")
                and not item.get("valid")
            ):
                invalid_configured.append(
                    {
                        "asset": name,
                        "relative_path": item.get(
                            "relative_path"
                        ),
                        "error": item.get(
                            "error"
                        ),
                    }
                )

        if invalid_configured:
            raise HTTPException(
                status_code=422,
                detail={
                    "stage": "brand_assets",
                    "error": "configured_asset_validation_failed",
                    "invalid_assets": invalid_configured,
                },
            )

    # Only persist a profile after the explicit asset snapshot passes visual
    # validation.  A failed update must not poison the production registry.

    saved_path = (
        _save_brand_profiles_registry(
            registry
        )
    )

    return {
        "ok": True,
        "version": "0.17.0",
        "mode": "brand_assets_update",
        "profile": profile,
        "validation": validation,
        "registry_relative_path": (
            saved_path
            .relative_to(
                WORKSPACE
            )
            .as_posix()
        ),
    }


def _render_brand_asset_preview_card(
    out_path,
    profile,
    validation,
):
    width = 720
    height = 1280

    card = np.zeros(
        (
            height,
            width,
            3,
        ),
        dtype=np.uint8,
    )

    card[:] = (
        30,
        30,
        30,
    )

    y = 110

    cv2.putText(
        card,
        "Brand Asset Preview",
        (
            48,
            y,
        ),
        cv2.FONT_HERSHEY_SIMPLEX,
        1.1,
        (
            245,
            245,
            245,
        ),
        2,
        cv2.LINE_AA,
    )

    y += 80

    cv2.putText(
        card,
        str(
            profile.get(
                "brand_name"
            )
            or ""
        ),
        (
            48,
            y,
        ),
        cv2.FONT_HERSHEY_SIMPLEX,
        0.9,
        (
            245,
            245,
            245,
        ),
        2,
        cv2.LINE_AA,
    )

    y += 55

    cv2.putText(
        card,
        str(
            profile.get(
                "product_name"
            )
            or ""
        ),
        (
            48,
            y,
        ),
        cv2.FONT_HERSHEY_SIMPLEX,
        0.72,
        (
            220,
            220,
            220,
        ),
        2,
        cv2.LINE_AA,
    )

    assets = profile.get(
        "assets"
    ) or {}

    logo = _load_bgr_asset(
        assets.get(
            "logo_image_relative_path"
        )
        or assets.get(
            "icon_image_relative_path"
        )
    )

    if logo is not None:
        card = _alpha_overlay_image(
            card,
            logo,
            48,
            310,
            120,
        )

    y = 500

    rows = [
        (
            "Top brand",
            validation["summary"][
                "top_brand_asset_ready"
            ],
        ),
        (
            "Mid Promo",
            validation["summary"][
                "mid_promo_asset_ready"
            ],
        ),
        (
            "End Card",
            validation["summary"][
                "end_card_asset_ready"
            ],
        ),
    ]

    for label, ready in rows:
        text = (
            f"{label}: "
            + (
                "READY"
                if ready
                else "NOT SET"
            )
        )

        cv2.putText(
            card,
            text,
            (
                48,
                y,
            ),
            cv2.FONT_HERSHEY_SIMPLEX,
            0.72,
            (
                235,
                235,
                235,
            ),
            2,
            cv2.LINE_AA,
        )

        y += 58

    if not cv2.imwrite(
        str(out_path),
        card,
    ):
        raise HTTPException(
            status_code=500,
            detail={
                "stage": "brand_assets_preview",
                "error": "preview_image_write_failed",
            },
        )

    return out_path


def _brand_assets_preview_sync(
    req: BrandingBrandAssetsPreviewRequest
):
    registry = (
        _load_brand_profiles_registry()
    )

    profile = _find_profile_by_id(
        registry,
        req.profile_id,
    )

    if profile is None:
        raise HTTPException(
            status_code=404,
            detail={
                "stage": "brand_assets_preview",
                "error": "profile_not_found",
                "profile_id": req.profile_id,
            },
        )

    validation = _validate_brand_assets(
        profile
    )

    timestamp = _app_now().strftime(
        "%Y-%m-%d_%H%M%S"
    )

    out_dir = (
        WORKSPACE
        / "review"
        / "brand_assets_preview"
        / timestamp
        / str(
            req.profile_id
        )
    )

    out_dir.mkdir(
        parents=True,
        exist_ok=True,
    )

    card_path = (
        out_dir
        / "brand-assets-summary.png"
    )

    _render_brand_asset_preview_card(
        card_path,
        profile,
        validation,
    )

    previews = {
        "summary_image_relative_path": (
            card_path
            .relative_to(
                WORKSPACE
            )
            .as_posix()
        )
    }

    assets = profile.get(
        "assets"
    ) or {}

    # Normalize short previews for configured promo/end-card videos.
    for label, rel in (
        (
            "mid_promo",
            assets.get(
                "mid_promo_video_relative_path"
            ),
        ),
        (
            "end_card",
            assets.get(
                "end_card_video_relative_path"
            ),
        ),
    ):
        if not rel:
            continue

        path = _safe_workspace_path(
            rel
        )

        media = _probe_media(
            path
        )

        if not media.get(
            "has_video"
        ):
            continue

        out_path = (
            out_dir
            / f"{label}-asset-preview.mp4"
        )

        ffmpeg = shutil.which(
            "ffmpeg"
        )

        duration = min(
            max(
                0.5,
                float(
                    req.preview_seconds
                ),
            ),
            float(
                media.get(
                    "duration_seconds"
                )
                or req.preview_seconds
            ),
        )

        cmd = [
            ffmpeg,
            "-y",
            "-i",
            str(path),
            "-t",
            f"{duration:.3f}",
            "-c:v",
            "libx264",
            "-crf",
            str(
                int(req.crf)
            ),
            "-preset",
            str(
                req.preset
            ),
            "-pix_fmt",
            "yuv420p",
            "-c:a",
            "aac",
            "-b:a",
            "160k",
            "-movflags",
            "+faststart",
            str(
                out_path
            ),
        ]

        _run_ffmpeg_checked(
            cmd,
            f"brand_assets_preview_{label}",
        )

        previews[
            f"{label}_video_relative_path"
        ] = (
            out_path
            .relative_to(
                WORKSPACE
            )
            .as_posix()
        )

    return {
        "ok": True,
        "version": "0.17.0",
        "mode": "brand_assets_preview",
        "profile": profile,
        "validation": validation,
        "previews": previews,
        "output_relative_dir": (
            out_dir
            .relative_to(
                WORKSPACE
            )
            .as_posix()
        ),
    }


def _production_candidate_render_sync(
    req: BrandingProductionCandidateRenderRequest
):
    plan_path, plan = _read_json_workspace(
        req.replacement_plan_relative_path,
        "production_candidate_render",
    )

    profile = (
        plan.get(
            "profile"
        )
        or {}
    )

    # Prefer latest profile registry snapshot if same profile_id exists.
    profile_id = profile.get(
        "profile_id"
    )

    if profile_id:
        registry = _load_brand_profiles_registry()
        latest = _find_profile_by_id(
            registry,
            profile_id,
        )

        if latest is not None:
            embedded_profile = json.loads(
                json.dumps(
                    profile,
                    ensure_ascii=False,
                )
            )

            merged_profile = json.loads(
                json.dumps(
                    latest,
                    ensure_ascii=False,
                )
            )

            embedded_assets = (
                embedded_profile.get(
                    "assets"
                )
                or {}
            )

            merged_profile.update(
                {
                    key: value
                    for key, value in (
                        embedded_profile.items()
                    )
                    if key != "assets"
                }
            )

            merged_assets = (
                merged_profile.setdefault(
                    "assets",
                    {},
                )
            )

            merged_assets.update(
                embedded_assets
            )

            profile = (
                merged_profile
            )

    validation = _validate_brand_assets(
        profile
    )

    actions = plan.get(
        "actions"
    ) or []

    verified_dynamic_track_count = _production_verified_dynamic_track_count(plan)
    detected_watermark_present = _production_detected_watermark_present(plan)
    execution_route = _production_execution_route(
        plan,
        verified_dynamic_track_count=verified_dynamic_track_count,
        include_review_actions=bool(req.include_review_actions),
        detected_watermark_present=detected_watermark_present,
    )

    if execution_route["watermark"]["classification_required"]:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "production_candidate_render",
                "error": "watermark_classification_required",
                "message": (
                    "A source watermark was detected but could not be safely "
                    "classified as a fixed watermark or a verified dynamic "
                    "track. Rendering is rejected rather than treating the "
                    "source as clean and leaving the mark in the output."
                ),
                "execution_route": execution_route,
            },
        )

    has_mid_promo_action = any(
        action.get("type")
        == "mid_promo_replace"
        and (
            action.get("status")
            != "REVIEW"
            or bool(
                req.include_review_actions
            )
        )
        for action in actions
    )

    if (
        bool(
            req.require_mid_promo_asset_when_present
        )
        and has_mid_promo_action
        and not validation[
            "summary"
        ][
            "mid_promo_asset_ready"
        ]
    ):
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "production_candidate_render",
                "error": "mid_promo_asset_required",
                "profile_id": profile_id,
            },
        )

    if (
        bool(
            req.require_own_end_card_asset
        )
        and not validation[
            "summary"
        ][
            "end_card_asset_ready"
        ]
    ):
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "production_candidate_render",
                "error": "own_end_card_asset_required",
                "profile_id": profile_id,
            },
        )

    if (
        int(execution_route["watermark"].get("top_fixed_action_count") or 0) > 0
        and not validation["summary"]["top_brand_asset_ready"]
    ):
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "production_candidate_render",
                "error": "top_brand_logo_or_icon_required",
                "profile_id": profile_id,
            },
        )

    # Inject the latest validated profile snapshot into an in-memory plan copy
    # so the normal renderer uses current assets without re-running semantic
    # detection. Persist a temporary production plan snapshot.
    out_dir = (
        WORKSPACE
        / "output"
        / "production_candidate_plan"
        / _app_now().strftime(
            "%Y-%m-%d_%H%M%S"
        )
    )

    out_dir.mkdir(
        parents=True,
        exist_ok=True,
    )

    production_plan = json.loads(
        json.dumps(
            plan,
            ensure_ascii=False,
        )
    )

    production_plan[
        "profile"
    ] = profile
    production_plan["execution_route"] = execution_route
    production_plan.setdefault("summary", {})["execution_route"] = execution_route

    if execution_route["render"]["exclude_legacy_moving_actions"]:
        # Strict census tracks are repaired by the temporal stage before the
        # compositor. Do not let old broad moving-overlay actions trigger a
        # second pass or a false handoff failure afterwards.
        production_plan["actions"] = [
            action
            for action in (production_plan.get("actions") or [])
            if action.get("type") != "moving_brand_overlay"
        ]

    temp_plan_path = (
        out_dir
        / (
            Path(
                plan_path
            ).stem
            + ".production-profile-plan.json"
        )
    )

    temp_plan_path.write_text(
        json.dumps(
            production_plan,
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )

    render_payload = req.model_dump()

    render_payload[
        "replacement_plan_relative_path"
    ] = (
        temp_plan_path
        .relative_to(
            WORKSPACE
        )
        .as_posix()
    )

    render_payload[
        "allow_placeholder_assets"
    ] = False

    route_render = execution_route["render"]
    render_payload["diagonal_brand_cover_enabled"] = route_render[
        "diagonal_brand_cover_enabled"
    ]
    render_payload["compose_top_brand_layers"] = route_render[
        "compose_top_brand_layers"
    ]
    render_payload["watermark_treatment_mode"] = route_render[
        "watermark_treatment_mode"
    ]
    render_payload["persistent_watermark_auto_from_source_layout"] = route_render[
        "persistent_watermark_auto_from_source_layout"
    ]
    render_payload["persistent_watermark_required"] = route_render[
        "persistent_watermark_required"
    ]
    render_payload["dynamic_watermark_temporal_recovery_enabled"] = route_render[
        "dynamic_watermark_temporal_recovery_enabled"
    ]
    render_payload["append_own_end_card_when_absent"] = route_render[
        "append_own_end_card_when_absent"
    ]

    # For an exact-source calibrated diagonal/tiled watermark, do not silently
    # ship a candidate when rebrand geometry cannot be resolved.
    if False:  # blur-only mode does not require legacy diagonal rebrand geometry
        source_router_rel = str(
            ((plan.get("source") or {}).get("router_report_relative_path") or "")
        ).strip()
        if source_router_rel:
            render_payload[
                "diagonal_brand_cover_router_report_relative_path"
            ] = source_router_rel

    # Better real-icon default; placeholder badge is irrelevant in production.
    render_payload[
        "top_icon_placeholder_badge"
    ] = False

    render_req = BrandingReplacementRenderRequest(
        **{
            key: value
            for key, value in render_payload.items()
            if key in BrandingReplacementRenderRequest.model_fields
        }
    )

    result = _replacement_render_sync(
        render_req
    )

    diagonal_visual = result.get("visual_base") or {}
    diagonal_geometry = diagonal_visual.get("diagonal_brand_cover") or {}
    if False:  # blur-only mode does not render a legacy diagonal brand cover
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "production_candidate_render",
                "error": "calibrated_diagonal_watermark_not_rendered",
                "message": (
                    "An exact-source diagonal/dynamic watermark cover was required for this "
                    "production candidate, but no validated geometry could be "
                    "resolved. The candidate was not accepted silently."
                ),
                "geometry": diagonal_geometry,
            },
        )

    # Editorially compact revisions: retain only the configured opening story
    # window and then append the already-normalized own end-card.  This runs
    # after brand compositing, so all remaining source frames still receive the
    # same watermark treatment.  The original render output is preserved under
    # a revision-specific filename for audit/recovery.
    editorial_max = getattr(
        req,
        "editorial_max_story_seconds",
        None,
    )
    if editorial_max is not None:
        try:
            editorial_max = float(editorial_max)
        except Exception:
            editorial_max = None

    if editorial_max is not None and editorial_max > 0:
        output_rel = (result.get("output") or {}).get("relative_path")
        output_path = (
            _safe_workspace_path(output_rel)
            if output_rel
            else None
        )
        end_events = [
            event
            for event in (result.get("timeline") or [])
            if event.get("kind") == "end_card_replace"
        ]
        if output_path is not None and output_path.exists() and end_events:
            own_end_seconds = float(
                end_events[-1].get("replacement_duration_seconds") or 0.0
            )
            output_info = _probe_media(output_path)
            output_seconds = float(
                output_info.get("duration_seconds") or 0.0
            )
            story_available = max(0.0, output_seconds - own_end_seconds)
            min_story = max(
                0.0,
                float(getattr(req, "editorial_min_story_seconds", 0.0) or 0.0),
            )
            story_seconds = min(story_available, editorial_max)
            if min_story > 0:
                story_seconds = max(min(story_available, min_story), story_seconds)

            if (
                own_end_seconds > 0.05
                and story_seconds > 0.05
                and story_seconds < story_available - 0.05
            ):
                ffmpeg = shutil.which("ffmpeg")
                if not ffmpeg:
                    raise HTTPException(
                        status_code=500,
                        detail={
                            "stage": "editorial_compaction",
                            "error": "ffmpeg_not_available",
                        },
                    )
                compact_path = output_path.with_name(
                    output_path.stem + ".editorial-compact.mp4"
                )
                cmd = [
                    ffmpeg,
                    "-y",
                    "-i",
                    str(output_path),
                    "-filter_complex",
                    (
                        f"[0:v]trim=duration={story_seconds:.6f},"
                        "setpts=PTS-STARTPTS[v0];"
                        f"[0:a]atrim=duration={story_seconds:.6f},"
                        "asetpts=PTS-STARTPTS[a0];"
                        f"[0:v]trim=start={story_available:.6f}:"
                        f"duration={own_end_seconds:.6f},"
                        "setpts=PTS-STARTPTS[v1];"
                        f"[0:a]atrim=start={story_available:.6f}:"
                        f"duration={own_end_seconds:.6f},"
                        "asetpts=PTS-STARTPTS[a1];"
                        "[v0][a0][v1][a1]concat=n=2:v=1:a=1[v][a]"
                    ),
                    "-map",
                    "[v]",
                    "-map",
                    "[a]",
                    "-c:v",
                    "libx264",
                    "-crf",
                    str(int(req.crf)),
                    "-preset",
                    str(req.preset),
                    "-pix_fmt",
                    "yuv420p",
                    "-c:a",
                    "aac",
                    "-b:a",
                    str(req.audio_bitrate),
                    "-movflags",
                    "+faststart",
                    str(compact_path),
                ]
                _run_ffmpeg_checked(cmd, "editorial_compaction")
                compact_info = _probe_media(compact_path)
                if not (
                    compact_path.exists()
                    and compact_info.get("has_video")
                    and compact_info.get("has_audio")
                ):
                    raise HTTPException(
                        status_code=500,
                        detail={
                            "stage": "editorial_compaction",
                            "error": "compact_output_invalid",
                        },
                    )
                output_path.unlink(missing_ok=True)
                compact_path.replace(output_path)
                result["output"].update(
                    {
                        "duration_seconds": round(
                            float(compact_info.get("duration_seconds") or 0.0),
                            3,
                        ),
                        "has_video": bool(compact_info.get("has_video")),
                        "has_audio": bool(compact_info.get("has_audio")),
                    }
                )
                result.setdefault("timeline", []).append(
                    {
                        "kind": "editorial_compaction",
                        "story_retained_seconds": round(story_seconds, 3),
                        "story_available_seconds": round(story_available, 3),
                        "own_end_card_seconds": round(own_end_seconds, 3),
                        "target_max_story_seconds": round(editorial_max, 3),
                    }
                )
                result.setdefault("summary", {})[
                    "editorial_compaction_applied"
                ] = True
            else:
                result.setdefault("summary", {})[
                    "editorial_compaction_applied"
                ] = False

    result[
        "version"
    ] = "0.13.0"

    result[
        "render_stage"
    ] = "PRODUCTION_CANDIDATE"

    result[
        "brand_asset_validation"
    ] = validation

    result.setdefault(
        "summary",
        {},
    )[
        "engineering_placeholders_allowed"
    ] = False

    result["execution_route"] = execution_route
    result["summary"]["watermark_present"] = execution_route["watermark"]["present"]
    result["summary"]["watermark_classification"] = execution_route["watermark"]["classification"]
    result["summary"]["dynamic_moving_watermark_processing_enabled"] = execution_route[
        "watermark"
    ]["dynamic_present"]
    result["summary"]["dynamic_watermark_treatment"] = execution_route[
        "watermark"
    ]["dynamic_strategy"]
    result["summary"]["persistent_watermark_treatment"] = execution_route[
        "watermark"
    ]["fixed_strategy"]
    result["summary"]["own_brand_overlay_for_fixed_watermarks"] = execution_route[
        "watermark"
    ]["own_brand_overlay_for_fixed_watermarks"]
    result["summary"]["own_brand_overlay_for_dynamic_watermarks"] = False
    result["summary"]["mid_promo_treatment"] = execution_route["editorial"]["mid_promo_strategy"]
    result["summary"]["end_card_treatment"] = execution_route["editorial"]["end_card_strategy"]

    result[
        "summary"
    ][
        "dark_diagonal_watermark_processing_enabled"
    ] = False

    # A cover is mandatory for a source with validated geometry (or when an
    # advanced caller explicitly requires it).  A merely similar, uncalibrated
    # layout remains a review case instead of causing every production task to
    # fail after the renderer correctly declines to reuse stale coordinates.
    result["summary"]["diagonal_dynamic_watermark_required"] = bool(
        False
    )

    result["summary"]["dark_diagonal_watermark_cover_frames"] = int(
        (result.get("visual_base") or {}).get("diagonal_brand_cover_frames")
        or 0
    )
    result["summary"]["dynamic_watermark_singleton_tracks_skipped"] = True
    result["summary"]["overlapping_bottom_brand_actions_deduplicated"] = True

    result[
        "summary"
    ][
        "production_candidate"
    ] = True

    output_rel = (
        (
            result.get(
                "output"
            )
            or {}
        ).get(
            "relative_path"
        )
    )

    qc = {
        "output_exists": False,
        "output_has_video": False,
        "output_has_audio": False,
        "duration_seconds": None,
        "qc_pass": False,
    }

    if output_rel:
        output_path = _safe_workspace_path(
            output_rel
        )

        media = _probe_media(
            output_path
        )

        qc.update(
            {
                "output_exists": output_path.exists(),
                "output_has_video": bool(
                    media.get("has_video")
                ),
                "output_has_audio": bool(
                    media.get("has_audio")
                ),
                "duration_seconds": media.get(
                    "duration_seconds"
                ),
            }
        )

        qc["qc_pass"] = bool(
            qc["output_exists"]
            and qc["output_has_video"]
            and qc["output_has_audio"]
            and float(
                qc["duration_seconds"]
                or 0.0
            )
            > 0.5
        )

    result[
        "production_qc"
    ] = qc

    report_rel = (
        result.get(
            "report_relative_path"
        )
    )

    if report_rel:
        _safe_workspace_path(
            report_rel
        ).write_text(
            json.dumps(
                result,
                ensure_ascii=False,
                indent=2,
            ),
            encoding="utf-8",
        )

    return result




# ---------------------------------------------------------------------------
# v0.14.0 Auto Brand Asset Discovery + Language Census / Language Plan
#
# Brand assets:
#   workspace/assets/brand/<brand-slug>/
#       logo.png
#       icon.png
#       mid-promo.mp4
#       end-card.mp4 or end-card.png
#
# Missing registry asset paths are automatically filled from that directory.
#
# Language stage:
#   1. Language Census
#      - Whisper speech language + timed transcript
#      - optional Whisper English translation diagnostic channel
#      - OCR visible-text inventory
#      - burned-in subtitle presence / dominant subtitle region
#
#   2. Language Plan
#      - determine KEEP / REPLACE / GENERATE / REVIEW actions
#      - no destructive render yet
#
# Dark diagonal watermark remains PARKED.
# ---------------------------------------------------------------------------


def _slugify_asset_dir(value):
    raw = str(
        value
        or ""
    ).strip().lower()

    chars = []

    for ch in raw:
        if (
            ch.isalnum()
            or ch in ("-", "_")
        ):
            chars.append(ch)
        elif ch.isspace():
            chars.append("-")

    slug = "".join(
        chars
    ).strip("-_")

    return (
        slug
        or "default"
    )


def _brand_asset_language_code(
    language=None,
    language_code=None,
):
    code = re.sub(
        r"[^A-Za-z]",
        "",
        str(
            language_code
            or ""
        ),
    ).lower()

    if 2 <= len(code) <= 3:
        return code

    mapping = {
        "english": "en",
        "spanish": "es",
        "portuguese": "pt",
        "brazilian portuguese": "pt",
        "indonesian": "id",
        "bahasa indonesia": "id",
        "thai": "th",
        "japanese": "ja",
        "korean": "ko",
        "french": "fr",
        "german": "de",
        "italian": "it",
        "turkish": "tr",
        "arabic": "ar",
        "vietnamese": "vi",
        "malay": "ms",
        "filipino": "tl",
        "tagalog": "tl",
        "hindi": "hi",
        "bengali": "bn",
        "russian": "ru",
        "chinese": "zh",
        "traditional chinese": "zh",
        "simplified chinese": "zh",
    }

    return mapping.get(
        str(
            language
            or ""
        ).strip().casefold()
    )


def _brand_asset_language_candidates(
    asset_directory,
    stem,
    extensions,
    *,
    language=None,
    language_code=None,
):
    """
    Language-aware drop-in slots.

    Priority:
      stem.<lang>.<ext>
      stem.<ext>

    Example:
      mid-promo.en.mp4
      mid-promo.mp4
    """
    lang = (
        _brand_asset_language_code(
            language,
            language_code,
        )
    )

    candidates = []

    if lang:
        for extension in extensions:
            candidates.append(
                asset_directory
                / (
                    stem
                    + "."
                    + lang
                    + "."
                    + extension
                )
            )

    for extension in extensions:
        candidates.append(
            asset_directory
            / (
                stem
                + "."
                + extension
            )
        )

    return candidates


def _brand_asset_first_existing(
    candidates,
):
    for candidate in candidates:
        if candidate.is_file():
            return candidate

    return None


def _brand_asset_match_key(
    value,
):
    return re.sub(
        r"[^a-z0-9]",
        "",
        str(
            value
            or ""
        ).lower(),
    )


def _brand_asset_directory_for_profile(
    profile,
):
    """
    Resolve a drop-in brand asset folder robustly.

    Examples that must resolve to the same directory:
      profile brand_name = FloatboatFDE
      profile_id         = floatboatfde-e6af4d0a11
      asset directory    = workspace/assets/brand/floatboat-fde/

    Earlier exact slug matching treated "floatboatfde" and "floatboat-fde" as
    different folders, which could make mid-promo.mp4 appear missing even when
    it was present on disk.
    """
    base = (
        WORKSPACE
        / "assets"
        / "brand"
    )

    preferred_values = [
        profile.get(
            "brand_name"
        ),
        profile.get(
            "product_name"
        ),
        profile.get(
            "profile_id"
        ),
    ]

    profile_id = str(
        profile.get(
            "profile_id"
        )
        or ""
    ).strip()

    # Generated profile IDs end in -<10 hex chars>.  The prefix is also a
    # useful asset-directory identity.
    stripped_profile_id = re.sub(
        r"-[0-9a-fA-F]{10}$",
        "",
        profile_id,
    )

    if stripped_profile_id:
        preferred_values.append(
            stripped_profile_id
        )

    # First try exact slug forms.
    for value in preferred_values:
        if not value:
            continue

        candidate = (
            base
            / _slugify_asset_dir(
                value
            )
        )

        if candidate.is_dir():
            return candidate

    # Then scan drop-in directories by separator-insensitive identity.
    wanted = {
        _brand_asset_match_key(
            value
        )
        for value in preferred_values
        if value
    }

    wanted.discard(
        ""
    )

    if base.is_dir():
        matches = []

        for candidate in (
            base.iterdir()
        ):
            if not candidate.is_dir():
                continue

            key = (
                _brand_asset_match_key(
                    candidate.name
                )
            )

            if key in wanted:
                matches.append(
                    candidate
                )

        if matches:
            # Deterministic result.
            return sorted(
                matches,
                key=lambda p: (
                    p.name.lower()
                ),
            )[
                0
            ]

    # Preserve historical fallback path for diagnostics / future file drops.
    brand_name = (
        profile.get(
            "brand_name"
        )
        or profile.get(
            "product_name"
        )
        or profile.get(
            "profile_id"
        )
        or "default"
    )

    return (
        base
        / _slugify_asset_dir(
            brand_name
        )
    )


def _first_existing_candidate(
    directory,
    names,
):
    for name in names:
        path = (
            directory
            / name
        )

        if path.exists():
            return path

    return None


def _autodiscover_brand_assets(
    profile,
):
    directory = (
        _brand_asset_directory_for_profile(
            profile
        )
    )

    assets = profile.setdefault(
        "assets",
        {},
    )

    candidates = {
        "logo_image_relative_path": [
            "logo.png",
            "logo.webp",
            "logo.jpg",
            "logo.jpeg",
        ],
        "icon_image_relative_path": [
            "icon.png",
            "icon.webp",
            "icon.jpg",
            "icon.jpeg",
        ],
        "mid_promo_video_relative_path": [
            "mid-promo.mp4",
            "mid_promo.mp4",
            "promo.mp4",
        ],
        "end_card_video_relative_path": [
            "end-card.mp4",
            "end_card.mp4",
        ],
        "end_card_image_relative_path": [
            "end-card.png",
            "end_card.png",
            "end-card.webp",
            "end_card.webp",
            "end-card.jpg",
            "end_card.jpg",
        ],
    }

    discovered = {}

    for key, names in (
        candidates.items()
    ):
        configured = (
            assets.get(
                key
            )
        )

        if configured:
            continue

        found = (
            _first_existing_candidate(
                directory,
                names,
            )
        )

        if found is None:
            continue

        rel = (
            found
            .relative_to(
                WORKSPACE
            )
            .as_posix()
        )

        assets[
            key
        ] = rel

        discovered[
            key
        ] = rel

    return {
        "asset_directory_relative_path": (
            directory
            .relative_to(
                WORKSPACE
            )
            .as_posix()
        ),
        "discovered": discovered,
    }


_validate_brand_assets_v0130 = (
    _validate_brand_assets
)


def _validate_brand_assets(
    profile,
    *,
    language=None,
    language_code=None,
):
    """
    Compatibility wrapper around the language-aware validator.

    v0.13-era generic asset autodiscovery runs first so logo/icon and fallback
    mid-promo/end-card slots can still populate profile["assets"].

    The language-aware validator then selects:
      mid-promo.<lang>.mp4 -> mid-promo.mp4
      end-card.<lang>.mp4/png -> end-card.mp4/png

    Do NOT replace its autodiscovery dict: it carries the selected language
    paths consumed later by the Operator render path.
    """
    discovery = (
        _autodiscover_brand_assets(
            profile
        )
    )

    result = (
        _validate_brand_assets_v0130(
            profile,
            language=language,
            language_code=language_code,
        )
    )

    autodiscovery = (
        result.setdefault(
            "autodiscovery",
            {},
        )
    )

    autodiscovery[
        "asset_directory_relative_path"
    ] = (
        discovery.get(
            "asset_directory_relative_path"
        )
    )

    autodiscovery[
        "discovered"
    ] = (
        discovery.get(
            "discovered"
        )
        or {}
    )

    return result


class LanguageCensusRequest(BaseModel):
    video_relative_path: str

    sample_interval_seconds: float = 1.25
    max_ocr_samples: int = 140

    ocr_language: str = "eng"
    ocr_min_confidence: float = 22.0
    ocr_scale: float = 1.5

    enable_whisper: bool = True
    enable_whisper_translation: bool = True

    whisper_model: Optional[str] = None
    whisper_device: str = "cpu"
    whisper_compute_type: str = "int8"

    save_debug_frames: bool = True
    max_debug_frames: int = 12

    # Top brand is not part of language localization.
    ignore_top_ratio: float = 0.16


class LanguageProcessingPlanRequest(BaseModel):
    census_report_relative_path: str

    target_language: str
    target_language_name: Optional[str] = None

    generate_target_subtitles: bool = True
    replace_burned_in_subtitles: bool = True
    replace_other_visual_text: bool = True
    dub_speech: bool = True

    # Whisper can automatically translate speech only into English.
    use_whisper_english_translation_if_target_english: bool = True

    # Optional externally prepared translation segments.
    # Each item:
    # {
    #   "start_seconds": 1.2,
    #   "end_seconds": 3.4,
    #   "text": "..."
    # }
    target_translation_segments: Optional[
        list[
            dict[
                str,
                Any,
            ]
        ]
    ] = None


def _ocr_lines_from_words(
    words,
    frame_width,
    frame_height,
):
    groups = defaultdict(
        list
    )

    for word in (
        words
        or []
    ):
        groups[
            (
                word.get(
                    "block_num"
                ),
                word.get(
                    "par_num"
                ),
                word.get(
                    "line_num"
                ),
            )
        ].append(
            word
        )

    lines = []

    for group_words in (
        groups.values()
    ):
        group_words.sort(
            key=lambda w: int(
                w.get(
                    "word_num"
                )
                or 0
            )
        )

        text_value = " ".join(
            str(
                w.get(
                    "text"
                )
                or ""
            ).strip()
            for w in group_words
            if str(
                w.get(
                    "text"
                )
                or ""
            ).strip()
        ).strip()

        if not text_value:
            continue

        boxes = [
            {
                "x": int(
                    w["x"]
                ),
                "y": int(
                    w["y"]
                ),
                "width": int(
                    w["width"]
                ),
                "height": int(
                    w["height"]
                ),
            }
            for w in group_words
        ]

        bbox = _clip_bbox(
            _bbox_union(
                boxes
            ),
            int(
                frame_width
            ),
            int(
                frame_height
            ),
        )

        avg_conf = float(
            np.mean(
                [
                    float(
                        w.get(
                            "conf"
                        )
                        or 0.0
                    )
                    for w in group_words
                ]
            )
        )

        y_center = (
            bbox["y"]
            + bbox["height"]
            / 2.0
        ) / float(
            max(
                1,
                frame_height,
            )
        )

        y_bottom = (
            bbox["y"]
            + bbox["height"]
        ) / float(
            max(
                1,
                frame_height,
            )
        )

        x_center = (
            bbox["x"]
            + bbox["width"]
            / 2.0
        ) / float(
            max(
                1,
                frame_width,
            )
        )

        if y_bottom >= 0.82:
            role = (
                "bottom_subtitle_candidate"
            )
        elif y_center <= 0.20:
            role = (
                "top_overlay"
            )
        elif (
            0.28
            <= y_center
            <= 0.72
        ):
            role = (
                "center_visual_text"
            )
        elif y_center > 0.72:
            role = (
                "lower_visual_text"
            )
        else:
            role = (
                "other_visual_text"
            )

        lines.append(
            {
                "text": text_value,
                "normalized_text": (
                    _normalize_text(
                        text_value
                    )
                ),
                "confidence": round(
                    avg_conf,
                    3,
                ),
                "bbox": bbox,
                "role": role,
                "normalized_center": {
                    "x": round(
                        x_center,
                        4,
                    ),
                    "y": round(
                        y_center,
                        4,
                    ),
                },
            }
        )

    return lines


def _dominant_bottom_subtitle_bbox(
    occurrences,
    width,
    height,
):
    boxes = [
        item["bbox"]
        for item in occurrences
        if item.get(
            "role"
        )
        == "bottom_subtitle_candidate"
    ]

    if not boxes:
        return None

    x1 = int(round(
        _quantile(
            [
                b["x"]
                for b in boxes
            ],
            0.20,
            0,
        )
    ))

    y1 = int(round(
        _quantile(
            [
                b["y"]
                for b in boxes
            ],
            0.20,
            int(
                height * 0.75
            ),
        )
    ))

    x2 = int(round(
        _quantile(
            [
                b["x"]
                + b["width"]
                for b in boxes
            ],
            0.80,
            width,
        )
    ))

    y2 = int(round(
        _quantile(
            [
                b["y"]
                + b["height"]
                for b in boxes
            ],
            0.80,
            height,
        )
    ))

    pad_x = max(
        8,
        int(
            width * 0.025
        ),
    )

    pad_y = max(
        6,
        int(
            height * 0.008
        ),
    )

    return _clip_bbox(
        {
            "x": max(
                0,
                x1 - pad_x,
            ),
            "y": max(
                0,
                y1 - pad_y,
            ),
            "width": max(
                1,
                (
                    x2
                    - x1
                    + pad_x * 2
                ),
            ),
            "height": max(
                1,
                (
                    y2
                    - y1
                    + pad_y * 2
                ),
            ),
        },
        int(width),
        int(height),
    )


def _language_census_sync(
    req: LanguageCensusRequest
):
    video_path = (
        _safe_workspace_path(
            req.video_relative_path
        )
    )

    cap = cv2.VideoCapture(
        str(
            video_path
        )
    )

    if not cap.isOpened():
        raise HTTPException(
            status_code=422,
            detail={
                "stage": (
                    "language_census"
                ),
                "error": (
                    "could_not_open_video"
                ),
            },
        )

    try:
        meta = _video_metadata(
            cap
        )
    finally:
        cap.release()

    fps = float(
        meta.get(
            "fps"
        )
        or 30.0
    )

    width = int(
        meta.get(
            "width"
        )
        or 0
    )

    height = int(
        meta.get(
            "height"
        )
        or 0
    )

    duration = float(
        meta.get(
            "duration_seconds"
        )
        or 0.0
    )

    if duration <= 0:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": (
                    "language_census"
                ),
                "error": (
                    "invalid_video_duration"
                ),
            },
        )

    # Reuse the already accepted Whisper implementation.
    whisper = (
        _whisper_model_and_segments(
            video_path,
            req,
        )
    )

    requested_interval = max(
        0.5,
        float(
            req.sample_interval_seconds
        ),
    )

    effective_interval = max(
        requested_interval,
        duration
        / float(
            max(
                1,
                int(
                    req.max_ocr_samples
                ),
            )
        ),
    )

    cap = cv2.VideoCapture(
        str(
            video_path
        )
    )

    occurrences = []
    sample_count = 0
    bottom_sample_times = set()

    timestamp = (
        _app_now().strftime(
            "%Y-%m-%d_%H%M%S"
        )
    )

    out_dir = (
        WORKSPACE
        / "review"
        / "language_census"
        / timestamp
        / video_path.stem
    )

    debug_dir = (
        out_dir
        / "debug"
    )

    out_dir.mkdir(
        parents=True,
        exist_ok=True,
    )

    if bool(
        req.save_debug_frames
    ):
        debug_dir.mkdir(
            parents=True,
            exist_ok=True,
        )

    debug_saved = 0
    t = 0.0

    try:
        while (
            t
            <= duration
            + 1e-6
            and sample_count
            < int(
                req.max_ocr_samples
            )
        ):
            cap.set(
                cv2.CAP_PROP_POS_MSEC,
                t * 1000.0,
            )

            ok, frame = cap.read()

            if (
                not ok
                or frame is None
            ):
                t += (
                    effective_interval
                )
                continue

            try:
                words = _tesseract_words(
                    frame,
                    str(
                        req.ocr_language
                    ),
                    float(
                        req.ocr_min_confidence
                    ),
                    float(
                        req.ocr_scale
                    ),
                )
            except Exception as exc:
                cap.release()

                raise HTTPException(
                    status_code=422,
                    detail={
                        "stage": (
                            "language_census"
                        ),
                        "error": (
                            "ocr_failed"
                        ),
                        "message": str(
                            exc
                        )[:600],
                    },
                )

            lines = (
                _ocr_lines_from_words(
                    words,
                    width,
                    height,
                )
            )

            kept_lines = []

            for line in lines:
                bbox = line[
                    "bbox"
                ]

                top_ratio = (
                    bbox["y"]
                    / float(
                        max(
                            1,
                            height,
                        )
                    )
                )

                # Skip the known top brand/watermark area from localization
                # inventory. It belongs to branding, not language.
                if (
                    line.get(
                        "role"
                    )
                    == "top_overlay"
                    and top_ratio
                    <= float(
                        req.ignore_top_ratio
                    )
                ):
                    continue

                record = {
                    **line,
                    "time_seconds": round(
                        t,
                        3,
                    ),
                }

                occurrences.append(
                    record
                )

                kept_lines.append(
                    line
                )

                if (
                    line.get(
                        "role"
                    )
                    == (
                        "bottom_subtitle_candidate"
                    )
                ):
                    bottom_sample_times.add(
                        round(
                            t,
                            3,
                        )
                    )

            if (
                bool(
                    req.save_debug_frames
                )
                and kept_lines
                and debug_saved
                < int(
                    req.max_debug_frames
                )
            ):
                annotated = (
                    frame.copy()
                )

                for line in kept_lines:
                    b = line[
                        "bbox"
                    ]

                    cv2.rectangle(
                        annotated,
                        (
                            int(
                                b["x"]
                            ),
                            int(
                                b["y"]
                            ),
                        ),
                        (
                            int(
                                b["x"]
                                + b["width"]
                            ),
                            int(
                                b["y"]
                                + b["height"]
                            ),
                        ),
                        (
                            255,
                            255,
                            255,
                        ),
                        2,
                    )

                debug_path = (
                    debug_dir
                    / (
                        f"ocr-{t:07.2f}.jpg"
                    )
                )

                cv2.imwrite(
                    str(
                        debug_path
                    ),
                    annotated,
                )

                debug_saved += 1

            sample_count += 1
            t += effective_interval

    finally:
        cap.release()

    role_counts = defaultdict(
        int
    )

    for item in occurrences:
        role_counts[
            str(
                item.get(
                    "role"
                )
            )
        ] += 1

    subtitle_bbox = (
        _dominant_bottom_subtitle_bbox(
            occurrences,
            width,
            height,
        )
    )

    bottom_sample_ratio = (
        len(
            bottom_sample_times
        )
        / float(
            max(
                1,
                sample_count,
            )
        )
    )

    bottom_occurrence_count = (
        role_counts[
            "bottom_subtitle_candidate"
        ]
    )

    if (
        bottom_occurrence_count
        >= 3
        and bottom_sample_ratio
        >= 0.08
    ):
        subtitle_presence = (
            "PRESENT"
        )
    elif (
        bottom_occurrence_count
        >= 1
    ):
        subtitle_presence = (
            "UNCERTAIN"
        )
    else:
        subtitle_presence = (
            "ABSENT"
        )

    speech_segments = (
        whisper.get(
            "segments"
        )
        or []
    )

    translated_segments = (
        whisper.get(
            "translated_segments"
        )
        or []
    )

    result = {
        "ok": True,
        "version": "0.17.0",
        "mode": "language_census",
        "source": {
            "relative_path": (
                video_path
                .relative_to(
                    WORKSPACE
                )
                .as_posix()
            ),
        },
        "video": meta,
        "speech": {
            "status": (
                whisper.get(
                    "status"
                )
            ),
            "detected_language": (
                whisper.get(
                    "language"
                )
            ),
            "model": (
                whisper.get(
                    "model"
                )
            ),
            "segment_count": len(
                speech_segments
            ),
            "segments": (
                speech_segments
            ),
            "english_translation_available": bool(
                translated_segments
            ),
            "english_translation_segments": (
                translated_segments
            ),
            "error": (
                whisper.get(
                    "error"
                )
            ),
            "translation_error": (
                whisper.get(
                    "translation_error"
                )
            ),
        },
        "visual_text": {
            "ocr_language": str(
                req.ocr_language
            ),
            "sample_interval_seconds": round(
                effective_interval,
                4,
            ),
            "sample_count": int(
                sample_count
            ),
            "occurrence_count": len(
                occurrences
            ),
            "role_counts": dict(
                role_counts
            ),
            "occurrences": (
                occurrences
            ),
        },
        "burned_in_subtitles": {
            "presence": (
                subtitle_presence
            ),
            "sample_ratio": round(
                bottom_sample_ratio,
                4,
            ),
            "occurrence_count": int(
                bottom_occurrence_count
            ),
            "dominant_bbox": (
                subtitle_bbox
            ),
        },
        "summary": {
            "speech_language_detected": bool(
                whisper.get(
                    "language"
                )
            ),
            "speech_segment_count": len(
                speech_segments
            ),
            "burned_in_subtitles": (
                subtitle_presence
            ),
            "other_visual_text_occurrence_count": sum(
                count
                for role, count in (
                    role_counts.items()
                )
                if role
                != (
                    "bottom_subtitle_candidate"
                )
            ),
            "manual_review_required_before_language_render": True,
            "source_video_modified": False,
        },
        "output_relative_dir": (
            out_dir
            .relative_to(
                WORKSPACE
            )
            .as_posix()
        ),
        "notes": {
            "ocr": (
                "OCR is an inventory channel. OCR language packs installed in "
                "the container limit recognition quality; Latin-script text can "
                "still often be located with eng."
            ),
            "speech": (
                "Whisper translation is English-only and is used as a diagnostic "
                "language-normalized channel. Arbitrary target-language translation "
                "is not silently invented by the local pipeline."
            ),
            "top_brand": (
                "Top branding region is excluded from language-localization inventory."
            ),
        },
    }

    report_path = (
        out_dir
        / (
            f"{video_path.stem}"
            ".language-census.json"
        )
    )

    result[
        "report_relative_path"
    ] = (
        report_path
        .relative_to(
            WORKSPACE
        )
        .as_posix()
    )

    report_path.write_text(
        json.dumps(
            result,
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )

    return result


def _normalize_language_code(
    value,
):
    value = str(
        value
        or ""
    ).strip().lower()

    aliases = {
        "english": "en",
        "eng": "en",
        "en-us": "en",
        "en-gb": "en",
        "portuguese": "pt",
        "por": "pt",
        "pt-br": "pt",
        "spanish": "es",
        "spa": "es",
        "french": "fr",
        "fra": "fr",
        "german": "de",
        "deu": "de",
        "indonesian": "id",
        "vietnamese": "vi",
        "thai": "th",
        "japanese": "ja",
        "korean": "ko",
        "chinese": "zh",
        "zh-cn": "zh",
        "zh-tw": "zh",
    }

    return (
        aliases.get(
            value,
            value,
        )
    )


def _language_plan_sync(
    req: LanguageProcessingPlanRequest
):
    census_path, census = (
        _read_json_workspace(
            req.census_report_relative_path,
            "language_plan",
        )
    )

    if (
        census.get(
            "mode"
        )
        != "language_census"
    ):
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "language_plan",
                "error": (
                    "expected_language_census_report"
                ),
            },
        )

    source_language = (
        _normalize_language_code(
            (
                census.get(
                    "speech"
                )
                or {}
            ).get(
                "detected_language"
            )
        )
    )

    target_language = (
        _normalize_language_code(
            req.target_language
        )
    )

    speech = (
        census.get(
            "speech"
        )
        or {}
    )

    original_segments = (
        speech.get(
            "segments"
        )
        or []
    )

    translated_en = (
        speech.get(
            "english_translation_segments"
        )
        or []
    )

    supplied_target = (
        req.target_translation_segments
        or []
    )

    if (
        source_language
        and target_language
        and source_language
        == target_language
    ):
        translation_status = (
            "NOT_NEEDED"
        )
        target_segments = (
            original_segments
        )
        translation_source = (
            "original_speech"
        )

    elif (
        target_language
        == "en"
        and bool(
            req.use_whisper_english_translation_if_target_english
        )
        and translated_en
    ):
        translation_status = (
            "READY"
        )
        target_segments = (
            translated_en
        )
        translation_source = (
            "whisper_translate_to_english"
        )

    elif supplied_target:
        translation_status = (
            "READY"
        )
        target_segments = (
            supplied_target
        )
        translation_source = (
            "provided_target_translation_segments"
        )

    else:
        translation_status = (
            "TARGET_TRANSLATION_REQUIRED"
        )
        target_segments = []
        translation_source = None

    subtitle_info = (
        census.get(
            "burned_in_subtitles"
        )
        or {}
    )

    subtitle_presence = (
        subtitle_info.get(
            "presence"
        )
        or "ABSENT"
    )

    actions = []

    if bool(
        req.dub_speech
    ):
        if (
            source_language
            and target_language
            and source_language
            == target_language
        ):
            actions.append(
                {
                    "type": "speech",
                    "operation": "KEEP",
                    "status": "AUTO",
                    "reason": (
                        "source_language_equals_target_language"
                    ),
                }
            )
        else:
            actions.append(
                {
                    "type": "speech",
                    "operation": "DUB",
                    "status": (
                        "REVIEW"
                        if translation_status
                        == "READY"
                        else "WAITING"
                    ),
                    "translation_status": (
                        translation_status
                    ),
                    "translation_source": (
                        translation_source
                    ),
                    "tts_status": (
                        "NOT_CONFIGURED"
                    ),
                    "segment_count": len(
                        target_segments
                    ),
                }
            )

    if bool(
        req.generate_target_subtitles
    ):
        if (
            source_language
            and target_language
            and source_language
            == target_language
            and subtitle_presence
            == "PRESENT"
        ):
            subtitle_operation = (
                "KEEP"
            )
            subtitle_status = (
                "AUTO"
            )
        elif (
            subtitle_presence
            == "PRESENT"
            and bool(
                req.replace_burned_in_subtitles
            )
        ):
            subtitle_operation = (
                "COVER_AND_REDRAW"
            )
            subtitle_status = (
                "REVIEW"
                if translation_status
                in (
                    "READY",
                    "NOT_NEEDED",
                )
                else "WAITING"
            )
        else:
            subtitle_operation = (
                "ADD_TARGET_SUBTITLES"
            )
            subtitle_status = (
                "REVIEW"
                if translation_status
                in (
                    "READY",
                    "NOT_NEEDED",
                )
                else "WAITING"
            )

        actions.append(
            {
                "type": "subtitles",
                "operation": (
                    subtitle_operation
                ),
                "status": (
                    subtitle_status
                ),
                "source_burned_in_presence": (
                    subtitle_presence
                ),
                "source_bbox": (
                    subtitle_info.get(
                        "dominant_bbox"
                    )
                ),
                "target_segment_count": len(
                    target_segments
                ),
                "translation_status": (
                    translation_status
                ),
            }
        )

    other_visual_count = int(
        (
            census.get(
                "summary"
            )
            or {}
        ).get(
            "other_visual_text_occurrence_count"
        )
        or 0
    )

    if (
        bool(
            req.replace_other_visual_text
        )
        and other_visual_count
        > 0
    ):
        actions.append(
            {
                "type": "visual_text",
                "operation": (
                    "REPLACE_VISIBLE_TEXT"
                ),
                "status": "REVIEW",
                "occurrence_count": (
                    other_visual_count
                ),
                "policy": (
                    "detect_and_group_first; do not erase story graphics blindly"
                ),
            }
        )

    plan_ready = all(
        action.get(
            "status"
        )
        not in (
            "WAITING",
        )
        for action in actions
    )

    timestamp = (
        _app_now().strftime(
            "%Y-%m-%d_%H%M%S"
        )
    )

    source_rel = (
        (
            census.get(
                "source"
            )
            or {}
        ).get(
            "relative_path"
        )
    )

    stem = (
        Path(
            source_rel
            or "video"
        ).stem
    )

    out_dir = (
        WORKSPACE
        / "review"
        / "language_plan"
        / timestamp
        / stem
    )

    out_dir.mkdir(
        parents=True,
        exist_ok=True,
    )

    result = {
        "ok": True,
        "version": "0.17.0",
        "mode": "language_processing_plan",
        "source": {
            "video_relative_path": (
                source_rel
            ),
            "census_report_relative_path": (
                census_path
                .relative_to(
                    WORKSPACE
                )
                .as_posix()
            ),
        },
        "languages": {
            "source_language": (
                source_language
            ),
            "target_language": (
                target_language
            ),
            "target_language_name": (
                req.target_language_name
            ),
        },
        "translation": {
            "status": (
                translation_status
            ),
            "source": (
                translation_source
            ),
            "target_segments": (
                target_segments
            ),
        },
        "actions": actions,
        "summary": {
            "action_count": len(
                actions
            ),
            "auto_count": sum(
                1
                for a in actions
                if a.get(
                    "status"
                )
                == "AUTO"
            ),
            "review_count": sum(
                1
                for a in actions
                if a.get(
                    "status"
                )
                == "REVIEW"
            ),
            "waiting_count": sum(
                1
                for a in actions
                if a.get(
                    "status"
                )
                == "WAITING"
            ),
            "translation_ready": (
                translation_status
                in (
                    "READY",
                    "NOT_NEEDED",
                )
            ),
            "language_plan_ready_for_render_development": bool(
                plan_ready
            ),
            "source_video_modified": False,
        },
        "notes": {
            "speech": (
                "DUB actions are planned but TTS/audio replacement is intentionally "
                "not rendered in v0.14.0."
            ),
            "subtitles": (
                "Burned-in subtitle geometry is identified before any cover/redraw "
                "renderer is enabled."
            ),
            "visual_text": (
                "Non-subtitle visible text remains REVIEW because UI/promo/story "
                "graphics need different replacement strategies."
            ),
        },
        "output_relative_dir": (
            out_dir
            .relative_to(
                WORKSPACE
            )
            .as_posix()
        ),
    }

    report_path = (
        out_dir
        / (
            f"{stem}"
            ".language-plan.json"
        )
    )

    result[
        "report_relative_path"
    ] = (
        report_path
        .relative_to(
            WORKSPACE
        )
        .as_posix()
    )

    report_path.write_text(
        json.dumps(
            result,
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )

    return result




# ---------------------------------------------------------------------------
# v0.14.1 Language Structure Refinement
#
# OCR census intentionally over-detects to avoid missing visible text.
# This stage converts raw OCR occurrences into persistent text tracks.
#
# Goals:
#   - preserve the accepted burned-in subtitle region
#   - suppress isolated OCR noise
#   - group repeated/nearby visual text through time
#   - separate subtitle tracks from other visual-text tracks
#   - only pass stable / repeated non-subtitle tracks to later replacement
# ---------------------------------------------------------------------------


class LanguageStructureRefineRequest(BaseModel):
    census_report_relative_path: str

    # Track association.
    max_time_gap_seconds: float = 2.75
    min_spatial_iou: float = 0.10
    max_center_distance_ratio: float = 0.18
    min_text_similarity: float = 0.20

    # Noise filtering.
    min_track_occurrences: int = 2
    min_track_duration_seconds: float = 0.50
    min_average_confidence: float = 25.0

    # Subtitle track rules.
    subtitle_min_sample_ratio: float = 0.06
    subtitle_region_iou_threshold: float = 0.18

    # Non-subtitle visual text needs stronger persistence than subtitles.
    non_subtitle_min_occurrences: int = 3
    non_subtitle_min_duration_seconds: float = 1.0

    # Keep a capped list of rejected/noise items for diagnostics.
    max_noise_examples: int = 80


def _bbox_iou(a, b):
    if not a or not b:
        return 0.0

    ax1 = float(a["x"])
    ay1 = float(a["y"])
    ax2 = ax1 + float(a["width"])
    ay2 = ay1 + float(a["height"])

    bx1 = float(b["x"])
    by1 = float(b["y"])
    bx2 = bx1 + float(b["width"])
    by2 = by1 + float(b["height"])

    ix1 = max(ax1, bx1)
    iy1 = max(ay1, by1)
    ix2 = min(ax2, bx2)
    iy2 = min(ay2, by2)

    iw = max(0.0, ix2 - ix1)
    ih = max(0.0, iy2 - iy1)

    inter = iw * ih

    if inter <= 0.0:
        return 0.0

    area_a = max(
        1.0,
        (ax2 - ax1) * (ay2 - ay1),
    )

    area_b = max(
        1.0,
        (bx2 - bx1) * (by2 - by1),
    )

    return float(
        inter
        / max(
            1.0,
            area_a + area_b - inter,
        )
    )


def _bbox_center_distance_ratio(
    a,
    b,
    width,
    height,
):
    if not a or not b:
        return 999.0

    acx = (
        float(a["x"])
        + float(a["width"]) / 2.0
    )

    acy = (
        float(a["y"])
        + float(a["height"]) / 2.0
    )

    bcx = (
        float(b["x"])
        + float(b["width"]) / 2.0
    )

    bcy = (
        float(b["y"])
        + float(b["height"]) / 2.0
    )

    dx = (
        acx - bcx
    ) / float(
        max(
            1,
            width,
        )
    )

    dy = (
        acy - bcy
    ) / float(
        max(
            1,
            height,
        )
    )

    return float(
        (dx * dx + dy * dy)
        ** 0.5
    )


def _text_similarity_ratio(
    a,
    b,
):
    a = _normalize_text(
        str(
            a
            or ""
        )
    )

    b = _normalize_text(
        str(
            b
            or ""
        )
    )

    if not a or not b:
        return 0.0

    if a == b:
        return 1.0

    # Simple token overlap + character containment.
    tokens_a = set(
        token
        for token in a.split()
        if token
    )

    tokens_b = set(
        token
        for token in b.split()
        if token
    )

    token_score = 0.0

    if tokens_a and tokens_b:
        token_score = (
            len(
                tokens_a
                & tokens_b
            )
            / float(
                max(
                    1,
                    len(
                        tokens_a
                        | tokens_b
                    ),
                )
            )
        )

    containment = 0.0

    if (
        len(a) >= 3
        and len(b) >= 3
    ):
        shorter, longer = (
            (a, b)
            if len(a) <= len(b)
            else (b, a)
        )

        if shorter in longer:
            containment = (
                len(shorter)
                / float(
                    max(
                        1,
                        len(longer),
                    )
                )
            )

    return float(
        max(
            token_score,
            containment,
        )
    )


def _track_union_bbox(
    items,
    width,
    height,
):
    boxes = [
        item.get(
            "bbox"
        )
        for item in items
        if item.get(
            "bbox"
        )
    ]

    if not boxes:
        return None

    return _clip_bbox(
        _bbox_union(
            boxes
        ),
        int(width),
        int(height),
    )


def _track_median_bbox(
    items,
    width,
    height,
):
    boxes = [
        item.get(
            "bbox"
        )
        for item in items
        if item.get(
            "bbox"
        )
    ]

    if not boxes:
        return None

    xs = [
        float(
            b["x"]
        )
        for b in boxes
    ]

    ys = [
        float(
            b["y"]
        )
        for b in boxes
    ]

    ws = [
        float(
            b["width"]
        )
        for b in boxes
    ]

    hs = [
        float(
            b["height"]
        )
        for b in boxes
    ]

    return _clip_bbox(
        {
            "x": int(round(
                np.median(
                    xs
                )
            )),
            "y": int(round(
                np.median(
                    ys
                )
            )),
            "width": max(
                1,
                int(round(
                    np.median(
                        ws
                    )
                )),
            ),
            "height": max(
                1,
                int(round(
                    np.median(
                        hs
                    )
                )),
            ),
        },
        int(width),
        int(height),
    )


def _track_canonical_text(
    items,
):
    texts = [
        str(
            item.get(
                "text"
            )
            or ""
        ).strip()
        for item in items
        if str(
            item.get(
                "text"
            )
            or ""
        ).strip()
    ]

    if not texts:
        return ""

    # Prefer the longest reasonably confident recurring OCR line.
    scored = []

    for text_value in texts:
        normalized = _normalize_text(
            text_value
        )

        recurrence = sum(
            1
            for other in texts
            if _text_similarity_ratio(
                normalized,
                other,
            )
            >= 0.45
        )

        scored.append(
            (
                recurrence,
                len(
                    normalized
                ),
                text_value,
            )
        )

    scored.sort(
        reverse=True
    )

    return scored[0][2]


def _track_role(
    items,
):
    counts = defaultdict(
        int
    )

    for item in items:
        counts[
            str(
                item.get(
                    "role"
                )
                or "unknown"
            )
        ] += 1

    if not counts:
        return "unknown"

    return max(
        counts.items(),
        key=lambda kv: kv[1],
    )[0]


def _build_ocr_tracks(
    occurrences,
    width,
    height,
    req,
):
    ordered = sorted(
        occurrences,
        key=lambda x: float(
            x.get(
                "time_seconds"
            )
            or 0.0
        ),
    )

    tracks = []

    for occurrence in ordered:
        t = float(
            occurrence.get(
                "time_seconds"
            )
            or 0.0
        )

        bbox = occurrence.get(
            "bbox"
        )

        text_value = occurrence.get(
            "text"
        )

        best_track = None
        best_score = -999.0

        for track in reversed(
            tracks
        ):
            gap = (
                t
                - float(
                    track[
                        "last_time"
                    ]
                )
            )

            if gap < -1e-6:
                continue

            if gap > float(
                req.max_time_gap_seconds
            ):
                # Tracks are chronological; older ones further back are not
                # useful once the gap is too large.
                continue

            reference_bbox = (
                track.get(
                    "last_bbox"
                )
                or track.get(
                    "median_bbox"
                )
            )

            iou = _bbox_iou(
                bbox,
                reference_bbox,
            )

            distance = (
                _bbox_center_distance_ratio(
                    bbox,
                    reference_bbox,
                    width,
                    height,
                )
            )

            text_sim = (
                _text_similarity_ratio(
                    text_value,
                    track.get(
                        "canonical_text"
                    ),
                )
            )

            same_role = (
                str(
                    occurrence.get(
                        "role"
                    )
                )
                == str(
                    track.get(
                        "role"
                    )
                )
            )

            spatial_ok = (
                iou
                >= float(
                    req.min_spatial_iou
                )
                or distance
                <= float(
                    req.max_center_distance_ratio
                )
            )

            text_ok = (
                text_sim
                >= float(
                    req.min_text_similarity
                )
            )

            if not spatial_ok:
                continue

            # Subtitle lines can change every sentence, so spatial continuity
            # is more important than text similarity for bottom subtitles.
            subtitle_like = (
                occurrence.get(
                    "role"
                )
                == "bottom_subtitle_candidate"
                and track.get(
                    "role"
                )
                == "bottom_subtitle_candidate"
            )

            if (
                not subtitle_like
                and not text_ok
                and not same_role
            ):
                continue

            score = (
                iou * 2.0
                + max(
                    0.0,
                    1.0 - distance * 4.0,
                )
                + text_sim
                + (
                    0.25
                    if same_role
                    else 0.0
                )
                - gap
                / float(
                    max(
                        0.1,
                        req.max_time_gap_seconds,
                    )
                )
                * 0.30
            )

            if score > best_score:
                best_score = score
                best_track = track

        if best_track is None:
            track = {
                "track_index": len(
                    tracks
                ),
                "items": [
                    occurrence
                ],
                "first_time": t,
                "last_time": t,
                "last_bbox": bbox,
                "median_bbox": bbox,
                "canonical_text": str(
                    text_value
                    or ""
                ),
                "role": str(
                    occurrence.get(
                        "role"
                    )
                    or "unknown"
                ),
            }

            tracks.append(
                track
            )

        else:
            best_track[
                "items"
            ].append(
                occurrence
            )

            best_track[
                "last_time"
            ] = t

            best_track[
                "last_bbox"
            ] = bbox

            best_track[
                "median_bbox"
            ] = (
                _track_median_bbox(
                    best_track[
                        "items"
                    ],
                    width,
                    height,
                )
            )

            best_track[
                "canonical_text"
            ] = (
                _track_canonical_text(
                    best_track[
                        "items"
                    ]
                )
            )

            best_track[
                "role"
            ] = (
                _track_role(
                    best_track[
                        "items"
                    ]
                )
            )

    return tracks


def _finalize_ocr_tracks(
    tracks,
    census,
    width,
    height,
    req,
):
    sample_count = int(
        (
            census.get(
                "visual_text"
            )
            or {}
        ).get(
            "sample_count"
        )
        or 0
    )

    subtitle_bbox = (
        (
            census.get(
                "burned_in_subtitles"
            )
            or {}
        ).get(
            "dominant_bbox"
        )
    )

    accepted = []
    rejected = []

    for track in tracks:
        items = (
            track.get(
                "items"
            )
            or []
        )

        if not items:
            continue

        start = min(
            float(
                item.get(
                    "time_seconds"
                )
                or 0.0
            )
            for item in items
        )

        end = max(
            float(
                item.get(
                    "time_seconds"
                )
                or 0.0
            )
            for item in items
        )

        duration = max(
            0.0,
            end - start,
        )

        confidences = [
            float(
                item.get(
                    "confidence"
                )
                or 0.0
            )
            for item in items
        ]

        avg_conf = float(
            np.mean(
                confidences
            )
        ) if confidences else 0.0

        role = (
            _track_role(
                items
            )
        )

        median_bbox = (
            _track_median_bbox(
                items,
                width,
                height,
            )
        )

        union_bbox = (
            _track_union_bbox(
                items,
                width,
                height,
            )
        )

        unique_sample_times = sorted(
            set(
                round(
                    float(
                        item.get(
                            "time_seconds"
                        )
                        or 0.0
                    ),
                    3,
                )
                for item in items
            )
        )

        sample_ratio = (
            len(
                unique_sample_times
            )
            / float(
                max(
                    1,
                    sample_count,
                )
            )
        )

        subtitle_region_iou = (
            _bbox_iou(
                median_bbox,
                subtitle_bbox,
            )
            if subtitle_bbox
            and median_bbox
            else 0.0
        )

        subtitle_track = bool(
            (
                role
                == "bottom_subtitle_candidate"
            )
            and (
                sample_ratio
                >= float(
                    req.subtitle_min_sample_ratio
                )
                or subtitle_region_iou
                >= float(
                    req.subtitle_region_iou_threshold
                )
            )
        )

        if subtitle_track:
            track_kind = (
                "SUBTITLE_TRACK"
            )

            accepted_flag = bool(
                len(items)
                >= int(
                    req.min_track_occurrences
                )
                and avg_conf
                >= float(
                    req.min_average_confidence
                )
            )

        else:
            track_kind = (
                "VISUAL_TEXT_TRACK"
            )

            accepted_flag = bool(
                len(items)
                >= int(
                    req.non_subtitle_min_occurrences
                )
                and (
                    duration
                    >= float(
                        req.non_subtitle_min_duration_seconds
                    )
                    or sample_ratio
                    >= 0.04
                )
                and avg_conf
                >= float(
                    req.min_average_confidence
                )
            )

        finalized = {
            "track_id": (
                f"text-track-{int(track['track_index']) + 1}"
            ),
            "kind": track_kind,
            "role": role,
            "start_seconds": round(
                start,
                3,
            ),
            "end_seconds": round(
                end,
                3,
            ),
            "duration_seconds": round(
                duration,
                3,
            ),
            "occurrence_count": len(
                items
            ),
            "sample_count": len(
                unique_sample_times
            ),
            "sample_ratio": round(
                sample_ratio,
                4,
            ),
            "average_confidence": round(
                avg_conf,
                3,
            ),
            "canonical_text": (
                _track_canonical_text(
                    items
                )
            ),
            "median_bbox": (
                median_bbox
            ),
            "union_bbox": (
                union_bbox
            ),
            "subtitle_region_iou": round(
                subtitle_region_iou,
                4,
            ),
            "accepted": bool(
                accepted_flag
            ),
            "examples": [
                {
                    "time_seconds": item.get(
                        "time_seconds"
                    ),
                    "text": item.get(
                        "text"
                    ),
                    "confidence": item.get(
                        "confidence"
                    ),
                    "bbox": item.get(
                        "bbox"
                    ),
                }
                for item in items[:8]
            ],
        }

        if accepted_flag:
            accepted.append(
                finalized
            )
        else:
            rejected.append(
                finalized
            )

    return accepted, rejected


def _language_structure_refine_sync(
    req: LanguageStructureRefineRequest
):
    census_path, census = (
        _read_json_workspace(
            req.census_report_relative_path,
            "language_structure_refine",
        )
    )

    if (
        census.get(
            "mode"
        )
        != "language_census"
    ):
        raise HTTPException(
            status_code=422,
            detail={
                "stage": (
                    "language_structure_refine"
                ),
                "error": (
                    "expected_language_census_report"
                ),
            },
        )

    video = (
        census.get(
            "video"
        )
        or {}
    )

    width = int(
        video.get(
            "width"
        )
        or 0
    )

    height = int(
        video.get(
            "height"
        )
        or 0
    )

    occurrences = (
        (
            census.get(
                "visual_text"
            )
            or {}
        ).get(
            "occurrences"
        )
        or []
    )

    raw_tracks = (
        _build_ocr_tracks(
            occurrences,
            width,
            height,
            req,
        )
    )

    accepted, rejected = (
        _finalize_ocr_tracks(
            raw_tracks,
            census,
            width,
            height,
            req,
        )
    )

    subtitle_tracks = [
        track
        for track in accepted
        if track.get(
            "kind"
        )
        == "SUBTITLE_TRACK"
    ]

    visual_tracks = [
        track
        for track in accepted
        if track.get(
            "kind"
        )
        == "VISUAL_TEXT_TRACK"
    ]

    # The census dominant subtitle box remains authoritative for later cleanup.
    # Track boxes are diagnostics and can refine timing, not replace the global
    # subtitle region automatically.
    subtitle_info = (
        census.get(
            "burned_in_subtitles"
        )
        or {}
    )

    source_rel = (
        (
            census.get(
                "source"
            )
            or {}
        ).get(
            "relative_path"
        )
    )

    stem = (
        Path(
            source_rel
            or "video"
        ).stem
    )

    timestamp = (
        _app_now().strftime(
            "%Y-%m-%d_%H%M%S"
        )
    )

    out_dir = (
        WORKSPACE
        / "review"
        / "language_structure_refinement"
        / timestamp
        / stem
    )

    out_dir.mkdir(
        parents=True,
        exist_ok=True,
    )

    result = {
        "ok": True,
        "version": "0.17.0",
        "mode": (
            "language_structure_refinement"
        ),
        "source": {
            "video_relative_path": (
                source_rel
            ),
            "census_report_relative_path": (
                census_path
                .relative_to(
                    WORKSPACE
                )
                .as_posix()
            ),
        },
        "speech": (
            census.get(
                "speech"
            )
            or {}
        ),
        "burned_in_subtitles": {
            **subtitle_info,
            "accepted_track_count": len(
                subtitle_tracks
            ),
            "tracks": subtitle_tracks,
        },
        "visual_text": {
            "raw_occurrence_count": len(
                occurrences
            ),
            "raw_track_count": len(
                raw_tracks
            ),
            "accepted_non_subtitle_track_count": len(
                visual_tracks
            ),
            "accepted_tracks": visual_tracks,
            "rejected_noise_track_count": len(
                rejected
            ),
            "rejected_noise_examples": rejected[
                :max(
                    0,
                    int(
                        req.max_noise_examples
                    ),
                )
            ],
        },
        "summary": {
            "speech_language": (
                (
                    census.get(
                        "speech"
                    )
                    or {}
                ).get(
                    "detected_language"
                )
            ),
            "burned_in_subtitles": (
                subtitle_info.get(
                    "presence"
                )
            ),
            "subtitle_track_count": len(
                subtitle_tracks
            ),
            "non_subtitle_visual_track_count": len(
                visual_tracks
            ),
            "raw_ocr_occurrence_count": len(
                occurrences
            ),
            "noise_track_count": len(
                rejected
            ),
            "ready_for_subtitle_preview_development": bool(
                subtitle_info.get(
                    "presence"
                )
                == "PRESENT"
                and subtitle_info.get(
                    "dominant_bbox"
                )
            ),
            "other_visual_text_still_review": True,
            "source_video_modified": False,
        },
        "notes": {
            "subtitle_policy": (
                "The census dominant subtitle bbox remains the cleanup anchor. "
                "Temporal subtitle tracks refine when text is present."
            ),
            "visual_text_policy": (
                "Only persistent/repeated non-subtitle tracks survive. Isolated "
                "OCR detections are treated as noise and will not be erased."
            ),
            "next": (
                "After this report is accepted, build subtitle cover/redraw preview "
                "before speech dubbing or arbitrary visual-text replacement."
            ),
        },
        "output_relative_dir": (
            out_dir
            .relative_to(
                WORKSPACE
            )
            .as_posix()
        ),
    }

    report_path = (
        out_dir
        / (
            f"{stem}"
            ".language-structure.json"
        )
    )

    result[
        "report_relative_path"
    ] = (
        report_path
        .relative_to(
            WORKSPACE
        )
        .as_posix()
    )

    report_path.write_text(
        json.dumps(
            result,
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )

    return result




# ---------------------------------------------------------------------------
# v0.15.0 BGM Census + BGM Plan
#
# Subtitle / visual-text processing is intentionally DEFERRED for the early
# production workflow.
#
# BGM stage goals:
#   - discover own BGM assets from a drop-in directory
#   - inspect source audio / speech coverage
#   - decide whether safe BGM replacement requires stem separation
#   - never blindly overlay a second BGM on mixed speech+music audio
#
# No destructive audio render is performed in this version.
# ---------------------------------------------------------------------------


class BGMCensusRequest(BaseModel):
    video_relative_path: str

    # Optional existing Language Census. If supplied, reuse its Whisper speech
    # segments rather than transcribing again.
    language_census_report_relative_path: Optional[str] = None

    # If no language census is supplied, Whisper can be used for speech timing.
    enable_whisper_if_needed: bool = True
    whisper_model: Optional[str] = "small"
    whisper_device: str = "cpu"
    whisper_compute_type: str = "int8"

    # Drop-in BGM lookup.
    product_name: Optional[str] = None
    brand_name: Optional[str] = None
    language: Optional[str] = None

    # Treat clips with little/no speech differently from dialogue-heavy clips.
    speech_present_min_seconds: float = 0.8
    speech_present_min_ratio: float = 0.02


class BGMPlanRequest(BaseModel):
    census_report_relative_path: str

    # AUTO:
    #   speech present -> REPLACE_BGM_REQUIRES_STEM_SEPARATION
    #   no speech      -> REPLACE_FULL_AUDIO_BED
    # KEEP:
    #   preserve current audio
    # REPLACE:
    #   request own BGM replacement
    mode: str = "AUTO"

    # When speech is present, dialogue preservation is required by default.
    preserve_dialogue: bool = True

    # Do not allow a second BGM to be simply overlaid over a mixed source track.
    forbid_double_bgm_overlay: bool = True

    # Intended final mix target.
    target_bgm_lufs: float = -20.0
    target_dialogue_lufs: float = -16.0
    bgm_duck_db_under_dialogue: float = -7.0

    # Loop/fade policy for future renderer.
    loop_bgm_to_fit: bool = True
    fade_in_seconds: float = 0.20
    fade_out_seconds: float = 0.75


def _bgm_asset_roots(
    product_name=None,
    brand_name=None,
    language=None,
):
    roots = []

    product_slug = _slugify_asset_dir(
        product_name
        or ""
    )

    brand_slug = _slugify_asset_dir(
        brand_name
        or ""
    )

    language_slug = _slugify_asset_dir(
        language
        or ""
    )

    base = (
        WORKSPACE
        / "assets"
        / "bgm"
    )

    # Most-specific to least-specific.
    if product_name and language:
        roots.append(
            base
            / product_slug
            / language_slug
        )

    if brand_name and language:
        roots.append(
            base
            / brand_slug
            / language_slug
        )

    if product_name:
        roots.append(
            base
            / product_slug
        )

    if brand_name:
        roots.append(
            base
            / brand_slug
        )

    if language:
        roots.append(
            base
            / "default"
            / language_slug
        )

    roots.append(
        base
        / "default"
    )

    # De-duplicate.
    unique = []
    seen = set()

    for root in roots:
        key = str(root).lower()

        if key in seen:
            continue

        seen.add(key)
        unique.append(root)

    return unique


def _discover_bgm_asset(
    product_name=None,
    brand_name=None,
    language=None,
):
    filenames = [
        "bgm.mp3",
        "bgm.wav",
        "bgm.m4a",
        "bgm.aac",
        "bgm.flac",
        "music.mp3",
        "music.wav",
        "music.m4a",
    ]

    checked = []

    for root in _bgm_asset_roots(
        product_name,
        brand_name,
        language,
    ):
        checked.append(
            root
            .relative_to(
                WORKSPACE
            )
            .as_posix()
        )

        for filename in filenames:
            path = (
                root
                / filename
            )

            if not path.exists():
                continue

            media = _probe_media(
                path
            )

            # ffprobe treats an audio-only file as has_video=False, so only
            # require a valid duration and an audio stream.
            valid = bool(
                media.get(
                    "has_audio"
                )
                and float(
                    media.get(
                        "duration_seconds"
                    )
                    or 0.0
                )
                > 0.05
            )

            return {
                "found": bool(
                    valid
                ),
                "relative_path": (
                    path
                    .relative_to(
                        WORKSPACE
                    )
                    .as_posix()
                ),
                "media": media,
                "checked_directories": checked,
                "error": (
                    None
                    if valid
                    else "audio_stream_missing_or_invalid"
                ),
            }

    return {
        "found": False,
        "relative_path": None,
        "media": None,
        "checked_directories": checked,
        "error": "bgm_asset_not_found",
    }


def _merge_time_intervals(
    intervals,
):
    clean = []

    for start, end in intervals:
        try:
            start = float(start)
            end = float(end)
        except Exception:
            continue

        if end <= start:
            continue

        clean.append(
            (
                start,
                end,
            )
        )

    clean.sort()

    merged = []

    for start, end in clean:
        if not merged:
            merged.append(
                [
                    start,
                    end,
                ]
            )
            continue

        prev = merged[-1]

        if start <= (
            prev[1]
            + 0.12
        ):
            prev[1] = max(
                prev[1],
                end,
            )
        else:
            merged.append(
                [
                    start,
                    end,
                ]
            )

    return [
        (
            float(start),
            float(end),
        )
        for start, end in merged
    ]


def _speech_summary_from_segments(
    segments,
    duration,
    min_seconds,
    min_ratio,
):
    intervals = []

    for segment in (
        segments
        or []
    ):
        try:
            start = float(
                segment.get(
                    "start_seconds"
                )
                or 0.0
            )

            end = float(
                segment.get(
                    "end_seconds"
                )
                or 0.0
            )
        except Exception:
            continue

        if end > start:
            intervals.append(
                (
                    start,
                    end,
                )
            )

    merged = (
        _merge_time_intervals(
            intervals
        )
    )

    speech_seconds = sum(
        max(
            0.0,
            end - start,
        )
        for start, end in merged
    )

    ratio = (
        speech_seconds
        / float(
            max(
                0.001,
                duration,
            )
        )
    )

    present = bool(
        speech_seconds
        >= float(
            min_seconds
        )
        and ratio
        >= float(
            min_ratio
        )
    )

    return {
        "present": present,
        "speech_seconds": round(
            speech_seconds,
            3,
        ),
        "speech_ratio": round(
            ratio,
            4,
        ),
        "merged_interval_count": len(
            merged
        ),
        "intervals": [
            {
                "start_seconds": round(
                    start,
                    3,
                ),
                "end_seconds": round(
                    end,
                    3,
                ),
            }
            for start, end in merged
        ],
    }


def _load_speech_for_bgm(
    video_path,
    duration,
    req,
):
    if req.language_census_report_relative_path:
        census_path, census = (
            _read_json_workspace(
                req.language_census_report_relative_path,
                "bgm_census",
            )
        )

        if (
            census.get(
                "mode"
            )
            != "language_census"
        ):
            raise HTTPException(
                status_code=422,
                detail={
                    "stage": "bgm_census",
                    "error": (
                        "expected_language_census_report"
                    ),
                },
            )

        speech = (
            census.get(
                "speech"
            )
            or {}
        )

        return {
            "source": (
                "language_census"
            ),
            "census_report_relative_path": (
                census_path
                .relative_to(
                    WORKSPACE
                )
                .as_posix()
            ),
            "language": speech.get(
                "detected_language"
            ),
            "segments": speech.get(
                "segments"
            )
            or [],
            "status": speech.get(
                "status"
            ),
        }

    if not bool(
        req.enable_whisper_if_needed
    ):
        return {
            "source": "none",
            "language": None,
            "segments": [],
            "status": "SKIPPED",
        }

    class _WhisperShim:
        enable_whisper = True
        enable_whisper_translation = False
        whisper_model = req.whisper_model
        whisper_device = req.whisper_device
        whisper_compute_type = (
            req.whisper_compute_type
        )

    whisper = (
        _whisper_model_and_segments(
            video_path,
            _WhisperShim(),
        )
    )

    return {
        "source": "whisper",
        "language": whisper.get(
            "language"
        ),
        "segments": whisper.get(
            "segments"
        )
        or [],
        "status": whisper.get(
            "status"
        ),
        "error": whisper.get(
            "error"
        ),
    }


def _bgm_census_sync(
    req: BGMCensusRequest
):
    video_path = (
        _safe_workspace_path(
            req.video_relative_path
        )
    )

    if not video_path.exists():
        raise HTTPException(
            status_code=404,
            detail={
                "stage": "bgm_census",
                "error": (
                    "video_not_found"
                ),
            },
        )

    cap = cv2.VideoCapture(
        str(
            video_path
        )
    )

    if not cap.isOpened():
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "bgm_census",
                "error": (
                    "could_not_open_video"
                ),
            },
        )

    try:
        meta = _video_metadata(
            cap
        )
    finally:
        cap.release()

    duration = float(
        meta.get(
            "duration_seconds"
        )
        or 0.0
    )

    source_media = _probe_media(
        video_path
    )

    speech_source = (
        _load_speech_for_bgm(
            video_path,
            duration,
            req,
        )
    )

    speech_summary = (
        _speech_summary_from_segments(
            speech_source.get(
                "segments"
            )
            or [],
            duration,
            float(
                req.speech_present_min_seconds
            ),
            float(
                req.speech_present_min_ratio
            ),
        )
    )

    language = (
        req.language
        or speech_source.get(
            "language"
        )
    )

    own_bgm = (
        _discover_bgm_asset(
            req.product_name,
            req.brand_name,
            language,
        )
    )

    source_has_audio = bool(
        source_media.get(
            "has_audio"
        )
    )

    speech_present = bool(
        speech_summary.get(
            "present"
        )
    )

    if not source_has_audio:
        source_audio_class = (
            "NO_AUDIO"
        )
    elif speech_present:
        source_audio_class = (
            "MIXED_DIALOGUE_AUDIO"
        )
    else:
        source_audio_class = (
            "NON_DIALOGUE_AUDIO"
        )

    if own_bgm.get(
        "found"
    ):
        if (
            source_audio_class
            == "MIXED_DIALOGUE_AUDIO"
        ):
            recommended = (
                "REPLACE_BGM_REQUIRES_STEM_SEPARATION"
            )
        elif (
            source_audio_class
            in (
                "NON_DIALOGUE_AUDIO",
                "NO_AUDIO",
            )
        ):
            recommended = (
                "REPLACE_FULL_AUDIO_BED"
            )
        else:
            recommended = (
                "REVIEW"
            )
    else:
        recommended = (
            "KEEP_UNTIL_OWN_BGM_AVAILABLE"
        )

    timestamp = (
        _app_now().strftime(
            "%Y-%m-%d_%H%M%S"
        )
    )

    out_dir = (
        WORKSPACE
        / "review"
        / "bgm_census"
        / timestamp
        / video_path.stem
    )

    out_dir.mkdir(
        parents=True,
        exist_ok=True,
    )

    result = {
        "ok": True,
        "version": "0.17.0",
        "mode": "bgm_census",
        "source": {
            "relative_path": (
                video_path
                .relative_to(
                    WORKSPACE
                )
                .as_posix()
            ),
            "media": source_media,
            "audio_class": (
                source_audio_class
            ),
        },
        "video": meta,
        "speech": {
            "source": speech_source.get(
                "source"
            ),
            "language": speech_source.get(
                "language"
            ),
            "status": speech_source.get(
                "status"
            ),
            "summary": speech_summary,
        },
        "own_bgm": own_bgm,
        "summary": {
            "source_has_audio": (
                source_has_audio
            ),
            "speech_present": (
                speech_present
            ),
            "speech_ratio": (
                speech_summary.get(
                    "speech_ratio"
                )
            ),
            "own_bgm_available": bool(
                own_bgm.get(
                    "found"
                )
            ),
            "recommended_operation": (
                recommended
            ),
            "blind_double_bgm_overlay_allowed": False,
            "source_video_modified": False,
        },
        "notes": {
            "safety": (
                "A dialogue-heavy mixed track must not receive a second BGM "
                "overlay. Proper BGM replacement requires dialogue/accompaniment "
                "stem separation first."
            ),
            "subtitle_stage": (
                "Subtitle/visual-text processing is deferred and does not block "
                "the BGM stage."
            ),
        },
        "output_relative_dir": (
            out_dir
            .relative_to(
                WORKSPACE
            )
            .as_posix()
        ),
    }

    report_path = (
        out_dir
        / (
            f"{video_path.stem}"
            ".bgm-census.json"
        )
    )

    result[
        "report_relative_path"
    ] = (
        report_path
        .relative_to(
            WORKSPACE
        )
        .as_posix()
    )

    report_path.write_text(
        json.dumps(
            result,
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )

    return result


def _bgm_plan_sync(
    req: BGMPlanRequest
):
    census_path, census = (
        _read_json_workspace(
            req.census_report_relative_path,
            "bgm_plan",
        )
    )

    if (
        census.get(
            "mode"
        )
        != "bgm_census"
    ):
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "bgm_plan",
                "error": (
                    "expected_bgm_census_report"
                ),
            },
        )

    source = (
        census.get(
            "source"
        )
        or {}
    )

    speech = (
        census.get(
            "speech"
        )
        or {}
    )

    own_bgm = (
        census.get(
            "own_bgm"
        )
        or {}
    )

    source_class = str(
        source.get(
            "audio_class"
        )
        or "UNKNOWN"
    )

    own_bgm_available = bool(
        own_bgm.get(
            "found"
        )
    )

    speech_present = bool(
        (
            speech.get(
                "summary"
            )
            or {}
        ).get(
            "present"
        )
    )

    requested_mode = str(
        req.mode
        or "AUTO"
    ).strip().upper()

    if requested_mode not in (
        "AUTO",
        "KEEP",
        "REPLACE",
    ):
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "bgm_plan",
                "error": (
                    "invalid_mode"
                ),
                "allowed": [
                    "AUTO",
                    "KEEP",
                    "REPLACE",
                ],
            },
        )

    if requested_mode == "KEEP":
        operation = "KEEP_SOURCE_AUDIO"
        status = "AUTO"
        stem_required = False

    elif not own_bgm_available:
        operation = (
            "WAIT_FOR_OWN_BGM_ASSET"
        )
        status = "WAITING"
        stem_required = False

    elif (
        speech_present
        and bool(
            req.preserve_dialogue
        )
    ):
        operation = (
            "REPLACE_BGM_WITH_DIALOGUE_PRESERVATION"
        )
        status = "REVIEW"
        stem_required = True

    elif (
        source_class
        in (
            "NON_DIALOGUE_AUDIO",
            "NO_AUDIO",
        )
    ):
        operation = (
            "REPLACE_FULL_AUDIO_BED"
        )
        status = "REVIEW"
        stem_required = False

    else:
        operation = "REVIEW_AUDIO_POLICY"
        status = "REVIEW"
        stem_required = bool(
            speech_present
        )

    if (
        bool(
            req.forbid_double_bgm_overlay
        )
        and speech_present
        and operation
        == "REPLACE_BGM_WITH_DIALOGUE_PRESERVATION"
    ):
        direct_overlay_allowed = False
    else:
        direct_overlay_allowed = bool(
            not req.forbid_double_bgm_overlay
        )

    timestamp = (
        _app_now().strftime(
            "%Y-%m-%d_%H%M%S"
        )
    )

    source_rel = (
        (
            census.get(
                "source"
            )
            or {}
        ).get(
            "relative_path"
        )
    )

    stem = (
        Path(
            source_rel
            or "video"
        ).stem
    )

    out_dir = (
        WORKSPACE
        / "review"
        / "bgm_plan"
        / timestamp
        / stem
    )

    out_dir.mkdir(
        parents=True,
        exist_ok=True,
    )

    result = {
        "ok": True,
        "version": "0.17.0",
        "mode": "bgm_plan",
        "source": {
            "video_relative_path": (
                source_rel
            ),
            "census_report_relative_path": (
                census_path
                .relative_to(
                    WORKSPACE
                )
                .as_posix()
            ),
        },
        "own_bgm": own_bgm,
        "decision": {
            "requested_mode": (
                requested_mode
            ),
            "operation": (
                operation
            ),
            "status": status,
            "preserve_dialogue": bool(
                req.preserve_dialogue
            ),
            "stem_separation_required": bool(
                stem_required
            ),
            "direct_double_bgm_overlay_allowed": (
                direct_overlay_allowed
            ),
        },
        "mix_policy": {
            "target_bgm_lufs": float(
                req.target_bgm_lufs
            ),
            "target_dialogue_lufs": float(
                req.target_dialogue_lufs
            ),
            "bgm_duck_db_under_dialogue": float(
                req.bgm_duck_db_under_dialogue
            ),
            "loop_bgm_to_fit": bool(
                req.loop_bgm_to_fit
            ),
            "fade_in_seconds": float(
                req.fade_in_seconds
            ),
            "fade_out_seconds": float(
                req.fade_out_seconds
            ),
        },
        "summary": {
            "own_bgm_available": (
                own_bgm_available
            ),
            "speech_present": (
                speech_present
            ),
            "stem_separation_required": bool(
                stem_required
            ),
            "ready_for_bgm_render_development": bool(
                status
                != "WAITING"
            ),
            "source_video_modified": False,
        },
        "notes": {
            "next": (
                "If stem_separation_required=true, the next module will use a "
                "dialogue/accompaniment separator before mixing own BGM. If false, "
                "the renderer can replace the audio bed directly with FFmpeg."
            ),
            "no_double_bgm": (
                "The plan never silently overlays own BGM on top of a mixed "
                "dialogue+music source track."
            ),
        },
        "output_relative_dir": (
            out_dir
            .relative_to(
                WORKSPACE
            )
            .as_posix()
        ),
    }

    report_path = (
        out_dir
        / (
            f"{stem}"
            ".bgm-plan.json"
        )
    )

    result[
        "report_relative_path"
    ] = (
        report_path
        .relative_to(
            WORKSPACE
        )
        .as_posix()
    )

    report_path.write_text(
        json.dumps(
            result,
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )

    return result




# ---------------------------------------------------------------------------
# v0.16.0 Mintegral Upload + Creative Set + Audit
#
# Official Open API flow:
#   local creative
#   -> local MD5
#   -> query creative library by creative_md5
#   -> reuse if already uploaded
#   -> otherwise upload creative
#   -> create/update Creative Set
#   -> query Creative Set audit_status / audit_reason
#
# Credentials are loaded locally and are NEVER returned in API responses.
#
# workspace/config/mintegral.env
#   MINTEGRAL_ACCESS_KEY=
#   MINTEGRAL_API_KEY=
#   MINTEGRAL_DEFAULT_OFFER_ID=
#   MINTEGRAL_DEFAULT_CREATIVE_SET_NAME=
#   MINTEGRAL_DEFAULT_GEOS=ALL
#   MINTEGRAL_DEFAULT_AD_OUTPUTS=
# ---------------------------------------------------------------------------


MINTEGRAL_API_BASE_DEFAULT = "https://ss-api.mintegral.com"
MINTEGRAL_STORAGE_BASE_DEFAULT = "https://ss-storage-api.mintegral.com"


class MintegralConnectionCheckRequest(BaseModel):
    live_check: bool = True
    offer_id: Optional[int] = None


class MintegralUploadCreativeRequest(BaseModel):
    video_relative_path: str

    reuse_existing_by_md5: bool = True

    # false = read-only preflight, true = may upload externally
    execute: bool = False

    timeout_seconds: float = 180.0


class MintegralPublishCreativeRequest(BaseModel):
    video_relative_path: str

    offer_id: Optional[int] = None
    creative_set_name: Optional[str] = None

    geos: Optional[list[str]] = None
    ad_outputs: Optional[list[int]] = None

    # Customized creative set by default.
    combination_method: int = 2

    reuse_existing_by_md5: bool = True

    # false = dry-run / read-only planning
    # true = upload if needed + create/update Creative Set
    execute: bool = False

    timeout_seconds: float = 180.0


class MintegralAuditStatusRequest(BaseModel):
    offer_id: Optional[int] = None
    creative_set_name: Optional[str] = None
    creative_md5: Optional[str] = None

    page: int = 1
    limit: int = 50
    timeout_seconds: float = 60.0


def _mintegral_config_path():
    return (
        WORKSPACE
        / "config"
        / "mintegral.env"
    )


def _read_simple_env_file(
    path,
):
    values = {}

    if not path.exists():
        return values

    try:
        raw = path.read_text(
            encoding="utf-8"
        )
    except Exception:
        return values

    for line in raw.splitlines():
        line = line.strip()

        if (
            not line
            or line.startswith("#")
            or "=" not in line
        ):
            continue

        key, value = line.split(
            "=",
            1,
        )

        key = key.strip()
        value = value.strip()

        if (
            len(value) >= 2
            and value[0] == value[-1]
            and value[0] in (
                '"',
                "'",
            )
        ):
            value = value[
                1:-1
            ]

        values[
            key
        ] = value

    return values


def _mintegral_config():
    file_values = (
        _read_simple_env_file(
            _mintegral_config_path()
        )
    )

    def get_value(
        key,
        default=None,
    ):
        env_value = os.getenv(
            key
        )

        if (
            env_value is not None
            and str(
                env_value
            ).strip()
            != ""
        ):
            return str(
                env_value
            ).strip()

        file_value = (
            file_values.get(
                key
            )
        )

        if (
            file_value is not None
            and str(
                file_value
            ).strip()
            != ""
        ):
            return str(
                file_value
            ).strip()

        return default

    access_key = get_value(
        "MINTEGRAL_ACCESS_KEY"
    )

    api_key = get_value(
        "MINTEGRAL_API_KEY"
    )

    default_offer_raw = get_value(
        "MINTEGRAL_DEFAULT_OFFER_ID"
    )

    default_offer = None

    if default_offer_raw:
        try:
            default_offer = int(
                default_offer_raw
            )
        except Exception:
            default_offer = None

    default_geos_raw = (
        get_value(
            "MINTEGRAL_DEFAULT_GEOS",
            "ALL",
        )
        or "ALL"
    )

    default_geos = [
        item.strip().upper()
        for item in default_geos_raw.split(
            ","
        )
        if item.strip()
    ]

    ad_outputs_raw = (
        get_value(
            "MINTEGRAL_DEFAULT_AD_OUTPUTS",
            "",
        )
        or ""
    )

    default_ad_outputs = []

    for item in ad_outputs_raw.split(
        ","
    ):
        item = item.strip()

        if not item:
            continue

        try:
            default_ad_outputs.append(
                int(item)
            )
        except Exception:
            continue

    return {
        # Secret values are used internally only.
        "_access_key": access_key,
        "_api_key": api_key,

        "api_base": (
            get_value(
                "MINTEGRAL_API_BASE",
                MINTEGRAL_API_BASE_DEFAULT,
            )
            or MINTEGRAL_API_BASE_DEFAULT
        ).rstrip("/"),

        "storage_base": (
            get_value(
                "MINTEGRAL_STORAGE_BASE",
                MINTEGRAL_STORAGE_BASE_DEFAULT,
            )
            or MINTEGRAL_STORAGE_BASE_DEFAULT
        ).rstrip("/"),

        "default_offer_id": (
            default_offer
        ),

        "default_creative_set_name": (
            get_value(
                "MINTEGRAL_DEFAULT_CREATIVE_SET_NAME"
            )
        ),

        "default_geos": (
            default_geos
            or ["ALL"]
        ),

        "default_ad_outputs": (
            default_ad_outputs
        ),

        "config_relative_path": (
            _mintegral_config_path()
            .relative_to(
                WORKSPACE
            )
            .as_posix()
        ),
    }


def _mintegral_public_config(
    config,
):
    return {
        "credentials": {
            "access_key_configured": bool(
                config.get(
                    "_access_key"
                )
            ),
            "api_key_configured": bool(
                config.get(
                    "_api_key"
                )
            ),
            "ready": bool(
                config.get(
                    "_access_key"
                )
                and config.get(
                    "_api_key"
                )
            ),
        },
        "api_base": (
            config.get(
                "api_base"
            )
        ),
        "storage_base": (
            config.get(
                "storage_base"
            )
        ),
        "default_offer_id": (
            config.get(
                "default_offer_id"
            )
        ),
        "default_creative_set_name": (
            config.get(
                "default_creative_set_name"
            )
        ),
        "default_geos": (
            config.get(
                "default_geos"
            )
        ),
        "default_ad_outputs": (
            config.get(
                "default_ad_outputs"
            )
        ),
        "config_relative_path": (
            config.get(
                "config_relative_path"
            )
        ),
    }


def _mintegral_require_credentials(
    config,
):
    if not (
        config.get(
            "_access_key"
        )
        and config.get(
            "_api_key"
        )
    ):
        raise HTTPException(
            status_code=422,
            detail={
                "stage": (
                    "mintegral"
                ),
                "error": (
                    "credentials_not_configured"
                ),
                "config_relative_path": (
                    config.get(
                        "config_relative_path"
                    )
                ),
                "required_fields": [
                    "MINTEGRAL_ACCESS_KEY",
                    "MINTEGRAL_API_KEY",
                ],
                "message": (
                    "Fill the local Mintegral config file. "
                    "Do not put account secrets in Swagger request bodies."
                ),
            },
        )


def _mintegral_auth_headers(
    config,
):
    import hashlib
    import time

    _mintegral_require_credentials(
        config
    )

    timestamp = str(
        int(
            time.time()
        )
    )

    timestamp_md5 = (
        hashlib.md5(
            timestamp.encode(
                "utf-8"
            )
        ).hexdigest()
    )

    token = hashlib.md5(
        (
            str(
                config[
                    "_api_key"
                ]
            )
            + timestamp_md5
        ).encode(
            "utf-8"
        )
    ).hexdigest()

    return {
        "access-key": str(
            config[
                "_access_key"
            ]
        ),
        "token": token,
        "timestamp": timestamp,
    }


def _mintegral_requests():
    try:
        import requests
    except Exception as exc:
        raise HTTPException(
            status_code=500,
            detail={
                "stage": "mintegral",
                "error": (
                    "python_requests_dependency_missing"
                ),
                "message": str(
                    exc
                )[:300],
            },
        )

    return requests


def _mintegral_response_json(
    response,
    stage,
):
    try:
        payload = response.json()
    except Exception:
        raise HTTPException(
            status_code=502,
            detail={
                "stage": stage,
                "error": (
                    "mintegral_non_json_response"
                ),
                "http_status": int(
                    response.status_code
                ),
                "body": (
                    response.text[
                        :1200
                    ]
                    if response.text
                    else ""
                ),
            },
        )

    code = payload.get(
        "code"
    )

    # Some Mintegral endpoints use msg, others use message.
    message = (
        payload.get(
            "msg"
        )
        or payload.get(
            "message"
        )
        or ""
    )

    if (
        response.status_code
        >= 400
        or (
            code is not None
            and int(code) != 200
        )
    ):
        raise HTTPException(
            status_code=502,
            detail={
                "stage": stage,
                "error": (
                    "mintegral_api_error"
                ),
                "http_status": int(
                    response.status_code
                ),
                "api_code": code,
                "api_message": str(
                    message
                )[:1000],
            },
        )

    return payload


def _mintegral_get(
    config,
    path,
    *,
    params=None,
    timeout=60.0,
    stage="mintegral_get",
):
    requests = (
        _mintegral_requests()
    )

    headers = (
        _mintegral_auth_headers(
            config
        )
    )

    response = requests.get(
        (
            str(
                config[
                    "api_base"
                ]
            )
            + path
        ),
        headers=headers,
        params=(
            params
            or {}
        ),
        timeout=float(
            timeout
        ),
    )

    return _mintegral_response_json(
        response,
        stage,
    )


def _mintegral_json_request(
    config,
    method,
    path,
    payload,
    *,
    timeout=60.0,
    stage="mintegral_json_request",
):
    requests = (
        _mintegral_requests()
    )

    headers = (
        _mintegral_auth_headers(
            config
        )
    )

    headers[
        "Content-Type"
    ] = "application/json"

    response = requests.request(
        method.upper(),
        (
            str(
                config[
                    "api_base"
                ]
            )
            + path
        ),
        headers=headers,
        json=payload,
        timeout=float(
            timeout
        ),
    )

    return _mintegral_response_json(
        response,
        stage,
    )


def _local_file_md5(
    path,
):
    import hashlib

    digest = hashlib.md5()

    with path.open(
        "rb"
    ) as f:
        while True:
            chunk = f.read(
                1024 * 1024
            )

            if not chunk:
                break

            digest.update(
                chunk
            )

    return digest.hexdigest()


def _mintegral_query_creative_by_md5(
    config,
    creative_md5,
    timeout=60.0,
):
    payload = _mintegral_get(
        config,
        "/api/open/v1/creatives/source",
        params={
            "creative_md5": str(
                creative_md5
            ),
            "page": 1,
            "limit": 10,
        },
        timeout=timeout,
        stage=(
            "mintegral_query_creative"
        ),
    )

    data = (
        payload.get(
            "data"
        )
        or {}
    )

    items = (
        data.get(
            "list"
        )
        or []
    )

    matches = [
        item
        for item in items
        if str(
            item.get(
                "creative_md5"
            )
            or ""
        ).lower()
        == str(
            creative_md5
        ).lower()
    ]

    return {
        "found": bool(
            matches
        ),
        "matches": matches,
        "raw_total": (
            data.get(
                "total"
            )
        ),
    }


def _mintegral_upload_file(
    config,
    path,
    timeout=180.0,
):
    requests = (
        _mintegral_requests()
    )

    headers = (
        _mintegral_auth_headers(
            config
        )
    )

    url = (
        str(
            config[
                "storage_base"
            ]
        )
        + (
            "/api/open/v1/creatives/upload"
        )
    )

    with path.open(
        "rb"
    ) as f:
        response = requests.post(
            url,
            headers=headers,
            files={
                "file": (
                    path.name,
                    f,
                    "application/octet-stream",
                )
            },
            timeout=float(
                timeout
            ),
        )

    payload = (
        _mintegral_response_json(
            response,
            "mintegral_upload_creative",
        )
    )

    data = (
        payload.get(
            "data"
        )
        or {}
    )

    creative_md5 = (
        data.get(
            "creative_md5"
        )
    )

    creative_name = (
        data.get(
            "creative_name"
        )
    )

    if not creative_md5:
        raise HTTPException(
            status_code=502,
            detail={
                "stage": (
                    "mintegral_upload_creative"
                ),
                "error": (
                    "upload_success_without_creative_md5"
                ),
            },
        )

    return {
        "creative_md5": str(
            creative_md5
        ),
        "creative_name": str(
            creative_name
            or path.name
        ),
    }


def _mintegral_creative_sets(
    config,
    *,
    offer_id=None,
    creative_set_name=None,
    page=1,
    limit=50,
    timeout=60.0,
):
    params = {
        "page": max(
            1,
            int(page),
        ),
        "limit": min(
            50,
            max(
                1,
                int(limit),
            ),
        ),
    }

    if offer_id is not None:
        params[
            "offer_id"
        ] = int(
            offer_id
        )

    if creative_set_name:
        params[
            "creative_set_name"
        ] = str(
            creative_set_name
        )

    payload = _mintegral_get(
        config,
        "/api/open/v1/creative_sets",
        params=params,
        timeout=timeout,
        stage=(
            "mintegral_get_creative_sets"
        ),
    )

    return (
        payload.get(
            "data"
        )
        or {}
    )


def _mintegral_find_creative_set(
    config,
    offer_id,
    creative_set_name,
    timeout=60.0,
):
    data = (
        _mintegral_creative_sets(
            config,
            offer_id=offer_id,
            creative_set_name=(
                creative_set_name
            ),
            page=1,
            limit=50,
            timeout=timeout,
        )
    )

    items = (
        data.get(
            "list"
        )
        or []
    )

    exact = [
        item
        for item in items
        if (
            int(
                item.get(
                    "offer_id"
                )
                or -1
            )
            == int(
                offer_id
            )
            and str(
                item.get(
                    "creative_set_name"
                )
                or ""
            )
            == str(
                creative_set_name
            )
        )
    ]

    return (
        exact[0]
        if exact
        else None
    )


def _mintegral_audit_label(
    value,
):
    try:
        value = int(
            value
        )
    except Exception:
        return "UNKNOWN"

    return {
        0: "INITIALIZED",
        1: "APPROVED",
        2: "REJECTED",
        3: "UNDER_REVIEW",
    }.get(
        value,
        "UNKNOWN",
    )


def _mintegral_connection_check_sync(
    req: MintegralConnectionCheckRequest
):
    config = (
        _mintegral_config()
    )

    public = (
        _mintegral_public_config(
            config
        )
    )

    result = {
        "ok": bool(
            public[
                "credentials"
            ][
                "ready"
            ]
        ),
        "version": "0.17.0",
        "mode": (
            "mintegral_connection_check"
        ),
        "config": public,
        "live_check": {
            "requested": bool(
                req.live_check
            ),
            "performed": False,
            "ok": None,
        },
    }

    if not bool(
        req.live_check
    ):
        return result

    _mintegral_require_credentials(
        config
    )

    # Minimal read-only call verifies auth.
    library = _mintegral_get(
        config,
        "/api/open/v1/creatives/source",
        params={
            "page": 1,
            "limit": 1,
        },
        timeout=60.0,
        stage=(
            "mintegral_connection_check"
        ),
    )

    result[
        "live_check"
    ] = {
        "requested": True,
        "performed": True,
        "ok": True,
        "creative_library_total": (
            (
                library.get(
                    "data"
                )
                or {}
            ).get(
                "total"
            )
        ),
    }

    offer_id = (
        req.offer_id
        if req.offer_id is not None
        else config.get(
            "default_offer_id"
        )
    )

    if offer_id is not None:
        offers = _mintegral_get(
            config,
            "/api/open/v1/offers",
            params={
                "offer_id": str(
                    int(
                        offer_id
                    )
                ),
                "page": 1,
                "limit": 1,
            },
            timeout=60.0,
            stage=(
                "mintegral_offer_check"
            ),
        )

        offer_list = (
            (
                offers.get(
                    "data"
                )
                or {}
            ).get(
                "list"
            )
            or []
        )

        result[
            "live_check"
        ][
            "offer"
        ] = {
            "offer_id": int(
                offer_id
            ),
            "found": bool(
                offer_list
            ),
            "offer_name": (
                offer_list[
                    0
                ].get(
                    "offer_name"
                )
                if offer_list
                else None
            ),
            "status": (
                offer_list[
                    0
                ].get(
                    "status"
                )
                if offer_list
                else None
            ),
        }

    return result


def _mintegral_upload_preflight_or_execute(
    video_path,
    config,
    *,
    reuse_existing_by_md5=True,
    execute=False,
    timeout=180.0,
):
    local_md5 = _local_file_md5(
        video_path
    )

    existing = None

    if bool(
        reuse_existing_by_md5
    ):
        existing = (
            _mintegral_query_creative_by_md5(
                config,
                local_md5,
                timeout=min(
                    60.0,
                    float(
                        timeout
                    ),
                ),
            )
        )

        if existing.get(
            "found"
        ):
            item = (
                existing[
                    "matches"
                ][0]
            )

            return {
                "status": (
                    "REUSED_EXISTING"
                ),
                "executed_upload": False,
                "local_md5": (
                    local_md5
                ),
                "creative_md5": (
                    item.get(
                        "creative_md5"
                    )
                ),
                "creative_name": (
                    item.get(
                        "creative_name"
                    )
                    or video_path.name
                ),
                "creative_type": (
                    item.get(
                        "creative_type"
                    )
                ),
                "resolution": (
                    item.get(
                        "resolution"
                    )
                    or item.get(
                        "dimension"
                    )
                ),
            }

    if not bool(
        execute
    ):
        return {
            "status": (
                "READY_TO_UPLOAD"
            ),
            "executed_upload": False,
            "local_md5": (
                local_md5
            ),
            "creative_md5": None,
            "creative_name": (
                video_path.name
            ),
            "message": (
                "Set execute=true to upload. "
                "No external write was performed."
            ),
        }

    uploaded = (
        _mintegral_upload_file(
            config,
            video_path,
            timeout=timeout,
        )
    )

    return {
        "status": "UPLOADED",
        "executed_upload": True,
        "local_md5": (
            local_md5
        ),
        "creative_md5": (
            uploaded[
                "creative_md5"
            ]
        ),
        "creative_name": (
            uploaded[
                "creative_name"
            ]
        ),
    }


def _mintegral_upload_creative_sync(
    req: MintegralUploadCreativeRequest
):
    config = (
        _mintegral_config()
    )

    _mintegral_require_credentials(
        config
    )

    video_path = (
        _safe_workspace_path(
            req.video_relative_path
        )
    )

    if not video_path.is_file():
        raise HTTPException(
            status_code=422,
            detail={
                "stage": (
                    "mintegral_upload_creative"
                ),
                "error": (
                    "creative_path_is_not_file"
                ),
            },
        )

    upload = (
        _mintegral_upload_preflight_or_execute(
            video_path,
            config,
            reuse_existing_by_md5=(
                req.reuse_existing_by_md5
            ),
            execute=req.execute,
            timeout=req.timeout_seconds,
        )
    )

    return {
        "ok": True,
        "version": "0.17.0",
        "mode": (
            "mintegral_upload_creative"
        ),
        "source": {
            "relative_path": (
                video_path
                .relative_to(
                    WORKSPACE
                )
                .as_posix()
            ),
            "size_bytes": (
                video_path.stat().st_size
            ),
        },
        "upload": upload,
        "summary": {
            "external_write_performed": bool(
                upload.get(
                    "executed_upload"
                )
            ),
            "reused_existing": (
                upload.get(
                    "status"
                )
                == "REUSED_EXISTING"
            ),
        },
    }


def _mintegral_resolve_publish_config(
    req,
    config,
):
    offer_id = (
        req.offer_id
        if req.offer_id is not None
        else config.get(
            "default_offer_id"
        )
    )

    creative_set_name = (
        req.creative_set_name
        or config.get(
            "default_creative_set_name"
        )
    )

    geos = (
        req.geos
        if req.geos is not None
        else config.get(
            "default_geos"
        )
    )

    ad_outputs = (
        req.ad_outputs
        if req.ad_outputs is not None
        else config.get(
            "default_ad_outputs"
        )
    )

    return {
        "offer_id": (
            int(
                offer_id
            )
            if offer_id is not None
            else None
        ),
        "creative_set_name": (
            str(
                creative_set_name
            )
            if creative_set_name
            else None
        ),
        "geos": [
            str(
                geo
            ).upper()
            for geo in (
                geos
                or ["ALL"]
            )
            if str(
                geo
            ).strip()
        ],
        "ad_outputs": [
            int(
                item
            )
            for item in (
                ad_outputs
                or []
            )
        ],
    }


def _mintegral_publish_creative_sync(
    req: MintegralPublishCreativeRequest
):
    config = (
        _mintegral_config()
    )

    _mintegral_require_credentials(
        config
    )

    video_path = (
        _safe_workspace_path(
            req.video_relative_path
        )
    )

    resolved = (
        _mintegral_resolve_publish_config(
            req,
            config,
        )
    )

    if resolved[
        "offer_id"
    ] is None:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": (
                    "mintegral_publish_creative"
                ),
                "error": (
                    "offer_id_required"
                ),
                "message": (
                    "Set offer_id in the request or MINTEGRAL_DEFAULT_OFFER_ID locally."
                ),
            },
        )

    if not resolved[
        "creative_set_name"
    ]:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": (
                    "mintegral_publish_creative"
                ),
                "error": (
                    "creative_set_name_required"
                ),
            },
        )

    existing_set = (
        _mintegral_find_creative_set(
            config,
            resolved[
                "offer_id"
            ],
            resolved[
                "creative_set_name"
            ],
            timeout=min(
                60.0,
                float(
                    req.timeout_seconds
                ),
            ),
        )
    )

    # For dry-run, do not upload. Compute local MD5 and check whether the
    # creative already exists so the plan is useful without external writes.
    upload = (
        _mintegral_upload_preflight_or_execute(
            video_path,
            config,
            reuse_existing_by_md5=(
                req.reuse_existing_by_md5
            ),
            execute=bool(
                req.execute
            ),
            timeout=req.timeout_seconds,
        )
    )

    write_action = None
    write_response = None

    if bool(
        req.execute
    ):
        creative_md5 = (
            upload.get(
                "creative_md5"
            )
        )

        creative_name = (
            upload.get(
                "creative_name"
            )
            or video_path.name
        )

        if not creative_md5:
            raise HTTPException(
                status_code=500,
                detail={
                    "stage": (
                        "mintegral_publish_creative"
                    ),
                    "error": (
                        "creative_md5_unavailable_after_upload"
                    ),
                },
            )

        if existing_set is not None:
            write_action = (
                "UPDATE_CREATIVE_SET"
            )

            # Preserve existing group targeting unless explicitly overridden.
            geos = (
                req.geos
                if req.geos is not None
                else existing_set.get(
                    "geos"
                )
                or resolved[
                    "geos"
                ]
            )

            ad_outputs = (
                req.ad_outputs
                if req.ad_outputs is not None
                else existing_set.get(
                    "ad_outputs"
                )
                or resolved[
                    "ad_outputs"
                ]
            )

            payload = {
                "offer_id": int(
                    resolved[
                        "offer_id"
                    ]
                ),
                "creative_set_name": str(
                    resolved[
                        "creative_set_name"
                    ]
                ),
                "geos": [
                    str(
                        geo
                    )
                    for geo in geos
                ],
                "ad_outputs": [
                    int(
                        item
                    )
                    for item in ad_outputs
                ],
                "creatives": [
                    {
                        "creative_name": str(
                            creative_name
                        ),
                        "creative_md5": str(
                            creative_md5
                        ),
                        "option": "ENABLE",
                    }
                ],
            }

            write_response = (
                _mintegral_json_request(
                    config,
                    "PUT",
                    "/api/open/v1/creative_set",
                    payload,
                    timeout=req.timeout_seconds,
                    stage=(
                        "mintegral_update_creative_set"
                    ),
                )
            )

        else:
            if not resolved[
                "ad_outputs"
            ]:
                raise HTTPException(
                    status_code=422,
                    detail={
                        "stage": (
                            "mintegral_publish_creative"
                        ),
                        "error": (
                            "ad_outputs_required_for_new_creative_set"
                        ),
                        "message": (
                            "The Creative Set does not exist yet. "
                            "Specify ad_outputs explicitly or configure "
                            "MINTEGRAL_DEFAULT_AD_OUTPUTS. "
                            "The system will not guess an ad_output."
                        ),
                    },
                )

            write_action = (
                "CREATE_CREATIVE_SET"
            )

            payload = {
                "creative_set_name": str(
                    resolved[
                        "creative_set_name"
                    ]
                ),
                "combination_method": int(
                    req.combination_method
                ),
                "offer_id": int(
                    resolved[
                        "offer_id"
                    ]
                ),
                "geos": [
                    str(
                        geo
                    )
                    for geo in resolved[
                        "geos"
                    ]
                ],
                "ad_outputs": [
                    int(
                        item
                    )
                    for item in resolved[
                        "ad_outputs"
                    ]
                ],
                "creatives": [
                    {
                        "creative_name": str(
                            creative_name
                        ),
                        "creative_md5": str(
                            creative_md5
                        ),
                    }
                ],
            }

            write_response = (
                _mintegral_json_request(
                    config,
                    "POST",
                    "/api/open/v1/creative_set",
                    payload,
                    timeout=req.timeout_seconds,
                    stage=(
                        "mintegral_create_creative_set"
                    ),
                )
            )

    else:
        if existing_set is not None:
            write_action = (
                "WOULD_UPDATE_CREATIVE_SET"
            )
        else:
            write_action = (
                "WOULD_CREATE_CREATIVE_SET"
            )

    timestamp = (
        _app_now().strftime(
            "%Y-%m-%d_%H%M%S"
        )
    )

    out_dir = (
        WORKSPACE
        / "output"
        / "mintegral_publish"
        / timestamp
        / video_path.stem
    )

    out_dir.mkdir(
        parents=True,
        exist_ok=True,
    )

    result = {
        "ok": True,
        "version": "0.17.0",
        "mode": (
            "mintegral_publish_creative"
        ),
        "source": {
            "relative_path": (
                video_path
                .relative_to(
                    WORKSPACE
                )
                .as_posix()
            ),
        },
        "target": {
            "offer_id": (
                resolved[
                    "offer_id"
                ]
            ),
            "creative_set_name": (
                resolved[
                    "creative_set_name"
                ]
            ),
            "geos": (
                resolved[
                    "geos"
                ]
            ),
            "ad_outputs": (
                resolved[
                    "ad_outputs"
                ]
            ),
            "creative_set_existed_before": bool(
                existing_set is not None
            ),
        },
        "upload": upload,
        "publish": {
            "execute": bool(
                req.execute
            ),
            "action": (
                write_action
            ),
            "external_write_performed": bool(
                req.execute
                and write_response is not None
            ),
            "api_result": (
                {
                    "code": (
                        write_response.get(
                            "code"
                        )
                    ),
                    "message": (
                        write_response.get(
                            "msg"
                        )
                        or write_response.get(
                            "message"
                        )
                    ),
                }
                if write_response
                else None
            ),
        },
        "summary": {
            "dry_run": bool(
                not req.execute
            ),
            "creative_ready": bool(
                upload.get(
                    "creative_md5"
                )
            ),
            "creative_reused": (
                upload.get(
                    "status"
                )
                == "REUSED_EXISTING"
            ),
            "creative_uploaded": (
                upload.get(
                    "status"
                )
                == "UPLOADED"
            ),
            "creative_set_write_performed": bool(
                req.execute
                and write_response is not None
            ),
        },
        "notes": {
            "audit": (
                "After execute=true succeeds, use /integrations/mintegral/audit-status "
                "to read audit_status and audit_reason from the Creative Set."
            ),
            "idempotency": (
                "The local file MD5 is queried first; an already uploaded creative "
                "is reused instead of uploaded again."
            ),
        },
        "output_relative_dir": (
            out_dir
            .relative_to(
                WORKSPACE
            )
            .as_posix()
        ),
    }

    report_path = (
        out_dir
        / (
            f"{video_path.stem}"
            ".mintegral-publish.json"
        )
    )

    result[
        "report_relative_path"
    ] = (
        report_path
        .relative_to(
            WORKSPACE
        )
        .as_posix()
    )

    report_path.write_text(
        json.dumps(
            result,
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )

    return result


def _mintegral_audit_status_sync(
    req: MintegralAuditStatusRequest
):
    config = (
        _mintegral_config()
    )

    _mintegral_require_credentials(
        config
    )

    offer_id = (
        req.offer_id
        if req.offer_id is not None
        else config.get(
            "default_offer_id"
        )
    )

    creative_set_name = (
        req.creative_set_name
        or config.get(
            "default_creative_set_name"
        )
    )

    if offer_id is None:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": (
                    "mintegral_audit_status"
                ),
                "error": (
                    "offer_id_required"
                ),
            },
        )

    data = (
        _mintegral_creative_sets(
            config,
            offer_id=int(
                offer_id
            ),
            creative_set_name=(
                creative_set_name
            ),
            page=req.page,
            limit=req.limit,
            timeout=req.timeout_seconds,
        )
    )

    sets = (
        data.get(
            "list"
        )
        or []
    )

    creative_records = []

    for creative_set in sets:
        set_name = (
            creative_set.get(
                "creative_set_name"
            )
        )

        for creative in (
            creative_set.get(
                "creatives"
            )
            or []
        ):
            md5 = str(
                creative.get(
                    "creative_md5"
                )
                or ""
            )

            if (
                req.creative_md5
                and md5.lower()
                != str(
                    req.creative_md5
                ).lower()
            ):
                continue

            audit_status = (
                creative.get(
                    "audit_status"
                )
            )

            creative_records.append(
                {
                    "offer_id": (
                        creative_set.get(
                            "offer_id"
                        )
                    ),
                    "creative_set_name": (
                        set_name
                    ),
                    "creative_name": (
                        creative.get(
                            "creative_name"
                        )
                    ),
                    "creative_md5": md5,
                    "creative_type": (
                        creative.get(
                            "creative_type"
                        )
                    ),
                    "dimension": (
                        creative.get(
                            "dimension"
                        )
                    ),
                    "created_at": (
                        creative.get(
                            "created_at"
                        )
                    ),
                    "audit_status": (
                        audit_status
                    ),
                    "audit_label": (
                        _mintegral_audit_label(
                            audit_status
                        )
                    ),
                    "audit_reason": (
                        creative.get(
                            "audit_reason"
                        )
                        or ""
                    ),
                }
            )

    counts = defaultdict(
        int
    )

    for item in (
        creative_records
    ):
        counts[
            item[
                "audit_label"
            ]
        ] += 1

    if (
        creative_records
        and counts.get(
            "REJECTED",
            0,
        )
        > 0
    ):
        overall = "REJECTED"
    elif (
        creative_records
        and counts.get(
            "UNDER_REVIEW",
            0,
        )
        > 0
    ):
        overall = "UNDER_REVIEW"
    elif (
        creative_records
        and counts.get(
            "INITIALIZED",
            0,
        )
        > 0
    ):
        overall = "INITIALIZED"
    elif (
        creative_records
        and counts.get(
            "APPROVED",
            0,
        )
        == len(
            creative_records
        )
    ):
        overall = "APPROVED"
    else:
        overall = (
            "NOT_FOUND"
        )

    timestamp = (
        _app_now().strftime(
            "%Y-%m-%d_%H%M%S"
        )
    )

    out_dir = (
        WORKSPACE
        / "review"
        / "mintegral_audit"
        / timestamp
    )

    out_dir.mkdir(
        parents=True,
        exist_ok=True,
    )

    result = {
        "ok": True,
        "version": "0.17.0",
        "mode": (
            "mintegral_audit_status"
        ),
        "query": {
            "offer_id": int(
                offer_id
            ),
            "creative_set_name": (
                creative_set_name
            ),
            "creative_md5": (
                req.creative_md5
            ),
        },
        "summary": {
            "overall_status": (
                overall
            ),
            "creative_count": len(
                creative_records
            ),
            "counts": dict(
                counts
            ),
            "approved_count": int(
                counts.get(
                    "APPROVED",
                    0,
                )
            ),
            "rejected_count": int(
                counts.get(
                    "REJECTED",
                    0,
                )
            ),
            "under_review_count": int(
                counts.get(
                    "UNDER_REVIEW",
                    0,
                )
            ),
            "initialized_count": int(
                counts.get(
                    "INITIALIZED",
                    0,
                )
            ),
        },
        "creatives": (
            creative_records
        ),
        "notes": {
            "audit_mapping": {
                "0": "INITIALIZED",
                "1": "APPROVED",
                "2": "REJECTED",
                "3": "UNDER_REVIEW",
            },
        },
        "output_relative_dir": (
            out_dir
            .relative_to(
                WORKSPACE
            )
            .as_posix()
        ),
    }

    report_path = (
        out_dir
        / (
            f"offer-{int(offer_id)}"
            ".mintegral-audit.json"
        )
    )

    result[
        "report_relative_path"
    ] = (
        report_path
        .relative_to(
            WORKSPACE
        )
        .as_posix()
    )

    report_path.write_text(
        json.dumps(
            result,
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )

    return result




# ---------------------------------------------------------------------------
# v0.16.1 Mintegral Upload Only
#
# Current scope is intentionally minimal:
#
#   local MP4
#   -> POST multipart/form-data to
#      https://ss-storage-api.mintegral.com/api/open/v1/creatives/upload
#   -> creative_md5
#   -> creative_name
#
# No offer_id.
# No Creative Set.
# No campaign write.
# No audit query.
#
# Credentials remain local:
#   workspace/config/mintegral.env
#     MINTEGRAL_ACCESS_KEY=
#     MINTEGRAL_API_KEY=
# ---------------------------------------------------------------------------


class MintegralMaterialUploadRequest(BaseModel):
    video_relative_path: str

    # Optional upload filename. If omitted, a Mintegral-safe filename is
    # generated from the local filename.
    material_name: Optional[str] = None

    timeout_seconds: float = 180.0


def _mintegral_safe_upload_filename(
    path,
    requested_name=None,
):
    import re

    ext = path.suffix.lower()

    # Preserve common video extension; current workflow uploads MP4.
    if not ext:
        ext = ".mp4"

    raw_name = str(
        requested_name
        or path.stem
    ).strip()

    # If caller supplied an extension, strip it before sanitizing so we do not
    # produce name.mp4.mp4.
    requested_path = Path(
        raw_name
    )

    if requested_path.suffix:
        raw_name = (
            requested_path.stem
        )

    safe_stem = re.sub(
        r"[^A-Za-z0-9_]+",
        "_",
        raw_name,
    )

    safe_stem = re.sub(
        r"_+",
        "_",
        safe_stem,
    ).strip("_")

    if not safe_stem:
        safe_stem = "creative"

    return (
        safe_stem
        + ext
    )


def _mintegral_upload_material_direct(
    config,
    video_path,
    upload_filename,
    timeout_seconds,
):
    requests = (
        _mintegral_requests()
    )

    headers = (
        _mintegral_auth_headers(
            config
        )
    )

    url = (
        str(
            config[
                "storage_base"
            ]
        ).rstrip("/")
        + "/api/open/v1/creatives/upload"
    )

    with video_path.open(
        "rb"
    ) as f:
        response = requests.post(
            url,
            headers=headers,
            files={
                "file": (
                    upload_filename,
                    f,
                    "video/mp4",
                )
            },
            timeout=float(
                timeout_seconds
            ),
        )

    try:
        payload = response.json()
    except Exception:
        raise HTTPException(
            status_code=502,
            detail={
                "stage": (
                    "mintegral_upload_material"
                ),
                "error": (
                    "non_json_response"
                ),
                "http_status": int(
                    response.status_code
                ),
                "body": (
                    response.text[:1000]
                    if response.text
                    else ""
                ),
            },
        )

    code = payload.get(
        "code"
    )

    msg = str(
        payload.get(
            "msg"
        )
        or ""
    )

    data = (
        payload.get(
            "data"
        )
        or {}
    )

    if (
        response.status_code
        >= 400
        or int(
            code
            if code is not None
            else -1
        )
        != 200
    ):
        # Mintegral documents that an already-existing file MD5 produces an
        # error. Keep the upstream message intact so the operator can see
        # whether the cause is duplicate MD5, format, size, auth, etc.
        raise HTTPException(
            status_code=502,
            detail={
                "stage": (
                    "mintegral_upload_material"
                ),
                "error": (
                    "mintegral_upload_failed"
                ),
                "http_status": int(
                    response.status_code
                ),
                "api_code": code,
                "api_message": msg[:1200],
                "api_data": (
                    data
                    if isinstance(
                        data,
                        dict,
                    )
                    else None
                ),
            },
        )

    creative_md5 = (
        data.get(
            "creative_md5"
        )
    )

    creative_name = (
        data.get(
            "creative_name"
        )
    )

    if not creative_md5:
        raise HTTPException(
            status_code=502,
            detail={
                "stage": (
                    "mintegral_upload_material"
                ),
                "error": (
                    "success_without_creative_md5"
                ),
                "api_message": msg,
            },
        )

    return {
        "creative_md5": str(
            creative_md5
        ),
        "creative_name": str(
            creative_name
            or upload_filename
        ),
        "api_code": int(
            code
        ),
        "api_message": msg,
    }


def _mintegral_material_upload_sync(
    req: MintegralMaterialUploadRequest
):
    config = (
        _mintegral_config()
    )

    _mintegral_require_credentials(
        config
    )

    video_path = (
        _safe_workspace_path(
            req.video_relative_path
        )
    )

    if not video_path.is_file():
        raise HTTPException(
            status_code=422,
            detail={
                "stage": (
                    "mintegral_upload_material"
                ),
                "error": (
                    "video_not_found"
                ),
                "relative_path": (
                    req.video_relative_path
                ),
            },
        )

    if (
        video_path.suffix.lower()
        != ".mp4"
    ):
        raise HTTPException(
            status_code=422,
            detail={
                "stage": (
                    "mintegral_upload_material"
                ),
                "error": (
                    "expected_mp4_video"
                ),
                "relative_path": (
                    req.video_relative_path
                ),
            },
        )

    upload_filename = (
        _mintegral_safe_upload_filename(
            video_path,
            req.material_name,
        )
    )

    local_md5 = (
        _local_file_md5(
            video_path
        )
    )

    uploaded = (
        _mintegral_upload_material_direct(
            config,
            video_path,
            upload_filename,
            req.timeout_seconds,
        )
    )

    timestamp = (
        _app_now().strftime(
            "%Y-%m-%d_%H%M%S"
        )
    )

    out_dir = (
        WORKSPACE
        / "output"
        / "mintegral_upload"
        / timestamp
        / video_path.stem
    )

    out_dir.mkdir(
        parents=True,
        exist_ok=True,
    )

    result = {
        "ok": True,
        "version": "0.17.0",
        "mode": (
            "mintegral_material_upload"
        ),
        "source": {
            "relative_path": (
                video_path
                .relative_to(
                    WORKSPACE
                )
                .as_posix()
            ),
            "local_filename": (
                video_path.name
            ),
            "size_bytes": int(
                video_path.stat().st_size
            ),
            "local_md5": (
                local_md5
            ),
        },
        "upload": {
            "endpoint": (
                "https://ss-storage-api.mintegral.com"
                "/api/open/v1/creatives/upload"
            ),
            "multipart_field": "file",
            "upload_filename": (
                upload_filename
            ),
            "creative_md5": (
                uploaded[
                    "creative_md5"
                ]
            ),
            "creative_name": (
                uploaded[
                    "creative_name"
                ]
            ),
            "api_code": (
                uploaded[
                    "api_code"
                ]
            ),
            "api_message": (
                uploaded[
                    "api_message"
                ]
            ),
        },
        "summary": {
            "uploaded": True,
            "offer_id_required": False,
            "creative_set_required": False,
            "campaign_modified": False,
            "returned_creative_md5": True,
        },
        "notes": {
            "scope": (
                "Upload to Mintegral Creative Management > Materials only. "
                "No association to an Offer or Creative Set is performed."
            ),
            "duplicate": (
                "Mintegral may reject upload when the file MD5 already exists. "
                "The upstream API error is returned for operator review."
            ),
        },
        "output_relative_dir": (
            out_dir
            .relative_to(
                WORKSPACE
            )
            .as_posix()
        ),
    }

    report_path = (
        out_dir
        / (
            f"{video_path.stem}"
            ".mintegral-upload.json"
        )
    )

    result[
        "report_relative_path"
    ] = (
        report_path
        .relative_to(
            WORKSPACE
        )
        .as_posix()
    )

    report_path.write_text(
        json.dumps(
            result,
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )

    return result




# ---------------------------------------------------------------------------
# v0.16.2 One-Job Process + Mintegral Upload
#
# Main early-production workflow:
#
#   accepted replacement plan
#   -> replacement render
#   -> resolve generated final MP4
#   -> local MD5
#   -> local upload ledger
#   -> skip duplicate OR upload to Mintegral Materials
#   -> creative_md5 / creative_name
#   -> one job report
#
# Deferred:
#   subtitles / visible text
#   speech localization
#   BGM
#   Offer / Creative Set
#   audit polling
# ---------------------------------------------------------------------------


class CreativeProcessAndUploadRequest(BrandingReplacementRenderRequest):
    # Mintegral upload settings.
    upload_material_name: Optional[str] = None
    upload_timeout_seconds: float = 180.0

    # Local idempotency.
    skip_if_uploaded_locally: bool = True

    # Dedicated endpoint implies actual upload by default.
    # Set false only when testing the render/resolve/ledger steps.
    execute_upload: bool = True

    # If true, upload failure makes the whole job fail.
    # If false, render result/report is still returned with upload error.
    fail_job_if_upload_fails: bool = True


class CreativeUploadHistoryRequest(BaseModel):
    limit: int = 50
    local_md5: Optional[str] = None
    creative_md5: Optional[str] = None
    source_video_relative_path: Optional[str] = None


def _upload_ledger_path():
    return (
        WORKSPACE
        / "state"
        / "mintegral_upload_ledger.jsonl"
    )


def _read_upload_ledger():
    path = _upload_ledger_path()

    if not path.exists():
        return []

    rows = []

    try:
        raw = path.read_text(
            encoding="utf-8"
        )
    except Exception:
        return []

    for line in raw.splitlines():
        line = line.strip()

        if not line:
            continue

        try:
            item = json.loads(
                line
            )
        except Exception:
            continue

        if isinstance(
            item,
            dict,
        ):
            rows.append(
                item
            )

    return rows


def _append_upload_ledger(
    item,
):
    path = _upload_ledger_path()

    path.parent.mkdir(
        parents=True,
        exist_ok=True,
    )

    line = json.dumps(
        item,
        ensure_ascii=False,
        separators=(
            ",",
            ":",
        ),
    )

    with path.open(
        "a",
        encoding="utf-8",
    ) as f:
        f.write(
            line
            + "\n"
        )

    return path


def _find_uploaded_by_local_md5(
    local_md5,
):
    target = str(
        local_md5
        or ""
    ).strip().lower()

    if not target:
        return None

    for item in reversed(
        _read_upload_ledger()
    ):
        if (
            str(
                item.get(
                    "local_md5"
                )
                or ""
            ).strip().lower()
            == target
            and bool(
                item.get(
                    "uploaded"
                )
            )
            and item.get(
                "creative_md5"
            )
        ):
            return item

    return None


def _candidate_output_paths_from_render_result(
    result,
):
    candidates = []

    def add(
        value,
    ):
        if not value:
            return

        value = str(
            value
        ).strip()

        if (
            value
            and value not in candidates
        ):
            candidates.append(
                value
            )

    output = (
        result.get(
            "output"
        )
        or {}
    )

    if isinstance(
        output,
        dict,
    ):
        for key in (
            "relative_path",
            "video_relative_path",
            "output_relative_path",
            "processed_video_relative_path",
            "final_video_relative_path",
        ):
            add(
                output.get(
                    key
                )
            )

    for key in (
        "output_relative_path",
        "video_relative_path",
        "processed_video_relative_path",
        "final_video_relative_path",
    ):
        add(
            result.get(
                key
            )
        )

    # Timeline/items may contain generated outputs in some historical versions.
    for collection_key in (
        "outputs",
        "artifacts",
        "files",
    ):
        collection = (
            result.get(
                collection_key
            )
            or []
        )

        if not isinstance(
            collection,
            list,
        ):
            continue

        for item in collection:
            if not isinstance(
                item,
                dict,
            ):
                continue

            for key in (
                "relative_path",
                "video_relative_path",
                "output_relative_path",
            ):
                add(
                    item.get(
                        key
                    )
                )

    return candidates


def _resolve_rendered_mp4(
    result,
):
    # 1) Trust explicit report fields first.
    candidates = (
        _candidate_output_paths_from_render_result(
            result
        )
    )

    for rel in candidates:
        try:
            path = (
                _safe_workspace_path(
                    rel
                )
            )
        except Exception:
            continue

        if (
            path.is_file()
            and path.suffix.lower()
            == ".mp4"
        ):
            return path

    # 2) Fall back to output_relative_dir if the renderer only reported a dir.
    relative_dirs = []

    for key in (
        "output_relative_dir",
        "output_dir_relative_path",
    ):
        value = result.get(
            key
        )

        if value:
            relative_dirs.append(
                str(
                    value
                )
            )

    output = (
        result.get(
            "output"
        )
        or {}
    )

    if isinstance(
        output,
        dict,
    ):
        for key in (
            "relative_dir",
            "output_relative_dir",
        ):
            value = output.get(
                key
            )

            if value:
                relative_dirs.append(
                    str(
                        value
                    )
                )

    for rel_dir in relative_dirs:
        try:
            directory = (
                _safe_workspace_path(
                    rel_dir
                )
            )
        except Exception:
            continue

        if not directory.is_dir():
            continue

        mp4s = sorted(
            directory.glob(
                "*.mp4"
            ),
            key=lambda p: (
                p.stat().st_mtime
                if p.exists()
                else 0.0
            ),
            reverse=True,
        )

        if mp4s:
            return mp4s[0]

    # 3) Last-resort extraction from report path: inspect sibling folder.
    report_rel = result.get(
        "report_relative_path"
    )

    if report_rel:
        try:
            report_path = (
                _safe_workspace_path(
                    report_rel
                )
            )

            if report_path.parent.is_dir():
                mp4s = sorted(
                    report_path.parent.glob(
                        "*.mp4"
                    ),
                    key=lambda p: (
                        p.stat().st_mtime
                        if p.exists()
                        else 0.0
                    ),
                    reverse=True,
                )

                if mp4s:
                    return mp4s[0]
        except Exception:
            pass

    raise HTTPException(
        status_code=500,
        detail={
            "stage": (
                "process_and_upload"
            ),
            "error": (
                "render_succeeded_but_output_mp4_not_resolved"
            ),
            "candidate_paths": candidates[
                :20
            ],
            "report_relative_path": (
                result.get(
                    "report_relative_path"
                )
            ),
        },
    )


def _render_request_from_process_upload(
    req,
):
    payload = req.model_dump()

    allowed = (
        BrandingReplacementRenderRequest
        .model_fields
        .keys()
    )

    render_payload = {
        key: value
        for key, value in (
            payload.items()
        )
        if key in allowed
    }

    # Keep deferred branches out of the main early-production workflow.
    render_payload[
        "diagonal_brand_cover_enabled"
    ] = False

    return (
        BrandingReplacementRenderRequest(
            **render_payload
        )
    )


def _process_and_upload_sync(
    req: CreativeProcessAndUploadRequest
):
    started_at = (
        _app_now()
    )

    config = (
        _mintegral_config()
    )

    if bool(
        req.execute_upload
    ):
        _mintegral_require_credentials(
            config
        )

    render_req = (
        _render_request_from_process_upload(
            req
        )
    )

    render_result = (
        _replacement_render_sync(
            render_req
        )
    )

    rendered_path = (
        _resolve_rendered_mp4(
            render_result
        )
    )

    local_md5 = (
        _local_file_md5(
            rendered_path
        )
    )

    previous = None

    if bool(
        req.skip_if_uploaded_locally
    ):
        previous = (
            _find_uploaded_by_local_md5(
                local_md5
            )
        )

    upload_status = None
    upload_result = None
    upload_error = None
    ledger_record = None

    if previous is not None:
        upload_status = (
            "SKIPPED_ALREADY_UPLOADED"
        )

        upload_result = {
            "creative_md5": (
                previous.get(
                    "creative_md5"
                )
            ),
            "creative_name": (
                previous.get(
                    "creative_name"
                )
            ),
            "previous_uploaded_at": (
                previous.get(
                    "uploaded_at"
                )
            ),
            "previous_job_id": (
                previous.get(
                    "job_id"
                )
            ),
        }

    elif not bool(
        req.execute_upload
    ):
        upload_status = (
            "UPLOAD_NOT_EXECUTED"
        )

    else:
        upload_filename = (
            _mintegral_safe_upload_filename(
                rendered_path,
                req.upload_material_name,
            )
        )

        try:
            uploaded = (
                _mintegral_upload_material_direct(
                    config,
                    rendered_path,
                    upload_filename,
                    req.upload_timeout_seconds,
                )
            )

            upload_status = (
                "UPLOADED"
            )

            upload_result = {
                "creative_md5": (
                    uploaded[
                        "creative_md5"
                    ]
                ),
                "creative_name": (
                    uploaded[
                        "creative_name"
                    ]
                ),
                "api_code": (
                    uploaded[
                        "api_code"
                    ]
                ),
                "api_message": (
                    uploaded[
                        "api_message"
                    ]
                ),
                "upload_filename": (
                    upload_filename
                ),
            }

        except HTTPException as exc:
            upload_status = (
                "UPLOAD_FAILED"
            )

            upload_error = (
                exc.detail
            )

            if bool(
                req.fail_job_if_upload_fails
            ):
                # Preserve a failed job record before re-raising.
                failed_at = (
                    _app_now()
                )

                job_id = (
                    started_at.strftime(
                        "%Y%m%d_%H%M%S"
                    )
                    + "-"
                    + rendered_path.stem[
                        :36
                    ]
                )

                failed_record = {
                    "job_id": job_id,
                    "uploaded": False,
                    "upload_status": (
                        upload_status
                    ),
                    "source_plan_relative_path": (
                        req.replacement_plan_relative_path
                    ),
                    "processed_video_relative_path": (
                        rendered_path
                        .relative_to(
                            WORKSPACE
                        )
                        .as_posix()
                    ),
                    "local_md5": (
                        local_md5
                    ),
                    "creative_md5": None,
                    "creative_name": None,
                    "uploaded_at": None,
                    "failed_at": (
                        failed_at.isoformat()
                    ),
                    "error": (
                        upload_error
                    ),
                }

                _append_upload_ledger(
                    failed_record
                )

                raise

    finished_at = (
        _app_now()
    )

    job_id = (
        started_at.strftime(
            "%Y%m%d_%H%M%S"
        )
        + "-"
        + rendered_path.stem[
            :36
        ]
    )

    uploaded_flag = bool(
        upload_status
        in (
            "UPLOADED",
            "SKIPPED_ALREADY_UPLOADED",
        )
        and upload_result
        and upload_result.get(
            "creative_md5"
        )
    )

    ledger_record = {
        "job_id": (
            job_id
        ),
        "uploaded": (
            uploaded_flag
        ),
        "upload_status": (
            upload_status
        ),
        "source_plan_relative_path": (
            req.replacement_plan_relative_path
        ),
        "processed_video_relative_path": (
            rendered_path
            .relative_to(
                WORKSPACE
            )
            .as_posix()
        ),
        "local_md5": (
            local_md5
        ),
        "creative_md5": (
            upload_result.get(
                "creative_md5"
            )
            if upload_result
            else None
        ),
        "creative_name": (
            upload_result.get(
                "creative_name"
            )
            if upload_result
            else None
        ),
        "uploaded_at": (
            finished_at.isoformat()
            if uploaded_flag
            else None
        ),
        "created_at": (
            finished_at.isoformat()
        ),
    }

    ledger_path = (
        _append_upload_ledger(
            ledger_record
        )
    )

    job_dir = (
        WORKSPACE
        / "output"
        / "process_and_upload"
        / started_at.strftime(
            "%Y-%m-%d_%H%M%S"
        )
        / rendered_path.stem
    )

    job_dir.mkdir(
        parents=True,
        exist_ok=True,
    )

    result = {
        "ok": bool(
            upload_status
            != "UPLOAD_FAILED"
        ),
        "version": "0.17.0",
        "mode": (
            "creative_process_and_upload"
        ),
        "job_id": (
            job_id
        ),
        "render": {
            "ok": bool(
                render_result.get(
                    "ok",
                    True,
                )
            ),
            "version": (
                render_result.get(
                    "version"
                )
            ),
            "processed_video_relative_path": (
                rendered_path
                .relative_to(
                    WORKSPACE
                )
                .as_posix()
            ),
            "report_relative_path": (
                render_result.get(
                    "report_relative_path"
                )
            ),
            "local_md5": (
                local_md5
            ),
        },
        "mintegral": {
            "execute_upload": bool(
                req.execute_upload
            ),
            "status": (
                upload_status
            ),
            "creative_md5": (
                upload_result.get(
                    "creative_md5"
                )
                if upload_result
                else None
            ),
            "creative_name": (
                upload_result.get(
                    "creative_name"
                )
                if upload_result
                else None
            ),
            "reused_local_ledger": bool(
                previous is not None
            ),
            "error": (
                upload_error
            ),
        },
        "ledger": {
            "relative_path": (
                ledger_path
                .relative_to(
                    WORKSPACE
                )
                .as_posix()
            ),
            "record": (
                ledger_record
            ),
        },
        "summary": {
            "render_completed": True,
            "output_mp4_resolved": True,
            "uploaded_or_already_uploaded": (
                uploaded_flag
            ),
            "new_external_upload_performed": (
                upload_status
                == "UPLOADED"
            ),
            "duplicate_upload_skipped": (
                upload_status
                == (
                    "SKIPPED_ALREADY_UPLOADED"
                )
            ),
            "subtitles_processed": False,
            "speech_localized": False,
            "bgm_processed": False,
            "offer_or_creative_set_modified": False,
        },
        "timing": {
            "started_at": (
                started_at.isoformat()
            ),
            "finished_at": (
                finished_at.isoformat()
            ),
            "elapsed_seconds": round(
                (
                    finished_at
                    - started_at
                ).total_seconds(),
                3,
            ),
        },
        "notes": {
            "idempotency": (
                "Successful uploads are recorded by local processed-file MD5. "
                "Running the same final MP4 again skips Mintegral upload by default."
            ),
            "scope": (
                "The job ends after Mintegral Creative Management material upload. "
                "No Offer / Creative Set / campaign operation is performed."
            ),
        },
        "output_relative_dir": (
            job_dir
            .relative_to(
                WORKSPACE
            )
            .as_posix()
        ),
    }

    report_path = (
        job_dir
        / (
            rendered_path.stem
            + ".process-upload-job.json"
        )
    )

    result[
        "report_relative_path"
    ] = (
        report_path
        .relative_to(
            WORKSPACE
        )
        .as_posix()
    )

    report_path.write_text(
        json.dumps(
            result,
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )

    return result


def _upload_history_sync(
    req: CreativeUploadHistoryRequest
):
    rows = (
        _read_upload_ledger()
    )

    def match(
        item,
    ):
        if (
            req.local_md5
            and str(
                item.get(
                    "local_md5"
                )
                or ""
            ).lower()
            != str(
                req.local_md5
            ).lower()
        ):
            return False

        if (
            req.creative_md5
            and str(
                item.get(
                    "creative_md5"
                )
                or ""
            ).lower()
            != str(
                req.creative_md5
            ).lower()
        ):
            return False

        if (
            req.source_video_relative_path
            and str(
                item.get(
                    "processed_video_relative_path"
                )
                or ""
            )
            != str(
                req.source_video_relative_path
            )
        ):
            return False

        return True

    filtered = [
        item
        for item in reversed(
            rows
        )
        if match(
            item
        )
    ]

    limit = min(
        500,
        max(
            1,
            int(
                req.limit
            ),
        ),
    )

    filtered = (
        filtered[
            :limit
        ]
    )

    return {
        "ok": True,
        "version": "0.17.0",
        "mode": (
            "creative_upload_history"
        ),
        "count": len(
            filtered
        ),
        "items": (
            filtered
        ),
        "ledger_relative_path": (
            _upload_ledger_path()
            .relative_to(
                WORKSPACE
            )
            .as_posix()
        ),
    }




# ---------------------------------------------------------------------------
# v0.16.3 Mintegral Existing-MD5 = Idempotent Success
#
# Mintegral upload may return:
#
#   HTTP 200
#   code = 500
#   msg = "failed"
#   data.file.creative_name =
#       "Creative is already existed, please change to another.
#        fmd5: <md5>, name: <filename>"
#
# This is not a workflow failure. The material is already present in Creative
# Management > Materials and Mintegral gives us the reusable creative MD5.
#
# New behavior:
#   -> parse fmd5 + name
#   -> REUSED_MINTEGRAL_EXISTING
#   -> write it to local upload ledger
#   -> future identical local MP4 runs become SKIPPED_ALREADY_UPLOADED
# ---------------------------------------------------------------------------


def _parse_mintegral_existing_material(
    payload,
    fallback_name,
):
    import re

    if not isinstance(
        payload,
        dict,
    ):
        return None

    try:
        code = int(
            payload.get(
                "code"
            )
        )
    except Exception:
        code = None

    if code == 200:
        return None

    data = (
        payload.get(
            "data"
        )
        or {}
    )

    if not isinstance(
        data,
        dict,
    ):
        return None

    messages = []

    def collect_strings(
        value,
    ):
        if isinstance(
            value,
            str,
        ):
            messages.append(
                value
            )
            return

        if isinstance(
            value,
            dict,
        ):
            for nested in (
                value.values()
            ):
                collect_strings(
                    nested
                )
            return

        if isinstance(
            value,
            list,
        ):
            for nested in value:
                collect_strings(
                    nested
                )

    collect_strings(
        data
    )

    for message in messages:
        lower = message.lower()

        if not (
            "already existed"
            in lower
            or "already exists"
            in lower
        ):
            continue

        md5_match = re.search(
            r"\bfmd5\s*:\s*([0-9a-fA-F]{32})\b",
            message,
            flags=re.IGNORECASE,
        )

        if not md5_match:
            md5_match = re.search(
                r"\bcreative_md5\s*:\s*([0-9a-fA-F]{32})\b",
                message,
                flags=re.IGNORECASE,
            )

        if not md5_match:
            continue

        name_match = re.search(
            r"\bname\s*:\s*(.+?)\s*$",
            message,
            flags=re.IGNORECASE,
        )

        creative_name = (
            name_match.group(1).strip()
            if name_match
            else str(
                fallback_name
            )
        )

        # Defensive trim if upstream appends punctuation.
        creative_name = (
            creative_name
            .strip()
            .strip('"')
            .strip("'")
        )

        return {
            "creative_md5": (
                md5_match.group(1)
                .lower()
            ),
            "creative_name": (
                creative_name
                or str(
                    fallback_name
                )
            ),
            "duplicate_message": (
                message
            ),
            "api_code": code,
            "api_message": str(
                payload.get(
                    "msg"
                )
                or ""
            ),
        }

    return None


def _mintegral_upload_material_direct(
    config,
    video_path,
    upload_filename,
    timeout_seconds,
):
    requests = (
        _mintegral_requests()
    )

    headers = (
        _mintegral_auth_headers(
            config
        )
    )

    url = (
        str(
            config[
                "storage_base"
            ]
        ).rstrip("/")
        + "/api/open/v1/creatives/upload"
    )

    with video_path.open(
        "rb"
    ) as f:
        response = requests.post(
            url,
            headers=headers,
            files={
                "file": (
                    upload_filename,
                    f,
                    "video/mp4",
                )
            },
            timeout=float(
                timeout_seconds
            ),
        )

    try:
        payload = response.json()
    except Exception:
        raise HTTPException(
            status_code=502,
            detail={
                "stage": (
                    "mintegral_upload_material"
                ),
                "error": (
                    "non_json_response"
                ),
                "http_status": int(
                    response.status_code
                ),
                "body": (
                    response.text[:1000]
                    if response.text
                    else ""
                ),
            },
        )

    code = payload.get(
        "code"
    )

    msg = str(
        payload.get(
            "msg"
        )
        or ""
    )

    data = (
        payload.get(
            "data"
        )
        or {}
    )

    success = False

    try:
        success = (
            response.status_code < 400
            and int(code) == 200
        )
    except Exception:
        success = False

    if not success:
        existing = (
            _parse_mintegral_existing_material(
                payload,
                upload_filename,
            )
        )

        if existing is not None:
            return {
                "status": (
                    "REUSED_MINTEGRAL_EXISTING"
                ),
                "creative_md5": (
                    existing[
                        "creative_md5"
                    ]
                ),
                "creative_name": (
                    existing[
                        "creative_name"
                    ]
                ),
                "api_code": (
                    existing[
                        "api_code"
                    ]
                ),
                "api_message": (
                    existing[
                        "api_message"
                    ]
                ),
                "duplicate_message": (
                    existing[
                        "duplicate_message"
                    ]
                ),
                "new_upload_performed": False,
                "mintegral_material_already_existed": True,
            }

        raise HTTPException(
            status_code=502,
            detail={
                "stage": (
                    "mintegral_upload_material"
                ),
                "error": (
                    "mintegral_upload_failed"
                ),
                "http_status": int(
                    response.status_code
                ),
                "api_code": code,
                "api_message": msg[:1200],
                "api_data": (
                    data
                    if isinstance(
                        data,
                        dict,
                    )
                    else None
                ),
            },
        )

    if not isinstance(
        data,
        dict,
    ):
        data = {}

    creative_md5 = (
        data.get(
            "creative_md5"
        )
    )

    creative_name = (
        data.get(
            "creative_name"
        )
    )

    if not creative_md5:
        raise HTTPException(
            status_code=502,
            detail={
                "stage": (
                    "mintegral_upload_material"
                ),
                "error": (
                    "success_without_creative_md5"
                ),
                "api_message": msg,
            },
        )

    return {
        "status": "UPLOADED",
        "creative_md5": str(
            creative_md5
        ),
        "creative_name": str(
            creative_name
            or upload_filename
        ),
        "api_code": int(
            code
        ),
        "api_message": msg,
        "duplicate_message": None,
        "new_upload_performed": True,
        "mintegral_material_already_existed": False,
    }


def _mintegral_material_upload_sync(
    req: MintegralMaterialUploadRequest
):
    config = (
        _mintegral_config()
    )

    _mintegral_require_credentials(
        config
    )

    video_path = (
        _safe_workspace_path(
            req.video_relative_path
        )
    )

    if not video_path.is_file():
        raise HTTPException(
            status_code=422,
            detail={
                "stage": (
                    "mintegral_upload_material"
                ),
                "error": (
                    "video_not_found"
                ),
                "relative_path": (
                    req.video_relative_path
                ),
            },
        )

    if (
        video_path.suffix.lower()
        != ".mp4"
    ):
        raise HTTPException(
            status_code=422,
            detail={
                "stage": (
                    "mintegral_upload_material"
                ),
                "error": (
                    "expected_mp4_video"
                ),
                "relative_path": (
                    req.video_relative_path
                ),
            },
        )

    upload_filename = (
        _mintegral_safe_upload_filename(
            video_path,
            req.material_name,
        )
    )

    local_md5 = (
        _local_file_md5(
            video_path
        )
    )

    uploaded = (
        _mintegral_upload_material_direct(
            config,
            video_path,
            upload_filename,
            req.timeout_seconds,
        )
    )

    status = str(
        uploaded.get(
            "status"
        )
        or "UPLOADED"
    )

    now = (
        _app_now()
    )

    # Direct-upload endpoint also seeds the same local ledger so the combined
    # workflow can skip this file in later runs.
    ledger_record = {
        "job_id": (
            now.strftime(
                "%Y%m%d_%H%M%S"
            )
            + "-direct-upload-"
            + video_path.stem[
                :28
            ]
        ),
        "uploaded": True,
        "upload_status": status,
        "source_plan_relative_path": None,
        "processed_video_relative_path": (
            video_path
            .relative_to(
                WORKSPACE
            )
            .as_posix()
        ),
        "local_md5": local_md5,
        "creative_md5": (
            uploaded[
                "creative_md5"
            ]
        ),
        "creative_name": (
            uploaded[
                "creative_name"
            ]
        ),
        "uploaded_at": (
            now.isoformat()
        ),
        "created_at": (
            now.isoformat()
        ),
    }

    ledger_path = (
        _append_upload_ledger(
            ledger_record
        )
    )

    timestamp = (
        _app_now().strftime(
            "%Y-%m-%d_%H%M%S"
        )
    )

    out_dir = (
        WORKSPACE
        / "output"
        / "mintegral_upload"
        / timestamp
        / video_path.stem
    )

    out_dir.mkdir(
        parents=True,
        exist_ok=True,
    )

    result = {
        "ok": True,
        "version": "0.17.0",
        "mode": (
            "mintegral_material_upload"
        ),
        "source": {
            "relative_path": (
                video_path
                .relative_to(
                    WORKSPACE
                )
                .as_posix()
            ),
            "local_filename": (
                video_path.name
            ),
            "size_bytes": int(
                video_path.stat().st_size
            ),
            "local_md5": local_md5,
        },
        "upload": {
            "status": status,
            "endpoint": (
                "https://ss-storage-api.mintegral.com"
                "/api/open/v1/creatives/upload"
            ),
            "multipart_field": "file",
            "upload_filename": (
                upload_filename
            ),
            "creative_md5": (
                uploaded[
                    "creative_md5"
                ]
            ),
            "creative_name": (
                uploaded[
                    "creative_name"
                ]
            ),
            "api_code": (
                uploaded[
                    "api_code"
                ]
            ),
            "api_message": (
                uploaded[
                    "api_message"
                ]
            ),
            "duplicate_message": (
                uploaded.get(
                    "duplicate_message"
                )
            ),
        },
        "ledger": {
            "relative_path": (
                ledger_path
                .relative_to(
                    WORKSPACE
                )
                .as_posix()
            ),
            "record": ledger_record,
        },
        "summary": {
            "material_available_in_mintegral": True,
            "new_upload_performed": bool(
                uploaded.get(
                    "new_upload_performed"
                )
            ),
            "reused_existing_mintegral_material": (
                status
                == "REUSED_MINTEGRAL_EXISTING"
            ),
            "offer_id_required": False,
            "creative_set_required": False,
            "campaign_modified": False,
            "returned_creative_md5": True,
        },
    }

    report_path = (
        out_dir
        / (
            f"{video_path.stem}"
            ".mintegral-upload.json"
        )
    )

    result[
        "report_relative_path"
    ] = (
        report_path
        .relative_to(
            WORKSPACE
        )
        .as_posix()
    )

    report_path.write_text(
        json.dumps(
            result,
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )

    return result


_process_and_upload_sync_v0162 = (
    _process_and_upload_sync
)


def _process_and_upload_sync(
    req: CreativeProcessAndUploadRequest
):
    # v0.16.2 already handles local-ledger reuse.
    # The only missing behavior was Mintegral-side existing-MD5 reuse.
    #
    # We reimplement the narrow upload decision here so an upstream duplicate
    # response becomes success and is seeded into the local ledger.
    started_at = (
        _app_now()
    )

    config = (
        _mintegral_config()
    )

    if bool(
        req.execute_upload
    ):
        _mintegral_require_credentials(
            config
        )

    render_req = (
        _render_request_from_process_upload(
            req
        )
    )

    render_result = (
        _replacement_render_sync(
            render_req
        )
    )

    rendered_path = (
        _resolve_rendered_mp4(
            render_result
        )
    )

    local_md5 = (
        _local_file_md5(
            rendered_path
        )
    )

    previous = None

    if bool(
        req.skip_if_uploaded_locally
    ):
        previous = (
            _find_uploaded_by_local_md5(
                local_md5
            )
        )

    upload_status = None
    upload_result = None
    upload_error = None

    if previous is not None:
        upload_status = (
            "SKIPPED_ALREADY_UPLOADED"
        )

        upload_result = {
            "creative_md5": (
                previous.get(
                    "creative_md5"
                )
            ),
            "creative_name": (
                previous.get(
                    "creative_name"
                )
            ),
            "previous_uploaded_at": (
                previous.get(
                    "uploaded_at"
                )
            ),
            "previous_job_id": (
                previous.get(
                    "job_id"
                )
            ),
        }

    elif not bool(
        req.execute_upload
    ):
        upload_status = (
            "UPLOAD_NOT_EXECUTED"
        )

    else:
        upload_filename = (
            _mintegral_safe_upload_filename(
                rendered_path,
                req.upload_material_name,
            )
        )

        try:
            uploaded = (
                _mintegral_upload_material_direct(
                    config,
                    rendered_path,
                    upload_filename,
                    req.upload_timeout_seconds,
                )
            )

            upload_status = str(
                uploaded.get(
                    "status"
                )
                or "UPLOADED"
            )

            upload_result = {
                "creative_md5": (
                    uploaded[
                        "creative_md5"
                    ]
                ),
                "creative_name": (
                    uploaded[
                        "creative_name"
                    ]
                ),
                "api_code": (
                    uploaded[
                        "api_code"
                    ]
                ),
                "api_message": (
                    uploaded[
                        "api_message"
                    ]
                ),
                "upload_filename": (
                    upload_filename
                ),
                "duplicate_message": (
                    uploaded.get(
                        "duplicate_message"
                    )
                ),
            }

        except HTTPException as exc:
            upload_status = (
                "UPLOAD_FAILED"
            )

            upload_error = (
                exc.detail
            )

            if bool(
                req.fail_job_if_upload_fails
            ):
                failed_at = (
                    _app_now()
                )

                job_id = (
                    started_at.strftime(
                        "%Y%m%d_%H%M%S"
                    )
                    + "-"
                    + rendered_path.stem[
                        :36
                    ]
                )

                failed_record = {
                    "job_id": job_id,
                    "uploaded": False,
                    "upload_status": (
                        upload_status
                    ),
                    "source_plan_relative_path": (
                        req.replacement_plan_relative_path
                    ),
                    "processed_video_relative_path": (
                        rendered_path
                        .relative_to(
                            WORKSPACE
                        )
                        .as_posix()
                    ),
                    "local_md5": (
                        local_md5
                    ),
                    "creative_md5": None,
                    "creative_name": None,
                    "uploaded_at": None,
                    "failed_at": (
                        failed_at.isoformat()
                    ),
                    "error": (
                        upload_error
                    ),
                }

                _append_upload_ledger(
                    failed_record
                )

                raise

    finished_at = (
        _app_now()
    )

    job_id = (
        started_at.strftime(
            "%Y%m%d_%H%M%S"
        )
        + "-"
        + rendered_path.stem[
            :36
        ]
    )

    success_statuses = (
        "UPLOADED",
        "REUSED_MINTEGRAL_EXISTING",
        "SKIPPED_ALREADY_UPLOADED",
    )

    uploaded_flag = bool(
        upload_status
        in success_statuses
        and upload_result
        and upload_result.get(
            "creative_md5"
        )
    )

    ledger_record = {
        "job_id": job_id,
        "uploaded": uploaded_flag,
        "upload_status": upload_status,
        "source_plan_relative_path": (
            req.replacement_plan_relative_path
        ),
        "processed_video_relative_path": (
            rendered_path
            .relative_to(
                WORKSPACE
            )
            .as_posix()
        ),
        "local_md5": local_md5,
        "creative_md5": (
            upload_result.get(
                "creative_md5"
            )
            if upload_result
            else None
        ),
        "creative_name": (
            upload_result.get(
                "creative_name"
            )
            if upload_result
            else None
        ),
        "uploaded_at": (
            finished_at.isoformat()
            if uploaded_flag
            else None
        ),
        "created_at": (
            finished_at.isoformat()
        ),
    }

    ledger_path = (
        _append_upload_ledger(
            ledger_record
        )
    )

    job_dir = (
        WORKSPACE
        / "output"
        / "process_and_upload"
        / started_at.strftime(
            "%Y-%m-%d_%H%M%S"
        )
        / rendered_path.stem
    )

    job_dir.mkdir(
        parents=True,
        exist_ok=True,
    )

    result = {
        "ok": bool(
            upload_status
            != "UPLOAD_FAILED"
        ),
        "version": "0.17.0",
        "mode": (
            "creative_process_and_upload"
        ),
        "job_id": job_id,
        "render": {
            "ok": bool(
                render_result.get(
                    "ok",
                    True,
                )
            ),
            "version": (
                render_result.get(
                    "version"
                )
            ),
            "processed_video_relative_path": (
                rendered_path
                .relative_to(
                    WORKSPACE
                )
                .as_posix()
            ),
            "report_relative_path": (
                render_result.get(
                    "report_relative_path"
                )
            ),
            "local_md5": local_md5,
        },
        "mintegral": {
            "execute_upload": bool(
                req.execute_upload
            ),
            "status": upload_status,
            "creative_md5": (
                upload_result.get(
                    "creative_md5"
                )
                if upload_result
                else None
            ),
            "creative_name": (
                upload_result.get(
                    "creative_name"
                )
                if upload_result
                else None
            ),
            "reused_local_ledger": bool(
                previous is not None
            ),
            "reused_existing_mintegral_material": (
                upload_status
                == "REUSED_MINTEGRAL_EXISTING"
            ),
            "error": upload_error,
        },
        "ledger": {
            "relative_path": (
                ledger_path
                .relative_to(
                    WORKSPACE
                )
                .as_posix()
            ),
            "record": ledger_record,
        },
        "summary": {
            "render_completed": True,
            "output_mp4_resolved": True,
            "material_available_in_mintegral": (
                uploaded_flag
            ),
            "new_external_upload_performed": (
                upload_status
                == "UPLOADED"
            ),
            "mintegral_existing_material_reused": (
                upload_status
                == "REUSED_MINTEGRAL_EXISTING"
            ),
            "duplicate_upload_skipped_by_local_ledger": (
                upload_status
                == "SKIPPED_ALREADY_UPLOADED"
            ),
            "offer_or_creative_set_modified": False,
        },
        "timing": {
            "started_at": (
                started_at.isoformat()
            ),
            "finished_at": (
                finished_at.isoformat()
            ),
            "elapsed_seconds": round(
                (
                    finished_at
                    - started_at
                ).total_seconds(),
                3,
            ),
        },
        "notes": {
            "idempotency": (
                "Both local-ledger duplicates and Mintegral-side existing-MD5 "
                "responses are treated as successful material availability."
            ),
        },
        "output_relative_dir": (
            job_dir
            .relative_to(
                WORKSPACE
            )
            .as_posix()
        ),
    }

    report_path = (
        job_dir
        / (
            rendered_path.stem
            + ".process-upload-job.json"
        )
    )

    result[
        "report_relative_path"
    ] = (
        report_path
        .relative_to(
            WORKSPACE
        )
        .as_posix()
    )

    report_path.write_text(
        json.dumps(
            result,
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )

    return result




# ---------------------------------------------------------------------------
# v0.16.4 Render Cache / Process Key
#
# Same accepted plan + same source + same referenced brand assets
# + same render request + same renderer code:
#
#   -> same process_key
#   -> reuse already rendered MP4
#   -> then reuse Mintegral ledger if already uploaded
#
# This removes the ~6-7 minute re-render cost from repeated identical jobs.
# ---------------------------------------------------------------------------


class CreativeProcessAndUploadRequest(BrandingReplacementRenderRequest):
    upload_material_name: Optional[str] = None
    upload_timeout_seconds: float = 180.0

    skip_if_uploaded_locally: bool = True
    execute_upload: bool = True
    fail_job_if_upload_fails: bool = True

    # v0.16.4
    use_render_cache: bool = True
    force_render: bool = False

    # Cache hit validation:
    # If file size + mtime still match the cache entry, the stored MD5 is
    # trusted. If they changed, MD5 is recomputed when this is true.
    verify_cached_file_md5: bool = True


def _sha256_file(
    path,
):
    import hashlib

    digest = hashlib.sha256()

    with path.open(
        "rb"
    ) as f:
        while True:
            chunk = f.read(
                1024 * 1024
            )

            if not chunk:
                break

            digest.update(
                chunk
            )

    return digest.hexdigest()


def _sha256_bytes(
    value,
):
    import hashlib

    return hashlib.sha256(
        value
    ).hexdigest()


def _renderer_code_fingerprint():
    try:
        path = Path(
            __file__
        )

        if path.is_file():
            return {
                "relative_or_name": (
                    path.name
                ),
                "sha256": (
                    _sha256_file(
                        path
                    )
                ),
            }
    except Exception:
        pass

    return {
        "relative_or_name": (
            "branding_v09.py"
        ),
        "sha256": (
            "unavailable"
        ),
    }


def _cache_safe_workspace_file(
    rel,
):
    if not rel:
        return None

    try:
        path = (
            _safe_workspace_path(
                str(rel)
            )
        )
    except Exception:
        return None

    if not path.is_file():
        return None

    return path


def _find_source_video_in_plan(
    plan,
):
    direct_candidates = []

    for container_key in (
        "source",
        "video",
        "input",
    ):
        container = (
            plan.get(
                container_key
            )
            or {}
        )

        if isinstance(
            container,
            dict,
        ):
            for key in (
                "relative_path",
                "video_relative_path",
                "source_video_relative_path",
                "path",
            ):
                value = (
                    container.get(
                        key
                    )
                )

                if value:
                    direct_candidates.append(
                        value
                    )

    for key in (
        "source_video_relative_path",
        "video_relative_path",
        "source_relative_path",
    ):
        value = plan.get(
            key
        )

        if value:
            direct_candidates.append(
                value
            )

    for rel in direct_candidates:
        path = (
            _cache_safe_workspace_file(
                rel
            )
        )

        if (
            path is not None
            and path.suffix.lower()
            in (
                ".mp4",
                ".mov",
                ".m4v",
                ".webm",
            )
        ):
            return path

    # Conservative recursive fallback: only existing workspace video files.
    found = []

    def walk(
        value,
    ):
        if isinstance(
            value,
            dict,
        ):
            for nested in (
                value.values()
            ):
                walk(
                    nested
                )
            return

        if isinstance(
            value,
            list,
        ):
            for nested in value:
                walk(
                    nested
                )
            return

        if not isinstance(
            value,
            str,
        ):
            return

        lower = value.lower()

        if not lower.endswith(
            (
                ".mp4",
                ".mov",
                ".m4v",
                ".webm",
            )
        ):
            return

        path = (
            _cache_safe_workspace_file(
                value
            )
        )

        if path is not None:
            found.append(
                path
            )

    walk(
        plan
    )

    if not found:
        return None

    # Prefer raw/input-like paths over generated review/output paths.
    found.sort(
        key=lambda p: (
            0
            if (
                "raw" in [
                    part.lower()
                    for part in p.parts
                ]
            )
            else 1,
            len(
                str(
                    p
                )
            ),
        )
    )

    return found[0]


def _collect_profile_asset_files(
    plan,
):
    profile = (
        plan.get(
            "profile"
        )
        or {}
    )

    files = []
    seen = set()

    def add_path(
        rel,
    ):
        path = (
            _cache_safe_workspace_file(
                rel
            )
        )

        if path is None:
            return

        key = str(
            path.resolve()
        ).lower()

        if key in seen:
            return

        seen.add(
            key
        )

        files.append(
            path
        )

    def walk(
        value,
    ):
        if isinstance(
            value,
            dict,
        ):
            for nested in (
                value.values()
            ):
                walk(
                    nested
                )
            return

        if isinstance(
            value,
            list,
        ):
            for nested in value:
                walk(
                    nested
                )
            return

        if not isinstance(
            value,
            str,
        ):
            return

        lower = value.lower()

        if lower.endswith(
            (
                ".png",
                ".jpg",
                ".jpeg",
                ".webp",
                ".mp4",
                ".mov",
                ".m4v",
            )
        ):
            add_path(
                value
            )

    walk(
        profile
    )

    # Include standard drop-in brand directory files because later versions
    # can auto-discover them even when the plan snapshot has null paths.
    try:
        directory = (
            _brand_asset_directory_for_profile(
                profile
            )
        )

        if directory.is_dir():
            for name in (
                "logo.png",
                "logo.webp",
                "logo.jpg",
                "logo.jpeg",
                "icon.png",
                "icon.webp",
                "icon.jpg",
                "icon.jpeg",
                "mid-promo.mp4",
                "mid_promo.mp4",
                "promo.mp4",
                "end-card.mp4",
                "end_card.mp4",
                "end-card.png",
                "end_card.png",
                "end-card.webp",
                "end_card.webp",
                "end-card.jpg",
                "end_card.jpg",
            ):
                path = (
                    directory
                    / name
                )

                if path.is_file():
                    key = str(
                        path.resolve()
                    ).lower()

                    if key not in seen:
                        seen.add(
                            key
                        )

                        files.append(
                            path
                        )
    except Exception:
        pass

    return sorted(
        files,
        key=lambda p: str(
            p
        ).lower(),
    )


def _file_cache_fingerprint(
    path,
    include_sha256=True,
):
    stat = path.stat()

    item = {
        "relative_path": (
            path
            .relative_to(
                WORKSPACE
            )
            .as_posix()
        ),
        "size_bytes": int(
            stat.st_size
        ),
        "mtime_ns": int(
            stat.st_mtime_ns
        ),
    }

    if include_sha256:
        item[
            "sha256"
        ] = (
            _sha256_file(
                path
            )
        )

    return item


def _render_cache_identity(
    req,
):
    plan_path, plan = (
        _read_json_workspace(
            req.replacement_plan_relative_path,
            "render_cache_identity",
        )
    )

    plan_bytes = (
        plan_path.read_bytes()
    )

    source_path = (
        _find_source_video_in_plan(
            plan
        )
    )

    source_fingerprint = None

    if source_path is not None:
        source_fingerprint = (
            _file_cache_fingerprint(
                source_path,
                include_sha256=True,
            )
        )

    assets = []

    for path in (
        _collect_profile_asset_files(
            plan
        )
    ):
        try:
            assets.append(
                _file_cache_fingerprint(
                    path,
                    include_sha256=True,
                )
            )
        except Exception:
            continue

    render_req = (
        _render_request_from_process_upload(
            req
        )
    )

    render_payload = (
        render_req.model_dump()
    )

    # Diagonal processing is already forced off by
    # _render_request_from_process_upload, preserving current PARKED policy.
    identity = {
        "cache_schema": (
            "branding-render-cache-v1"
        ),
        "plan": {
            "relative_path": (
                plan_path
                .relative_to(
                    WORKSPACE
                )
                .as_posix()
            ),
            "sha256": (
                _sha256_bytes(
                    plan_bytes
                )
            ),
        },
        "source": (
            source_fingerprint
        ),
        "brand_assets": (
            assets
        ),
        "render_request": (
            render_payload
        ),
        "renderer_code": (
            _renderer_code_fingerprint()
        ),
    }

    canonical = json.dumps(
        identity,
        ensure_ascii=False,
        sort_keys=True,
        separators=(
            ",",
            ":",
        ),
    ).encode(
        "utf-8"
    )

    process_key = (
        _sha256_bytes(
            canonical
        )
    )

    return (
        process_key,
        identity,
        render_req,
    )


def _render_cache_dir(
    process_key,
):
    return (
        WORKSPACE
        / "cache"
        / "branding_render"
        / str(
            process_key
        )
    )


def _render_cache_metadata_path(
    process_key,
):
    return (
        _render_cache_dir(
            process_key
        )
        / "cache.json"
    )


def _read_render_cache_entry(
    process_key,
):
    path = (
        _render_cache_metadata_path(
            process_key
        )
    )

    if not path.is_file():
        return None

    try:
        entry = json.loads(
            path.read_text(
                encoding="utf-8"
            )
        )
    except Exception:
        return None

    if not isinstance(
        entry,
        dict,
    ):
        return None

    if str(
        entry.get(
            "process_key"
        )
        or ""
    ) != str(
        process_key
    ):
        return None

    return entry


def _validate_render_cache_entry(
    entry,
    verify_md5=True,
):
    if not entry:
        return {
            "valid": False,
            "reason": (
                "CACHE_MISS"
            ),
        }

    rel = entry.get(
        "processed_video_relative_path"
    )

    path = (
        _cache_safe_workspace_file(
            rel
        )
    )

    if (
        path is None
        or path.suffix.lower()
        != ".mp4"
    ):
        return {
            "valid": False,
            "reason": (
                "CACHED_MP4_MISSING"
            ),
        }

    stat = path.stat()

    cached_size = (
        entry.get(
            "size_bytes"
        )
    )

    cached_mtime = (
        entry.get(
            "mtime_ns"
        )
    )

    cached_md5 = str(
        entry.get(
            "local_md5"
        )
        or ""
    ).lower()

    stat_unchanged = bool(
        cached_size is not None
        and cached_mtime is not None
        and int(
            cached_size
        )
        == int(
            stat.st_size
        )
        and int(
            cached_mtime
        )
        == int(
            stat.st_mtime_ns
        )
    )

    if (
        stat_unchanged
        and cached_md5
    ):
        return {
            "valid": True,
            "reason": (
                "CACHE_HIT_STAT_MATCH"
            ),
            "path": path,
            "local_md5": (
                cached_md5
            ),
            "md5_recomputed": False,
        }

    if not bool(
        verify_md5
    ):
        return {
            "valid": False,
            "reason": (
                "CACHE_FILE_CHANGED"
            ),
        }

    actual_md5 = (
        _local_file_md5(
            path
        )
    )

    if (
        cached_md5
        and actual_md5.lower()
        == cached_md5
    ):
        # Content is still identical even if metadata changed.
        return {
            "valid": True,
            "reason": (
                "CACHE_HIT_MD5_MATCH"
            ),
            "path": path,
            "local_md5": (
                actual_md5
            ),
            "md5_recomputed": True,
        }

    return {
        "valid": False,
        "reason": (
            "CACHE_MD5_MISMATCH"
        ),
        "actual_md5": (
            actual_md5
        ),
    }


def _write_render_cache_entry(
    process_key,
    identity,
    render_result,
    rendered_path,
    local_md5,
):
    cache_dir = (
        _render_cache_dir(
            process_key
        )
    )

    cache_dir.mkdir(
        parents=True,
        exist_ok=True,
    )

    stat = (
        rendered_path.stat()
    )

    entry = {
        "cache_schema": (
            "branding-render-cache-v1"
        ),
        "process_key": (
            process_key
        ),
        "created_at": (
            _app_now()
            .isoformat()
        ),
        "processed_video_relative_path": (
            rendered_path
            .relative_to(
                WORKSPACE
            )
            .as_posix()
        ),
        "render_report_relative_path": (
            render_result.get(
                "report_relative_path"
            )
        ),
        "renderer_version": (
            render_result.get(
                "version"
            )
        ),
        "local_md5": (
            local_md5
        ),
        "size_bytes": int(
            stat.st_size
        ),
        "mtime_ns": int(
            stat.st_mtime_ns
        ),
        "identity": (
            identity
        ),
    }

    path = (
        _render_cache_metadata_path(
            process_key
        )
    )

    path.write_text(
        json.dumps(
            entry,
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )

    return (
        path,
        entry,
    )


def _process_and_upload_sync(
    req: CreativeProcessAndUploadRequest
):
    started_at = (
        _app_now()
    )

    config = (
        _mintegral_config()
    )

    if bool(
        req.execute_upload
    ):
        _mintegral_require_credentials(
            config
        )

    (
        process_key,
        cache_identity,
        render_req,
    ) = (
        _render_cache_identity(
            req
        )
    )

    cache_status = (
        "BYPASSED"
    )

    cache_reason = None
    cache_entry = None
    cache_validation = None
    render_result = None
    rendered_path = None
    local_md5 = None
    renderer_version = None
    render_seconds = 0.0

    if (
        bool(
            req.use_render_cache
        )
        and not bool(
            req.force_render
        )
    ):
        cache_entry = (
            _read_render_cache_entry(
                process_key
            )
        )

        cache_validation = (
            _validate_render_cache_entry(
                cache_entry,
                verify_md5=(
                    req.verify_cached_file_md5
                ),
            )
        )

        if bool(
            cache_validation.get(
                "valid"
            )
        ):
            cache_status = "HIT"
            cache_reason = (
                cache_validation.get(
                    "reason"
                )
            )
            rendered_path = (
                cache_validation[
                    "path"
                ]
            )
            local_md5 = (
                cache_validation[
                    "local_md5"
                ]
            )
            renderer_version = (
                cache_entry.get(
                    "renderer_version"
                )
            )

            report_rel = (
                cache_entry.get(
                    "render_report_relative_path"
                )
            )

            if report_rel:
                try:
                    report_path = (
                        _safe_workspace_path(
                            report_rel
                        )
                    )

                    if report_path.is_file():
                        render_result = json.loads(
                            report_path.read_text(
                                encoding="utf-8"
                            )
                        )
                except Exception:
                    render_result = None

            if not isinstance(
                render_result,
                dict,
            ):
                render_result = {
                    "ok": True,
                    "version": (
                        renderer_version
                    ),
                    "report_relative_path": (
                        report_rel
                    ),
                    "cache_reused": True,
                }

    if rendered_path is None:
        cache_status = (
            "MISS"
            if bool(
                req.use_render_cache
            )
            and not bool(
                req.force_render
            )
            else (
                "FORCED_RENDER"
                if bool(
                    req.force_render
                )
                else "DISABLED"
            )
        )

        if (
            cache_validation
            and not cache_reason
        ):
            cache_reason = (
                cache_validation.get(
                    "reason"
                )
            )

        render_started = (
            _app_now()
        )

        render_result = (
            _replacement_render_sync(
                render_req
            )
        )

        render_finished = (
            _app_now()
        )

        render_seconds = (
            render_finished
            - render_started
        ).total_seconds()

        rendered_path = (
            _resolve_rendered_mp4(
                render_result
            )
        )

        local_md5 = (
            _local_file_md5(
                rendered_path
            )
        )

        renderer_version = (
            render_result.get(
                "version"
            )
        )

        if bool(
            req.use_render_cache
        ):
            (
                cache_meta_path,
                cache_entry,
            ) = (
                _write_render_cache_entry(
                    process_key,
                    cache_identity,
                    render_result,
                    rendered_path,
                    local_md5,
                )
            )
        else:
            cache_meta_path = None

    else:
        cache_meta_path = (
            _render_cache_metadata_path(
                process_key
            )
        )

    previous = None

    if bool(
        req.skip_if_uploaded_locally
    ):
        previous = (
            _find_uploaded_by_local_md5(
                local_md5
            )
        )

    upload_status = None
    upload_result = None
    upload_error = None

    if previous is not None:
        upload_status = (
            "SKIPPED_ALREADY_UPLOADED"
        )

        upload_result = {
            "creative_md5": (
                previous.get(
                    "creative_md5"
                )
            ),
            "creative_name": (
                previous.get(
                    "creative_name"
                )
            ),
            "previous_uploaded_at": (
                previous.get(
                    "uploaded_at"
                )
            ),
            "previous_job_id": (
                previous.get(
                    "job_id"
                )
            ),
        }

    elif not bool(
        req.execute_upload
    ):
        upload_status = (
            "UPLOAD_NOT_EXECUTED"
        )

    else:
        upload_filename = (
            _mintegral_safe_upload_filename(
                rendered_path,
                req.upload_material_name,
            )
        )

        try:
            uploaded = (
                _mintegral_upload_material_direct(
                    config,
                    rendered_path,
                    upload_filename,
                    req.upload_timeout_seconds,
                )
            )

            upload_status = str(
                uploaded.get(
                    "status"
                )
                or "UPLOADED"
            )

            upload_result = {
                "creative_md5": (
                    uploaded[
                        "creative_md5"
                    ]
                ),
                "creative_name": (
                    uploaded[
                        "creative_name"
                    ]
                ),
                "api_code": (
                    uploaded[
                        "api_code"
                    ]
                ),
                "api_message": (
                    uploaded[
                        "api_message"
                    ]
                ),
                "upload_filename": (
                    upload_filename
                ),
                "duplicate_message": (
                    uploaded.get(
                        "duplicate_message"
                    )
                ),
            }

        except HTTPException as exc:
            upload_status = (
                "UPLOAD_FAILED"
            )
            upload_error = (
                exc.detail
            )

            if bool(
                req.fail_job_if_upload_fails
            ):
                failed_at = (
                    _app_now()
                )

                failed_record = {
                    "job_id": (
                        started_at.strftime(
                            "%Y%m%d_%H%M%S"
                        )
                        + "-"
                        + rendered_path.stem[
                            :36
                        ]
                    ),
                    "uploaded": False,
                    "upload_status": (
                        upload_status
                    ),
                    "source_plan_relative_path": (
                        req.replacement_plan_relative_path
                    ),
                    "processed_video_relative_path": (
                        rendered_path
                        .relative_to(
                            WORKSPACE
                        )
                        .as_posix()
                    ),
                    "local_md5": (
                        local_md5
                    ),
                    "creative_md5": None,
                    "creative_name": None,
                    "uploaded_at": None,
                    "failed_at": (
                        failed_at.isoformat()
                    ),
                    "process_key": (
                        process_key
                    ),
                    "cache_status": (
                        cache_status
                    ),
                    "error": (
                        upload_error
                    ),
                }

                _append_upload_ledger(
                    failed_record
                )

                raise

    finished_at = (
        _app_now()
    )

    job_id = (
        started_at.strftime(
            "%Y%m%d_%H%M%S"
        )
        + "-"
        + rendered_path.stem[
            :36
        ]
    )

    success_statuses = (
        "UPLOADED",
        "REUSED_MINTEGRAL_EXISTING",
        "SKIPPED_ALREADY_UPLOADED",
    )

    uploaded_flag = bool(
        upload_status
        in success_statuses
        and upload_result
        and upload_result.get(
            "creative_md5"
        )
    )

    ledger_record = {
        "job_id": (
            job_id
        ),
        "uploaded": (
            uploaded_flag
        ),
        "upload_status": (
            upload_status
        ),
        "source_plan_relative_path": (
            req.replacement_plan_relative_path
        ),
        "processed_video_relative_path": (
            rendered_path
            .relative_to(
                WORKSPACE
            )
            .as_posix()
        ),
        "local_md5": (
            local_md5
        ),
        "creative_md5": (
            upload_result.get(
                "creative_md5"
            )
            if upload_result
            else None
        ),
        "creative_name": (
            upload_result.get(
                "creative_name"
            )
            if upload_result
            else None
        ),
        "uploaded_at": (
            finished_at.isoformat()
            if uploaded_flag
            else None
        ),
        "created_at": (
            finished_at.isoformat()
        ),
        "process_key": (
            process_key
        ),
        "cache_status": (
            cache_status
        ),
    }

    ledger_path = (
        _append_upload_ledger(
            ledger_record
        )
    )

    job_dir = (
        WORKSPACE
        / "output"
        / "process_and_upload"
        / started_at.strftime(
            "%Y-%m-%d_%H%M%S"
        )
        / rendered_path.stem
    )

    job_dir.mkdir(
        parents=True,
        exist_ok=True,
    )

    elapsed_seconds = (
        finished_at
        - started_at
    ).total_seconds()

    result = {
        "ok": bool(
            upload_status
            != "UPLOAD_FAILED"
        ),

        "version": "0.17.0",
        "workflow_version": "0.16.4",
        "renderer_version": (
            renderer_version
        ),

        "mode": (
            "creative_process_and_upload"
        ),

        "job_id": (
            job_id
        ),

        "process_key": (
            process_key
        ),

        "cache": {
            "enabled": bool(
                req.use_render_cache
            ),
            "force_render": bool(
                req.force_render
            ),
            "status": (
                cache_status
            ),
            "reason": (
                cache_reason
            ),
            "metadata_relative_path": (
                cache_meta_path
                .relative_to(
                    WORKSPACE
                )
                .as_posix()
                if cache_meta_path
                and cache_meta_path.exists()
                else None
            ),
            "render_skipped": (
                cache_status
                == "HIT"
            ),
        },

        "render": {
            "ok": True,
            "renderer_version": (
                renderer_version
            ),
            "processed_video_relative_path": (
                rendered_path
                .relative_to(
                    WORKSPACE
                )
                .as_posix()
            ),
            "report_relative_path": (
                render_result.get(
                    "report_relative_path"
                )
                if isinstance(
                    render_result,
                    dict,
                )
                else None
            ),
            "local_md5": (
                local_md5
            ),
            "render_seconds_this_job": round(
                float(
                    render_seconds
                ),
                3,
            ),
        },

        "mintegral": {
            "execute_upload": bool(
                req.execute_upload
            ),
            "status": (
                upload_status
            ),
            "creative_md5": (
                upload_result.get(
                    "creative_md5"
                )
                if upload_result
                else None
            ),
            "creative_name": (
                upload_result.get(
                    "creative_name"
                )
                if upload_result
                else None
            ),
            "reused_local_ledger": bool(
                previous is not None
            ),
            "reused_existing_mintegral_material": (
                upload_status
                == "REUSED_MINTEGRAL_EXISTING"
            ),
            "error": (
                upload_error
            ),
        },

        "ledger": {
            "relative_path": (
                ledger_path
                .relative_to(
                    WORKSPACE
                )
                .as_posix()
            ),
            "record": (
                ledger_record
            ),
        },

        "summary": {
            "render_cache_hit": (
                cache_status
                == "HIT"
            ),
            "render_completed_this_job": (
                cache_status
                != "HIT"
            ),
            "output_mp4_resolved": True,
            "material_available_in_mintegral": (
                uploaded_flag
            ),
            "new_external_upload_performed": (
                upload_status
                == "UPLOADED"
            ),
            "mintegral_existing_material_reused": (
                upload_status
                == "REUSED_MINTEGRAL_EXISTING"
            ),
            "duplicate_upload_skipped_by_local_ledger": (
                upload_status
                == "SKIPPED_ALREADY_UPLOADED"
            ),
            "offer_or_creative_set_modified": False,
        },

        "timing": {
            "started_at": (
                started_at.isoformat()
            ),
            "finished_at": (
                finished_at.isoformat()
            ),
            "elapsed_seconds": round(
                elapsed_seconds,
                3,
            ),
            "render_seconds_this_job": round(
                float(
                    render_seconds
                ),
                3,
            ),
        },

        "notes": {
            "cache": (
                "The cache key changes when the plan, source video, referenced "
                "brand assets, render request, or renderer code changes."
            ),
            "idempotency": (
                "Render-cache reuse and Mintegral-upload reuse are independent. "
                "An identical job can skip both expensive stages."
            ),
        },

        "output_relative_dir": (
            job_dir
            .relative_to(
                WORKSPACE
            )
            .as_posix()
        ),
    }

    report_path = (
        job_dir
        / (
            rendered_path.stem
            + ".process-upload-job.json"
        )
    )

    result[
        "report_relative_path"
    ] = (
        report_path
        .relative_to(
            WORKSPACE
        )
        .as_posix()
    )

    report_path.write_text(
        json.dumps(
            result,
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )

    return result




# ---------------------------------------------------------------------------
# v0.17.0 Persistent Batch Queue
#
# Submit many accepted replacement plans once:
#
#   POST /workflow/creative/batch-start
#       -> returns batch_job_id immediately
#
# Background worker processes items SEQUENTIALLY:
#   plan
#   -> render cache
#   -> processed MP4
#   -> upload ledger
#   -> Mintegral Materials
#
# Progress:
#   POST /workflow/creative/batch-status
#
# History:
#   POST /workflow/creative/batch-list
#
# One active batch per API process by design. This avoids parallel FFmpeg
# contention and keeps the early-production workflow predictable.
# ---------------------------------------------------------------------------

import threading
import traceback


class CreativeBatchStartRequest(BaseModel):
    # Explicit plans are safest. Duplicates are removed while preserving order.
    replacement_plan_relative_paths: list[str]

    # Any field accepted by CreativeProcessAndUploadRequest except
    # replacement_plan_relative_path can be supplied here once for all items.
    common_request: Optional[dict[str, Any]] = None

    # Continue processing the remaining items if one item fails.
    continue_on_error: bool = True

    # If this batch job file already contains a SUCCEEDED item with exactly the
    # same plan path (mainly useful for manual recovery), do not rerun it.
    skip_succeeded_items: bool = True


class CreativeBatchStatusRequest(BaseModel):
    batch_job_id: str


class CreativeBatchListRequest(BaseModel):
    limit: int = 20


_BATCH_RUNTIME_LOCK = threading.Lock()
_BATCH_ACTIVE_JOB_ID = None


def _batch_jobs_dir():
    return (
        WORKSPACE
        / "state"
        / "batch_jobs"
    )


def _batch_job_path(
    batch_job_id,
):
    safe = "".join(
        ch
        for ch in str(
            batch_job_id
        )
        if (
            ch.isalnum()
            or ch in (
                "-",
                "_",
            )
        )
    )

    if not safe:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": (
                    "batch_status"
                ),
                "error": (
                    "invalid_batch_job_id"
                ),
            },
        )

    return (
        _batch_jobs_dir()
        / (
            safe
            + ".json"
        )
    )


def _atomic_write_json(
    path,
    payload,
):
    path.parent.mkdir(
        parents=True,
        exist_ok=True,
    )

    # Never share a fixed ``.tmp`` pathname between worker threads.  The
    # concurrent operator pipeline used to let two writers truncate/replace
    # the same temporary file, leaving a syntactically invalid task JSON (and
    # consequently stale or incomplete UI results).  A unique file in the
    # destination directory preserves atomic replacement while eliminating
    # that race.
    temp_name = None
    try:
        with tempfile.NamedTemporaryFile(
            mode="w",
            encoding="utf-8",
            dir=str(path.parent),
            prefix=f".{path.name}.",
            suffix=".tmp",
            delete=False,
        ) as handle:
            temp_name = handle.name
            handle.write(json.dumps(payload, ensure_ascii=False, indent=2))
            handle.flush()
            os.fsync(handle.fileno())
        replace_error = None
        for attempt in range(6):
            try:
                os.replace(temp_name, path)
                replace_error = None
                break
            except PermissionError as exc:
                # Windows can briefly hold the destination while another
                # worker replaces it.  Retry the atomic operation instead of
                # surfacing a spurious task failure.
                replace_error = exc
                if attempt >= 5:
                    raise
                time.sleep(0.01 * (attempt + 1))
        temp_name = None
    finally:
        if temp_name:
            try:
                Path(temp_name).unlink(missing_ok=True)
            except Exception:
                pass


def _read_batch_job(
    batch_job_id,
):
    path = (
        _batch_job_path(
            batch_job_id
        )
    )

    if not path.is_file():
        raise HTTPException(
            status_code=404,
            detail={
                "stage": (
                    "batch_status"
                ),
                "error": (
                    "batch_job_not_found"
                ),
                "batch_job_id": (
                    batch_job_id
                ),
            },
        )

    try:
        payload = json.loads(
            path.read_text(
                encoding="utf-8"
            )
        )
    except Exception as exc:
        raise HTTPException(
            status_code=500,
            detail={
                "stage": (
                    "batch_status"
                ),
                "error": (
                    "batch_job_state_unreadable"
                ),
                "message": str(
                    exc
                )[:500],
            },
        )

    return (
        path,
        payload,
    )


def _batch_error_payload(
    exc,
):
    if isinstance(
        exc,
        HTTPException,
    ):
        return {
            "type": (
                "HTTPException"
            ),
            "status_code": (
                exc.status_code
            ),
            "detail": (
                exc.detail
            ),
        }

    return {
        "type": (
            exc.__class__.__name__
        ),
        "message": str(
            exc
        )[:2000],
        "traceback_tail": (
            traceback.format_exc()[
                -5000:
            ]
        ),
    }


def _batch_summary_from_items(
    items,
):
    counts = {
        "PENDING": 0,
        "RUNNING": 0,
        "SUCCEEDED": 0,
        "FAILED": 0,
        "SKIPPED": 0,
    }

    cache_hits = 0
    uploads_new = 0
    uploads_reused_mintegral = 0
    uploads_skipped_local = 0

    for item in (
        items
        or []
    ):
        status = str(
            item.get(
                "status"
            )
            or "PENDING"
        )

        counts[
            status
        ] = (
            counts.get(
                status,
                0,
            )
            + 1
        )

        if (
            item.get(
                "cache_status"
            )
            == "HIT"
        ):
            cache_hits += 1

        upload_status = (
            item.get(
                "upload_status"
            )
        )

        if upload_status == "UPLOADED":
            uploads_new += 1
        elif (
            upload_status
            == "REUSED_MINTEGRAL_EXISTING"
        ):
            uploads_reused_mintegral += 1
        elif (
            upload_status
            == "SKIPPED_ALREADY_UPLOADED"
        ):
            uploads_skipped_local += 1

    total = len(
        items
        or []
    )

    completed = (
        counts.get(
            "SUCCEEDED",
            0,
        )
        + counts.get(
            "FAILED",
            0,
        )
        + counts.get(
            "SKIPPED",
            0,
        )
    )

    return {
        "total": total,
        "completed": completed,
        "remaining": max(
            0,
            total - completed,
        ),
        "counts": counts,
        "cache_hit_count": (
            cache_hits
        ),
        "new_mintegral_upload_count": (
            uploads_new
        ),
        "reused_mintegral_existing_count": (
            uploads_reused_mintegral
        ),
        "skipped_local_upload_count": (
            uploads_skipped_local
        ),
        "progress_ratio": round(
            (
                completed / total
                if total
                else 1.0
            ),
            4,
        ),
    }


def _validate_batch_common_request(
    common_request,
):
    common = dict(
        common_request
        or {}
    )

    common.pop(
        "replacement_plan_relative_path",
        None,
    )

    allowed = set(
        CreativeProcessAndUploadRequest
        .model_fields
        .keys()
    )

    unknown = sorted(
        key
        for key in common.keys()
        if key not in allowed
    )

    if unknown:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": (
                    "batch_start"
                ),
                "error": (
                    "unknown_common_request_fields"
                ),
                "fields": (
                    unknown
                ),
            },
        )

    # Validate common fields once by constructing a temporary request with a
    # placeholder path. This catches bad enum/range/type values immediately.
    try:
        CreativeProcessAndUploadRequest(
            replacement_plan_relative_path=(
                "review/_batch_validation_placeholder.json"
            ),
            **common,
        )
    except Exception as exc:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": (
                    "batch_start"
                ),
                "error": (
                    "invalid_common_request"
                ),
                "message": str(
                    exc
                )[:2000],
            },
        )

    return common


def _normalize_batch_plan_paths(
    values,
):
    if not values:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": (
                    "batch_start"
                ),
                "error": (
                    "replacement_plan_relative_paths_required"
                ),
            },
        )

    result = []
    seen = set()

    for raw in values:
        rel = str(
            raw
            or ""
        ).strip()

        if not rel:
            continue

        key = rel.lower()

        if key in seen:
            continue

        path = (
            _safe_workspace_path(
                rel
            )
        )

        if not path.is_file():
            raise HTTPException(
                status_code=422,
                detail={
                    "stage": (
                        "batch_start"
                    ),
                    "error": (
                        "replacement_plan_not_found"
                    ),
                    "relative_path": rel,
                },
            )

        try:
            payload = json.loads(
                path.read_text(
                    encoding="utf-8"
                )
            )
        except Exception as exc:
            raise HTTPException(
                status_code=422,
                detail={
                    "stage": (
                        "batch_start"
                    ),
                    "error": (
                        "replacement_plan_invalid_json"
                    ),
                    "relative_path": rel,
                    "message": str(
                        exc
                    )[:500],
                },
            )

        # Avoid silently processing arbitrary JSON files.
        mode = str(
            payload.get(
                "mode"
            )
            or ""
        ).lower()

        if (
            "replacement" not in mode
            and "plan" not in mode
            and not rel.lower().endswith(
                ".replacement-plan.json"
            )
        ):
            raise HTTPException(
                status_code=422,
                detail={
                    "stage": (
                        "batch_start"
                    ),
                    "error": (
                        "file_does_not_look_like_replacement_plan"
                    ),
                    "relative_path": rel,
                    "mode": (
                        payload.get(
                            "mode"
                        )
                    ),
                },
            )

        seen.add(
            key
        )

        result.append(
            rel
        )

    if not result:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": (
                    "batch_start"
                ),
                "error": (
                    "no_valid_replacement_plans"
                ),
            },
        )

    return result


def _batch_item_from_result(
    item,
    result,
    started_at,
    finished_at,
):
    cache = (
        result.get(
            "cache"
        )
        or {}
    )

    mintegral = (
        result.get(
            "mintegral"
        )
        or {}
    )

    render = (
        result.get(
            "render"
        )
        or {}
    )

    item.update(
        {
            "status": "SUCCEEDED",
            "started_at": (
                started_at.isoformat()
            ),
            "finished_at": (
                finished_at.isoformat()
            ),
            "elapsed_seconds": round(
                (
                    finished_at
                    - started_at
                ).total_seconds(),
                3,
            ),
            "job_id": (
                result.get(
                    "job_id"
                )
            ),
            "process_key": (
                result.get(
                    "process_key"
                )
            ),
            "cache_status": (
                cache.get(
                    "status"
                )
            ),
            "render_skipped": bool(
                cache.get(
                    "render_skipped"
                )
            ),
            "processed_video_relative_path": (
                render.get(
                    "processed_video_relative_path"
                )
            ),
            "local_md5": (
                render.get(
                    "local_md5"
                )
            ),
            "upload_status": (
                mintegral.get(
                    "status"
                )
            ),
            "creative_md5": (
                mintegral.get(
                    "creative_md5"
                )
            ),
            "creative_name": (
                mintegral.get(
                    "creative_name"
                )
            ),
            "job_report_relative_path": (
                result.get(
                    "report_relative_path"
                )
            ),
            "error": None,
        }
    )


def _batch_worker(
    batch_job_id,
):
    global _BATCH_ACTIVE_JOB_ID

    path = (
        _batch_job_path(
            batch_job_id
        )
    )

    try:
        payload = json.loads(
            path.read_text(
                encoding="utf-8"
            )
        )

        payload[
            "status"
        ] = "RUNNING"

        payload[
            "started_at"
        ] = (
            _app_now()
            .isoformat()
        )

        payload[
            "worker_pid"
        ] = (
            os.getpid()
        )

        payload[
            "summary"
        ] = (
            _batch_summary_from_items(
                payload.get(
                    "items"
                )
            )
        )

        _atomic_write_json(
            path,
            payload,
        )

        common = (
            payload.get(
                "common_request"
            )
            or {}
        )

        continue_on_error = bool(
            payload.get(
                "continue_on_error",
                True,
            )
        )

        for index, item in enumerate(
            payload.get(
                "items"
            )
            or []
        ):
            if (
                item.get(
                    "status"
                )
                in (
                    "SUCCEEDED",
                    "SKIPPED",
                )
            ):
                continue

            item[
                "status"
            ] = "RUNNING"

            item[
                "started_at"
            ] = (
                _app_now()
                .isoformat()
            )

            payload[
                "current_index"
            ] = index

            payload[
                "current_plan_relative_path"
            ] = (
                item.get(
                    "replacement_plan_relative_path"
                )
            )

            payload[
                "summary"
            ] = (
                _batch_summary_from_items(
                    payload.get(
                        "items"
                    )
                )
            )

            _atomic_write_json(
                path,
                payload,
            )

            item_started = (
                _app_now()
            )

            try:
                item_req = (
                    CreativeProcessAndUploadRequest(
                        replacement_plan_relative_path=(
                            item[
                                "replacement_plan_relative_path"
                            ]
                        ),
                        **common,
                    )
                )

                result = (
                    _process_and_upload_sync(
                        item_req
                    )
                )

                item_finished = (
                    _app_now()
                )

                _batch_item_from_result(
                    item,
                    result,
                    item_started,
                    item_finished,
                )

            except Exception as exc:
                item_finished = (
                    _app_now()
                )

                item.update(
                    {
                        "status": (
                            "FAILED"
                        ),
                        "finished_at": (
                            item_finished
                            .isoformat()
                        ),
                        "elapsed_seconds": round(
                            (
                                item_finished
                                - item_started
                            ).total_seconds(),
                            3,
                        ),
                        "error": (
                            _batch_error_payload(
                                exc
                            )
                        ),
                    }
                )

                if not continue_on_error:
                    # Remaining pending items are intentionally skipped.
                    for remaining in (
                        payload.get(
                            "items"
                        )
                        or []
                    )[
                        index + 1:
                    ]:
                        if (
                            remaining.get(
                                "status"
                            )
                            == "PENDING"
                        ):
                            remaining[
                                "status"
                            ] = "SKIPPED"

                            remaining[
                                "skip_reason"
                            ] = (
                                "STOPPED_AFTER_PREVIOUS_FAILURE"
                            )

                    payload[
                        "status"
                    ] = (
                        "FAILED"
                    )

                    payload[
                        "summary"
                    ] = (
                        _batch_summary_from_items(
                            payload.get(
                                "items"
                            )
                        )
                    )

                    break

            payload[
                "summary"
            ] = (
                _batch_summary_from_items(
                    payload.get(
                        "items"
                    )
                )
            )

            _atomic_write_json(
                path,
                payload,
            )

        summary = (
            _batch_summary_from_items(
                payload.get(
                    "items"
                )
            )
        )

        if (
            payload.get(
                "status"
            )
            != "FAILED"
        ):
            if (
                summary[
                    "counts"
                ].get(
                    "FAILED",
                    0,
                )
                > 0
            ):
                payload[
                    "status"
                ] = (
                    "COMPLETED_WITH_ERRORS"
                )
            else:
                payload[
                    "status"
                ] = (
                    "COMPLETED"
                )

        payload[
            "finished_at"
        ] = (
            _app_now()
            .isoformat()
        )

        payload[
            "current_index"
        ] = None

        payload[
            "current_plan_relative_path"
        ] = None

        payload[
            "summary"
        ] = summary

        _atomic_write_json(
            path,
            payload,
        )

    except Exception as exc:
        # Batch-level failure should still leave readable state.
        try:
            payload = (
                json.loads(
                    path.read_text(
                        encoding="utf-8"
                    )
                )
                if path.is_file()
                else {}
            )
        except Exception:
            payload = {}

        payload.update(
            {
                "batch_job_id": (
                    batch_job_id
                ),
                "status": (
                    "FAILED"
                ),
                "finished_at": (
                    _app_now()
                    .isoformat()
                ),
                "batch_error": (
                    _batch_error_payload(
                        exc
                    )
                ),
            }
        )

        payload[
            "summary"
        ] = (
            _batch_summary_from_items(
                payload.get(
                    "items"
                )
            )
        )

        try:
            _atomic_write_json(
                path,
                payload,
            )
        except Exception:
            pass

    finally:
        with _BATCH_RUNTIME_LOCK:
            if (
                _BATCH_ACTIVE_JOB_ID
                == batch_job_id
            ):
                _BATCH_ACTIVE_JOB_ID = None


def _batch_start_sync(
    req: CreativeBatchStartRequest
):
    global _BATCH_ACTIVE_JOB_ID

    plans = (
        _normalize_batch_plan_paths(
            req.replacement_plan_relative_paths
        )
    )

    common = (
        _validate_batch_common_request(
            req.common_request
        )
    )

    with _BATCH_RUNTIME_LOCK:
        if _BATCH_ACTIVE_JOB_ID:
            active_path = (
                _batch_job_path(
                    _BATCH_ACTIVE_JOB_ID
                )
            )

            active_status = None

            if active_path.is_file():
                try:
                    active_payload = json.loads(
                        active_path.read_text(
                            encoding="utf-8"
                        )
                    )
                    active_status = (
                        active_payload.get(
                            "status"
                        )
                    )
                except Exception:
                    active_status = None

            if active_status in (
                "QUEUED",
                "RUNNING",
            ):
                raise HTTPException(
                    status_code=409,
                    detail={
                        "stage": (
                            "batch_start"
                        ),
                        "error": (
                            "another_batch_is_active"
                        ),
                        "active_batch_job_id": (
                            _BATCH_ACTIVE_JOB_ID
                        ),
                        "active_status": (
                            active_status
                        ),
                    },
                )

            _BATCH_ACTIVE_JOB_ID = None

        now = (
            _app_now()
        )

        batch_job_id = (
            "batch-"
            + now.strftime(
                "%Y%m%d-%H%M%S"
            )
            + "-"
            + str(
                os.getpid()
            )
        )

        path = (
            _batch_job_path(
                batch_job_id
            )
        )

        # Extremely defensive collision handling.
        suffix = 1
        base_job_id = (
            batch_job_id
        )

        while path.exists():
            batch_job_id = (
                base_job_id
                + "-"
                + str(
                    suffix
                )
            )
            suffix += 1
            path = (
                _batch_job_path(
                    batch_job_id
                )
            )

        items = [
            {
                "index": index,
                "replacement_plan_relative_path": (
                    rel
                ),
                "status": "PENDING",
                "started_at": None,
                "finished_at": None,
                "elapsed_seconds": None,
                "job_id": None,
                "process_key": None,
                "cache_status": None,
                "render_skipped": None,
                "processed_video_relative_path": None,
                "local_md5": None,
                "upload_status": None,
                "creative_md5": None,
                "creative_name": None,
                "job_report_relative_path": None,
                "error": None,
            }
            for index, rel in enumerate(
                plans
            )
        ]

        payload = {
            "ok": True,
            "version": "0.17.0",
            "mode": (
                "creative_batch_process_and_upload"
            ),
            "batch_job_id": (
                batch_job_id
            ),
            "status": "QUEUED",
            "created_at": (
                now.isoformat()
            ),
            "started_at": None,
            "finished_at": None,
            "worker_pid": None,
            "continue_on_error": bool(
                req.continue_on_error
            ),
            "skip_succeeded_items": bool(
                req.skip_succeeded_items
            ),
            "common_request": (
                common
            ),
            "current_index": None,
            "current_plan_relative_path": None,
            "items": items,
            "summary": (
                _batch_summary_from_items(
                    items
                )
            ),
            "state_relative_path": (
                path
                .relative_to(
                    WORKSPACE
                )
                .as_posix()
            ),
        }

        _atomic_write_json(
            path,
            payload,
        )

        _BATCH_ACTIVE_JOB_ID = (
            batch_job_id
        )

        thread = threading.Thread(
            target=_batch_worker,
            args=(
                batch_job_id,
            ),
            daemon=True,
            name=(
                "creative-loop-"
                + batch_job_id
            ),
        )

        thread.start()

    return {
        "ok": True,
        "version": "0.17.0",
        "mode": (
            "creative_batch_start"
        ),
        "batch_job_id": (
            batch_job_id
        ),
        "status": "QUEUED",
        "item_count": len(
            plans
        ),
        "state_relative_path": (
            path
            .relative_to(
                WORKSPACE
            )
            .as_posix()
        ),
        "message": (
            "Batch accepted. Use /workflow/creative/batch-status "
            "with batch_job_id to read progress."
        ),
    }


def _batch_status_sync(
    req: CreativeBatchStatusRequest
):
    path, payload = (
        _read_batch_job(
            req.batch_job_id
        )
    )

    payload[
        "summary"
    ] = (
        _batch_summary_from_items(
            payload.get(
                "items"
            )
        )
    )

    payload[
        "state_relative_path"
    ] = (
        path
        .relative_to(
            WORKSPACE
        )
        .as_posix()
    )

    return payload


def _batch_list_sync(
    req: CreativeBatchListRequest
):
    directory = (
        _batch_jobs_dir()
    )

    if not directory.is_dir():
        return {
            "ok": True,
            "version": "0.17.0",
            "mode": (
                "creative_batch_list"
            ),
            "count": 0,
            "items": [],
        }

    limit = min(
        200,
        max(
            1,
            int(
                req.limit
            ),
        ),
    )

    files = sorted(
        directory.glob(
            "batch-*.json"
        ),
        key=lambda p: (
            p.stat().st_mtime
            if p.exists()
            else 0.0
        ),
        reverse=True,
    )

    rows = []

    for path in files[
        :limit
    ]:
        try:
            payload = json.loads(
                path.read_text(
                    encoding="utf-8"
                )
            )
        except Exception:
            continue

        summary = (
            _batch_summary_from_items(
                payload.get(
                    "items"
                )
            )
        )

        rows.append(
            {
                "batch_job_id": (
                    payload.get(
                        "batch_job_id"
                    )
                ),
                "status": (
                    payload.get(
                        "status"
                    )
                ),
                "created_at": (
                    payload.get(
                        "created_at"
                    )
                ),
                "started_at": (
                    payload.get(
                        "started_at"
                    )
                ),
                "finished_at": (
                    payload.get(
                        "finished_at"
                    )
                ),
                "summary": summary,
                "state_relative_path": (
                    path
                    .relative_to(
                        WORKSPACE
                    )
                    .as_posix()
                ),
            }
        )

    return {
        "ok": True,
        "version": "0.17.0",
        "mode": (
            "creative_batch_list"
        ),
        "count": len(
            rows
        ),
        "items": rows,
    }




# ---------------------------------------------------------------------------
# v0.18.0 Operator Console
#
# User-facing workflow is deliberately reduced to:
#
#   1) Login to InsightTrackr if the persistent session is not already valid
#   2) Submit ONE of:
#        - Insight detail URL
#        - keyword + download count
#   3) Wait for automatic:
#        crawl -> dedupe/archive -> branding analysis -> semantic plan
#        -> production candidate render
#   4) Review rendered video(s)
#   5) Approve -> Mintegral Materials upload
#
# Swagger and the many low-level endpoints remain available only for advanced
# debugging. They are not the normal operator experience anymore.
# ---------------------------------------------------------------------------

import uuid


class OperatorTaskSubmitRequest(BaseModel):
    mode: str
    detail_url: Optional[str] = None
    # The console accepts one URL per line (and also comma/semicolon separated
    # values).  Keep the legacy singular field for older clients.
    detail_urls: Optional[list[str]] = Field(default=None, max_length=50)
    keyword: Optional[str] = None

    # Keyword-search business parameters visible to the operator.
    search_date_start: Optional[str] = None
    search_date_end: Optional[str] = None

    download_count: int = 10


def _operator_parse_detail_urls(raw_values):
    """Normalize console URL input into a de-duplicated URL list.

    Accept both the new JSON array and the legacy single string.  Splitting is
    intentionally done before validation so pasted multi-line input cannot be
    sent downstream as one malformed URL.
    """
    from urllib.parse import urlparse

    if raw_values is None:
        values = []
    elif isinstance(raw_values, str):
        values = [raw_values]
    elif isinstance(raw_values, (list, tuple, set)):
        values = list(raw_values)
    else:
        values = [str(raw_values)]

    normalized = []
    invalid = []
    seen = set()
    for value in values:
        chunks = re.split(r"[\s,;]+", str(value or "").strip())
        for chunk in chunks:
            candidate = chunk.strip().strip("<>\"'")
            if not candidate:
                continue
            parsed = urlparse(candidate)
            if parsed.scheme not in {"http", "https"} or not parsed.netloc:
                invalid.append(candidate)
                continue
            key = candidate.casefold()
            if key not in seen:
                seen.add(key)
                normalized.append(candidate)

    return normalized, invalid


class OperatorReviewRequest(BaseModel):
    task_id: str
    decision: str
    item_ids: list[str] = Field(default_factory=list)


class OperatorCancelRequest(BaseModel):
    task_id: str


class OperatorDeleteRequest(BaseModel):
    task_id: str


class _OperatorTaskCancelled(Exception):
    pass


class _OperatorTaskDiscarded(Exception):
    """A downloaded source is intentionally excluded before any edit starts."""

    def __init__(self, reason, detail=None):
        super().__init__(str(reason))
        self.reason = str(reason)
        self.detail = detail if isinstance(detail, dict) else {}


_OPERATOR_PROCESS_LOCK = threading.Lock()
_OPERATOR_REVIEW_LOCK = threading.Lock()

_OPERATOR_BOOT_ID = uuid.uuid4().hex
_OPERATOR_WORKER_REGISTRY_LOCK = threading.Lock()
_OPERATOR_WORKER_REGISTRY = {}
_OPERATOR_THREAD_CONTEXT = threading.local()


def _operator_worker_register(task_id, thread):
    with _OPERATOR_WORKER_REGISTRY_LOCK:
        _OPERATOR_WORKER_REGISTRY[str(task_id)] = thread


def _operator_worker_unregister(task_id):
    with _OPERATOR_WORKER_REGISTRY_LOCK:
        _OPERATOR_WORKER_REGISTRY.pop(str(task_id), None)


def _operator_worker_registered(task_id):
    with _OPERATOR_WORKER_REGISTRY_LOCK:
        return str(task_id) in _OPERATOR_WORKER_REGISTRY


def _operator_current_task_id():
    return getattr(_OPERATOR_THREAD_CONTEXT, "task_id", None)


def _operator_raise_if_cancelled():
    task_id = _operator_current_task_id()
    if task_id and _operator_cancel_requested(task_id):
        raise _OperatorTaskCancelled(
            "cooperative_cancel:" + str(task_id)
        )


def _operator_jobs_dir():
    return (
        WORKSPACE
        / "state"
        / "operator_jobs"
    )


def _operator_job_path(
    task_id,
):
    safe = "".join(
        ch
        for ch in str(
            task_id
        )
        if (
            ch.isalnum()
            or ch in (
                "-",
                "_",
            )
        )
    )

    if not safe:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "operator",
                "error": "invalid_task_id",
            },
        )

    return (
        _operator_jobs_dir()
        / (
            safe
            + ".json"
        )
    )


def _operator_read_job(
    task_id,
):
    path = (
        _operator_job_path(
            task_id
        )
    )

    if not path.is_file():
        raise HTTPException(
            status_code=404,
            detail={
                "stage": "operator",
                "error": "task_not_found",
                "task_id": task_id,
            },
        )

    try:
        payload = json.loads(
            path.read_text(
                encoding="utf-8"
            )
        )
    except Exception as exc:
        raise HTTPException(
            status_code=500,
            detail={
                "stage": "operator",
                "error": "task_state_unreadable",
                "message": str(exc)[:500],
            },
        )

    return (
        path,
        payload,
    )


def _operator_write_job(
    path,
    payload,
):
    payload[
        "updated_at"
    ] = (
        _app_now()
        .isoformat()
    )

    _atomic_write_json(
        path,
        payload,
    )


def _operator_cancel_marker_path(
    task_id,
):
    return (
        _operator_job_path(
            task_id
        )
        .with_suffix(
            ".cancel"
        )
    )


def _operator_cancel_requested(
    task_id,
):
    try:
        return (
            _operator_cancel_marker_path(
                task_id
            )
            .is_file()
        )
    except Exception:
        return False


def _operator_progress_counts(
    task,
):
    request = (
        task.get(
            "request"
        )
        or {}
    )

    requested = int(
        request.get(
            "download_count"
        )
        or (
            1
            if request.get(
                "mode"
            )
            == "url"
            else 0
        )
    )

    items = (
        task.get(
            "items"
        )
        or []
    )

    progress = (
        task.get(
            "progress"
        )
        or {}
    )

    downloaded = int(
        progress.get(
            "downloaded_count"
        )
        or (
            (
                task.get(
                    "crawl"
                )
                or {}
            )
            .get(
                "downloaded_video_count"
            )
            or 0
        )
    )

    processed = sum(
        1
        for item in items
        if item.get(
            "processed_video_relative_path"
        )
    )

    attempted = sum(
        1
        for item in items
        if str(
            item.get(
                "status"
            )
        )
        not in (
            "PENDING",
            "PROCESSING",
        )
    )

    awaiting = sum(
        1
        for item in items
        if item.get(
            "status"
        )
        == "AWAITING_REVIEW"
    )

    uploaded = sum(
        1
        for item in items
        if item.get(
            "status"
        )
        == "UPLOADED"
    )

    rejected = sum(
        1
        for item in items
        if item.get(
            "status"
        )
        == "REJECTED"
    )

    failed = sum(
        1
        for item in items
        if item.get(
            "status"
        )
        in (
            "FAILED",
            "UPLOAD_FAILED",
        )
    )

    discarded = sum(
        1
        for item in items
        if item.get("status") == "DISCARDED"
    )

    cancelled = sum(
        1
        for item in items
        if item.get(
            "status"
        )
        == "CANCELLED"
    )

    source_shortfall = max(
        0,
        int(
            requested
        )
        - int(
            downloaded
        ),
    )

    return {
        "requested_count": (
            requested
        ),
        # Kept for backward compatibility with saved task JSON.
        "downloaded_count": (
            downloaded
        ),
        "acquired_count": (
            downloaded
        ),
        "source_shortfall_count": (
            source_shortfall
        ),
        "processed_count": (
            processed
        ),
        "processed_attempted_count": (
            attempted
        ),
        "awaiting_review_count": (
            awaiting
        ),
        "uploaded_count": (
            uploaded
        ),
        "rejected_count": (
            rejected
        ),
        "failed_count": (
            failed
        ),
        "discarded_count": (
            discarded
        ),
        "cancelled_count": (
            cancelled
        ),
    }


def _operator_refresh_progress(
    task,
):
    counts = (
        _operator_progress_counts(
            task
        )
    )

    status = str(
        task.get(
            "status"
        )
        or ""
    )

    requested = max(
        1,
        int(
            counts[
                "requested_count"
            ]
            or 1
        ),
    )

    downloaded = int(
        counts[
            "downloaded_count"
        ]
    )

    items = (
        task.get(
            "items"
        )
        or []
    )

    total_items = max(
        1,
        len(
            items
        ),
    )

    attempted = int(
        counts[
            "processed_attempted_count"
        ]
    )

    if status == "QUEUED":
        percent = 3
    elif status == "CRAWLING":
        percent = (
            8
            + round(
                24
                * min(
                    1.0,
                    downloaded
                    / requested,
                )
            )
        )
    elif status == "PROCESSING":
        percent = (
            32
            + round(
                48
                * min(
                    1.0,
                    attempted
                    / total_items,
                )
            )
        )
    elif status == "AWAITING_REVIEW":
        percent = 82
    elif status == "UPLOADING":
        upload_done = (
            counts[
                "uploaded_count"
            ]
            + counts[
                "rejected_count"
            ]
            + counts[
                "failed_count"
            ]
        )

        percent = (
            84
            + round(
                15
                * min(
                    1.0,
                    upload_done
                    / total_items,
                )
            )
        )
    elif status == "CANCEL_REQUESTED":
        percent = int(
            (
                task.get(
                    "progress"
                )
                or {}
            )
            .get(
                "overall_percent"
            )
            or 10
        )
    elif status in (
        "COMPLETED",
        "COMPLETED_WITH_ERRORS",
        "FAILED",
        "CANCELLED",
    ):
        percent = 100
    else:
        percent = 5

    task[
        "progress"
    ] = {
        **(
            task.get(
                "progress"
            )
            or {}
        ),
        **counts,
        "overall_percent": int(
            max(
                0,
                min(
                    100,
                    percent,
                ),
            )
        ),
    }

    return task[
        "progress"
    ]


def _operator_finalize_cancelled(
    path,
    task,
    *,
    note=None,
):
    for item in (
        task.get(
            "items"
        )
        or []
    ):
        if item.get(
            "status"
        ) in (
            "PENDING",
            "PROCESSING",
            "AWAITING_REVIEW",
            "UPLOADING",
        ):
            item[
                "status"
            ] = "CANCELLED"

            item[
                "cancelled_at"
            ] = (
                _app_now()
                .isoformat()
            )

    task[
        "cancel_requested"
    ] = True

    task[
        "status"
    ] = "CANCELLED"

    task[
        "stage_label"
    ] = (
        "任务已取消"
    )

    task[
        "cancelled_at"
    ] = (
        _app_now()
        .isoformat()
    )

    task[
        "finished_at"
    ] = (
        task.get(
            "finished_at"
        )
        or task[
            "cancelled_at"
        ]
    )

    if note:
        task[
            "cancel_note"
        ] = str(
            note
        )

    counts = (
        _operator_progress_counts(
            task
        )
    )

    task[
        "summary"
    ] = {
        "video_count": len(
            task.get(
                "items"
            )
            or []
        ),
        "review_ready_count": (
            counts[
                "awaiting_review_count"
            ]
        ),
        "failed_count": (
            counts[
                "failed_count"
            ]
        ),
        "uploaded_count": (
            counts[
                "uploaded_count"
            ]
        ),
        "rejected_count": (
            counts[
                "rejected_count"
            ]
        ),
        "cancelled_count": (
            counts[
                "cancelled_count"
            ]
        ),
    }

    _operator_refresh_progress(
        task
    )

    _operator_write_job(
        path,
        task,
    )

    return task


def _operator_internal_base():
    return (
        os.getenv(
            "OPERATOR_INTERNAL_API_BASE",
            "http://127.0.0.1:8000",
        )
        .strip()
        .rstrip("/")
    )


def _operator_internal_request(
    method,
    path,
    *,
    json_payload=None,
    timeout=120.0,
):
    requests = (
        _mintegral_requests()
    )

    response = requests.request(
        str(
            method
        ).upper(),
        (
            _operator_internal_base()
            + str(
                path
            )
        ),
        json=(
            json_payload
            if json_payload is not None
            else None
        ),
        timeout=float(
            timeout
        ),
    )

    try:
        payload = response.json()
    except Exception:
        raise HTTPException(
            status_code=502,
            detail={
                "stage": "operator_internal_api",
                "error": "non_json_response",
                "path": path,
                "http_status": int(
                    response.status_code
                ),
                "body": (
                    response.text[:1200]
                    if response.text
                    else ""
                ),
            },
        )

    if response.status_code >= 400:
        raise HTTPException(
            status_code=response.status_code,
            detail={
                "stage": "operator_internal_api",
                "error": "internal_api_failed",
                "path": path,
                "http_status": int(
                    response.status_code
                ),
                "response": payload,
            },
        )

    return payload


def _operator_openapi():
    return (
        _operator_internal_request(
            "GET",
            "/openapi.json",
            timeout=30.0,
        )
    )


def _operator_resolve_schema(
    openapi,
    schema,
):
    if not isinstance(
        schema,
        dict,
    ):
        return {}

    ref = schema.get(
        "$ref"
    )

    if not ref:
        return schema

    prefix = "#/components/schemas/"

    if not str(
        ref
    ).startswith(
        prefix
    ):
        return schema

    name = str(
        ref
    )[
        len(prefix):
    ]

    return (
        (
            openapi.get(
                "components"
            )
            or {}
        )
        .get(
            "schemas",
            {}
        )
        .get(
            name,
            {}
        )
    )


def _operator_request_schema(
    openapi,
    path,
):
    operation = (
        (
            openapi.get(
                "paths"
            )
            or {}
        )
        .get(
            path,
            {}
        )
        .get(
            "post",
            {}
        )
    )

    content = (
        (
            operation.get(
                "requestBody"
            )
            or {}
        )
        .get(
            "content",
            {}
        )
    )

    schema = (
        (
            content.get(
                "application/json"
            )
            or {}
        )
        .get(
            "schema",
            {}
        )
    )

    return (
        _operator_resolve_schema(
            openapi,
            schema,
        )
    )


def _operator_find_crawl_path(
    openapi,
    mode,
):
    paths = list(
        (
            openapi.get(
                "paths"
            )
            or {}
        ).keys()
    )

    if mode == "search":
        preferred = [
            "/crawl/search",
            "/crawl/keyword",
        ]

        for path in preferred:
            if path in paths:
                return path

        for path in paths:
            lower = (
                path.lower()
            )

            if (
                "/crawl/" in lower
                and (
                    "search" in lower
                    or "keyword" in lower
                )
            ):
                return path

        raise HTTPException(
            status_code=500,
            detail={
                "stage": "operator_crawl",
                "error": "keyword_crawl_endpoint_not_found",
            },
        )

    preferred = [
        "/crawl/url",
        "/crawl/items",
    ]

    for path in preferred:
        if path in paths:
            return path

    raise HTTPException(
        status_code=500,
        detail={
            "stage": "operator_crawl",
            "error": "url_crawl_endpoint_not_found",
        },
    )



def _operator_url_action_schema_value(prop, action):
    prop = prop if isinstance(prop, dict) else {}
    action = str(action or "").strip().casefold()

    if action in {"metadata", "metadata_only", "inspect"}:
        preferred = ("metadata_only", "metadata", "inspect", "detail")
        canonical = "metadata_only"
    elif action in {"download", "acquire", "media"}:
        preferred = ("download", "acquire", "media")
        canonical = "download"
    else:
        return None

    enum_values = prop.get("enum") or []

    if enum_values:
        normalized = {
            str(value).strip().casefold(): value
            for value in enum_values
        }

        for candidate in preferred:
            if candidate in normalized:
                return normalized[candidate]

        return prop.get("default")

    return canonical


def _operator_fill_schema_payload(
    openapi,
    path,
    *,
    mode,
    detail_url=None,
    detail_urls=None,
    keyword=None,
    search_date_start=None,
    search_date_end=None,
    download_count=10,
    url_action=None,
):
    from datetime import timedelta

    schema = (
        _operator_request_schema(
            openapi,
            path,
        )
    )

    props = (
        schema.get(
            "properties"
        )
        or {}
    )

    required = set(
        schema.get(
            "required"
        )
        or []
    )

    payload = {}

    normalized_detail_urls, _ = _operator_parse_detail_urls(
        detail_urls if detail_urls is not None else detail_url
    )
    if not normalized_detail_urls and detail_url:
        normalized_detail_urls = [str(detail_url).strip()]
    first_detail_url = (
        normalized_detail_urls[0]
        if normalized_detail_urls
        else str(detail_url or "").strip()
    )

    today = (
        _app_now()
        .date()
    )

    start_date = (
        today
        - timedelta(
            days=30
        )
    )

    explicit_start = str(
        search_date_start
        or ""
    ).strip()

    explicit_end = str(
        search_date_end
        or ""
    ).strip()

    keyword_aliases = {
        "keyword",
        "search_keyword",
        "search_term",
        "query",
        "q",
    }

    count_aliases = {
        "top_n",
        "download_count",
        "count",
        "limit",
        "max_items",
        "max_results",
    }

    url_aliases = {
        "url",
        "detail_url",
        "creative_url",
    }

    urls_aliases = {
        "urls",
        "detail_urls",
        "creative_urls",
    }

    start_aliases = {
        "date_start",
        "start_date",
        "search_date_start",
        "from_date",
    }

    end_aliases = {
        "date_end",
        "end_date",
        "search_date_end",
        "to_date",
    }

    for name, prop in props.items():
        lower = str(
            name
        ).lower()

        if (
            mode == "search"
            and lower in keyword_aliases
        ):
            payload[
                name
            ] = str(
                keyword
                or ""
            )
            continue

        if lower in count_aliases:
            payload[
                name
            ] = int(
                download_count
            )
            continue

        if (
            mode == "url"
            and lower in urls_aliases
        ):
            payload[
                name
            ] = [
                str(url)
                for url in normalized_detail_urls
            ]
            continue

        if (
            mode == "url"
            and lower in url_aliases
        ):
            payload[
                name
            ] = first_detail_url
            continue

        if (
            mode == "url"
            and lower in (
                "mode",
                "action",
                "operation",
                "crawl_mode",
            )
            and url_action
        ):
            selected_url_action = (
                _operator_url_action_schema_value(
                    prop,
                    url_action,
                )
            )

            if selected_url_action not in (
                None,
                "",
            ):
                payload[
                    name
                ] = selected_url_action
                continue

        if lower in (
            "video_only",
            "only_video",
            "download_video_only",
        ):
            payload[
                name
            ] = True
            continue

        if lower in (
            "auto_download",
            "download",
            "download_media",
        ):
            # Keyword mode must NOT download inside /crawl/search.
            # We first obtain candidate metadata, enforce Imp.Estimate DESC,
            # then pass the ranked Top N through /crawl/items.
            payload[
                name
            ] = (
                False
                if mode == "search"
                else True
            )
            continue

        if lower == "download_cover":
            payload[
                name
            ] = False
            continue

        if lower == "auto_detect_language":
            payload[
                name
            ] = True
            continue

        if lower == "wait_ms":
            payload[
                name
            ] = 5000
            continue

        if lower in start_aliases:
            if explicit_start:
                payload[
                    name
                ] = explicit_start
            elif (
                name in required
                or prop.get(
                    "default"
                )
                is None
            ):
                payload[
                    name
                ] = (
                    start_date
                    .isoformat()
                )
            continue

        if lower in end_aliases:
            if explicit_end:
                payload[
                    name
                ] = explicit_end
            elif (
                name in required
                or prop.get(
                    "default"
                )
                is None
            ):
                payload[
                    name
                ] = (
                    today
                    .isoformat()
                )
            continue

        if (
            mode == "search"
            and lower in (
                "field",
                "sort_field",
                "sortfield",
                "field_id",
                "fieldid",
            )
        ):
            # Insight native exposure sort field. This is the contract that
            # /crawl/search previously verified in production.
            payload[
                name
            ] = "15"
            continue

        if (
            mode == "search"
            and lower in (
                "rule",
                "sort_rule",
                "sortrule",
            )
        ):
            payload[
                name
            ] = "desc"
            continue

        if (
            mode == "search"
            and lower in (
                "sort",
                "sort_by",
                "sortby",
                "order_by",
                "orderby",
                "ranking",
                "rank_by",
            )
        ):
            enum_values = (
                prop.get(
                    "enum"
                )
                or []
            )

            preferred = [
                "imp_estimate_desc",
                "imp_estimate",
                "imp_desc",
                "impression_desc",
                "highest_imp",
                "imp",
            ]

            selected = None

            if enum_values:
                normalized_enum = {
                    str(
                        value
                    ).casefold(): value
                    for value in enum_values
                }

                for candidate in preferred:
                    if (
                        candidate.casefold()
                        in normalized_enum
                    ):
                        selected = (
                            normalized_enum[
                                candidate.casefold()
                            ]
                        )
                        break

            if selected is None:
                selected = (
                    "imp_estimate_desc"
                )

            payload[
                name
            ] = selected
            continue

        if (
            mode == "search"
            and lower in (
                "sort_order",
                "order",
                "direction",
                "sort_direction",
            )
        ):
            enum_values = (
                prop.get(
                    "enum"
                )
                or []
            )

            selected = "desc"

            if enum_values:
                normalized_enum = {
                    str(
                        value
                    ).casefold(): value
                    for value in enum_values
                }

                for candidate in (
                    "desc",
                    "descending",
                    "-1",
                ):
                    if (
                        candidate.casefold()
                        in normalized_enum
                    ):
                        selected = (
                            normalized_enum[
                                candidate.casefold()
                            ]
                        )
                        break

            payload[
                name
            ] = selected
            continue

        if lower in (
            "material_type",
            "ad_type",
        ):
            if name in required:
                payload[
                    name
                ] = "video"
            continue

        if lower in (
            "page",
            "page_no",
            "page_number",
        ):
            if name in required:
                payload[
                    name
                ] = 1
            continue

        if lower in (
            "page_size",
            "page_limit",
            "per_page",
        ):
            if name in required:
                payload[
                    name
                ] = max(
                    20,
                    int(
                        download_count
                    ),
                )
            continue

        if name in required:
            if "default" in prop:
                payload[
                    name
                ] = prop[
                    "default"
                ]
                continue

            lower_type = (
                prop.get(
                    "type"
                )
            )

            if lower_type == "boolean":
                payload[
                    name
                ] = False
                continue

            if lower_type == "array":
                payload[
                    name
                ] = []
                continue

    # Historical crawler contract fallback. Extra fields are normally ignored
    # by Pydantic, while these make older crawler builds usable.
    if mode == "url":
        if url_action:
            for action_key in (
                "mode",
                "action",
                "operation",
                "crawl_mode",
            ):
                if (
                    action_key in props
                    and action_key not in payload
                ):
                    selected_url_action = (
                        _operator_url_action_schema_value(
                            props.get(
                                action_key
                            )
                            or {},
                            url_action,
                        )
                    )

                    if selected_url_action not in (
                        None,
                        "",
                    ):
                        payload[
                            action_key
                        ] = selected_url_action

        payload.setdefault(
            "urls",
            [
                str(
                    detail_url
                )
            ],
        )
    else:
        payload.setdefault(
            "keyword",
            str(
                keyword
                or ""
            ),
        )

        payload.setdefault(
            "top_n",
            int(
                download_count
            ),
        )

        payload.setdefault(
            "sort",
            "imp_estimate_desc",
        )

        payload.setdefault(
            "sort_order",
            "desc",
        )

        # Native Insight search contract. If the current /crawl/search request
        # model exposes these fields they are consumed; older models normally
        # ignore extra fields.
        payload.setdefault(
            "field",
            "15",
        )

        payload.setdefault(
            "rule",
            "desc",
        )

        if explicit_start:
            payload.setdefault(
                "date_start",
                explicit_start,
            )

        if explicit_end:
            payload.setdefault(
                "date_end",
                explicit_end,
            )

    return payload


def _operator_workspace_relative(
    value,
):
    if not value:
        return None

    raw = str(
        value
    ).strip()

    if not raw:
        return None

    if raw.startswith(
        "http://"
    ) or raw.startswith(
        "https://"
    ):
        return None

    workspace_text = str(
        WORKSPACE
    ).replace(
        "\\",
        "/",
    )

    normalized = raw.replace(
        "\\",
        "/",
    )

    if normalized.startswith(
        workspace_text
        + "/"
    ):
        normalized = normalized[
            len(
                workspace_text
            )
            + 1:
        ]

    try:
        path = (
            _safe_workspace_path(
                normalized
            )
        )
    except Exception:
        return None

    if (
        path.is_file()
        and path.suffix.lower()
        == ".mp4"
    ):
        return (
            path
            .relative_to(
                WORKSPACE
            )
            .as_posix()
        )

    return None


def _operator_source_sidecar_payload(
    video_path,
):
    candidates = [
        video_path.with_suffix(
            ".metadata.json"
        ),
        Path(
            str(
                video_path
            )
            + ".metadata.json"
        ),
        video_path.parent
        / (
            video_path.name
            + ".metadata.json"
        ),
        video_path.parent
        / (
            video_path.stem
            + ".metadata.json"
        ),
    ]

    for candidate in candidates:
        if not candidate.is_file():
            continue

        try:
            payload = json.loads(
                candidate.read_text(
                    encoding="utf-8-sig"
                )
            )

            if isinstance(
                payload,
                dict,
            ):
                return (
                    payload,
                    candidate,
                )
        except Exception:
            continue

    return (
        None,
        None,
    )


def _operator_nested_first(
    payload,
    keys,
):
    wanted = {
        str(
            key
        ).casefold()
        for key in keys
    }

    queue = [
        payload
    ]

    while queue:
        value = (
            queue.pop(
                0
            )
        )

        if isinstance(
            value,
            dict,
        ):
            for key, nested in (
                value.items()
            ):
                if (
                    str(
                        key
                    ).casefold()
                    in wanted
                ):
                    if nested not in (
                        None,
                        "",
                        [],
                        {},
                    ):
                        return nested

            queue.extend(
                value.values()
            )

        elif isinstance(
            value,
            list,
        ):
            queue.extend(
                value
            )

    return None


def _operator_clean_metadata_text(
    value,
):
    text = str(
        value
        or ""
    ).strip()

    if text.casefold() in {
        "",
        "none",
        "null",
        "unknown",
        "unknown_language",
        "unknown_product",
        "n/a",
        "na",
    }:
        return None

    return text


def _operator_source_video_context(
    relative_path,
    hinted_product=None,
    hinted_language=None,
):
    path = (
        _safe_workspace_path(
            relative_path
        )
    )

    payload, sidecar = (
        _operator_source_sidecar_payload(
            path
        )
    )

    sidecar_product = None
    sidecar_language = None
    product_source = None
    language_source = None
    package_name = None
    app_title = None
    countries = None
    source_sha256 = None
    source_status = None
    language_code = None
    icon_url = None
    brand_id = None
    brand_profile_relative_path = None
    brand_identity_source = None
    brand_identity_snapshot_present = False

    if payload:
        sidecar_product = (
            _operator_clean_metadata_text(
                _operator_nested_first(
                    payload,
                    [
                        "product_name",
                        "product",
                    ],
                )
            )
        )

        sidecar_language = (
            _operator_clean_metadata_text(
                _operator_nested_first(
                    payload,
                    [
                        "language",
                        "detected_language",
                    ],
                )
            )
        )

        product_source = (
            _operator_clean_metadata_text(
                _operator_nested_first(
                    payload,
                    [
                        "product_name_source",
                        "product_source",
                    ],
                )
            )
        )

        language_source = (
            _operator_clean_metadata_text(
                _operator_nested_first(
                    payload,
                    [
                        "language_source",
                        "detection_source",
                    ],
                )
            )
        )

        language_code = (
            _operator_clean_metadata_text(
                _operator_nested_first(
                    payload,
                    [
                        "language_code",
                        "detected_language_code",
                    ],
                )
            )
        )

        package_name = (
            _operator_clean_metadata_text(
                _operator_nested_first(
                    payload,
                    [
                        "package_name",
                        "package",
                        "bundle_id",
                    ],
                )
            )
        )

        app_title = (
            _operator_clean_metadata_text(
                _operator_nested_first(
                    payload,
                    [
                        "app_title",
                        "app_name",
                        "application_name",
                    ],
                )
            )
        )

        countries = (
            _operator_nested_first(
                payload,
                [
                    "countries",
                    "country_list",
                    "country_codes",
                ],
            )
        )

        source_sha256 = (
            _operator_clean_metadata_text(
                _operator_nested_first(
                    payload,
                    [
                        "sha256",
                        "source_sha256",
                    ],
                )
            )
        )

        source_status = (
            _operator_clean_metadata_text(
                _operator_nested_first(
                    payload,
                    [
                        "status",
                        "archive_status",
                    ],
                )
            )
        )

        icon_url = _operator_clean_metadata_text(
            _operator_nested_first(payload, ["icon_url", "app_icon_url", "logo_url"])
        )
        brand_id = _operator_clean_metadata_text(
            _operator_nested_first(payload, ["brand_id"])
        )
        # Acquisition writes a material-bound identity snapshot beside every
        # source video.  Prefer that path so processing is independent of the
        # machine's global brand registry.  Keep both historical sidecar
        # locations as compatibility fallbacks for already-downloaded media.
        snapshot = payload.get("brand_identity_snapshot")
        if isinstance(snapshot, dict):
            snapshot_profile = _operator_clean_metadata_text(
                snapshot.get("profile_relative_path")
            )
            if snapshot_profile:
                brand_profile_relative_path = snapshot_profile
                brand_identity_source = "material_bound_snapshot"
                brand_identity_snapshot_present = True
        if not brand_profile_relative_path:
            brand_profile_relative_path = _operator_clean_metadata_text(
                _operator_nested_first(payload, ["brand_profile"])
            )
            if brand_profile_relative_path:
                brand_identity_source = "sidecar_brand_profile"
        if not brand_profile_relative_path:
            diagnostic = payload.get("detail_identity_diagnostic")
            if isinstance(diagnostic, dict):
                brand_profile_relative_path = _operator_clean_metadata_text(
                    diagnostic.get("brand_profile")
                )
                if brand_profile_relative_path:
                    brand_identity_source = "detail_identity_diagnostic"

    path_product = None
    path_language = None
    run_folder = None
    archive_ready = False

    try:
        parts = list(
            path.relative_to(
                WORKSPACE
            ).parts
        )

        # Formal crawler archive:
        # raw/<run-minute>/<competitor-product>/<language>/<original-file>
        if (
            len(
                parts
            )
            >= 5
            and str(
                parts[
                    0
                ]
            ).casefold()
            == "raw"
            and str(
                parts[
                    1
                ]
            ).casefold()
            != "_staging"
        ):
            run_folder = str(
                parts[
                    1
                ]
            )

            path_product = (
                _operator_clean_metadata_text(
                    parts[
                        2
                    ]
                )
            )

            path_language = (
                _operator_clean_metadata_text(
                    parts[
                        3
                    ]
                )
            )

            archive_ready = bool(
                path_product
                and path_language
            )

    except Exception:
        pass

    product_name = (
        sidecar_product
        or _operator_clean_metadata_text(
            hinted_product
        )
        or path_product
    )

    language = (
        sidecar_language
        or _operator_clean_metadata_text(
            hinted_language
        )
        or path_language
    )

    # A file is production-ready for editing only when it has actually reached
    # the formal raw/<run>/<product>/<language>/ archive.  Files under review/
    # or raw/_staging must never silently enter the editing pipeline.
    archive_ready = bool(
        archive_ready
        and product_name
        and language
    )

    return {
        "relative_path": (
            path.relative_to(
                WORKSPACE
            ).as_posix()
        ),
        "archive_ready": (
            archive_ready
        ),
        "run_folder": (
            run_folder
        ),
        "product_name": (
            product_name
        ),
        "product_name_source": (
            product_source
            or (
                "archive_path"
                if path_product
                else None
            )
        ),
        "language": (
            language
        ),
        "language_code": (
            language_code
        ),
        "language_source": (
            language_source
            or (
                "archive_path"
                if path_language
                else None
            )
        ),
        "package_name": (
            package_name
        ),
        "app_title": (
            app_title
        ),
        "countries": (
            countries
            if isinstance(
                countries,
                list,
            )
            else (
                [
                    countries
                ]
                if countries
                else []
            )
        ),
        "sha256": (
            source_sha256
        ),
        "source_status": (
            source_status
        ),
        "icon_url": icon_url,
        "brand_id": brand_id,
        "brand_profile_relative_path": brand_profile_relative_path,
        "brand_identity_source": brand_identity_source,
        "brand_identity_snapshot_present": brand_identity_snapshot_present,
        "metadata_sidecar": (
            sidecar.relative_to(
                WORKSPACE
            ).as_posix()
            if sidecar
            else None
        ),
    }


def _operator_relocate_stale_source(
    relative_path,
    *,
    sha256_hint=None,
    product_hint=None,
    language_hint=None,
):
    """
    Resolve a historical stale workspace path after prior review->raw moves.

    Formal crawler filenames are preserved, so the original basename is a
    strong first key.  SHA256 is used when available to disambiguate.

    Search priority:
      1. raw/**/<original-filename>
      2. review/**/<original-filename>

    raw/_staging is never accepted as a production-ready replacement.
    """
    raw_relative = str(
        relative_path
        or ""
    ).strip().replace(
        chr(
            92
        ),
        "/",
    )

    if not raw_relative:
        return None

    original = (
        _safe_workspace_path(
            raw_relative,
            must_exist=False,
        )
    )

    if original.is_file():
        return {
            "resolved": True,
            "relative_path": (
                original.relative_to(
                    WORKSPACE
                ).as_posix()
            ),
            "source": "original_path",
            "matched_by": "path",
            "candidate_count": 1,
        }

    basename = (
        original.name
    )

    if not basename:
        return None

    candidates = []

    for root_name in (
        "raw",
        "review",
    ):
        root = (
            WORKSPACE
            / root_name
        )

        if not root.is_dir():
            continue

        try:
            found = list(
                root.rglob(
                    basename
                )
            )
        except Exception:
            found = []

        for candidate in found:
            if not candidate.is_file():
                continue

            try:
                rel = (
                    candidate.relative_to(
                        WORKSPACE
                    )
                    .as_posix()
                )
            except Exception:
                continue

            parts = list(
                candidate.relative_to(
                    WORKSPACE
                ).parts
            )

            if (
                parts
                and str(
                    parts[
                        0
                    ]
                ).casefold()
                == "raw"
                and len(
                    parts
                )
                >= 2
                and str(
                    parts[
                        1
                    ]
                ).casefold()
                == "_staging"
            ):
                continue

            candidates.append(
                candidate
            )

    # De-duplicate identical filesystem paths.
    unique = []
    seen = set()

    for candidate in candidates:
        key = str(
            candidate.resolve()
        ).casefold()

        if key in seen:
            continue

        seen.add(
            key
        )
        unique.append(
            candidate
        )

    candidates = unique

    if not candidates:
        return None

    expected_sha = str(
        sha256_hint
        or ""
    ).strip().casefold()

    if expected_sha:
        sha_matches = []

        for candidate in candidates:
            try:
                actual = (
                    _sha256_file(
                        candidate
                    )
                    .casefold()
                )
            except Exception:
                continue

            if actual == expected_sha:
                sha_matches.append(
                    candidate
                )

        if sha_matches:
            candidates = (
                sha_matches
            )

    product_norm = (
        str(
            product_hint
            or ""
        )
        .strip()
        .casefold()
    )

    language_norm = (
        str(
            language_hint
            or ""
        )
        .strip()
        .casefold()
    )

    def score(
        candidate,
    ):
        try:
            parts = [
                str(
                    value
                ).casefold()
                for value in (
                    candidate
                    .relative_to(
                        WORKSPACE
                    )
                    .parts
                )
            ]
        except Exception:
            parts = []

        value = 0

        if (
            parts
            and parts[
                0
            ]
            == "raw"
        ):
            value += 100

        if (
            product_norm
            and product_norm in parts
        ):
            value += 20

        if (
            language_norm
            and language_norm in parts
        ):
            value += 10

        try:
            mtime = float(
                candidate.stat().st_mtime
            )
        except Exception:
            mtime = 0.0

        return (
            value,
            mtime,
        )

    candidates.sort(
        key=score,
        reverse=True,
    )

    selected = (
        candidates[
            0
        ]
    )

    # If multiple candidates remain and no SHA was supplied, accept only when
    # the best candidate clearly wins by archive/product/language scoring.
    if (
        len(
            candidates
        )
        > 1
        and not expected_sha
    ):
        best_score = score(
            candidates[
                0
            ]
        )[
            0
        ]

        second_score = score(
            candidates[
                1
            ]
        )[
            0
        ]

        if best_score == second_score:
            # Same hashed source filename appearing more than once is usually
            # the same source copied across historical runs. Verify content
            # equality before choosing the newest one.
            try:
                best_sha = (
                    _sha256_file(
                        candidates[
                            0
                        ]
                    )
                )

                second_sha = (
                    _sha256_file(
                        candidates[
                            1
                        ]
                    )
                )
            except Exception:
                best_sha = None
                second_sha = None

            if (
                not best_sha
                or best_sha
                != second_sha
            ):
                return {
                    "resolved": False,
                    "error": (
                        "stale_source_relocation_ambiguous"
                    ),
                    "requested_relative_path": (
                        raw_relative
                    ),
                    "basename": (
                        basename
                    ),
                    "candidate_count": len(
                        candidates
                    ),
                    "candidates": [
                        candidate
                        .relative_to(
                            WORKSPACE
                        )
                        .as_posix()
                        for candidate in (
                            candidates[
                                :10
                            ]
                        )
                    ],
                }

    resolved_rel = (
        selected
        .relative_to(
            WORKSPACE
        )
        .as_posix()
    )

    return {
        "resolved": True,
        "relative_path": (
            resolved_rel
        ),
        "source": (
            "raw_relocation"
            if resolved_rel.casefold().startswith(
                "raw/"
            )
            else "review_relocation"
        ),
        "matched_by": (
            "sha256+basename"
            if expected_sha
            else "basename"
        ),
        "candidate_count": len(
            candidates
        ),
        "requested_relative_path": (
            raw_relative
        ),
    }


def _operator_source_video_ready(
    entry,
):
    rel = str(
        (
            entry
            or {}
        ).get(
            "relative_path"
        )
        or ""
    ).strip()

    if not rel:
        return False

    try:
        context = (
            _operator_source_video_context(
                rel,
                (
                    entry
                    or {}
                ).get(
                    "product_name"
                ),
                (
                    entry
                    or {}
                ).get(
                    "language"
                ),
            )
        )
    except HTTPException as exc:
        detail = (
            getattr(
                exc,
                "detail",
                None,
            )
        )

        is_missing = (
            getattr(
                exc,
                "status_code",
                None,
            )
            == 404
            and isinstance(
                detail,
                dict,
            )
            and detail.get(
                "error"
            )
            == "file_not_found"
        )

        if not is_missing:
            raise

        relocation = (
            _operator_relocate_stale_source(
                rel,
                sha256_hint=(
                    (
                        entry
                        or {}
                    ).get(
                        "sha256"
                    )
                    or (
                        entry
                        or {}
                    ).get(
                        "source_sha256"
                    )
                ),
                product_hint=(
                    (
                        entry
                        or {}
                    ).get(
                        "product_name"
                    )
                ),
                language_hint=(
                    (
                        entry
                        or {}
                    ).get(
                        "language"
                    )
                ),
            )
        )

        if not (
            relocation
            and relocation.get(
                "resolved"
            )
        ):
            return False

        rel = (
            relocation[
                "relative_path"
            ]
        )

        if isinstance(
            entry,
            dict,
        ):
            entry[
                "stale_relative_path"
            ] = (
                entry.get(
                    "relative_path"
                )
            )

            entry[
                "relative_path"
            ] = rel

            entry[
                "path_relocation"
            ] = relocation

        context = (
            _operator_source_video_context(
                rel,
                (
                    entry
                    or {}
                ).get(
                    "product_name"
                ),
                (
                    entry
                    or {}
                ).get(
                    "language"
                ),
            )
        )

    return bool(
        context.get(
            "archive_ready"
        )
    )


def _operator_extract_videos(
    payload,
):
    """
    Extract usable workspace media paths without allowing stale API paths to
    abort the whole Operator task.

    /crawl/items and /language/detect may legitimately return both:
      relative_path     -> old review path
      new_relative_path -> promoted raw path

    Once promotion moves the file, the old review path no longer exists.
    Therefore path priority matters and file_not_found on an old path is a
    reconciliation signal, not a fatal error.
    """
    results = []
    seen = set()

    path_priority = (
        "new_relative_path",
        "processed_video_relative_path",
        "existing_path",
        "downloaded_path",
        "saved_path",
        "video_relative_path",
        "file_path",
        "relative_path",
    )

    path_keys = set(
        path_priority
    )

    def add_path(
        raw_path,
        value,
        product,
        language,
        path_key,
    ):
        if not isinstance(
            raw_path,
            str,
        ):
            return

        rel = (
            _operator_workspace_relative(
                raw_path
            )
        )

        if not rel:
            return

        normalized = (
            rel.casefold()
        )

        if normalized in seen:
            return

        try:
            context = (
                _operator_source_video_context(
                    rel,
                    product,
                    language,
                )
            )
        except HTTPException as exc:
            detail = (
                getattr(
                    exc,
                    "detail",
                    None,
                )
            )

            is_missing = (
                getattr(
                    exc,
                    "status_code",
                    None,
                )
                == 404
                and (
                    isinstance(
                        detail,
                        dict,
                    )
                    and detail.get(
                        "error"
                    )
                    == "file_not_found"
                )
            )

            if is_missing:
                relocation = (
                    _operator_relocate_stale_source(
                        rel,
                        sha256_hint=(
                            value.get(
                                "sha256"
                            )
                            or value.get(
                                "source_sha256"
                            )
                        ),
                        product_hint=(
                            product
                        ),
                        language_hint=(
                            language
                        ),
                    )
                )

                if not (
                    relocation
                    and relocation.get(
                        "resolved"
                    )
                ):
                    # The old path may be a pre-move API field with no current
                    # filesystem target. Keep scanning the response for another
                    # final path rather than aborting the entire batch.
                    return

                rel = (
                    relocation[
                        "relative_path"
                    ]
                )

                normalized = (
                    rel.casefold()
                )

                if normalized in seen:
                    return

                context = (
                    _operator_source_video_context(
                        rel,
                        product,
                        language,
                    )
                )

                context[
                    "stale_relative_path"
                ] = (
                    raw_path
                )

                context[
                    "path_relocation"
                ] = (
                    relocation
                )

            else:
                raise

        seen.add(
            normalized
        )

        context[
            "result_status"
        ] = (
            value.get(
                "status"
            )
        )

        context[
            "language_detection"
        ] = (
            value.get(
                "language_detection"
            )
            or (
                value.get(
                    "detection"
                )
                if isinstance(
                    value.get(
                        "detection"
                    ),
                    dict,
                )
                else None
            )
        )

        context[
            "path_source_key"
        ] = (
            path_key
        )

        for key in (
            "sha256",
            "source_sha256",
            "package_name",
            "app_title",
            "product_name_source",
            "language_source",
            "language_code",
            "source_media_url",
            "rank",
            "search_rank",
            "imp_estimate",
            "impression",
        ):
            if (
                context.get(
                    key
                )
                in (
                    None,
                    "",
                )
                and value.get(
                    key
                )
                not in (
                    None,
                    "",
                )
            ):
                context[
                    key
                ] = (
                    value.get(
                        key
                    )
                )

        results.append(
            context
        )

    def walk(
        value,
        inherited_product=None,
        inherited_language=None,
    ):
        if isinstance(
            value,
            dict,
        ):
            product = (
                value.get(
                    "product_name"
                )
                or value.get(
                    "product"
                )
                or inherited_product
            )

            language = (
                value.get(
                    "language"
                )
                or value.get(
                    "detected_language"
                )
                or inherited_language
            )

            # Process promoted/final paths before pre-move relative_path.
            for key in (
                path_priority
            ):
                if key in value:
                    add_path(
                        value.get(
                            key
                        ),
                        value,
                        product,
                        language,
                        key,
                    )

            # Then walk nested data, but do not process path strings twice.
            for key, nested in (
                value.items()
            ):
                if (
                    str(
                        key
                    )
                    in path_keys
                ):
                    continue

                walk(
                    nested,
                    product,
                    language,
                )

            return

        if isinstance(
            value,
            list,
        ):
            for nested in value:
                walk(
                    nested,
                    inherited_product,
                    inherited_language,
                )

    walk(
        payload
    )

    return (
        results
    )

def _operator_parse_imp_estimate(
    value,
):
    if value is None:
        return None

    if isinstance(
        value,
        bool,
    ):
        return None

    if isinstance(
        value,
        (
            int,
            float,
        ),
    ):
        number = float(
            value
        )

        if number < 0:
            return None

        return number

    if isinstance(
        value,
        dict,
    ):
        for key in (
            "value",
            "estimate",
            "total",
            "max",
            "upper",
        ):
            if key in value:
                parsed = (
                    _operator_parse_imp_estimate(
                        value.get(
                            key
                        )
                    )
                )

                if parsed is not None:
                    return parsed

        return None

    raw = str(
        value
    ).strip()

    if not raw:
        return None

    normalized = (
        raw
        .replace(
            ",",
            "",
        )
        .replace(
            " ",
            "",
        )
    )

    match = re.search(
        r"([-+]?[0-9]*\.?[0-9]+)([KMB])?",
        normalized,
        flags=re.IGNORECASE,
    )

    if not match:
        return None

    try:
        number = float(
            match.group(
                1
            )
        )
    except Exception:
        return None

    suffix = (
        match.group(
            2
        )
        or ""
    ).upper()

    multiplier = {
        "": 1.0,
        "K": 1_000.0,
        "M": 1_000_000.0,
        "B": 1_000_000_000.0,
    }.get(
        suffix,
        1.0,
    )

    number = (
        number
        * multiplier
    )

    if number < 0:
        return None

    return number


def _operator_record_imp_estimate(
    record,
):
    if not isinstance(
        record,
        dict,
    ):
        return None

    aliases = {
        "imp_estimate",
        "impestimate",
        "imp_est",
        "impest",
        "impression_estimate",
        "impressions_estimate",
        "estimated_impressions",
        "estimate_impressions",
        "impression",
        "impressions",
        "imp",
    }

    normalized_aliases = {
        re.sub(
            r"[^a-z0-9]",
            "",
            alias.casefold(),
        )
        for alias in aliases
    }

    for key, value in (
        record.items()
    ):
        normalized_key = re.sub(
            r"[^a-z0-9]",
            "",
            str(
                key
            ).casefold(),
        )

        if (
            normalized_key
            in normalized_aliases
        ):
            parsed = (
                _operator_parse_imp_estimate(
                    value
                )
            )

            if parsed is not None:
                return parsed

    for container_key in (
        "metrics",
        "metric",
        "statistics",
        "stats",
        "data_performance",
        "performance",
    ):
        nested = (
            record.get(
                container_key
            )
        )

        if isinstance(
            nested,
            dict,
        ):
            parsed = (
                _operator_record_imp_estimate(
                    nested
                )
            )

            if parsed is not None:
                return parsed

    return None


def _operator_find_sort_contract(
    payload,
):
    """
    Find the crawler's sort diagnostic even when an endpoint wraps the result
    under data/result/payload. Do not search arbitrary scalar values; only
    dictionaries that look like a sort contract are accepted.
    """
    if not isinstance(
        payload,
        dict,
    ):
        return {}

    queue = [
        (
            payload,
            0,
        )
    ]

    while queue:
        value, depth = queue.pop(
            0
        )

        if not isinstance(
            value,
            dict,
        ):
            continue

        sort_value = value.get(
            "sort"
        )

        if isinstance(
            sort_value,
            dict,
        ):
            if any(
                key in sort_value
                for key in (
                    "impression_desc_verified",
                    "field",
                    "rule",
                    "diagnostic",
                )
            ):
                return sort_value

        if any(
            key in value
            for key in (
                "impression_desc_verified",
                "field",
                "rule",
            )
        ):
            # Some crawler builds flatten the sort metadata.
            if (
                "impression_desc_verified"
                in value
            ):
                return value

        if depth >= 4:
            continue

        for nested in value.values():
            if isinstance(
                nested,
                dict,
            ):
                queue.append(
                    (
                        nested,
                        depth + 1,
                    )
                )

    return {}


def _operator_desc_rule(
    value,
):
    raw = str(
        value
        or ""
    ).strip().casefold()

    return raw in {
        "desc",
        "descending",
        "-1",
    }


def _operator_native_impression_request(
    request_payload,
):
    request_payload = (
        request_payload
        if isinstance(
            request_payload,
            dict,
        )
        else {}
    )

    requested_field = None

    for key in (
        "field",
        "sort_field",
        "sortfield",
        "field_id",
        "fieldid",
    ):
        if request_payload.get(
            key
        ) not in (
            None,
            "",
        ):
            requested_field = (
                request_payload.get(
                    key
                )
            )
            break

    requested_rule = None

    for key in (
        "rule",
        "sort_rule",
        "sortrule",
        "sort_order",
        "order",
        "direction",
    ):
        if request_payload.get(
            key
        ) not in (
            None,
            "",
        ):
            requested_rule = (
                request_payload.get(
                    key
                )
            )
            break

    native = (
        str(
            requested_field
            or ""
        ).strip()
        == "15"
        and _operator_desc_rule(
            requested_rule
        )
    )

    generic_sort = str(
        request_payload.get(
            "sort"
        )
        or request_payload.get(
            "sort_by"
        )
        or request_payload.get(
            "order_by"
        )
        or ""
    ).strip().casefold()

    generic_desc = (
        generic_sort
        in {
            "imp_estimate_desc",
            "impression_desc",
            "highest_imp",
            "imp_desc",
        }
        and _operator_desc_rule(
            request_payload.get(
                "sort_order"
            )
            or request_payload.get(
                "order"
            )
            or request_payload.get(
                "direction"
            )
            or "desc"
        )
    )

    return {
        "native": bool(
            native
        ),
        "generic_desc": bool(
            generic_desc
        ),
        "field": (
            requested_field
        ),
        "rule": (
            requested_rule
        ),
    }


def _operator_search_order_evidence(
    items,
):
    candidates = list(
        items
        or []
    )

    impressions = []
    missing = []
    invalid_visual_assets = []
    invalid_visual_assets = []

    for index, item in enumerate(
        candidates,
        start=1,
    ):
        parsed = (
            _operator_parse_imp_estimate(
                (
                    item
                    or {}
                ).get(
                    "imp_estimate"
                )
            )
        )

        if parsed is None:
            missing.append(
                index
            )
        else:
            impressions.append(
                parsed
            )

    complete = (
        len(
            candidates
        )
        > 0
        and not missing
        and len(
            impressions
        )
        == len(
            candidates
        )
    )

    non_increasing = (
        complete
        and all(
            impressions[
                index
            ]
            >= impressions[
                index + 1
            ]
            for index in range(
                max(
                    0,
                    len(
                        impressions
                    )
                    - 1,
                )
            )
        )
    )

    ranks = []

    for item in candidates:
        raw_rank = (
            (
                item
                or {}
            ).get(
                "crawler_rank"
            )
        )

        try:
            rank_value = int(
                raw_rank
            )
        except Exception:
            ranks = []
            break

        ranks.append(
            rank_value
        )

    rank_sequence_verified = bool(
        ranks
        and ranks
        == list(
            range(
                ranks[
                    0
                ],
                ranks[
                    0
                ]
                + len(
                    ranks
                ),
            )
        )
    )

    return {
        "candidate_count": len(
            candidates
        ),
        "complete_impression_values": bool(
            complete
        ),
        "non_increasing": bool(
            non_increasing
        ),
        "rank_sequence_verified": bool(
            rank_sequence_verified
        ),
        "first_impressions": (
            impressions[
                :10
            ]
        ),
        "missing_impression_indexes": (
            missing[
                :20
            ]
        ),
        "crawler_ranks": (
            ranks[
                :20
            ]
        ),
    }


def _operator_crawler_sort_diagnostic(
    payload,
    *,
    request_payload=None,
    extracted_items=None,
):
    sort = (
        _operator_find_sort_contract(
            payload
        )
    )

    claimed_verified = bool(
        sort.get(
            "impression_desc_verified"
        )
    )

    response_field = (
        sort.get(
            "field"
        )
    )

    response_rule = (
        sort.get(
            "rule"
        )
    )

    request_contract = (
        _operator_native_impression_request(
            request_payload
        )
    )

    order_evidence = (
        _operator_search_order_evidence(
            extracted_items
        )
    )

    response_native = (
        str(
            response_field
            or ""
        ).strip()
        == "15"
        and _operator_desc_rule(
            response_rule
        )
    )

    # Primary proof: crawler explicitly says it verified native field=15 DESC.
    crawler_native_verified = (
        claimed_verified
        and (
            response_native
            or (
                response_field
                in (
                    None,
                    "",
                )
                and response_rule
                in (
                    None,
                    "",
                )
            )
        )
    )

    # Recovery proof for wrapper/diagnostic regressions:
    # 1. Operator explicitly requested native field=15 DESC.
    # 2. Every returned candidate has an exposure value.
    # 3. Returned order itself is non-increasing.
    #
    # This does NOT simply trust a generic local re-sort. Verification is done
    # on the crawler's ORIGINAL response order before Top-N selection.
    response_order_verified = (
        bool(
            request_contract.get(
                "native"
            )
        )
        and bool(
            order_evidence.get(
                "complete_impression_values"
            )
        )
        and bool(
            order_evidence.get(
                "non_increasing"
            )
        )
    )

    verified = (
        crawler_native_verified
        or response_order_verified
    )

    if crawler_native_verified:
        verification_source = (
            "crawler_impression_desc_verified"
        )
    elif response_order_verified:
        verification_source = (
            "native_request_plus_response_order"
        )
    else:
        verification_source = (
            "not_verified"
        )

    return {
        "verified": bool(
            verified
        ),
        "verification_source": (
            verification_source
        ),
        "crawler_claimed_verified": (
            claimed_verified
        ),
        "field": (
            response_field
        ),
        "rule": (
            response_rule
        ),
        "diagnostic": (
            sort.get(
                "diagnostic"
            )
        ),
        "request_field": (
            request_contract.get(
                "field"
            )
        ),
        "request_rule": (
            request_contract.get(
                "rule"
            )
        ),
        "request_native": bool(
            request_contract.get(
                "native"
            )
        ),
        "request_generic_desc": bool(
            request_contract.get(
                "generic_desc"
            )
        ),
        "response_native": bool(
            response_native
        ),
        "response_order": (
            order_evidence
        ),
    }


def _operator_rank_search_items(
    items,
    requested_count,
    *,
    crawler_sort=None,
):
    """
    Enforce the business contract:
      Imp.Estimate DESC -> Top N -> detail/download.

    We do not silently trust response order. Every candidate used for ranking
    must expose an interpretable Imp.Estimate value.
    """
    candidates = list(
        items
        or []
    )

    if not candidates:
        return (
            [],
            {
                "sort": "imp_estimate_desc",
                "candidate_count": 0,
                "ranked_count": 0,
                "requested_count": int(
                    requested_count
                ),
                "items": [],
            },
        )

    prepared = []
    missing = []

    for source_index, item in enumerate(
        candidates
    ):
        value = (
            item.get(
                "imp_estimate"
            )
        )

        parsed = (
            _operator_parse_imp_estimate(
                value
            )
        )

        if parsed is None:
            missing.append(
                {
                    "source_index": (
                        source_index + 1
                    ),
                    "url": (
                        item.get(
                            "url"
                        )
                    ),
                    "raw_imp_estimate": (
                        value
                    ),
                }
            )

            continue

        prepared.append(
            (
                source_index,
                parsed,
                dict(
                    item
                ),
            )
        )

    if missing:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": (
                    "operator_search_ranking"
                ),
                "error": (
                    "imp_estimate_required_for_strict_ranking"
                ),
                "message": (
                    "Keyword download was stopped because one or more search "
                    "candidates did not expose a valid Imp.Estimate. Strict "
                    "Top-N ranking cannot be guaranteed without it."
                ),
                "candidate_count": len(
                    candidates
                ),
                "missing_count": len(
                    missing
                ),
                "missing_samples": (
                    missing[
                        :20
                    ]
                ),
            },
        )

    # Python sort is stable: equal exposure preserves search response order.
    prepared.sort(
        key=lambda row: (
            -row[
                1
            ],
            row[
                0
            ],
        )
    )

    requested = max(
        1,
        int(
            requested_count
        ),
    )

    ranked = []

    for rank, (
        source_index,
        imp_value,
        item,
    ) in enumerate(
        prepared[
            :requested
        ],
        start=1,
    ):
        item[
            "imp_estimate"
        ] = (
            imp_value
        )

        item[
            "search_rank"
        ] = (
            rank
        )

        item[
            "search_source_index"
        ] = (
            source_index
            + 1
        )

        ranked.append(
            item
        )

    crawler_sort = (
        crawler_sort
        or {}
    )

    if not bool(
        crawler_sort.get(
            "verified"
        )
    ):
        raise HTTPException(
            status_code=422,
            detail={
                "stage": (
                    "operator_search_ranking"
                ),
                "error": (
                    "insight_impression_sort_not_verified"
                ),
                "message": (
                    "Keyword Top-N selection requires a verified Insight "
                    "Imp.Estimate descending search. The Operator requested "
                    "native field=15/rule=desc, but neither the crawler's "
                    "verification flag nor the original response order supplied "
                    "enough evidence to prove Top-N correctness."
                ),
                "crawler_sort": (
                    crawler_sort
                ),
            },
        )

    audit = {
        "sort": (
            "imp_estimate_desc"
        ),
        "strict": True,
        "crawler_verified": bool(
            crawler_sort.get(
                "verified"
            )
        ),
        "crawler_sort_field": (
            crawler_sort.get(
                "field"
            )
        ),
        "crawler_sort_rule": (
            crawler_sort.get(
                "rule"
            )
        ),
        "crawler_sort_diagnostic": (
            crawler_sort.get(
                "diagnostic"
            )
        ),
        "crawler_sort_verification_source": (
            crawler_sort.get(
                "verification_source"
            )
        ),
        "crawler_request_field": (
            crawler_sort.get(
                "request_field"
            )
        ),
        "crawler_request_rule": (
            crawler_sort.get(
                "request_rule"
            )
        ),
        "crawler_response_order": (
            crawler_sort.get(
                "response_order"
            )
        ),
        "candidate_count": len(
            candidates
        ),
        "ranked_count": len(
            ranked
        ),
        "requested_count": (
            requested
        ),
        "is_non_increasing": all(
            ranked[
                index
            ][
                "imp_estimate"
            ]
            >= ranked[
                index + 1
            ][
                "imp_estimate"
            ]
            for index in range(
                max(
                    0,
                    len(
                        ranked
                    )
                    - 1,
                )
            )
        ),
        "items": [
            {
                "rank": (
                    item[
                        "search_rank"
                    ]
                ),
                "imp_estimate": (
                    item[
                        "imp_estimate"
                    ]
                ),
                "url": (
                    item.get(
                        "url"
                    )
                ),
                "source_index": (
                    item.get(
                        "search_source_index"
                    )
                ),
                "crawler_rank": (
                    item.get(
                        "crawler_rank"
                    )
                ),
                "crawler_impression": (
                    item.get(
                        "crawler_impression"
                    )
                ),
            }
            for item in ranked
        ],
    }

    return (
        ranked,
        audit,
    )


def _operator_detail_id_from_url(
    url,
):
    raw = str(
        url
        or ""
    ).strip()

    marker = (
        "/creative/material/detail/"
    )

    if marker not in raw:
        return None

    tail = raw.split(
        marker,
        1,
    )[
        1
    ]

    value = (
        tail.split(
            "?",
            1,
        )[
            0
        ]
        .split(
            "#",
            1,
        )[
            0
        ]
        .strip(
            "/"
        )
    )

    return (
        value
        or None
    )


def _operator_detail_id_from_record(
    value,
):
    if not isinstance(
        value,
        dict,
    ):
        return None

    url = str(
        value.get(
            "url"
        )
        or value.get(
            "detail_url"
        )
        or value.get(
            "material_detail_url"
        )
        or ""
    ).strip()

    from_url = (
        _operator_detail_id_from_url(
            url
        )
    )

    if from_url:
        return from_url

    for key in (
        "detail_id",
        "material_id",
        "creative_id",
        "creative_material_id",
        "id",
    ):
        candidate = str(
            value.get(
                key
            )
            or ""
        ).strip()

        if (
            len(
                candidate
            )
            >= 20
            and re.fullmatch(
                r"[A-Za-z0-9_-]+",
                candidate,
            )
        ):
            return candidate

    return None


def _operator_detail_item_richness(
    item,
):
    item = (
        item
        or {}
    )

    score = 0

    for key, weight in (
        (
            "product_name",
            8,
        ),
        (
            "app_title",
            7,
        ),
        (
            "package_name",
            7,
        ),
        (
            "source_filename",
            8,
        ),
        (
            "source_media_url",
            5,
        ),
        (
            "imp_estimate",
            4,
        ),
        (
            "crawler_impression",
            4,
        ),
        (
            "crawler_rank",
            2,
        ),
        (
            "language",
            2,
        ),
    ):
        if item.get(
            key
        ) not in (
            None,
            "",
        ):
            score += weight

    if item.get(
        "countries"
    ):
        score += 1

    return score


def _operator_merge_detail_record(
    base,
    extra,
):
    merged = dict(
        base
        or {}
    )

    extra = (
        extra
        or {}
    )

    for key in (
        "url",
        "detail_id",
        "app_title",
        "package_name",
        "product_name",
        "product_name_source",
        "language",
        "material_type",
        "source_filename",
        "source_media_url",
        "crawler_rank",
        "crawler_impression",
        "search_rank",
        "search_source_index",
    ):
        value = (
            extra.get(
                key
            )
        )

        if (
            value
            not in (
                None,
                "",
            )
            and merged.get(
                key
            )
            in (
                None,
                "",
            )
        ):
            merged[
                key
            ] = value

    current_imp = (
        _operator_parse_imp_estimate(
            merged.get(
                "imp_estimate"
            )
        )
    )

    extra_imp = (
        _operator_parse_imp_estimate(
            extra.get(
                "imp_estimate"
            )
        )
    )

    if (
        current_imp is None
        and extra_imp is not None
    ):
        merged[
            "imp_estimate"
        ] = extra_imp

    elif (
        current_imp is not None
        and extra_imp is not None
    ):
        merged[
            "imp_estimate"
        ] = max(
            current_imp,
            extra_imp,
        )

    countries = []

    for source in (
        merged.get(
            "countries"
        )
        or [],
        extra.get(
            "countries"
        )
        or [],
    ):
        if isinstance(
            source,
            str,
        ):
            source = [
                source
            ]

        if isinstance(
            source,
            list,
        ):
            for country in source:
                country = str(
                    country
                    or ""
                ).strip()

                if (
                    country
                    and country
                    not in countries
                ):
                    countries.append(
                        country
                    )

    merged[
        "countries"
    ] = countries

    merged.setdefault(
        "language",
        None,
    )

    merged.setdefault(
        "material_type",
        "video",
    )

    return merged


def _operator_extract_detail_items(
    payload,
):
    """
    Insight may repeat one material several times in nested wrappers. Never use
    first-win URL dedupe: shallow wrappers can contain only detail_url while a
    later record contains package/app/impression/source_filename.
    """
    records = []

    def first_text(
        value,
        keys,
    ):
        for key in keys:
            nested = value.get(
                key
            )

            if nested not in (
                None,
                "",
            ):
                text_value = str(
                    nested
                ).strip()

                if text_value:
                    return text_value

        return None

    def first_dict(
        value,
        keys,
    ):
        for key in keys:
            nested = value.get(
                key
            )

            if isinstance(
                nested,
                dict,
            ):
                return nested

        return {}

    def record_from_dict(
        value,
    ):
        url = str(
            value.get(
                "url"
            )
            or value.get(
                "detail_url"
            )
            or value.get(
                "detailUrl"
            )
            or value.get(
                "material_detail_url"
            )
            or value.get(
                "materialDetailUrl"
            )
            or ""
        ).strip()

        detail_id = (
            _operator_detail_id_from_record(
                value
            )
        )

        if (
            "/creative/material/detail/"
            not in url
            and not detail_id
        ):
            return None

        app_obj = (
            first_dict(
                value,
                [
                    "app",
                    "application",
                ],
            )
        )

        media_obj = (
            first_dict(
                value,
                [
                    "media",
                    "video",
                    "creative",
                    "material",
                ],
            )
        )

        app_title = (
            first_text(
                value,
                [
                    "app_title",
                    "appTitle",
                    "app_name",
                    "appName",
                    "application_name",
                    "applicationName",
                ],
            )
            or first_text(
                app_obj,
                [
                    "app_title",
                    "name",
                    "title",
                    "app_name",
                ],
            )
        )

        package_name = (
            first_text(
                value,
                [
                    "package_name",
                    "packageName",
                    "package",
                    "bundle_id",
                    "bundleId",
                ],
            )
            or first_text(
                app_obj,
                [
                    "package_name",
                    "packageName",
                    "package",
                    "bundle_id",
                    "bundleId",
                ],
            )
        )

        product_name = (
            first_text(
                value,
                [
                    "product_name",
                    "productName",
                    "product",
                ],
            )
            or first_text(
                app_obj,
                [
                    "product_name",
                    "productName",
                    "product",
                ],
            )
        )

        countries = (
            value.get(
                "countries"
            )
            or value.get(
                "country_list"
            )
            or value.get(
                "country_codes"
            )
            or []
        )

        if isinstance(
            countries,
            str,
        ):
            countries = [
                countries
            ]

        source_filename = (
            first_text(
                value,
                [
                    "source_filename",
                    "sourceFilename",
                    "filename",
                    "file_name",
                    "fileName",
                    "original_filename",
                    "originalFilename",
                ],
            )
            or first_text(
                media_obj,
                [
                    "source_filename",
                    "sourceFilename",
                    "filename",
                    "file_name",
                    "fileName",
                    "original_filename",
                    "originalFilename",
                ],
            )
        )

        source_media_url = (
            first_text(
                value,
                [
                    "source_media_url",
                    "video_url",
                    "videoUrl",
                    "media_url",
                    "mediaUrl",
                ],
            )
            or first_text(
                media_obj,
                [
                    "source_media_url",
                    "video_url",
                    "videoUrl",
                    "media_url",
                    "mediaUrl",
                ],
            )
        )

        return {
            "url": (
                url
                if "/creative/material/detail/"
                in url
                else None
            ),
            "detail_id": (
                detail_id
            ),
            "imp_estimate": (
                _operator_record_imp_estimate(
                    value
                )
            ),
            "crawler_rank": (
                value.get(
                    "rank"
                )
            ),
            "crawler_impression": (
                value.get(
                    "impression"
                )
            ),
            "app_title": (
                app_title
            ),
            "package_name": (
                package_name
            ),
            "product_name": (
                product_name
            ),
            "countries": (
                countries
                if isinstance(
                    countries,
                    list,
                )
                else []
            ),
            "language": (
                value.get(
                    "language"
                )
            ),
            "material_type": (
                value.get(
                    "material_type"
                )
                or "video"
            ),
            "source_filename": (
                source_filename
            ),
            "source_media_url": (
                source_media_url
            ),
        }

    def walk(
        value,
    ):
        if isinstance(
            value,
            dict,
        ):
            record = (
                record_from_dict(
                    value
                )
            )

            if record:
                records.append(
                    record
                )

            for nested in (
                value.values()
            ):
                walk(
                    nested
                )

        elif isinstance(
            value,
            list,
        ):
            for nested in value:
                walk(
                    nested
                )

    walk(
        payload
    )

    if not records:
        return []

    url_by_detail_id = {}

    for record in records:
        detail_id = str(
            record.get(
                "detail_id"
            )
            or ""
        ).strip()

        url = str(
            record.get(
                "url"
            )
            or ""
        ).strip()

        if (
            detail_id
            and url
        ):
            url_by_detail_id[
                detail_id
            ] = url

    for record in records:
        if not record.get(
            "url"
        ):
            detail_id = str(
                record.get(
                    "detail_id"
                )
                or ""
            ).strip()

            if (
                detail_id
                and detail_id
                in url_by_detail_id
            ):
                record[
                    "url"
                ] = (
                    url_by_detail_id[
                        detail_id
                    ]
                )

    grouped = {}
    order = []

    for record in records:
        url = str(
            record.get(
                "url"
            )
            or ""
        ).strip()

        detail_id = str(
            record.get(
                "detail_id"
            )
            or _operator_detail_id_from_url(
                url
            )
            or ""
        ).strip()

        key = (
            (
                "id",
                detail_id,
            )
            if detail_id
            else (
                "url",
                url,
            )
        )

        if not (
            detail_id
            or url
        ):
            continue

        if key not in grouped:
            grouped[
                key
            ] = dict(
                record
            )

            order.append(
                key
            )

        else:
            grouped[
                key
            ] = (
                _operator_merge_detail_record(
                    grouped[
                        key
                    ],
                    record,
                )
            )

    items = [
        grouped[
            key
        ]
        for key in order
    ]

    return [
        item
        for item in items
        if str(
            item.get(
                "url"
            )
            or ""
        ).strip()
    ]


def _operator_product_map_path():
    return (
        WORKSPACE
        / "config"
        / "product_map.json"
    )


def _operator_load_product_map():
    path = (
        _operator_product_map_path()
    )

    default = {
        "package_names": {},
        "app_titles": {},
    }

    if not path.is_file():
        return default

    try:
        payload = json.loads(
            path.read_text(
                encoding="utf-8-sig"
            )
        )
    except Exception:
        return default

    if not isinstance(
        payload,
        dict,
    ):
        return default

    package_names = (
        payload.get(
            "package_names"
        )
    )

    app_titles = (
        payload.get(
            "app_titles"
        )
    )

    if not isinstance(
        package_names,
        dict,
    ):
        package_names = {}

    if not isinstance(
        app_titles,
        dict,
    ):
        app_titles = {}

    payload[
        "package_names"
    ] = package_names

    payload[
        "app_titles"
    ] = app_titles

    return payload


def _operator_save_product_map(
    payload,
):
    path = (
        _operator_product_map_path()
    )

    path.parent.mkdir(
        parents=True,
        exist_ok=True,
    )

    temp_path = (
        path.with_suffix(
            path.suffix
            + ".tmp"
        )
    )

    temp_path.write_text(
        json.dumps(
            payload,
            ensure_ascii=False,
            indent=2,
            sort_keys=True,
        )
        + "\n",
        encoding="utf-8",
    )

    temp_path.replace(
        path
    )

    return path


def _operator_clean_product_label(
    value,
):
    text = str(
        value
        or ""
    ).strip()

    if not text:
        return None

    text = re.sub(
        r"<[^>]+>",
        "",
        text,
    )

    text = (
        text
        .replace(
            "&amp;",
            "&",
        )
        .replace(
            "&nbsp;",
            " ",
        )
    )

    text = re.sub(
        r"\s+",
        " ",
        text,
    ).strip()

    if not text:
        return None

    if text.casefold() in {
        "unknown",
        "unknown product",
        "n/a",
        "none",
        "null",
    }:
        return None

    text = re.sub(
        r'[<>:"/\\|?*]',
        " ",
        text,
    )

    text = re.sub(
        r"\s+",
        " ",
        text,
    ).strip(
        " .-_"
    )

    if not text:
        return None

    return text[
        :80
    ].strip()


def _operator_product_from_app_title(
    app_title,
):
    """
    Derive a compact product label only from an explicit Insight App title.

    This is normalization, not package-name guessing:
      "ReelShort - Stream Drama & TV" -> "ReelShort"
      "GoodShort: Movies & Dramas"    -> "GoodShort"

    If there is no clear separator, keep the explicit App title itself.
    """
    cleaned = (
        _operator_clean_product_label(
            app_title
        )
    )

    if not cleaned:
        return None

    for separator in (
        " - ",
        " – ",
        " — ",
        " | ",
        ": ",
    ):
        if separator not in cleaned:
            continue

        prefix = (
            cleaned.split(
                separator,
                1,
            )[
                0
            ].strip()
        )

        prefix = (
            _operator_clean_product_label(
                prefix
            )
        )

        if (
            prefix
            and 2 <= len(
                prefix
            ) <= 48
        ):
            return prefix

    return cleaned


def _operator_auto_learn_product(
    item,
):
    """
    product_map.json is a cache / normalization layer, not a whitelist.

    Priority:
      1. Explicit product_name from the current Insight detail material
      2. Explicit app_title from the current Insight detail material
      3. Existing exact app-title override
      4. Existing package override, only when there is no current explicit
         detail identity (package mappings are historical cache, not truth)

    package_name alone is NEVER converted into a guessed product name.
    """
    current = dict(
        item
        or {}
    )

    package_name = str(
        current.get(
            "package_name"
        )
        or ""
    ).strip()

    app_title = str(
        current.get(
            "app_title"
        )
        or ""
    ).strip()

    explicit_product = (
        _operator_clean_product_label(
            current.get(
                "product_name"
            )
        )
    )

    product_map = (
        _operator_load_product_map()
    )

    package_names = (
        product_map.setdefault(
            "package_names",
            {},
        )
    )

    app_titles = (
        product_map.setdefault(
            "app_titles",
            {},
        )
    )

    # Current explicit detail identity always wins over historical cache values.
    product_name = explicit_product or _operator_product_from_app_title(app_title)

    if product_name:
        source = (
            "detail_product_name"
            if explicit_product
            else "detail_app_title"
        )
        updated = False

        if package_name and package_names.get(package_name) != product_name:
            package_names[package_name] = product_name
            updated = True

        if app_title and app_titles.get(app_title) != product_name:
            app_titles[app_title] = product_name
            updated = True

        if updated:
            _operator_save_product_map(product_map)

        current["product_name"] = product_name
        current["product_name_source"] = source + "_auto_learned"
        return (
            current,
            {
                "status": "auto_learned" if updated else "resolved",
                "package_name": package_name or None,
                "app_title": app_title or None,
                "product_name": product_name,
                "source": source,
                "map_updated": updated,
                "product_map_relative_path": "config/product_map.json",
            },
        )

    existing_app = (
        app_titles.get(app_title)
        if app_title
        else None
    )

    if existing_app:
        product_name = _operator_clean_product_label(existing_app)
        if product_name:
            current["product_name"] = product_name
            current["product_name_source"] = "app_title_map"
            return (
                current,
                {
                    "status": "cache_hit",
                    "package_name": package_name or None,
                    "app_title": app_title,
                    "product_name": product_name,
                    "source": "app_title_map",
                    "map_updated": False,
                },
            )

    if not product_name:
        return (
            current,
            {
                "status": "unresolved",
                "package_name": (
                    package_name
                    or None
                ),
                "app_title": (
                    app_title
                    or None
                ),
                "product_name": None,
                "source": None,
                "map_updated": False,
                "reason": (
                    "insight_detail_has_no_explicit_product_or_app_title"
                ),
            },
        )

def _operator_patch_review_sidecar(
    relative_path,
    detail_item,
):
    video_path = (
        _safe_workspace_path(
            relative_path
        )
    )

    payload, sidecar = (
        _operator_source_sidecar_payload(
            video_path
        )
    )

    if not isinstance(
        payload,
        dict,
    ):
        payload = {}

    if sidecar is None:
        sidecar = Path(
            str(
                video_path
            )
            + ".metadata.json"
        )

    product_name = (
        _operator_clean_product_label(
            (
                detail_item
                or {}
            ).get(
                "product_name"
            )
        )
    )

    if product_name:
        payload[
            "product_name"
        ] = product_name

        payload[
            "product_name_source"
        ] = (
            (
                detail_item
                or {}
            ).get(
                "product_name_source"
            )
            or "operator_auto_recovery"
        )

    for key in (
        "package_name",
        "app_title",
        "url",
        "material_type",
    ):
        value = (
            (
                detail_item
                or {}
            ).get(
                key
            )
        )

        if value not in (
            None,
            "",
        ):
            payload[
                key
            ] = value

    countries = (
        (
            detail_item
            or {}
        ).get(
            "countries"
        )
    )

    if isinstance(
        countries,
        list,
    ) and countries:
        payload[
            "countries"
        ] = countries

    payload[
        "operator_review_recovery"
    ] = {
        "attempted": True,
        "source_relative_path": (
            relative_path
        ),
        "reason": (
            "reuse_review_asset_after_metadata_resolution"
        ),
    }

    sidecar.parent.mkdir(
        parents=True,
        exist_ok=True,
    )

    temp = (
        sidecar.with_suffix(
            sidecar.suffix
            + ".tmp"
        )
    )

    temp.write_text(
        json.dumps(
            payload,
            ensure_ascii=False,
            indent=2,
        )
        + "\n",
        encoding="utf-8",
    )

    temp.replace(
        sidecar
    )

    return (
        sidecar
        .relative_to(
            WORKSPACE
        )
        .as_posix()
    )


def _operator_recover_review_video(
    video,
    detail_item,
):
    """
    Reconcile a stale global-SHA duplicate that still points into review/.

    Historical case:
      old task -> review/missing_product/<run>/<file>
      later task resolves product
      /crawl/items -> duplicate -> old review path

    The media is not downloaded again. We patch its sidecar and reuse the
    existing /language/detect promotion path.
    """
    relative_path = str(
        (
            video
            or {}
        ).get(
            "relative_path"
        )
        or ""
    ).strip().replace(
        chr(
            92
        ),
        "/",
    )

    product_name = (
        _operator_clean_product_label(
            (
                detail_item
                or {}
            ).get(
                "product_name"
            )
        )
    )

    if (
        not relative_path
        or not relative_path.casefold().startswith(
            "review/"
        )
    ):
        return {
            "attempted": False,
            "reason": "not_review_path",
            "source_relative_path": (
                relative_path
                or None
            ),
        }

    if not product_name:
        return {
            "attempted": False,
            "reason": "product_still_unresolved",
            "source_relative_path": (
                relative_path
            ),
        }

    try:
        sidecar = (
            _operator_patch_review_sidecar(
                relative_path,
                detail_item,
            )
        )

        language_result = (
            _operator_internal_request(
                "POST",
                "/language/detect",
                json_payload={
                    "relative_path": (
                        relative_path
                    ),
                    "promote": True,
                },
                timeout=1800.0,
            )
        )

        promoted_videos = (
            _operator_extract_videos(
                language_result
                or {}
            )
        )

        ready = [
            entry
            for entry in promoted_videos
            if _operator_source_video_ready(
                entry
            )
        ]

        if ready:
            return {
                "attempted": True,
                "recovered": True,
                "source_relative_path": (
                    relative_path
                ),
                "sidecar": (
                    sidecar
                ),
                "product_name": (
                    product_name
                ),
                "language_result": (
                    language_result
                ),
                "videos": (
                    ready
                ),
            }

        return {
            "attempted": True,
            "recovered": False,
            "source_relative_path": (
                relative_path
            ),
            "sidecar": (
                sidecar
            ),
            "product_name": (
                product_name
            ),
            "language_result": (
                language_result
            ),
            "reason": (
                "language_detection_did_not_promote_to_formal_raw"
            ),
        }

    except Exception as exc:
        return {
            "attempted": True,
            "recovered": False,
            "source_relative_path": (
                relative_path
            ),
            "product_name": (
                product_name
            ),
            "reason": (
                "review_recovery_failed"
            ),
            "error": (
                _operator_error_payload(
                    exc
                )
            ),
        }

def _operator_existing_raw_video_for_item(
    detail_item,
):
    """
    Reuse a previously archived Insight source by its preserved original
    filename when it is unambiguous and belongs to the same product.

    Insight video filenames are stable across repeated searches. This avoids
    asking the detail crawler to rediscover a media URL for content that is
    already safely present in formal raw storage.
    """
    item = (
        detail_item
        or {}
    )

    filename = str(
        item.get(
            "source_filename"
        )
        or ""
    ).strip()

    if not filename:
        return None

    filename = Path(
        filename
    ).name

    if not filename.casefold().endswith(
        ".mp4"
    ):
        return None

    product_name = (
        _operator_clean_product_label(
            item.get(
                "product_name"
            )
        )
    )

    if not product_name:
        return None

    root = (
        WORKSPACE
        / "raw"
    )

    if not root.is_dir():
        return None

    candidates = []

    try:
        found = list(
            root.rglob(
                filename
            )
        )
    except Exception:
        found = []

    for candidate in found:
        if not candidate.is_file():
            continue

        try:
            rel_parts = list(
                candidate.relative_to(
                    WORKSPACE
                ).parts
            )
        except Exception:
            continue

        if (
            len(
                rel_parts
            )
            < 5
            or str(
                rel_parts[
                    0
                ]
            ).casefold()
            != "raw"
            or str(
                rel_parts[
                    1
                ]
            ).casefold()
            == "_staging"
        ):
            continue

        path_product = str(
            rel_parts[
                2
            ]
        ).strip()

        if (
            path_product.casefold()
            != product_name.casefold()
        ):
            continue

        try:
            context = (
                _operator_source_video_context(
                    candidate
                    .relative_to(
                        WORKSPACE
                    )
                    .as_posix(),
                    product_name,
                    None,
                )
            )
        except Exception:
            continue

        if not context.get(
            "archive_ready"
        ):
            continue

        candidates.append(
            (
                candidate,
                context,
            )
        )

    if not candidates:
        return None

    # If the same Insight filename exists in several historical run folders,
    # accept it only when all copies are byte-identical.
    hashes = {}

    for candidate, context in candidates:
        sha = str(
            context.get(
                "sha256"
            )
            or ""
        ).strip().casefold()

        if not sha:
            try:
                sha = (
                    _sha256_file(
                        candidate
                    )
                    .casefold()
                )
            except Exception:
                return None

        hashes.setdefault(
            sha,
            [],
        ).append(
            (
                candidate,
                context,
            )
        )

    if len(
        hashes
    ) != 1:
        return None

    identical = next(
        iter(
            hashes.values()
        )
    )

    identical.sort(
        key=lambda pair: (
            pair[
                0
            ].stat().st_mtime
        ),
        reverse=True,
    )

    candidate, context = (
        identical[
            0
        ]
    )

    context = dict(
        context
    )

    context[
        "source_filename"
    ] = filename

    context[
        "archive_cache_reused"
    ] = True

    context[
        "archive_cache_match"
    ] = (
        "source_filename+product+sha256"
    )

    return context



def _operator_crawl_error_diagnostics(payload, *, max_items=12):
    found = []

    def compact(value):
        if value is None:
            return None

        if isinstance(value, (str, int, float, bool)):
            return str(value)[:1200]

        if isinstance(value, dict):
            result = {}
            for key in (
                "type",
                "status_code",
                "stage",
                "error",
                "message",
                "detail",
            ):
                if key in value:
                    nested = compact(value.get(key))
                    if nested not in (None, "", {}):
                        result[key] = nested
            return result

        return str(value)[:1200]

    def walk(value):
        if len(found) >= max(1, int(max_items)):
            return

        if isinstance(value, dict):
            status = str(value.get("status") or "").strip().casefold()
            raw_error = value.get("error")
            raw_message = value.get("message")

            looks_failed = (
                status in {"error", "failed", "failure"}
                or value.get("ok") is False
                or raw_error not in (None, "")
            )

            if looks_failed:
                found.append(
                    {
                        "stage": value.get("stage"),
                        "status": value.get("status"),
                        "mode": value.get("mode"),
                        "detail_id": value.get("detail_id"),
                        "url": value.get("url"),
                        "error": compact(raw_error),
                        "message": compact(raw_message),
                    }
                )

            for nested in value.values():
                walk(nested)

        elif isinstance(value, list):
            for nested in value:
                walk(nested)

    walk(payload)

    unique = []
    seen = set()

    for item in found:
        marker = json.dumps(
            item,
            ensure_ascii=False,
            sort_keys=True,
            default=str,
        )

        if marker in seen:
            continue

        seen.add(marker)
        unique.append(item)

    return unique[: max(1, int(max_items))]


def _operator_response_mode(payload):
    if isinstance(payload, dict):
        value = payload.get("mode")
        if value not in (None, ""):
            return value
    return None


def _operator_no_media_diagnostic(
    payload,
):
    found = []

    def walk(
        value,
    ):
        if isinstance(
            value,
            dict,
        ):
            status = str(
                value.get(
                    "status"
                )
                or ""
            ).strip().casefold()

            error = str(
                value.get(
                    "error"
                )
                or ""
            ).strip()

            if (
                status
                == "no_media"
                or (
                    "no downloadable media url found"
                    in error.casefold()
                )
            ):
                found.append(
                    {
                        "status": (
                            value.get(
                                "status"
                            )
                        ),
                        "error": (
                            value.get(
                                "error"
                            )
                        ),
                        "detail_id": (
                            value.get(
                                "detail_id"
                            )
                        ),
                        "url": (
                            value.get(
                                "url"
                            )
                        ),
                    }
                )

            for nested in (
                value.values()
            ):
                walk(
                    nested
                )

        elif isinstance(
            value,
            list,
        ):
            for nested in value:
                walk(
                    nested
                )

    walk(
        payload
    )

    return (
        found[
            0
        ]
        if found
        else None
    )


def _operator_download_detail_url_fallback(
    openapi,
    detail_item,
):
    """
    Last-resort media acquisition for an item that /crawl/items reports as
    no_media.

    The normal fast path remains metadata-only detail enrichment + /crawl/items.
    This fallback enables real URL download only for the failed item.
    """
    url = str(
        (
            detail_item
            or {}
        ).get(
            "url"
        )
        or ""
    ).strip()

    if not url:
        return None

    url_path = (
        _operator_find_crawl_path(
            openapi,
            "url",
        )
    )

    # If the installation has no dedicated URL crawler and "url" resolves to
    # /crawl/items, retrying would simply repeat the same failure.
    if (
        str(
            url_path
        ).rstrip(
            "/"
        )
        == "/crawl/items"
    ):
        return None

    payload = (
        _operator_fill_schema_payload(
            openapi,
            url_path,
            mode="url",
            detail_url=url,
            download_count=1,
            url_action="download",
        )
    )

    for action_key in (
        "mode",
        "action",
        "operation",
        "crawl_mode",
    ):
        if action_key in payload:
            schema_prop = (
                (
                    _operator_request_schema(
                        openapi,
                        url_path,
                    ).get(
                        "properties"
                    )
                    or {}
                ).get(
                    action_key
                )
                or {}
            )

            selected_action = (
                _operator_url_action_schema_value(
                    schema_prop,
                    "download",
                )
            )

            if selected_action not in (
                None,
                "",
            ):
                payload[
                    action_key
                ] = selected_action

    for key in list(
        payload.keys()
    ):
        lower = str(
            key
        ).casefold()

        if lower in (
            "auto_download",
            "download",
            "download_media",
        ):
            payload[
                key
            ] = True

        elif lower == "download_cover":
            payload[
                key
            ] = False

        elif lower == "auto_detect_language":
            payload[
                key
            ] = True

        elif lower == "wait_ms":
            payload[
                key
            ] = max(
                int(
                    payload.get(
                        key
                    )
                    or 0
                ),
                8000,
            )

    return (
        _operator_internal_request(
            "POST",
            url_path,
            json_payload=payload,
            timeout=1800.0,
        )
    )


def _operator_crawl_items(
    items,
):
    if not items:
        return None

    return (
        _operator_internal_request(
            "POST",
            "/crawl/items",
            json_payload={
                "items": items,
                "wait_ms": 5000,
                "download_cover": False,
                "auto_detect_language": True,
            },
            timeout=1800.0,
        )
    )


def _operator_merge_detail_item(
    base,
    extra,
):
    return _operator_merge_detail_record(
        base,
        extra,
    )


def _operator_merge_identity_from_payload(base, payload):
    """Merge explicit Insight identity/media metadata from one material response."""
    merged = dict(base or {})
    if not isinstance(payload, (dict, list)):
        return merged

    for candidate in sorted(
        _operator_extract_detail_items(payload),
        key=_operator_detail_item_richness,
    ):
        merged = _operator_merge_detail_record(merged, candidate)

    alias_map = {
        "detail_id": ("detail_id", "detailId", "material_id", "materialId"),
        "app_title": ("app_title", "appTitle", "app_name", "appName",
                      "application_name", "applicationName"),
        "package_name": ("package_name", "packageName", "package",
                         "bundle_id", "bundleId", "app_package", "appPackage"),
        "product_name": ("product_name", "productName",
                         "app_product_name", "appProductName"),
        "product_name_source": ("product_name_source", "productNameSource",
                                "product_source", "productSource"),
        "source_filename": ("source_filename", "sourceFilename",
                            "original_filename", "originalFilename",
                            "file_name", "fileName"),
        "source_media_url": ("source_media_url", "sourceMediaUrl",
                             "video_url", "videoUrl", "media_url", "mediaUrl",
                             "download_url", "downloadUrl"),
        "language": ("language", "detected_language", "detectedLanguage",
                     "language_name", "languageName"),
    }

    recovered = {}
    for canonical, aliases in alias_map.items():
        value = _operator_nested_first(payload, aliases)
        if canonical == "detail_id":
            value = str(value or "").strip() or None
        else:
            value = _operator_clean_metadata_text(value)
        if value not in (None, ""):
            recovered[canonical] = value

    detail_url = _operator_nested_first(
        payload,
        ("detail_url", "detailUrl", "material_detail_url", "materialDetailUrl"),
    )
    if isinstance(detail_url, str) and "/creative/material/detail/" in detail_url:
        recovered["url"] = detail_url.strip()

    countries = _operator_nested_first(
        payload,
        ("countries", "country_list", "countryList", "country_codes", "countryCodes"),
    )
    if isinstance(countries, str):
        countries = [countries]
    if isinstance(countries, list) and countries:
        recovered["countries"] = countries

    return _operator_merge_detail_record(merged, recovered)


def _operator_merge_identity_from_videos(base, videos):
    """Merge identity recovered from downloaded-file sidecars."""
    merged = dict(base or {})
    for video in (videos or []):
        extra = {}
        for key in (
            "product_name", "product_name_source", "app_title",
            "package_name", "language", "source_media_url",
        ):
            value = (video or {}).get(key)
            if value not in (None, ""):
                extra[key] = value

        rel = str((video or {}).get("relative_path") or "").strip().replace(chr(92), "/")
        if rel and not merged.get("source_filename"):
            extra["source_filename"] = Path(rel).name

        merged = _operator_merge_detail_record(merged, extra)
    return merged


def _operator_enrich_detail_item(
    openapi,
    item,
):
    """
    Force the search result through the detail-page crawler before /crawl/items.

    Keyword search is only the discovery step.  Product/App/package/country
    metadata belongs to the detail stage, matching the original business
    storage contract.
    """
    url = str(
        (
            item
            or {}
        ).get(
            "url"
        )
        or ""
    ).strip()

    if not url:
        return (
            item,
            None,
            [],
        )

    try:
        url_path = (
            _operator_find_crawl_path(
                openapi,
                "url",
            )
        )

        url_payload = (
            _operator_fill_schema_payload(
                openapi,
                url_path,
                mode="url",
                detail_url=url,
                download_count=1,
                url_action="metadata_only",
            )
        )

        # Detail enrichment is metadata-only. The actual media download,
        # SHA256 dedupe and source-language detection happen exactly once via
        # /crawl/items below.
        for action_key in (
            "mode",
            "action",
            "operation",
            "crawl_mode",
        ):
            if action_key in url_payload:
                schema_prop = (
                    (
                        _operator_request_schema(
                            openapi,
                            url_path,
                        ).get(
                            "properties"
                        )
                        or {}
                    ).get(
                        action_key
                    )
                    or {}
                )

                selected_action = (
                    _operator_url_action_schema_value(
                        schema_prop,
                        "metadata_only",
                    )
                )

                if selected_action not in (
                    None,
                    "",
                ):
                    url_payload[
                        action_key
                    ] = selected_action

        for payload_key in list(
            url_payload.keys()
        ):
            lower_key = str(
                payload_key
            ).casefold()

            if lower_key in (
                "auto_download",
                "download",
                "download_media",
            ):
                url_payload[
                    payload_key
                ] = False

            elif lower_key == "download_cover":
                url_payload[
                    payload_key
                ] = False

            elif lower_key == "auto_detect_language":
                url_payload[
                    payload_key
                ] = False

            elif lower_key == "wait_ms":
                try:
                    detail_wait_ms = int(
                        os.getenv(
                            "OPERATOR_DETAIL_WAIT_MS",
                            "2500",
                        )
                    )
                except Exception:
                    detail_wait_ms = 2500

                url_payload[
                    payload_key
                ] = max(
                    1000,
                    min(
                        10000,
                        detail_wait_ms,
                    ),
                )

        try:
            detail_result = (
                _operator_internal_request(
                    "POST",
                    url_path,
                    json_payload=url_payload,
                    timeout=1800.0,
                )
            )
        except HTTPException as first_exc:
            if int(getattr(first_exc, "status_code", 0) or 0) != 422:
                raise
            request_schema = _operator_request_schema(openapi, url_path)
            required_fields = set(request_schema.get("required") or [])
            retry_payload = dict(url_payload)
            changed = False
            for action_key in ("mode", "action", "operation", "crawl_mode"):
                if action_key in retry_payload and action_key not in required_fields:
                    retry_payload.pop(action_key, None)
                    changed = True
            if not changed:
                raise
            detail_result = _operator_internal_request(
                "POST",
                url_path,
                json_payload=retry_payload,
                timeout=1800.0,
            )
            if isinstance(detail_result, dict):
                detail_result.setdefault(
                    "operator_detail_retry",
                    {"used": True, "reason": "metadata_action_422_retry_without_optional_action"},
                )

        detail_items = (
            _operator_extract_detail_items(
                detail_result
            )
        )

        merged = _operator_merge_identity_from_payload(
            item,
            detail_result,
        )

        target_detail_id = (
            _operator_detail_id_from_url(
                url
            )
            or _operator_detail_id_from_record(
                merged
            )
        )

        matching_candidates = []

        for candidate in detail_items:
            candidate_url = str(
                candidate.get(
                    "url"
                )
                or ""
            )

            candidate_detail_id = (
                candidate.get(
                    "detail_id"
                )
                or _operator_detail_id_from_url(
                    candidate_url
                )
            )

            if (
                candidate_url
                == url
                or (
                    target_detail_id
                    and candidate_detail_id
                    and str(
                        candidate_detail_id
                    )
                    == str(
                        target_detail_id
                    )
                )
            ):
                matching_candidates.append(
                    candidate
                )

        if not matching_candidates:
            matching_candidates = (
                detail_items
            )

        matching_candidates = sorted(
            matching_candidates,
            key=(
                _operator_detail_item_richness
            ),
        )

        for candidate in matching_candidates:
            merged = (
                _operator_merge_detail_item(
                    merged,
                    candidate,
                )
            )

        merged[
            "detail_enrichment_record_count"
        ] = len(
            matching_candidates
        )

        merged[
            "detail_enrichment_richness"
        ] = (
            _operator_detail_item_richness(
                merged
            )
        )

        direct_videos = [
            video
            for video in (
                _operator_extract_videos(
                    detail_result
                )
            )
            if _operator_source_video_ready(
                video
            )
        ]

        return (
            merged,
            detail_result,
            direct_videos,
        )

    except Exception as exc:
        # Preserve the search metadata and let /crawl/items make the final
        # determination.  The error is returned into the crawl report instead
        # of silently pretending detail enrichment succeeded.
        return (
            item,
            {
                "ok": False,
                "stage": (
                    "operator_detail_enrichment"
                ),
                "error": (
                    _operator_error_payload(
                        exc
                    )
                ),
            },
            [],
        )


def _operator_runtime_dependency_guard():
    required = (
        "_operator_auto_learn_product",
        "_operator_clean_product_label",
        "_operator_recover_review_video",
        "_operator_product_map_path",
        "_operator_load_product_map",
        "_operator_save_product_map",
        "_operator_product_from_app_title",
    )

    missing = [
        name
        for name in required
        if not callable(
            globals().get(
                name
            )
        )
    ]

    if missing:
        raise RuntimeError(
            "operator_runtime_dependency_missing:"
            + ",".join(
                missing
            )
        )

    return {
        "ok": True,
        "required": list(
            required
        ),
    }


def _operator_run_crawl(
    mode,
    *,
    detail_url=None,
    detail_urls=None,
    keyword=None,
    search_date_start=None,
    search_date_end=None,
    download_count=10,
    progress_callback=None,
    cancel_callback=None,
    video_callback=None,
):
    _operator_runtime_dependency_guard()

    openapi = (
        _operator_openapi()
    )

    path = (
        _operator_find_crawl_path(
            openapi,
            mode,
        )
    )

    requested_count = max(
        1,
        int(
            download_count
        ),
    )

    normalized_detail_urls, _ = _operator_parse_detail_urls(
        detail_urls if detail_urls is not None else detail_url
    )
    if mode == "url" and normalized_detail_urls:
        # URL mode processes one requested material per supplied detail page.
        # Keep the old download_count behavior for callers that only provide a
        # singular URL, while ensuring a batch is never truncated to one item.
        requested_count = max(requested_count, len(normalized_detail_urls))
    url_batch = mode == "url" and bool(normalized_detail_urls)

    # /crawl/search already performs the real Insight sort and returns an
    # explicit impression_desc_verified diagnostic. Request only the operator's
    # actual Top N instead of materializing 60 candidates on every small task.
    # _operator_rank_search_items still performs a local numeric DESC check.
    candidate_count = (
        requested_count
    )

    payload = (
        _operator_fill_schema_payload(
            openapi,
            path,
            mode=mode,
            detail_url=detail_url,
            detail_urls=normalized_detail_urls,
            keyword=keyword,
            search_date_start=search_date_start,
            search_date_end=search_date_end,
            download_count=(
                candidate_count
            ),
            url_action=(
                "download"
                if mode == "url"
                else None
            ),
        )
    )

    if progress_callback:
        progress_callback(
            0,
            int(
                download_count
            ),
            "searching",
        )

    if (
        cancel_callback
        and cancel_callback()
    ):
        raise _OperatorTaskCancelled(
            "cancelled_before_crawl"
        )

    result = (
        _operator_internal_request(
            "POST",
            path,
            json_payload=payload,
            timeout=1800.0,
        )
    )

    if (
        cancel_callback
        and cancel_callback()
    ):
        raise _OperatorTaskCancelled(
            "cancelled_after_search"
        )

    primary_videos = (
        _operator_extract_videos(
            result
        )
    )

    ready_primary = [
        video
        for video in primary_videos
        if _operator_source_video_ready(
            video
        )
    ]

    # A crawler result may already be fully archived.  It is safe to consume
    # only when it has reached the formal raw/<run>/<product>/<language>/ path.
    if (
        ready_primary
        and mode == "url"
        and (
            not url_batch
            or len(ready_primary) >= len(normalized_detail_urls)
        )
    ):
        videos = (
            ready_primary
            if url_batch
            else ready_primary[: int(download_count)]
        )

        if progress_callback:
            progress_callback(
                len(
                    videos
                ),
                int(
                    download_count
                ),
                "archived",
            )

        return {
            "primary_path": path,
            "primary_result": result,
            "detail_results": None,
            "download_result": None,
            "metadata_issues": [],
            "product_learning": [],
            "review_recovery": [],
            "ranking": None,
            "search_candidate_count": None,
            "videos": videos,
        }

    detail_items = (
        _operator_extract_detail_items(
            result
        )
    )

    if mode == "url" and normalized_detail_urls:
        # Some crawler responses omit a URL when its detail page could not be
        # enriched. Preserve every requested URL so /crawl/items still gets a
        # chance to acquire it and the task does not silently drop pasted rows.
        by_url = {
            str(item.get("url") or "").strip().casefold(): item
            for item in detail_items
            if isinstance(item, dict) and item.get("url")
        }
        ordered_detail_items = []
        for requested_url in normalized_detail_urls:
            ordered_detail_items.append(
                by_url.get(
                    requested_url.casefold(),
                    {
                        "url": requested_url,
                        "app_title": None,
                        "package_name": None,
                        "product_name": None,
                        "countries": [],
                        "language": None,
                        "material_type": "video",
                    },
                )
            )
        detail_items = ordered_detail_items

    detail_items = list(
        detail_items
        or []
    )

    ranking_audit = None

    if mode == "search":
        crawler_sort = (
            _operator_crawler_sort_diagnostic(
                result,
                request_payload=(
                    payload
                ),
                extracted_items=(
                    detail_items
                ),
            )
        )

        (
            detail_items,
            ranking_audit,
        ) = (
            _operator_rank_search_items(
                detail_items,
                requested_count,
                crawler_sort=(
                    crawler_sort
                ),
            )
        )
    else:
        detail_items = (
            detail_items[
                :requested_count
            ]
            if not url_batch
            else detail_items
        )

    detail_results = []
    download_results = []
    downloaded_videos = []
    metadata_issues = []
    product_learning_results = []
    review_recovery_results = []
    seen_paths = set()

    def emit_video(video):
        """Append one archived video and hand it to the processing pipeline.

        The callback is deliberately best-effort: acquisition remains the
        source of truth, while processing is allowed to run concurrently in a
        separate worker pool. A processing exception must never abort the
        crawler or prevent later downloads from being emitted.
        """
        # Respect the same Top-N/detail-page bound used by the final return;
        # otherwise a crawler response containing extra archived videos would
        # schedule work that the task will later discard.
        if len(downloaded_videos) >= requested_count:
            return
        downloaded_videos.append(video)
        if video_callback is not None:
            try:
                video_callback(dict(video))
            except Exception:
                # The task worker records per-item processing failures. Never
                # turn a callback/UI issue into a download failure.
                pass

    # Preserve already-compliant paths if the search endpoint returned some.
    for video in ready_primary:
        rel = str(
            video.get(
                "relative_path"
            )
            or ""
        )

        if (
            rel
            and rel.casefold()
            not in seen_paths
        ):
            seen_paths.add(
                rel.casefold()
            )

            emit_video(video)

    for index, original_item in enumerate(
        detail_items
    ):
        if (
            len(
                downloaded_videos
            )
            >= requested_count
            and not url_batch
        ):
            break

        if (
            cancel_callback
            and cancel_callback()
        ):
            raise _OperatorTaskCancelled(
                "cancelled_during_metadata_archive"
            )

        detail_item = dict(
            original_item
            or {}
        )

        detail_result = None
        direct_videos = []

        # Keyword discovery must always pass through a detail-page enrichment
        # step.  URL mode does it when the primary result did not already give
        # a compliant archived source.
        if (
            mode == "search"
            or not (
                detail_item.get(
                    "app_title"
                )
                or detail_item.get(
                    "package_name"
                )
                or detail_item.get(
                    "product_name"
                )
            )
        ):
            (
                detail_item,
                detail_result,
                direct_videos,
            ) = (
                _operator_enrich_detail_item(
                    openapi,
                    detail_item,
                )
            )

            detail_results.append(
                {
                    "url": (
                        detail_item.get(
                            "url"
                        )
                    ),
                    "result": (
                        detail_result
                    ),
                }
            )

        for video in direct_videos:
            video[
                "imp_estimate"
            ] = (
                detail_item.get(
                    "imp_estimate"
                )
            )

            video[
                "search_rank"
            ] = (
                detail_item.get(
                    "search_rank"
                )
            )

            rel = str(
                video.get(
                    "relative_path"
                )
                or ""
            )

            if (
                rel
                and rel.casefold()
                not in seen_paths
            ):
                seen_paths.add(
                    rel.casefold()
                )

                emit_video(video)

        if (
            len(
                downloaded_videos
            )
            >= requested_count
            and not url_batch
        ):
            break

        # Product map is a cache, not a whitelist. After the detail stage,
        # automatically learn a previously unseen package when Insight gives
        # an explicit product_name or app_title. Never guess from the package
        # string itself.
        (
            detail_item,
            product_learning,
        ) = (
            _operator_auto_learn_product(
                detail_item
            )
        )

        product_learning_results.append(
            product_learning
        )

        existing_archived = (
            _operator_existing_raw_video_for_item(
                detail_item
            )
        )

        if existing_archived:
            existing_archived[
                "imp_estimate"
            ] = (
                detail_item.get(
                    "imp_estimate"
                )
            )

            existing_archived[
                "search_rank"
            ] = (
                detail_item.get(
                    "search_rank"
                )
            )

            rel = str(
                existing_archived.get(
                    "relative_path"
                )
                or ""
            )

            if (
                rel
                and rel.casefold()
                not in seen_paths
            ):
                seen_paths.add(
                    rel.casefold()
                )

                emit_video(existing_archived)

            if progress_callback:
                progress_callback(
                    len(
                        downloaded_videos
                    ),
                    int(
                        download_count
                    ),
                    (
                        f"archive_cache_{index + 1}"
                    ),
                )

            continue

        # Always pass enriched metadata into the mature /crawl/items path.
        # The just-learned package mapping is already on disk before this call.
        items_result = (
            _operator_crawl_items(
                [
                    detail_item
                ]
            )
        )

        no_media = (
            _operator_no_media_diagnostic(
                items_result
            )
        )

        items_videos_initial = (
            _operator_extract_videos(
                items_result
                or {}
            )
        )

        detail_item = _operator_merge_identity_from_payload(
            detail_item,
            items_result or {},
        )
        detail_item = _operator_merge_identity_from_videos(
            detail_item,
            items_videos_initial,
        )
        detail_item, post_items_product_learning = _operator_auto_learn_product(
            detail_item
        )
        post_items_product_learning = dict(post_items_product_learning or {})
        post_items_product_learning["phase"] = "post_items_acquisition"
        product_learning_results.append(post_items_product_learning)

        silent_empty_items = (
            len(
                items_videos_initial
            )
            == 0
        )

        fallback_result = None

        if (
            no_media
            or silent_empty_items
        ):
            try:
                fallback_result = (
                    _operator_download_detail_url_fallback(
                        openapi,
                        detail_item,
                    )
                )
            except Exception as exc:
                fallback_result = {
                    "ok": False,
                    "stage": (
                        "operator_no_media_url_fallback"
                    ),
                    "error": (
                        _operator_error_payload(
                            exc
                        )
                    ),
                }

        if fallback_result is not None:
            fallback_detail_items = (
                _operator_extract_detail_items(
                    fallback_result
                    or {}
                )
            )

            target_detail_id = (
                detail_item.get(
                    "detail_id"
                )
                or _operator_detail_id_from_url(
                    detail_item.get(
                        "url"
                    )
                )
            )

            for fallback_detail in (
                fallback_detail_items
            ):
                fallback_detail_id = (
                    fallback_detail.get(
                        "detail_id"
                    )
                    or _operator_detail_id_from_url(
                        fallback_detail.get(
                            "url"
                        )
                    )
                )

                if (
                    not target_detail_id
                    or not fallback_detail_id
                    or str(
                        fallback_detail_id
                    )
                    == str(
                        target_detail_id
                    )
                ):
                    detail_item = (
                        _operator_merge_detail_item(
                            detail_item,
                            fallback_detail,
                        )
                    )

            download_results.append(
                {
                    "items_result": (
                        items_result
                    ),
                    "no_media_diagnostic": (
                        no_media
                    ),
                    "silent_empty_items": (
                        silent_empty_items
                    ),
                    "url_download_fallback": (
                        fallback_result
                    ),
                    "detail_item_after_fallback": {
                        "detail_id": (
                            detail_item.get(
                                "detail_id"
                            )
                        ),
                        "product_name": (
                            detail_item.get(
                                "product_name"
                            )
                        ),
                        "app_title": (
                            detail_item.get(
                                "app_title"
                            )
                        ),
                        "package_name": (
                            detail_item.get(
                                "package_name"
                            )
                        ),
                        "source_filename": (
                            detail_item.get(
                                "source_filename"
                            )
                        ),
                    },
                }
            )

            fallback_videos = (
                _operator_extract_videos(
                    fallback_result
                    or {}
                )
            )

            detail_item = _operator_merge_identity_from_payload(
                detail_item,
                fallback_result or {},
            )
            detail_item = _operator_merge_identity_from_videos(
                detail_item,
                fallback_videos,
            )
            detail_item, post_fallback_product_learning = _operator_auto_learn_product(
                detail_item
            )
            post_fallback_product_learning = dict(post_fallback_product_learning or {})
            post_fallback_product_learning["phase"] = "post_url_fallback_acquisition"
            product_learning_results.append(post_fallback_product_learning)

            one_result = (
                fallback_result
                if fallback_videos
                else items_result
            )
        else:
            download_results.append(
                items_result
            )

            one_result = (
                items_result
            )

        items_errors = (
            _operator_crawl_error_diagnostics(
                items_result
                or {}
            )
        )

        fallback_errors = (
            _operator_crawl_error_diagnostics(
                fallback_result
                or {}
            )
            if fallback_result is not None
            else []
        )

        detail_errors = (
            _operator_crawl_error_diagnostics(
                detail_result
                or {}
            )
            if detail_result is not None
            else []
        )

        one_videos = (
            _operator_extract_videos(
                one_result
                or {}
            )
        )

        recovered_videos = []
        recovered_sources = set()

        for candidate_video in (
            one_videos
        ):
            if _operator_source_video_ready(
                candidate_video
            ):
                continue

            rel = str(
                candidate_video.get(
                    "relative_path"
                )
                or ""
            ).replace(
                chr(
                    92
                ),
                "/",
            )

            if not rel.casefold().startswith(
                "review/"
            ):
                continue

            recovery = (
                _operator_recover_review_video(
                    candidate_video,
                    detail_item,
                )
            )

            review_recovery_results.append(
                recovery
            )

            if recovery.get(
                "recovered"
            ):
                recovered_sources.add(
                    rel
                )

            for recovered in (
                recovery.get(
                    "videos"
                )
                or []
            ):
                recovered[
                    "imp_estimate"
                ] = (
                    detail_item.get(
                        "imp_estimate"
                    )
                )

                recovered[
                    "search_rank"
                ] = (
                    detail_item.get(
                        "search_rank"
                    )
                )

                recovered_videos.append(
                    recovered
                )

        combined_videos = list(
            one_videos
        ) + list(
            recovered_videos
        )

        ready = [
            video
            for video in combined_videos
            if _operator_source_video_ready(
                video
            )
        ]

        unresolved = [
            video
            for video in one_videos
            if (
                not _operator_source_video_ready(
                    video
                )
                and str(
                    video.get(
                        "relative_path"
                    )
                    or ""
                ).replace(
                    chr(
                        92
                    ),
                    "/",
                )
                not in recovered_sources
            )
        ]

        for video in ready:
            video[
                "imp_estimate"
            ] = (
                detail_item.get(
                    "imp_estimate"
                )
            )

            video[
                "search_rank"
            ] = (
                detail_item.get(
                    "search_rank"
                )
            )

            rel = str(
                video.get(
                    "relative_path"
                )
                or ""
            )

            if (
                rel
                and rel.casefold()
                not in seen_paths
            ):
                seen_paths.add(
                    rel.casefold()
                )

                emit_video(video)

        if unresolved:
            for video in unresolved:
                metadata_issues.append(
                    {
                        "url": (
                            detail_item.get(
                                "url"
                            )
                        ),
                        "relative_path": (
                            video.get(
                                "relative_path"
                            )
                        ),
                        "product_name": (
                            video.get(
                                "product_name"
                            )
                        ),
                        "language": (
                            video.get(
                                "language"
                            )
                        ),
                        "package_name": (
                            video.get(
                                "package_name"
                            )
                            or detail_item.get(
                                "package_name"
                            )
                        ),
                        "app_title": (
                            video.get(
                                "app_title"
                            )
                            or detail_item.get(
                                "app_title"
                            )
                        ),
                        "archive_ready": False,
                        "detail_errors": (
                            detail_errors
                        ),
                        "items_errors": (
                            items_errors
                        ),
                        "fallback_errors": (
                            fallback_errors
                        ),
                        "items_mode": (
                            _operator_response_mode(
                                items_result
                            )
                        ),
                        "fallback_mode": (
                            _operator_response_mode(
                                fallback_result
                            )
                            if fallback_result is not None
                            else None
                        ),
                        "reason": (
                            "source_not_in_formal_raw_product_language_archive"
                        ),
                    }
                )

        if (
            not ready
            and not one_videos
        ):
            final_no_media = (
                _operator_no_media_diagnostic(
                    fallback_result
                    if fallback_result is not None
                    else items_result
                )
                or no_media
            )

            identity_missing = not any(
                [
                    detail_item.get(
                        "product_name"
                    ),
                    detail_item.get(
                        "app_title"
                    ),
                    detail_item.get(
                        "package_name"
                    ),
                    detail_item.get(
                        "source_filename"
                    ),
                ]
            )

            metadata_issues.append(
                {
                    "url": (
                        detail_item.get(
                            "url"
                        )
                    ),
                    "detail_id": (
                        detail_item.get(
                            "detail_id"
                        )
                        or _operator_detail_id_from_url(
                            detail_item.get(
                                "url"
                            )
                        )
                    ),
                    "product_name": (
                        detail_item.get(
                            "product_name"
                        )
                    ),
                    "app_title": (
                        detail_item.get(
                            "app_title"
                        )
                    ),
                    "package_name": (
                        detail_item.get(
                            "package_name"
                        )
                    ),
                    "language": (
                        detail_item.get(
                            "language"
                        )
                    ),
                    "source_filename": (
                        detail_item.get(
                            "source_filename"
                        )
                    ),
                    "detail_enrichment_record_count": (
                        detail_item.get(
                            "detail_enrichment_record_count"
                        )
                    ),
                    "detail_enrichment_richness": (
                        detail_item.get(
                            "detail_enrichment_richness"
                        )
                    ),
                    "silent_empty_items": (
                        silent_empty_items
                    ),
                    "crawler_error": (
                        (
                            final_no_media
                            or {}
                        ).get(
                            "error"
                        )
                    ),
                    "detail_errors": (
                        detail_errors
                    ),
                    "items_errors": (
                        items_errors
                    ),
                    "fallback_errors": (
                        fallback_errors
                    ),
                    "items_mode": (
                        _operator_response_mode(
                            items_result
                        )
                    ),
                    "fallback_mode": (
                        _operator_response_mode(
                            fallback_result
                        )
                        if fallback_result is not None
                        else None
                    ),
                    "reason": (
                        "detail_identity_metadata_missing_after_enrichment"
                        if identity_missing
                        else (
                            "no_downloadable_media_url"
                            if final_no_media
                            else "crawl_items_did_not_return_existing_formal_mp4"
                        )
                    ),
                }
            )

        if progress_callback:
            progress_callback(
                len(
                    downloaded_videos
                ),
                int(
                    download_count
                ),
                (
                    f"archiving_{index + 1}"
                ),
            )

    videos = downloaded_videos[
        :requested_count
    ]

    if not videos:
        missing_product_packages = sorted(
            {
                str(
                    issue.get(
                        "package_name"
                    )
                    or ""
                ).strip()
                for issue in metadata_issues
                if (
                    not issue.get(
                        "product_name"
                    )
                    and str(
                        issue.get(
                            "package_name"
                        )
                        or ""
                    ).strip()
                )
            }
        )

        missing_product_packages = [
            value
            for value in missing_product_packages
            if value
        ]

        language_unresolved = [
            issue
            for issue in metadata_issues
            if (
                issue.get(
                    "product_name"
                )
                and not issue.get(
                    "language"
                )
            )
        ]

        missing_identity_items = [
            issue
            for issue in metadata_issues
            if (
                issue.get(
                    "reason"
                )
                == "detail_identity_metadata_missing_after_enrichment"
            )
        ]

        if missing_identity_items:
            raise HTTPException(
                status_code=422,
                detail={
                    "stage": (
                        "operator_detail_metadata"
                    ),
                    "error": (
                        "detail_identity_metadata_missing"
                    ),
                    "message": (
                        "Insight returned a material detail URL, but the "
                        "Operator could not recover product/app/package/source-"
                        "filename metadata from search/detail payloads. "
                        "Language detection has not started yet."
                    ),
                    "metadata_issues": (
                        missing_identity_items[
                            :20
                        ]
                    ),
                },
            )

        if missing_product_packages:
            raise HTTPException(
                status_code=422,
                detail={
                    "stage": (
                        "operator_source_archive"
                    ),
                    "error": (
                        "product_identity_unresolved"
                    ),
                    "message": (
                        "Downloaded material could not enter the formal raw "
                        "archive because Insight detail metadata did not provide "
                        "a usable product/App name for package(s): "
                        + ", ".join(
                            missing_product_packages
                        )
                        + ". product_map.json is auto-learned and is no longer "
                        "a manual whitelist."
                    ),
                    "package_names": (
                        missing_product_packages
                    ),
                    "product_map_relative_path": (
                        "config/product_map.json"
                    ),
                    "metadata_issues": (
                        metadata_issues[
                            :20
                        ]
                    ),
                },
            )

        failed_review_recovery = [
            item
            for item in (
                review_recovery_results
            )
            if (
                item.get(
                    "attempted"
                )
                and not item.get(
                    "recovered"
                )
            )
        ]

        if failed_review_recovery:
            raise HTTPException(
                status_code=422,
                detail={
                    "stage": (
                        "operator_review_recovery"
                    ),
                    "error": (
                        "review_asset_recovery_failed"
                    ),
                    "message": (
                        "The media already existed in review/ from an earlier "
                        "test. Current product metadata was repaired, but the "
                        "existing review asset could not be promoted into the "
                        "formal raw archive."
                    ),
                    "review_recovery": (
                        failed_review_recovery[
                            :20
                        ]
                    ),
                    "metadata_issues": (
                        metadata_issues[
                            :20
                        ]
                    ),
                },
            )

        # A language can only be detected after a media file has been acquired.
        # A detail response with no downloadable URL must not be reported as a
        # speech-recognition failure merely because its metadata language is
        # also empty.
        media_acquisition_failures = [
            issue
            for issue in metadata_issues
            if (
                not issue.get("relative_path")
                and (
                    issue.get("reason") == "no_downloadable_media_url"
                    or issue.get("crawler_error")
                    or issue.get("detail_errors")
                    or issue.get("items_errors")
                    or issue.get("fallback_errors")
                )
            )
        ]

        if media_acquisition_failures:
            raise HTTPException(
                status_code=422,
                detail={
                    "stage": "operator_media_acquisition",
                    "error": "detail_or_media_download_failed",
                    "message": (
                        "The source video was not downloaded, so language "
                        "recognition did not run. Insight did not return a "
                        "downloadable media URL for this detail item."
                    ),
                    "metadata_issues": media_acquisition_failures[:20],
                },
            )

        if language_unresolved:
            raise HTTPException(
                status_code=422,
                detail={
                    "stage": (
                        "operator_source_archive"
                    ),
                    "error": (
                        "source_language_unresolved"
                    ),
                    "message": (
                        "Product metadata is available, but automatic source-"
                        "language detection did not promote the material to the "
                        "formal raw archive."
                    ),
                    "metadata_issues": (
                        metadata_issues[
                            :20
                        ]
                    ),
                },
            )

        downloaded_identity_failures = [
            issue
            for issue in metadata_issues
            if (
                issue.get("relative_path")
                and issue.get("language")
                and not issue.get("product_name")
            )
        ]

        if downloaded_identity_failures:
            raise HTTPException(
                status_code=422,
                detail={
                    "stage": "operator_product_identity",
                    "error": "product_identity_missing_after_detail_download",
                    "message": (
                        "The detail acquisition downloaded the source video and "
                        "detected its spoken language, but no explicit Insight "
                        "product/App/package identity could be recovered from the "
                        "search payload, detail response, download response or "
                        "downloaded-file metadata sidecar. The media must not be "
                        "downloaded again; fix the crawler detail identity parser."
                    ),
                    "metadata_issues": downloaded_identity_failures[:20],
                },
            )

        raise HTTPException(
            status_code=422,
            detail={
                "stage": "operator_source_archive",
                "error": "source_metadata_or_language_incomplete",
                "message": (
                    "No source video reached the required "
                    "raw/<run-minute>/<product>/<language>/<original-file> archive. "
                    "Product detail metadata and source-language detection must "
                    "finish before editing starts."
                ),
                "metadata_issues": (
                    metadata_issues[
                        :20
                    ]
                ),
            },
        )

    return {
        "primary_path": path,
        "primary_result": result,
        "detail_results": (
            detail_results
            if detail_results
            else None
        ),
        "download_result": (
            download_results
            if download_results
            else None
        ),
        "metadata_issues": (
            metadata_issues
        ),
        "product_learning": (
            product_learning_results
        ),
        "review_recovery": (
            review_recovery_results
        ),
        "ranking": (
            ranking_audit
        ),
        "search_candidate_count": (
            candidate_count
            if mode == "search"
            else None
        ),
        "videos": (
            videos
        ),
    }

def _operator_known_product_names():
    path = (
        WORKSPACE
        / "config"
        / "product_map.json"
    )

    values = []

    if path.is_file():
        try:
            payload = json.loads(
                path.read_text(
                    encoding="utf-8"
                )
            )

            def walk(
                value,
            ):
                if isinstance(
                    value,
                    dict,
                ):
                    for nested in (
                        value.values()
                    ):
                        walk(
                            nested
                        )
                    return

                if isinstance(
                    value,
                    list,
                ):
                    for nested in value:
                        walk(
                            nested
                        )
                    return

                if isinstance(
                    value,
                    str,
                ):
                    text = (
                        value.strip()
                    )

                    if (
                        text
                        and text not in values
                        and len(
                            text
                        )
                        <= 80
                    ):
                        values.append(
                            text
                        )

            walk(
                payload
            )
        except Exception:
            pass

    return values[
        :20
    ]


def _operator_sidecar_product(
    video_path,
):
    candidates = [
        video_path.with_suffix(
            ".metadata.json"
        ),
        Path(
            str(
                video_path
            )
            + ".metadata.json"
        ),
        video_path.parent
        / (
            video_path.stem
            + ".metadata.json"
        ),
    ]

    for path in candidates:
        if not path.is_file():
            continue

        try:
            payload = json.loads(
                path.read_text(
                    encoding="utf-8"
                )
            )
        except Exception:
            continue

        stack = [
            payload
        ]

        while stack:
            value = (
                stack.pop()
            )

            if isinstance(
                value,
                dict,
            ):
                product = (
                    value.get(
                        "product_name"
                    )
                    or value.get(
                        "product"
                    )
                )

                if product:
                    return str(
                        product
                    ).strip()

                stack.extend(
                    value.values()
                )

            elif isinstance(
                value,
                list,
            ):
                stack.extend(
                    value
                )

    return None


def _operator_brand_targets(
    video_relative_path,
    hinted_product=None,
):
    video_path = (
        _safe_workspace_path(
            video_relative_path
        )
    )

    values = []

    def add(
        value,
    ):
        text = str(
            value
            or ""
        ).strip()

        if (
            text
            and text.lower()
            not in {
                item.lower()
                for item in values
            }
        ):
            values.append(
                text
            )

    add(
        hinted_product
    )

    add(
        _operator_sidecar_product(
            video_path
        )
    )

    try:
        rel_parts = list(
            video_path
            .relative_to(
                WORKSPACE
            )
            .parts
        )

        # Typical:
        # raw/<run>/<product>/<language>/<file>
        if (
            len(
                rel_parts
            )
            >= 5
            and rel_parts[
                0
            ].lower()
            == "raw"
        ):
            add(
                rel_parts[
                    2
                ]
            )
    except Exception:
        pass

    if not values:
        for product in (
            _operator_known_product_names()
        ):
            add(
                product
            )

    return values[
        :12
    ]


def _operator_source_brand_detection_assets(source_context):
    """Resolve acquisition-time competitor icon/logo evidence for one source.

    The crawler writes a material-bound ``brand_profile`` with the raw video.
    Production detection consumes that same identity package so an animated or
    stylised watermark is not downgraded to OCR-only matching.
    """
    source_context = source_context or {}
    profile_rel = str(
        source_context.get("brand_profile_relative_path") or ""
    ).strip()
    fallback = {
        "brand_id": source_context.get("brand_id"),
        "icon_relative_path": None,
        "logo_relative_path": None,
        "profile_relative_path": profile_rel or None,
        "identity_source": source_context.get("brand_identity_source") or "unavailable",
        "template_ready": False,
        # Text identity remains useful to the OCR detector when a source icon
        # could not be acquired. Do not turn one missing bitmap into a blind
        # watermark scan.
        "product_name": source_context.get("product_name"),
        "app_title": source_context.get("app_title"),
    }
    if not profile_rel:
        return fallback
    try:
        _, profile = _read_json_workspace(
            profile_rel,
            "operator_source_brand_detection_assets",
        )
    except Exception:
        return fallback

    icon = profile.get("icon") or {}
    template_assets = (profile.get("templates") or {}).get("assets") or {}
    candidates = [
        icon.get("relative_path"),
        template_assets.get("icon-gray.png"),
        template_assets.get("icon.png"),
    ]
    icon_rel = None
    for candidate in candidates:
        candidate = str(candidate or "").strip()
        if not candidate:
            continue
        try:
            if _safe_workspace_path(candidate).is_file():
                icon_rel = candidate
                break
        except Exception:
            continue
    return {
        "brand_id": str(
            profile.get("brand_id")
            or source_context.get("brand_id")
            or ""
        ).strip() or None,
        "icon_relative_path": icon_rel,
        # The acquired app icon doubles as the source-logo template until a
        # dedicated wordmark template is registered for the same product.
        "logo_relative_path": icon_rel,
        "profile_relative_path": profile_rel,
        "identity_source": source_context.get("brand_identity_source") or "profile",
        "template_ready": bool(icon_rel),
        "product_name": profile.get("product_name") or source_context.get("product_name"),
        "app_title": profile.get("app_title") or source_context.get("app_title"),
    }


def _operator_select_profile():
    registry = (
        _load_replacement_registry()
    )

    profiles = list(
        registry.get(
            "profiles"
        )
        or []
    )

    if not profiles:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "operator_branding",
                "error": "brand_profile_not_configured",
                "message": (
                    "No brand replacement profile exists. "
                    "This is a one-time system configuration issue, "
                    "not a per-task operator field."
                ),
            },
        )

    if len(
        profiles
    ) == 1:
        return profiles[
            0
        ]

    for profile in profiles:
        profile_id = str(
            profile.get(
                "profile_id"
            )
            or ""
        ).lower()

        brand_name = str(
            profile.get(
                "brand_name"
            )
            or ""
        ).lower()

        if (
            "floatboat"
            in profile_id
            or "floatboat"
            in brand_name
        ):
            return profile

    return profiles[
        0
    ]


def _operator_brand_asset_state():
    try:
        profile = (
            _operator_select_profile()
        )

        validation = (
            _validate_brand_assets(
                profile
            )
        )

        return {
            "profile_id": (
                profile.get(
                    "profile_id"
                )
            ),
            "profile_name": (
                profile.get(
                    "brand_name"
                )
                or profile.get(
                    "product_name"
                )
            ),
            "ready": bool(
                (
                    validation.get(
                        "summary"
                    )
                    or {}
                ).get(
                    "top_brand_asset_ready"
                )
                and (
                    validation.get(
                        "summary"
                    )
                    or {}
                ).get(
                    "mid_promo_asset_ready"
                )
                and (
                    validation.get(
                        "summary"
                    )
                    or {}
                ).get(
                    "end_card_asset_ready"
                )
            ),
            "validation": (
                validation.get(
                    "summary"
                )
            ),
        }

    except Exception as exc:
        return {
            "profile_id": None,
            "profile_name": None,
            "ready": False,
            "error": (
                _operator_error_payload(
                    exc
                )
            ),
        }


def _operator_error_payload(
    exc,
):
    if isinstance(
        exc,
        HTTPException,
    ):
        return {
            "type": "HTTPException",
            "status_code": (
                exc.status_code
            ),
            "detail": (
                exc.detail
            ),
        }

    return {
        "type": (
            exc.__class__.__name__
        ),
        "message": str(
            exc
        )[:2000],
        "traceback_tail": (
            traceback.format_exc()[
                -5000:
            ]
        ),
    }


def _operator_output_folder_component(
    value,
    fallback,
):
    raw = str(
        value
        or ""
    ).strip()

    cleaned = "".join(
        "_"
        if (
            ch in '<>:"/\\\\|?*'
            or ord(
                ch
            )
            < 32
        )
        else ch
        for ch in raw
    ).strip(
        " ."
    )

    return (
        cleaned[
            :120
        ]
        or fallback
    )


def _operator_language_short(
    language,
    language_code=None,
):
    code = re.sub(
        r"[^A-Za-z]",
        "",
        str(
            language_code
            or ""
        ),
    ).upper()

    if 2 <= len(
        code
    ) <= 3:
        return code

    mapping = {
        "english": "EN",
        "spanish": "ES",
        "portuguese": "PT",
        "brazilian portuguese": "PT",
        "indonesian": "ID",
        "bahasa indonesia": "ID",
        "thai": "TH",
        "japanese": "JA",
        "korean": "KO",
        "french": "FR",
        "german": "DE",
        "italian": "IT",
        "turkish": "TR",
        "arabic": "AR",
        "vietnamese": "VI",
        "malay": "MS",
        "filipino": "TL",
        "tagalog": "TL",
        "hindi": "HI",
        "bengali": "BN",
        "russian": "RU",
        "chinese": "ZH",
        "traditional chinese": "ZH",
        "simplified chinese": "ZH",
    }

    key = str(
        language
        or ""
    ).strip().casefold()

    if key in mapping:
        return mapping[
            key
        ]

    letters = re.sub(
        r"[^A-Za-z]",
        "",
        str(
            language
            or ""
        ),
    ).upper()

    return (
        letters[
            :2
        ]
        if len(
            letters
        )
        >= 2
        else "XX"
    )


def _operator_profile_product_short(
    profile,
):
    for key in (
        "product_short_name",
        "brand_short_name",
        "short_name",
        "abbreviation",
        "product_abbreviation",
    ):
        value = re.sub(
            r"[^A-Za-z0-9]",
            "",
            str(
                profile.get(
                    key
                )
                or ""
            ),
        ).upper()

        if 1 <= len(
            value
        ) <= 10:
            return value

    profile_id = str(
        profile.get(
            "profile_id"
        )
        or ""
    )

    tokens = [
        token
        for token in re.findall(
            r"[A-Za-z0-9]+",
            profile_id,
        )
        if token
    ]

    for token in reversed(
        tokens
    ):
        # Skip generated hash suffixes.
        if re.fullmatch(
            r"[0-9a-fA-F]{8,}",
            token,
        ):
            continue

        if (
            token.isalpha()
            and 2 <= len(
                token
            ) <= 6
        ):
            return token.upper()

    product_name = str(
        profile.get(
            "product_name"
        )
        or profile.get(
            "brand_name"
        )
        or ""
    )

    words = re.findall(
        r"[A-Za-z0-9]+",
        product_name,
    )

    if len(
        words
    ) >= 2:
        initials = "".join(
            word[
                0
            ]
            for word in words[
                :5
            ]
            if word
        ).upper()

        if initials:
            return initials

    if words:
        return words[
            0
        ][
            :3
        ].upper()

    return "PRD"


def _operator_unique_processed_path(
    directory,
    base_stem,
):
    candidate = (
        directory
        / (
            base_stem
            + ".mp4"
        )
    )

    if not candidate.exists():
        return candidate

    for index in range(
        1,
        10000,
    ):
        candidate = (
            directory
            / (
                base_stem
                + "_"
                + str(
                    index
                ).zfill(
                    3
                )
                + ".mp4"
            )
        )

        if not candidate.exists():
            return candidate

    raise HTTPException(
        status_code=500,
        detail={
            "stage": "processed_layout",
            "error": "processed_filename_sequence_exhausted",
            "directory": str(
                directory
            ),
            "base_stem": (
                base_stem
            ),
        },
    )


def _operator_publish_processed_candidate(
    rendered_path,
    *,
    video_entry,
    profile,
    rendered,
    qc,
):
    """
    Business-facing editing output contract from the original Loop document:

        processed/<our-product>/<language>/
            <LANG>_<PRODUCT_SHORT>_video_<YYYYMMDD>[_NNN].mp4

    The branding renderer's output/branding_replacement_render/... file is an
    internal render artifact.  The Operator Console, review gate and Mintegral
    upload use the canonical processed/ path returned here.
    """
    source_context = (
        _operator_source_video_context(
            video_entry[
                "relative_path"
            ],
            video_entry.get(
                "product_name"
            ),
            video_entry.get(
                "language"
            ),
        )
    )

    language = (
        _operator_clean_metadata_text(
            source_context.get(
                "language"
            )
        )
    )

    if not language:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "processed_layout",
                "error": "source_language_required_for_processed_output",
                "source_video_relative_path": (
                    video_entry.get(
                        "relative_path"
                    )
                ),
            },
        )

    own_product = (
        _operator_clean_metadata_text(
            profile.get(
                "product_name"
            )
        )
        or _operator_clean_metadata_text(
            profile.get(
                "brand_name"
            )
        )
        or "Product"
    )

    own_product_short = (
        _operator_profile_product_short(
            profile
        )
    )

    language_short = (
        _operator_language_short(
            language,
            source_context.get(
                "language_code"
            ),
        )
    )

    product_dir = (
        _operator_output_folder_component(
            own_product,
            "Product",
        )
    )

    language_dir = (
        _operator_output_folder_component(
            language,
            "UnknownLanguage",
        )
    )

    out_dir = (
        WORKSPACE
        / "processed"
        / product_dir
        / language_dir
    )

    out_dir.mkdir(
        parents=True,
        exist_ok=True,
    )

    production_date = (
        _app_now()
        .strftime(
            "%Y%m%d"
        )
    )

    base_stem = (
        language_short
        + "_"
        + own_product_short
        + "_video_"
        + production_date
    )

    final_path = (
        _operator_unique_processed_path(
            out_dir,
            base_stem,
        )
    )

    # Prefer a hard link on the same workspace filesystem to avoid storing the
    # full MP4 twice.  Fall back to copy when the backing filesystem does not
    # support links.
    try:
        os.link(
            rendered_path,
            final_path,
        )

        storage_method = (
            "hardlink"
        )

    except Exception:
        shutil.copy2(
            rendered_path,
            final_path,
        )

        storage_method = (
            "copy"
        )

    final_md5 = (
        _local_file_md5(
            final_path
        )
    )

    sidecar_path = Path(
        str(
            final_path
        )
        + ".metadata.json"
    )

    sidecar_payload = {
        "schema_version": 1,
        "kind": "processed_creative",
        "created_at": (
            _app_now()
            .isoformat()
        ),
        "storage_contract": {
            "directory": (
                "processed/<our-product>/<language>/<file>"
            ),
            "filename": (
                "<LANG_SHORT>_<PRODUCT_SHORT>_video_<YYYYMMDD>[_NNN].mp4"
            ),
        },
        "source": {
            "relative_path": (
                video_entry.get(
                    "relative_path"
                )
            ),
            "competitor_product_name": (
                source_context.get(
                    "product_name"
                )
            ),
            "product_name_source": (
                source_context.get(
                    "product_name_source"
                )
            ),
            "language": (
                language
            ),
            "language_code": (
                source_context.get(
                    "language_code"
                )
            ),
            "language_source": (
                source_context.get(
                    "language_source"
                )
            ),
            "package_name": (
                source_context.get(
                    "package_name"
                )
            ),
            "app_title": (
                source_context.get(
                    "app_title"
                )
            ),
            "countries": (
                source_context.get(
                    "countries"
                )
                or []
            ),
            "sha256": (
                source_context.get(
                    "sha256"
                )
            ),
            "metadata_sidecar": (
                source_context.get(
                    "metadata_sidecar"
                )
            ),
        },
        "output": {
            "product_name": (
                own_product
            ),
            "product_short_name": (
                own_product_short
            ),
            "language": (
                language
            ),
            "language_short": (
                language_short
            ),
            "material_type": "video",
            "production_date": (
                production_date
            ),
            "filename": (
                final_path.name
            ),
            "relative_path": (
                final_path.relative_to(
                    WORKSPACE
                ).as_posix()
            ),
            "md5": (
                final_md5
            ),
            "storage_method": (
                storage_method
            ),
        },
        "branding": {
            "profile_id": (
                profile.get(
                    "profile_id"
                )
            ),
            "brand_name": (
                profile.get(
                    "brand_name"
                )
            ),
        },
        "render": {
            "engine_output_relative_path": (
                rendered_path.relative_to(
                    WORKSPACE
                ).as_posix()
            ),
            "render_report_relative_path": (
                rendered.get(
                    "report_relative_path"
                )
            ),
            "renderer_version": (
                rendered.get(
                    "version"
                )
            ),
            "production_qc": (
                qc
            ),
        },
    }

    _atomic_write_json(
        sidecar_path,
        sidecar_payload,
    )

    return {
        "processed_video_relative_path": (
            final_path.relative_to(
                WORKSPACE
            ).as_posix()
        ),
        "processed_metadata_sidecar": (
            sidecar_path.relative_to(
                WORKSPACE
            ).as_posix()
        ),
        "processed_local_md5": (
            final_md5
        ),
        "output_product_name": (
            own_product
        ),
        "output_product_short_name": (
            own_product_short
        ),
        "output_language": (
            language
        ),
        "output_language_short": (
            language_short
        ),
        "output_material_type": (
            "video"
        ),
        "renderer_internal_video_relative_path": (
            rendered_path.relative_to(
                WORKSPACE
            ).as_posix()
        ),
    }


def _operator_detect_end_card_start(
    video_path,
    duration,
    fallback_start,
    *,
    search_seconds=7.0,
    interval_seconds=0.20,
    fps=None,
    guard_frames=0,
):
    """Tighten a terminal-card cut using adjacent-frame scene changes.

    Semantic/OCR routing is intentionally coarse.  For the actual destructive
    cut we sample the final seconds sequentially and pick the first sustained
    hard transition near the proposed terminal-card boundary.  The fallback is
    retained whenever no robust visual boundary can be demonstrated.
    """
    duration = max(0.0, float(duration or 0.0))
    fallback = max(0.0, min(duration, float(fallback_start or duration)))
    try:
        resolved_fps = float(fps or 0.0)
    except Exception:
        resolved_fps = 0.0
    if resolved_fps <= 1e-6:
        resolved_fps = 30.0
    try:
        safe_guard_frames = max(0, int(guard_frames or 0))
    except Exception:
        safe_guard_frames = 0
    guard_seconds = safe_guard_frames / resolved_fps
    guarded_fallback = max(0.0, fallback - guard_seconds)
    if duration <= 0.5:
        return {
            "start_seconds": round(guarded_fallback, 3),
            "source": "fallback_duration_unavailable",
            "confidence": 0.0,
            "terminal_guard_frames": safe_guard_frames,
            "terminal_guard_seconds": round(guard_seconds, 6),
        }

    start = max(0.0, min(fallback, duration - 0.25) - max(1.0, float(search_seconds)))
    cap = cv2.VideoCapture(str(video_path))
    if not cap.isOpened():
        return {
            "start_seconds": round(guarded_fallback, 3),
            "source": "fallback_video_unreadable",
            "confidence": 0.0,
            "terminal_guard_frames": safe_guard_frames,
            "terminal_guard_seconds": round(guard_seconds, 6),
        }

    samples = []
    try:
        # Seek only once, then decode forward. Re-seeking for every 50ms sample
        # turns a short terminal scan into hundreds of random decoder seeks and
        # can make the render appear stalled after visual-base output.
        cap.set(cv2.CAP_PROP_POS_MSEC, start * 1000.0)
        source_fps = float(cap.get(cv2.CAP_PROP_FPS) or resolved_fps)
        if source_fps <= 1e-6:
            source_fps = resolved_fps
        sample_stride = max(
            1,
            int(round(max(0.03, float(interval_seconds)) * source_fps)),
        )
        decoded_frames = 0
        while True:
            ok, frame = cap.read()
            if not ok or frame is None:
                break
            t = start + decoded_frames / source_fps
            if t > duration - 0.02:
                break
            if decoded_frames % sample_stride == 0:
                thumb = cv2.resize(frame, (96, 170), interpolation=cv2.INTER_AREA)
                gray = cv2.cvtColor(thumb, cv2.COLOR_BGR2GRAY)
                samples.append((float(t), gray))
            decoded_frames += 1
    finally:
        cap.release()

    candidates = []
    for (left_t, left), (right_t, right) in zip(samples[:-1], samples[1:]):
        diff = float(cv2.absdiff(left, right).mean()) / 255.0
        # Weight proximity to the semantic starting point so an unrelated cut
        # elsewhere in the final search window cannot replace source footage.
        distance = abs(right_t - fallback)
        proximity = max(0.0, 1.0 - distance / max(1.0, float(search_seconds)))
        score = diff * (0.55 + 0.45 * proximity)
        if diff >= 0.105:
            candidates.append((score, right_t, diff, proximity))

    if not candidates:
        return {
            "start_seconds": round(guarded_fallback, 3),
            "source": "semantic_fallback_no_visual_boundary",
            "confidence": 0.0,
            "terminal_guard_frames": safe_guard_frames,
            "terminal_guard_seconds": round(guard_seconds, 6),
            "scan_interval_seconds": round(max(0.03, float(interval_seconds)), 6),
        }

    _, candidate_t, diff, proximity = max(candidates, key=lambda value: value[0])
    # Prefer a cut on/before the semantic onset.  A terminal logo/name may fade
    # in several frames before the strongest scene-change sample.  The old
    # fixed 50ms preroll was smaller than the 200ms sampling cadence and leaked
    # those frames.  Production now samples at 50ms and uses an explicit
    # frame-rate-aware terminal guard, recorded below for auditability.
    detected_start = min(fallback, candidate_t)
    refined = max(0.0, detected_start - guard_seconds)
    return {
        "start_seconds": round(refined, 3),
        "source": "terminal_visual_transition",
        "confidence": round(min(1.0, diff * 3.8) * (0.70 + 0.30 * proximity), 4),
        "semantic_start_seconds": round(fallback, 3),
        "candidate_transition_seconds": round(candidate_t, 3),
        "detected_start_seconds": round(detected_start, 3),
        "terminal_guard_frames": safe_guard_frames,
        "terminal_guard_seconds": round(guard_seconds, 6),
        "scan_interval_seconds": round(max(0.03, float(interval_seconds)), 6),
        "frame_difference": round(diff, 5),
    }


def _operator_brand_assets_preflight(
    profile,
    *,
    language=None,
    language_code=None,
):
    validation = (
        _validate_brand_assets(
            profile,
            language=language,
            language_code=language_code,
        )
    )

    summary = (
        validation.get(
            "summary"
        )
        or {}
    )

    missing = []
    invalid_visual_assets = []

    if not bool(
        summary.get(
            "top_brand_asset_ready"
        )
    ):
        missing.append(
            "logo.png or icon.png"
        )

    if not bool(
        summary.get(
            "mid_promo_asset_ready"
        )
    ):
        missing.append(
            "mid-promo.mp4"
        )
        selected = validation.get("selected_mid_promo_validation") or {}
        if selected.get("error"):
            invalid_visual_assets.append(
                {
                    "asset": "mid-promo.mp4",
                    "relative_path": selected.get("relative_path"),
                    "error": selected.get("error"),
                    "visual_integrity": selected.get("visual_integrity"),
                }
            )

    if not bool(
        summary.get(
            "end_card_asset_ready"
        )
    ):
        missing.append(
            "end-card.mp4 or end-card.png"
        )
        selected = validation.get("selected_end_card_validation") or {}
        if selected.get("error"):
            invalid_visual_assets.append(
                {
                    "asset": "end-card.mp4 or end-card.png",
                    "relative_path": selected.get("relative_path"),
                    "error": selected.get("error"),
                    "visual_integrity": selected.get("visual_integrity"),
                }
            )

    if missing:
        discovery = (
            validation.get(
                "autodiscovery"
            )
            or {}
        )

        raise HTTPException(
            status_code=422,
            detail={
                "stage": "operator_brand_assets_preflight",
                "error": "required_brand_assets_missing",
                "profile_id": (
                    profile.get(
                        "profile_id"
                    )
                ),
                "profile_name": (
                    profile.get(
                        "brand_name"
                    )
                    or profile.get(
                        "product_name"
                    )
                ),
                "asset_directory": (
                    discovery.get(
                        "asset_directory_relative_path"
                    )
                ),
                "missing": (
                    missing
                ),
                "validation": (
                    summary
                ),
                "invalid_visual_assets": invalid_visual_assets,
                "message": (
                    "Required brand assets are missing or visually invalid. "
                    "Use language-specific files such as mid-promo.en.mp4 / "
                    "end-card.en.mp4, or the default mid-promo.mp4 / end-card.mp4 "
                    "fallback in the resolved brand asset folder."
                ),
            },
        )

    return validation


def _operator_render_preset():
    value = str(
        os.getenv(
            "OPERATOR_RENDER_PRESET",
            "veryfast",
        )
        or "medium"
    ).strip().casefold()

    allowed = {
        "ultrafast",
        "superfast",
        "veryfast",
        "faster",
        "fast",
        "medium",
        "slow",
        "slower",
        "veryslow",
    }

    if value not in allowed:
        return "veryfast"

    return value



def _operator_render_crf():
    try:
        value = int(os.getenv("OPERATOR_RENDER_CRF", "17"))
    except Exception:
        value = 17
    return max(15, min(23, value))


def _operator_semantic_sample_interval():
    try:
        value = float(
            os.getenv(
                "OPERATOR_SEMANTIC_SAMPLE_INTERVAL_SECONDS",
                "3.0",
            )
        )
    except Exception:
        value = 2.0

    return max(
        1.0,
        min(
            5.0,
            value,
        ),
    )


def _operator_semantic_max_samples():
    try:
        value = int(
            os.getenv(
                "OPERATOR_SEMANTIC_MAX_SAMPLES",
                "60",
            )
        )
    except Exception:
        value = 120

    return max(
        30,
        min(
            900,
            value,
        ),
    )


def _operator_semantic_whisper_enabled():
    return str(
        os.getenv("OPERATOR_SEMANTIC_WHISPER_ENABLED", "true")
    ).strip().casefold() not in {"0", "false", "no", "off"}


def _operator_semantic_whisper_start_timeout_seconds():
    try:
        value = int(os.getenv("OPERATOR_SEMANTIC_WHISPER_MAX_START_SECONDS", "15"))
    except Exception:
        value = 15
    return max(5, min(45, value))


def _operator_semantic_router_fingerprint(router):
    """Fingerprint only router evidence consumed by semantic classification.

    Router reports contain run-specific output paths and timestamps, so hashing
    their raw JSON would defeat reuse for an unchanged source.  The semantic
    scorer only reads the two layer families normalized below; this compact,
    deterministic projection invalidates the cache when relevant evidence
    changes without turning every new report file into a cache miss.
    """
    relevant = []
    for layer in (router or {}).get("watermark_layers") or []:
        layer_type = str(layer.get("type") or "")
        if layer_type not in {"unclassified_brand_text", "end_card"}:
            continue
        evidence = layer.get("evidence") or {}
        relevant.append(
            {
                "type": layer_type,
                "confidence": round(float(layer.get("confidence") or 0.0), 6),
                "time_min_seconds": evidence.get("time_min_seconds"),
                "time_max_seconds": evidence.get("time_max_seconds"),
            }
        )
    relevant.sort(
        key=lambda item: (
            item["type"],
            item["time_min_seconds"] is None,
            item["time_min_seconds"] or 0.0,
            item["time_max_seconds"] is None,
            item["time_max_seconds"] or 0.0,
            item["confidence"],
        )
    )
    import hashlib

    return hashlib.sha256(
        json.dumps(
            relevant,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()


def _operator_semantic_cache_identity(
    source_context,
    router=None,
):
    source_identity = str(
        (
            source_context
            or {}
        ).get(
            "sha256"
        )
        or ""
    ).strip().casefold()

    if not source_identity:
        relative_path = str(
            (
                source_context
                or {}
            ).get(
                "relative_path"
            )
            or ""
        ).strip()

        if not relative_path:
            return None

        try:
            source_identity = (
                _sha256_file(
                    _safe_workspace_path(
                        relative_path
                    )
                )
                .casefold()
            )
        except Exception:
            return None

    # Semantics consume both source frames and router evidence.  Include the
    # effective analysis configuration so a more precise request never reuses
    # a report generated with a different sampling or Whisper policy.
    router_identity = _operator_semantic_router_fingerprint(router)
    source_language_code = str(
        (source_context or {}).get("language_code") or ""
    ).strip().casefold()
    source_language_name = str(
        (source_context or {}).get("language") or ""
    ).strip().casefold()
    whisper_translation_enabled = not (
        source_language_code in {"en", "eng"}
        or source_language_name in {"english", "en", "eng"}
    )

    import hashlib

    payload = {
        "cache_schema": "v018110-semantic-inputs1",
        "source_sha256": source_identity,
        "router_sha256": router_identity,
        "sample_interval_seconds": _operator_semantic_sample_interval(),
        "max_samples": _operator_semantic_max_samples(),
        "whisper_enabled": _operator_semantic_whisper_enabled(),
        "whisper_translation_enabled": whisper_translation_enabled,
        "whisper_model": str(
            os.getenv("OPERATOR_SEMANTIC_WHISPER_MODEL") or "base"
        ).strip(),
    }
    return hashlib.sha256(
        json.dumps(
            payload,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()


def _operator_semantic_cache_path(
    source_context,
    router=None,
):
    identity = (
        _operator_semantic_cache_identity(
            source_context,
            router,
        )
    )

    if not identity:
        return None

    return (
        WORKSPACE
        / "output"
        / "operator_cache"
        / "semantic"
        / (
            identity
            + ".v018110-inputs1.json"
        )
    )


def _operator_semantic_cache_load(
    source_context,
    router,
):
    path = (
        _operator_semantic_cache_path(
            source_context,
            router,
        )
    )

    if (
        path is None
        or not path.is_file()
    ):
        return None

    try:
        payload = json.loads(
            path.read_text(
                encoding="utf-8"
            )
        )
    except Exception:
        return None

    cache_meta = (
        payload.get(
            "_operator_semantic_cache"
        )
        or {}
    )

    if (
        cache_meta.get(
            "version"
        )
        != "v018110-semantic-inputs1"
    ):
        return None

    if (
        payload.get(
            "mode"
        )
        != "branding_semantic_structure_census"
    ):
        return None

    identity = (
        _operator_semantic_cache_identity(
            source_context,
            router,
        )
    )

    if (
        not identity
        or str(
            cache_meta.get(
                "cache_identity"
            )
            or ""
        ).casefold()
        != identity
    ):
        return None

    source = payload.setdefault(
        "source",
        {},
    )

    source[
        "relative_path"
    ] = (
        source_context.get(
            "relative_path"
        )
    )

    source[
        "router_report_relative_path"
    ] = (
        router.get(
            "report_relative_path"
        )
    )

    cache_rel = (
        path.relative_to(
            WORKSPACE
        )
        .as_posix()
    )

    payload[
        "report_relative_path"
    ] = cache_rel

    payload[
        "_operator_semantic_cache"
    ][
        "hit"
    ] = True

    try:
        path.write_text(
            json.dumps(
                payload,
                ensure_ascii=False,
                indent=2,
            ),
            encoding="utf-8",
        )
    except Exception:
        pass

    return payload


def _operator_semantic_cache_store(
    semantic,
    source_context,
    router,
):
    path = (
        _operator_semantic_cache_path(
            source_context,
            router,
        )
    )

    identity = (
        _operator_semantic_cache_identity(
            source_context,
            router,
        )
    )

    if (
        path is None
        or not identity
        or not isinstance(
            semantic,
            dict,
        )
    ):
        return semantic

    # JSON round-trip gives us an independent serializable copy.
    try:
        cached = json.loads(
            json.dumps(
                semantic,
                ensure_ascii=False,
            )
        )
    except Exception:
        return semantic

    path.parent.mkdir(
        parents=True,
        exist_ok=True,
    )

    cache_rel = (
        path.relative_to(
            WORKSPACE
        )
        .as_posix()
    )

    source = cached.setdefault(
        "source",
        {},
    )

    source[
        "relative_path"
    ] = (
        source_context.get(
            "relative_path"
        )
    )

    source[
        "router_report_relative_path"
    ] = (
        router.get(
            "report_relative_path"
        )
    )

    cached[
        "report_relative_path"
    ] = cache_rel

    cached[
        "_operator_semantic_cache"
    ] = {
        "version": "v018110-semantic-inputs1",
        "cache_identity": (
            identity
        ),
        "source_sha256": str(
            (source_context or {}).get("sha256") or ""
        ).casefold(),
        "router_report_relative_path": str(
            (router or {}).get("report_relative_path") or ""
        ),
        "router_evidence_fingerprint": _operator_semantic_router_fingerprint(
            router
        ),
        "sample_interval_seconds": (
            _operator_semantic_sample_interval()
        ),
        "max_samples": (
            _operator_semantic_max_samples()
        ),
        "hit": False,
        "created_at": (
            _app_now()
            .isoformat()
        ),
    }

    try:
        path.write_text(
            json.dumps(
                cached,
                ensure_ascii=False,
                indent=2,
            ),
            encoding="utf-8",
        )
    except Exception:
        return semantic

    return cached


def _operator_video_duration_from_reports(
    census,
    router,
):
    for payload in (
        census,
        router,
    ):
        video = (
            (
                payload
                or {}
            ).get(
                "video"
            )
            or {}
        )

        try:
            value = float(
                video.get(
                    "duration_seconds"
                )
                or 0.0
            )
        except Exception:
            value = 0.0

        if value > 0:
            return value

    return 0.0


def _operator_route_layers_of_type(
    router,
    layer_type,
):
    return [
        layer
        for layer in (
            (
                router
                or {}
            ).get(
                "watermark_layers"
            )
            or []
        )
        if str(
            layer.get(
                "type"
            )
            or ""
        )
        == str(
            layer_type
        )
    ]



def _operator_midpromo_actions(plan):
    return [
        a for a in ((plan or {}).get("actions") or [])
        if a.get("type") == "mid_promo_replace"
    ]


def _operator_midpromo_user_boundary_override(plan, profile, source_context):
    """Use a user-confirmed boundary only for the matching source SHA-256."""
    if _operator_midpromo_actions(plan):
        return {"used": False, "reason": "midpromo_action_already_present", "action_added": False}

    source_sha256 = str((source_context or {}).get("sha256") or "").casefold()
    source_rel = str((source_context or {}).get("relative_path") or "")
    if not source_sha256 or not source_rel:
        return {"used": False, "reason": "source_identity_missing", "action_added": False}

    path = WORKSPACE / "config" / "midpromo_boundary_overrides.json"
    try:
        payload = json.loads(path.read_text(encoding="utf-8")) if path.is_file() else {}
    except Exception:
        payload = {}

    entry = next(
        (
            item for item in (payload.get("entries") or [])
            if isinstance(item, dict)
            and str(item.get("source_sha256") or "").casefold() == source_sha256
        ),
        None,
    )
    if not entry:
        return {"used": False, "reason": "no_user_boundary_override", "action_added": False}

    try:
        start = float(entry["start_seconds"])
        end = float(entry["end_seconds"])
        duration = float(_probe_media(_safe_workspace_path(source_rel)).get("duration_seconds") or 0.0)
    except Exception:
        return {"used": False, "reason": "invalid_user_boundary_override", "action_added": False}

    if not (0.0 <= start < end <= duration and 4.0 <= end - start <= 40.0):
        return {"used": False, "reason": "user_boundary_out_of_range", "action_added": False}

    assets = (profile or {}).get("assets") or {}
    mid_asset = (
        assets.get("mid_promo_video_relative_path")
        or (profile or {}).get("mid_promo_asset_relative_path")
        or (profile or {}).get("mid_promo_relative_path")
    )
    if not mid_asset:
        return {"used": False, "reason": "midpromo_asset_unavailable", "action_added": False}

    plan.setdefault("actions", []).append(
        {
            "action_id": "operator-midpromo-user-confirmed-boundary",
            "type": "mid_promo_replace",
            "status": "AUTO",
            "handler": "replace_mid_segment",
            "start_seconds": round(start, 3),
            "end_seconds": round(end, 3),
            "strategy": "user_confirmed_midpromo_boundary_replace",
            "decision_source": "user_review_confirmed_boundary",
            "replacement_content": {
                "mid_promo_video_relative_path": mid_asset,
                "generated_product_name": (profile or {}).get("product_name"),
            },
            "source_candidate": {
                "type": "mid_promo_candidate",
                "boundary_ready": True,
                "source_sha256": source_sha256,
                "user_confirmed": True,
                "reason": str(entry.get("reason") or ""),
                "override_config_relative_path": "config/midpromo_boundary_overrides.json",
            },
        }
    )
    return {
        "used": True,
        "reason": "user_confirmed_midpromo_boundary_applied",
        "action_added": True,
        "selected_segment": {"start_seconds": start, "end_seconds": end},
        "override_config_relative_path": "config/midpromo_boundary_overrides.json",
    }


def _operator_midpromo_fullscreen_insert_fallback(plan, profile, source_context, semantic=None):
    """Create a REVIEW-only action for a generic full-screen interruption."""
    if _operator_midpromo_actions(plan):
        return {"used": False, "reason": "midpromo_action_already_present", "action_added": False}
    source_rel = str((source_context or {}).get("relative_path") or "")
    if not source_rel:
        return {"used": False, "reason": "source_path_missing", "action_added": False}
    video_path = _safe_workspace_path(source_rel)
    duration = float(_probe_media(video_path).get("duration_seconds") or 0.0)
    if duration <= 0.0:
        return {"used": False, "reason": "source_duration_unavailable", "action_added": False}

    started = time.monotonic()
    scan = _fullscreen_promo_scan(
        video_path,
        duration,
        sample_interval_seconds=0.50,
        semantic_report=semantic,
    )
    report_dir = WORKSPACE / "review" / "fullscreen_promo_detection" / _app_now().strftime("%Y-%m-%d_%H%M%S") / video_path.stem
    report_dir.mkdir(parents=True, exist_ok=True)
    report_path = report_dir / f"{video_path.stem}.fullscreen-promo-detection.json"
    report_path.write_text(
        json.dumps(
            {
                "ok": True,
                "version": "1.0",
                "mode": "fullscreen_promo_detection",
                "source": {"relative_path": source_rel, "sha256": (source_context or {}).get("sha256")},
                "policy": {
                    "decision": "Candidate requires a sustained full-screen visual regime plus hard scene cuts on both sides.",
                    "non_semantic": "No product, language, or CTA identity is inferred.",
                    "safety": "Generic candidates become REVIEW actions and keep the existing human review gate.",
                },
                "detector": {
                    "sample_interval_seconds": 0.50,
                    "visual_score_threshold": 0.66,
                    "minimum_balanced_grid_lines": 3,
                    "scene_cut_threshold": 0.45,
                },
                "elapsed_seconds": round(time.monotonic() - started, 3),
                "sample_count": len(scan.get("samples") or []),
                "scene_cut_count": len(scan.get("scene_cuts") or []),
                "semantic_anchors": scan.get("semantic_anchors") or [],
                "candidates": scan.get("candidates") or [],
            },
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )
    report_rel = report_path.relative_to(WORKSPACE).as_posix()
    candidates = scan.get("candidates") or []
    if not candidates:
        return {
            "used": True,
            "reason": "no_scene_bounded_fullscreen_insert_candidate",
            "action_added": False,
            "candidate_count": 0,
            "report_relative_path": report_rel,
            # Keep this in-memory only: it is an optimization hand-off for the
            # immediately following fallback, not durable decision evidence.
            "scene_cuts": scan.get("scene_cuts") or [],
            "scene_cut_interval_seconds": 0.50,
        }

    assets = (profile or {}).get("assets") or {}
    mid_asset = assets.get("mid_promo_video_relative_path") or (profile or {}).get("mid_promo_asset_relative_path") or (profile or {}).get("mid_promo_relative_path")
    if not mid_asset:
        return {"used": True, "reason": "midpromo_asset_unavailable", "action_added": False, "candidate_count": len(candidates), "report_relative_path": report_rel}

    # This detector is intentionally generalized. It may conservatively include
    # a final title/CTA beat; expose that uncertainty as REVIEW-only, never as a
    # silent automatic replacement. Exact user-confirmed boundaries still take
    # precedence for the immutable source they describe.
    selected = candidates[0]
    plan.setdefault("actions", []).append(
        {
            "action_id": "operator-midpromo-fullscreen-insert-fallback",
            "type": "mid_promo_replace",
            "status": "REVIEW",
            "handler": "replace_mid_segment",
            "start_seconds": selected["start_seconds"],
            "end_seconds": selected["end_seconds"],
            "strategy": "scene_bounded_fullscreen_insert_replace",
            "decision_source": "fullscreen_visual_regime_plus_scene_cuts",
            "replacement_content": {"mid_promo_video_relative_path": mid_asset, "generated_product_name": (profile or {}).get("product_name")},
            "source_candidate": {"type": "mid_promo_candidate", "fallback": True, "boundary_ready": True, "requires_human_review": True, "fullscreen_detection_report_relative_path": report_rel, "fullscreen_visual_regime": selected},
        }
    )
    return {"used": True, "reason": "scene_bounded_fullscreen_insert_candidate_added_for_review", "action_added": True, "candidate_count": len(candidates), "selected_segment": selected, "elapsed_seconds": round(time.monotonic() - started, 3), "report_relative_path": report_rel}


def _operator_midpromo_semantic_activity_fallback(
    plan,
    profile,
    semantic,
    *,
    scene_cuts=None,
):
    """Recover an interstitial from visual overlay activity plus scene cuts.

    Full-screen trailers can make both OCR text and Whisper unreliable.  The
    semantic census still records the independent non-narrative overlay activity
    regime, which becomes sufficient only when bounded by hard cuts on both
    sides.  This preserves the no-guessing rule while covering the specific
    failure mode where the router has no brand-text anchor at all.
    """
    if _operator_midpromo_actions(plan):
        return {
            "used": False,
            "reason": "midpromo_action_already_present",
            "action_added": False,
            "candidate_count": len(_operator_midpromo_actions(plan)),
            "report_relative_path": (semantic or {}).get("report_relative_path"),
        }

    source = (semantic or {}).get("source") or {}
    source_rel = source.get("relative_path")
    if not source_rel:
        return {
            "used": True,
            "reason": "semantic_source_missing",
            "action_added": False,
            "candidate_count": 0,
            "report_relative_path": (semantic or {}).get("report_relative_path"),
        }

    points = []
    for sample in (semantic or {}).get("samples") or []:
        if not isinstance(sample, dict):
            continue
        try:
            timestamp = float(sample.get("time_seconds"))
            activity = float(
                (sample.get("text_layer_activity") or {}).get("promo_overlay_activity")
                or 0.0
            )
        except Exception:
            continue
        if activity >= 0.55:
            points.append((timestamp, activity))

    if len(points) < 2:
        return {
            "used": True,
            "reason": "no_sustained_semantic_overlay_activity",
            "action_added": False,
            "candidate_count": 0,
            "report_relative_path": (semantic or {}).get("report_relative_path"),
        }

    groups = []
    current = [points[0]]
    for point in points[1:]:
        if point[0] - current[-1][0] <= 3.25:
            current.append(point)
        else:
            groups.append(current)
            current = [point]
    groups.append(current)

    video_path = _safe_workspace_path(source_rel)
    media = _probe_media(video_path)
    duration = float(media.get("duration_seconds") or 0.0)
    if duration <= 0:
        return {
            "used": True,
            "reason": "semantic_source_duration_unavailable",
            "action_added": False,
            "candidate_count": 0,
            "report_relative_path": (semantic or {}).get("report_relative_path"),
        }
    # Fullscreen fallback has already made a sequential visual pass at 0.5 s.
    # Its scene cuts are sufficient for this 0.30 threshold and avoid reopening
    # and randomly seeking across the whole source a second time.  Preserve the
    # legacy 0.25 s scan when no compatible in-memory hand-off is available.
    cuts = list(scene_cuts or [])
    reused_scene_cuts = bool(cuts)
    if not cuts:
        cuts = _scene_cut_scores(video_path, 0.0, duration, 0.25)
    candidates = []

    for group in groups:
        observed_start, observed_end = group[0][0], group[-1][0]
        if len(group) < 2 or observed_end - observed_start < 2.0:
            continue

        # Sparse 2-second semantic samples need a narrow lead-in window. This
        # captures the nearby 45.25s boundary rather than any distant scene cut.
        before = _best_cut_before(
            cuts,
            observed_start + 0.75,
            max(0.0, observed_start - 3.0),
            0.30,
        )
        after = _best_cut_after(
            cuts,
            observed_end - 0.75,
            min(duration, observed_end + 8.0),
            0.30,
        )
        if not before or not after:
            continue

        start, end = float(before["time_seconds"]), float(after["time_seconds"])
        segment_seconds = end - start
        if not 4.0 <= segment_seconds <= 40.0:
            continue
        # Mid-promo must return to story; terminal CTA belongs to End Card.
        if end >= duration - 8.0:
            continue

        activity_mean = sum(value for _, value in group) / len(group)
        confidence = min(
            0.98,
            0.42
            + 0.24 * min(1.0, activity_mean)
            + 0.17 * min(1.0, float(before.get("cut_score") or 0.0))
            + 0.17 * min(1.0, float(after.get("cut_score") or 0.0)),
        )
        candidates.append(
            {
                "start_seconds": round(start, 3),
                "end_seconds": round(end, 3),
                "duration_seconds": round(segment_seconds, 3),
                "observed_activity_start_seconds": round(observed_start, 3),
                "observed_activity_end_seconds": round(observed_end, 3),
                "sample_count": len(group),
                "mean_overlay_activity": round(activity_mean, 6),
                "before_cut": before,
                "after_cut": after,
                "confidence": round(confidence, 6),
            }
        )

    if not candidates:
        return {
            "used": True,
            "reason": "no_scene_bounded_semantic_midpromo_candidate",
            "action_added": False,
            "candidate_count": 0,
            "report_relative_path": (semantic or {}).get("report_relative_path"),
            "scene_cuts_reused_from_fullscreen_scan": reused_scene_cuts,
        }

    candidates.sort(key=lambda item: (item["confidence"], item["duration_seconds"]), reverse=True)
    selected = candidates[0]
    assets = (profile or {}).get("assets") or {}
    mid_asset = (
        assets.get("mid_promo_video_relative_path")
        or (profile or {}).get("mid_promo_asset_relative_path")
        or (profile or {}).get("mid_promo_relative_path")
    )
    if not mid_asset:
        return {
            "used": True,
            "reason": "midpromo_asset_unavailable",
            "action_added": False,
            "candidate_count": len(candidates),
            "report_relative_path": (semantic or {}).get("report_relative_path"),
            "scene_cuts_reused_from_fullscreen_scan": reused_scene_cuts,
        }

    plan.setdefault("actions", []).append(
        {
            "action_id": "operator-midpromo-semantic-activity-fallback",
            "type": "mid_promo_replace",
            "status": "AUTO",
            "handler": "replace_mid_segment",
            "start_seconds": selected["start_seconds"],
            "end_seconds": selected["end_seconds"],
            "strategy": "operator_scene_bounded_semantic_overlay_midpromo_fallback",
            "decision_source": "semantic_overlay_activity_plus_scene_cuts",
            "replacement_content": {
                "mid_promo_video_relative_path": mid_asset,
                "generated_product_name": (profile or {}).get("product_name"),
            },
            "source_candidate": {
                "type": "mid_promo_candidate",
                "fallback": True,
                "boundary_ready": True,
                "semantic_overlay_activity": selected,
                "semantic_report_relative_path": (semantic or {}).get("report_relative_path"),
            },
        }
    )
    return {
        "used": True,
        "reason": "midpromo_action_recovered_from_semantic_overlay_activity",
        "action_added": True,
        "candidate_count": len(candidates),
        "report_relative_path": (semantic or {}).get("report_relative_path"),
        "scene_cuts_reused_from_fullscreen_scan": reused_scene_cuts,
        "selected_segment": selected,
    }


def _operator_midpromo_recovery(plan, profile, router):
    if _operator_midpromo_actions(plan):
        return {
            "used": False,
            "reason": "semantic_midpromo_action_present",
            "candidate_count": len(_operator_midpromo_actions(plan)),
            "action_added": False,
            "report_relative_path": None,
        }

    router_rel = (router or {}).get("report_relative_path")
    if not router_rel:
        return {
            "used": False,
            "reason": "router_report_missing",
            "candidate_count": 0,
            "action_added": False,
            "report_relative_path": None,
        }

    # The legacy segment census can only emit a mid-promo candidate from an
    # ``unclassified_brand_text`` router layer.  Avoid its expensive scene,
    # OCR and multimodal passes when that necessary input is absent.
    candidate_layers = _operator_route_layers_of_type(
        router,
        "unclassified_brand_text",
    )
    if not candidate_layers:
        return {
            "used": False,
            "reason": "legacy_multimodal_pruned_no_unclassified_brand_text_layer",
            "candidate_count": 0,
            "action_added": False,
            "report_relative_path": None,
            "router_unclassified_brand_text_layer_count": 0,
        }

    fallback = _replacement_segment_census_sync(
        BrandingReplacementSegmentCensusRequest(
            router_report_relative_path=router_rel,
            mid_context_seconds=28.0,
            scene_scan_interval_seconds=0.50,
            max_mid_segment_seconds=40.0,
            promo_ocr_interval_seconds=1.50,
            multimodal_sample_interval_seconds=0.75,
            text_layer_scan_interval_seconds=1.50,
        )
    )

    valid = []
    for seg in fallback.get("segments") or []:
        if seg.get("type") != "mid_promo_candidate":
            continue
        try:
            start = float(seg.get("start_seconds"))
            end = float(seg.get("end_seconds"))
        except Exception:
            continue
        duration = end - start
        if duration < 4.0 or duration > 40.0:
            continue
        if seg.get("qualifies_duration") is False:
            continue
        boundary_support = int(bool(seg.get("before_cut"))) + int(bool(seg.get("after_cut")))
        valid.append((boundary_support, duration, seg))

    valid.sort(key=lambda x: (x[0], x[1]), reverse=True)
    report_rel = fallback.get("report_relative_path")

    if not valid:
        return {
            "used": True,
            "reason": "no_valid_multimodal_midpromo_candidate",
            "candidate_count": 0,
            "action_added": False,
            "report_relative_path": report_rel,
        }

    seg = valid[0][2]
    assets = (profile or {}).get("assets") or {}
    mid_asset = (
        assets.get("mid_promo_video_relative_path")
        or (profile or {}).get("mid_promo_asset_relative_path")
        or (profile or {}).get("mid_promo_relative_path")
    )

    action = {
        "action_id": "operator-midpromo-multimodal-fallback",
        "type": "mid_promo_replace",
        "status": "AUTO",
        "handler": "replace_mid_segment",
        "start_seconds": float(seg["start_seconds"]),
        "end_seconds": float(seg["end_seconds"]),
        "strategy": "operator_anchor_connected_multimodal_midpromo_fallback",
        "decision_source": "legacy_multimodal_segment_census",
        "replacement_content": {
            "mid_promo_video_relative_path": mid_asset,
            "generated_product_name": (profile or {}).get("product_name"),
        },
        "source_candidate": {
            **seg,
            "fallback": True,
            "segment_census_report_relative_path": report_rel,
        },
    }

    plan.setdefault("actions", []).append(action)
    plan.setdefault("summary", {})["operator_midpromo_recovery_used"] = True
    plan["summary"]["operator_midpromo_recovery_source"] = "legacy_multimodal_segment_census"
    plan["operator_midpromo_recovery"] = {
        "used": True,
        "reason": "midpromo_action_recovered",
        "candidate_count": len(valid),
        "action_added": True,
        "report_relative_path": report_rel,
        "selected_segment": seg,
    }

    report = plan.get("report_relative_path")
    if report:
        _safe_workspace_path(report).write_text(
            json.dumps(plan, ensure_ascii=False, indent=2),
            encoding="utf-8",
        )

    return plan["operator_midpromo_recovery"]


def _operator_ensure_core_brand_actions(
    plan,
    census,
    router,
):
    actions = plan.setdefault("actions", [])
    duration = _operator_video_duration_from_reports(
        census,
        router,
    )
    video = (census or {}).get("video") or {}

    try:
        width = int(video.get("width") or 0)
        height = int(video.get("height") or 0)
    except Exception:
        width = 0
        height = 0
        duration = 0.0

    full_end = max(
        0.1,
        float(duration or 0.0),
    )
    added = []

    top_actions = [
        action
        for action in actions
        if (
            action.get("type") == "fixed_brand_overlay"
            and (
                str(action.get("placement") or "").startswith("top_")
                or action.get("handler") == "top_cleanup_brand_overlay"
            )
        )
    ]

    # Remove stale top actions that were created from a terminal census
    # cluster.  Older plans promoted an end-card logo to a full-story top
    # overlay, which explains the incorrect cover position in the latest
    # successful render.
    terminal_cluster_ids = set()
    for cluster in census.get("clusters") or []:
        try:
            cluster_id = str(cluster.get("cluster_id"))
            cluster_end = float(cluster.get("time_max_seconds") or 0.0)
            cluster_start = float(cluster.get("time_min_seconds") or 0.0)
            if duration > 0.0 and cluster_end >= duration - 2.0 and (cluster_end - cluster_start) <= max(2.0, duration * 0.20):
                terminal_cluster_ids.add(cluster_id)
        except Exception:
            continue
    if terminal_cluster_ids:
        stale_top_actions = []
        for action in top_actions:
            source = str(action.get("decision_source") or "")
            cluster_id = source.rsplit(":", 1)[-1] if source.startswith("watermark_census_top_cluster:") else ""
            if cluster_id and cluster_id in terminal_cluster_ids:
                stale_top_actions.append(action)
        for action in stale_top_actions:
            if action in actions:
                actions.remove(action)
        top_actions = [action for action in top_actions if action not in stale_top_actions]

    top_source = None

    if top_actions:
        normalized = []

        for action in top_actions:
            bbox = _operator_top_action_bbox(action)
            if not bbox:
                continue

            action["status"] = "AUTO"
            action["handler"] = "top_cleanup_brand_overlay"
            action["bbox"] = bbox
            action["active_segments"] = [
                {
                    "start_seconds": 0.0,
                    "end_seconds": full_end,
                    "bbox": bbox,
                }
            ]
            action["operator_force_full_story_span"] = True
            action["strategy"] = (
                "operator_canonical_top_icon_plus_product_name_full_story"
            )
            top_source = (
                action.get("decision_source")
                or "existing_replacement_plan"
            )
            normalized.append(action)

        top_actions = normalized

    if not top_actions:
        bbox = None
        decision_source = None

        fixed_layers = _operator_route_layers_of_type(
            router,
            "fixed_strong",
        )

        top_router_candidates = []

        for layer in fixed_layers:
            evidence = layer.get("evidence") or {}
            candidate_bbox = evidence.get("bbox") or {}

            if not candidate_bbox or height <= 0:
                continue

            try:
                center_y = (
                    float(candidate_bbox.get("y") or 0)
                    + float(candidate_bbox.get("height") or 0) / 2.0
                )
            except Exception:
                continue

            if center_y <= float(height) * 0.24:
                top_router_candidates.append(layer)

        if top_router_candidates:
            layer = max(
                top_router_candidates,
                key=lambda value: float(
                    value.get("confidence") or 0.0
                ),
            )
            bbox = (layer.get("evidence") or {}).get("bbox")
            decision_source = (
                "watermark_router_fixed_strong_top"
            )

        if not bbox:
            census_candidate = _operator_top_census_candidate(
                census
            )

            if census_candidate:
                bbox = census_candidate["bbox"]
                cluster = census_candidate["cluster"]
                decision_source = (
                    "watermark_census_top_cluster:"
                    + str(cluster.get("cluster_id"))
                )

        if bbox:
            center_x = (
                float(bbox.get("x") or 0)
                + float(bbox.get("width") or 0) / 2.0
            )

            placement = (
                "top_right"
                if width and center_x >= float(width) / 2.0
                else "top_left"
            )

            action = {
                "action_id": "operator-forced-top-brand",
                "type": "fixed_brand_overlay",
                "status": "AUTO",
                "handler": "top_cleanup_brand_overlay",
                "placement": placement,
                "bbox": bbox,
                "active_segments": [
                    {
                        "start_seconds": 0.0,
                        "end_seconds": full_end,
                        "bbox": bbox,
                    }
                ],
                "strategy": (
                    "operator_canonical_top_icon_plus_product_name_full_story"
                ),
                "decision_source": decision_source,
                "operator_force_full_story_span": True,
            }

            actions.append(action)
            top_actions = [action]
            top_source = decision_source

            added.append(
                {
                    "type": "fixed_brand_overlay",
                    "source": decision_source,
                }
            )

    has_top = bool(top_actions)

    # The original recovery only created a top action.  Router evidence for a
    # bottom fixed logo was therefore visible to classification/QC but never
    # handed to the bottom compositor.  Add one bounded bottom action when no
    # planner action already owns that source mark.
    bottom_actions = [
        action for action in actions
        if action.get("type") == "fixed_brand_overlay"
        and _operator_fixed_action_vertical_zone(action, width, height) == "bottom"
    ]
    if not bottom_actions:
        bottom_candidates = []
        for layer in _operator_route_layers_of_type(router, "fixed_strong"):
            evidence = layer.get("evidence") or {}
            candidate_bbox = evidence.get("bbox") or {}
            try:
                center_y = float(candidate_bbox.get("y")) + float(candidate_bbox.get("height")) / 2.0
            except (AttributeError, TypeError, ValueError):
                continue
            if height > 0 and center_y >= float(height) * 0.62:
                bottom_candidates.append(layer)
        if bottom_candidates:
            layer = max(bottom_candidates, key=lambda value: float(value.get("confidence") or 0.0))
            bbox = (layer.get("evidence") or {}).get("bbox") or {}
            action = {
                "action_id": "operator-forced-bottom-brand",
                "type": "fixed_brand_overlay",
                "status": "AUTO",
                "handler": "bottom_cleanup_brand_overlay",
                "placement": "bottom_right" if float(bbox.get("x") or 0) >= float(width) * 0.5 else "bottom_left",
                "bbox": bbox,
                "active_segments": [{"start_seconds": 0.0, "end_seconds": full_end, "bbox": bbox}],
                "strategy": "operator_canonical_bottom_brand_full_story",
                "decision_source": "watermark_router_fixed_strong_bottom",
                "operator_force_full_story_span": True,
            }
            actions.append(action)
            added.append({"type": "fixed_brand_overlay", "source": action["decision_source"]})

    # A terminal app-promo card can be visually distinct enough that OCR sees
    # no readable product text.  If semantic analysis already bounds the final
    # promo segment, it is safer to trim it than retain competitor conversion
    # content and append our card afterwards.  This fallback is terminal-only;
    # it never promotes in-story brand mentions into destructive edits.
    semantic_end_candidates = []
    for action in actions:
        if action.get("type") != "mid_promo_replace":
            continue
        source_candidate = action.get("source_candidate") or {}
        semantic_decision = source_candidate.get("_semantic_decision") or {}
        try:
            start_seconds = float(action.get("start_seconds") or 0.0)
            end_seconds = float(action.get("end_seconds") or 0.0)
        except Exception:
            continue
        if (
            full_end > 0.0
            # A semantic promo often ends on the last spoken CTA while a
            # 1–3-second visual app card follows without readable OCR.  Treat
            # that bounded terminal tail as an end-card candidate as well.
            and end_seconds >= full_end - 3.5
            and start_seconds >= max(0.0, full_end - 30.0)
            and str(semantic_decision.get("presence") or "").upper() == "PRESENT"
        ):
            semantic_end_candidates.append(
                {
                    "action": action,
                    "start_seconds": start_seconds,
                    "end_seconds": end_seconds,
                }
            )

    def _production_approved(action):
        if str(action.get("status") or "").upper() != "REVIEW":
            return True
        candidate = action.get("source_candidate") or {}
        return bool(candidate.get("user_confirmed") or action.get("user_confirmed"))

    has_end = any(
        action.get("type") == "end_card_replace"
        and _production_approved(action)
        for action in actions
    )

    if not has_end:
        end_layers = _operator_route_layers_of_type(
            router,
            "end_card",
        )

        if end_layers:
            layer = max(
                end_layers,
                key=lambda value: float(
                    value.get("confidence") or 0.0
                ),
            )
            evidence = layer.get("evidence") or {}

            try:
                start_seconds = float(
                    evidence.get("time_min_seconds") or 0.0
                )
            except Exception:
                start_seconds = 0.0

            try:
                end_seconds = float(
                    duration
                    or evidence.get("time_max_seconds")
                    or start_seconds
                )
            except Exception:
                end_seconds = start_seconds

            if end_seconds > start_seconds:
                actions.append(
                    {
                        "action_id": "operator-fallback-end-card",
                        "type": "end_card_replace",
                        "status": "AUTO",
                        "handler": "trim_append_end_card",
                        "start_seconds": max(
                            0.0,
                            start_seconds,
                        ),
                        "end_seconds": end_seconds,
                        "strategy": (
                            "operator_watermark_router_end_card_fallback"
                        ),
                        "decision_source": "watermark_router_end_card",
                        "source_candidate": {
                            "type": "end_card",
                            "boundary_ready": True,
                            "fallback": True,
                            "router_layer_id": layer.get("layer_id"),
                        },
                    }
                )

                added.append(
                    {
                        "type": "end_card_replace",
                        "source": "watermark_router_end_card",
                    }
                )

    has_end = any(
        action.get("type") == "end_card_replace"
        and _production_approved(action)
        for action in actions
    )
    if not has_end and semantic_end_candidates:
        candidate = min(
            semantic_end_candidates,
            key=lambda value: value["start_seconds"],
        )
        actions.append(
            {
                "action_id": "operator-fallback-semantic-terminal-end-card",
                "type": "end_card_replace",
                "status": "AUTO",
                "handler": "trim_append_end_card",
                # This End Card is the terminal continuation of the selected
                # Mid Promo.  It begins at the Mid Promo's semantic end, never
                # inside it.  Render-only guards may later expand the Mid
                # Promo or refine the End Card boundary, and the renderer has a
                # linked-action handoff clamp for that case; the plan itself
                # must remain non-overlapping and auditable.
                "start_seconds": max(0.0, candidate["end_seconds"]),
                "end_seconds": full_end,
                "strategy": "operator_semantic_terminal_promo_trim_then_own_end_card",
                "decision_source": "semantic_terminal_promo",
                "source_candidate": {
                    "type": "end_card",
                    "boundary_ready": True,
                    "fallback": True,
                    "semantic_mid_promo_action_id": candidate["action"].get("action_id"),
                },
            }
        )
        added.append(
            {
                "type": "end_card_replace",
                "source": "semantic_terminal_promo",
            }
        )

    plan.setdefault(
        "operator_fallback_actions",
        [],
    ).extend(added)

    plan.setdefault(
        "summary",
        {},
    )["operator_fallback_action_count"] = len(
        plan.get("operator_fallback_actions") or []
    )

    plan["summary"]["operator_top_brand_required"] = has_top
    plan["summary"]["operator_top_brand_full_story_span"] = has_top
    plan["summary"]["operator_top_brand_source"] = top_source

    report_rel = plan.get("report_relative_path")

    if report_rel:
        try:
            _safe_workspace_path(report_rel).write_text(
                json.dumps(
                    plan,
                    ensure_ascii=False,
                    indent=2,
                ),
                encoding="utf-8",
            )
        except Exception:
            pass

    return plan


def _operator_branding_business_qc(
    rendered,
    source_context,
    router,
    plan=None,
    profile=None,
):
    summary = rendered.get("summary") or {}
    visual = rendered.get("visual_base") or {}
    plan = plan or {}
    plan_summary = plan.get("summary") or {}
    profile = profile or {}
    profile_assets = profile.get("assets") or {}

    top_expected = bool(
        plan_summary.get("operator_top_brand_required")
        or int(summary.get("top_brand_action_count") or 0) > 0
    )
    fixed_expected = bool(_operator_route_layers_of_type(router, "fixed_strong"))
    end_card_expected = bool(_operator_route_layers_of_type(router, "end_card"))
    mid_promo_expected = any(
        action.get("type") == "mid_promo_replace"
        for action in (plan.get("actions") or [])
    )
    temporal_repair_completed = str(
        summary.get("dynamic_watermark_temporal_recovery_status") or ""
    ).lower() == "completed"
    dynamic_expected_track_count = max(
        int(
            plan_summary.get(
                "operator_dynamic_brand_expected_track_count"
            )
            or 0
        ),
        int(
            visual.get(
                "dynamic_brand_track_count"
            )
            or 0
        ),
    )
    # A completed temporal handoff has already removed the moving source mark
    # in an intermediate video, so QC must not require a second compositor
    # receipt for those tracks.
    if temporal_repair_completed:
        dynamic_expected_track_count = 0

    dynamic_tracks_skipped_by_bottom = list(
        visual.get("dynamic_brand_track_ids_skipped_by_bottom_cover") or []
    )
    dynamic_expected_effective_count = max(
        0,
        dynamic_expected_track_count - len(dynamic_tracks_skipped_by_bottom),
    )
    dynamic_expected = dynamic_expected_effective_count > 0
    bottom_expected = any(
        action.get("type") == "fixed_brand_overlay"
        and str(
            action.get("placement")
            or ""
        ).startswith("bottom_")
        for action in (
            plan.get("actions")
            or []
        )
    )

    top_frames = int(visual.get("top_composed_frames") or 0)
    top_icon_frames = int(visual.get("top_icon_asset_frames") or 0)
    top_text_frames = int(visual.get("top_product_text_frames") or 0)

    top_product_name = str(
        visual.get("top_product_name")
        or profile.get("product_name")
        or ""
    ).strip()
    bottom_frames = int(
        visual.get(
            "bottom_brand_cover_frames"
        )
        or 0
    )
    bottom_applications = int(
        visual.get(
            "bottom_brand_cover_applications"
        )
        or 0
    )

    top_icon_relative_path = str(
        profile_assets.get("icon_image_relative_path")
        or ""
    ).strip()

    dynamic_frames = int(
        visual.get(
            "dynamic_brand_cover_frames"
        )
        or 0
    )

    dynamic_applications = int(
        visual.get(
            "dynamic_brand_cover_applications"
        )
        or 0
    )
    diagonal_required = bool(
        summary.get("diagonal_dynamic_watermark_required")
    )
    diagonal_geometry = visual.get("diagonal_brand_cover") or {}
    diagonal_frames = int(
        visual.get("diagonal_brand_cover_frames") or 0
    )
    end_replace_count = int(summary.get("end_card_replace_count") or 0)
    end_append_count = int(summary.get("end_card_append_count") or 0)
    mid_promo_replace_count = int(summary.get("mid_promo_replace_count") or 0)

    failures = []

    if top_expected:
        if top_frames <= 0:
            failures.append("top_brand_required_but_no_top_frames_rendered")
        if not top_icon_relative_path:
            failures.append("top_brand_required_but_icon_asset_not_configured")
        if top_icon_frames <= 0:
            failures.append("top_brand_required_but_own_icon_not_rendered")
        if not top_product_name:
            failures.append("top_brand_required_but_product_name_missing")
        if top_text_frames <= 0:
            failures.append("top_brand_required_but_product_name_not_rendered")

    if fixed_expected and top_expected and top_frames <= 0:
        failures.append("fixed_logo_detected_but_no_top_brand_frames_rendered")

    if dynamic_expected and dynamic_frames <= 0:
        failures.append(
            "dynamic_watermark_detected_but_no_dynamic_cover_frames_rendered"
        )

    if (
        dynamic_expected
        and dynamic_applications <= 0
    ):
        failures.append(
            "dynamic_watermark_expected_but_no_cover_application_rendered"
        )

    if (
        dynamic_expected_track_count
        > int(
            visual.get(
                "dynamic_brand_track_count_before_bottom_dedup"
            )
            or visual.get(
                "dynamic_brand_track_count"
            )
            or 0
        )
    ):
        failures.append(
            "dynamic_watermark_track_lost_between_census_and_renderer"
        )

    if diagonal_required and not bool(diagonal_geometry.get("available")):
        failures.append("diagonal_watermark_cover_required_but_geometry_unavailable")

    if diagonal_required and diagonal_frames <= 0:
        failures.append("diagonal_watermark_cover_required_but_no_frames_rendered")

    if bottom_expected and bottom_frames <= 0:
        failures.append(
            "bottom_brand_detected_but_no_bottom_cover_frames_rendered"
        )

    if (
        bottom_expected
        and bottom_applications <= 0
    ):
        failures.append(
            "bottom_brand_expected_but_no_cover_application_rendered"
        )

    if end_card_expected and end_replace_count <= 0:
        failures.append("competitor_end_card_detected_but_not_replaced")

    terminal_semantic_promo = any(
        action.get("type") == "end_card_replace"
        and str(action.get("decision_source") or "") == "semantic_terminal_promo"
        for action in (plan.get("actions") or [])
    )
    if terminal_semantic_promo and end_replace_count <= 0:
        failures.append("terminal_competitor_promo_detected_but_not_trimmed")

    if not end_card_expected and (end_replace_count + end_append_count) <= 0:
        failures.append("own_end_card_was_neither_replacement_nor_append")

    if mid_promo_expected and mid_promo_replace_count <= 0:
        failures.append("mid_promo_expected_but_no_mid_promo_replacement_rendered")

    failures = list(dict.fromkeys(failures))

    return {
        "ok": len(failures) == 0,
        "top_brand_required": top_expected,
        "top_brand_source": plan_summary.get("operator_top_brand_source"),
        "top_brand_full_story_span": bool(
            plan_summary.get("operator_top_brand_full_story_span")
        ),
        "top_composed_frames": top_frames,
        "top_icon_relative_path": top_icon_relative_path or None,
        "top_icon_asset_frames": top_icon_frames,
        "top_product_name": top_product_name or None,
        "top_product_text_frames": top_text_frames,
        "top_icon_treatments": visual.get("top_icon_treatments") or {},
        "fixed_logo_expected": fixed_expected,
        "dynamic_watermark_expected": dynamic_expected,
        "dynamic_expected_track_count": (
            dynamic_expected_track_count
        ),
        "dynamic_expected_effective_track_count": (
            dynamic_expected_effective_count
        ),
        "dynamic_track_ids_satisfied_by_bottom_cover": (
            dynamic_tracks_skipped_by_bottom
        ),
        "dynamic_track_count": int(
            visual.get(
                "dynamic_brand_track_count"
            )
            or 0
        ),
        "dynamic_track_sources": (
            visual.get(
                "dynamic_brand_track_sources"
            )
            or {}
        ),
        "dynamic_cover_frames": dynamic_frames,
        "dynamic_cover_applications": (
            dynamic_applications
        ),
        "diagonal_watermark_cover_required": diagonal_required,
        "diagonal_watermark_geometry_available": bool(
            diagonal_geometry.get("available")
        ),
        "diagonal_watermark_cover_frames": diagonal_frames,
        "bottom_brand_expected": (
            bottom_expected
        ),
        "bottom_brand_cover_frames": (
            bottom_frames
        ),
        "bottom_brand_cover_applications": (
            bottom_applications
        ),
        "end_card_expected": end_card_expected,
        "end_card_replace_count": end_replace_count,
        "end_card_append_count": end_append_count,
        "terminal_semantic_promo_expected": terminal_semantic_promo,
        "mid_promo_expected": mid_promo_expected,
        "mid_promo_replace_count": mid_promo_replace_count,
        "failures": failures,
        "source_relative_path": source_context.get("relative_path"),
    }


def _operator_top_identity_contract(
    profile,
):
    profile = profile or {}
    assets = profile.get("assets") or {}

    product_name = str(
        profile.get("product_name") or ""
    ).strip()

    icon_relative_path = str(
        assets.get("icon_image_relative_path") or ""
    ).strip()

    icon_path = None

    if icon_relative_path:
        try:
            icon_path = _safe_workspace_path(
                icon_relative_path
            )
        except Exception:
            icon_path = None

    return {
        "ok": bool(
            product_name
            and icon_path is not None
            and icon_path.is_file()
        ),
        "product_name": product_name,
        "icon_relative_path": icon_relative_path or None,
        "icon_exists": bool(
            icon_path is not None
            and icon_path.is_file()
        ),
    }


def _operator_top_census_candidate(
    census,
):
    census = census or {}
    video = census.get("video") or {}

    try:
        width = int(video.get("width") or 0)
        height = int(video.get("height") or 0)
        duration = float(video.get("duration_seconds") or 0.0)
    except Exception:
        width = 0
        height = 0

    if width <= 0 or height <= 0:
        return None

    candidates = []

    for cluster in census.get("clusters") or []:
        bbox = cluster.get("stable_bbox") or {}
        if not bbox:
            continue

        try:
            center_y = (
                float(bbox.get("y") or 0)
                + float(bbox.get("height") or 0) / 2.0
            )
            unique_times = int(cluster.get("unique_time_count") or 0)
            hit_count = int(cluster.get("hit_count") or 0)
            similarity = float(cluster.get("best_similarity") or 0.0)
        except Exception:
            continue

        # A logo cluster that exists only in the final seconds is an end-card
        # candidate, not a fixed top watermark.  Promoting it to a full-story
        # top overlay puts our replacement in the wrong location for the
        # entire video (the regression observed in the latest 5-item task).
        time_min = float(cluster.get("time_min_seconds") or 0.0)
        time_max = float(cluster.get("time_max_seconds") or 0.0)
        observed_span = max(0.0, time_max - time_min)
        if duration > 0.0 and time_max >= duration - 2.0 and observed_span <= max(2.0, duration * 0.20):
            continue

        if center_y > float(height) * 0.24:
            continue

        classification = str(cluster.get("classification") or "")
        fixed_rank = 2 if classification == "fixed_candidate" else 1

        if classification != "fixed_candidate" and unique_times < 2:
            continue

        candidates.append(
            {
                "cluster": cluster,
                "bbox": _clip_bbox(
                    bbox,
                    width,
                    height,
                ),
                "rank": (
                    fixed_rank,
                    unique_times,
                    hit_count,
                    similarity,
                ),
            }
        )

    if not candidates:
        return None

    candidates.sort(
        key=lambda value: value["rank"],
        reverse=True,
    )

    return candidates[0]


def _operator_top_action_bbox(
    action,
):
    action = action or {}

    bbox = action.get("bbox")
    if bbox:
        return bbox

    for segment in action.get("active_segments") or []:
        bbox = segment.get("bbox")
        if bbox:
            return bbox

    return None


def _operator_process_video(
    video_entry,
    progress_callback=None,
):
    pipeline_started = time.monotonic()
    stage_timings = []
    timing_finalized = False

    def finalize_stage_timings():
        nonlocal timing_finalized
        if timing_finalized:
            return
        now = time.monotonic()
        if stage_timings and "elapsed_seconds" not in stage_timings[-1]:
            stage_timings[-1]["elapsed_seconds"] = round(
                now - stage_timings[-1]["started_monotonic"],
                3,
            )
        timing_finalized = True

    def stage(
        code,
        label,
    ):
        now = time.monotonic()
        if stage_timings:
            stage_timings[-1]["elapsed_seconds"] = round(
                now - stage_timings[-1]["started_monotonic"],
                3,
            )
        stage_timings.append(
            {
                "code": str(code),
                "label": str(label),
                "started_monotonic": now,
            }
        )
        if callable(
            progress_callback
        ):
            try:
                progress_callback(
                    str(
                        code
                    ),
                    str(
                        label
                    ),
                )
            except Exception:
                # Task-status reporting must never break the media pipeline.
                pass

    def run_stage(code, label, operation):
        stage(code, label)
        return operation()

    # Strictly verified dynamic tracks are eligible for the source-specific
    # compositor; each remains subject to a per-track frame receipt at render.

    stage(
        "source_validation",
        "校验源文件与归档信息",
    )

    relative_path = (
        video_entry[
            "relative_path"
        ]
    )

    try:
        source_context = (
            _operator_source_video_context(
                relative_path,
                video_entry.get(
                    "product_name"
                ),
                video_entry.get(
                    "language"
                ),
            )
        )
    except HTTPException as exc:
        detail = (
            getattr(
                exc,
                "detail",
                None,
            )
        )

        is_missing = (
            getattr(
                exc,
                "status_code",
                None,
            )
            == 404
            and isinstance(
                detail,
                dict,
            )
            and detail.get(
                "error"
            )
            == "file_not_found"
        )

        if not is_missing:
            raise

        relocation = (
            _operator_relocate_stale_source(
                relative_path,
                sha256_hint=(
                    video_entry.get(
                        "sha256"
                    )
                    or video_entry.get(
                        "source_sha256"
                    )
                ),
                product_hint=(
                    video_entry.get(
                        "product_name"
                    )
                ),
                language_hint=(
                    video_entry.get(
                        "language"
                    )
                ),
            )
        )

        if not (
            relocation
            and relocation.get(
                "resolved"
            )
        ):
            raise HTTPException(
                status_code=404,
                detail={
                    "stage": (
                        "operator_source_relocation"
                    ),
                    "error": (
                        (
                            relocation
                            or {}
                        ).get(
                            "error"
                        )
                        or "stale_source_reference_unrecoverable"
                    ),
                    "message": (
                        "The historical source path no longer exists and no "
                        "matching current source file could be located under "
                        "workspace/raw or workspace/review."
                    ),
                    "relative_path": (
                        relative_path
                    ),
                    "basename": (
                        Path(
                            relative_path
                        ).name
                    ),
                    "relocation": (
                        relocation
                    ),
                },
            )

        video_entry[
            "stale_relative_path"
        ] = (
            relative_path
        )

        video_entry[
            "relative_path"
        ] = (
            relocation[
                "relative_path"
            ]
        )

        video_entry[
            "path_relocation"
        ] = (
            relocation
        )

        relative_path = (
            video_entry[
                "relative_path"
            ]
        )

        source_context = (
            _operator_source_video_context(
                relative_path,
                video_entry.get(
                    "product_name"
                ),
                video_entry.get(
                    "language"
                ),
            )
        )

    if not bool(
        source_context.get(
            "archive_ready"
        )
    ):
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "operator_source_archive",
                "error": "source_archive_not_ready",
                "message": (
                    "Editing is blocked until product metadata and source "
                    "language are resolved and the original file is archived "
                    "under raw/<run-minute>/<product>/<language>/."
                ),
                "relative_path": (
                    relative_path
                ),
                "product_name": (
                    source_context.get(
                        "product_name"
                    )
                ),
                "language": (
                    source_context.get(
                        "language"
                    )
                ),
            },
        )

    # Run the hard diagonal/tiled watermark exclusion immediately after source
    # validation. This prevents brand lookup, OCR, dynamic tracking, Whisper,
    # and render planning for assets that must be discarded.
    diagonal_screen = run_stage(
        "diagonal_watermark_gate",
        "先行筛查斜向平铺水印",
        lambda: _operator_diagonal_tiled_watermark_screen(video_entry),
    )
    if bool((diagonal_screen or {}).get("detected")):
        raise _OperatorTaskDiscarded(
            "diagonal_tiled_watermark",
            {
                "source_video_relative_path": relative_path,
                "diagonal_watermark_screen": diagonal_screen,
                "message": "检测到斜向平铺水印，素材跳过正式剪辑。",
            },
        )

    stage(
        "brand_target",
        "识别竞品品牌目标",
    )

    targets = (
        _operator_brand_targets(
            relative_path,
            source_context.get(
                "product_name"
            ),
        )
    )

    source_brand_assets = _operator_source_brand_detection_assets(
        source_context
    )
    # Keep the acquisition-time app title and package-derived aliases in the
    # same census request as the visual templates.  The old path passed only
    # text targets, which is why this task's dynamic watermark expected count
    # collapsed to zero despite a registered source brand.
    for identity_value in (
        source_context.get("app_title"),
        source_context.get("product_name"),
    ):
        if identity_value and identity_value not in targets:
            targets.append(identity_value)

    if not targets:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "operator_branding",
                "error": "competitor_brand_target_unavailable",
                "relative_path": (
                    relative_path
                ),
            },
        )

    # Fail fast before watermark census / Whisper / semantic analysis.
    # The standard production profile requires all drop-in brand assets.
    stage(
        "brand_assets",
        "检查 Logo / Mid Promo / End Card",
    )

    profile = (
        _operator_select_profile()
    )

    brand_asset_validation = (
        _operator_brand_assets_preflight(
            profile,
            language=(
                source_context.get(
                    "language"
                )
            ),
            language_code=(
                source_context.get(
                    "language_code"
                )
            ),
        )
    )

    # Apply the language-specific drop-in slots to the selected profile for
    # this render.  The formal profile stays automatic; the operator does not
    # enter asset paths.
    autodiscovery = (
        brand_asset_validation.get(
            "autodiscovery"
        )
        or {}
    )

    selected_mid = (
        autodiscovery.get(
            "mid_promo_selected_relative_path"
        )
    )

    selected_end = (
        autodiscovery.get(
            "end_card_selected_relative_path"
        )
    )

    profile_assets = (
        profile.setdefault(
            "assets",
            {},
        )
    )

    top_identity = _operator_top_identity_contract(
        profile
    )

    if not bool(
        top_identity.get(
            "ok"
        )
    ):
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "operator_brand_assets_preflight",
                "error": "top_icon_and_product_name_required",
                "profile_id": profile.get("profile_id"),
                "product_name": top_identity.get("product_name"),
                "icon_relative_path": top_identity.get(
                    "icon_relative_path"
                ),
                "icon_exists": top_identity.get("icon_exists"),
                "message": (
                    "Production top branding requires icon.png plus "
                    "a configured product_name."
                ),
            },
        )

    if selected_mid:
        profile_assets[
            "mid_promo_video_relative_path"
        ] = selected_mid

        profile[
            "mid_promo_asset_relative_path"
        ] = selected_mid

        profile[
            "mid_promo_relative_path"
        ] = selected_mid

    if selected_end:
        if str(
            selected_end
        ).lower().endswith(
            ".mp4"
        ):
            profile_assets[
                "end_card_video_relative_path"
            ] = selected_end

            profile_assets[
                "end_card_image_relative_path"
            ] = None
        else:
            profile_assets[
                "end_card_image_relative_path"
            ] = selected_end

            profile_assets[
                "end_card_video_relative_path"
            ] = None

        profile[
            "end_card_asset_relative_path"
        ] = selected_end

        profile[
            "end_card_relative_path"
        ] = selected_end

    census = run_stage(
        "watermark_census",
        "扫描水印与品牌覆盖区域",
        lambda: _watermark_census_sync(
            BrandingWatermarkCensusRequest(
                relative_path=(
                    relative_path
                ),
                targets=(
                    targets
                ),
                source_brand_id=source_brand_assets.get("brand_id"),
                source_product_name=source_context.get("product_name"),
                source_app_title=source_context.get("app_title"),
                source_icon_relative_path=source_brand_assets.get("icon_relative_path"),
                source_logo_relative_path=source_brand_assets.get("logo_relative_path"),
                # OCR is used for fixed identity and coarse routing. Running
                # four Tesseract subprocesses every 0.30s made a 100s clip
                # take many minutes before rendering even started. Dynamic
                # motion is handled by the separate visual scan below, so use
                # two OCR variants at a bounded cadence here.
                scan_interval_seconds=0.75,
                max_frames=140,
                ocr_scale=1.5,
                preprocess_variants=["original", "clahe"],
                dynamic_visual_mode=True,
                dynamic_visual_sample_interval_seconds=0.50,
                dynamic_visual_min_alpha_response=0.035,
                dynamic_visual_min_persistence_ratio=0.45,
                save_debug_frames=False,
                max_debug_frames=0,
            )
        ),
    )
    diagonal_screen = run_stage(
        "diagonal_watermark_gate",
        "筛查斜向平铺水印（不符合无痕处理条件的素材将跳过剪辑）",
        # The gate was already executed before brand/OCR work. Reuse its
        # result here for backward-compatible stage reporting without a second
        # full video scan.
        lambda: diagonal_screen,
    )
    if bool((diagonal_screen or {}).get("detected")):
        raise _OperatorTaskDiscarded(
            "diagonal_tiled_watermark",
            {
                "source_video_relative_path": relative_path,
                "diagonal_watermark_screen": diagonal_screen,
                "message": (
                    "检测到斜向平铺水印。当前无痕处理门禁要求该素材跳过剪辑，"
                    "已保留原始下载文件供审核，不进入正式成片。"
                ),
            },
        )

    router = run_stage(
        "watermark_route",
        "生成品牌处理路由",
        lambda: _watermark_route_sync(
            BrandingWatermarkRouteRequest(
                relative_path=(
                    relative_path
                ),
                brand_targets=(
                    targets
                ),
                census_report_relative_path=(
                    census.get(
                        "report_relative_path"
                    )
                ),
                save_three_anchor_profile=False,
            )
        ),
    )

    source_language_code = str(
        source_context.get(
            "language_code"
        )
        or ""
    ).strip().casefold()

    source_language_name = str(
        source_context.get(
            "language"
        )
        or ""
    ).strip().casefold()

    semantic_translation_enabled = not (
        source_language_code in {
            "en",
            "eng",
        }
        or source_language_name in {
            "english",
            "en",
            "eng",
        }
    )

    semantic = (
        _operator_semantic_cache_load(
            source_context,
            router,
        )
    )

    semantic_cache_hit = bool(
        semantic
    )

    if semantic_cache_hit:
        stage(
            "semantic_cache",
            "复用 SHA256 语义分析缓存",
        )

    else:
        semantic_mode_label = (
            "单次 Whisper 英译"
            if semantic_translation_enabled
            else "单次 Whisper 转写"
        )

        semantic = run_stage(
            "semantic_analysis",
            (
                "语义分析快速路径 · "
                + semantic_mode_label
                + " + "
                + str(
                    _operator_semantic_sample_interval()
                )
                + "s OCR"
            ),
            lambda: _semantic_structure_census_sync(
                BrandingSemanticStructureRequest(
                    router_report_relative_path=(
                        router[
                            "report_relative_path"
                        ]
                    ),
                    sample_interval_seconds=(
                        _operator_semantic_sample_interval()
                    ),
                    max_samples=(
                        _operator_semantic_max_samples()
                    ),
                    enable_whisper=_operator_semantic_whisper_enabled(),
                    enable_whisper_translation=(
                        semantic_translation_enabled
                    ),
                    whisper_single_pass_translation=(
                        semantic_translation_enabled
                    ),
                    whisper_device="cpu",
                    whisper_compute_type="int8",
                    # Keep semantic classification independent from the larger
                    # acquisition language model. A base model is sufficient
                    # for promo/CTA phrase scoring and avoids a second small
                    # model pass turning a 90s clip into a long CPU job.
                    whisper_model=os.getenv("OPERATOR_SEMANTIC_WHISPER_MODEL") or "base",
                )
            ),
        )

        semantic = (
            _operator_semantic_cache_store(
                semantic,
                source_context,
                router,
            )
        )

    plan = run_stage(
        "replacement_plan",
        "生成替换计划",
        lambda: _replacement_plan_sync(
            BrandingReplacementPlanRequest(
                router_report_relative_path=(
                    router[
                        "report_relative_path"
                    ]
                ),
                profile_id=str(
                    profile[
                        "profile_id"
                    ]
                ),
                semantic_structure_report_relative_path=(
                    semantic.get(
                        "report_relative_path"
                    )
                ),
                moving_tracks_approved=True,
                include_uncertain_structures=False,
                require_semantic_structure_ready=False,
            )
        ),
    )

    plan = (
        _operator_ensure_core_brand_actions(
            plan,
            census,
            router,
        )
    )

    # Persist the acquisition-time competitor identity in every production
    # plan.  Temporal repair must use the same product-specific template as
    # the census; relying on a generic fallback makes otherwise valid dynamic
    # tracks disappear during the render handoff.
    plan.setdefault("source", {})["source_identity"] = {
        "brand_id": source_brand_assets.get("brand_id") or source_context.get("brand_id"),
        "product_name": source_context.get("product_name"),
        "app_title": source_context.get("app_title") or source_context.get("product_name"),
        "icon_relative_path": source_brand_assets.get("icon_relative_path"),
        "logo_relative_path": source_brand_assets.get("logo_relative_path"),
    }

    dynamic_track_preview = (
        _operator_dynamic_brand_tracks_from_census(
            census.get(
                "report_relative_path"
            )
        )
    )

    dynamic_track_source_counts = {}

    for track in dynamic_track_preview:
        source = str(
            track.get(
                "recovery_source"
            )
            or track.get(
                "classification"
            )
            or "unknown"
        )

        dynamic_track_source_counts[
            source
        ] = (
            dynamic_track_source_counts.get(
                source,
                0,
            )
            + 1
        )

    plan.setdefault(
        "summary",
        {},
    )[
        "operator_dynamic_brand_expected_track_count"
    ] = len(
        dynamic_track_preview
    )

    plan[
        "summary"
    ][
        "operator_dynamic_brand_track_sources"
    ] = (
        dynamic_track_source_counts
    )

    if _operator_midpromo_actions(plan):
        midpromo_recovery = {
            "used": False,
            "reason": "semantic_midpromo_action_present",
            "candidate_count": len(_operator_midpromo_actions(plan)),
            "action_added": False,
            "report_relative_path": None,
        }
    else:
        midpromo_recovery = _operator_midpromo_user_boundary_override(
            plan,
            profile,
            source_context,
        )

        # The legacy multimodal census is the slowest recovery branch after
        # OCR.  Prefer the sequential fullscreen scan (which also hands its
        # scene cuts to the semantic-activity recovery) and invoke the legacy
        # census only when the fast route cannot identify a bounded segment.
        if not _operator_midpromo_actions(plan):
            fullscreen_recovery = run_stage(
                "midpromo_fullscreen_recovery",
                "Mid Promo 语义未命中 · 快速检测全屏插播结构",
                lambda: _operator_midpromo_fullscreen_insert_fallback(
                    plan, profile, source_context, semantic
                ),
            )
            midpromo_recovery = {
                **midpromo_recovery,
                "fullscreen_insert_fallback": fullscreen_recovery,
            }

        if not _operator_midpromo_actions(plan):
            activity_recovery = run_stage(
                "midpromo_activity_recovery",
                "Mid Promo 无 OCR 锚点 · 以画面活动与场景边界复核",
                lambda: _operator_midpromo_semantic_activity_fallback(
                    plan,
                    profile,
                    semantic,
                    scene_cuts=(fullscreen_recovery or {}).get("scene_cuts"),
                ),
            )
            midpromo_recovery = {
                **midpromo_recovery,
                "semantic_activity_fallback": activity_recovery,
            }

        if not _operator_midpromo_actions(plan):
            # Do not turn an unbounded/uncertain interruption into a slow
            # destructive edit.  The review UI retains the source and exposes
            # the no-match reason; a user boundary override remains available
            # for the exceptional case.  This removes the 4–5 minute legacy
            # OCR/scene pass from the normal production path.
            legacy_recovery = run_stage(
                "midpromo_multimodal_recovery",
                "Mid Promo targeted scene-boundary recovery",
                lambda: _operator_midpromo_recovery(plan, profile, router),
            )
            midpromo_recovery = {
                **midpromo_recovery,
                "legacy_multimodal_fallback": legacy_recovery,
            }

    plan.setdefault("summary", {})["mid_promo_replace_count"] = len(
        _operator_midpromo_actions(plan)
    )

    # Persist operator-added recovery actions before the production renderer
    # snapshots the plan. The original plan stays the audit record; the current
    # task's render always has a complete, readable action trail.
    if plan.get("report_relative_path"):
        _safe_workspace_path(plan["report_relative_path"]).write_text(
            json.dumps(plan, ensure_ascii=False, indent=2), encoding="utf-8"
        )

    production_req = (
        BrandingProductionCandidateRenderRequest(
            replacement_plan_relative_path=(
                plan[
                    "report_relative_path"
                ]
            ),
            include_review_actions=False,
            allow_placeholder_assets=False,

            watermark_treatment_mode="rebrand_fixed_clean_dynamic",
            compose_top_brand_layers=True,

            # The renderer automatically consumes only the census tracks that
            # survived strict source-specific validation. Its per-track receipt
            # gate remains mandatory, so no unhandled verified motion track can
            # be delivered.
            dynamic_brand_cover_enabled=False,
            dynamic_brand_cover_census_report_relative_path=None,
            dynamic_brand_cover_auto_from_plan=True,
            # Verified moving marks are repaired in the temporal stage before
            # the fixed-layer compositor. Without this flag the compositor is
            # disabled while business QC still expects dynamic frames.
            dynamic_watermark_temporal_recovery_enabled=True,
            # Match the verified-track policy: no interpolation across a
            # missing/teleport interval longer than 320ms.
            dynamic_brand_cover_max_gap_seconds=0.32,
            dynamic_brand_cover_expand_ratio=1.08,
            dynamic_watermark_blur_sigma=5.0,

            diagonal_brand_cover_enabled=True,
            diagonal_brand_cover_max_points=24,
            persistent_watermark_blur_sigma=7.0,

            mid_promo_tail_guard_frames=1,

            # Only exact-source validated grids are mandatory. Unknown layouts
            # remain reviewable rather than being covered from stale geometry.
            diagonal_dynamic_watermark_required=False,

            editorial_max_story_seconds=55.0,
            editorial_min_story_seconds=45.0,

            append_own_end_card_when_absent=True,

            crf=_operator_render_crf(),
            preset=(
                _operator_render_preset()
            ),

            audio_sample_rate=48000,
            audio_channels=2,
            audio_bitrate="160k",

            keep_intermediate_files=False,

            production_candidate=True,
            require_own_end_card_asset=True,
            require_mid_promo_asset_when_present=True,
        )
    )

    rendered = run_stage(
        "render",
        (
            "FFmpeg 正式渲染"
            + "（preset="
            + _operator_render_preset()
            + "）"
        ),
        lambda: _production_candidate_render_sync(
            production_req
        ),
    )

    qc = run_stage(
        "quality_check",
        "执行成片 QC",
        lambda: rendered.get(
            "production_qc"
        )
        or {}
    )

    if not bool(
        qc.get(
            "qc_pass"
        )
    ):
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "operator_branding",
                "error": "production_candidate_qc_failed",
                "qc": qc,
            },
        )

    branding_business_qc = (
        _operator_branding_business_qc(
            rendered,
            source_context,
            router,
            plan=plan,
            profile=profile,
        )
    )

    qc[
        "branding_business_qc"
    ] = (
        branding_business_qc
    )

    qc[
        "branding_business_qc_pass"
    ] = bool(
        branding_business_qc.get(
            "ok"
        )
    )

    if not bool(
        branding_business_qc.get(
            "ok"
        )
    ):
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "operator_branding",
                "error": (
                    "branding_effect_qc_failed"
                ),
                "message": (
                    "The output MP4 is technically valid, but required "
                    "competitor-brand treatment was not actually rendered."
                ),
                "branding_business_qc": (
                    branding_business_qc
                ),
            },
        )

    renderer_output_path = (
        _resolve_rendered_mp4(
            rendered
        )
    )

    published = run_stage(
        "publish",
        "发布 processed 成片",
        lambda: _operator_publish_processed_candidate(
            renderer_output_path,
            video_entry={
                **video_entry,
                "product_name": (
                    source_context.get(
                        "product_name"
                    )
                ),
                "language": (
                    source_context.get(
                        "language"
                    )
                ),
            },
            profile=(
                profile
            ),
            rendered=(
                rendered
            ),
            qc=(
                qc
            ),
        ),
    )

    stage(
        "done",
        "剪辑完成",
    )

    finalize_stage_timings()

    public_stage_timings = [
        {
            key: value
            for key, value in item.items()
            if key != "started_monotonic"
        }
        for item in stage_timings
    ]

    return {
        "source_video_relative_path": (
            relative_path
        ),
        "source_stale_relative_path": (
            video_entry.get(
                "stale_relative_path"
            )
        ),
        "source_path_relocation": (
            video_entry.get(
                "path_relocation"
            )
        ),
        "source_product_name": (
            source_context.get(
                "product_name"
            )
        ),
        "source_product_name_source": (
            source_context.get(
                "product_name_source"
            )
        ),
        "source_language": (
            source_context.get(
                "language"
            )
        ),
        "source_language_code": (
            source_context.get(
                "language_code"
            )
        ),
        "source_language_source": (
            source_context.get(
                "language_source"
            )
        ),
        "source_metadata_sidecar": (
            source_context.get(
                "metadata_sidecar"
            )
        ),
        "competitor_brand_targets": (
            targets
        ),
        "brand_asset_validation": (
            brand_asset_validation
        ),
        "router_report_relative_path": (
            router.get(
                "report_relative_path"
            )
        ),
        "semantic_report_relative_path": (
            semantic.get(
                "report_relative_path"
            )
        ),
        "semantic_translation_enabled": (
            semantic_translation_enabled
        ),
        "semantic_cache_hit": (
            semantic_cache_hit
        ),
        "semantic_sample_interval_seconds": (
            _operator_semantic_sample_interval()
        ),
        "semantic_whisper_pass_count": (
            (
                semantic.get(
                    "whisper_runtime"
                )
                or {}
            ).get(
                "pass_count"
            )
        ),
        "semantic_whisper_segment_mode": (
            (
                semantic.get(
                    "whisper_runtime"
                )
                or {}
            ).get(
                "segment_mode"
            )
        ),
        "render_preset": (
            _operator_render_preset()
        ),
        "render_crf": (
            _operator_render_crf()
        ),
        "midpromo_recovery": midpromo_recovery,
        "dynamic_watermark_recovery": {
            "expected_track_count": len(
                dynamic_track_preview
            ),
            "track_sources": (
                dynamic_track_source_counts
            ),
            "track_ids": [
                track.get(
                    "cluster_id"
                )
                for track in dynamic_track_preview
            ],
        },
        "semantic_mid_promo_count": (
            (semantic.get("summary") or {}).get("mid_promo_count")
        ),
        "replacement_plan_relative_path": (
            plan.get(
                "report_relative_path"
            )
        ),
        **published,
        "production_qc": qc,
        "branding_business_qc": (
            branding_business_qc
        ),
        "renderer_version": (
            rendered.get(
                "version"
            )
        ),
        "render_report_relative_path": (
            rendered.get(
                "report_relative_path"
            )
        ),
        "pipeline_timing": {
            "elapsed_seconds": round(
                time.monotonic() - pipeline_started,
                3,
            ),
            "stages": public_stage_timings,
        },
    }

_OPERATOR_LOGIN_STATUS_LOCK = threading.Lock()
_OPERATOR_LOGIN_STATUS_CACHE = {
    "ok": True,
    "available": None,
    "checking": True,
    "browser_session_active": False,
    "logged_in": False,
    "current_url": None,
    "vnc_url": "http://localhost:7900/?autoconnect=1&resize=scale",
    "last_probe_at": None,
    "last_error": None,
}
_OPERATOR_LOGIN_STATUS_UPDATED_MONOTONIC = 0.0
_OPERATOR_LOGIN_PROBE_THREAD = None

_OPERATOR_LOGIN_ACTION_LOCK = threading.Lock()
_OPERATOR_LOGIN_ACTION_THREAD = None
_OPERATOR_LOGIN_ACTION_STATE = {
    "active": False,
    "started_at": None,
    "finished_at": None,
    "result": None,
    "error": None,
}


def _operator_login_cache_update(payload):
    global _OPERATOR_LOGIN_STATUS_UPDATED_MONOTONIC

    value = dict(payload or {})
    value.setdefault(
        "vnc_url",
        "http://localhost:7900/?autoconnect=1&resize=scale",
    )
    value["last_probe_at"] = (
        _app_now().isoformat()
    )

    with _OPERATOR_LOGIN_STATUS_LOCK:
        _OPERATOR_LOGIN_STATUS_CACHE.clear()
        _OPERATOR_LOGIN_STATUS_CACHE.update(value)
        _OPERATOR_LOGIN_STATUS_UPDATED_MONOTONIC = time.monotonic()


def _operator_login_cache_snapshot():
    with _OPERATOR_LOGIN_STATUS_LOCK:
        return dict(_OPERATOR_LOGIN_STATUS_CACHE)


def _operator_insight_core():
    """Load the already-running crawler module without an HTTP self-request."""
    try:
        from . import main as core
    except ImportError:  # pragma: no cover - direct module debugging
        import main as core
    return core


def _operator_login_status_probe_sync():
    try:
        # Calling 127.0.0.1:8000 from the same ASGI process used to make the
        # status poll contend with a browser-start request. Read the one
        # dedicated Selenium session directly instead; no credential material
        # leaves the process.
        result = _operator_insight_core()._insight_status_sync()

        value = {
            "ok": True,
            "available": True,
            "checking": False,
            "browser_session_active": bool(
                result.get("browser_session_active")
            ),
            "logged_in": bool(
                result.get("logged_in")
            ),
            "current_url": result.get("current_url"),
            "vnc_url": (
                result.get("vnc_url")
                or "http://localhost:7900/?autoconnect=1&resize=scale"
            ),
            "last_error": None,
        }

    except Exception as exc:
        value = {
            "ok": False,
            "available": False,
            "checking": False,
            "browser_session_active": False,
            "logged_in": False,
            "current_url": None,
            "vnc_url": "http://localhost:7900/?autoconnect=1&resize=scale",
            "last_error": _operator_error_payload(exc),
        }

    _operator_login_cache_update(value)
    return value


def _operator_login_probe_worker():
    global _OPERATOR_LOGIN_PROBE_THREAD

    try:
        _operator_login_status_probe_sync()
    finally:
        with _OPERATOR_LOGIN_STATUS_LOCK:
            _OPERATOR_LOGIN_PROBE_THREAD = None


def _operator_login_status_cached(*, max_age_seconds=12.0):
    global _OPERATOR_LOGIN_PROBE_THREAD

    now = time.monotonic()

    with _OPERATOR_LOGIN_STATUS_LOCK:
        snapshot = dict(_OPERATOR_LOGIN_STATUS_CACHE)

        age = (
            now - _OPERATOR_LOGIN_STATUS_UPDATED_MONOTONIC
            if _OPERATOR_LOGIN_STATUS_UPDATED_MONOTONIC
            else None
        )

        if age is not None and age <= float(max_age_seconds):
            snapshot["cache_age_seconds"] = round(age, 2)
            return snapshot

        thread = _OPERATOR_LOGIN_PROBE_THREAD

        if thread is None or not thread.is_alive():
            thread = threading.Thread(
                target=_operator_login_probe_worker,
                daemon=True,
                name="operator-insight-status-probe",
            )
            _OPERATOR_LOGIN_PROBE_THREAD = thread
            thread.start()

        snapshot["checking"] = True
        snapshot["cache_age_seconds"] = (
            round(age, 2)
            if age is not None
            else None
        )
        return snapshot


def _operator_login_status_sync():
    return _operator_login_status_probe_sync()


def _operator_login_recover_sync():
    """
    Recover the dedicated Insight Selenium browser when the API process has
    lost its local WebDriver reference but the single Grid slot is still held
    by an older/orphaned session.

    The crawler foundation already owns /auth/insight/recover. Reuse it here
    rather than creating a second recovery implementation.
    """
    core = _operator_insight_core()
    retired_sessions = 0

    # This Grid is dedicated to Insight. Retiring stale sessions is safe and
    # preserves the persistent Chrome profile, including any valid login.
    try:
        core._close_insight_driver_sync()
        grid = core._cl_grid_graphql_sessions()
        for session_id in grid.get("session_ids") or []:
            if core._cl_grid_delete_session(session_id):
                retired_sessions += 1
    except Exception:
        pass

    try:
        core._get_or_create_insight_driver()
    except Exception as exc:
        raise RuntimeError("Insight browser could not be recovered") from exc

    status = _operator_login_status_sync()

    return {
        "ok": bool(
            status.get(
                "browser_session_active"
            )
        ),
        "recovered": True,
        "status": status,
        "recovery": {"retired_stale_sessions": retired_sessions},
        "vnc_url": (
            status.get(
                "vnc_url"
            )
            or (
                "http://localhost:7900/"
                "?autoconnect=1&resize=scale"
            )
        ),
    }


def _operator_login_open_background():
    global _OPERATOR_LOGIN_ACTION_THREAD

    with _OPERATOR_LOGIN_ACTION_LOCK:
        _OPERATOR_LOGIN_ACTION_STATE["active"] = True
        _OPERATOR_LOGIN_ACTION_STATE["started_at"] = (
            _app_now().isoformat()
        )
        _OPERATOR_LOGIN_ACTION_STATE["finished_at"] = None
        _OPERATOR_LOGIN_ACTION_STATE["result"] = None
        _OPERATOR_LOGIN_ACTION_STATE["error"] = None

    result = None
    action_error = None

    try:
        current = _operator_login_status_sync()

        if bool(current.get("browser_session_active")):
            result = {
                "ok": True,
                "action": "already_attached",
                "status": current,
            }
            return

        recovery_error = None

        try:
            recovered = _operator_login_recover_sync()
            recovered_status = recovered.get("status") or {}

            if bool(recovered_status.get("browser_session_active")):
                result = {
                    "ok": True,
                    "action": "recovered",
                    "status": recovered_status,
                    "recovery": recovered.get("recovery"),
                }
                return

        except Exception as exc:
            recovery_error = _operator_error_payload(exc)

        # Recovery has already attempted a fresh session. If it could not do
        # so, continue to the normal open path below; do not make a second
        # same-process HTTP request back into /auth/insight/open.

        try:
            core = _operator_insight_core()
            driver = core._get_or_create_insight_driver()

            status = _operator_login_status_sync()

            result = {
                "ok": bool(status.get("browser_session_active")),
                "action": "opened",
                "status": status,
                "open_result": {
                    "browser_session_active": bool(driver),
                },
                "recovery_error": recovery_error,
            }

        except Exception as exc:
            action_error = {
                "error": _operator_error_payload(exc),
                "recovery_error": recovery_error,
                "restart_insight_browser_recommended": True,
                "message": (
                    "Insight Selenium session could not be attached/recovered "
                    "within the bounded timeout. Restart only insight-browser "
                    "and log in again."
                ),
            }

            _operator_login_cache_update(
                {
                    "ok": False,
                    "available": False,
                    "checking": False,
                    "browser_session_active": False,
                    "logged_in": False,
                    "current_url": None,
                    "vnc_url": (
                        "http://localhost:7900/"
                        "?autoconnect=1&resize=scale"
                    ),
                    "last_error": action_error,
                }
            )

    finally:
        with _OPERATOR_LOGIN_ACTION_LOCK:
            _OPERATOR_LOGIN_ACTION_STATE["active"] = False
            _OPERATOR_LOGIN_ACTION_STATE["finished_at"] = (
                _app_now().isoformat()
            )
            _OPERATOR_LOGIN_ACTION_STATE["result"] = result
            _OPERATOR_LOGIN_ACTION_STATE["error"] = action_error
            _OPERATOR_LOGIN_ACTION_THREAD = None


def _operator_login_action_snapshot():
    with _OPERATOR_LOGIN_ACTION_LOCK:
        return dict(_OPERATOR_LOGIN_ACTION_STATE)


def _operator_login_open_sync():
    global _OPERATOR_LOGIN_ACTION_THREAD

    cached = _operator_login_status_cached(
        max_age_seconds=5.0
    )

    if bool(cached.get("browser_session_active")):
        return {
            "ok": True,
            "starting": False,
            "recovered": False,
            "vnc_url": cached.get("vnc_url"),
            "status": cached,
            "message": "Insight browser session is already available.",
        }

    with _OPERATOR_LOGIN_ACTION_LOCK:
        thread = _OPERATOR_LOGIN_ACTION_THREAD

        if thread is not None and thread.is_alive():
            return {
                "ok": True,
                "starting": True,
                "already_running": True,
                "vnc_url": "http://localhost:7900/?autoconnect=1&resize=scale",
                "status": cached,
                "action": dict(_OPERATOR_LOGIN_ACTION_STATE),
                "message": (
                    "Insight browser recovery/start is already running "
                    "in background."
                ),
            }

        thread = threading.Thread(
            target=_operator_login_open_background,
            daemon=True,
            name="operator-insight-login-open",
        )

        _OPERATOR_LOGIN_ACTION_THREAD = thread
        _OPERATOR_LOGIN_ACTION_STATE["active"] = True
        _OPERATOR_LOGIN_ACTION_STATE["started_at"] = (
            _app_now().isoformat()
        )
        _OPERATOR_LOGIN_ACTION_STATE["finished_at"] = None
        _OPERATOR_LOGIN_ACTION_STATE["result"] = None
        _OPERATOR_LOGIN_ACTION_STATE["error"] = None
        thread.start()

    return {
        "ok": True,
        "starting": True,
        "already_running": False,
        "vnc_url": "http://localhost:7900/?autoconnect=1&resize=scale",
        "status": cached,
        "message": (
            "Insight browser recovery/start was queued in background. "
            "Console task controls remain responsive."
        ),
    }


def _operator_system_state_sync():
    login = _operator_login_status_cached(
        max_age_seconds=12.0
    )

    login_action = _operator_login_action_snapshot()

    mintegral_config = (
        _mintegral_config()
    )

    mintegral_ready = bool(
        mintegral_config.get(
            "_access_key"
        )
        and mintegral_config.get(
            "_api_key"
        )
    )

    return {
        "ok": True,
        "version": "0.18.10.9.2",
        "login": login,
        "login_action": login_action,
        "brand_assets": (
            _operator_brand_asset_state()
        ),
        "mintegral": {
            "ready": (
                mintegral_ready
            ),
        },
        "workflow": {
            "user_steps": [
                "login_if_needed",
                "submit_url_or_keyword",
                "review_processed_video",
            ],
            "automatic_steps": [
                "crawl",
                "download",
                "dedupe_archive",
                "branding_detection",
                "semantic_structure",
                "replacement_plan",
                "production_candidate_render",
            ],
            "approval_action": (
                "upload_to_mintegral_materials"
            ),
            "storage_contract": {
                "source": (
                    "raw/<run-minute>/<competitor-product>/<language>/<original-file>"
                ),
                "processed": (
                    "processed/<our-product>/<language>/<LANG>_<PRODUCT_SHORT>_video_<YYYYMMDD>[_NNN].mp4"
                ),
            },
        },
    }


def _operator_task_worker(
    task_id,
):
    path = (
        _operator_job_path(
            task_id
        )
    )
    processing_pool = None

    with _OPERATOR_PROCESS_LOCK:
        try:
            _, task = (
                _operator_read_job(
                    task_id
                )
            )

            if _operator_cancel_requested(task_id):
                _operator_finalize_cancelled(
                    path,
                    task,
                    note="cancelled_before_worker_start",
                )
                return

            task[
                "status"
            ] = "CRAWLING"

            task[
                "started_at"
            ] = (
                _app_now()
                .isoformat()
            )

            task[
                "stage_label"
            ] = "正在采集素材"

            task.setdefault(
                "progress",
                {}
            )

            _operator_refresh_progress(
                task
            )

            _operator_write_job(
                path,
                task,
            )

            if _operator_cancel_requested(
                task_id
            ):
                _operator_finalize_cancelled(
                    path,
                    task,
                    note="cancelled_before_crawl",
                )
                return

            request = (
                task.get(
                    "request"
                )
                or {}
            )

            mode = (
                request[
                    "mode"
                ]
            )

            # Keyword search requires a valid authenticated browser.
            #
            # After an API-only rebuild, noVNC can still show an old Chrome
            # while the new API process has no WebDriver reference. Recover
            # that dedicated Selenium session automatically before deciding
            # login is required.
            if mode == "search":
                login = (
                    _operator_login_status_sync()
                )

                recovery = None

                if (
                    not bool(
                        login.get(
                            "logged_in"
                        )
                    )
                    and not bool(
                        login.get(
                            "browser_session_active"
                        )
                    )
                ):
                    try:
                        recovery = (
                            _operator_login_recover_sync()
                        )
                    except Exception as exc:
                        recovery = {
                            "ok": False,
                            "error": (
                                _operator_error_payload(
                                    exc
                                )
                            ),
                        }

                    login = (
                        _operator_login_status_sync()
                    )

                if not bool(
                    login.get(
                        "logged_in"
                    )
                ):
                    browser_active = bool(
                        login.get(
                            "browser_session_active"
                        )
                    )

                    raise HTTPException(
                        status_code=422,
                        detail={
                            "stage": "operator_crawl",
                            "error": (
                                "insight_login_required"
                                if browser_active
                                else "insight_browser_unavailable"
                            ),
                            "message": (
                                "Insight browser is ready but login is required. "
                                "Complete login in the visible noVNC Chrome and retry."
                                if browser_active
                                else
                                "Insight browser session could not be recovered. "
                                "Use the Login button, then retry."
                            ),
                            "browser_session_active": (
                                browser_active
                            ),
                            "logged_in": False,
                            "recovery": (
                                recovery
                            ),
                        },
                    )

            # Bounded producer/consumer pipeline: each formally archived video
            # is submitted immediately while the crawler continues acquiring.
            processing_state_lock = threading.RLock()
            processing_workers = max(1, min(4, int(os.getenv("OPERATOR_PROCESS_WORKERS", "2") or 2)))
            async_processing_enabled = str(os.getenv("OPERATOR_ASYNC_PROCESSING", "1")).strip().lower() not in {"0", "false", "no", "off"}
            processing_pool = ThreadPoolExecutor(
                max_workers=processing_workers,
                thread_name_prefix=f"operator-process-{task_id[-8:]}",
            )
            processing_futures = []
            processing_items_by_path = {}
            task["items"] = []
            task["pipeline_mode"] = "download_and_process_concurrently"
            task["processing_workers"] = processing_workers

            def _task_item_from_entry(entry, index):
                return {
                    "item_id": "item-" + str(index + 1),
                    "source_video_relative_path": entry.get("relative_path"),
                    "status": "PROCESSING",
                    "processing_stage": "queued",
                    "processing_stage_label": "已采集，等待检测线程",
                    "product_name": entry.get("product_name"),
                    "product_name_source": entry.get("product_name_source"),
                    "language": entry.get("language"),
                    "language_code": entry.get("language_code"),
                    "language_source": entry.get("language_source"),
                    "source_metadata_sidecar": entry.get("metadata_sidecar"),
                    "source_sha256": entry.get("sha256"),
                    "search_rank": entry.get("search_rank"),
                    "imp_estimate": entry.get("imp_estimate"),
                    "processed_video_relative_path": None,
                    "creative_md5": None,
                    "creative_name": None,
                    "upload_status": None,
                    "error": None,
                }

            def _process_one_acquired_video(entry, item):
                _OPERATOR_THREAD_CONTEXT.task_id = str(task_id)
                def processing_stage_callback(stage_code, stage_label):
                    with processing_state_lock:
                        now = _app_now().isoformat()
                        if item.get("processing_stage") != stage_code:
                            item["processing_stage_started_at"] = now
                        item["processing_stage"] = stage_code
                        item["processing_stage_label"] = stage_label
                        item["last_processing_update_at"] = now
                        task["current_item_id"] = item.get("item_id")
                        task["stage_label"] = f"并行剪辑 {item.get('item_id')} · {stage_label}"
                        _operator_refresh_progress(task)
                        _operator_write_job(path, task)
                try:
                    processed = _operator_process_video(entry, progress_callback=processing_stage_callback)
                    with processing_state_lock:
                        item.update(processed)
                        item["status"] = "AWAITING_REVIEW"
                        item["processing_stage"] = "done"
                        item["processing_stage_label"] = "剪辑完成"
                        item["finished_at"] = _app_now().isoformat()
                        _operator_refresh_progress(task)
                        _operator_write_job(path, task)
                except _OperatorTaskDiscarded as exc:
                    with processing_state_lock:
                        item.update({"status": "DISCARDED", "processing_stage": "discarded", "processing_stage_label": "检测到斜向平铺水印，已跳过剪辑", "discard_reason": exc.reason, "discard_detail": exc.detail, "error": exc.detail or {"error": exc.reason}, "finished_at": _app_now().isoformat()})
                        _operator_refresh_progress(task)
                        _operator_write_job(path, task)
                except Exception as exc:
                    with processing_state_lock:
                        item.update({"status": "FAILED", "processing_stage": "failed", "processing_stage_label": "剪辑失败", "error": _operator_error_payload(exc), "finished_at": _app_now().isoformat()})
                        _operator_refresh_progress(task)
                        _operator_write_job(path, task)
                finally:
                    try:
                        delattr(_OPERATOR_THREAD_CONTEXT, "task_id")
                    except Exception:
                        pass

            def process_acquired_video(entry):
                if _operator_cancel_requested(task_id):
                    return
                relative = str(entry.get("relative_path") or "").replace("\\", "/")
                if not relative:
                    return
                with processing_state_lock:
                    key = relative.casefold()
                    if key in processing_items_by_path:
                        return
                    item = _task_item_from_entry(entry, len(task.get("items") or []))
                    task.setdefault("items", []).append(item)
                    processing_items_by_path[key] = item
                    task["status"] = "PROCESSING"
                    task["current_item_id"] = item.get("item_id")
                    task["stage_label"] = f"已采集 {item.get('item_id')}，并行开始检测/剪辑"
                    _operator_refresh_progress(task)
                    _operator_write_job(path, task)
                processing_futures.append(processing_pool.submit(_process_one_acquired_video, entry, item))

            def _crawl_progress_unlocked(
                downloaded,
                total,
                phase,
            ):
                task.setdefault(
                    "progress",
                    {}
                )

                task[
                    "progress"
                ][
                    "downloaded_count"
                ] = int(
                    downloaded
                )

                task[
                    "progress"
                ][
                    "download_total"
                ] = int(
                    total
                    or (
                        request.get(
                            "download_count"
                        )
                        or 1
                    )
                )

                task[
                    "stage_label"
                ] = (
                    f"正在下载素材 {downloaded}/{total}"
                    if int(
                        total
                        or 0
                    )
                    > 0
                    else "正在采集素材"
                )

                _operator_refresh_progress(
                    task
                )

                _operator_write_job(
                    path,
                    task,
                )

            def crawl_progress(downloaded, total, phase):
                with processing_state_lock:
                    _crawl_progress_unlocked(downloaded, total, phase)

            crawl = (
                _operator_run_crawl(
                    mode,
                    detail_url=(
                        request.get(
                            "detail_url"
                        )
                    ),
                    detail_urls=(
                        request.get(
                            "detail_urls"
                        )
                    ),
                    keyword=(
                        request.get(
                            "keyword"
                        )
                    ),
                    search_date_start=(
                        request.get(
                            "search_date_start"
                        )
                    ),
                    search_date_end=(
                        request.get(
                            "search_date_end"
                        )
                    ),
                    download_count=int(
                        request.get(
                            "download_count"
                        )
                        or 10
                    ),
                    progress_callback=(
                        crawl_progress
                    ),
                    video_callback=process_acquired_video,
                    cancel_callback=lambda: (
                        _operator_cancel_requested(
                            task_id
                        )
                    ),
                )
            )

            # Wait only after acquisition is exhausted. Individual items have
            # already been processing throughout the crawl; this drains the
            # bounded pool before the task is marked review-ready.
            processing_pool.shutdown(wait=True)

            if _operator_cancel_requested(
                task_id
            ):
                _operator_finalize_cancelled(
                    path,
                    task,
                    note="cancelled_after_crawl",
                )
                return

            crawl_report_path = (
                path.with_name(
                    path.stem
                    + ".crawl.json"
                )
            )

            crawl_report_path.write_text(
                json.dumps(
                    {
                        "primary_path": (
                            crawl.get(
                                "primary_path"
                            )
                        ),
                        "primary_result": (
                            crawl.get(
                                "primary_result"
                            )
                        ),
                        "detail_results": (
                            crawl.get(
                                "detail_results"
                            )
                        ),
                        "download_result": (
                            crawl.get(
                                "download_result"
                            )
                        ),
                        "metadata_issues": (
                            crawl.get(
                                "metadata_issues"
                            )
                            or []
                        ),
                        "product_learning": (
                            crawl.get(
                                "product_learning"
                            )
                            or []
                        ),
                        "review_recovery": (
                            crawl.get(
                                "review_recovery"
                            )
                            or []
                        ),
                        "ranking": (
                            crawl.get(
                                "ranking"
                            )
                        ),
                        "search_candidate_count": (
                            crawl.get(
                                "search_candidate_count"
                            )
                        ),
                    },
                    ensure_ascii=False,
                    indent=2,
                ),
                encoding="utf-8",
            )

            videos = list(
                crawl.get(
                    "videos"
                )
                or []
            )

            if not videos:
                raise HTTPException(
                    status_code=422,
                    detail={
                        "stage": "operator_crawl",
                        "error": "no_downloaded_mp4_resolved",
                        "primary_path": (
                            crawl.get(
                                "primary_path"
                            )
                        ),
                    },
                )

            # URL batches are already bounded by the number of supplied
            # detail pages inside _operator_run_crawl. Do not slice them again
            # here: one detail page may legitimately expose more than one
            # downloadable video, and a discarded first item must never hide a
            # later acquired item. Search mode keeps its Top-N limit.
            if not (
                str(request.get("mode") or "").strip().lower() == "url"
                and request.get("detail_urls")
            ):
                videos = videos[
                    : int(
                        request.get(
                            "download_count"
                        )
                        or len(
                            videos
                        )
                    )
                ]

            task[
                "crawl"
            ] = {
                "endpoint": (
                    crawl.get(
                        "primary_path"
                    )
                ),
                "downloaded_video_count": len(
                    videos
                ),
                "acquired_video_count": len(
                    videos
                ),
                "source_shortfall_count": max(
                    0,
                    int(
                        request.get(
                            "download_count"
                        )
                        or 0
                    )
                    - len(
                        videos
                    ),
                ),
                "report_relative_path": (
                    crawl_report_path
                    .relative_to(
                        WORKSPACE
                    )
                    .as_posix()
                ),
                "metadata_issue_count": len(
                    crawl.get(
                        "metadata_issues"
                    )
                    or []
                ),
                "metadata_issue_preview": (
                    (
                        crawl.get(
                            "metadata_issues"
                        )
                        or []
                    )[
                        :5
                    ]
                ),
                "product_auto_learned_count": len(
                    [
                        item
                        for item in (
                            crawl.get(
                                "product_learning"
                            )
                            or []
                        )
                        if (
                            item.get(
                                "status"
                            )
                            == "auto_learned"
                        )
                    ]
                ),
                "product_learning": (
                    crawl.get(
                        "product_learning"
                    )
                    or []
                ),
                "review_recovered_count": len(
                    [
                        item
                        for item in (
                            crawl.get(
                                "review_recovery"
                            )
                            or []
                        )
                        if item.get(
                            "recovered"
                        )
                    ]
                ),
                "review_recovery": (
                    crawl.get(
                        "review_recovery"
                    )
                    or []
                ),
                "ranking_sort": (
                    (
                        crawl.get(
                            "ranking"
                        )
                        or {}
                    ).get(
                        "sort"
                    )
                ),
                "ranking_verified": bool(
                    (
                        crawl.get(
                            "ranking"
                        )
                        or {}
                    ).get(
                        "is_non_increasing"
                    )
                ),
                "crawler_ranking_verified": bool(
                    (
                        crawl.get(
                            "ranking"
                        )
                        or {}
                    ).get(
                        "crawler_verified"
                    )
                ),
                "crawler_sort_field": (
                    (
                        crawl.get(
                            "ranking"
                        )
                        or {}
                    ).get(
                        "crawler_sort_field"
                    )
                ),
                "crawler_sort_rule": (
                    (
                        crawl.get(
                            "ranking"
                        )
                        or {}
                    ).get(
                        "crawler_sort_rule"
                    )
                ),
                "search_candidate_count": (
                    crawl.get(
                        "search_candidate_count"
                    )
                ),
                "ranking": (
                    crawl.get(
                        "ranking"
                    )
                ),
            }

            task[
                "status"
            ] = "PROCESSING"

            task[
                "stage_label"
            ] = (
                "正在自动剪辑"
            )

            task.setdefault(
                "progress",
                {}
            )

            task[
                "progress"
            ][
                "downloaded_count"
            ] = len(
                videos
            )

            if not task.get("items"):
                task[
                    "items"
                ] = [
                {
                    "item_id": (
                        "item-"
                        + str(
                            index + 1
                        )
                    ),
                    "source_video_relative_path": (
                        entry[
                            "relative_path"
                        ]
                    ),
                    "status": "PENDING",
                    "product_name": (
                        entry.get(
                            "product_name"
                        )
                    ),
                    "product_name_source": (
                        entry.get(
                            "product_name_source"
                        )
                    ),
                    "language": (
                        entry.get(
                            "language"
                        )
                    ),
                    "language_code": (
                        entry.get(
                            "language_code"
                        )
                    ),
                    "language_source": (
                        entry.get(
                            "language_source"
                        )
                    ),
                    "source_metadata_sidecar": (
                        entry.get(
                            "metadata_sidecar"
                        )
                    ),
                    "source_sha256": (
                        entry.get(
                            "sha256"
                        )
                    ),
                    "search_rank": (
                        entry.get(
                            "search_rank"
                        )
                    ),
                    "imp_estimate": (
                        entry.get(
                            "imp_estimate"
                        )
                    ),
                    "processed_video_relative_path": None,
                    "creative_md5": None,
                    "creative_name": None,
                    "upload_status": None,
                    "error": None,
                }
                for index, entry in enumerate(
                    videos
                )
                ]

            _operator_refresh_progress(
                task
            )

            _operator_write_job(
                path,
                task,
            )

            acquired_video_count = len(videos)
            succeeded = sum(
                1 for item in task.get("items") or []
                if item.get("status") == "AWAITING_REVIEW"
            )
            failed = sum(
                1 for item in task.get("items") or []
                if item.get("status") == "FAILED"
            )

            # In concurrent mode all entries were submitted by
            # ``video_callback`` during acquisition. Keep this legacy loop
            # only as a compatibility fallback for callers that disable the
            # pipeline explicitly.
            serial_videos = [] if async_processing_enabled else videos
            for index, entry in enumerate(serial_videos):
                if _operator_cancel_requested(
                    task_id
                ):
                    _operator_finalize_cancelled(
                        path,
                        task,
                        note=(
                            "cancelled_before_processing_next_video"
                        ),
                    )
                    return
                item = (
                    task[
                        "items"
                    ][
                        index
                    ]
                )

                item[
                    "status"
                ] = "PROCESSING"

                item[
                    "started_at"
                ] = (
                    _app_now()
                    .isoformat()
                )

                task[
                    "current_item_id"
                ] = (
                    item[
                        "item_id"
                    ]
                )

                task[
                    "stage_label"
                ] = (
                    f"正在剪辑 {index + 1}/{len(videos)}"
                )

                _operator_write_job(
                    path,
                    task,
                )

                def processing_stage_callback(
                    stage_code,
                    stage_label,
                ):
                    now = (
                        _app_now().isoformat()
                    )

                    if (
                        item.get(
                            "processing_stage"
                        )
                        != stage_code
                    ):
                        item[
                            "processing_stage_started_at"
                        ] = now

                    item[
                        "processing_stage"
                    ] = (
                        stage_code
                    )

                    item[
                        "processing_stage_label"
                    ] = (
                        stage_label
                    )

                    item[
                        "last_processing_update_at"
                    ] = now

                    task[
                        "stage_label"
                    ] = (
                        f"正在剪辑 {index + 1}/{len(videos)} · "
                        + str(
                            stage_label
                        )
                    )

                    _operator_write_job(
                        path,
                        task,
                    )

                try:
                    processed = (
                        _operator_process_video(
                            entry,
                            progress_callback=(
                                processing_stage_callback
                            ),
                        )
                    )

                    item.update(
                        processed
                    )

                    item[
                        "status"
                    ] = (
                        "AWAITING_REVIEW"
                    )

                    item[
                        "processing_stage"
                    ] = "done"

                    item[
                        "processing_stage_label"
                    ] = "剪辑完成"

                    item[
                        "finished_at"
                    ] = (
                        _app_now().isoformat()
                    )

                    succeeded += 1

                except _OperatorTaskDiscarded as exc:
                    item["status"] = "DISCARDED"
                    item["processing_stage"] = "discarded"
                    item["processing_stage_label"] = "检测到斜向平铺水印，已跳过剪辑"
                    item["discard_reason"] = exc.reason
                    item["discard_detail"] = exc.detail
                    item["error"] = exc.detail or {"error": exc.reason}
                    item["finished_at"] = _app_now().isoformat()

                except Exception as exc:
                    item[
                        "status"
                    ] = "FAILED"

                    item[
                        "processing_stage"
                    ] = "failed"

                    item[
                        "processing_stage_label"
                    ] = "剪辑失败"

                    item[
                        "error"
                    ] = (
                        _operator_error_payload(
                            exc
                        )
                    )

                    item[
                        "finished_at"
                    ] = (
                        _app_now().isoformat()
                    )

                    failed += 1

                _operator_refresh_progress(
                    task
                )

                _operator_write_job(
                    path,
                    task,
                )

                if _operator_cancel_requested(
                    task_id
                ):
                    _operator_finalize_cancelled(
                        path,
                        task,
                        note=(
                            "cancelled_after_current_video_finished"
                        ),
                    )
                    return

            task[
                "current_item_id"
            ] = None

            # Recompute from the final item states.  Worker completion order is
            # nondeterministic, so incrementing local counters can drift from
            # the persisted item list when a callback races with crawl updates.
            final_items = list(task.get("items") or [])
            succeeded = sum(1 for item in final_items if item.get("status") == "AWAITING_REVIEW")
            failed = sum(1 for item in final_items if item.get("status") == "FAILED")
            discarded = sum(1 for item in final_items if item.get("status") == "DISCARDED")
            task["summary"] = {
                "video_count": len(
                    final_items
                ),
                "review_ready_count": (
                    succeeded
                ),
                "failed_count": (
                    failed
                ),
                "discarded_count": discarded,
                "uploaded_count": 0,
                "rejected_count": 0,
            }

            if succeeded:
                task[
                    "status"
                ] = (
                    "AWAITING_REVIEW"
                )

                task[
                    "stage_label"
                ] = (
                    "剪辑完成，等待审核"
                )
            elif any(
                item.get("status") == "DISCARDED"
                for item in task.get("items") or []
            ):
                task["status"] = "COMPLETED_WITH_ERRORS"
                task["stage_label"] = "部分素材因斜向平铺水印已跳过，剩余素材处理完成"
                task["finished_at"] = _app_now().isoformat()
            else:
                task[
                    "status"
                ] = "FAILED"

                task[
                    "stage_label"
                ] = (
                    "处理失败"
                )

                task[
                    "finished_at"
                ] = (
                    _app_now()
                    .isoformat()
                )

            _operator_refresh_progress(
                task
            )

            _operator_write_job(
                path,
                task,
            )

        except _OperatorTaskCancelled as exc:
            if processing_pool is not None:
                processing_pool.shutdown(wait=False, cancel_futures=True)
            try:
                _, task = (
                    _operator_read_job(
                        task_id
                    )
                )
            except Exception:
                task = {
                    "task_id": task_id,
                    "items": [],
                }

            _operator_finalize_cancelled(
                path,
                task,
                note=str(
                    exc
                ),
            )

        except Exception as exc:
            if processing_pool is not None:
                processing_pool.shutdown(wait=False, cancel_futures=True)
            try:
                _, task = (
                    _operator_read_job(
                        task_id
                    )
                )
            except Exception:
                task = {
                    "task_id": (
                        task_id
                    ),
                    "items": [],
                }

            task[
                "status"
            ] = "FAILED"

            task[
                "stage_label"
            ] = (
                "任务失败"
            )

            task[
                "error"
            ] = (
                _operator_error_payload(
                    exc
                )
            )

            task[
                "finished_at"
            ] = (
                _app_now()
                .isoformat()
            )

            _operator_write_job(
                path,
                task,
            )


def _operator_task_worker_entry(
    task_id,
):
    _OPERATOR_THREAD_CONTEXT.task_id = str(task_id)
    try:
        _operator_task_worker(task_id)
    finally:
        try:
            delattr(_OPERATOR_THREAD_CONTEXT, "task_id")
        except Exception:
            pass
        _operator_worker_unregister(task_id)


def _operator_submit_sync(
    req: OperatorTaskSubmitRequest
):
    _operator_reconcile_all_stale_tasks()

    mode = str(
        req.mode
        or ""
    ).strip().lower()

    if mode not in (
        "url",
        "search",
    ):
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "operator_submit",
                "error": "mode_must_be_url_or_search",
            },
        )

    raw_detail_urls = (
        (
            req.detail_urls
            if req.detail_urls is not None
            else req.detail_url
        )
        if mode == "url"
        else None
    )
    detail_urls, invalid_detail_urls = _operator_parse_detail_urls(
        raw_detail_urls
    )
    if len(detail_urls) > 50:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "operator_submit",
                "error": "detail_url_count_exceeded",
                "allowed": 50,
            },
        )
    if invalid_detail_urls:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "operator_submit",
                "error": "invalid_detail_url",
                "invalid_urls": invalid_detail_urls[:20],
                "message": "每条详情页链接必须是完整的 http(s) URL。",
            },
        )
    detail_url = detail_urls[0] if detail_urls else ""

    keyword = str(
        req.keyword
        or ""
    ).strip()

    if (
        mode == "url"
        and not detail_urls
    ):
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "operator_submit",
                "error": "detail_url_required",
            },
        )

    if (
        mode == "search"
        and not keyword
    ):
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "operator_submit",
                "error": "keyword_required",
            },
        )

    search_date_start = str(
        req.search_date_start
        or ""
    ).strip()

    search_date_end = str(
        req.search_date_end
        or ""
    ).strip()

    if mode == "search":
        if not search_date_start or not search_date_end:
            raise HTTPException(
                status_code=422,
                detail={
                    "stage": "operator_submit",
                    "error": "search_date_range_required",
                    "message": (
                        "Keyword search requires both start and end dates."
                    ),
                },
            )

        try:
            start_date_obj = datetime.strptime(
                search_date_start,
                "%Y-%m-%d",
            ).date()

            end_date_obj = datetime.strptime(
                search_date_end,
                "%Y-%m-%d",
            ).date()

        except Exception:
            raise HTTPException(
                status_code=422,
                detail={
                    "stage": "operator_submit",
                    "error": "invalid_search_date_format",
                    "expected": "YYYY-MM-DD",
                },
            )

        if start_date_obj > end_date_obj:
            raise HTTPException(
                status_code=422,
                detail={
                    "stage": "operator_submit",
                    "error": "search_date_start_after_end",
                },
            )

    count = int(req.download_count)
    if mode == "url":
        count = len(detail_urls)

    if not 1 <= count <= 100:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "operator_submit",
                "error": "download_count_out_of_range",
                "allowed": "1..100",
            },
        )

    now = (
        _app_now()
    )

    task_id = (
        "task-"
        + now.strftime(
            "%Y%m%d-%H%M%S"
        )
        + "-"
        + uuid.uuid4().hex[
            :8
        ]
    )

    path = (
        _operator_job_path(
            task_id
        )
    )

    task = {
        "ok": True,
        "version": "0.18.10.9.2",
        "task_id": task_id,
        "worker_boot_id": _OPERATOR_BOOT_ID,
        "status": "QUEUED",
        "stage_label": "等待处理",
        "created_at": (
            now.isoformat()
        ),
        "updated_at": (
            now.isoformat()
        ),
        "started_at": None,
        "finished_at": None,
        "request": {
            "mode": mode,
            "detail_url": (
                detail_url
                if mode == "url"
                else None
            ),
            "detail_urls": (
                detail_urls
                if mode == "url"
                else None
            ),
            "keyword": (
                keyword
                if mode == "search"
                else None
            ),
            "search_date_start": (
                search_date_start
                if mode == "search"
                else None
            ),
            "search_date_end": (
                search_date_end
                if mode == "search"
                else None
            ),
            "download_count": (
                count
            ),
        },
        "crawl": None,
        "current_item_id": None,
        "cancel_requested": False,
        "cancel_requested_at": None,
        "cancelled_at": None,
        "items": [],
        "progress": {
            "requested_count": count,
            "downloaded_count": 0,
            "processed_count": 0,
            "processed_attempted_count": 0,
            "awaiting_review_count": 0,
            "uploaded_count": 0,
            "rejected_count": 0,
            "failed_count": 0,
            "cancelled_count": 0,
            "overall_percent": 3,
        },
        "summary": {
            "video_count": 0,
            "review_ready_count": 0,
            "failed_count": 0,
            "uploaded_count": 0,
            "rejected_count": 0,
        },
        "error": None,
    }

    thread = threading.Thread(
        target=(
            _operator_task_worker_entry
        ),
        args=(
            task_id,
        ),
        daemon=True,
        name=(
            "operator-"
            + task_id
        ),
    )

    _operator_worker_register(
        task_id,
        thread,
    )

    task["worker_active"] = True

    _operator_write_job(
        path,
        task,
    )

    try:
        thread.start()
    except Exception:
        _operator_worker_unregister(task_id)
        raise

    return {
        "ok": True,
        "version": "0.18.10.9.2",
        "task_id": task_id,
        "status": "QUEUED",
        "message": (
            "Task accepted. Crawling, processing and rendering now run automatically."
        ),
    }


def _operator_upload_item(
    item,
):
    relative_path = (
        item.get(
            "processed_video_relative_path"
        )
    )

    if not relative_path:
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "operator_review",
                "error": "processed_video_missing",
                "item_id": (
                    item.get(
                        "item_id"
                    )
                ),
            },
        )

    video_path = (
        _safe_workspace_path(
            relative_path
        )
    )

    local_md5 = (
        item.get(
            "processed_local_md5"
        )
        or _local_file_md5(
            video_path
        )
    )

    previous = (
        _find_uploaded_by_local_md5(
            local_md5
        )
    )

    now = (
        _app_now()
    )

    if previous:
        status = (
            "SKIPPED_ALREADY_UPLOADED"
        )

        creative_md5 = (
            previous.get(
                "creative_md5"
            )
        )

        creative_name = (
            previous.get(
                "creative_name"
            )
        )

    else:
        config = (
            _mintegral_config()
        )

        _mintegral_require_credentials(
            config
        )

        upload_filename = (
            _mintegral_safe_upload_filename(
                video_path,
                None,
            )
        )

        uploaded = (
            _mintegral_upload_material_direct(
                config,
                video_path,
                upload_filename,
                180.0,
            )
        )

        status = str(
            uploaded.get(
                "status"
            )
            or "UPLOADED"
        )

        creative_md5 = (
            uploaded.get(
                "creative_md5"
            )
        )

        creative_name = (
            uploaded.get(
                "creative_name"
            )
        )

        ledger_record = {
            "job_id": (
                now.strftime(
                    "%Y%m%d_%H%M%S"
                )
                + "-operator-"
                + str(
                    item.get(
                        "item_id"
                    )
                )
            ),
            "uploaded": True,
            "upload_status": (
                status
            ),
            "source_plan_relative_path": (
                item.get(
                    "replacement_plan_relative_path"
                )
            ),
            "processed_video_relative_path": (
                relative_path
            ),
            "local_md5": (
                local_md5
            ),
            "creative_md5": (
                creative_md5
            ),
            "creative_name": (
                creative_name
            ),
            "uploaded_at": (
                now.isoformat()
            ),
            "created_at": (
                now.isoformat()
            ),
            "operator_console": True,
        }

        _append_upload_ledger(
            ledger_record
        )

    return {
        "status": status,
        "creative_md5": (
            creative_md5
        ),
        "creative_name": (
            creative_name
        ),
    }


def _operator_review_worker(
    task_id,
    decision,
    item_ids,
):
    path = (
        _operator_job_path(
            task_id
        )
    )

    with _OPERATOR_REVIEW_LOCK:
        try:
            _, task = (
                _operator_read_job(
                    task_id
                )
            )

            items = (
                task.get(
                    "items"
                )
                or []
            )

            wanted = {
                str(
                    value
                )
                for value in (
                    item_ids
                    or []
                )
            }

            targets = [
                item
                for item in items
                if (
                    item.get(
                        "status"
                    )
                    == "AWAITING_REVIEW"
                    and (
                        not wanted
                        or str(
                            item.get(
                                "item_id"
                            )
                        )
                        in wanted
                    )
                )
            ]

            if not targets:
                return

            if _operator_cancel_requested(
                task_id
            ):
                _operator_finalize_cancelled(
                    path,
                    task,
                    note="cancelled_before_review_action",
                )
                return

            if decision == "reject":
                for item in targets:
                    item[
                        "status"
                    ] = "REJECTED"

                    item[
                        "reviewed_at"
                    ] = (
                        _app_now().isoformat()
                    )

                task[
                    "stage_label"
                ] = (
                    "审核结果已保存"
                )

            else:
                task[
                    "status"
                ] = "UPLOADING"

                task[
                    "stage_label"
                ] = (
                    "审核通过，正在上传 Mintegral"
                )

                _operator_write_job(
                    path,
                    task,
                )

                for item in targets:
                    if _operator_cancel_requested(
                        task_id
                    ):
                        _operator_finalize_cancelled(
                            path,
                            task,
                            note=(
                                "cancelled_before_next_upload"
                            ),
                        )
                        return

                    item[
                        "status"
                    ] = "UPLOADING"

                    _operator_write_job(
                        path,
                        task,
                    )

                    try:
                        result = (
                            _operator_upload_item(
                                item
                            )
                        )

                        item[
                            "status"
                        ] = "UPLOADED"

                        item[
                            "upload_status"
                        ] = (
                            result[
                                "status"
                            ]
                        )

                        item[
                            "creative_md5"
                        ] = (
                            result[
                                "creative_md5"
                            ]
                        )

                        item[
                            "creative_name"
                        ] = (
                            result[
                                "creative_name"
                            ]
                        )

                        item[
                            "reviewed_at"
                        ] = (
                            _app_now().isoformat()
                        )

                    except Exception as exc:
                        item[
                            "status"
                        ] = (
                            "UPLOAD_FAILED"
                        )

                        item[
                            "error"
                        ] = (
                            _operator_error_payload(
                                exc
                            )
                        )

                    _operator_refresh_progress(
                        task
                    )

                    _operator_write_job(
                        path,
                        task,
                    )

                    if _operator_cancel_requested(
                        task_id
                    ):
                        _operator_finalize_cancelled(
                            path,
                            task,
                            note=(
                                "cancelled_after_current_upload_finished"
                            ),
                        )
                        return

            counts = defaultdict(
                int
            )

            for item in items:
                counts[
                    str(
                        item.get(
                            "status"
                        )
                    )
                ] += 1

            awaiting = (
                counts.get(
                    "AWAITING_REVIEW",
                    0,
                )
            )

            task[
                "summary"
            ] = {
                "video_count": len(
                    items
                ),
                "review_ready_count": (
                    awaiting
                ),
                "failed_count": (
                    counts.get(
                        "FAILED",
                        0,
                    )
                    + counts.get(
                        "UPLOAD_FAILED",
                        0,
                    )
                ),
                "uploaded_count": (
                    counts.get(
                        "UPLOADED",
                        0,
                    )
                ),
                "rejected_count": (
                    counts.get(
                        "REJECTED",
                        0,
                    )
                ),
            }

            if awaiting > 0:
                task[
                    "status"
                ] = (
                    "AWAITING_REVIEW"
                )

                task[
                    "stage_label"
                ] = (
                    "仍有素材等待审核"
                )

            elif (
                counts.get(
                    "UPLOAD_FAILED",
                    0,
                )
                > 0
                or counts.get(
                    "FAILED",
                    0,
                )
                > 0
            ):
                task[
                    "status"
                ] = (
                    "COMPLETED_WITH_ERRORS"
                )

                task[
                    "stage_label"
                ] = (
                    "任务完成，但有失败项"
                )

                task[
                    "finished_at"
                ] = (
                    _app_now()
                    .isoformat()
                )

            else:
                task[
                    "status"
                ] = "COMPLETED"

                task[
                    "stage_label"
                ] = (
                    "任务完成"
                )

                task[
                    "finished_at"
                ] = (
                    _app_now()
                    .isoformat()
                )

            _operator_refresh_progress(
                task
            )

            _operator_write_job(
                path,
                task,
            )

        except Exception:
            try:
                _, task = (
                    _operator_read_job(
                        task_id
                    )
                )

                task[
                    "review_error"
                ] = (
                    traceback.format_exc()[
                        -5000:
                    ]
                )

                _operator_write_job(
                    path,
                    task,
                )

            except Exception:
                pass


def _operator_review_sync(
    req: OperatorReviewRequest
):
    decision = str(
        req.decision
        or ""
    ).strip().lower()

    if decision not in (
        "approve",
        "reject",
    ):
        raise HTTPException(
            status_code=422,
            detail={
                "stage": "operator_review",
                "error": "decision_must_be_approve_or_reject",
            },
        )

    _, task = (
        _operator_read_job(
            req.task_id
        )
    )

    if task.get(
        "status"
    ) not in (
        "AWAITING_REVIEW",
        "UPLOADING",
    ):
        raise HTTPException(
            status_code=409,
            detail={
                "stage": "operator_review",
                "error": "task_not_waiting_for_review",
                "status": (
                    task.get(
                        "status"
                    )
                ),
            },
        )

    thread = threading.Thread(
        target=(
            _operator_review_worker
        ),
        args=(
            req.task_id,
            decision,
            list(
                req.item_ids
                or []
            ),
        ),
        daemon=True,
        name=(
            "operator-review-"
            + req.task_id
        ),
    )

    thread.start()

    return {
        "ok": True,
        "version": "0.18.10.9.2",
        "task_id": (
            req.task_id
        ),
        "decision": (
            decision
        ),
        "message": (
            "Review accepted. The next step now runs automatically."
        ),
    }


def _operator_finalize_interrupted(
    path,
    task,
    *,
    note=None,
):
    now = _app_now().isoformat()

    for item in task.get("items") or []:
        if item.get("status") in (
            "PENDING",
            "PROCESSING",
            "UPLOADING",
        ):
            item["status"] = "INTERRUPTED"
            item["finished_at"] = item.get("finished_at") or now

    task["status"] = "INTERRUPTED"
    task["stage_label"] = "服务重启导致任务中断"
    task["finished_at"] = task.get("finished_at") or now
    task["current_item_id"] = None

    if note:
        task["interrupt_note"] = str(note)

    _operator_refresh_progress(task)
    _operator_write_job(path, task)
    return task


def _operator_reconcile_job_state(
    path,
    task,
):
    status = str(task.get("status") or "")

    active = {
        "QUEUED",
        "CRAWLING",
        "PROCESSING",
        "UPLOADING",
        "CANCEL_REQUESTED",
    }

    if status not in active:
        task["worker_active"] = False
        return task

    task_id = str(task.get("task_id") or path.stem)
    worker_active = _operator_worker_registered(task_id)
    task["worker_active"] = bool(worker_active)

    if worker_active:
        return task

    if (
        status == "CANCEL_REQUESTED"
        or bool(task.get("cancel_requested"))
        or _operator_cancel_requested(task_id)
    ):
        task = _operator_finalize_cancelled(
            path,
            task,
            note="reconciled_stale_cancel_after_api_restart",
        )
    else:
        task = _operator_finalize_interrupted(
            path,
            task,
            note="reconciled_stale_active_task_after_api_restart",
        )

    task["worker_active"] = False
    return task


def _operator_reconcile_all_stale_tasks():
    directory = _operator_jobs_dir()
    if not directory.is_dir():
        return

    for path in directory.glob("task-*.json"):
        if path.name.endswith(".crawl.json"):
            continue

        try:
            task = json.loads(path.read_text(encoding="utf-8"))
            _operator_reconcile_job_state(path, task)
        except Exception:
            continue


def _operator_cancel_sync(
    req: OperatorCancelRequest
):
    path, task = (
        _operator_read_job(
            req.task_id
        )
    )

    task = _operator_reconcile_job_state(
        path,
        task,
    )

    status = str(
        task.get(
            "status"
        )
        or ""
    )

    terminal = {
        "COMPLETED",
        "COMPLETED_WITH_ERRORS",
        "FAILED",
        "CANCELLED",
        "INTERRUPTED",
    }

    if status in terminal:
        return {
            "ok": True,
            "version": "0.18.10.9.2",
            "task_id": (
                req.task_id
            ),
            "status": status,
            "already_terminal": True,
            "message": (
                "Task is already finished."
            ),
        }

    marker = (
        _operator_cancel_marker_path(
            req.task_id
        )
    )

    marker.parent.mkdir(
        parents=True,
        exist_ok=True,
    )

    marker.write_text(
        json.dumps(
            {
                "task_id": (
                    req.task_id
                ),
                "requested_at": (
                    _app_now()
                    .isoformat()
                ),
            },
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )

    task[
        "cancel_requested"
    ] = True

    task[
        "cancel_requested_at"
    ] = (
        _app_now()
        .isoformat()
    )

    if status in (
        "QUEUED",
        "AWAITING_REVIEW",
    ):
        _operator_finalize_cancelled(
            path,
            task,
            note=(
                "cancelled_before_active_operation"
            ),
        )

        return {
            "ok": True,
            "version": "0.18.10.9.2",
            "task_id": (
                req.task_id
            ),
            "status": "CANCELLED",
            "safe_boundary_wait": False,
            "message": (
                "Task cancelled."
            ),
        }

    task[
        "status"
    ] = "CANCEL_REQUESTED"

    task[
        "stage_label"
    ] = (
        "正在取消 · Whisper/OCR/渲染会在最近安全点停止"
    )

    _operator_refresh_progress(
        task
    )

    _operator_write_job(
        path,
        task,
    )

    return {
        "ok": True,
        "version": "0.18.10.9.2",
        "task_id": (
            req.task_id
        ),
        "status": "CANCEL_REQUESTED",
        "safe_boundary_wait": True,
        "message": (
            "Cancellation requested. The current download, render or upload "
            "operation will finish safely; no new item will start."
        ),
    }


def _operator_delete_sync(
    req: OperatorDeleteRequest
):
    path, task = (
        _operator_read_job(
            req.task_id
        )
    )

    task = _operator_reconcile_job_state(
        path,
        task,
    )

    status = str(
        task.get(
            "status"
        )
        or ""
    )

    active = {
        "QUEUED",
        "CRAWLING",
        "PROCESSING",
        "UPLOADING",
        "CANCEL_REQUESTED",
    }

    if status in active:
        raise HTTPException(
            status_code=409,
            detail={
                "stage": (
                    "operator_delete"
                ),
                "error": (
                    "active_task_must_be_cancelled_first"
                ),
                "task_id": (
                    req.task_id
                ),
                "status": (
                    status
                ),
                "message": (
                    "Cancel the active task before deleting its task record."
                ),
            },
        )

    removed = []

    candidates = [
        path,
        path.with_name(
            path.stem
            + ".crawl.json"
        ),
        _operator_cancel_marker_path(
            req.task_id
        ),
    ]

    for candidate in candidates:
        try:
            if candidate.is_file():
                candidate.unlink()
                removed.append(
                    candidate.name
                )
        except FileNotFoundError:
            pass

    return {
        "ok": True,
        "version": "0.18.10.9.2",
        "task_id": (
            req.task_id
        ),
        "deleted": True,
        "deleted_record_files": (
            removed
        ),
        "media_deleted": False,
        "message": (
            "任务记录已删除；raw、processed、review、output 媒体文件未删除。"
        ),
    }


def _operator_tasks_sync(
    limit=30,
):
    directory = (
        _operator_jobs_dir()
    )

    if not directory.is_dir():
        return {
            "ok": True,
            "version": "0.18.10.9.2",
            "items": [],
        }

    files = sorted(
        [
            path
            for path in directory.glob(
                "task-*.json"
            )
            if not path.name.endswith(
                ".crawl.json"
            )
        ],
        key=lambda path: (
            path.stat().st_mtime
            if path.exists()
            else 0.0
        ),
        reverse=True,
    )

    rows = []

    for path in files[
        : min(
            100,
            max(
                1,
                int(
                    limit
                ),
            ),
        )
    ]:
        try:
            payload = json.loads(
                path.read_text(
                    encoding="utf-8"
                )
            )
        except Exception:
            continue

        try:
            payload = _operator_reconcile_job_state(
                path,
                payload,
            )
        except Exception:
            pass

        payload["worker_active"] = bool(
            _operator_worker_registered(
                payload.get("task_id") or path.stem
            )
        )

        rows.append(
            payload
        )

    return {
        "ok": True,
        "version": "0.18.10.9.2",
        "count": len(
            rows
        ),
        "items": rows,
    }


