    @app.get("/console/media", include_in_schema=False)
    async def creative_loop_operator_media(
        path: str,
        request: Request,
    ):
        from fastapi.responses import StreamingResponse

        media_path = (
            _safe_workspace_path(
                path
            )
        )

        try:
            media_relative = (
                media_path.relative_to(
                    WORKSPACE
                ).as_posix()
            )
        except Exception:
            media_relative = ""

        if (
            not media_path.is_file()
            or media_path.suffix.lower()
            != ".mp4"
            or not media_relative.lower().startswith(
                "processed/"
            )
        ):
            raise HTTPException(
                status_code=404,
                detail=(
                    "Processed review video not found. "
                    "The final-review player never falls back to raw source media."
                ),
            )

        file_size = media_path.stat().st_size
        range_header = request.headers.get("range")
        start = 0
        end = file_size - 1
        status_code = 200
        if range_header:
            match = re.match(r"bytes=(\d*)-(\d*)", range_header.strip())
            if not match:
                raise HTTPException(status_code=416, detail="Invalid byte range.")
            raw_start, raw_end = match.groups()
            if raw_start:
                start = int(raw_start)
                end = int(raw_end) if raw_end else end
            elif raw_end:
                suffix = int(raw_end)
                start = max(0, file_size - suffix)
            if start >= file_size or start > end:
                raise HTTPException(
                    status_code=416,
                    detail="Requested byte range is not satisfiable.",
                    headers={"Content-Range": f"bytes */{file_size}"},
                )
            end = min(end, file_size - 1)
            status_code = 206

        content_length = end - start + 1

        def iter_file():
            with media_path.open("rb") as handle:
                handle.seek(start)
                remaining = content_length
                while remaining > 0:
                    chunk = handle.read(min(1024 * 1024, remaining))
                    if not chunk:
                        break
                    remaining -= len(chunk)
                    yield chunk

        headers = {
            "Accept-Ranges": "bytes",
            "Content-Length": str(content_length),
            "Cache-Control": "no-store, no-cache, must-revalidate, max-age=0",
            "Pragma": "no-cache",
            "Expires": "0",
        }
        if status_code == 206:
            headers["Content-Range"] = f"bytes {start}-{end}/{file_size}"
        return StreamingResponse(
            iter_file(),
            status_code=status_code,
            media_type="video/mp4",
            headers=headers,
        )
